  overflow-x: hidden; /* evita scroll horizontal */
}


.full-width,
.banner,
.card,
.container-main {
  width: 100%;      /* pega toda a largura da tela */
  max-width: 100%;   /* garante que não ultrapasse */
  box-sizing: border-box; /* inclui padding/border na largura */
}

/* 3. Ajuste para containers com padding/margin interno */

.full-width, .banner, .card, .container-main {
  margin-left: auto;
  margin-right: auto;
  padding-left: 0;
  padding-right: 0;
}

*{
  box-sizing:border-box;
}











