/* =========================================
   TRANSIÇÃO ENTRE EQUIPES
========================================= */

.team-transition{

    position:fixed;

    inset:0;

    display:flex;

    justify-content:center;
    align-items:center;

    overflow:hidden;

    opacity:0;

    visibility:hidden;

    pointer-events:none;

    z-index:999999;

    transition:
        opacity .35s ease,
        visibility .35s ease;
}


/* =========================================
   TRANSIÇÃO ATIVA
========================================= */

.team-transition.ativo{

    opacity:1;

    visibility:visible;

    pointer-events:auto;
}


/* =========================================
   NOME GIGANTE AO FUNDO
========================================= */

.team-transition::before{

    content:"";

    position:absolute;

    top:50%;

    left:50%;

    z-index:1;

    transform:
        translate(-50%,-50%)
        scale(.9);

    width:100%;

    text-align:center;

    font-family:'Inter',sans-serif;

    font-size:clamp(70px,17vw,280px);

    font-weight:900;

    letter-spacing:-8px;

    text-transform:uppercase;

    white-space:nowrap;

    color:rgba(255,255,255,.08);

    opacity:0;

    pointer-events:none;

}


/* NOME DO FUNDO */

.team-transition.ativo::before{

    content:attr(data-team-name);

    animation:

        fundoEquipe
        .8s
        .15s
        ease
        forwards;

}


@keyframes fundoEquipe{

    0%{

        opacity:0;

        transform:

            translate(-50%,-50%)
            scale(.9);

    }

    100%{

        opacity:1;

        transform:

            translate(-50%,-50%)
            scale(1);

    }

}


/* =========================================
   CONTEÚDO CENTRAL
========================================= */

.team-info{

    position:relative;

    z-index:5;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:center;

    text-align:center;

}


/* =========================================
   LOGO DA EQUIPE
========================================= */

#teamLogo{

    width:clamp(120px,16vw,220px);

    max-width:65vw;

    opacity:0;

    transform:

        scale(.4)
        rotate(-10deg);

    filter:

        drop-shadow(
            0 0 30px
            rgba(255,255,255,.35)
        );

}


/* LOGO APARECE */

.team-transition.ativo #teamLogo{

    animation:

        logoEntrada
        .7s
        ease
        forwards;

}


@keyframes logoEntrada{

    0%{

        opacity:0;

        transform:

            scale(.4)
            rotate(-10deg);

    }

    40%{

        opacity:1;

        transform:

            scale(1.15);

    }

    70%{

        transform:

            scale(.95);

    }

    100%{

        opacity:1;

        transform:

            scale(1);

    }

}


/* =========================================
   NOME PRINCIPAL DA EQUIPE
========================================= */

#teamName{

    margin:

        16px
        0
        14px;

    font-family:'Inter',sans-serif;

    font-size:clamp(32px,6vw,80px);

    font-weight:900;

    line-height:.9;

    letter-spacing:-3px;

    text-transform:uppercase;

    color:#fff;

    opacity:0;

    transform:

        translateY(25px);

    text-shadow:

        0 10px 30px
        rgba(0,0,0,.35);

}


/* NOME ENTRA */

.team-transition.ativo #teamName{

    animation:

        nomeEquipeEntrada
        .6s
        .35s
        ease
        forwards;

}


@keyframes nomeEquipeEntrada{

    from{

        opacity:0;

        transform:

            translateY(25px);

    }

    to{

        opacity:1;

        transform:

            translateY(0);

    }

}


/* =========================================
   ÁREA DOS PILOTOS
========================================= */

.team-drivers{

    display:flex;

    align-items:center;

    justify-content:center;

    gap:30px;

    opacity:0;

    transform:

        translateY(20px);

}


/* PILOTO */

.transition-driver{

    display:flex;

    align-items:center;

    gap:10px;

    color:#fff;

    font-family:'Inter',sans-serif;

}


/* NÚMERO */

.transition-driver span:first-child{

    font-size:clamp(35px,5vw,65px);

    line-height:1;

    font-weight:900;

    font-style:italic;

    color:#fff;

    opacity:.95;

    text-shadow:

        0 5px 20px
        rgba(0,0,0,.3);

}


/* NOME */

.transition-driver span:last-child{

    font-size:clamp(11px,1.5vw,20px);

    font-weight:800;

    letter-spacing:1px;

    text-transform:uppercase;

    white-space:nowrap;

    color:rgba(255,255,255,.9);

}


/* PILOTOS ENTRAM */

.team-transition.ativo .team-drivers{

    animation:

        pilotosEntrada
        .6s
        .7s
        ease
        forwards;

}


@keyframes pilotosEntrada{

    from{

        opacity:0;

        transform:

            translateY(20px);

    }

    to{

        opacity:1;

        transform:

            translateY(0);

    }

}


/* =========================================
   CARRO DA EQUIPE
========================================= */

#teamCar{

    position:absolute;

    z-index:4;

    width:min(600px,90vw);

    height:auto;

    bottom:7%;

    left:0;

    opacity:0;

    transform:

        translateX(-120vw);

    pointer-events:none;

    filter:

        drop-shadow(
            0 20px 25px
            rgba(0,0,0,.4)
        );

}


/* CARRO ATRAVESSA A TELA */

.team-transition.ativo #teamCar{

    animation:

        carroPassando
        3.4s
        linear
        forwards;

}


@keyframes carroPassando{

    0%{

        opacity:1;

        transform:

            translateX(-120vw);

    }

    100%{

        opacity:1;

        transform:

            translateX(120vw);

    }

}


/* =========================================
   MOBILE
========================================= */

