/* =========================================================
   TRANSIÇÃO DAS PÁGINAS DOS PILOTOS
========================================================= */

.driver-transition{
    position:fixed;

    inset:0;

    width:100%;
    height:100dvh;

    display:flex;

    align-items:center;
    justify-content:center;

    overflow:hidden;

    opacity:0;
    visibility:hidden;

    z-index:999999;

    transition:
        opacity .25s ease,
        visibility .25s ease;
}


/* =========================================================
   ATIVO
========================================================= */

.driver-transition.ativo{
    opacity:1;
    visibility:visible;
}


/* =========================================================
   NÚMERO GIGANTE DE FUNDO
========================================================= */

.driver-number-bg{
    position:absolute;

    top:50%;
    left:50%;

    transform:
        translate(-50%, -50%)
        scale(.7);

    font-family:'Inter', sans-serif;

    font-size:clamp(300px, 60vw, 1000px);

    font-weight:900;

    line-height:.8;

    color:rgba(255,255,255,.08);

    letter-spacing:-40px;

    pointer-events:none;

    user-select:none;

    opacity:0;

    z-index:1;
}


/* Animação do número */

.driver-transition.ativo
.driver-number-bg{

    animation:
        driverNumberEnter
        3.4s
        cubic-bezier(.22,1,.36,1)
        forwards;
}


@keyframes driverNumberEnter{

    0%{
        opacity:0;

        transform:
            translate(-50%, -50%)
            scale(.4);
    }

    15%{
        opacity:.85;
    }

    100%{
        opacity:.12;

        transform:
            translate(-50%, -50%)
            scale(1);
    }

}


/* =========================================================
   NOME GIGANTE
========================================================= */

.driver-name-transition{
    position:absolute;

    left:50%;
    top:50%;

    width:100%;

    transform:
        translate(-50%, -50%);

    display:flex;

    flex-direction:column;

    align-items:center;

    text-align:center;

    pointer-events:none;

    z-index:4;
}


/* Nome */

.driver-name-transition span{

    display:block;

    font-family:'Inter', sans-serif;

    font-size:
        clamp(60px, 10vw, 190px);

    font-weight:900;

    line-height:.8;

    letter-spacing:-6px;

    color:#fff;

    text-transform:uppercase;

    white-space:nowrap;

    opacity:0;

    transform:
        translateX(-150px);

}


/* Sobrenome */

.driver-name-transition strong{

    display:block;

    font-family:'Inter', sans-serif;

    font-size:
        clamp(70px, 12vw, 230px);

    font-weight:900;

    line-height:.8;

    letter-spacing:-8px;

    color:rgba(255,255,255,.35);

    text-transform:uppercase;

    white-space:nowrap;

    opacity:0;

    transform:
        translateX(150px);

}


/* =========================================================
   ANIMAÇÃO DO NOME
========================================================= */

.driver-transition.ativo
.driver-name-transition span{

    animation:
        driverFirstName
        .9s
        .45s
        cubic-bezier(.22,1,.36,1)
        forwards;
}


.driver-transition.ativo
.driver-name-transition strong{

    animation:
        driverLastName
        .9s
        .6s
        cubic-bezier(.22,1,.36,1)
        forwards;
}


@keyframes driverFirstName{

    from{
        opacity:0;

        transform:
            translateX(-150px);
    }

    to{
        opacity:1;

        transform:
            translateX(0);
    }

}


@keyframes driverLastName{

    from{
        opacity:0;

        transform:
            translateX(150px);
    }

    to{
        opacity:1;

        transform:
            translateX(0);
    }

}


/* =========================================================
   FOTO DO PILOTO
========================================================= */

.driver-transition-image{

    position:absolute;

    left:4%;

    bottom:0;

    height:92%;

    width:auto;

    max-width:50vw;

    object-fit:contain;

    object-position:center bottom;

    opacity:0;

    transform:
        translateX(-100%);

    filter:

        drop-shadow(
            0 20px 40px
            rgba(0,0,0,.45)
        );

    z-index:3;

    pointer-events:none;
}


/* Foto entra */

.driver-transition.ativo
.driver-transition-image{

    animation:
        driverImageEnter
        1.1s
        .2s
        cubic-bezier(.22,1,.36,1)
        forwards;
}


@keyframes driverImageEnter{

    0%{
        opacity:0;

        transform:
            translateX(-120%);
    }

    70%{
        opacity:1;

        transform:
            translateX(15px);
    }

    100%{
        opacity:1;

        transform:
            translateX(0);
    }

}


/* =========================================================
   INFORMAÇÕES INFERIORES
========================================================= */

.driver-info-transition{

    position:absolute;

    left:clamp(25px, 5vw, 100px);

    right:clamp(25px, 5vw, 100px);

    bottom:clamp(30px, 5vh, 80px);

    z-index:10;

    opacity:0;

    transform:
        translateY(40px);
}


/* Equipe */

.driver-info-transition > span{

    display:block;

    margin-bottom:12px;

    font-family:'Inter', sans-serif;

    font-size:
        clamp(11px, 1.2vw, 20px);

    font-weight:900;

    letter-spacing:5px;

    color:rgba(255,255,255,.7);

    text-transform:uppercase;
}


/* Nome e número */

.driver-info-bottom{

    display:flex;

    align-items:center;

    justify-content:space-between;

    gap:20px;

    border-top:
        1px solid
        rgba(255,255,255,.4);

    padding-top:14px;
}


/* Nome */

#driverFullName{

    font-family:'Inter', sans-serif;

    font-size:
        clamp(18px, 2vw, 36px);

    font-weight:900;

    color:#fff;

    text-transform:uppercase;

    letter-spacing:-1px;
}


/* Número pequeno */

#driverSmallNumber{

    font-family:'Inter', sans-serif;

    font-size:
        clamp(25px, 3vw, 55px);

    font-weight:900;

    line-height:1;

    color:#fff;
}


/* Animação das informações */

.driver-transition.ativo
.driver-info-transition{

    animation:
        driverInfoEnter
        .8s
        1.2s
        cubic-bezier(.22,1,.36,1)
        forwards;
}


@keyframes driverInfoEnter{

    from{

        opacity:0;

        transform:
            translateY(40px);
    }

    to{

        opacity:1;

        transform:
            translateY(0);
    }

}


/* =========================================================
   EFEITO DE LUZ
========================================================= */

.driver-transition::before{

    content:"";

    position:absolute;

    inset:0;

    background:

        radial-gradient(
            circle at 20% 50%,
            rgba(255,255,255,.18),
            transparent 30%
        ),

        linear-gradient(
            120deg,
            rgba(255,255,255,.08),
            transparent 45%
        );

    opacity:0;

    pointer-events:none;

    z-index:2;
}


.driver-transition.ativo::before{

    animation:
        driverLight
        1.5s
        .2s
        forwards;
}


@keyframes driverLight{

    from{
        opacity:0;
    }

    to{
        opacity:1;
    }

}


/* =========================================================
   LINHA DECORATIVA
========================================================= */

.driver-transition::after{

    content:"";

    position:absolute;

    left:0;

    bottom:0;

    width:0;

    height:4px;

    background:#fff;

    z-index:20;

    opacity:.7;
}


.driver-transition.ativo::after{

    animation:
        driverLine
        3.2s
        linear
        forwards;
}


@keyframes driverLine{

    from{
        width:0;
    }

    to{
        width:100%;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media(max-width:768px){

    .driver-number-bg{

        font-size:
            clamp(250px, 90vw, 600px);

        letter-spacing:-25px;
    }


    /* Foto */

    .driver-transition-image{

        left:-8%;

        height:78%;

        max-width:65vw;
    }


    /* Nome central */

    .driver-name-transition{

        left:55%;

        width:90%;
    }


    .driver-name-transition span{

        font-size:
            clamp(45px, 12vw, 90px);

        letter-spacing:-4px;
    }


    .driver-name-transition strong{

        font-size:
            clamp(52px, 14vw, 110px);

        letter-spacing:-5px;
    }


    /* Informações */

    .driver-info-transition{

        left:20px;

        right:20px;

        bottom:25px;
    }


    .driver-info-transition > span{

        margin-bottom:8px;

        font-size:10px;

        letter-spacing:3px;
    }


    .driver-info-bottom{

        padding-top:10px;
    }


    #driverFullName{

        font-size:
            clamp(16px, 5vw, 24px);
    }


    #driverSmallNumber{

        font-size:
            clamp(24px, 8vw, 40px);
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media(max-width:400px){

    .driver-transition-image{

        left:-12%;

        height:73%;
    }


    .driver-name-transition{

        left:57%;
    }


    .driver-name-transition span{

        font-size:38px;

        letter-spacing:-3px;
    }


    .driver-name-transition strong{

        font-size:46px;

        letter-spacing:-4px;
    }


    .driver-info-transition{

        left:14px;

        right:14px;

        bottom:18px;
    }

}


/* =========================================================
   TELAS BAIXAS / MODO PAISAGEM
========================================================= */

@media(max-height:600px){

    .driver-transition-image{

        height:90%;
    }


    .driver-name-transition span{

        font-size:
            clamp(45px, 8vw, 110px);
    }


    .driver-name-transition strong{

        font-size:
            clamp(55px, 10vw, 130px);
    }


    .driver-info-transition{

        bottom:15px;
    }

}








