/* =========================================
   BOTÕES
========================================= */

.switch-pontuacao{
  display:flex;

  justify-content:center;

  flex-wrap:wrap;

  gap:12px;

  margin-bottom:40px;
}

.btn-pontuacao{
  position:relative;

  overflow:hidden;

  background:
  linear-gradient(
    145deg,
    #121212,
    #090909
  );

  color:#e10600;

  border:
  1px solid rgba(225,6,0,.18);

  padding:12px 22px;

  cursor:pointer;

  border-radius:14px;

  transition:.35s ease;

  font-size:18px;

  font-weight:800;

  letter-spacing:.5px;

  box-shadow:
  0 10px 20px rgba(0,0,0,.25);
}

/* brilho */
.btn-pontuacao::before{
  content:"";

  position:absolute;

  top:0;
  left:-120%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.25),
    transparent
  );

  transition:.7s;
}

.btn-pontuacao:hover::before{
  left:120%;
}

/* hover */
.btn-pontuacao:hover{
  background:
  linear-gradient(
    145deg,
    #e10600,
    #850300
  );

  color:#ffffff;

  transform:
  translateY(-4px)
  scale(1.04);

  box-shadow:
  0 0 22px rgba(225,6,0,.4);
}

/* ativo */
.btn-pontuacao.ativo{
  background:
  linear-gradient(
    145deg,
    #e10600,
    #870300
  );

  color:#ffffff;

  box-shadow:
  0 0 24px rgba(225,6,0,.5);
}

/* =========================================
   TELEMETRIA
========================================= */

.telemetria-pontuacao{
  max-width:850px;

  margin:auto;

  display:flex;
  flex-direction:column;

  gap:14px;
}

/* =========================================
   LINHA
========================================= */

.linha-pontuacao{
  position:relative;

  overflow:hidden;

  display:flex;

  align-items:center;

  gap:14px;

  padding:14px 16px;

  border-radius:16px;

  background:
  linear-gradient(
    145deg,
    #111111,
    #0b0b0b
  );

  border:
  1px solid rgba(255,255,255,.05);

  transition:.35s ease;

  box-shadow:
  0 10px 18px rgba(0,0,0,.22);
}

/* brilho */
.linha-pontuacao::before{
  content:"";

  position:absolute;

  inset:0;

  background:
  linear-gradient(
    120deg,
    rgba(255,255,255,.06),
    transparent 45%
  );

  opacity:0;

  transition:.35s;
}

.linha-pontuacao:hover::before{
  opacity:1;
}

/* hover */
.linha-pontuacao:hover{
  transform:
  translateY(-4px);

  box-shadow:
  0 0 24px rgba(225,6,0,.15);
}

/* posição */
.linha-pontuacao span{
  width:42px;

  font-weight:900;

  font-size:18px;

  color:#ffffff;
}

/* número */
.numero-pontuacao{
  width:55px;

  text-align:right;

  font-size:18px;

  font-weight:800;

  color:#ffffff;
}

/* =========================================
   BARRAS
========================================= */

.barra-pontuacao{
  flex:1;

  height:12px;

  background:#222;

  border-radius:30px;

  overflow:hidden;

  position:relative;
}

.barra-fill-pontuacao{
  height:100%;

  width:0%;

  border-radius:30px;

  box-shadow:
  0 0 14px currentColor;

  transition:
  width 1s ease;
}

/* =========================================
   CORES
========================================= */

/* ouro */
.gold-pontuacao{
  background:
  linear-gradient(
    90deg,
    #ffd700,
    #ffb300
  );

  color:#ffd700;
}

/* prata */
.silver-pontuacao{
  background:
  linear-gradient(
    90deg,
    #cfcfcf,
    #f1f1f1
  );

  color:#d6d6d6;
}

/* bronze */
.bronze-pontuacao{
  background:
  linear-gradient(
    90deg,
    #cd7f32,
    #9e5c1f
  );

  color:#cd7f32;
}

/* branco */
.white-pontuacao{
  background:
  linear-gradient(
    90deg,
    #ffffff,
    #dcdcdc
  );

  color:#ffffff;
}

/* =========================================
   ANIMAÇÃO
========================================= */

@keyframes f1PontuacaoGlow{

  0%,100%{
    transform:translate(0,0) scale(1);
  }

  50%{
    transform:translate(60px,40px) scale(1.12);
  }

