/* ===========================
   SLIDER PIT STOP
=========================== */

.slider-pit{
    position:relative;
    width:100%;
    overflow:hidden;
    padding:70px 0;
	  background:#15151e;
}

.bg-slider-pit{
    position:absolute;
    inset:0;

    background-size:cover;
    background-position:center;

    filter:blur(35px) brightness(.35);
    transform:scale(1.15);

    transition:.6s;
    z-index:0;
}

.bg-slider-pit::after{
    content:"";
    position:absolute;
    inset:0;
}

.titulo-pit-slider,
.slider-pit-container{
    position:relative;
    z-index:2;
}

.titulo-pit-slider{
    text-align:center;
    color:#dc0000;
    font-size:48px;
    margin-bottom:40px;
}

.slider-pit-container{
    width:min(1300px,95%);
    margin:auto;
    overflow:hidden;
    border-radius:20px;
    position:relative;
}

.slider-pit-track{
    display:flex;
    transition:transform .45s ease;
}

.slide-pit{
    min-width:100%;
    position:relative;
}

.slide-pit video{
    width:100%;
    height:clamp(320px,60vw,700px);

    object-fit:cover;
    display:block;
}

.slide-pit-texto{
    position:absolute;
    left:0;
    right:0;
    bottom:0;

    padding:35px;

    background:linear-gradient(
        transparent,
        rgba(0,0,0,.92)
    );
}

.slide-pit-texto h3{
    color:#dc0000;
    font-size:42px;
    margin-bottom:12px;
}

.slide-pit-texto p{
    color:#f0f0f0;
    font-size:23px;
    line-height:1.6;
}

