.btn-pit{
    position:absolute;
    top:50%;

    transform:translateY(-50%);

    width:52px;
    height:52px;

    border:none;
    border-radius:50%;

    background:rgba(0,0,0,.55);
    color:#fff;

    font-size:28px;
    cursor:pointer;

    transition:.25s;
    z-index:3;
}

.btn-pit:hover{
