.secao-bandeiras{
  position:relative;

  padding:20px 20px;

  background:#15151e;

  overflow:hidden;

}

/* DETALHE FUNDO */
.secao-bandeiras::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    120deg,
    rgba(255,255,255,.03),
    transparent 35%
  );

  pointer-events:none;
}

/* TÍTULO */
.titulo-bandeiras{
  text-align:center;

  color:white;

  font-size:clamp(28px,5vw,42px);
  font-weight:900;

  letter-spacing:1px;

  margin-bottom:60px;

  text-transform:uppercase;

  position:relative;
}

.titulo-bandeiras::after{
  content:"";

  width:90px;
  height:4px;

  border-radius:999px;

  background:#e10600;

  display:block;

  margin:14px auto 0;
}

/* SLIDER */
.slider-bandeiras{
  perspective:1600px;

  overflow:hidden;

  width:100%;
}

/* CONTAINER */
.bandeiras-focus{
  display:flex;

  justify-content:center;
  align-items:center;

  gap:28px;

  transition:transform .5s ease;

  padding:35px 0;
}

/* CARD */
.card-focus{
  position:relative;

  width:min(26vw,270px);
  aspect-ratio:9/16;

  border-radius:24px;

  overflow:hidden;

  cursor:pointer;

  transition:
  transform .45s ease,
  filter .45s ease,
  box-shadow .45s ease;

  filter:
  grayscale(100%)
  brightness(.4);

  transform:
  scale(.82)
  rotateY(14deg);

  box-shadow:
  0 15px 40px rgba(0,0,0,.5);

  flex-shrink:0;
}

/* DIREITA */
.card-focus:nth-child(3),
.card-focus:nth-child(4){
  transform:
  scale(.82)
  rotateY(-14deg);
}

/* IMAGEM */
.card-focus img{
  width:100%;
  height:100%;

  object-fit:cover;

  transition:transform .5s ease;
}

.card-focus:hover img{
  transform:scale(1.05);
}

/* CARD ATIVO */
.card-focus.ativo{
  filter:none;

  transform:
  scale(1.12)
  rotateY(0deg);

  z-index:5;

  box-shadow:
  0 0 40px rgba(255,255,255,.12),
  0 20px 60px rgba(0,0,0,.7);
}

/* OVERLAY */
.overlay-info{
  position:absolute;

  inset:auto 0 0 0;

  padding:24px 20px;

  background:
  linear-gradient(
    transparent,
    rgba(0,0,0,.94)
  );

  color:white;

  transform:translateY(100%);

  transition:.4s ease;
}

/* TEXTO */
.overlay-info h3{
  font-size:clamp(16px,2vw,20px);

  font-weight:800;

  margin-bottom:6px;

  opacity:0;

  transform:translateY(14px);

  transition:.4s;
}

.overlay-info p{
  font-size:clamp(12px,1.5vw,14px);

  line-height:1.5;

  color:#d1d1d1;

  opacity:0;

  transform:translateY(14px);

  transition:.4s;
}

/* QUANDO ATIVO */
.card-focus.ativo .overlay-info{
  transform:translateY(0);
}

.card-focus.ativo .overlay-info h3{
  opacity:1;
  transform:translateY(0);

  transition-delay:.15s;
}

.card-focus.ativo .overlay-info p{
  opacity:1;
  transform:translateY(0);

  transition-delay:.3s;
}

/* GLOW */
.card-focus.ativo::before{
  content:"";

  position:absolute;
  inset:-2px;

  border-radius:24px;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.6),
    transparent
  );

  animation:brilho 2.2s linear infinite;
}

@keyframes brilho{
  0%{
    opacity:0;
    transform:translateX(-120%);
  }

  50%{
    opacity:1;
  }

  100%{
    opacity:0;
    transform:translateX(120%);
  }
}

/* CORES */
