.pista-sc{
  position:relative;
  width:100%;
  height:500px;

  background:#15151e;

  overflow:hidden;

  border:1px solid rgba(255,255,255,.06);

  box-shadow:
  inset 0 0 40px rgba(255,255,255,.03),
  0 0 35px rgba(0,0,0,.45);
}

/* ========================= */
/* LINHAS / FUNDO */
/* ========================= */

.linha-pista{
  position:absolute;
  top:605px;
  left:0;

  width:220%;
  height:3px;

  background:
  repeating-linear-gradient(
    to right,
    rgba(255,255,255,.95),
    rgba(255,255,255,.95) 16px,
    transparent 16px,
    transparent 34px
  );

  opacity:.35;

  animation:moverLinha 2s linear infinite;
}

@keyframes moverLinha{
  from{
    transform:translateX(0);
  }

  to{
    transform:translateX(-50%);
  }
}

/* brilho ambiente */
.pista-sc::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(circle at center,
  rgba(255,255,255,.04),
  transparent 65%);

  pointer-events:none;
}

/* ========================= */
/* SAFETY CAR */
/* ========================= */

.safety-car{
  position:absolute;

  top:490px;
  left:-300px;

  width:200px;

  z-index:1000;

  opacity:0;

  transition:
  left .8s ease,
  opacity .5s ease,
  transform .4s ease;
}

.safety-car img{
  width:100%;
  display:block;

  filter:
  drop-shadow(0 0 12px rgba(255,214,0,.45));
}

/* ========================= */
/* CARROS */
/* ========================= */

.carro{
  position:absolute;
  z-index:10;

  transition:
  left .7s ease,
  transform .25s ease,
  filter .25s ease;
}

.carro:hover{
  transform:scale(1.03);
}

.carro img{
  width:200px;
  display:block;

  filter:
  drop-shadow(0 0 14px rgba(255,255,255,.08));
}

/* POSIÇÕES MANTIDAS */

.carro1{
  left:1200px;
  top:505px;
}

.carro2{
  left:900px;
  top:535px;
}

.carro3{
  left:500px;
  top:490px;
}

.carro4{
  left:100px;
  top:530px;
}

/* ========================= */
/* BADGES */
/* ========================= */

.badge-sc,
.badge-vsc{
  display:flex;
  align-items:center;
  justify-content:center;

  width:58px;
  height:48px;

  border-radius:8px;

  font-size:34px;
  font-weight:900;

  color:#000;

  backdrop-filter:blur(4px);
}

.badge-sc{
  background:
  linear-gradient(135deg,#ffe600,#ffbf00);

  border:2px solid #000;

  box-shadow:
  0 0 15px rgba(255,214,0,.5);

  animation:piscarSC 1s infinite;
}

.badge-vsc{
  background:
  linear-gradient(135deg,#fff06a,#ffd600);

  border:2px solid rgba(0,0,0,.4);

  box-shadow:
  0 0 12px rgba(255,214,0,.45);

  animation:piscarVSC .8s infinite;
}

@keyframes piscarSC{
  0%{
    opacity:1;
    transform:scale(1);
  }

  50%{
    opacity:.45;
    transform:scale(1.08);
  }

  100%{
    opacity:1;
    transform:scale(1);
  }
}

@keyframes piscarVSC{
  0%{
    opacity:1;
  }

  50%{
    opacity:.35;
  }

  100%{
    opacity:1;
  }
}

/* INFO CORRIDA */
.info-corrida{
  position:absolute;

  top:35px;
  left:35px;

  width:min(500px,120vw);

  padding:18px;

  border-radius:18px;

  background:
  linear-gradient(
    135deg,
    rgba(0,0,0,.88),
    rgba(18,18,18,.78)
  );

  border:
  1px solid rgba(255,255,255,.08);

  border-left:
  4px solid lime;

  color:white;

  backdrop-filter:blur(10px);

  box-shadow:
  0 15px 40px rgba(0,0,0,.45);

  z-index:20;
}

.titulo-info{
