  font-weight:800;

  margin-bottom:8px;
}

.texto-info{
  font-size:33px;

  line-height:1.6;

  color:#d4d4d4;
}


.hud-velocidade{
  position:absolute;

  bottom:28px;
  left:20px;

  display:flex;
  align-items:center;
  gap:14px;

  padding:12px 14px;

  border-radius:14px;

