.penalidades-container{
  padding:40px 20px;

  background:#15151e;

  color:white;
  font-family:'Segoe UI',Arial,sans-serif;

  position:relative;
  overflow:hidden;
}

/* ========================= */
/* TÍTULO */
/* ========================= */

.penalidades-container h2{
  text-align:center;

  font-size:2rem;
  font-weight:900;

  margin-bottom:10px;

  letter-spacing:1px;
  text-transform:uppercase;
}

.penalidades-container p{
  text-align:center;

  opacity:.7;

  margin-bottom:25px;

  font-size:.95rem;
}

/* ========================= */
/* GRID */
/* ========================= */

.pen-grid{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(170px,1fr));

  gap:18px;

  margin-top:70px;
}

/* ========================= */
/* CARDS */
/* ========================= */

.pen-card{
  position:relative;

  background:
  linear-gradient(
    145deg,
    #151515,
    #0b0b0b
  );
  top:150px;
  padding:22px 16px;

  border-radius:18px;

  text-align:center;

  cursor:pointer;

  overflow:hidden;

  border:1px solid rgba(255,255,255,.05);

  border-left:5px solid #444;

  box-shadow:
  0 8px 20px rgba(0,0,0,.35);

  transition:
  transform .25s ease,
  box-shadow .25s ease,
  border-color .25s ease;
}

.pen-card::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.05),
    transparent
  );

  transform:translateX(-100%);

  transition:.6s;
}

.pen-card:hover::before{
  transform:translateX(100%);
}

.pen-card:hover{
  transform:
  translateY(-6px)
  scale(1.03);

  box-shadow:
  0 12px 30px rgba(0,0,0,.45);
}

/* TÍTULO DO CARD */

.pen-card h3{
  font-size:1.5rem;
  font-weight:800;

  margin-bottom:8px;

  letter-spacing:.5px;
}

/* TEXTO */

.pen-card p{
  margin:0;

  opacity:.72;

  font-size:1.88rem;

  line-height:1.4;
}

/* ========================= */
/* CORES FIA */
/* ========================= */

.pen-card[data-tipo="+5s"]{
  border-color:#ff9f1a;
  box-shadow:0 0 18px rgba(255,159,26,.15);
}

.pen-card[data-tipo="+10s"]{
  border-color:#ff3131;
  box-shadow:0 0 18px rgba(255,49,49,.15);
}

.pen-card[data-tipo="DRIVE THROUGH"]{
  border-color:#8f5cff;
  box-shadow:0 0 18px rgba(143,92,255,.18);
}

.pen-card[data-tipo="STOP & GO"]{
  border-color:#ff004c;
  box-shadow:0 0 18px rgba(255,0,76,.18);
}

.pen-card[data-tipo="GRID PENALTY"]{
  border-color:#ffe600;
  box-shadow:0 0 18px rgba(255,230,0,.15);
}

.pen-card[data-tipo="DSQ"]{
  border-color:#ffffff;
  box-shadow:0 0 18px rgba(255,255,255,.15);
}

/* ========================= */
/* BANNER FIA */
/* ========================= */

.fia-banner{
