/* ==========================================================
   NOTÍCIAS F1
========================================================== */

.noticias-f1{

    position:relative;

    overflow:hidden;

    padding:90px 20px;

    color:#ffffff;

    background:#15151e;

}

.noticias-f1::before{

    content:"";

    position:absolute;

    top:-180px;
    left:-180px;

    width:520px;
    height:520px;

    filter:blur(45px);

    animation:f1Glow 8s ease-in-out infinite;

    z-index:0;

}

.noticias-f1>*{

    position:relative;

    z-index:2;

}

/* ==========================================================
   TÍTULOS
========================================================== */

.titulo-noticias{

    text-align:center;

    font-size:clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    color:#ffffff;

    margin-bottom:14px;

    text-shadow:
    0 0 18px rgba(225,6,0,.45);

}

.subtitulo-noticias{

    text-align:center;

    max-width:700px;

    margin:0 auto 45px;

    font-size:18px;

    color:#cfcfcf;

    line-height:1.6;

}

/* ==========================================================
   GRID
========================================================== */

.noticias-container{

    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(330px,1fr));

    gap:28px;

    max-width:1250px;

    margin:auto;

}

/* ==========================================================
   CARD
========================================================== */

.noticia-card{

    display:flex;

    flex-direction:column;

    overflow:hidden;

    border-radius:22px;

    background:
    linear-gradient(
        145deg,
        #151515,
        #202020
    );

    border:1px solid rgba(225,6,0,.15);

    box-shadow:
    0 15px 30px rgba(0,0,0,.30);

    transition:.35s ease;

}

.noticia-card:hover{

    transform:
    translateY(-8px);

    border-color:
    rgba(225,6,0,.45);

    box-shadow:
    0 0 28px rgba(225,6,0,.28);

}

/* ==========================================================
   IMAGEM
========================================================== */

.noticia-imagem{

    width:100%;

    height:220px;

    object-fit:cover;

    display:block;

    transition:.4s ease;

}

.noticia-card:hover .noticia-imagem{

    transform:scale(1.05);

}

/* ==========================================================
   CONTEÚDO
========================================================== */

.noticia-conteudo{

    display:flex;

    flex-direction:column;

    gap:14px;

    padding:22px;

    flex:1;

}

.noticia-fonte{

    display:inline-block;

    width:max-content;

    padding:5px 12px;

    border-radius:999px;

    background:#e10600;

    color:#ffffff;

    font-size:12px;

    font-weight:700;

    text-transform:uppercase;

    letter-spacing:.5px;

}

.noticia-titulo{

    font-size:22px;

    font-weight:800;

    line-height:1.35;

    color:#ffffff;

}

.noticia-descricao{

    flex:1;

    font-size:15px;

    line-height:1.7;

    color:#cfcfcf;

}

/* ==========================================================
   RODAPÉ
========================================================== */

.noticia-footer{

    display:flex;

    justify-content:space-between;

    align-items:center;

    gap:14px;

    margin-top:auto;

}

.noticia-data{

    font-size:13px;

    color:#9d9d9d;

}

.noticia-link{

    padding:10px 18px;

    border-radius:10px;

    background:#e10600;

    color:#ffffff;

    text-decoration:none;

    font-weight:700;

    transition:.3s ease;

}

.noticia-link:hover{

    background:#ff2a20;

    transform:translateY(-2px);

    box-shadow:0 0 15px rgba(225,6,0,.45);

}

/* ==========================================================
   RESPONSIVO
========================================================== */

@media(max-width:768px){

    .noticias-f1{

        padding:70px 14px;

    }

    .titulo-noticias{

        font-size:2.2rem;

    }

    .subtitulo-noticias{

        font-size:15px;

        margin-bottom:30px;

    }

    .noticias-container{

        grid-template-columns:1fr;

        gap:20px;

    }

    .noticia-imagem{

        height:200px;

    }

    .noticia-conteudo{

        padding:18px;

    }

    .noticia-titulo{

        font-size:20px;

    }

    .noticia-descricao{

        font-size:14px;

    }

    .noticia-footer{

        flex-direction:column;

        align-items:flex-start;

    }

    .noticia-link{

        width:100%;

        text-align:center;

    }

}

@media(max-width:480px){

    .titulo-noticias{

        font-size:1.9rem;

    }

    .noticia-imagem{

        height:180px;

    }

    .noticia-titulo{

        font-size:18px;

    }

}




/*===============================================================

FIM DE SEMANA

========================================================*/

.f1-guide-section {
  background-color: #15151e;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  box-sizing: border-box;
  width: 100%;
}

.f1-guide-section * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* --- CABEÇALHO --- */
.f1-guide-section .f1-header {
  text-align: center;
  margin-bottom: 30px;
  width: 100%;
  max-width: 900px;
}

.f1-guide-section .f1-header h1 {
  font-size: 2rem;
  margin-bottom: 8px;
  text-transform: uppercase;
  color: #ffffff;
}

.f1-guide-section .f1-header p {
  color: #a0a0a0;
  font-size: 1rem;
}

/* --- BOTÕES DE ALTERNÂNCIA --- */
.f1-guide-section .toggle-container {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-bottom: 20px;
  background-color: #000000;
  padding: 6px;
  border-radius: 30px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}

.f1-guide-section .toggle-btn {
  background-color: transparent;
  border: none;
  color: #ffffff;
  padding: 10px 24px;
  font-weight: bold;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.f1-guide-section .toggle-btn.active {
  background-color: #e10600;
  box-shadow: 0 0 10px rgba(225, 6, 0, 0.5);
  color: #ffffff;
}

/* --- CARROSSEL --- */
.f1-guide-section .carousel-wrapper {
  position: relative;
  width: 100%;
  max-width: 1100px;
  display: flex;
  align-items: center;
}

.f1-guide-section .carousel-container {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: 20px 10px;
  width: 100%;
  scrollbar-width: none;
}

.f1-guide-section .carousel-container::-webkit-scrollbar {
  display: none;
}

/* --- CARDS DOS DIAS --- */
.f1-guide-section .card {
  min-width: 300px;
  max-width: 320px;
  height: 420px;
  background-color: #1f1f2b;
  border-radius: 16px;
  overflow: hidden;
  flex-shrink: 0;
  position: relative;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
  border: 1px solid #333333;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  transition: transform 0.3s ease, border-color 0.3s ease;
}

.f1-guide-section .card:hover {
  transform: translateY(-5px);
  border-color: #e10600;
}

.f1-guide-section .card-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.6;
  transition: opacity 0.3s ease;
}

.f1-guide-section .card:hover .card-img {
  opacity: 0.8;
}

.f1-guide-section .card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(15, 15, 22, 0.95) 20%, rgba(15, 15, 22, 0.2) 70%);
}

.f1-guide-section .card-content {
  position: relative;
  z-index: 2;
  padding: 20px;
}

.f1-guide-section .card-badge {
  display: inline-block;
  background-color: #e10600;
  color: #ffffff;
  font-size: 0.75rem;
  font-weight: bold;
  padding: 4px 8px;
  border-radius: 4px;
  margin-bottom: 10px;
  text-transform: uppercase;
}

.f1-guide-section .card-day {
  font-size: 1.6rem;
  font-weight: 800;
  text-transform: uppercase;
  color: #ffffff;
  margin-bottom: 8px;
}

.f1-guide-section .card-description {
  font-size: 0.9rem;
  color: #a0a0a0;
  line-height: 1.4;
}

/* --- BOTÕES DE NAVEGAÇÃO E INDICADORES --- */
.f1-guide-section .nav-btn {
  background-color: rgba(0, 0, 0, 0.7);
  border: 1px solid #444444;
  color: #ffffff;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  cursor: pointer;
  position: absolute;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  transition: background-color 0.3s ease;
}

.f1-guide-section .nav-btn:hover {
  background-color: #e10600;
}

.f1-guide-section .nav-btn.prev {
  left: -20px;
}

.f1-guide-section .nav-btn.next {
  right: -20px;
}

.f1-guide-section .dots-container {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 15px;
}

.f1-guide-section .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: #444444;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.f1-guide-section .dot.active {
  background-color: #e10600;
}

/* RESPONSIVIDADE */
@media (max-width: 768px) {
  .f1-guide-section .nav-btn {
    display: none;
  }
  .f1-guide-section .card {
    min-width: 260px;
    height: 380px;
  }
}



