/* =====================================
   ESTATÍSTICAS DA TEMPORADA
===================================== */

.estatisticas-temporada{

    max-width:1200px;

    margin:70px auto;

    padding:35px;

    border-radius:26px;

    background:#15151e;

    border:1px solid
    rgba(225,6,0,.18);

    box-shadow:
    0 20px 45px
    rgba(0,0,0,.45);

    color:#fff;

    position:relative;

    overflow:hidden;
}


/* brilho */

.estatisticas-temporada::before{

    content:"";

    position:absolute;

    inset:0;


    pointer-events:none;

}


/* =====================================
   TÍTULO
===================================== */

.estatisticas-temporada h2{

    text-align:center;

    font-size:42px;

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:1px;

    margin-bottom:40px;

    color:#fff;

    text-shadow:
    0 0 18px
    rgba(225,6,0,.45);

}


/* =====================================
   GRID DOS CARDS
===================================== */

.stats-grid{

    display:grid;

    grid-template-columns:
    repeat(3,1fr);

    gap:22px;

}


/* =====================================
   CARD
===================================== */

.stat-card{

    position:relative;

    padding:25px 20px;

    border-radius:22px;

    text-align:center;

    background:
    linear-gradient(
        145deg,
        #1b1b1b,
        #101010
    );

    border:
    1px solid
    rgba(255,255,255,.08);

    overflow:hidden;

    transition:.35s ease;

    box-shadow:
    0 12px 25px
    rgba(0,0,0,.35);

}


/* brilho interno */

.stat-card::before{

    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
        120deg,
        rgba(255,255,255,.08),
        transparent 40%
    );

    opacity:0;

    transition:.35s;

}


.stat-card:hover{

    transform:
    translateY(-8px);

    border-color:
    rgba(225,6,0,.45);

    box-shadow:
    0 0 30px
    rgba(225,6,0,.25);

}


.stat-card:hover::before{

    opacity:1;

}


/* =====================================
   TITULO DO CARD
===================================== */

.stat-card h3{

    position:relative;

    z-index:1;

    margin-bottom:20px;

    font-size:30px;

    color:#e10600;

    font-weight:900;

}


/* =====================================
   IMAGEM PILOTO
===================================== */

.stat-card img{

    width:150px;

    height:150px;

    object-fit:contain;

    border-radius:50%;

    margin-bottom:15px;

    filter:
    drop-shadow(
        0 0 12px
        rgba(225,6,0,.35)
    );

}


/* =====================================
   NOME
===================================== */

.stat-card strong{

    display:block;

    position:relative;

    z-index:1;

    font-size:28px;

    font-weight:900;

    color:#fff;

}


/* =====================================
   VALOR
===================================== */

.stat-card p{

    margin-top:10px;

    position:relative;

    z-index:1;

    font-size:25px;

    color:#bdbdbd;

    font-weight:700;

}


/* =====================================
   MOBILE
===================================== */

@media(max-width:900px){

    .stats-grid{

        grid-template-columns:
        repeat(2,1fr);

    }

}


@media(max-width:600px){

    .estatisticas-temporada{

        margin:40px 15px;

        padding:22px;

    }


    .estatisticas-temporada h2{

        font-size:28px;

    }


    .stats-grid{

        grid-template-columns:1fr;

    }


    .stat-card h3{

        font-size:18px;

    }


    .stat-card strong{

        font-size:22px;

    }

}



