========================================================== */

.titulo-campeonatos{

    text-align:center;

    font-size:clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:45px;

    color:#ffffff;

    text-shadow:
    0 0 18px rgba(225,6,0,.45);

}

/* ==========================================================
   CONTAINER
========================================================== */

.container-campeonatos{

    max-width:1150px;

    margin:auto;

}

/* ==========================================================
   BOTÕES
========================================================== */

.tabs-campeonatos{

    display:flex;

    justify-content:center;

    gap:18px;

    margin-bottom:35px;

}

.tab-campeonato{

    padding:14px 34px;

    border:none;

    border-radius:14px;

    cursor:pointer;

    font-size:17px;

    font-weight:800;

    color:#ffffff;

    background:
    linear-gradient(
        145deg,
        #1a1a1a,
        #252525
    );

    border:1px solid rgba(225,6,0,.18);

    transition:.3s ease;

}

.tab-campeonato:hover{

    transform:translateY(-3px);

    border-color:#e10600;

    box-shadow:
    0 0 18px rgba(225,6,0,.25);

}

.tab-campeonato.active{

    background:
    linear-gradient(
        135deg,
        #e10600,
        #870300
    );

    border-color:#e10600;

    box-shadow:
    0 0 20px rgba(225,6,0,.40);

}

/* ==========================================================
   PAINEL
========================================================== */

.painel-campeonato{

    background:
    linear-gradient(
        145deg,
        #141414,
        #1c1c1c
    );

    border-radius:22px;

    overflow:hidden;

    border:1px solid rgba(225,6,0,.15);

    box-shadow:
    0 15px 30px rgba(0,0,0,.30);

}

.escondido{

    display:none;

}

/* ==========================================================
   CABEÇALHO
========================================================== */

.cabecalho-campeonato{

    display:grid;

    grid-template-columns:
    70px
    80px
    90px
    70px
    1fr
    90px;

    align-items:center;

    padding:18px;

    background:
    linear-gradient(
        90deg,
        #870300,
        #e10600
    );

    font-size:14px;

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:1px;

    color:#ffffff;

}

/* ==========================================================
   LINHAS DOS CAMPEONATOS
========================================================== */

.linha-piloto,
.linha-construtor{

    display:grid;

    align-items:center;

    min-height:82px;

    padding:14px 18px;

    transition:.30s ease;

    color:#ffffff;

}

.linha-piloto{

    grid-template-columns:
    70px
    80px
    90px
    70px
    1fr
    90px;

}

.linha-construtor{

    grid-template-columns:
    70px
    80px
    140px
    1fr
    90px;

}

.linha-piloto:nth-child(even),
.linha-construtor:nth-child(even){

    filter:brightness(.96);

}

.linha-piloto:hover,
.linha-construtor:hover{

    transform:scale(1.01);

    filter:brightness(1.08);

    box-shadow:
    inset 0 0 0 2px rgba(255,255,255,.18);

