/* FUNDO DO DASHBOARD */
/* FUNDO ESCURO */
#dashboard{
  position: fixed;
  inset: 0;

  background: rgba(0,0,0,0.75);
  backdrop-filter: blur(6px);

  display: none;
  align-items: center;
  justify-content: center;

  z-index: 9999;
}

/* CONTAINER PRINCIPAL */
.dashboard-container{
  width: 92%;
  max-width: 900px;

  background: #111;
  border-radius: 22px;

  padding: 16px;

  display: flex;
  flex-direction: column;
  gap: 10px;

  box-shadow: 0 0 30px rgba(0,0,0,0.45);

  animation: aparecer .25s ease;
}

/* TÍTULO */
#tituloGP{
  font-size: 2.8rem;
  font-weight: 900;
  text-align: center;

  color: white;

  text-transform: uppercase;
  letter-spacing: 1px;

  margin-bottom: 4px;
}

/* LISTA DOS PILOTOS */
#listaPilotos{
  display: flex;
  flex-direction: column;
  gap: 7px;
}

/* LINHA PILOTO */
.linha-ppiloto{
  min-height: 64px;

  border-radius: 14px;

  display: flex;
  align-items: center;
  gap: 12px;

  padding: 0 14px;

  box-shadow: inset 0 0 0 2px rgba(255,255,255,0.05);

  transition: transform .15s ease;
}

.linha-ppiloto:hover{
  transform: scale(1.01);
}

/* POSIÇÃO */
.posicao-box{
  width: 38px;
  height: 38px;

  border-radius: 10px;

  background: rgba(255,255,255,0.94);

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 1.2rem;
  font-weight: 900;
}

/* LOGO EQUIPE */
.equipe-logo img{
  width: 38px;
  height: 38px;

  object-fit: contain;
}

/* FOTO PILOTO */
.piloto-img-box img{
  width: 48px;
  height: 48px;

  border-radius: 50%;
  object-fit: cover;

}

/* INFO */
.info-piloto{
  flex: 1;
}

/* NOME + NÚMERO */
.nome-numero{
  display: flex;
  align-items: center;
  gap: 8px;
}

.nome{
  font-size: 1.55rem;
  font-weight: 800;
}

.numero{
  font-size: 1.95rem;
  opacity:1;
  font-weight:800;

}

/* TEMPO */
.tempo{
  min-width: 95px;

  text-align: center;

  font-size: 1.8rem;
  font-weight: 700;
}

/* VOLTA RÁPIDA */
.volta-rapida{
  width: 34px;
  height: 34px;

  border-radius: 50%;

  background: #b400ff;

  display: flex;
  align-items: center;
  justify-content: center;
}

.volta-rapida svg{
  width: 18px;
  height: 18px;

  stroke: white;
  stroke-width: 2;
  fill: none;
}

/* PONTOS */
.pontos-box{
  min-width: 46px;
  height: 42px;

  border-radius: 12px;

  background: rgba(0,5,2,0.94);
  color:red;
  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 1.45rem;
  font-weight: 900;
}

/* LÍDER DA CORRIDA */
.linha-piloto:first-child .posicao-box{
  background:#e10600;
  color:white;

  box-shadow:
  0 0 12px rgba(225,6,0,.45);
}

/* BOTÃO FECHAR */
.fechar-btn{
  width: 100%;
  height: 46px;

  border: none;
  border-radius: 12px;

  background: #e10600;
  color: white;

  font-size: .95rem;
  font-weight: 800;

  cursor: pointer;

  transition: .2s;
}



.fechar-btn:hover{
  background: #ff1f1f;
  transform: scale(1.02);
}

/* ANIMAÇÃO */
@keyframes aparecer{
  from{
    opacity: 0;
    transform: translateY(20px) scale(.96);
  }

  to{
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

