////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/


/* ==================================================
   CAMPEONATO MUNDIAL DE CONSTRUTORES
================================================== */

.f1-titulos-construtores{
  position:relative;

  width:100%;
	height:100vh;
	min-height:100vh;
	

  padding:110px 40px;

  box-sizing:border-box;

  overflow:hidden;

  background:
    radial-gradient(
      circle at 15% 20%,
      rgba(255,255,255,.06),
      transparent 35%
    ),
    linear-gradient(
      135deg,
      #050505 0%,
      #0b0b0b 55%,
      #111 100%
    );

  color:#fff;

  isolation:isolate;
}


/* ==================================================
   GLOW DO FUNDO
================================================== */

.f1-titulos-construtores::before{
  content:"";

  position:absolute;

  width:600px;
  height:600px;

  top:-300px;
  right:-250px;

  background:
    radial-gradient(
      circle,
      rgba(255,128,0,.16),
      transparent 70%
    );

  filter:blur(50px);

  pointer-events:none;

  z-index:0;
}


.f1-titulos-construtores::after{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  bottom:-300px;
  left:-250px;

  background:
    radial-gradient(
      circle,
      rgba(255,255,255,.05),
      transparent 70%
    );

  filter:blur(50px);

  pointer-events:none;

  z-index:0;
}


/* ==================================================
   CONTEÚDO
================================================== */

.f1-titulos-construtores > *{
  position:relative;

  z-index:2;
}


/* ==================================================
   CABEÇALHO
================================================== */

.f1-titulos-header{
  max-width:1000px;

  margin:0 auto 25px;

  text-align:center;
}


.f1-titulos-kicker{
  display:inline-block;

  margin-bottom:7px;

  color:#ffffff;

  font-size:15px;

  font-weight:800;

  letter-spacing:3px;
}


.f1-titulos-titulo{
  margin:0;

  font-family:Arial,sans-serif;

  font-size:
    clamp(2rem,4vw,4rem);

  font-weight:900;

  line-height:.95;

  letter-spacing:-2px;

  text-transform:uppercase;

  background:
    linear-gradient(
      90deg,
      #fff,
      #dc5555
    );

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
}


.f1-titulos-subtitulo{
  max-width:700px;

  margin:22px auto 0;

  color:rgba(255,255,255,.65);

  font-size:
    clamp(.95rem,1.5vw,1.15rem);

  line-height:1.7;
}


/* ==================================================
   GRADE
================================================== */

.f1-titulos-grade{

    position:relative;

    z-index:5;

    width:100%;
    max-width:none;

    margin:0;

    padding:20px;

    box-sizing:border-box;

    display:grid;

    grid-template-rows:
        repeat(10,minmax(0,1fr));

    grid-auto-flow:column;

    grid-auto-columns:
        minmax(135px,1fr);

    gap:6px;

    background:
        rgba(255,255,255,.025);

    border:
        1px solid
        rgba(255,255,255,.08);

    border-radius:20px;

    box-shadow:
        inset 0 1px 0
        rgba(255,255,255,.04),

        0 20px 60px
        rgba(0,0,0,.35);

    backdrop-filter:blur(10px);
    -webkit-backdrop-filter:blur(10px);

    min-width:0;
    min-height:0;

    overflow:visible;
}


/* ==================================================
   ITEM DO TÍTULO
================================================== */

.f1-titulo-item{
  position:relative;

  display:flex;

  align-items:center;

  gap:10px;

  min-height:54px;

  padding:7px 12px;

  box-sizing:border-box;

  border-radius:10px;

  background:
    rgba(255,255,255,.035);

  border:
    1px solid rgba(255,255,255,.06);

  cursor:pointer;

  transition:
    transform .3s ease,
    background .3s ease,
    border-color .3s ease,
    box-shadow .3s ease;
}


/* ==================================================
   LOGO
================================================== */

.f1-titulo-logo{
  width:34px;
  height:34px;

  object-fit:contain;

  flex-shrink:0;

  filter:
    drop-shadow(
      0 4px 7px rgba(0,0,0,.6)
    );

  transition:
    transform .35s ease,
    filter .35s ease;
}


/* ==================================================
   ANO
================================================== */

.f1-titulo-ano{
  font-size:15px;

  font-weight:900;

  color:#fff;

  white-space:nowrap;

  transition:
    color .3s ease;
}


/* ==================================================
   EQUIPE
================================================== */

.f1-titulo-equipe{
  font-size:17px;

  font-weight:700;

  color:rgba(255,255,255,.65);

  white-space:nowrap;

  overflow:hidden;

  text-overflow:ellipsis;

  transition:
    color .3s ease;
}


/* ==================================================
   LINHA LATERAL
================================================== */

.f1-titulo-item::before{
  content:"";

  position:absolute;

  left:0;
  top:50%;

  width:3px;
  height:0;

  border-radius:10px;

  background:#909091;

  transform:
    translateY(-50%);

  transition:
    height .3s ease;
}


/* ==================================================
   HOVER DO TÍTULO
================================================== */

.f1-titulo-item:hover{
  transform:
    translateX(5px);

  background:
    rgba(255,228,250,.09);

  border-color:
    rgba(255,248,255,.3);

  box-shadow:
    0 8px 25px rgba(0,0,0,.35),
    0 0 20px rgba(255,248,250,.08);

  z-index:10;
}


.f1-titulo-item:hover::before{
  height:70%;
}


.f1-titulo-item:hover .f1-titulo-logo{
  transform:
    scale(1.18);

  filter:
    drop-shadow(
      0 0 10px rgba(255,248,250,.5)
    );
}


.f1-titulo-item:hover .f1-titulo-ano{
  color:#909091;
}


.f1-titulo-item:hover .f1-titulo-equipe{
  color:#fff;
}


/* ==================================================
   MINI CARD
================================================== */

.f1-titulo-card{
  position:fixed;

  left:50%;

  bottom:35px;

  width:390px;

  max-width:
    calc(100vw - 30px);

  padding:22px;

  box-sizing:border-box;

  border-radius:18px;

  background:
    linear-gradient(
      145deg,
      rgba(20,20,20,.97),
      rgba(5,5,5,.97)
    );

  border:
    1px solid rgba(255,255,250,.35);

  box-shadow:
    0 20px 60px rgba(0,0,0,.65),
    0 0 30px rgba(255,248,250,.1);

  backdrop-filter:blur(18px);

  opacity:0;

  visibility:hidden;

  pointer-events:none;

  transform:
    translate(-50%,20px)
    scale(.96);

  transition:
    opacity .3s ease,
    transform .3s ease,
    visibility .3s ease;

  z-index:9999;
}


/*
  Classe que o JavaScript vai adicionar
  quando um título estiver selecionado.
*/

.f1-titulo-card.mostrar{
  opacity:1;

  visibility:visible;

  transform:
    translate(-50%,0)
    scale(1);
}


/* ==================================================
   CABEÇALHO DO CARD
================================================== */

.f1-titulo-card-header{
  display:flex;

  align-items:center;

  gap:14px;

  padding-bottom:16px;

  margin-bottom:16px;

  border-bottom:
    1px solid rgba(255,255,255,.08);
}


.f1-titulo-card-logo{
  width:55px;
  height:55px;

  object-fit:contain;

  filter:
    drop-shadow(
      0 5px 10px rgba(0,0,0,.6)
    );
}


.f1-titulo-card-ano{
  display:block;

  color:#ffb347;

  font-size:13px;

  font-weight:800;

  letter-spacing:2px;
}


.f1-titulo-card-equipe{
  margin:3px 0 0;

  color:#fff;

  font-size:25px;

  font-weight:900;
}


/* ==================================================
   PILOTOS
================================================== */

.f1-titulo-card-pilotos{
  display:flex;

  flex-direction:column;

  gap:6px;

  margin-bottom:20px;
}


.f1-titulo-card-piloto{
  color:#fff;

  font-size:14px;

  font-weight:700;
}


/* ==================================================
   ESTATÍSTICAS
================================================== */

.f1-titulo-card-estatisticas{
  display:grid;

  grid-template-columns:
    repeat(4,1fr);

  gap:8px;
}


.f1-titulo-stat{
  display:flex;

  flex-direction:column;

  align-items:center;

  justify-content:center;

  min-height:65px;

  padding:8px;

  box-sizing:border-box;

  border-radius:9px;

  background:
    rgba(255,255,255,.045);

  border:
    1px solid rgba(255,255,255,.06);
}


.f1-titulo-stat strong{
  color:#fff;

  font-size:19px;

  font-weight:900;
}


.f1-titulo-stat span{
  margin-top:3px;

  color:rgba(255,255,255,.45);

  font-size:8px;

  font-weight:800;

  letter-spacing:1px;
}


/* ==================================================
   CONTADOR
================================================== */

.f1-titulos-contador{
  display:flex;

  align-items:baseline;

  justify-content:center;

  gap:10px;

  margin-top:35px;

  color:rgba(255,255,255,.5);

  font-size:11px;

  font-weight:800;

  letter-spacing:2px;
}


.f1-titulos-contador strong{
  color:rgba(255,255,255,.5);

  font-size:28px;

  font-weight:900;

  letter-spacing:0;
}


/* ==================================================
   RESPONSIVO
================================================== */

@media(max-width:900px){

  .f1-titulos-construtores{
    padding:
      80px 15px;
  }


  .f1-titulos-header{
    margin-bottom:40px;
  }


  .f1-titulos-grade{
    grid-template-rows:
      repeat(10,auto);

    grid-auto-columns:
      minmax(175px,1fr);

    gap:8px 10px;

    padding:15px;

    border-radius:18px;
  }


  .f1-titulo-item{
    min-height:48px;

    padding:6px 9px;

    gap:8px;
  }


  .f1-titulo-logo{
    width:29px;
    height:29px;
  }


  .f1-titulo-ano{
    font-size:13px;
  }


  .f1-titulo-equipe{
    font-size:11px;
  }


  .f1-titulo-card{
    width:
      calc(100vw - 30px);

    bottom:15px;

    padding:18px;
  }

}


@media(max-width:600px){

  .f1-titulos-titulo{
    font-size:2.4rem;

    letter-spacing:-1px;
  }


  .f1-titulos-subtitulo{
    font-size:.9rem;
  }


  .f1-titulos-grade{
    /*
      No celular a grade vira
      uma sequência horizontal
      rolável para não esmagar
      os títulos.
    */

    grid-template-rows:
      repeat(8,auto);

    grid-auto-columns:
      170px;

    max-height:600px;

    overflow-x:auto;
    overflow-y:hidden;
  }


  .f1-titulo-card-estatisticas{
    grid-template-columns:
      repeat(2,1fr);
  }


  .f1-titulo-card-equipe{
    font-size:22px;
  }

}


/* ==================================================
   REDUÇÃO DE MOVIMENTO
================================================== */

@media(prefers-reduced-motion:reduce){

  .f1-titulo-item,
  .f1-titulo-logo,
  .f1-titulo-card{
    transition:none;
  }

}


