/* =========================================================
   MINI CARD
========================================================= */

/*
   IMPORTANTE:

   Não usamos mais:
       left:50%;
       bottom:30px;

   O JS agora define:
       card.style.left
       card.style.top

   Assim o card pode aparecer próximo
   do ano selecionado.
*/

.f1-campeao-piloto-card{

    position:fixed;

    width:390px;

    max-width:
        calc(100vw - 30px);

    box-sizing:border-box;

    padding:24px;

    border-radius:20px;

    background:
        linear-gradient(
            145deg,
            rgba(25,25,25,.98),
            rgba(7,7,7,.98)
        );

    border:
        1px solid
        rgba(220,0,0,.35);

    box-shadow:
        0 25px 70px
        rgba(0,0,0,.75),

        0 0 35px
        rgba(220,0,0,.12);

    backdrop-filter:blur(20px);
    -webkit-backdrop-filter:blur(20px);

    opacity:0;

    visibility:hidden;

    pointer-events:none;

    transform:
        translateY(10px)
        scale(.96);

    transition:
        opacity .25s ease,
        transform .25s ease,
        visibility .25s ease;

    z-index:99999;
}


/* =========================================================
   CARD ATIVO
========================================================= */

.f1-campeao-piloto-card.ativo{

    opacity:1;

    visibility:visible;

    pointer-events:auto;

    transform:
        translateY(0)
        scale(1);
}


/* =========================================================
   DIREÇÃO DO MINI CARD
========================================================= */

/* Card abrindo para baixo */
.f1-campeao-piloto.card-para-baixo
.f1-campeao-piloto-card{

    top: var(--card-top);
    bottom: auto;

    left: var(--card-left);

    transform:
        translate(0, 0)
        scale(.96);
}


/* Card aberto para baixo */
.f1-campeao-piloto.card-para-baixo
.f1-campeao-piloto-card.ativo{

    transform:
        translate(0, 0)
        scale(1);
}


/* Card abrindo para cima */
.f1-campeao-piloto.card-para-cima
.f1-campeao-piloto-card{

    top: auto;
    bottom: var(--card-bottom);

    left: var(--card-left);

    transform:
        translate(0, 0)
        scale(.96);
}


/* Card aberto para cima */
.f1-campeao-piloto.card-para-cima
.f1-campeao-piloto-card.ativo{

    transform:
        translate(0, 0)
        scale(1);
}




