/* =========================================================
   BANDEIRA
========================================================= */

.f1-campeao-piloto-card-bandeira{

    margin-left:auto;

    font-size:1.5rem;
}


/* =========================================================
   NOME DO PILOTO
========================================================= */

.f1-campeao-piloto-card-nome{

    margin:
        0 0 12px;

    color:#fff;

    font-size:26px;

    font-weight:900;

    line-height:1.05;

    overflow-wrap:anywhere;
}


/* =========================================================
   EQUIPE
========================================================= */

.f1-campeao-piloto-card-equipe{

    display:flex;

    align-items:center;

    gap:10px;

    min-width:0;

    color:
        rgba(255,255,255,.65);

    font-size:13px;

    font-weight:700;
}


/* =========================================================
   LOGO DA EQUIPE
========================================================= */

.f1-campeao-piloto-card-logo{

    width:42px;
    height:42px;

    flex:0 0 42px;

    object-fit:contain;

    filter:
        drop-shadow(
            0 4px 8px
            rgba(0,0,0,.6)
        );
}


.f1-campeao-piloto-card-equipe span{

    min-width:0;

    overflow:hidden;

    text-overflow:ellipsis;

    white-space:nowrap;
}


/* =========================================================
   LINHA
========================================================= */

.f1-campeao-piloto-card-linha{

    width:100%;

    height:1px;

    margin:18px 0;

    background:
        rgba(255,255,255,.09);
}


/* =========================================================
   ESTATÍSTICAS
========================================================= */

.f1-campeao-piloto-estatisticas{

    display:grid;

    grid-template-columns:
        repeat(2,1fr);

    gap:8px;
}


.f1-campeao-piloto-estatistica{

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:center;

    min-height:65px;

    padding:8px;

    box-sizing:border-box;

    border-radius:9px;

    background:
        rgba(255,255,255,.045);

    border:
        1px solid
        rgba(255,255,255,.06);

    text-align:center;
}


.f1-campeao-piloto-estatistica > span{

    font-size:1.05rem;
}


.f1-campeao-piloto-estatistica small{

    display:block;

    margin-top:4px;

    color:
        rgba(255,255,255,.45);

    font-size:8px;

    font-weight:800;

    letter-spacing:1px;
}


.f1-campeao-piloto-estatistica strong{

    display:block;

    margin-top:2px;

    color:#fff;

    font-size:18px;

    font-weight:900;
}


/* =========================================================
   FOOTER
========================================================= */

.f1-campeao-piloto-card-footer{

    margin-top:18px;

    padding-top:14px;

    border-top:
        1px solid
        rgba(255,255,255,.08);

    text-align:center;
}


.f1-campeao-piloto-card-footer span{

    color:#fff;

    font-size:13px;

    font-weight:900;

    letter-spacing:2px;
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width:900px){

    .f1-campeoes-pilotos{

        height:auto;

        min-height:100dvh;

        padding:
            40px
            15px
            20px;

        overflow:visible;
    }


    .f1-campeoes-pilotos-header{

        margin-bottom:20px;
    }


    .f1-campeoes-pilotos-titulo{

        font-size:
