/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width:600px){

    .f1-campeoes-pilotos{

        width:100%;

        height:auto;

        min-height:100dvh;

        padding:
            30px
            8px
            20px;

        box-sizing:border-box;

        overflow:visible;
    }


    /* =====================================================
       CABEÇALHO
    ===================================================== */

    .f1-campeoes-pilotos-header{

        width:100%;

        margin:
            0 auto 15px;

        text-align:center;
    }


    .f1-campeoes-pilotos-kicker{

        font-size:8px;

        letter-spacing:2px;

        margin-bottom:7px;
    }


    .f1-campeoes-pilotos-titulo{

        font-size:2rem;

        line-height:1;

        letter-spacing:-1px;
    }


    .f1-campeoes-pilotos-subtitulo{

        display:none;
    }


    /* =====================================================
       LISTA
    ===================================================== */

    .f1-campeoes-pilotos-timeline{

        display:grid;

        grid-template-columns:1fr;

        grid-template-rows:none;

        grid-auto-flow:row;

        grid-auto-columns:auto;

        gap:5px;

        width:100%;

        padding:8px;

        margin:0;

        box-sizing:border-box;

        overflow:visible;
    }


    /* =====================================================
       ITEM
    ===================================================== */

    .f1-campeao-piloto{

        width:100%;

        min-width:0;

        min-height:0;
    }


    /* =====================================================
       CONTEÚDO
    ===================================================== */

    .f1-campeao-piloto-conteudo{

        display:flex;

        align-items:center;

        width:100%;

        min-width:0;

        min-height:38px;

        padding:
            7px
            8px;

        gap:7px;

        box-sizing:border-box;
    }


    /* =====================================================
       ANO
    ===================================================== */

    .f1-campeao-piloto-ano{

        flex-shrink:0;

        min-width:40px;

        font-size:10px;

        white-space:nowrap;
    }


    /* =====================================================
       NOME
    ===================================================== */

    .f1-campeao-piloto-nome{

        min-width:0;

        font-size:9px;

        white-space:nowrap;

        overflow:hidden;

        text-overflow:ellipsis;
    }


    /* =====================================================
       CARD MOBILE
    ===================================================== */

    /*
       Não usamos top:50%, left:12px ou right:12px.

       O JavaScript posiciona o card próximo
       do item selecionado.
    */

    .f1-campeao-piloto-card{

        width:
            calc(100vw - 24px);

        max-width:
            calc(100vw - 24px);

        max-height:
            calc(100dvh - 24px);

        padding:20px;

        border-radius:18px;

        overflow-y:auto;

        overflow-x:hidden;

        box-sizing:border-box;
    }


    /* =====================================================
       BOTÃO
    ===================================================== */

    .f1-campeao-piloto-card-fechar{

        top:9px;

        right:9px;

        width:30px;

        height:30px;

        font-size:20px;
    }


    /* =====================================================
       CABEÇALHO CARD
    ===================================================== */

    .f1-campeao-piloto-card-header{

        padding-right:38px;

        margin-bottom:14px;
    }


    /* =====================================================
       NOME CARD
    ===================================================== */

    .f1-campeao-piloto-card-nome{

        font-size:22px;
    }


    /* =====================================================
       LOGO
    ===================================================== */

    .f1-campeao-piloto-card-logo{

        width:38px;

        height:38px;

        flex-basis:38px;
    }


    /* =====================================================
       ESTATÍSTICAS
    ===================================================== */

    .f1-campeao-piloto-estatisticas{

        gap:6px;
    }


    .f1-campeao-piloto-estatistica{

        min-height:54px;

        padding:6px;
    }


    .f1-campeao-piloto-estatistica > span{

        font-size:16px;
    }


    .f1-campeao-piloto-estatistica strong{

        font-size:15px;
    }


    /* =====================================================
       FOOTER
    ===================================================== */

    .f1-campeao-piloto-card-footer{

        margin-top:18px;

        padding-top:14px;
    }


    /* =====================================================
       SEGURANÇA CONTRA ESTOURO
    ===================================================== */

    .f1-campeao-piloto-card,
    .f1-campeao-piloto-card-header,
    .f1-campeao-piloto-card-equipe,
    .f1-campeao-piloto-estatisticas{

        max-width:100%;

        box-sizing:border-box;
    }

    .f1-campeao-piloto-card{

        position: fixed;

        width:390px;

        max-width:
            calc(100vw - 30px);

        box-sizing:border-box;

        padding:24px;

        opacity:0;
        visibility:hidden;

        pointer-events:none;

        transition:
            opacity .25s ease,
            transform .25s ease,
            visibility .25s ease;

        z-index:99999;
    }


    /*
       Quando o JS calcula a posição,
       o hover também pode abrir o card.
    */

    .f1-campeao-piloto:hover
    .f1-campeao-piloto-card{

        opacity:1;

        visibility:visible;

        pointer-events:auto;
    }

}



/* =========================================================
   GENEALOGIA F1
========================================================= */

.f1-genealogia {

    width: 100%;
    height: 100vh;

    min-height: 600px;

    box-sizing: border-box;

    padding: 25px 30px;

    overflow: hidden;

    color: #fff;

    font-family:
        Arial,
        Helvetica,
        sans-serif;

    background:

        radial-gradient(
            circle at 15% 15%,
            rgba(0,0, 2, .18),
            transparent 30%
        ),

        radial-gradient(
            circle at 85% 85%,
            rgba(0, 0, 0, .12),
            transparent 35%
        ),

        linear-gradient(
            135deg,
            #061416,
            #061312 50%,
            #030c18
        );

    display: flex;

    flex-direction: column;

}


/* =========================================================
   CABEÇALHO
========================================================= */

.f1-header {

    flex-shrink: 0;

    text-align: center;

    margin-bottom: 18px;

}


.f1-kicker {

    display: block;

    margin-bottom: 5px;

    color: #42b8ff;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 3px;

    text-transform: uppercase;

}


.f1-header h2 {

    margin: 0;

    font-size: clamp(
        26px,
        3vw,
        42px
    );

    line-height: 1;

    font-weight: 950;

    text-transform: uppercase;

}


.f1-header p {

    max-width: 650px;

    margin: 8px auto 0;

    color:
        rgba(255,255,255,.58);

    font-size: 11px;

    line-height: 1.4;

}


/* =========================================================
   TIMELINE
========================================================= */

.f1-timeline {

    width: 100%;

    max-width: 1450px;

    margin: 0 auto;

    flex: 1;

    min-height: 0;

    box-sizing: border-box;

    padding: 12px 15px;

    overflow: hidden;

    border-radius: 15px;

    background:
        rgba(1,9,18,.55);

    border:
        1px solid
        rgba(255,255,255,.09);

    box-shadow:
        0 20px 55px
        rgba(0,0,0,.35);

}


/* =========================================================
   ESCALA DE ANOS
========================================================= */

.f1-years {

    width: 100%;

    height: 30px;

    display: grid;

    grid-template-columns:
        repeat(9, 1fr);

    align-items: start;

    border-bottom:
        1px solid
        rgba(255,255,255,.13);

}


.f1-years span {

    position: relative;

    height: 30px;

    text-align: center;

    color:
        rgba(255,255,255,.45);

    font-size: 18px;

    font-weight: 900;

    line-height: 15px;

}


.f1-years span::after {

    content: "";

    position: absolute;

    left: 50%;

    top: 17px;

    width: 1px;

    height: 13px;

    background:
        rgba(255,255,255,.18);

}


/* =========================================================
   CONTAINER DAS LINHAS
========================================================= */

.f1-lines {

    width: 100%;

    height: calc(100% - 30px);

    display: flex;

    flex-direction: column;

    justify-content: space-evenly;

    overflow: hidden;

}


/* =========================================================
   LINHA
========================================================= */

.f1-line {

    width: 100%;

    min-height: 38px;

    flex: 1;

    max-height: 58px;

    display: grid;

    grid-template-columns:
        145px minmax(0, 1fr);

    align-items: center;

    border-bottom:
        1px solid
        rgba(255,255,255,.035);

}


.f1-line:last-child {

    border-bottom: none;

}


/* =========================================================
   NOME DA LINHAGEM
========================================================= */

.f1-line-name {

    height: 100%;

    display: flex;

    align-items: center;

    padding: 0 10px;

    box-sizing: border-box;

    color:
        rgba(255,255,255,.72);

    font-size: 15px;

    font-weight: 900;

    text-transform: uppercase;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;

}


/* =========================================================
   ÁREA DAS EQUIPES
========================================================= */

.f1-track {

    position: relative;

    width: 100%;

    height: 100%;

    min-width: 0;

    display: flex;

    align-items: center;

    gap: 4px;

}


/* =========================================================
   LINHA CENTRAL
========================================================= */

.f1-track::before {

    content: "";

    position: absolute;

    left: 0;

    right: 0;

    top: 50%;

    height: 1px;

    background:
        rgba(255,255,255,.12);

    transform:
        translateY(-50%);

    pointer-events: none;

}


/* =========================================================
   EQUIPE
========================================================= */

.f1-team {

    position: relative;

    z-index: 2;

    flex: 1 1 0;

    min-width: 0;

    height: 34px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 6px;

    padding: 0 7px;

    box-sizing: border-box;

    border-radius: 7px;

    background:
        var(--team-color);

    border:
        1px solid
        rgba(255,255,255,.22);

    box-shadow:
        0 4px 12px
        rgba(0,0,0,.3);

    cursor: pointer;

    overflow: hidden;

    transition:
        transform .18s ease,
        filter .18s ease,
        box-shadow .18s ease;

}


/* =========================================================
   HOVER
========================================================= */

.f1-team:hover {

    transform:
        scale(1.035);

    filter:
        brightness(1.12);

    box-shadow:

        0 7px 18px
        rgba(0,0,0,.45),

        0 0 15px
        rgba(70,190,255,.18);

    z-index: 10;

}


/* =========================================================
   LOGO
========================================================= */

.f1-team img {

    width: 50px;

    height: 50px;

    min-width: 50px;

    object-fit: contain;

    display: block;

    filter:
        drop-shadow(
            0 1px 3px
            rgba(0,0,0,.75)
        );

}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.f1-team span {

    min-width: 0;

    color: #fff;

    font-size: 16px;

    font-weight: 900;

    line-height: 1;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;

    text-shadow:
        0 1px 3px
        rgba(0,0,0,.85);

}

.f1-team.light-team span {
    color: #111;
    
    text-shadow: none;
}


/* =========================================================
   CARD
========================================================= */

.f1-card-linha {

    position: fixed;

    left: 50%;

    bottom: 18px;

    width: 340px;

    max-width:
        calc(100vw - 30px);

    box-sizing: border-box;

    padding: 16px;

    display: flex;

    align-items: center;

    gap: 12px;

    border-radius: 14px;

    background:

        linear-gradient(
            145deg,
            rgba(10,30,48,.98),
            rgba(2,9,17,.98)
        );

    border:
        1px solid
        rgba(60,180,255,.25);

    box-shadow:
        0 20px 60px
        rgba(0,0,0,.65);

    backdrop-filter:
        blur(14px);

    opacity: 0;

    visibility: hidden;

    pointer-events: none;

    transform:
        translate(-50%, 15px)
        scale(.96);

    transition:
        opacity .2s ease,
        transform .2s ease,
        visibility .2s ease;

    z-index: 9999;

}


.f1-card-linha.show {

    opacity: 1;

    visibility: visible;

    pointer-events: auto;

    transform:
        translate(-50%, 0)
        scale(1);

}


/* =========================================================
   FECHAR CARD
========================================================= */

.f1-card-linha-close {

    position: absolute;

    top: 7px;

    right: 7px;

    width: 26px;

    height: 26px;

    border: none;

    border-radius: 50%;

    background:
        rgba(255,255,255,.08);

    color: #fff;

    font-size: 18px;

    cursor: pointer;

}


.f1-card-linha-close:hover {

    background:
        rgba(255,255,255,.16);

}


/* =========================================================
   LOGO CARD
========================================================= */

#f1-card-linha-logo {

    width: 48px;

    height: 48px;

    min-width: 48px;

    object-fit: contain;

}


/* =========================================================
   CONTEÚDO CARD
========================================================= */

.f1-card-linha-content {

    min-width: 0;

}


#f1-card-linha-period {

    display: block;

    margin-bottom: 3px;

    color: #39aaff;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 1px;

}


#f1-card-linha-name {

    margin: 0 0 4px;

    font-size: 19px;

    font-weight: 900;

}


#f1-card-linha-lineage {

    margin: 0;

    color:
        rgba(255,255,255,.55);

    font-size: 9px;

    line-height: 1.3;

}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 900px) {

    .f1-genealogia {

        padding: 18px 12px;

    }


    .f1-header {

        margin-bottom: 12px;

    }


    .f1-header h2 {

        font-size: 28px;

    }


    .f1-line {

        grid-template-columns:
            110px minmax(0, 1fr);

    }


    .f1-line-name {

        padding: 0 5px;

        font-size: 7px;

    }


    .f1-team {

        height: 31px;

        gap: 4px;

        padding: 0 5px;

    }


    .f1-team img {

        width: 19px;

        height: 19px;

        min-width: 19px;

    }


    .f1-team span {

        font-size: 7px;

    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 600px) {

    .f1-genealogia {

        min-height: 520px;

        padding: 12px 6px;

    }


    .f1-kicker {

        font-size: 7px;

        letter-spacing: 2px;

    }


    .f1-header h2 {

        font-size: 22px;

    }


    .f1-header p {

        display: none;

    }


    .f1-timeline {

        padding: 6px;

        border-radius: 9px;

    }


    .f1-years {

        height: 25px;

    }


    .f1-years span {

        height: 25px;

        font-size: 6px;

        line-height: 12px;

    }


    .f1-years span::after {

        top: 14px;

        height: 9px;

    }


    .f1-lines {

        height:
            calc(100% - 25px);

    }


    .f1-line {

        grid-template-columns:
            78px minmax(0, 1fr);

        min-height: 32px;

    }


    .f1-line-name {

        padding: 0 3px;

        font-size: 5px;

    }


    .f1-track {

        gap: 2px;

    }


    .f1-team {

        height: 26px;

        padding: 0 3px;

        gap: 2px;

        border-radius: 5px;

    }


    .f1-team img {

        width: 16px;

        height: 16px;

        min-width: 16px;

    }


    .f1-team span {

        font-size: 5px;

    }


    .f1-card-linha {

        width: 300px;

        padding: 13px;

    }


    #f1-card-linha-logo {

        width: 40px;

        height: 40px;

        min-width: 40px;

    }


    #f1-card-linha-name {

        font-size: 16px;

    }

}


/* =========================================================
   TELAS COM POUCA ALTURA
========================================================= */

@media (max-height: 700px) {

    .f1-genealogia {

        padding-top: 10px;

        padding-bottom: 10px;

    }


    .f1-header {

        margin-bottom: 7px;

    }


    .f1-header p {

        display: none;

    }


    .f1-header h2 {

        font-size: 25px;

    }


    .f1-team {

        height: 29px;

    }

}


/* =========================================================
   ACESSIBILIDADE
========================================================= */

.f1-team:focus-visible,
.f1-card-linha-close:focus-visible {

    outline:
        2px solid #42b8ff;

    outline-offset: 2px;

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .f1-team,
    .f1-card-linha {

        transition: none;

    }

}


/* =========================================================
   MAIORES CAMPEÕES DA FÓRMULA 1
   CSS — SEM VARIÁVEIS
========================================================= */


/* =========================================================
   SEÇÃO PRINCIPAL
========================================================= */

.f1-maiores-campeoes-section {

    width: 100%;

    padding: 90px 5% 70px;

    background:
        radial-gradient(
            circle at 50% 0%,
            rgba(255, 135, 0, 0.08),
            transparent 35%
        ),
        #050505;

    color: #ffffff;

    box-sizing: border-box;

    overflow: hidden;

    font-family:
        Arial,
        Helvetica,
        sans-serif;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.f1-maiores-campeoes-header {

    max-width: 900px;

    margin: 0 auto 60px;

    text-align: center;
}


.f1-maiores-campeoes-kicker {

    display: inline-block;

    margin-bottom: 10px;

