    color: #ffffff;

    font-size: 22px;

    font-weight: 800;
}


/* =========================================================
   CARD BASE
========================================================= */

.f1-campeao-card {

    position: relative;

    isolation: isolate;

    overflow: hidden;

    background: #151515;

    border: 1px solid rgba(255, 255, 255, 0.08);

    cursor: pointer;

    box-sizing: border-box;

    transition:
        transform 0.45s ease,
        border-color 0.45s ease,
        box-shadow 0.45s ease,
        opacity 0.45s ease,
        filter 0.45s ease;
}


.f1-campeao-card:hover {

    transform: translateY(-8px);

    border-color: rgba(255, 1, 0, 0.7);

    box-shadow:
        0 20px 50px
        rgba(0, 0, 0, 0.55);
}


.f1-campeao-card:focus {

    outline: 2px solid #dc0000;

    outline-offset: 4px;
}


/* =========================================================
   IMAGEM
========================================================= */

.f1-campeao-card-imagem {

    position: absolute;

    inset: 0;

    z-index: -2;
}


.f1-campeao-card-imagem img {

    width: 100%;

    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center top;

    transition:
        transform 0.7s ease,
        filter 0.7s ease;
}


.f1-campeao-card:hover
.f1-campeao-card-imagem img {

    transform: scale(1.06);
}


/* =========================================================
   CARDS COM IMG DIRETO
========================================================= */

.f1-campeao-card > img {

    position: absolute;

    inset: 0;

    z-index: -2;

    width: 100%;

    height: 100%;

    object-fit: cover;

    object-position: center top;

    transition:
        transform 0.7s ease,
        filter 0.7s ease;
}


.f1-campeao-card:hover > img {

    transform: scale(1.06);
}


/* =========================================================
   OVERLAY
========================================================= */
.f1-campeao-card-overlay {

    position: absolute;

    inset: 0;

    z-index: -1;

    background:
        linear-gradient(
            to top,
            rgba(0, 0, 0, 0.98) 0%,
            rgba(0, 0, 0, 0.82) 30%,
            rgba(0, 0, 0, 0.35) 65%,
            rgba(0, 0, 0, 0.05) 100%
        );

    transition:
        background 0.45s ease;
}


.f1-campeao-card:hover
.f1-campeao-card-overlay {

    background:
        linear-gradient(
            to top,
            rgba(0, 0, 0, 0.98) 0%,
            rgba(0, 0, 0, 0.75) 40%,
            rgba(255, 135, 0, 0.08) 100%
