/*============================================/////////////==////=///=

mclaren

=========================================*/

body.mclaren {
  background: #ff8000;
}






/* =========================================================
   MCLAREN HERO
========================================================= */

.mclaren-hero {
    position: relative;
    width: 100%;
    height: 100dvh;
    min-height: 620px;
    overflow: hidden;
    background: #020713;
    color: #fff;
    isolation: isolate;
}


/* =========================================================
   CARRO — FUNDO PRINCIPAL
========================================================= */

.mclaren-car-bg {
    position: absolute;
    inset: -5%;
    z-index: -5;

    background-image:
        url("carros/mcl40.jpg");

    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;

    filter:
        brightness(.58)
        contrast(1.08)
        saturate(1.12);

    transform: scale(1.04);

    transition:
        transform 1s ease,
        filter 1s ease;
}


/* LEVE MOVIMENTO */

.mclaren-hero:hover .mclaren-car-bg {
    transform: scale(1.07);

    filter:
        brightness(.63)
        contrast(1.1)
        saturate(1.15);
}


/* =========================================================
   OVERLAY
========================================================= */

.mclaren-overlay {
    position: absolute;
    inset: 0;
    z-index: -4;

    background:

        /* AZUL */
        linear-gradient(
            115deg,
            rgba(255,128,0,.78),
            transparent 42%
        ),

        /* VERMELHO */
        linear-gradient(
            250deg,
            rgba(2,2,2,.32),
            transparent 42%
        ),

        /* ESCURECIMENTO */
        linear-gradient(
            to bottom,
            rgba(0,0,0,.55),
            transparent 25%,
            rgba(0,0,0,.08) 55%,
            rgba(0,0,0,.82) 100%
        );
}


/* =========================================================
   TOPO
========================================================= */

.mclaren-top {
    position: absolute;

    top: 25px;
    left: 4vw;
    right: 4vw;

    z-index: 30;

    display: flex;
    align-items: center;
    justify-content: space-between;
}


/* =========================================================
   HOME
========================================================= */

.mclaren-home {
    display: flex;
    align-items: center;

    gap: 8px;

    padding: 9px 13px;

    text-decoration: none;

    color: rgba(255,255,255,.75);

    border: 1px solid rgba(255,255,255,.2);

    background: rgba(0,0,0,.3);

    backdrop-filter: blur(10px);

    font-size: 25px;
    font-weight: 900;
    letter-spacing: 2px;

    transition: .35s ease;
}

.mclaren-home i {
    font-size: 20px;
}

.mclaren-home:hover {
    color: #fff;

    background: rgba(255,128,0,.22);

    border-color: #ff8000;

    transform: translateY(-3px);
}


/* =========================================================
   STATUS
========================================================= */

.mclaren-status {
    position: absolute;

    left: 50%;

    transform: translateX(-50%);

    font-size: 15px;
    font-weight: 900;
    letter-spacing: 4px;

    color: rgba(255,255,255,.55);
}


/* =========================================================
   RED BULL — REDES SOCIAIS INFERIORES
========================================================= */

.mclaren-social-top {
    position: absolute;

    z-index: 30;

    left: 50%;
    bottom:110px;

    transform: translateX(-13%);

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 7px;
}


/* =========================================================
   ÍCONES
========================================================= */

.mclaren-social-top a {
    width: 100px;
    height: 100px;

    display: flex;
    align-items: center;
    justify-content: center;

    text-decoration: none;

    color: rgba(255,255,255,.65);

    border: 1px solid rgba(255,255,255,.16);

    background:
        linear-gradient(
            135deg,
            rgba(10,15,30,.78),
            rgba(0,0,0,.45)
        );

    backdrop-filter: blur(8px);

    font-size: 30px;

    transition:
        transform .35s ease,
        color .35s ease,
        background .35s ease,
        border-color .35s ease,
        box-shadow .35s ease;
}


/* =========================================================
   HOVER
========================================================= */

.mclaren-social-top a:hover {
    color: #fff;

    background:#Ff8000;

    border-color:#333333 ;

    transform:
        translateY(-5px)
        scale(1.08);

    box-shadow:
        0 8px 22px rgba(2,2,2,.35),
        0 0 15px rgba(2,2,2,.15);
}


/* =========================================================
   LINHA DECORATIVA
========================================================= */

.mclaren-social-top::before,
.mclaren-social-top::after {
    content: "";

    width: 55px;
    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(2,2,2,.7)
        );
}


.mclaren-social-top::after {
    background:
        linear-gradient(
            90deg,
            rgba(2,2,2,.7),
            transparent
        );
}


/* =========================================================
   LOGO RED BULL
========================================================= */

.mclaren-logo {
    position: absolute;

    z-index: 8;

    right: 4vw;
    top: -50px;

    width: 400px;
    height: 400px;

    display: flex;
    align-items: center;
    justify-content: center;

    pointer-events: none;

    animation: mclaren-logo-float 4s ease-in-out infinite;
}


/* LOGO */

.mclaren-logo img {
    position: relative;

    z-index: 2;

    width: 100%;
    height: 100%;

    object-fit: contain;

    display: block;

    filter: drop-shadow(0 5px 15px rgba(0,0,0,.6));
}


/* =========================================================
   ANIMAÇÃO DA LOGO
========================================================= */

@keyframes mclaren-logo-float {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-7px);
    }

}


/* =========================================================
   GLOW DA LOGO
========================================================= */

.mclaren-logo-glow {
    position: absolute;

    z-index: 1;

    width: 220px;
    height: 220px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255,128,0,.3),
            rgba(255,128,0,.15),
            transparent 70%
        );

    filter: blur(20px);

    animation: mclaren-logo-glow 4s ease-in-out infinite;
}


/* =========================================================
   ANIMAÇÃO DO GLOW
========================================================= */

@keyframes mclaren-logo-glow {

    0%,
    100% {
        transform: scale(.9);
        opacity: .55;
    }

    50% {
        transform: scale(1.15);
        opacity: 1;
    }

}

/* =========================================================
   NOME DA EQUIPE
========================================================= */

.mclaren-main {
    position: absolute;

    z-index: 20;

    left: 7vw;
    top: 28%;

    max-width: 520px;
}

.mclaren-kicker {
    font-size: 25px;
	  letter-spacing:3px;
    font-weight: 900;
    color: #222222;
}

.mclaren-main h1 {
    margin: 8px 0 4px;
    color:#Ff8000;
	font-size:
        clamp(45px,6vw,92px);

    line-height: .82;

    font-weight: 900;

    letter-spacing: -5px;

    text-shadow:
        0 8px 30px rgba(0,0,0,.8);
}

.mclaren-main h1 strong {
    display: block;

    font-weight: 300;

    color: #fff;

    letter-spacing: -3px;
}

.mclaren-full-name {
    margin: 14px 0 0;

    font-size: 18px;

    font-weight: 900;

    letter-spacing: 4px;

    color: rgba(255,255,255,.5);
}

/* =========================================================
   RODAPÉ
========================================================= */

.mclaren-bottom {
    position: absolute;

    z-index: 25;

    left: 4vw;
    right: 4vw;

    bottom: 82px;

    display: flex;

    align-items: center;

    gap: 15px;

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 3px;

    color: rgba(255,255,255,.53);
}

.mclaren-bottom div {
    flex: 1;

    height: 2px;

    background:
        linear-gradient(
            90deg,
            rgba(2,2,2,.8),
            rgba(255,128,0,.5)
            
        );
}


/* =========================================================
   RED BULL — PULSOS LUMINOSOS
========================================================= */

.mclaren-pulsos {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 3;
    pointer-events: none;
}

/* PONTO */

.mclaren-pulsos span {
    position: absolute;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    opacity: 0;

    animation:
        mclarenPulso
        var(--tempo)
        ease-in-out
        var(--atraso)
        infinite;
}


/* =========================================================
   CORES RED BULL
========================================================= */

.mclaren-pulsos span:nth-child(3n + 1) {
    background: #Ff8000;

    box-shadow:
        0 0 5px #Ff8000,
        0 0 12px rgba(255,128,0,.9),
        0 0 25px rgba(255,128,0,.5);
}


.mclaren-pulsos span:nth-child(3n + 2) {
    background: #222222;

    box-shadow:
        0 0 5px #222222,
        0 0 12px rgba(2,2,2,.9),
        0 0 25px rgba(2,2,2,.5);
}


.mclaren-pulsos span:nth-child(3n) {
    background: #ff8000;

    box-shadow:
        0 0 5px #333333,
        0 0 12px rgba(3,3,3 ,.9),
        0 0 25px rgba(3,3,3 ,.5);
}


