========================================================= */


/* =========================================================
   TABLET / TELAS MÉDIAS
========================================================= */

@media (max-width:1000px) {

    /* =========================
       BANNER
    ========================= */

    .mclaren-hero {
        min-height:620px;
    }


    /* =========================
       TOPO DO BANNER
    ========================= */

    .mclaren-top {
        top:20px;
        left:3vw;
        right:3vw;
    }

    .mclaren-home {
        padding:8px 11px;
        font-size:18px;
        letter-spacing:1.5px;
    }

    .mclaren-home i {
        font-size:17px;
    }

    .mclaren-status {
        font-size:12px;
        letter-spacing:3px;
    }


    /* =========================
       LOGO RED BULL
    ========================= */

    .mclaren-logo {
        right:2vw;
        top:-35px;
        width:220px;
        height:220px;
    }

    .mclaren-logo-glow {
        width:165px;
        height:165px;
    }


    /* =========================
       TÍTULO PRINCIPAL
    ========================= */

    .mclaren-main {
        left:5vw;
        top:30%;
        max-width:430px;
    }

    .mclaren-kicker {
        font-size:14px;
        letter-spacing:4px;
    }

    .mclaren-main h1 {
        font-size:clamp(42px,8vw,72px);
        letter-spacing:-4px;
    }

    .mclaren-full-name {
        font-size:14px;
        letter-spacing:3px;
    }


    /* =========================
       PALMARÈS
    ========================= */

    .mclaren-titles {
        right:3vw;
        top:37%;
        width:260px;
        padding:15px 17px 17px;
    }

    .mclaren-titles-top h3 {
        font-size:18px;
    }

    .mclaren-titles-top h3 strong {
        font-size:12px;
    }

    .mclaren-title-year span {
        font-size:14px;
    }


    /* =========================
       REDES SOCIAIS
    ========================= */

    .mclaren-social-top {
        bottom:105px;
        gap:5px;
        transform:translateX(-13%);
    }

    .mclaren-social-top a {
        width:65px;
        height:65px;
        font-size:22px;
    }

    .mclaren-social-top::before,
    .mclaren-social-top::after {
        width:35px;
    }


    /* =========================
       BOTTOM
    ========================= */

    .mclaren-bottom {
        left:3vw;
        right:3vw;
        bottom:45px;

        font-size:11px;
        letter-spacing:2px;
    }


    /* =========================
       PULSOS
    ========================= */

    .mclaren-pulsos span {
        width:4px;
        height:4px;
    }

}


/* =========================================================
   CELULAR — ATÉ 700px
========================================================= */

@media (max-width:700px) {

    /* =========================
       BANNER
    ========================= */

    .mclaren-hero {
        min-height:620px;
			        height:calc(100dvh - 70px);

    }


    /* =====================================================
       IMAGEM MOBILE
       
       TROQUE mcl40-mobile.jpg PELO NOME DA SUA FOTO
       VERTICAL PARA CELULAR
