/* =========================================================
   PILOTOS McLAREN
========================================================= */

.pilotos-mclaren {

    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 100dvh;

    overflow: hidden;

    box-sizing: border-box;

    padding: 45px 5vw;

    background:
        radial-gradient(
            circle at 50% 100%,
            rgba(255,128,0,.12),
            transparent 35%
        ),
        linear-gradient(
            120deg,
            #050505,
            #0b0b0b,
            #050505
        );

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.pilotos-titulo-mclaren {

    position: relative;

    z-index: 20;

    text-align: center;

    margin-bottom: 25px;
}


.pilotos-titulo-mclaren span {

    display: block;

    color: #ff8000;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 5px;
}


.pilotos-titulo-mclaren h2 {

    margin: 4px 0;

    font-size: clamp(30px, 4vw, 52px);

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotos-titulo-mclaren p {

    margin: 0;

    color: rgba(255,255,255,.62);

    font-size: 18px;
}


/* =========================================================
   ÁREA DOS PILOTOS
========================================================= */

.dupla-pilotos-mclaren {

    position: relative;

    display: grid;

    grid-template-columns: 1fr 1fr;

    height: calc(100% - 125px);

    max-width: 1450px;

    margin: auto;
}


/* =========================================================
   PILOTO
========================================================= */

.piloto-mclaren {

    position: relative;

    display: block;

    height: 100%;

    overflow: hidden;

    text-decoration: none;

    color: white;

    transition:
        transform .5s ease;
}


/* =========================================================
   BRILHO DE FUNDO
========================================================= */

.piloto-mclaren::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: 15%;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255,128,0,.15),
            transparent 68%
        );

    filter: blur(30px);

    opacity: .35;

    transition:
        transform .7s ease,
        opacity .7s ease;

    pointer-events: none;
}


/* =========================================================
   BRILHO NORRIS
========================================================= */

.piloto-norris-mclaren::before {

    left: -220px;
}


/* =========================================================
   BRILHO PIASTRI
========================================================= */

.piloto-piastri-mclaren::before {

    right: -220px;
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.piloto-numero-bg-mclaren {

    position: absolute;

    z-index: 0;

    top: 5%;

    font-size: clamp(200px, 40vw, 400px);

    font-weight: 900;

    line-height: 1;

    color: transparent;

    -webkit-text-stroke:
        1px rgba(255,255,255,.08);

    opacity: .8;

    transition:
        color .7s ease,
        -webkit-text-stroke .7s ease,
        transform .7s ease,
        opacity .7s ease;
}


/* =========================================================
   NÚMERO NORRIS
========================================================= */

.piloto-norris-mclaren
.piloto-numero-bg-mclaren {

    left: 3%;
}


/* =========================================================
   NÚMERO PIASTRI
========================================================= */

.piloto-piastri-mclaren
.piloto-numero-bg-mclaren {

    right: -2%;

    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   FOTO
========================================================= */

.piloto-foto-mclaren {

    position: absolute;

    z-index: 2;

    left: 50%;

    bottom: 0;

    width: 70%;

    height: 90%;

    transform:
        translateX(-50%);

    display: flex;

    align-items: flex-end;

    justify-content: center;

    pointer-events: none;
}


.piloto-foto-mclaren img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center bottom;

    filter:
        grayscale(.35)
        brightness(.65);

    opacity: .72;

    transform:
        translateY(30px)
        scale(.95);

    transition:
        transform .8s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


/* =========================================================
   POSIÇÃO DA FOTO DO PIASTRI
========================================================= */

.piloto-piastri-mclaren
.piloto-foto-mclaren {

    transform:
        translateX(-60%);
}


/* =========================================================
   DADOS DO PILOTO
========================================================= */

.piloto-dados-mclaren {

    position: absolute;

    z-index: 12;

    left: 7%;

    bottom: 9%;

    max-width: 80%;

    transition:
        transform .6s ease;
}


/* =========================================================
   DADOS DO PIASTRI
========================================================= */

.piloto-piastri-mclaren
.piloto-dados-mclaren {

    left: auto;

    right: 7%;

    text-align: right;
}


/* =========================================================
   PAÍS
========================================================= */

.piloto-pais-mclaren {

    display: block;

    margin-bottom: 8px;

    color: #ff8000;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 4px;
}


/* =========================================================
   NOME
========================================================= */

.piloto-dados-mclaren h3 {

    position: relative;

    display: inline-flex;

    flex-direction: column;

    align-items: flex-start;

    margin: 0;

    padding: 6px 14px 8px 0;

    z-index: 13;

    font-size: clamp(28px, 3vw, 42px);

    line-height: .9;

    font-weight: 900;

    text-shadow:
        0 3px 10px rgba(0,0,0,.95),
        0 0 18px rgba(0,0,0,.9);
}


/* =========================================================
   NOME PIASTRI — ALINHAMENTO
========================================================= */

.piloto-piastri-mclaren
.piloto-dados-mclaren h3 {

    align-items: flex-end;

    padding-right: 0;

    padding-left: 14px;
}


/* =========================================================
   FUNDO DE PROTEÇÃO DO NOME
========================================================= */

.piloto-dados-mclaren h3::before {

    content: "";

    position: absolute;

    z-index: -1;

    left: -30px;

    right: -30px;

    top: -10px;

    bottom: -10px;

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.92),
            rgba(0,0,0,.72),
            rgba(0,0,0,.25),
            transparent
        );

    filter: blur(7px);

    opacity: .9;

    pointer-events: none;

    transition:
        opacity .4s ease,
        transform .4s ease;
}


/* =========================================================
   FUNDO DO NOME PIASTRI
========================================================= */

.piloto-piastri-mclaren
.piloto-dados-mclaren h3::before {

    background:
        linear-gradient(
            270deg,
            rgba(0,0,0,.92),
            rgba(0,0,0,.72),
            rgba(0,0,0,.25),
            transparent
        );
}


/* =========================================================
   PRIMEIRO NOME
========================================================= */

.piloto-dados-mclaren h3 {

    color: #fff;
}


/* =========================================================
   SOBRENOME
========================================================= */

.piloto-dados-mclaren h3 strong {

    position: relative;

    display: block;

    color: #fff;

    font-weight: 900;

    transition:
        color .35s ease,
        text-shadow .35s ease;
}


/* =========================================================
   LINHA
========================================================= */

.piloto-linha-mclaren {

    width: 65px;

    height: 2px;

    margin: 15px 0;

    background: #ff8000;

    box-shadow:
        0 0 12px rgba(255,128,0,.7);

    transition:
        width .6s ease;
}


.piloto-piastri-mclaren
.piloto-linha-mclaren {

    margin-left: auto;
}


/* =========================================================
   CATEGORIA
========================================================= */

.piloto-categoria-mclaren {

    color: rgba(255,255,255,.98);

    font-size: 12px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* =========================================================
   AÇÃO
========================================================= */

.piloto-acao-mclaren {

    position: absolute;

    z-index: 14;

    right: 7%;

    bottom: 10%;

    display: flex;

    align-items: center;

    gap: 12px;

    color: rgba(255,255,255,.4);

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    transition:
        color .4s ease,
        transform .5s ease;
}


/* =========================================================
   AÇÃO PIASTRI
========================================================= */

.piloto-piastri-mclaren
.piloto-acao-mclaren {

    right: auto;

    left: 4%;
}


/* =========================================================
   ÍCONE
========================================================= */

.piloto-acao-mclaren strong {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 28px;

    height: 28px;

    border: 1px solid rgba(255,128,0,.3);

    color: #ff8000;

    font-size: 12px;

    transition:
        background .4s ease,
        color .4s ease,
        transform .4s ease;
}



/* =========================================================
   CENTRO McLAREN
========================================================= */

.centro-mclaren {

    position: absolute;

    z-index: 25;

    left: 50%;
    top: 5%;

    bottom: 5%;

    width: 90px;

    transform: translateX(-50%);

    display: flex;

    flex-direction: column;

    align-items: center;

    pointer-events: none;
}


/* =========================================================
   LOGO CENTRAL
========================================================= */

.centro-logo-mclaren {

    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle,
            rgba(5,5,5,.95) 45%,
            rgba(5,5,5,.75) 70%,
            transparent 100%
        );

    flex-shrink: 0;
}


.centro-logo-mclaren img {

    width: 55px;
    height: 55px;

    object-fit: contain;

    opacity: .75;

    filter:
        drop-shadow(
            0 0 8px rgba(255,128,0,.25)
        );

    transition:
        transform .5s ease,
        opacity .5s ease,
        filter .5s ease;
}


/* =========================================================
   LINHA VERTICAL
========================================================= */

.centro-linha-mclaren {

    width: 1px;

    flex: 1;

    min-height: 80px;

    background:
        linear-gradient(
            to bottom,
            rgba(255,128,0,.8),
            rgba(255,128,0,.15),
            transparent
        );

    box-shadow:
        0 0 8px rgba(255,128,0,.25);
}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.centro-nome-mclaren {

    writing-mode: vertical-rl;

    text-orientation: mixed;

    margin-top: 12px;

    color: rgba(255,255,255,.3);

    font-size: 20px;

    font-weight: 800;

    letter-spacing: 4px;

    text-transform: uppercase;

    white-space: nowrap;

    transition:
        color .4s ease,
        text-shadow .4s ease;
}


/* =========================================================
   HOVER NOS PILOTOS
========================================================= */

.dupla-pilotos-mclaren:has(
    .piloto-mclaren:hover
)
.centro-logo-mclaren img {

    opacity: 1;

    transform: scale(1.1);

    filter:
        drop-shadow(
            0 0 8px #ff8000
        )
        drop-shadow(
            0 0 20px rgba(255,128,0,.55)
        );
}


.dupla-pilotos-mclaren:has(
    .piloto-mclaren:hover
)
.centro-nome-mclaren {

    color: #ff8000;

    text-shadow:
        0 0 10px rgba(255,128,0,.6);
}


/* =========================================================
   HOVER — PILOTO
========================================================= */

.piloto-mclaren:hover {

    z-index: 20;
}


/* =========================================================
   HOVER — BRILHO
========================================================= */

.piloto-mclaren:hover::before {

    opacity: .9;

    transform: scale(1.3);
}


/* =========================================================
   HOVER — NÚMERO
========================================================= */

.piloto-mclaren:hover
.piloto-numero-bg-mclaren {

    color: rgba(255,128,0,.14);

    -webkit-text-stroke:
        1px rgba(255,128,0,.28);

    transform: scale(1.05);

    opacity: 1;
}


/* =========================================================
   HOVER — FOTO
========================================================= */

.piloto-mclaren:hover
.piloto-foto-mclaren img {

    filter:
        grayscale(0)
        brightness(1);

    opacity: 1;

    transform:
        translateY(0)
        scale(1.02);
}


/* =========================================================
   HOVER — DADOS
========================================================= */

.piloto-mclaren:hover
.piloto-dados-mclaren {

    transform:
        translateY(-8px);
}


/* =========================================================
   HOVER — NOME
========================================================= */

.piloto-mclaren:hover
.piloto-dados-mclaren h3 strong {

    color: #ff8000;

    text-shadow:
        0 0 8px rgba(255,128,0,.8),
        0 0 20px rgba(255,128,0,.45),
        0 3px 10px rgba(0,0,0,.9);
}


/* =========================================================
   HOVER — FUNDO DO NOME
========================================================= */

.piloto-mclaren:hover
.piloto-dados-mclaren h3::before {

    opacity: 1;

    transform: scaleX(1.05);
}


/* =========================================================
   HOVER — LINHA
========================================================= */

.piloto-mclaren:hover
.piloto-linha-mclaren {

    width: 120px;
}


/* =========================================================
   HOVER — AÇÃO
========================================================= */

.piloto-mclaren:hover
.piloto-acao-mclaren {

    color: white;

    transform:
        translateY(-5px);
}


.piloto-mclaren:hover
.piloto-acao-mclaren strong {

    background: #ff8000;

    color: #080808;

    transform:
        rotate(45deg);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 700px) {

    .pilotos-mclaren {

        padding:
            25px 12px;
    }


    .pilotos-titulo-mclaren {

        margin-bottom: 10px;
    }


    .pilotos-titulo-mclaren h2 {

        font-size: 30px;
    }


    .pilotos-titulo-mclaren p {

        font-size: 10px;
    }


    .dupla-pilotos-mclaren {

        height: calc(100% - 100px);

        grid-template-columns:
            1fr 1fr;
    }


    .dupla-pilotos-mclaren::before {

        top: 8%;

        bottom: 8%;
    }


    /* FOTO */

    .piloto-foto-mclaren {

        width: 110%;

        height: 72%;
    }


    /* NÚMERO */

    .piloto-numero-bg-mclaren {

        font-size: 150px;

        top: 15%;
    }


    .piloto-piastri-mclaren
    .piloto-numero-bg-mclaren {

        font-size: 135px;

        right: -5%;
    }


    /* DADOS */

    .piloto-dados-mclaren {

        left: 6%;

        bottom: 13%;

        max-width: 88%;
    }


    .piloto-piastri-mclaren
    .piloto-dados-mclaren {

        right: 6%;

        left: auto;
    }


    /* PAÍS */

    .piloto-pais-mclaren {

        font-size: 6px;

        letter-spacing: 2px;
    }


    /* NOME */

    .piloto-dados-mclaren h3 {

        font-size: 25px;

        line-height: .9;
    }


    /* LINHA */

    .piloto-linha-mclaren {

        margin-top: 9px;

        margin-bottom: 8px;

        width: 40px;
    }


    /* CATEGORIA */

    .piloto-categoria-mclaren {

        font-size: 5px;

        letter-spacing: 1px;
    }


    /* AÇÃO */

    .piloto-acao-mclaren {

        bottom: 5%;

        right: 6%;

        font-size: 6px;
    }


    .piloto-piastri-mclaren
    .piloto-acao-mclaren {

        left: 6%;

        right: auto;
    }


    .piloto-acao-mclaren strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-mclaren {

        padding:
            20px 8px;
    }


    .pilotos-titulo-mclaren h2 {

        font-size: 25px;
    }


    .pilotos-titulo-mclaren p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-mclaren {

        font-size: 115px;
    }


    .piloto-piastri-mclaren
    .piloto-numero-bg-mclaren {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-mclaren {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-mclaren {

        bottom: 12%;
    }


    .piloto-dados-mclaren h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-mclaren {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-mclaren span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-mclaren,
    .piloto-mclaren::before,
    .piloto-numero-bg-mclaren,
    .piloto-foto-mclaren img,
    .piloto-dados-mclaren,
    .piloto-dados-mclaren h3::before,
    .piloto-dados-mclaren h3 strong,
    .piloto-linha-mclaren,
    .piloto-acao-mclaren,
    .piloto-acao-mclaren strong {

        animation: none !important;

        transition: none !important;
    }

}







.intro-mclaren {
  padding: 80px 40px;
  background: linear-gradient(120deg, #0a0a0a 40%, #ff8000 120%);
}

.intro-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;

  max-width: 1200px;
  margin: auto;
}

/* TEXTO */
.intro-texto {
  flex: 1;
}

.intro-texto h2 {
  font-size: 48px;
  color: #ff8000;
  margin-bottom: 20px;
}

.intro-texto p {
  color: #ddd;
  font-size: 18px;
  line-height: 1.6;
  margin-bottom: 15px;
}

/* DADOS */
.intro-dados {
  margin-top: 20px;
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.intro-dados span {
  background: rgba(255,128,0,0.1);
  border: 1px solid #ff8000;
  padding: 8px 15px;
  border-radius: 10px;
  color: #ff8000;
  font-weight: bold;
}

