.intro-img {
  flex: 1;
  position: relative;
}

.intro-img img {
  width: 100%;
  border-radius: 20px;
  box-shadow: 0 0 40px rgba(255,128,0,0.4);
  transition: 0.4s;
}

.intro-img img:hover {
  transform: scale(1.03);
}

/* RESPONSIVO */
@media(max-width: 768px) {
  .intro-container {
    flex-direction: column;
    text-align: center;
  }

  .intro-texto h2 {
    font-size: 28px;
  }
}

.mclaren-philosophy{
  position:relative;

  width:100%;

  padding:140px 25px;

  overflow:hidden;

  background:
  linear-gradient(
  120deg,
  #0a0a0a 40%,
  #ff8000 120%);
}

/* TEXTO GIGANTE */
.mclaren-philosophy::before{
  content:"RACING";

  position:absolute;

  top:50%;
  left:50%;

  transform:translate(-50%,-50%);

  font-size:16vw;

  font-weight:900;

  letter-spacing:15px;

  color:rgba(255,255,255,.04);

  pointer-events:none;

  z-index:1;
}

/* GLOW */
.mclaren-philosophy::after{
  content:"";

  position:absolute;

  top:-250px;
  right:-250px;

  width:600px;
  height:600px;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.12),
  transparent 70%);

  filter:blur(50px);

  z-index:1;
}

/* CONTEÚDO */
.philosophy-content{
  position:relative;

  width:100%;
  max-width:1200px;

  margin:auto;

  z-index:2;
}

/* MINI TITLE */
.mini-title{
