  font-weight:800;

  letter-spacing:4px;

  text-transform:uppercase;

  padding:10px 18px;

  border-radius:999px;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  backdrop-filter:blur(10px);
}

/* TÍTULO */
.philosophy-content h2{
  font-size:
  clamp(3.2rem,8vw,7rem);

  line-height:1;

  margin-bottom:25px;

  color:#fff;

  font-weight:900;

  text-transform:uppercase;

  max-width:900px;
}

/* SUBTÍTULO */
.philosophy-content h3{
  max-width:800px;

  color:#f0f0f0;

  font-size:1.45rem;

  line-height:1.7;

  font-weight:500;

  margin-bottom:50px;
}

/* PARÁGRAFOS */
.philosophy-content p{
  max-width:900px;

  color:#e4e4e4;

  font-size:1.08rem;

  line-height:2;

  margin-bottom:30px;
}

/* PALAVRA DESTACADA */
.philosophy-content strong{
  color:#fff;

  font-weight:800;
}

/* BLOCO */
.philosophy-block{
  margin-top:70px;
  margin-bottom:50px;
}

/* TÍTULOS */
.philosophy-block h4,
.philosophy-ending h4{
  position:relative;

  display:inline-block;

  color:#fff;

  font-size:2rem;

  font-weight:800;

  margin-bottom:28px;

