.philosophy-ending h4::after{
  content:"";

  position:absolute;

  left:0;
  bottom:0;

  width:70px;
  height:4px;

  border-radius:20px;

  background:#fff;
}

/* GRID */
.philosophy-grid{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(280px,1fr));

  gap:25px;

  margin-top:50px;
}

/* CARDS */
.philosophy-card{
  position:relative;

  padding:38px 32px;

  border-radius:30px;

  background:
  linear-gradient(
  145deg,
  rgba(255,255,255,.10),
