    min-height: 600px;

    overflow: hidden;

    box-sizing: border-box;

    padding: 38px 4vw 25px;

    background: #050708;

    color: #fff;
}


/* =========================================================
   HEADER
========================================================= */

.linha-evolution-header-mclaren {
    position: relative;

    z-index: 10;

    text-align: center;

    margin-bottom: 28px;
}


.linha-evolution-header-mclaren > span {
    font-size: 13px;

    font-weight: 800;

    letter-spacing: 4px;

    color: rgba(220,255,255,.42);
}


.linha-evolution-header-mclaren h2 {
    margin: 6px 0 3px;

    font-size: clamp(28px, 4vw, 48px);

    line-height: 1;

    font-weight: 300;

    letter-spacing: -2px;
}


.linha-evolution-header-mclaren h2 strong {
    font-weight: 900;

    color: #FF8000;

    text-shadow:
        0 0 25px rgba(190,255,255,.2);
}


.linha-evolution-header-mclaren p {
    margin: 0;

    font-size: 15px;

    color: rgba(255,255,255,.35);

    letter-spacing: 1px;
}


/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-mclaren {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: flex;
    align-items: center;
    justify-content: center;
    grid-template-columns:
        repeat(5, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}

.linha-evolution-grid-mclaren
.linha-evolution-team-mclaren {
    width: min(420px, 70vw);
    height: 100%;
    flex: 0 0 min(420px, 70vw);
}
/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-mclaren {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-mclaren:hover
.linha-evolution-team-mclaren {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-mclaren
.linha-evolution-team-mclaren:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-mclaren {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-mclaren:hover
.team-bg-number-mclaren {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-mclaren {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-mclaren::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-mclaren img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-mclaren:hover
.team-image-mclaren {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-mclaren:hover
.team-image-mclaren::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-mclaren:hover
.team-image-mclaren img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-mclaren {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-mclaren:hover
.team-content-mclaren {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-mclaren {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-mclaren h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-mclaren {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-mclaren:hover
.team-line-mclaren {

    width: 65px;
}


/* Função */

.team-role-mclaren {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-mclaren {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-mclaren:hover
.team-arrow-mclaren {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


/* =========================================================
   CORES DAS EQUIPES
========================================================= */





/* =========================================================
   mclaren ATUAL
========================================================= */

.team-mclaren-current {

    --team-color: #FF8000;

    --team-glow:
        rgba(255,128,0,.8);
}


.team-mclaren-current:hover {

    background:
        linear-gradient(
            145deg,
            #071716,
            #050708 70%
        );

    border-color:
        rgba(255,128,0,.18);
}


.team-mclaren-current
.team-content-mclaren h3 {

    color: #FF8000;
}


.team-mclaren-current
.team-image-mclaren img {

    filter:
        grayscale(0%)
        brightness(.95);

    opacity: .85;
}


/* =========================================================
   FOOTER
========================================================= */

.linha-evolution-footer-mclaren {

    position: absolute;

    z-index: 10;

    left: 4vw;

    right: 4vw;

    bottom: 15px;

    display: flex;

    align-items: center;

    gap: 12px;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 3px;

    color:
        rgba(255,128,0,.25);
}


.footer-line-mclaren {

    height: 1px;

    flex: 1;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12)
        );
}


.footer-line-mclaren:last-of-type {

    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.12),
            transparent
        );
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 900px) {

    .mclaren-linha-evolution {

        padding-left: 20px;

        padding-right: 20px;
    }


    .linha-evolution-grid-mclaren {

        grid-template-columns:
            repeat(
                5,
                minmax(120px, 1fr)
            );

        overflow-x: auto;

        scrollbar-width: none;
    }


    .linha-evolution-grid-mclaren::-webkit-scrollbar {

        display: none;
    }


    .linha-evolution-team-mclaren {

        min-width: 150px;
    }


    .team-content-mclaren {

        left: 14px;

        right: 14px;

        bottom: 18px;
    }

}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .mclaren-linha-evolution {

        height: auto;

        min-height: 100dvh;

        padding:
            32px 15px 55px;
    }


    .linha-evolution-header-mclaren {

        margin-bottom: 18px;
    }


    .linha-evolution-header-mclaren > span {

        font-size: 6px;

        letter-spacing: 2px;
    }


    .linha-evolution-header-mclaren h2 {

        font-size: 28px;
    }


    .linha-evolution-header-mclaren p {

        font-size: 8px;
    }


    .linha-evolution-grid-mclaren {

        height: 62dvh;

        grid-template-columns:
            repeat(5, 145px);

        gap: 3px;

        overflow-x: auto;

        padding-bottom: 8px;
    }


    .linha-evolution-team-mclaren {

        min-width: 145px;
    }


    .team-image-mclaren {

        width: 75%;

        height: 55%;
    }


    .team-content-mclaren {

        left: 12px;

        bottom: 15px;
    }


    .team-content-mclaren h3 {

        font-size: 19px;
    }


    .team-bg-number-mclaren {

        font-size: 110px;
    }


    .team-arrow-mclaren {

        top: 12px;

        left: 12px;

        width: 22px;

        height: 22px;
    }


    .linha-evolution-footer-mclaren {

        left: 15px;

        right: 15px;
    }

}



/* ===== SECTION ===== */
.tabela-mclaren {
    padding: clamp(80px, 12vw, 140px) 20px;

 background: linear-gradient(120deg, #0a0a0a 40%, #ff8000 120%);

    color: #ff8000;
}

/* ===== TÍTULO ===== */
.titulo-tabela-mclaren {
    text-align: center;
    font-size: clamp(28px, 4vw, 46px);
    margin-bottom: 60px;

    display: flex;
    justify-content: center;
    align-items: center;
    gap: 12px;
}

/* LOGO */
.logo-titulo-mcl {
    width: clamp(28px, 4vw, 46px);

    filter: drop-shadow(0 0 12px rgba(255,128,0,0.7));
    transition: 0.3s ease;
}

.titulo-tabela-mclaren:hover .logo-titulo-mcl {
    transform: scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-mclaren {
    width: 90%;
    max-width: 1500px;
    margin: auto;

    background: rgba(0,0,0,0.7);
    border-radius: 20px;

    backdrop-filter: blur(8px);

    /* 🔥 glow McLaren */
    box-shadow:
        0 0 40px rgba(255,128,0,0.15),
        inset 0 0 30px rgba(255,128,0,0.05);
}

/* ===== TABELA ===== */
.box-tabela-mclaren table {
    width: 100%;
    border-collapse: collapse;
    min-width: 600px;
}

/* ===== LINHAS ===== */
.box-tabela-mclaren tr {
    transition: 0.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-mclaren td {
    padding: clamp(18px, 2.5vw, 28px);
    font-size: clamp(15px, 2vw, 20px);

    border-bottom: 1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-mclaren td:first-child {
    color: #ff8000;
    font-weight: bold;
    width: 50%;
}

/* SEGUNDA COLUNA */
.box-tabela-mclaren td:last-child {
    text-align: right;
    color: #e6e6e6;
    font-weight: 500;
}

/* ===== HOVER ===== */
.box-tabela-mclaren tr:hover {
    background: linear-gradient(
        90deg,
        rgba(255,128,0,0.1),
        rgba(255,179,71,0.08)
    );

    transform: scale(1.01);
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .box-tabela-mclaren{
    width: 95%;
    overflow: hidden;
  }

  .box-tabela-mclaren table{
    width: 100%;
    min-width: 100%;
  }

  .box-tabela-mclaren td{
    padding: 10px 8px;
    font-size: 18px;
  }

  .box-tabela-mclaren td:first-child{
    width: 45%;
    font-size: 16px;
  }

  .box-tabela-mclaren td:last-child{
    width: 55%;
    font-size: 18px;
    text-align: right;
    word-break: break-word;
  }

  .titulo-tabela-mclaren{
    font-size: 22px;
  }

}


