    font-size:14px;

    font-weight:900;

    letter-spacing:2px;

    color:#ff8000;

    white-space:nowrap;

}


/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.mclaren-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.mclaren-bar-left,
.mclaren-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.mclaren-bar-left{

    border-radius:999px 0 0 999px;

}


.mclaren-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #ffb347,
        #ff8000
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.mclaren-bar-right{

    border-radius:0 999px 999px 0;

}


.mclaren-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #ff8000,
        #ffb347
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.mclaren-value{

    animation:
    mclarenValueShow .5s ease;

}


@keyframes mclarenValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.mclaren-winner{

    color:#ff8000 !important;

    text-shadow:
    0 0 15px rgba(255,128,0,.8);

}


.mclaren-draw{

    color:#ffd7a5 !important;

}


