========================================== */

.numeros-mcLaren{

    position:relative;

    min-height:600px;

    padding:40px 0;

    overflow:hidden;

    background:
    linear-gradient(
        135deg,
        #000 0%,
        #080808 45%,
        #ff8000 120%
    );

}


/* IMAGEM DE FUNDO */

.bg-numeros-mcLaren{

    position:absolute;

    inset:0;

    width:100%;
    height:100%;

    object-fit:cover;

    filter:
    brightness(.35)
    blur(4px);

    transform:scale(1.1);

    z-index:0;

}



.numeros-mcLaren::before{

    content:"";

    position:absolute;

    inset:0;

    background:

    radial-gradient(
        circle at center,
        transparent 20%,
        rgba(0,0,0,.85)
    );

    z-index:1;

}



/* TITULO */

.titulo-numeros-mcLaren{

    position:relative;

    z-index:2;

    text-align:center;

    color:#ff8000;

    font-size:clamp(32px,5vw,55px);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:25px;

    text-shadow:

    0 0 15px #ff8000;

}



/* GRID */

.stats-grid-mcLaren{

    position:relative;

    z-index:2;


    max-width:1200px;

    margin:auto;

    padding:0 35px;


    display:grid;

    grid-template-columns:
    repeat(3,1fr);


    gap:15px;

}



/* CARDS */

.card-stat-mcLaren{

    position:relative;


    background:

    linear-gradient(
        145deg,
        rgba(255,255,255,.08),
        rgba(0,0,0,.25)
    );




    border-radius:22px;


    padding:18px;


    text-align:center;


    color:white;


    border:

    1px solid
    rgba(255,128,0,.5);



    box-shadow:

    0 15px 40px
    rgba(0,0,0,.7);



    overflow:hidden;



    opacity:0;

    transform:
    translateY(50px);



    transition:.6s ease;

}



/* LINHA LARANJA */

.card-stat-mcLaren::before{

    content:"";

    position:absolute;

    top:0;

    left:0;

    width:100%;

    height:4px;


    background:

    linear-gradient(
        90deg,
        transparent,
        #ff8000,
        transparent
    );

}



/* ATIVO */

.card-stat-mcLaren.ativo{

    opacity:1;

    transform:
    translateY(0);


    animation:

    brilhoMcLaren 2.5s infinite alternate;

}



@keyframes brilhoMcLaren{

    from{

        box-shadow:

        0 0 15px
        rgba(255,128,0,.3);

    }


    to{

        box-shadow:

        0 0 35px
        rgba(255,128,0,.8);

    }

}



/* NUMEROS */

.card-stat-mcLaren span{

    display:block;


    font-size:

    clamp(32px,4vw,55px);


    font-weight:900;


    color:#ff8000;


    text-shadow:

    0 0 15px #ff8000;

}



/* TEXTO */

.card-stat-mcLaren p{

    margin-top:15px;


    font-size:

    clamp(18px,2vw,28px);


    font-weight:bold;


    color:white;

}



/* CARD GRANDE */

.grande-mcLaren{

    grid-column:

    1 / -1;

}



/* BARRA */

.barra-velocidade-mcLaren{


    width:0%;


    height:8px;


    margin-top:20px;


    border-radius:20px;


    background:

    linear-gradient(
        90deg,
        #ff8000,
        #ffd180
    );


    box-shadow:

    0 0 15px #ff8000;


    transition:

    width .3s ease;

}



/* HOVER */

.card-stat-mcLaren:hover{


    transform:

    translateY(-10px)
    scale(1.03);



    border-color:#ff8000;


}



