.hall-mclaren{
padding:120px 40px;
position:relative;
  background: linear-gradient(120deg, #0a0a0a 40%, #ff8000 120%);
	min-height: auto;
height: auto;
overflow:hidden;
}


/* TÍTULO */

.titulo-hall-mclaren{
text-align:center;

font-size:52px;

color:#ff8000;

margin-bottom:80px;

text-shadow:
0 0 12px rgba(255,128,0,0.7);
}


/* GRID */

.hall-grid-mclaren{
  display:flex;

  justify-content:center;

  align-items:flex-start;

  flex-wrap:wrap;
  perspective: 1200px;
  gap:40px;

  position:relative;

  z-index:3;
}

.bg-hall-mclaren{
  position: absolute;
  inset: 0;
  z-index: 0;
}

.bg-layer-mclaren{
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  transform: scale(1);
  opacity: 0;
  transition: opacity .8s ease;
}

.bg-layer-mclaren.active{
  opacity: 1;
}

.hall-grid-mclaren,
.titulo-hall-mclaren,
.hall-overlay-mclaren{
  position: relative;
  z-index: 2;
}
/* CARD */

/* MODO SHOWCASE */
.hall-mclaren.showcase .hall-card-mclaren{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

/* FUNDO GANHA DESTAQUE */
.hall-mclaren.showcase .bg-layer-mclaren.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.15)
saturate(1.2);

transition:1s ease;
}


.hall-card-mclaren{
  position:relative;
  width:320px;
  padding:30px;
  border-radius:24px;
  background:
linear-gradient(
180deg,
rgba(15,15,25,0.28),
rgba(15,15,25,0.70)
);
  border:1px solid rgba(255,128,0,0.25);
  overflow:hidden;
  transition:0.45s ease;
  box-shadow:
    0 15px 35px rgba(0,0,0,0.45);
  text-align:center;
  backdrop-filter: blur(2px);
  transform-origin:center top;
}


/* HOVER */
.hall-card-mclaren:hover{
  transform: translateY(-14px) scale(1.04);
  background: rgba(15,15,15,0.92); /* 🔥 fica mais sólido no foco */
  box-shadow:
    0 25px 60px rgba(0,0,0,0.7),
    0 0 30px rgba(255,128,0,0.25);
  z-index: 10;
}

.hall-grid-mclaren:hover .hall-card-mclaren{
  opacity: 0.35;
  transform: scale(0.98);
}
.hall-card-mclaren:hover{
  opacity: 1 !important;
  transform: translateY(-14px) scale(1.06);
}
/* NÚMERO */

.numero-hall-mclaren{
position:absolute;

top:15px;
right:20px;

font-size:70px;

font-weight:900;

color:rgba(255,128,0,0.08);
}


/* FOTO */
.hall-card-mclaren img{
  width:170px;
  height:200px;

  object-fit:cover;

  border-radius:50%;

  border:3px solid #ff8000;

  margin-bottom:20px;

  filter: grayscale(100%) brightness(0.9);

  transition:0.5s ease;
}

.hall-card-mclaren:hover img{
  filter: grayscale(0%) brightness(1.1);
  transform: scale(1.1);
}


.hall-card-mclaren p,
.hall-stats-mclaren,
.frase-hall-mclaren {
  opacity: 0;
  transform: translateY(10px);
  max-height: 0;
  overflow: hidden;
  transition: 0.4s ease;
}

.hall-card-mclaren:hover p,
.hall-card-mclaren:hover .hall-stats-mclaren,
.hall-card-mclaren:hover .frase-hall-mclaren {
  opacity: 1;
  transform: translateY(0);
  max-height: 200px;
}

/* NOME */

.hall-card-mclaren h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}


/* PAÍS */

.pais-hall-mclaren{
display:block;

font-size:18px;

color:#ff9f3f;

margin-bottom:18px;
}


/* TEXTO */

.hall-card-mclaren p{
font-size:18px;

color:#ddd;

margin-bottom:22px;
}


/* STATS */

.hall-stats-mclaren{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#ffb347;
}


/* FRASE */

.frase-hall-mclaren{
font-size:14px;

font-style:italic;

color:#fff;

line-height:1.6;
}

