.mclaren-evolution{
  position:relative;
  width:100%;
  padding:120px 25px;
  overflow:hidden;

  background: linear-gradient(120deg, #0a0a0a 40%, #ff8000 120%);

  font-size:initial;
}

/* FUNDOS POR DÉCADA */
.mclaren-evolution.bg-60s{
  background:
  radial-gradient(circle at top,
  #5a2a00 0%,
  #120700 55%,
  #050505 100%);
}

.mclaren-evolution.bg-70s{
  background:
  radial-gradient(circle at top,
  #8b5e00 0%,
  #1a1200 55%,
  #050505 100%);
}

/* 80s — vermelho e branco */
.mclaren-evolution.bg-80s{
  background:
  radial-gradient(circle at top,
  #ffffff 0%,
  #b30000 35%,
  #240000 65%,
  #050505 100%);
}

/* 90s — vermelho e branco */
.mclaren-evolution.bg-90s{
  background:
  radial-gradient(circle at top,
  #f5f5f5 0%,
  #c40000 35%,
  #220000 65%,
  #050505 100%);
}

/* 2000s — prata e preto */
.mclaren-evolution.bg-2000s{
  background:
  radial-gradient(circle at top,
  #bdbdbd 0%,
  #5f5f5f 35%,
  #151515 65%,
  #050505 100%);
}

/* 2010s — prata e vermelho */
.mclaren-evolution.bg-2010s{
  background:
  radial-gradient(circle at top,
  #d9d9d9 0%,
  #8a0000 35%,
  #1a0000 65%,
  #050505 100%);
}

.mclaren-evolution.bg-2020s{
  background:
  radial-gradient(circle at top,
  #ff8000 0%,
  #140800 55%,
  #050505 100%);
}

/* TRANSIÇÃO SUAVE */
.mclaren-evolution{
  transition:
  background 1s ease;
}


/* BRILHOS */
.mclaren-evolution::before{
  content:"";

  position:absolute;
  top:-200px;
  left:-200px;

  width:500px;
  height:500px;

  background:
  radial-gradient(circle,
  rgba(255,128,0,.18),
  transparent 70%);

  filter:blur(30px);

  animation:glowMove 8s linear infinite;
}

.mclaren-evolution::after{
  content:"";

  position:absolute;
  right:-150px;
  bottom:-150px;

  width:450px;
  height:450px;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.06),
  transparent 70%);

  filter:blur(50px);
}

/* TÍTULO */
.title-mclaren{
  position:relative;

  font-size:clamp(2.5rem,6vw,5rem);

  text-align:center;

  margin-bottom:80px;

  font-weight:900;

  letter-spacing:3px;

  text-transform:uppercase;

  background:
  linear-gradient(90deg,#fff,#ff8000);

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;

  z-index:5;
}

/* ÁREA DO CARRO */
.car-container{
  position:relative;

  width:100%;
  max-width:900px;
  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;

  z-index:2;
}

/* BASE DO SHOWROOM */
.car-container::before{
  content:"";

  position:absolute;
  bottom:50px;

  width:70%;
  height:40px;

  background:
  radial-gradient(circle,
  rgba(255,128,0,.35),
  transparent 70%);

  filter:blur(20px);

  border-radius:50%;

  animation:pulseFloor 4s ease-in-out infinite;
}

/* CÍRCULO */
.car-circle{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:
  2px solid rgba(255,128,0,.18);

  box-shadow:
  0 0 40px rgba(255,128,0,.15),
  inset 0 0 40px rgba(255,128,0,.08);

  animation:rotateCircle 14s linear infinite;
}

/* LINHA EXTRA */
.car-circle::before{
  content:"";

  position:absolute;
  inset:20px;

  border-radius:50%;

  border:
  1px dashed rgba(255,255,255,.08);
}

/* CARRO */
.car-container img{
  position:relative;

  width:100%;
  max-width:650px;

  object-fit:contain;

  z-index:5;

  filter:
  drop-shadow(0 30px 35px rgba(0,0,0,.6));

  animation:
  floatCar 5s ease-in-out infinite,
  rotateCar 6s ease-in-out infinite;

  transition:
  opacity .45s ease,
  transform .45s ease;
}

/* BOTÕES */
.controls{
  position:relative;

  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin-top:40px;
  margin-bottom:90px;

  z-index:5;
}

.controls button{
  position:relative;

  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(145deg,#ff8000,#ff5e00);

  color:#000;

  font-weight:800;
  font-size:.95rem;

  letter-spacing:1px;

  cursor:pointer;

  overflow:hidden;

  transition:.35s;
}

/* brilho botão */
.controls button::before{
  content:"";

  position:absolute;
  top:0;
  left:-120%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
  120deg,
  transparent,
  rgba(255,255,255,.6),
  transparent);

  transition:.6s;
}

.controls button:hover::before{
  left:120%;
}

.controls button:hover{
  transform:
  translateY(-6px)
  scale(1.05);

  box-shadow:
  0 10px 30px rgba(255,128,0,.35);
}

/* INFOS */
.car-info{
  position:relative;

  width:100%;
  max-width:1200px;

  margin:auto;

  z-index:5;
}

.car-info h2{
  text-align:center;

  font-size:clamp(2rem,5vw,3.5rem);

  margin-bottom:50px;

  font-weight:900;

  color:#fff;
}

/* GRID */
.info-grid{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));

  gap:25px;
}

/* CARDS */
.info-card{
  position:relative;

  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
  145deg,
  rgba(255,255,255,.06),
  rgba(255,255,255,.02));

  border:
  1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  overflow:hidden;

  transition:.45s;
}

/* brilho interno */
.info-card::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
  140deg,
  rgba(255,255,255,.08),
  transparent 40%);

  opacity:0;

  transition:.4s;
}

.info-card:hover::before{
  opacity:1;
}

.info-card:hover{
  transform:
  translateY(-12px);

  border-color:
  rgba(255,128,0,.35);

  box-shadow:
  0 15px 40px rgba(0,0,0,.45),
  0 0 25px rgba(255,128,0,.12);
}

.info-card span{
  display:block;

  margin-bottom:14px;

  color:#ff8000;

  text-transform:uppercase;

  letter-spacing:2px;

  font-size:.8rem;

  font-weight:700;
}

.info-card h3{
  color:#fff;

  font-size:1.1rem;

  line-height:1.7;

  font-weight:600;
}

/* ANIMAÇÕES */
@keyframes rotateCircle{
  from{
    transform:rotate(0deg);
  }

  to{
    transform:rotate(360deg);
  }
}

@keyframes floatCar{

  0%,100%{
    transform:
    translateY(0px);
  }

  50%{
    transform:
    translateY(-15px);
  }

}

@keyframes rotateCar{

  0%,100%{
    rotate:y 0deg;
  }

  50%{
    rotate:y 10deg;
  }

}

@keyframes pulseFloor{

  0%,100%{
    transform:scale(.95);
    opacity:.5;
  }

  50%{
    transform:scale(1.05);
    opacity:1;
  }

}

@keyframes glowMove{

  0%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(80px,40px);
  }

  100%{
    transform:translate(0,0);
  }

}

/* RESPONSIVO */
@media(max-width:768px){

  .mclaren-evolution{
    padding:90px 18px;
  }

  .car-container{
    height:320px;
  }

  .car-circle{
    width:250px;
    height:250px;
  }

  .car-container img{
    max-width:340px;
  }

  .controls{
    gap:10px;
  }

  .controls button{
    padding:12px 16px;
    font-size:.8rem;
  }

  .info-card{
    padding:28px 22px;
  }

}

