/* ========//////=/////////================== 
MERCEDES
=============///////===========/========== */


body.mercedes{
  background: #c0c0c0;
}



/* =========================================================
   MERCEDES HERO
========================================================= */

.mercedes-hero {
    position: relative;
    width: 100%;
    height: 100dvh;
    min-height: 620px;
    overflow: hidden;
    background: #020713;
    color: #fff;
    isolation: isolate;
}


/* =========================================================
   CARRO — FUNDO PRINCIPAL
========================================================= */

.mercedes-car-bg {
    position: absolute;
    inset: -5%;
    z-index: -5;

    background-image:
        url("carros/w17.png");

    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;

    filter:
        brightness(.58)
        contrast(1.08)
        saturate(1.12);

    transform: scale(1.04);

    transition:
        transform 1s ease,
        filter 1s ease;
}


/* LEVE MOVIMENTO */

.mercedes-hero:hover .mercedes-car-bg {
    transform: scale(1.07);

    filter:
        brightness(.63)
        contrast(1.1)
        saturate(1.15);
}


/* =========================================================
   OVERLAY
========================================================= */

.mercedes-overlay {
    position: absolute;
    inset: 0;
    z-index: -4;

    background:

        /* AZUL */
        linear-gradient(
            115deg,
            rgba(0,210,190,.78),
            transparent 42%
        ),

        /* VERMELHO */
        linear-gradient(
            250deg,
            rgba(2,2,2,.32),
            transparent 42%
        ),

        /* ESCURECIMENTO */
        linear-gradient(
            to bottom,
            rgba(0,0,0,.55),
            transparent 25%,
            rgba(0,0,0,.08) 55%,
            rgba(0,0,0,.82) 100%
        );
}


/* =========================================================
   TOPO
========================================================= */

.mercedes-top {
    position: absolute;

    top: 25px;
    left: 4vw;
    right: 4vw;

    z-index: 30;

    display: flex;
    align-items: center;
    justify-content: space-between;
}


/* =========================================================
   HOME
========================================================= */

.mercedes-home {
    display: flex;
    align-items: center;

    gap: 8px;

    padding: 9px 13px;

    text-decoration: none;

    color: rgba(255,255,255,.75);

    border: 1px solid rgba(255,255,255,.2);

    background: rgba(0,0,0,.3);

    backdrop-filter: blur(10px);

    font-size: 25px;
    font-weight: 900;
    letter-spacing: 2px;

    transition: .35s ease;
}

.mercedes-home i {
    font-size: 20px;
}

.mercedes-home:hover {
    color: #fff;

    background: rgba(0,210,190,.22);

    border-color: #00d2be;

    transform: translateY(-3px);
}


/* =========================================================
   STATUS
========================================================= */

.mercedes-status {
    position: absolute;

    left: 50%;

    transform: translateX(-50%);

    font-size: 15px;
    font-weight: 900;
    letter-spacing: 4px;

    color: rgba(255,255,255,.55);
}


/* =========================================================
   RED BULL — REDES SOCIAIS INFERIORES
========================================================= */

.mercedes-social-top {
    position: absolute;

    z-index: 30;

    left: 50%;
    bottom:110px;

    transform: translateX(-13%);

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 7px;
}


/* =========================================================
   ÍCONES
========================================================= */

.mercedes-social-top a {
    width: 100px;
    height: 100px;

    display: flex;
    align-items: center;
    justify-content: center;

    text-decoration: none;

    color: rgba(255,255,255,.65);

    border: 1px solid rgba(255,255,255,.16);

    background:
        linear-gradient(
            135deg,
            rgba(10,15,30,.78),
            rgba(0,0,0,.45)
        );

    backdrop-filter: blur(8px);

    font-size: 30px;

    transition:
        transform .35s ease,
        color .35s ease,
        background .35s ease,
        border-color .35s ease,
        box-shadow .35s ease;
}


/* =========================================================
   HOVER
========================================================= */

.mercedes-social-top a:hover {
    color: #fff;

    background:#00d2be;

    border-color:#C0c0c0 ;

    transform:
        translateY(-5px)
        scale(1.08);

    box-shadow:
        0 8px 22px rgba(2,2,2,.35),
        0 0 15px rgba(2,2,2,.15);
}


/* =========================================================
   LINHA DECORATIVA
========================================================= */

.mercedes-social-top::before,
.mercedes-social-top::after {
    content: "";

    width: 55px;
    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(2,2,2,.7)
        );
}


.mercedes-social-top::after {
    background:
        linear-gradient(
            90deg,
            rgba(2,2,2,.7),
            transparent
        );
}


/* =========================================================
   LOGO RED BULL
========================================================= */

.mercedes-logo {
    position: absolute;

    z-index: 8;

    right: 4vw;
    top: -50px;

    width: 300px;
    height: 300px;

    display: flex;
    align-items: center;
    justify-content: center;

    pointer-events: none;

    animation: mercedes-logo-float 4s ease-in-out infinite;
}


/* LOGO */

.mercedes-logo img {
    position: relative;

    z-index: 2;

    width: 100%;
    height: 100%;

    object-fit: contain;

    display: block;

    filter: drop-shadow(0 5px 15px rgba(0,0,0,.6));
}


/* =========================================================
   ANIMAÇÃO DA LOGO
========================================================= */

@keyframes mercedes-logo-float {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-7px);
    }

}


/* =========================================================
   GLOW DA LOGO
========================================================= */

.mercedes-logo-glow {
    position: absolute;

    z-index: 1;

    width: 220px;
    height: 220px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0,210,190,.3),
            rgba(0,210,190,.15),
            transparent 70%
        );

    filter: blur(20px);

    animation: mercedes-logo-glow 4s ease-in-out infinite;
}


/* =========================================================
   ANIMAÇÃO DO GLOW
========================================================= */

@keyframes mercedes-logo-glow {

    0%,
    100% {
        transform: scale(.9);
        opacity: .55;
    }

    50% {
        transform: scale(1.15);
        opacity: 1;
    }

}

