.mercedes-pulsos span:nth-child(59) { --atraso:-2.9s; }
.mercedes-pulsos span:nth-child(60) { --atraso:-1s; }


/* =========================================================
   ANIMAÇÃO
========================================================= */

@keyframes mercedesPulso {

    0% {
        transform: scale(.2);
        opacity: 0;
    }

    18% {
        transform: scale(.6);
        opacity: .35;
    }

    38% {
        transform: scale(1.4);
        opacity: 1;
    }

    52% {
        transform: scale(.8);
        opacity: .65;
    }

    68% {
        transform: scale(1.8);
        opacity: .2;
    }

    100% {
        transform: scale(.2);
        opacity: 0;
    }
}

