/* =========================================================
   PILOTOS mercedes
========================================================= */

.pilotos-mercedes {

    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 100dvh;

    overflow: hidden;

    box-sizing: border-box;

    padding: 45px 5vw;

    background:
        radial-gradient(
            circle at 50% 100%,
            rgba(0,210,190,.12),
            transparent 35%
        ),
        linear-gradient(
            120deg,
            #050505,
            #0b0b0b,
            #050505
        );

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.pilotos-titulo-mercedes {

    position: relative;

    z-index: 20;

    text-align: center;

    margin-bottom: 25px;
}


.pilotos-titulo-mercedes span {

    display: block;

    color: #00d2be;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 5px;
}


.pilotos-titulo-mercedes h2 {

    margin: 4px 0;

    font-size: clamp(30px, 4vw, 52px);

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotos-titulo-mercedes p {

    margin: 0;

    color: rgba(255,255,255,.62);

    font-size: 18px;
}


/* =========================================================
   ÁREA DOS PILOTOS
========================================================= */

.dupla-pilotos-mercedes {

    position: relative;

    display: grid;

    grid-template-columns: 1fr 1fr;

    height: calc(100% - 125px);

    max-width: 1450px;

    margin: auto;
}


/* =========================================================
   PILOTO
========================================================= */

.piloto-mercedes {

    position: relative;

    display: block;

    height: 100%;

    overflow: hidden;

    text-decoration: none;

    color: white;

    transition:
        transform .5s ease;
}


/* =========================================================
   BRILHO DE FUNDO
========================================================= */

.piloto-mercedes::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: 15%;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0,210,190,.15),
            transparent 68%
        );

    filter: blur(30px);

    opacity: .35;

    transition:
        transform .7s ease,
        opacity .7s ease;

    pointer-events: none;
}


/* =========================================================
   BRILHO russell
========================================================= */

.piloto-russell-mercedes::before {

    left: -220px;
}


/* =========================================================
   BRILHO kimi
========================================================= */

.piloto-kimi-mercedes::before {

    right: -220px;
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.piloto-numero-bg-mercedes {

    position: absolute;

    z-index: 0;

    top: 5%;

    font-size: clamp(200px, 40vw, 400px);

    font-weight: 900;

    line-height: 1;

    color: transparent;

    -webkit-text-stroke:
        1px rgba(255,255,255,.08);

    opacity: .8;

    transition:
        color .7s ease,
        -webkit-text-stroke .7s ease,
        transform .7s ease,
        opacity .7s ease;
}


/* =========================================================
   NÚMERO russell
========================================================= */

.piloto-russell-mercedes
.piloto-numero-bg-mercedes {

    left: -3%;
	    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}



/* =========================================================
   NÚMERO kimi
========================================================= */

.piloto-kimi-mercedes
.piloto-numero-bg-mercedes {

    right: -2%;

    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   FOTO
========================================================= */

.piloto-foto-mercedes {

    position: absolute;

    z-index: 2;

    left: 50%;

    bottom: 0;

    width: 70%;

    height: 90%;

    transform:
        translateX(-50%);

    display: flex;

    align-items: flex-end;

    justify-content: center;

    pointer-events: none;
}


.piloto-foto-mercedes img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center bottom;

    filter:
        grayscale(.35)
        brightness(.65);

    opacity: .72;

    transform:
        translateY(30px)
        scale(.95);

    transition:
        transform .8s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


/* =========================================================
   POSIÇÃO DA FOTO DO kimi
========================================================= */

.piloto-kimi-mercedes
.piloto-foto-mercedes {

    transform:
        translateX(-60%);
}


/* =========================================================
   DADOS DO PILOTO
========================================================= */

.piloto-dados-mercedes {

    position: absolute;

    z-index: 12;

    left: 7%;

    bottom: 9%;

    max-width: 80%;

    transition:
        transform .6s ease;
}


/* =========================================================
   DADOS DO kimi
========================================================= */

.piloto-kimi-mercedes
.piloto-dados-mercedes {

    left: auto;

    right: 7%;

    text-align: right;
}


/* =========================================================
   PAÍS
========================================================= */

.piloto-pais-mercedes {

    display: block;

    margin-bottom: 8px;

    color: #00d2be;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 4px;
}


/* =========================================================
   NOME
========================================================= */

.piloto-dados-mercedes h3 {

    position: relative;

    display: inline-flex;

    flex-direction: column;

    align-items: flex-start;

    margin: 0;

    padding: 6px 14px 8px 0;

    z-index: 13;

    font-size: clamp(28px, 3vw, 42px);

    line-height: .9;

    font-weight: 900;

    text-shadow:
        0 3px 10px rgba(0,0,0,.95),
        0 0 18px rgba(0,0,0,.9);
}


/* =========================================================
   NOME kimi — ALINHAMENTO
========================================================= */

.piloto-kimi-mercedes
.piloto-dados-mercedes h3 {

    align-items: flex-end;

    padding-right: 0;

    padding-left: 14px;
}


/* =========================================================
   FUNDO DE PROTEÇÃO DO NOME
========================================================= */

.piloto-dados-mercedes h3::before {

    content: "";

    position: absolute;

    z-index: -1;

    left: -30px;

    right: -30px;

    top: -10px;

    bottom: -10px;

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.92),
            rgba(0,0,0,.72),
            rgba(0,0,0,.25),
            transparent
        );

    filter: blur(7px);

    opacity: .9;

    pointer-events: none;

    transition:
        opacity .4s ease,
        transform .4s ease;
}


/* =========================================================
   FUNDO DO NOME kimi
========================================================= */

.piloto-kimi-mercedes
.piloto-dados-mercedes h3::before {

    background:
        linear-gradient(
            270deg,
            rgba(0,0,0,.92),
            rgba(0,0,0,.72),
            rgba(0,0,0,.25),
            transparent
        );
}


/* =========================================================
   PRIMEIRO NOME
========================================================= */

.piloto-dados-mercedes h3 {

    color: #fff;
}


/* =========================================================
   SOBRENOME
========================================================= */

.piloto-dados-mercedes h3 strong {

    position: relative;

    display: block;

    color: #fff;

    font-weight: 900;

    transition:
        color .35s ease,
        text-shadow .35s ease;
}


/* =========================================================
   LINHA
========================================================= */

.piloto-linha-mercedes {

    width: 65px;

    height: 2px;

    margin: 15px 0;

    background: #00d2be;

    box-shadow:
        0 0 12px rgba(0,210,190,.7);

    transition:
        width .6s ease;
}


.piloto-kimi-mercedes
.piloto-linha-mercedes {

    margin-left: auto;
}


/* =========================================================
   CATEGORIA
========================================================= */

.piloto-categoria-mercedes {

    color: rgba(255,255,255,.98);

    font-size: 12px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* =========================================================
   AÇÃO
========================================================= */

.piloto-acao-mercedes {

    position: absolute;

    z-index: 14;

    right: 7%;

    bottom: 10%;

    display: flex;

    align-items: center;

    gap: 12px;

    color: rgba(255,255,255,.4);

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    transition:
        color .4s ease,
        transform .5s ease;
}


/* =========================================================
   AÇÃO kimi
========================================================= */

.piloto-kimi-mercedes
.piloto-acao-mercedes {

    right: auto;

    left: 4%;
}


/* =========================================================
   ÍCONE
========================================================= */

.piloto-acao-mercedes strong {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 28px;

    height: 28px;

    border: 1px solid rgba(0,210,190,.3);

    color: #00d2be;

    font-size: 12px;

    transition:
        background .4s ease,
        color .4s ease,
        transform .4s ease;
}



/* =========================================================
   CENTRO mercedes
========================================================= */

.centro-mercedes {

    position: absolute;

    z-index: 25;

    left: 50%;
    top: 5%;

    bottom: 5%;

    width: 90px;

    transform: translateX(-50%);

    display: flex;

    flex-direction: column;

    align-items: center;

    pointer-events: none;
}


/* =========================================================
   LOGO CENTRAL
========================================================= */

.centro-logo-mercedes {

    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle,
            rgba(5,5,5,.95) 45%,
            rgba(5,5,5,.75) 70%,
            transparent 100%
        );

    flex-shrink: 0;
}


.centro-logo-mercedes img {

    width: 55px;
    height: 55px;

    object-fit: contain;

    opacity: .75;

    filter:
        drop-shadow(
            0 0 8px rgba(0,210,190,.25)
        );

    transition:
        transform .5s ease,
        opacity .5s ease,
        filter .5s ease;
}


/* =========================================================
   LINHA VERTICAL
========================================================= */

.centro-linha-mercedes {

    width: 1px;

    flex: 1;

    min-height: 80px;

    background:
        linear-gradient(
            to bottom,
            rgba(0,210,190,.8),
            rgba(0,210,190,.15),
            transparent
        );

    box-shadow:
        0 0 8px rgba(0,210,190,.25);
}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.centro-nome-mercedes {

    writing-mode: vertical-rl;

    text-orientation: mixed;

    margin-top: 12px;

    color: rgba(255,255,255,.3);

    font-size: 20px;

    font-weight: 800;

    letter-spacing: 4px;

    text-transform: uppercase;

    white-space: nowrap;

    transition:
        color .4s ease,
        text-shadow .4s ease;
}


/* =========================================================
   HOVER NOS PILOTOS
========================================================= */

.dupla-pilotos-mercedes:has(
    .piloto-mercedes:hover
)
.centro-logo-mercedes img {

    opacity: 1;

    transform: scale(1.1);

    filter:
        drop-shadow(
            0 0 8px #00d2be
        )
        drop-shadow(
            0 0 20px rgba(0,210,190,.55)
        );
}


.dupla-pilotos-mercedes:has(
    .piloto-mercedes:hover
)
.centro-nome-mercedes {

    color: #00d2be;

    text-shadow:
        0 0 10px rgba(0,210,190,.6);
}


/* =========================================================
   HOVER — PILOTO
========================================================= */

.piloto-mercedes:hover {

    z-index: 20;
}


/* =========================================================
   HOVER — BRILHO
========================================================= */

.piloto-mercedes:hover::before {

    opacity: .9;

    transform: scale(1.3);
}


/* =========================================================
   HOVER — NÚMERO
========================================================= */

.piloto-mercedes:hover
.piloto-numero-bg-mercedes {

    color: rgba(0,210,190,.14);

    -webkit-text-stroke:
        1px rgba(0,210,190,.28);

    transform: scale(1.05);

    opacity: 1;
}


/* =========================================================
   HOVER — FOTO
========================================================= */

.piloto-mercedes:hover
.piloto-foto-mercedes img {

    filter:
        grayscale(0)
        brightness(1);

    opacity: 1;

    transform:
        translateY(0)
        scale(1.02);
}


/* =========================================================
   HOVER — DADOS
========================================================= */

.piloto-mercedes:hover
.piloto-dados-mercedes {

    transform:
        translateY(-8px);
}


/* =========================================================
   HOVER — NOME
========================================================= */

.piloto-mercedes:hover
.piloto-dados-mercedes h3 strong {

    color: #00d2be;

    text-shadow:
        0 0 8px rgba(0,210,190,.8),
        0 0 20px rgba(0,210,190,.45),
        0 3px 10px rgba(0,0,0,.9);
}


/* =========================================================
   HOVER — FUNDO DO NOME
========================================================= */

.piloto-mercedes:hover
.piloto-dados-mercedes h3::before {

    opacity: 1;

    transform: scaleX(1.05);
}


/* =========================================================
   HOVER — LINHA
========================================================= */

.piloto-mercedes:hover
.piloto-linha-mercedes {

    width: 120px;
}


/* =========================================================
   HOVER — AÇÃO
========================================================= */

.piloto-mercedes:hover
.piloto-acao-mercedes {

    color: white;

    transform:
        translateY(-5px);
}


.piloto-mercedes:hover
.piloto-acao-mercedes strong {

    background: #00d2be;

    color: #080808;

    transform:
        rotate(45deg);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 700px) {

    .pilotos-mercedes {

        padding:
            25px 12px;
    }


    .pilotos-titulo-mercedes {

        margin-bottom: 10px;
    }


    .pilotos-titulo-mercedes h2 {

        font-size: 30px;
    }


    .pilotos-titulo-mercedes p {

        font-size: 10px;
    }


    .dupla-pilotos-mercedes {

        height: calc(100% - 100px);

        grid-template-columns:
            1fr 1fr;
    }


    .dupla-pilotos-mercedes::before {

        top: 8%;

        bottom: 8%;
    }


    /* FOTO */

    .piloto-foto-mercedes {

        width: 110%;

        height: 72%;
    }


    /* NÚMERO */

    .piloto-numero-bg-mercedes {

        font-size: 150px;

        top: 15%;
    }


    .piloto-kimi-mercedes
    .piloto-numero-bg-mercedes {

        font-size: 135px;

        right: -5%;
    }


    /* DADOS */

    .piloto-dados-mercedes {

        left: 6%;

        bottom: 13%;

        max-width: 88%;
    }


    .piloto-kimi-mercedes
    .piloto-dados-mercedes {

        right: 6%;

        left: auto;
    }


    /* PAÍS */

    .piloto-pais-mercedes {

        font-size: 6px;

        letter-spacing: 2px;
    }


    /* NOME */

    .piloto-dados-mercedes h3 {

        font-size: 25px;

        line-height: .9;
    }


    /* LINHA */

    .piloto-linha-mercedes {

        margin-top: 9px;

        margin-bottom: 8px;

        width: 40px;
    }


    /* CATEGORIA */

    .piloto-categoria-mercedes {

        font-size: 5px;

        letter-spacing: 1px;
    }


    /* AÇÃO */

    .piloto-acao-mercedes {

        bottom: 5%;

        right: 6%;

        font-size: 6px;
    }


    .piloto-kimi-mercedes
    .piloto-acao-mercedes {

        left: 6%;

        right: auto;
    }


    .piloto-acao-mercedes strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-mercedes {

        padding:
            20px 8px;
    }


    .pilotos-titulo-mercedes h2 {

        font-size: 25px;
    }


    .pilotos-titulo-mercedes p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-mercedes {

        font-size: 115px;
    }


    .piloto-kimi-mercedes
    .piloto-numero-bg-mercedes {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-mercedes {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-mercedes {

        bottom: 12%;
    }


    .piloto-dados-mercedes h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-mercedes {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-mercedes span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-mercedes,
    .piloto-mercedes::before,
    .piloto-numero-bg-mercedes,
    .piloto-foto-mercedes img,
    .piloto-dados-mercedes,
    .piloto-dados-mercedes h3::before,
    .piloto-dados-mercedes h3 strong,
    .piloto-linha-mercedes,
    .piloto-acao-mercedes,
    .piloto-acao-mercedes strong {

        animation: none !important;

        transition: none !important;
    }

}




