.tabela-mercedes {
    padding: clamp(80px, 12vw, 140px) 20px;

  background: linear-gradient(120deg, #000000 0%, #000000 55%, #00d2be 80%, #d0d0d0 100%);

    color: #00D2BE;
}

/* ===== TÍTULO ===== */
.titulo-tabela-mercedes {
    text-align: center;
    font-size: clamp(28px, 4vw, 46px);
    margin-bottom: 60px;

    display: flex;
    justify-content: center;
    align-items: center;
    gap: 12px;
}

/* LOGO */
.logo-titulo-mer {
    width: clamp(28px, 4vw, 46px);

    filter: drop-shadow(0 0 12px rgba(0,210,190,0.7));
    transition: 0.3s ease;
}

.titulo-tabela-mercedes:hover .logo-titulo-mer {
    transform: scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-mercedes {
    width: 90%;
    max-width: 1500px;
    margin: auto;

    background: rgba(0,0,0,0.7);
    border-radius: 20px;
  

    backdrop-filter: blur(8px);

    /* 🔥 glow Mercedes */
    box-shadow:
        0 0 40px rgba(0,210,190,0.15),
        inset 0 0 30px rgba(0,210,190,0.05);
}

/* ===== TABELA ===== */
.box-tabela-mercedes table {
    width: 100%;
    border-collapse: collapse;
    min-width: 600px;
}

/* ===== LINHAS ===== */
.box-tabela-mercedes tr {
    transition: 0.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-mercedes td {
    padding: clamp(18px, 2.5vw, 28px);
    font-size: clamp(15px, 2vw, 20px);

    border-bottom: 1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-mercedes td:first-child {
    color: #00D2BE;
    font-weight: bold;
    width: 50%;
}

/* SEGUNDA COLUNA */
.box-tabela-mercedes td:last-child {
    text-align: right;
    color: #e6e6e6; /* prata/branco */
    font-weight: 500;
}

/* ===== HOVER ===== */
.box-tabela-mercedes tr:hover {
    background: linear-gradient(
        90deg,
        rgba(0,210,190,0.1),
        rgba(0,210,190,0.05)
    );

    transform: scale(1.01);
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .box-tabela-mercedes{
    width: 95%;
    overflow: hidden; /* 🔥 remove scroll */
  }

  .box-tabela-mercedes table{
    width: 100%;
    min-width: 100%; /* 🔥 remove os 600px */
  }

  .box-tabela-mercedes td{
    padding: 10px 8px;
    font-size: 18px;
  }

  /* coluna esquerda */
  .box-tabela-mercedes td:first-child{
    width: 45%;
    font-size: 16px;
  }

  /* coluna direita */
  .box-tabela-mercedes td:last-child{
    width: 55%;
    font-size: 18px;
    text-align: right;
    word-break: break-word; /* 🔥 quebra texto grande */
  }

  .titulo-tabela-mercedes{
    font-size: 22px;
  }

}

