    padding:80px 20px;

    color:#fff;

    background:
    radial-gradient(
        circle at top,
        #00d2aa 0%,
        #120900 45%,
        #050505 100%
    );

}


/* brilho de fundo */

.temporada-mercedes::before{

    content:"";

    position:absolute;

    top:-200px;

    right:-200px;

    width:500px;

    height:500px;


    background:
    radial-gradient(
        circle,
        rgba(0,210,190,.18),
        transparent 70%
    );


    filter:blur(50px);

}


.temporada-mercedes > *{

    position:relative;

    z-index:2;

}



/* =====================================
   TÍTULO
===================================== */


.titulo-temp-mercedes{

    text-align:center;

    margin-bottom:50px;

    font-size:
    clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:3px;


    color:#fff;


    text-shadow:

    0 0 20px
    rgba(0,210,190,.55);

}



/* =====================================
   DASHBOARD
===================================== */


.dashboard-mercedes{

    max-width:1200px;

    margin:auto;

}



/* =====================================
   TOPO
===================================== */


.topo-temp-mercedes{

    display:grid;

    grid-template-columns:

    220px 1fr 220px;

    gap:20px;

    align-items:center;

}



/* =====================================
   CARD POSIÇÃO
===================================== */


.card-campeonato-mercedes,
.card-pontos-mercedes,
.card-grafico-mercedes{


    background:

    linear-gradient(
        145deg,
        #161616,
        #202020
    );


    border-radius:25px;


    border:

    1px solid
    rgba(0,210,190,.2);


    box-shadow:

    0 15px 35px
    rgba(0,0,0,.35);


}



/* posição */

.card-campeonato-mercedes,
.card-pontos-mercedes{


    padding:30px 20px;

    text-align:center;

}



.valor-posicao-mercedes{

    font-size:70px;

    font-weight:900;

    color:#00d2be;


    text-shadow:

    0 0 20px
    rgba(0,210,190,.5);

}



.card-campeonato-mercedes p,
.card-pontos-mercedes p{


    margin:10px 0 0;


    color:#bbb;


    font-weight:700;

    text-transform:uppercase;

    font-size:14px;

}



/* =====================================
   PONTOS
===================================== */


#pontosmercedes{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-mercedes{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-mercedes svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficomercedes{


    stroke:#00d2be;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(0,210,190,.8)
    );


}

/* =====================================
   DESEMPENHO mercedes
===================================== */

.desempenho-mercedes{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-mercedes > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(0,210,190,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-mercedes > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(0,210,190,.55);



    box-shadow:

    0 0 25px
    rgba(0,210,190,.25);


}



/* números */

.desempenho-mercedes span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#00d2be;



    text-shadow:

    0 0 15px
    rgba(0,210,190,.45);


}



/* textos */

.desempenho-mercedes p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-mercedes span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(0,210,190,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(0,210,190,.75);

    }


}



/* =====================================
   DESTAQUE mercedes
===================================== */


.card-campeonato-mercedes::before,
.card-pontos-mercedes::before,
.card-grafico-mercedes::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(0,210,190,.12),
        transparent 45%
    );


    pointer-events:none;


}



/* garante posição dos cards */

.card-campeonato-mercedes,
.card-pontos-mercedes,
.card-grafico-mercedes{


    position:relative;


    overflow:hidden;


}

/* =====================================
   RESULTADOS mercedes
===================================== */

.resultados-mercedes{

    margin-top:45px;

    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );

    border-radius:25px;

    padding:25px;

    border:

    1px solid
    rgba(0,210,190,.18);

    box-shadow:

    0 15px 35px
    rgba(0,0,0,.4);

    overflow:hidden;

}



/* tabela */

.resultados-mercedes table{

    width:100%;

    border-collapse:collapse;

}



/* cabeçalho */

.resultados-mercedes th{


    padding:16px;


    background:

    rgba(0,210,190,.15);


    color:#00d2be;


    text-transform:uppercase;


    font-size:14px;


    letter-spacing:1px;

}



/* células */

.resultados-mercedes td{


    padding:14px;


    text-align:center;


    color:#ddd;


    border-bottom:

    1px solid
    rgba(255,255,255,.06);


    font-weight:600;

	  font-size:25px;

}



/* hover linha */

.resultados-mercedes tbody tr{


    transition:.3s ease;


}



.resultados-mercedes tbody tr:hover{


    background:

    rgba(0,210,190,.08);


    transform:

    scale(1.01);

}



/* primeira coluna */

.resultados-mercedes td:first-child{


    color:#00d2be;


    font-weight:900;

}



/* =====================================
   TOTAL PONTOS
===================================== */


.total-mercedes{


    margin-top:25px;


    padding:18px;


    border-radius:18px;


    text-align:center;


    background:

    linear-gradient(
        145deg,
        #00d2be,
        #00d2ff
    );


    color:#fff;


    font-size:22px;


    font-weight:900;


    box-shadow:

    0 0 25px
    rgba(0,210,190,.35);

}



#totalTabelamercedes{


    font-size:32px;


    margin-left:8px;

}



/* =====================================
   RESPONSIVO TABLET
===================================== */


@media(max-width:900px){


    .topo-temp-mercedes{


        grid-template-columns:

        1fr;


    }


    .card-grafico-mercedes{


        height:260px;

    }


    .desempenho-mercedes{


        grid-template-columns:

        repeat(2,1fr);

    }


}



/* =====================================
   RESPONSIVO CELULAR
===================================== */


@media(max-width:600px){


    .temporada-mercedes{


        padding:

        55px 14px;

    }



    .titulo-temp-mercedes{


        font-size:2rem;


