    .desempenho-mercedes > div{


        padding:18px 10px;

    }



    .desempenho-mercedes span{


        font-size:32px;

    }



    .resultados-mercedes{


        padding:12px;


        overflow-x:auto;

    }



    .resultados-mercedes table{


        min-width:500px;

    }



    .resultados-mercedes th,
    .resultados-mercedes td{


        padding:10px;


        font-size:12px;

    }



    .total-mercedes{


        font-size:18px;

    }


    #totalTabelamercedes{


        font-size:25px;

    }

}



/* =====================================
   CELULARES PEQUENOS
===================================== */


@media(max-width:400px){


    .desempenho-mercedes{


        grid-template-columns:

