/*==================================================
        HEADER
==================================================*/

.mercedes-header{

    width:100%;
    height:90px;

    position:relative;

    display:flex;

    align-items:center;

    justify-content:center;

}


.mercedes-title-wrap{

    text-align:center;

}


.mercedes-title-wrap h2{

    margin:0;

    font-size:clamp(30px,4vw,55px);

    line-height:1;

    font-weight:1000;

    color:white;

    text-shadow:
    0 0 25px rgba(0,210,190,.5);

}


.mercedes-title-wrap p{

    margin:7px 0 0;

    font-size:16px;

    font-weight:800;

    letter-spacing:6px;

    color:#f0f0f0;

}


.mercedes-team-logo{

    position:absolute;

    right:10px;

    top:50%;

    transform:translateY(-50%);

    height:75px;

    width:auto;

    filter:
    drop-shadow(
        0 0 20px rgba(0,210,190,.6)
    );

}


/*==================================================
        LAYOUT PRINCIPAL
==================================================*/

.mercedes-layout{

    width:100%;

    height:calc(100% - 90px);

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        minmax(430px,560px)
        minmax(0,1fr);

    align-items:center;

    gap:20px;

}


/*==================================================
        PILOTO ESQUERDO
==================================================*/

.mercedes-left{

    height:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:flex-start;

    overflow:hidden;

}


.mercedes-left-name{

    width:100%;

    text-align:center;

    flex-shrink:0;

    z-index:5;

}


.mercedes-left-name span{

    display:block;

    margin-bottom:4px;

    font-size:16px;

    font-weight:800;

    letter-spacing:5px;

    color:#ffffff;

}


.mercedes-left-name h3{

    margin:0;

    font-size:clamp(38px,4vw,64px);

    line-height:.85;

    font-weight:1000;

    letter-spacing:-3px;

    color:#00d2be;

    text-shadow:
    0 0 20px rgba(0,210,190,.4);

}


/*==================================================
        IMAGEM NORRIS
==================================================*/

.mercedes-left-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.mercedes-left-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(0,210,190,.3)
    );

    transition:
    transform .4s ease;

	 transform:translateY(-70px);

}


.mercedes-left-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        PILOTO DIREITO
==================================================*/

.mercedes-right{

    height:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:flex-start;

    overflow:hidden;

}


.mercedes-right-name{

    width:100%;

    text-align:center;

    flex-shrink:0;

    z-index:5;

}


.mercedes-right-name span{

    display:block;

    margin-bottom:4px;

    font-size:16px;

    font-weight:800;

    letter-spacing:5px;

    color:#ffffff;

}


.mercedes-right-name h3{

    margin:0;

    font-size:clamp(38px,4vw,64px);

    line-height:.85;

    font-weight:1000;

    letter-spacing:-3px;

    color:#00d2be;

    text-shadow:
    0 0 20px rgba(0,210,190,.4);

}


/*==================================================
        IMAGEM PIASTRI
==================================================*/

.mercedes-right-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.mercedes-right-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(0,210,190,.3)
    );

    transition:
    transform .4s ease;

	  transform:translateY(-70px);

}


.mercedes-right-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        CENTRO
==================================================*/

.mercedes-middle{

    width:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:center;

    position:relative;

    z-index:10;

}


/*==================================================
        VS
==================================================*/

.mercedes-vs{

    display:flex;

    align-items:center;

    justify-content:center;

    margin-bottom:12px;

}


.mercedes-vs-box{

    width:75px;

    height:75px;

    display:flex;

    align-items:center;

    justify-content:center;

    border-radius:50%;

    font-size:30px;

    font-weight:1000;

    color:#f0f0f0;

    background:#00d2be;

    border:4px solid white;

    box-shadow:
    0 0 30px rgba(0,210,190,.65);

}


/*==================================================
        TEMPORADA
==================================================*/

.mercedes-season{

    margin-bottom:20px;

    text-align:center;

    font-size:17px;

    font-weight:800;

    letter-spacing:4px;

    color:#f0f0f0;

}


/*==================================================
        ESTATÍSTICAS
==================================================*/

.mercedes-stats{

    width:100%;

    display:flex;

    flex-direction:column;

    gap:13px;

}


/*==================================================
        CADA ESTATÍSTICA
==================================================*/

.mercedes-stat{

    width:100%;

}


/*==================================================
        VALORES

        NORRIS | LABEL | PIASTRI
==================================================*/

.mercedes-stat-values{

    width:100%;

    display:grid;

    grid-template-columns:
        70px
        1fr
        70px;

    align-items:center;

}


.mercedes-value{

    display:flex;

    align-items:center;

    justify-content:center;

    font-size:28px;

    line-height:1;

    font-weight:1000;

    color:white;

}


.mercedes-label{

    text-align:center;

    font-size:14px;

    font-weight:900;

    letter-spacing:2px;

    color:#00d2be;

    white-space:nowrap;

}


/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.mercedes-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.mercedes-bar-left,
.mercedes-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.mercedes-bar-left{

    border-radius:999px 0 0 999px;

}


.mercedes-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #c0c0c0,
        #00d2be
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.mercedes-bar-right{

    border-radius:0 999px 999px 0;

}


.mercedes-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #00d2be,
        #c0c0c0
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.mercedes-value{

    animation:
    mercedesValueShow .5s ease;

}


@keyframes mercedesValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.mercedes-winner{

    color:#00d2be !important;

    text-shadow:
    0 0 15px rgba(0,210,190,.8);

}


.mercedes-draw{

    color:#020202 !important;

}


