    min-height:560px;

    margin:0;

    padding:35px;

    box-sizing:border-box;

    border-radius:0;

    background:
    linear-gradient(
        120deg,
        #0a0a0a 40%,
        #00d2be 120%
    );

    box-shadow:none;

}


/*==================================================
        TOPO
==================================================*/

.evolution-card-top-mercedes{

    width:100%;

    display:flex;

    align-items:center;

    justify-content:space-between;

    gap:25px;

    margin-bottom:28px;

}


.evolution-intro-mercedes h3{

    margin:0;

    font-size:25px;

    font-weight:900;

    letter-spacing:-1px;

}


.evolution-intro-mercedes h3 span{

    font-weight:400;

    margin:0 5px;

}


.evolution-intro-mercedes p{

    margin:6px 0 0;

    color:#92929a;

    font-size:14px;

}



/*==================================================
        SELETOR
==================================================*/

.evolution-selector-mercedes{

    display:flex;

    align-items:center;

    padding:4px;

    border-radius:8px;

    background:#29292f;

    border:1px solid #3c3c43;

}


.evolution-mode-mercedes{

    border:0;

    background:transparent;

    color:#aaaab0;

    padding:11px 18px;

    border-radius:6px;

    font-size:13px;

    font-weight:800;

    cursor:pointer;

    transition:.25s ease;

}


.evolution-mode-mercedes:hover{

    color:white;

}


.evolution-mode-mercedes.active{

    background:#f0f0f0;

    color:#111;

}



/*==================================================
        CONTENT
==================================================*/

.evolution-content-mercedes{

    width:100%;

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        240px;

    gap:40px;

}



/*==================================================
        GRÁFICO
==================================================*/

.evolution-chart-area-mercedes{

    min-width:0;

    position:relative;

}


.y-axis-title-mercedes{

    position:absolute;

    left:-65px;

    top:50%;

    transform:
    translateY(-50%)
    rotate(-90deg);

    color:#777780;

    font-size:22px;

    letter-spacing:1px;

    font-weight:700;

}


.evolution-chart-mercedes{

    width:100%;

    height:400px;

    display:grid;

    grid-template-columns:45px 1fr;

}


.chart-y-labels-mercedes{

    height:100%;

    display:flex;

    flex-direction:column;

    justify-content:space-between;

    align-items:flex-end;

    padding:0 10px 0 0;

    box-sizing:border-box;

}


.chart-y-labels-mercedes span{

    color:#73737b;

    font-size:20px;

}



/*==================================================
        ÁREA DAS LINHAS
==================================================*/

.chart-main-mercedes{

    position:relative;

    width:100%;

    height:100%;

    border-left:1px solid #38383f;

    border-bottom:1px solid #38383f;

    background:
    repeating-linear-gradient(
        to bottom,
        transparent 0,
        transparent calc(10% - 1px),
        #292930 calc(10% - 1px),
        #292930 10%
    );

}



/*==================================================
        GRID VERTICAL
==================================================*/

.chart-grid-mercedes{

    position:absolute;

    inset:0;

    display:flex;

}


.chart-grid-line-mercedes{

    flex:1;

    border-right:1px solid rgba(255,255,255,.06);

}



/*==================================================
        SVG
==================================================*/

.evolution-svg-mercedes{

    position:absolute;

    inset:0;

    width:100%;

    height:100%;

    overflow:visible;

}


.russell-path-mercedes{

    fill:none;

    stroke:#00d2be;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}


.antonelli-path-mercedes{

    fill:none;

    stroke:#c0c0c0;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}



/*==================================================
        ÁREA ABAIXO DA LINHA
==================================================*/

.russell-area-mercedes{

    fill:url(#russellGradient);

    opacity:.12;

}


.antonelli-area-mercedes{

    fill:url(#antonelliGradient);

    opacity:.08;

}



/*==================================================
        PONTOS
==================================================*/

.chart-point-mercedes{

    fill:#121217;

    stroke:#00d2be;

    stroke-width:3;

}


.chart-point-mercedes.antonelli-mercedes{

    stroke:#c0c0c0;

}



/*==================================================
        VALORES
==================================================*/

.chart-value-mercedes{

    fill:#eee;

    font-size:18px;

    font-weight:700;

    text-anchor:middle;

}


.chart-year-mercedes{

    fill:#777780;

    font-size:20px;

    text-anchor:middle;

}



/*==================================================
        SIDEBAR
==================================================*/

.evolution-sidebar-mercedes{

    padding-top:5px;

}


.sidebar-title-mercedes{

    color:#85858d;

    font-size:13px;

    letter-spacing:1px;

    font-weight:700;

    margin-bottom:16px;

}



/*==================================================
        IDENTIDADE
==================================================*/

.driver-identity-mercedes{

	  background:#15151a;

    display:flex;

    align-items:center;

    gap:12px;

    margin-bottom:20px;

}


.identity-line-mercedes{

    width:42px;

    height:3px;

    position:relative;

}


.identity-line-mercedes span{

    position:absolute;

    width:9px;

    height:9px;

    border-radius:50%;

    top:50%;

    left:50%;

    transform:translate(-50%,-50%);

    background:#ffffff;

    border:2px solid currentColor;

}


.russell-line-mercedes{

    background:#00d2be;

    color:#00d2be;

}


.antonelli-line-mercedes{

    background:#c0c0c0;

    color:#c0c0c0;

}


.driver-identity-mercedes small{

    display:block;

    color:#9999a0;

    font-size:11px;

}


.driver-identity-mercedes strong{

    display:block;

    color:#eee;

    font-size:14px;

}

/*==================================================
        IMAGENS - LINE IDENTITY
==================================================*/

.identity-driver-info-mercedes{

    display:flex;

    flex-direction:column;

    justify-content:center;

}


.identity-driver-image-mercedes{

    width:80px;

    height:80px;

    object-fit:contain;

    object-position:center bottom;

    align-self:flex-end;

    margin-left:auto;

}

/*==================================================
        LEGEND
==================================================*/

.legend-title-mercedes{

    margin-top:40px;

}


.driver-legend-mercedes{

    height:68px;

    margin-bottom:12px;

    padding:8px 10px 8px 15px;

    box-sizing:border-box;

    display:flex;

    align-items:center;

    justify-content:space-between;

    border:1px solid #00d2be;

    border-radius:8px;

    background:#17171c;

}


.legend-info-mercedes span{

    display:block;

    color:#ffffff;

    font-size:11px;

}


.legend-info-mercedes strong{

    display:block;

    color:#fff;

