}


.driver-legend-mercedes img{

    height:58px;

    width:auto;

    object-fit:contain;

    align-self:flex-end;

}



/*==================================================
        ANIMAÇÃO
==================================================*/

.evolution-svg-mercedes path{

    stroke-dasharray:3000;

    stroke-dashoffset:3000;

    animation:
    drawEvolution 1.5s ease forwards;

}


@keyframes drawEvolution{

    to{

        stroke-dashoffset:0;

    }

}


.chart-point-mercedes{

    opacity:0;

    animation:
    pointShow .3s ease forwards;

}


@keyframes pointShow{

    to{

        opacity:1;

    }

}



/*==================================================
        RESPONSIVO
==================================================*/

@media(max-width:900px){

    .evolution-card-mercedes{

        padding:25px 20px;

    }


    .evolution-card-top-mercedes{

