        padding:25px 8px;

    }


    .evolution-header-mercedes h2{

        font-size:32px;

        letter-spacing:-1px;

    }


    .evolution-header-mercedes p{

        font-size:15px;

    }


    .evolution-card-mercedes{

        padding:20px 12px;

        border-radius:10px;

    }


    .evolution-selector-mercedes{

        width:100%;

    }


    .evolution-mode-mercedes{

        flex:1;

        padding:10px 5px;

        font-size:11px;

    }


    .evolution-intro-mercedes h3{

        font-size:18px;

    }


    .evolution-chart-mercedes{

