    }


    .y-axis-title-mercedes{

        display:none;

    }


    .evolution-sidebar-mercedes{

        grid-template-columns:1fr;

    }


    .sidebar-title-mercedes{

        grid-column:auto;

    }

}


/* =========================================================
   mercedes — LIDERANÇA / COMMAND CENTER
========================================================= */

.mercedes-lideranca {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 650px;

    box-sizing: border-box;

    overflow: hidden;

    padding: 35px 5vw 25px;

    color: #fff;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(0,210,190,.16),
            transparent 30%
        ),
        radial-gradient(
            circle at 90% 80%,
            rgba(0,210,190,.10),
            transparent 30%
        ),
        #050505;

    isolation: isolate;
}


/* =========================================================
   GRID TÉCNICO DO FUNDO
========================================================= */

.mercedes-lideranca::before {
    content: "";

    position: absolute;

    inset: 0;

    z-index: -2;

    opacity: .35;

    background-image:
        linear-gradient(
            rgba(255,255,255,.025) 1px,
            transparent 1px
        ),
        linear-gradient(
            90deg,
            rgba(255,255,255,.025) 1px,
            transparent 1px
        );

    background-size: 55px 55px;

    pointer-events: none;
}


/* LINHA VERMELHA LATERAL */

.mercedes-lideranca::after {
    content: "";

    position: absolute;

    top: 0;
    right: 0;

    width: 3px;
    height: 100%;

    background:
        linear-gradient(
            to bottom,
            transparent,
            #00D2BE 25%,
            #00D2BE 75%,
            transparent
        );

    box-shadow:
        0 0 20px rgba(0,210,190,.35);

    pointer-events: none;
}


/* =========================================================
   HEADER
========================================================= */

.mercedes-lideranca-header {
    position: relative;

    width: 100%;
    max-width: 1500px;

    margin: 0 auto;
}


/* KICKER */

.mercedes-lideranca-kicker {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 8px;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 5px;

    color: rgba(255,255,255,.45);
}


.mercedes-lideranca-kicker span {
    width: 35px;
    height: 2px;

    background: #00D2BE;

    box-shadow:
        0 0 10px rgba(0,210,190,.6);
}


/* =========================================================
   TÍTULO
========================================================= */

.mercedes-lideranca-titulo-area {
    display: flex;

    align-items: center;

    gap: 18px;
}


.mercedes-lideranca-indice {
    width: 46px;
    height: 46px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border: 1px solid rgba(0,210,190,.6);

    background:
        linear-gradient(
            135deg,
            rgba(0,210,190,.18),
            rgba(0,210,190,.02)
        );

    color: #00D2BE;

    font-size: 11px;

    font-weight: 900;

    box-shadow:
        inset 0 0 20px rgba(0,210,190,.08);
}


.mercedes-lideranca-subtitulo {
    display: block;

    margin-bottom: 4px;

    font-size: 7px;

    font-weight: 900;

    letter-spacing: 4px;

    color: rgba(255,255,255,.32);
}


.mercedes-lideranca-titulo {
    margin: 0;

    font-size:
        clamp(32px, 4vw, 58px);

    line-height: .9;

    font-weight: 200;

    letter-spacing: -2px;

    text-transform: uppercase;
}


.mercedes-lideranca-titulo strong {
    font-weight: 900;

    color: #00D2BE;

    text-shadow:
        0 0 30px rgba(0,210,190,.18);
}


.mercedes-lideranca-descricao {
    margin: 7px 0 0;

    font-size: 9px;

    color: rgba(255,255,255,.5);

    letter-spacing: .3px;
}


/* =========================================================
   LINHA DO HEADER
========================================================= */

.mercedes-lideranca-linha {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: 1px;

    margin:
        17px auto 15px;

    background:
        linear-gradient(
            90deg,
            #00D2BE,
            rgba(255,255,255,.12),
            transparent
        );
}


.mercedes-lideranca-linha span {
    position: absolute;

    left: 0;
    top: -2px;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: #00D2BE;

    box-shadow:
        0 0 12px rgba(0,210,190,.8);
}


/* =========================================================
   GRID DOS LÍDERES
========================================================= */

.mercedes-lideranca-estrutura {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: calc(100% - 185px);

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        1.15fr 1.15fr .9fr .9fr;

    grid-template-rows:
        1fr 1fr;

    gap: 10px;
}


/* =========================================================
   CARD
========================================================= */

.mercedes-lideranca-card {
    position: relative;

    min-width: 0;
    min-height: 0;

    overflow: hidden;

    cursor: pointer;

    border:
        1px solid rgba(255,255,255,.12);

    background: #0b0b0b;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1),
        border-color .45s ease,
        box-shadow .45s ease;
}


/* BRILHO NO CARD */

.mercedes-lideranca-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: -120%;

    width: 70%;
    height: 100%;

    z-index: 5;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12),
            transparent
        );

    transform: skewX(-20deg);

    transition:
        left .7s ease;

    pointer-events: none;
}


/* LINHA INFERIOR */

.mercedes-lideranca-card::after {
    content: "";

    position: absolute;

    left: 0;
    bottom: 0;

    width: 0;
    height: 3px;

    z-index: 15;

    background:
        linear-gradient(
            90deg,
            #00D2BE,
            #9bf7f3,
            transparent
        );

    transition:
        width .5s ease;
}


/* HOVER */

.mercedes-lideranca-card:hover {
    transform:
        translateY(-7px)
        scale(1.015);

    border-color:
        rgba(0,210,190,.7);

    box-shadow:
        0 20px 50px rgba(0,0,0,.65),
        0 0 35px rgba(0,210,190,.12);
}


.mercedes-lideranca-card:hover::before {
    left: 140%;
}


.mercedes-lideranca-card:hover::after {
    width: 100%;
}


/* =========================================================
   TOPO DOS CARDS
========================================================= */

.mercedes-lideranca-card-topo {
    position: absolute;

    top: 12px;
    left: 13px;
    right: 13px;

    z-index: 12;

    display: flex;

    justify-content: space-between;

    align-items: center;
}


.mercedes-lideranca-card-numero {
    font-size: 8px;

    font-weight: 900;

    letter-spacing: 2px;

    color: rgba(255,255,255,.55);
}


.mercedes-lideranca-card-cargo {
    padding: 5px 7px;

    background:
        rgba(0,0,0,.65);

    border:
        1px solid rgba(255,255,255,.14);

    backdrop-filter: blur(8px);

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 1.5px;

    color: rgba(255,255,255,.65);

    transition:
        background .4s ease,
        border-color .4s ease,
        color .4s ease;
}


.mercedes-lideranca-card:hover
.mercedes-lideranca-card-cargo {
    background:
        rgba(0,210,190,.25);

    border-color:
        rgba(0,210,190,.6);

    color: #fff;
}


/* =========================================================
   FOTO
========================================================= */

.mercedes-lideranca-foto {
    position: absolute;

    inset: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.mercedes-lideranca-foto img {
    width: 100%;
    height: 100%;

    object-fit: cover;

    display: block;

    opacity: .72;

    filter:
        grayscale(.35)
        contrast(1.12)
        brightness(.72);

    transform: scale(1.02);

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


.mercedes-lideranca-card:hover
.mercedes-lideranca-foto img {
    transform: scale(1.09);

    opacity: .9;

    filter:
        grayscale(0)
        contrast(1.08)
        brightness(.88);
}


/* =========================================================
   OVERLAY DA FOTO
========================================================= */

.mercedes-lideranca-foto-overlay {
    position: absolute;

    inset: 0;

    z-index: 2;

    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.1) 0%,
            transparent 30%,
            rgba(0,0,0,.35) 50%,
            rgba(0,0,0,.96) 100%
        );

    transition:
        background .5s ease;
}


.mercedes-lideranca-card:hover
.mercedes-lideranca-foto-overlay {
    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.05),
            rgba(0,210,190,.05) 45%,
            rgba(0,0,0,.94)
        );
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.mercedes-lideranca-info {
    position: absolute;

    left: 16px;
    right: 16px;
    bottom: 15px;

    z-index: 10;
}


.mercedes-lideranca-funcao {
    display: block;

    margin-bottom: 5px;

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 2px;

    color: #ffffff;

    transition:
        color .35s ease;
}


.mercedes-lideranca-card:hover
.mercedes-lideranca-funcao {
    color: #9bf7f3;
}


.mercedes-lideranca-info h3 {
    margin: 0;

    font-size:
        clamp(19px, 1.8vw, 29px);

    line-height: .9;

    font-weight: 200;

    letter-spacing: -1px;

    color: #fff;

    text-shadow:
        0 3px 15px rgba(0,0,0,.9);
}


.mercedes-lideranca-info h3 strong {
    font-weight: 900;
	color: #00D2BE;
}


.mercedes-lideranca-info p {
    max-width: 340px;

    margin: 8px 0 0;

    font-size: 7px;

    line-height: 1.45;

    color: rgba(255,255,255,.62);

    transition:
        color .35s ease;
}


.mercedes-lideranca-card:hover
.mercedes-lideranca-info p {
    color: rgba(255,255,255,.82);
}


/* =========================================================
   CARDS PRINCIPAIS
========================================================= */

.mercedes-lideranca-card-destaque,
.mercedes-lideranca-card-principal {
    border-color:
        rgba(0,210,190,.3);
}


.mercedes-lideranca-card-destaque
.mercedes-lideranca-info h3,
.mercedes-lideranca-card-principal
.mercedes-lideranca-info h3 {
    font-size:
        clamp(23px, 2.2vw, 36px);
}


/* =========================================================
   CARD DE ENGENHARIA
========================================================= */

.mercedes-lideranca-foto-logo {
    background:
        radial-gradient(
            circle,
            rgba(0,210,190,.14),
            transparent 65%
        );
}


.mercedes-lideranca-foto-logo img {
    width: 100%;
    height: auto;

    object-fit: contain;

    opacity: .65;

    filter:
        drop-shadow(
            0 0 25px rgba(0,210,190,.4)
        );

    transition:
        transform .6s ease,
        opacity .5s ease,
        filter .5s ease;
}


.mercedes-lideranca-card:hover
.mercedes-lideranca-foto-logo img {
    transform:
        scale(1.12);

    opacity: 1;

    filter:
        drop-shadow(
            0 0 35px rgba(0,210,190,.7)
        );
}


/* =========================================================
   FOOTER
========================================================= */

.mercedes-lideranca-footer {
    position: absolute;

    left: 5vw;
    right: 5vw;
    bottom: 10px;

    z-index: 20;

    display: flex;

    align-items: center;

    gap: 15px;

    font-size: 5px;

    font-weight: 900;

    letter-spacing: 3px;

    color: rgba(255,255,255,.3);
}


.mercedes-lideranca-footer div {
    flex: 1;

    height: 1px;

    background:
        linear-gradient(
            90deg,
            rgba(0,210,190,.6),
            rgba(255,255,255,.1),
            transparent
        );
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width:900px) {

    .mercedes-lideranca {
        padding:
            30px 20px 20px;
    }

    .mercedes-lideranca-estrutura {
        grid-template-columns:
            repeat(3, 1fr);

        grid-template-rows:
            repeat(3, 1fr);

        height: calc(100% - 180px);
    }

    .mercedes-lideranca-info h3 {
        font-size: 18px;
    }

    .mercedes-lideranca-info p {
        font-size: 6px;
    }

}


