    .mercedes-lideranca {
        height: 100dvh;

        min-height: 650px;

        padding:
            22px 12px 12px;
    }


    /* HEADER */

    .mercedes-lideranca-kicker {
        font-size: 6px;

        letter-spacing: 3px;
    }

    .mercedes-lideranca-kicker span {
        width: 20px;
    }

    .mercedes-lideranca-titulo-area {
        gap: 10px;
    }

    .mercedes-lideranca-indice {
        width: 32px;
        height: 32px;

        font-size: 8px;
    }

    .mercedes-lideranca-subtitulo {
        font-size: 5px;

        letter-spacing: 2px;
    }

    .mercedes-lideranca-titulo {
