  overflow:hidden;
}

/* TÍTULO */
.titulo-timeline-mercedes{
  text-align:center;
  color:#00a19c;
  text-shadow: 
    0 0 10px #00a19c,
    0 0 20px #00a19c,
    0 0 30px #00a19c;

  font-size:42px;
  margin-bottom:300px;

  box-shadow:0 15px 40px rgba(0,0,0,0.7);
}

/* LINHA */
.linha-box-mercedes{
  position:relative;
  width:100%;
  height:4px;
  margin-bottom:400px;
}

.linha-cinza-mercedes{
  position:absolute;
  width:100%;
  height:4px;
  background:#444;
  margin-bottom:400px;
}

.linha-progresso-mercedes{
  position:absolute;
  width:0%;
  height:4px;

  background:linear-gradient(90deg,#00a19c,#5eead4);
  box-shadow:0 0 15px #00a19c;

  transition:width .8s;
  margin-bottom:400px;
}

.luz-mercedes{
  position:absolute;
  width:60px;
  height:8px;

  background:linear-gradient(90deg,transparent,#ffffff,transparent);

  top:-2px;
  left:-60px;

  filter:blur(4px);
}

/* PONTO */
.ponto-mercedes{
  position:absolute;
  top:30%;
  transform:translate(-50%,-50%);
  text-align:center;
  transition:0.3s ease;
}

.ponto-mercedes:hover{
  z-index:20;
}

.ponto-mercedes::after{
  content:"";
  width:10px;
  height:10px;

  background:#888;
  display:block;
  border-radius:50%;
  margin:8px auto;

  transition:.4s;
}

.ponto-mercedes.ativo::after{
  background:#00a19c;
  box-shadow:0 0 12px #00a19c;
}

/* ANO */
.ano-mercedes{
  position:absolute;
  left:50%;
  transform:translateX(-50%);

  font-size:30px;
  color:#00a19c;

  opacity:0;
  font-weight:600;

  transition:0.3s ease;
}

.ano-mercedes.cima{
  top:30px;
}

.ano-mercedes.baixo{
  top:-30px;
}

/* TROFÉU */
.titulo-num-mercedes{
  font-size:24px;

  padding:4px 10px;

  border-radius:20px;

  background:#111;

  color:#5eead4;

  border-left:3px solid #00a19c;

  font-weight:700;
  letter-spacing:1px;

  box-shadow:0 4px 10px rgba(0,0,0,0.35);

  transition:0.3s ease;
}

/* HOVER TROFÉU */
.ponto-mercedes:hover .titulo-num-mercedes{
  transform:scale(1.08);

  background:#1a1a1a;

  color:#7ff6e9;

  box-shadow:0 0 12px rgba(0,161,156,0.35);
}

/* ANO HOVER */
.ponto-mercedes:hover .ano-mercedes{
  transform:
  translateX(-50%)
  translateY(-6px)
  scale(1.08);

  color:#5eead4;

  text-shadow:
  0 0 10px rgba(0,161,156,0.9),
  0 0 20px rgba(0,161,156,0.45);
}

.ponto-mercedes.ativo .ano-mercedes{
  opacity:1;
}

/* FOTO */
.foto-cima-mercedes,
.foto-baixo-mercedes{
  position:absolute;
  left:50%;
  transform:translateX(-50%) scale(.6);
  opacity:0;
  transition:.6s;
}

.foto-cima-mercedes img,
.foto-baixo-mercedes img{
  width:90px;
  border-radius:12px;
  border:2px solid #00a19c;
  transition:transform 0.45s ease, filter 0.45s ease;
}

.foto-cima-mercedes img:hover,
.foto-baixo-mercedes img:hover{
  transform:scale(1.12) rotate(-2deg);

  filter:
  drop-shadow(0 0 10px rgba(0,161,156,0.7))
  drop-shadow(0 0 25px rgba(0,161,156,0.35));
}

