.info-baixo-mercedes{
  position:absolute;
  left:50%;
  transform:translateX(-50%);
  color:#00a19c;

  opacity:0;
  transition:0.3s ease;
}

/* HOVER INFO */
.info-cima-mercedes:hover,
.info-baixo-mercedes:hover{
  transform:translateX(-50%) translateY(-6px);
  filter:brightness(1.08);
}

/* TEXTO INFO */
.info-cima-mercedes p,
.info-baixo-mercedes p{
  font-size:25px;
  margin-top:30px;

  color:#5eead4;

  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;

  white-space:nowrap;
}

/* POSIÇÕES */
