.info-baixo-mercedes{ top:-6px; }

.ponto-mercedes.ativo .foto-cima-mercedes,
.ponto-mercedes.ativo .foto-baixo-mercedes{
  opacity:1;
  transform:translateX(-50%) scale(1);
}

.ponto-mercedes.ativo .info-cima-mercedes,
.ponto-mercedes.ativo .info-baixo-mercedes{
