  filter:blur(6px);
  left:0;

  transition:1.2s;
}

/* PONTO */
.ponto-car-mercedes{
  position:absolute;
  top:50%;
  transform:translate(-50%,-50%);
  width:10px;
  height:10px;

  background:#00a19c;
  border-radius:50%;

  z-index:3;
}

/* FOTO */
.foto-car-mercedes{
