.hall-mercedes{
padding:120px 40px;
position:relative;
background:
linear-gradient(120deg,#0a0a0a 40%,#00d2be 140%);
min-height: 100vh;
overflow:hidden;
}

/* TÍTULO */
.titulo-hall-mercedes{
text-align:center;
font-size:52px;
color:#00d2be;
margin-bottom:80px;
text-shadow:
0 0 12px rgba(0,210,190,0.7);
}

/* GRID */
.hall-grid-mercedes{
display:flex;
justify-content:center;
align-items:flex-start;
flex-wrap:wrap;
perspective: 1200px;
gap:40px;
position:relative;
z-index:3;
}

.bg-hall-mercedes{
position: absolute;
inset: 0;
z-index: 0;
}

.bg-layer-mercedes{
position: absolute;
inset: 0;
background-size: cover;
background-position: center;
opacity: 0;
transition: opacity .8s ease;
}

.bg-layer-mercedes.active{
opacity: 1;
}

.hall-grid-mercedes,
.titulo-hall-mercedes,
.hall-overlay-mercedes{
position: relative;
z-index: 2;
}

/* CARD */
.hall-card-mercedes{
position:relative;
width:320px;
padding:30px;
border-radius:24px;
background: rgba(15,15,15,0.55);
border:1px solid rgba(0,210,190,0.25);
overflow:hidden;
transition:0.45s ease;
box-shadow:
0 15px 35px rgba(0,0,0,0.45);
text-align:center;
backdrop-filter: blur(6px);
transform-origin:center top;
}

/* HOVER */
.hall-card-mercedes:hover{
transform: translateY(-14px) scale(1.04);
background: rgba(15,15,15,0.92);
box-shadow:
0 25px 60px rgba(0,0,0,0.7),
0 0 30px rgba(0,210,190,0.25);
z-index: 10;
}

.hall-grid-mercedes:hover .hall-card-mercedes{
opacity: 0.35;
transform: scale(0.98);
}

.hall-card-mercedes:hover{
opacity: 1 !important;
transform: translateY(-14px) scale(1.06);
}

/* NÚMERO */
.numero-hall-mercedes{
position:absolute;
top:15px;
right:20px;
font-size:70px;
font-weight:900;
color:rgba(0,210,190,0.08);
}

/* FOTO */
.hall-card-mercedes img{
width:170px;
height:200px;
object-fit:cover;
border-radius:50%;
border:3px solid #00d2be;
margin-bottom:20px;
filter: grayscale(100%) brightness(0.9);
transition:0.5s ease;
}

.hall-card-mercedes:hover img{
filter: grayscale(0%) brightness(1.1);
transform: scale(1.1);
}

/* ANIMAÇÃO TEXTO */
.hall-card-mercedes p,
.hall-stats-mercedes,
.frase-hall-mercedes {
opacity: 0;
transform: translateY(10px);
max-height: 0;
overflow: hidden;
transition: 0.4s ease;
}

.hall-card-mercedes:hover p,
.hall-card-mercedes:hover .hall-stats-mercedes,
.hall-card-mercedes:hover .frase-hall-mercedes {
opacity: 1;
transform: translateY(0);
max-height: 200px;
}

/* NOME */
.hall-card-mercedes h3{
font-size:32px;
color:#fff;
margin-bottom:10px;
}

/* PAÍS */
.pais-hall-mercedes{
display:block;
font-size:18px;
color:#00d2be;
margin-bottom:18px;
}

/* TEXTO */
.hall-card-mercedes p{
font-size:18px;
color:#ddd;
margin-bottom:22px;
}

/* STATS */
