.mercedes-evolution{
  position:relative;
  width:100%;
  padding:120px 25px;
  overflow:hidden;

  background:
  radial-gradient(circle at top,#1a1a1a 0%,#050505 60%);

  transition:background 1s ease;
}

/* 🔥 ERAS */

/* 1950s — prata clássico */
.mercedes-evolution.bg-50s{
  background:
  radial-gradient(circle at top,
    #dcdcdc 0%,
    #a6a6a6 25%,
    #5c5c5c 55%,
    #1a1a1a 80%,
    #050505 100%
  );
}

/* retorno 2010 — prata + cinza */
.mercedes-evolution.bg-2010s{
  background:
  radial-gradient(circle at top,
    #cfcfcf 0%,
    #7a7a7a 25%,
    #2a2a2a 55%,
    #0a0a0a 85%,
    #050505 100%
  );
}

/* era híbrida — verde Petronas */
.mercedes-evolution.bg-2014s{
  background:
  radial-gradient(circle at top,
    #ffffff 0%,
    #cfcfcf 15%,
    #00d2be 35%,
    #005f56 60%,
    #001a17 80%,
    #050505 100%
  );
}

/* domínio — verde + preto forte */
.mercedes-evolution.bg-2017s{
  background:
  radial-gradient(circle at top,
    #e6e6e6 0%,
    #00c2ad 25%,
    #003d36 55%,
    #001a17 75%,
    #050505 100%
  );
}

/* atual — verde mais escuro + preto */
.mercedes-evolution.bg-2020s{
  background:
  radial-gradient(circle at top,
    #00ffd5 0%,
    #00bfa6 25%,
    #004d44 55%,
    #001a17 75%,
    #050505 100%
  );
}

/* BRILHO */
.mercedes-evolution::before{
  content:"";
  position:absolute;
  top:-200px;
  left:-200px;

  width:500px;
  height:500px;

  background:
  radial-gradient(circle,
  rgba(0,210,190,.2),
  transparent 70%);

  filter:blur(30px);

  animation:glowMove 8s linear infinite;
}

.mercedes-evolution::after{
  content:"";
  position:absolute;
  right:-150px;
  bottom:-150px;

  width:450px;
  height:450px;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.05),
  transparent 70%);

  filter:blur(50px);
}

/* TÍTULO */
.title-mercedes{
  text-align:center;
  font-size:clamp(2.5rem,6vw,5rem);
  margin-bottom:80px;

  font-weight:900;
  letter-spacing:3px;
  text-transform:uppercase;

  background:
  linear-gradient(90deg,#ffffff,#00d2be);

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
}

/* CARRO */
.car-container-mercedes{
  position:relative;
  width:100%;
  max-width:900px;
  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;
}

/* BASE */
.car-container-mercedes::before{
  content:"";
  position:absolute;
  bottom:50px;

  width:70%;
  height:40px;

  background:
  radial-gradient(circle,
  rgba(0,210,190,.35),
  transparent 70%);

  filter:blur(20px);
  border-radius:50%;

  animation:pulseFloor 4s ease-in-out infinite;
}

/* CÍRCULO */
.car-circle-mercedes{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:2px solid rgba(0,210,190,.2);

  box-shadow:
  0 0 40px rgba(0,210,190,.2),
  inset 0 0 40px rgba(0,210,190,.08);

  animation:rotateCircle 14s linear infinite;
}

.car-circle-mercedes::before{
  content:"";
  position:absolute;
  inset:20px;

  border-radius:50%;
  border:1px dashed rgba(255,255,255,.08);
}

/* IMAGEM */
.car-container-mercedes img{
  width:100%;
  max-width:580px;

  filter:drop-shadow(0 30px 35px rgba(0,0,0,.6));

  animation:
  floatCar 5s ease-in-out infinite,
  rotateCar 6s ease-in-out infinite;

  transition:.45s;
}

/* BOTÕES */
.controls-mercedes{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin:50px 0 90px;
}

.controls-mercedes button{
  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(145deg,#00d2be,#009e8c);

  color:#000;
  font-weight:800;

  cursor:pointer;
  transition:.35s;
}

.controls-mercedes button:hover{
  transform:translateY(-6px) scale(1.05);

  box-shadow:
  0 10px 30px rgba(0,210,190,.35);
}

/* INFO */
.car-info-mercedes{
  max-width:1200px;
  margin:auto;
}

.car-info-mercedes h2{
  text-align:center;
  font-size:clamp(2rem,5vw,3.5rem);
  margin-bottom:50px;
  color:#fff;
}

/* GRID */
.info-grid-mercedes{
  display:grid;
  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));
  gap:25px;
}

/* CARD */
.info-card-mercedes{
  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
  145deg,
  rgba(255,255,255,.05),
  rgba(255,255,255,.02));

  border:1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  transition:.45s;
}

.info-card-mercedes:hover{
  transform:translateY(-12px);

  border-color:
  rgba(0,210,190,.4);

  box-shadow:
  0 15px 40px rgba(0,0,0,.45),
  0 0 25px rgba(0,210,190,.15);
}

.info-card-mercedes span{
  display:block;
  margin-bottom:14px;

  color:#00d2be;

  text-transform:uppercase;
  font-size:.8rem;
}

.info-card-mercedes h3{
  color:#fff;
}

/* ANIMAÇÕES (reaproveita as mesmas) */
@keyframes rotateCircle{
  from{transform:rotate(0deg);}
  to{transform:rotate(360deg);}
}

@keyframes floatCar{
  0%,100%{transform:translateY(0);}
  50%{transform:translateY(-15px);}
}

@keyframes rotateCar{
  0%,100%{rotate:y 0deg;}
  50%{rotate:y 10deg;}
}

@keyframes pulseFloor{
  0%,100%{transform:scale(.95);opacity:.5;}
  50%{transform:scale(1.05);opacity:1;}
}

@keyframes glowMove{
  0%{transform:translate(0,0);}
  50%{transform:translate(80px,40px);}
  100%{transform:translate(0,0);}
}


