    box-shadow:
    0 0 30px rgba(0,210,190,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#mercedes-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.mercedes-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(127,255,238,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.mercedes-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.mercedes-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.mercedes-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(127,255,238,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(0,210,190,.18);
}

/* ===== IMAGEM ===== */
.mercedes-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.mercedes-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(0,210,190,.28));
}

/* ===== ANO ===== */
.mercedes-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#7fffee;

    text-shadow:
    0 0 12px rgba(127,255,238,.3);
}

/* ===== TEXTO ===== */
#mercedes-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#efffff;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes mercedesGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-mercedes{
        padding:90px 18px;
    }

    .titulo-eras-mercedes{
        font-size:2.5rem;
    }

    #textoEra-mercedes{
        font-size:1rem;
    }

    .botoes-eras-mercedes{
        gap:10px;
    }

    .botoes-eras-mercedes button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #mercedes-timeline{
        grid-template-columns:1fr;
    }

    .mercedes-timeline-item{
        max-width:360px;
        margin:auto;
    }

}



