}

/* PONTO */
.ponto-redbull{
  position:absolute;

  top:30%;

  transform:translate(-50%,-50%);

  text-align:center;

  transition:.3s ease;
}

.ponto-redbull:hover{
  z-index:20;
}

/* CÍRCULO */
.ponto-redbull::after{
  content:"";

  width:12px;
  height:12px;

  background:#666;

  display:block;

  border-radius:50%;

  margin:8px auto;

  transition:.4s;
}

