  box-shadow:
    0 0 12px rgba(30,65,255,.6),
    0 0 28px rgba(255,30,30,.18);

  transition:1.2s;
}

/* LUZ */
.luz-car-redbull{
  position:absolute;

  top:-6px;

  width:70px;
  height:18px;

