.eras-redbull{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
    radial-gradient(circle at top,
    #4d79ff 0%,
    #001a70 35%,
    #000a2d 70%,
    #050505 100%);

    overflow:hidden;

    color:#eef3ff;
}

/* GLOW FUNDO */
.eras-redbull::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(0,90,255,.24),
    transparent 70%);

    filter:blur(40px);

    animation:redbullGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-redbull::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(255,0,60,.10),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-redbull > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-eras-redbull{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #7aa8ff,
    #ffcc33);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(0,90,255,.35);
}

/* ===== TEXTO ===== */
#textoEra-redbull{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#edf3ff;

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-redbull{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-redbull button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #07102c,
    #101f4d);

    color:#7aa8ff;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(122,168,255,.14);
}

/* brilho botão */
.botoes-eras-redbull button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-redbull button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-redbull button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #003cff,
    #001a70);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(0,90,255,.35);
}

/* BOTÃO ATIVO */
.botoes-eras-redbull .ativo{
    background:
    linear-gradient(
    145deg,
    #7aa8ff,
    #003cff);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(0,90,255,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#redbull-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.redbull-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(122,168,255,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.redbull-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.redbull-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.redbull-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(122,168,255,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(0,90,255,.18);
}

/* ===== IMAGEM ===== */
.redbull-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.redbull-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(0,90,255,.28));
}

/* ===== ANO ===== */
.redbull-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#7aa8ff;

    text-shadow:
    0 0 12px rgba(122,168,255,.3);
}

/* ===== TEXTO ===== */
#redbull-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#edf3ff;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes redbullGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-redbull{
        padding:90px 18px;
    }

    .titulo-eras-redbull{
        font-size:2.5rem;
    }

    #textoEra-redbull{
        font-size:1rem;
    }

    .botoes-eras-redbull{
        gap:10px;
    }

    .botoes-eras-redbull button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #redbull-timeline{
        grid-template-columns:1fr;
    }

    .redbull-timeline-item{
        max-width:360px;
        margin:auto;
    }

}



