/* ===========================
   TOPBAR ferrari
=========================== */

.topbar-ferrari{

width:100%;
max-width:100%;
overflow:hidden;
	
	height:70px;

    display:grid;
    grid-template-columns:60px 1fr 60px;

    align-items:center;

    background:#dc000060;
    border-bottom:3px solid #dc0000;

    padding:0 10px;

    box-sizing:border-box;

    position:sticky;
    top:0;
    z-index:9998;
}
/* ===========================
MENU
=========================== */

.menu-toggle-ferrari{
    width:45px;
    height:45px;

    display:flex;
    align-items:center;
    justify-content:center;

    background:none;
    border:none;

    color:#ffd426;

    font-size:24px;

    cursor:pointer;

	border-radius:12px;
transition:.3s;
}

.menu-toggle-ferrari{
    justify-self:start;
}

.menu-toggle-ferrari:hover{

    transform:scale(1.15);

    color:#fff;

	background:rgba(210,0,2,.15);

}

/* ===========================
TÍTULO
=========================== */

.topbar-title-ferrari{

    display:flex;

    align-items:center;

    justify-content:center;

    gap:10px;

    color:#ffd426;

    font-size:22px;

    font-weight:800;

    overflow:hidden;

    white-space:nowrap;

}

.topbar-title-ferrari img{

    width:34px;
    height:34px;

    object-fit:contain;

    filter:
        drop-shadow(0 0 8px rgba(210,0,2,.45));

    flex-shrink:0;

}

.topbar-title-ferrari span{

    overflow:hidden;

    text-overflow:ellipsis;

}

/* ===========================
BOTÃO NOTÍCIAS
=========================== */

.news-toggle-ferrari{

    width:45px;
    height:45px;

    display:flex;
    align-items:center;
    justify-content:center;

    background:none;
    border:none;

    color:#ffd326;

    font-size:24px;

    cursor:pointer;

	border-radius:12px;
transition:.3s;
}


.news-toggle-ferrari{
    justify-self:end;
}
.news-toggle-ferrari:hover{

    transform:scale(1.15);

    color:#fff;

	background:rgba(210,0,2,.15);
}


/* ===========================
MENU LATERAL
=========================== */

.side-menu-ferrari{

    position:fixed;

    top:0;
    left:-300px;

    width:290px;
    height:100vh;

    background:linear-gradient(
        180deg,
        #dc0000 0%,
        #1a1207 35%,
        #0a0a0a 100%
    );

    display:flex;
    flex-direction:column;

    overflow:hidden;

    transition:.45s cubic-bezier(.77,0,.18,1);

    z-index:9999;

    opacity:0;
    visibility:hidden;
    pointer-events:none;
}



.side-menu-ferrari.active{

left:0;

opacity:1;

visibility:visible;

pointer-events:all;

}


.side-menu-ferrari ul{
    list-style:none;
    padding:0;
    margin:0;
    position:relative;
    z-index:2;
}

.side-menu-ferrari li{
    margin:10px 0;
}

.side-menu-ferrari a{

    display:flex;
    justify-content:space-between;
    align-items:center;

    padding:12px 16px;

    color:#fff;

    text-decoration:none;

    background:rgba(255,255,255,.08);

    border:1px solid rgba(255,255,255,.12);

    border-radius:14px;

    font-size:16px;

    font-weight:800;

}


.side-menu-ferrari a span{

display:flex;

align-items:center;

gap:12px;

}

.side-menu-ferrari a i{

transition:.35s;

}

.side-menu-ferrari a:hover{

background:#dc0000;

color:#000;

transform:translateX(8px);

box-shadow:
0 0 20px rgba(210,0,2,.35);

}

.side-menu-ferrari a:hover .fa-chevron-right{

transform:translateX(8px);

}


.menu-links-ferrari{

    flex:1;

    overflow-y:auto;

    padding:0 20px 30px;

	

}

.menu-links-ferrari::-webkit-scrollbar{

    width:6px;

}

.menu-links-ferrari::-webkit-scrollbar-thumb{

    background:#dc0000;

