        right: auto;
    }


    .piloto-acao-ferrari strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-ferrari {

        padding:
            20px 8px;
    }


    .pilotos-titulo-ferrari h2 {

        font-size: 25px;
    }


    .pilotos-titulo-ferrari p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-ferrari {

        font-size: 115px;
    }


    .piloto-leclerc-ferrari
    .piloto-numero-bg-ferrari {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-ferrari {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-ferrari {

        bottom: 12%;
    }


    .piloto-dados-ferrari h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-ferrari {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-ferrari span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-ferrari,
    .piloto-ferrari::before,
    .piloto-numero-bg-ferrari,
    .piloto-foto-ferrari img,
    .piloto-dados-ferrari,
    .piloto-dados-ferrari h3::before,
    .piloto-dados-ferrari h3 strong,
    .piloto-linha-ferrari,
    .piloto-acao-ferrari,
    .piloto-acao-ferrari strong {

        animation: none !important;

        transition: none !important;
    }

}




