/* =========================================================
   ferrari — linha-evolution
========================================================= */

.ferrari-linha-evolution {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 600px;

    overflow: hidden;

    box-sizing: border-box;

    padding: 38px 4vw 25px;

    background: #050708;

    color: #fff;
}


/* =========================================================
   HEADER
========================================================= */

.linha-evolution-header-ferrari {
    position: relative;

    z-index: 10;

    text-align: center;

    margin-bottom: 28px;
}


.linha-evolution-header-ferrari > span {
    font-size: 13px;

    font-weight: 800;

    letter-spacing: 4px;

    color: rgba(220,255,255,.42);
}


.linha-evolution-header-ferrari h2 {
    margin: 6px 0 3px;

    font-size: clamp(28px, 4vw, 48px);

    line-height: 1;

    font-weight: 300;

    letter-spacing: -2px;
}


.linha-evolution-header-ferrari h2 strong {
    font-weight: 900;

    color: #DC0000;

    text-shadow:
        0 0 25px rgba(190,255,255,.2);
}


.linha-evolution-header-ferrari p {
    margin: 0;

    font-size: 15px;

    color: rgba(255,255,255,.35);

    letter-spacing: 1px;
}


/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-ferrari {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: flex;
    align-items: center;
    justify-content: center;
    grid-template-columns:
        repeat(5, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}

.linha-evolution-grid-ferrari
.linha-evolution-team-ferrari {
    width: min(420px, 70vw);
    height: 100%;
    flex: 0 0 min(420px, 70vw);
}
/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-ferrari {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-ferrari:hover
.linha-evolution-team-ferrari {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-ferrari
.linha-evolution-team-ferrari:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-ferrari {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-ferrari:hover
.team-bg-number-ferrari {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-ferrari {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-ferrari::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-ferrari img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-ferrari:hover
.team-image-ferrari {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-ferrari:hover
.team-image-ferrari::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-ferrari:hover
.team-image-ferrari img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-ferrari {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-ferrari:hover
.team-content-ferrari {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-ferrari {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-ferrari h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-ferrari {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-ferrari:hover
.team-line-ferrari {

    width: 65px;
}


/* Função */

.team-role-ferrari {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-ferrari {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-ferrari:hover
.team-arrow-ferrari {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


/* =========================================================
   CORES DAS EQUIPES
========================================================= */





/* =========================================================
   ferrari ATUAL
========================================================= */

.team-ferrari-current {

    --team-color: #DC0000;

    --team-glow:
        rgba(255,0,0,.8);
}


.team-ferrari-current:hover {

    background:
        linear-gradient(
            145deg,
            #071716,
            #050708 70%
        );

    border-color:
        rgba(255,0,0,.18);
}


.team-ferrari-current
.team-content-ferrari h3 {

    color: #DC0000;
}


.team-ferrari-current
.team-image-ferrari img {

    filter:
        grayscale(0%)
        brightness(.95);

    opacity: .85;
}


/* =========================================================
   FOOTER
========================================================= */

.linha-evolution-footer-ferrari {

    position: absolute;

    z-index: 10;

    left: 4vw;

    right: 4vw;

    bottom: 15px;

    display: flex;

    align-items: center;

    gap: 12px;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 3px;

    color:
        rgba(255,0,0,.25);
}


.footer-line-ferrari {

    height: 1px;

    flex: 1;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12)
        );
}


.footer-line-ferrari:last-of-type {

    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.12),
            transparent
        );
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 900px) {

    .ferrari-linha-evolution {

        padding-left: 20px;

        padding-right: 20px;
    }


    .linha-evolution-grid-ferrari {

        grid-template-columns:
            repeat(
                5,
                minmax(120px, 1fr)
            );

        overflow-x: auto;

        scrollbar-width: none;
    }


    .linha-evolution-grid-ferrari::-webkit-scrollbar {

        display: none;
    }


    .linha-evolution-team-ferrari {

        min-width: 150px;
    }


    .team-content-ferrari {

