.logo-titulo-fer{
    width:clamp(28px, 4vw, 46px);

    filter:drop-shadow(
      0 0 12px rgba(225,6,0,0.7)
    );

    transition:.3s ease;
}

.titulo-tabela-ferrari:hover .logo-titulo-fer{
    transform:scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-ferrari{
    width:90%;
    max-width:1500px;

    margin:auto;

    background:rgba(0,0,0,0.72);

    border-radius:20px;

    backdrop-filter:blur(8px);

    box-shadow:
      0 0 40px rgba(225,6,0,0.16),
      inset 0 0 30px rgba(225,6,0,0.05);
