    color:#e10600;

    font-weight:bold;

    width:50%;
}

/* SEGUNDA COLUNA */
.box-tabela-ferrari td:last-child{
    text-align:right;

    color:#e6e6e6;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-ferrari tr:hover{
