/* =====================================
   TEMPORADA ferrari 2026
===================================== */

.temporada-ferrari{

    position:relative;

    overflow:hidden;

    padding:80px 20px;

    color:#fff;

    background:
    radial-gradient(
        circle at top,
        #5c0000 0%,
        #120900 45%,
        #050505 100%
    );

}


/* brilho de fundo */

.temporada-ferrari::before{

    content:"";

    position:absolute;

    top:-200px;

    right:-200px;

    width:500px;

    height:500px;


    background:
    radial-gradient(
        circle,
        rgba(220,0,0,.18),
        transparent 70%
    );


    filter:blur(50px);

}


.temporada-ferrari > *{

    position:relative;

    z-index:2;

}



/* =====================================
   TÍTULO
===================================== */


.titulo-temp-ferrari{

    text-align:center;

    margin-bottom:50px;

    font-size:
    clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:3px;


    color:#fff;


    text-shadow:

    0 0 20px
    rgba(220,0,0,.55);

}



/* =====================================
   DASHBOARD
===================================== */


.dashboard-ferrari{

    max-width:1200px;

    margin:auto;

}



/* =====================================
   TOPO
===================================== */


.topo-temp-ferrari{

    display:grid;

    grid-template-columns:

    220px 1fr 220px;

    gap:20px;

    align-items:center;

}



/* =====================================
   CARD POSIÇÃO
===================================== */


.card-campeonato-ferrari,
.card-pontos-ferrari,
.card-grafico-ferrari{


    background:

    linear-gradient(
        145deg,
        #161616,
        #202020
    );


    border-radius:25px;


    border:

    1px solid
    rgba(220,0,0,.2);


    box-shadow:

    0 15px 35px
    rgba(0,0,0,.35);


}



/* posição */

.card-campeonato-ferrari,
.card-pontos-ferrari{


    padding:30px 20px;

    text-align:center;

}



.valor-posicao-ferrari{

    font-size:70px;

    font-weight:900;

    color:#dc0000;


    text-shadow:

    0 0 20px
    rgba(220,0,0,.5);

}



.card-campeonato-ferrari p,
.card-pontos-ferrari p{


    margin:10px 0 0;


    color:#bbb;


    font-weight:700;

    text-transform:uppercase;

    font-size:14px;

}



/* =====================================
   PONTOS
===================================== */


#pontosferrari{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-ferrari{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-ferrari svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficoferrari{


    stroke:#dc0000;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(220,0,0,.8)
    );


}

/* =====================================
   DESEMPENHO ferrari
===================================== */

.desempenho-ferrari{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-ferrari > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(220,0,0,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-ferrari > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(220,0,0,.55);



    box-shadow:

    0 0 25px
    rgba(220,0,0,.25);


}



/* números */

.desempenho-ferrari span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#dc0000;



    text-shadow:

    0 0 15px
    rgba(220,0,0,.45);


}



/* textos */

.desempenho-ferrari p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-ferrari span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(220,0,0,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(220,0,0,.75);

    }


}



/* =====================================
   DESTAQUE ferrari
===================================== */


.card-campeonato-ferrari::before,
.card-pontos-ferrari::before,
.card-grafico-ferrari::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(220,0,0,.12),
        transparent 45%
    );


    pointer-events:none;


}



/* garante posição dos cards */

.card-campeonato-ferrari,
.card-pontos-ferrari,
.card-grafico-ferrari{


    position:relative;


    overflow:hidden;


}

