==================================================*/

.ferrari-bar-right{

    border-radius:0 999px 999px 0;

}


.ferrari-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #dc0000,
        #5b0000
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.ferrari-value{

    animation:
    ferrariValueShow .5s ease;

}


@keyframes ferrariValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.ferrari-winner{

    color:#dc0000 !important;

    text-shadow:
    0 0 15px rgba(255,0,0,.8);

}


.ferrari-draw{

    color:#5b0000 !important;

}


