/*==================================================
        DRIVER EVOLUTION - ferrari
==================================================*/

/*==================================================
        ferrari DRIVER EVOLUTION
==================================================*/

.driver-evolution-ferrari{

    width:100%;

    min-height:100vh;

    padding:45px 0;

    box-sizing:border-box;

    background:
    linear-gradient(
        120deg,
        #6e0202 40%,
        #dc0000 120%
    );
	
    font-family:
    Arial,
    Helvetica,
    sans-serif;

    color:#fff;

}


/*==================================================
        HEADER
==================================================*/

.evolution-header-ferrari{

    text-align:center;
	
    margin-bottom:28px;

}


.evolution-header-ferrari h2{

    margin:0;

    font-size:clamp(35px,5vw,68px);

    line-height:.95;

    font-weight:1000;

    letter-spacing:-3px;

    color:#ffffff;

}


.evolution-header-ferrari p{

    margin:8px 0 0;

    font-size:20px;

    font-weight:800;

    letter-spacing:3px;

    color:#dc0000;

}



/*==================================================
        CARD
==================================================*/

.evolution-card-ferrari{

    width:100%;

    max-width:none;

    min-height:560px;

    margin:0;

    padding:35px;

    box-sizing:border-box;

    border-radius:0;

    background:
    linear-gradient(
        120deg,
        #6e0202 40%,
        #dc0000 120%
    );

    box-shadow:none;

}


/*==================================================
        TOPO
==================================================*/

.evolution-card-top-ferrari{

    width:100%;

    display:flex;

    align-items:center;

    justify-content:space-between;

    gap:25px;

    margin-bottom:28px;

}


.evolution-intro-ferrari h3{

    margin:0;

    font-size:25px;

    font-weight:900;

    letter-spacing:-1px;

}


.evolution-intro-ferrari h3 span{

    font-weight:400;

    margin:0 5px;

}


.evolution-intro-ferrari p{

    margin:6px 0 0;

    color:#92929a;

    font-size:14px;

}



/*==================================================
        SELETOR
==================================================*/

.evolution-selector-ferrari{

    display:flex;

    align-items:center;

    padding:4px;

    border-radius:8px;

    background:#29292f;

    border:1px solid #3c3c43;

}


.evolution-mode-ferrari{

    border:0;

    background:transparent;

    color:#aaaab0;

    padding:11px 18px;

    border-radius:6px;

    font-size:13px;

    font-weight:800;

    cursor:pointer;

    transition:.25s ease;

}


.evolution-mode-ferrari:hover{

    color:white;

}


.evolution-mode-ferrari.active{

    background:#f0f0f0;

    color:#111;

}



/*==================================================
        CONTENT
==================================================*/

.evolution-content-ferrari{

    width:100%;

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        240px;

    gap:40px;

}



/*==================================================
        GRÁFICO
==================================================*/

.evolution-chart-area-ferrari{

    min-width:0;

    position:relative;

}


.y-axis-title-ferrari{

    position:absolute;

    left:-65px;

    top:50%;

    transform:
    translateY(-50%)
    rotate(-90deg);

    color:#777780;

    font-size:22px;

    letter-spacing:1px;

    font-weight:700;

}


.evolution-chart-ferrari{

    width:100%;

    height:400px;

    display:grid;

    grid-template-columns:45px 1fr;

}


.chart-y-labels-ferrari{

    height:100%;

    display:flex;

    flex-direction:column;

    justify-content:space-between;

    align-items:flex-end;

    padding:0 10px 0 0;

    box-sizing:border-box;

}


.chart-y-labels-ferrari span{

    color:#73737b;

    font-size:20px;

}



/*==================================================
        ÁREA DAS LINHAS
==================================================*/

.chart-main-ferrari{

    position:relative;

    width:100%;

    height:100%;

    border-left:1px solid #38383f;

    border-bottom:1px solid #38383f;

    background:
    repeating-linear-gradient(
        to bottom,
        transparent 0,
        transparent calc(10% - 1px),
        #292930 calc(10% - 1px),
        #292930 10%
    );

}



/*==================================================
        GRID VERTICAL
==================================================*/

.chart-grid-ferrari{

    position:absolute;

    inset:0;

    display:flex;

}


.chart-grid-line-ferrari{

    flex:1;

    border-right:1px solid rgba(255,255,255,.06);

}



/*==================================================
        SVG
==================================================*/

.evolution-svg-ferrari{

    position:absolute;

    inset:0;

    width:100%;

    height:100%;

    overflow:visible;

}


.hamilton-path-ferrari{

    fill:none;

    stroke:#dc0000;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}


.leclerc-path-ferrari{

    fill:none;

    stroke:#f0f0f0;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}



/*==================================================
        ÁREA ABAIXO DA LINHA
==================================================*/

.hamilton-area-ferrari{

    fill:url(#hamiltonGradient);

    opacity:.12;

}


.leclerc-area-ferrari{

    fill:url(#leclercGradient);

    opacity:.08;

}



/*==================================================
        PONTOS
==================================================*/

.chart-point-ferrari{

    fill:#121217;

    stroke:#dc0000;

    stroke-width:3;

}


.chart-point-ferrari.leclerc-ferrari{

    stroke:#f0f0f0;

}



/*==================================================
        VALORES
==================================================*/

.chart-value-ferrari{

    fill:#eee;

    font-size:18px;

    font-weight:700;

    text-anchor:middle;

}


.chart-year-ferrari{

    fill:#777780;

    font-size:20px;

    text-anchor:middle;

}



/*==================================================
        SIDEBAR
==================================================*/

.evolution-sidebar-ferrari{

    padding-top:5px;

}


.sidebar-title-ferrari{

    color:#85858d;

    font-size:13px;

    letter-spacing:1px;

    font-weight:700;

    margin-bottom:16px;

}



/*==================================================
        IDENTIDADE
==================================================*/

.driver-identity-ferrari{

	  background:#15151a;

    display:flex;

    align-items:center;

    gap:12px;

    margin-bottom:20px;

}


.identity-line-ferrari{

    width:42px;

    height:3px;

    position:relative;

}


.identity-line-ferrari span{

    position:absolute;

    width:9px;

    height:9px;

    border-radius:50%;

    top:50%;

    left:50%;

    transform:translate(-50%,-50%);

    background:#ffffff;

    border:2px solid currentColor;

}


.hamilton-line-ferrari{

    background:#dc0000;

    color:#dc0000;

}


.leclerc-line-ferrari{

    background:#f0f0f0;

    color:#f0f0f0;

}


.driver-identity-ferrari small{

    display:block;

    color:#9999a0;

    font-size:11px;

}


.driver-identity-ferrari strong{

    display:block;

    color:#eee;

    font-size:14px;

}

/*==================================================
        IMAGENS - LINE IDENTITY
==================================================*/

.identity-driver-info-ferrari{

    display:flex;

    flex-direction:column;

    justify-content:center;

}


.identity-driver-image-ferrari{

    width:80px;

    height:80px;

    object-fit:contain;

    object-position:center bottom;

    align-self:flex-end;

    margin-left:auto;

}

/*==================================================
        LEGEND
==================================================*/

.legend-title-ferrari{

    margin-top:40px;

}


.driver-legend-ferrari{

    height:68px;

    margin-bottom:12px;

    padding:8px 10px 8px 15px;

    box-sizing:border-box;

    display:flex;

    align-items:center;

    justify-content:space-between;

    border:1px solid #dc0000;

    border-radius:8px;

    background:#17171c;

}


.legend-info-ferrari span{

    display:block;

    color:#ffffff;

    font-size:11px;

}


