    width:auto;

    object-fit:contain;

    align-self:flex-end;

}



/*==================================================
        ANIMAÇÃO
==================================================*/

.evolution-svg-ferrari path{

    stroke-dasharray:3000;

    stroke-dashoffset:3000;

    animation:
    drawEvolution 1.5s ease forwards;

}


@keyframes drawEvolution{

    to{

        stroke-dashoffset:0;

    }

}


.chart-point-ferrari{

    opacity:0;

    animation:
    pointShow .3s ease forwards;

}


@keyframes pointShow{

    to{

        opacity:1;

    }

}



