/* =========================================================
   FERRARI — LIDERANÇA / COMMAND CENTER
========================================================= */

.ferrari-lideranca {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 650px;

    box-sizing: border-box;

    overflow: hidden;

    padding: 35px 5vw 25px;

    color: #fff;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(220,0,0,.16),
            transparent 30%
        ),
        radial-gradient(
            circle at 90% 80%,
            rgba(220,0,0,.10),
            transparent 30%
        ),
        #050505;

    isolation: isolate;
}


/* =========================================================
   GRID TÉCNICO DO FUNDO
========================================================= */

.ferrari-lideranca::before {
    content: "";

    position: absolute;

    inset: 0;

    z-index: -2;

    opacity: .35;

    background-image:
        linear-gradient(
            rgba(255,255,255,.025) 1px,
            transparent 1px
        ),
        linear-gradient(
            90deg,
            rgba(255,255,255,.025) 1px,
            transparent 1px
        );

    background-size: 55px 55px;

    pointer-events: none;
}


/* LINHA VERMELHA LATERAL */

.ferrari-lideranca::after {
    content: "";

    position: absolute;

    top: 0;
    right: 0;

    width: 3px;
    height: 100%;

    background:
        linear-gradient(
            to bottom,
            transparent,
            #dc0000 25%,
            #dc0000 75%,
            transparent
        );

    box-shadow:
        0 0 20px rgba(220,0,0,.35);

    pointer-events: none;
}


/* =========================================================
   HEADER
========================================================= */

.ferrari-lideranca-header {
    position: relative;

    width: 100%;
    max-width: 1500px;

    margin: 0 auto;
}


/* KICKER */

.ferrari-lideranca-kicker {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 8px;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 5px;

    color: rgba(255,255,255,.45);
}


.ferrari-lideranca-kicker span {
    width: 35px;
    height: 2px;

    background: #dc0000;

    box-shadow:
        0 0 10px rgba(220,0,0,.6);
}


/* =========================================================
   TÍTULO
========================================================= */

.ferrari-lideranca-titulo-area {
    display: flex;

    align-items: center;

    gap: 18px;
}


.ferrari-lideranca-indice {
    width: 46px;
    height: 46px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border: 1px solid rgba(220,0,0,.6);

    background:
        linear-gradient(
            135deg,
            rgba(220,0,0,.18),
            rgba(220,0,0,.02)
        );

    color: #dc0000;

    font-size: 11px;

    font-weight: 900;

    box-shadow:
        inset 0 0 20px rgba(220,0,0,.08);
}


.ferrari-lideranca-subtitulo {
    display: block;

    margin-bottom: 4px;

    font-size: 7px;

    font-weight: 900;

    letter-spacing: 4px;

    color: rgba(255,255,255,.32);
}


.ferrari-lideranca-titulo {
    margin: 0;

    font-size:
        clamp(32px, 4vw, 58px);

    line-height: .9;

    font-weight: 200;

    letter-spacing: -2px;

    text-transform: uppercase;
}


.ferrari-lideranca-titulo strong {
    font-weight: 900;

    color: #dc0000;

    text-shadow:
        0 0 30px rgba(220,0,0,.18);
}


.ferrari-lideranca-descricao {
    margin: 7px 0 0;

    font-size: 9px;

    color: rgba(255,255,255,.5);

    letter-spacing: .3px;
}


/* =========================================================
   LINHA DO HEADER
========================================================= */

.ferrari-lideranca-linha {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: 1px;

    margin:
        17px auto 15px;

    background:
        linear-gradient(
            90deg,
            #dc0000,
            rgba(255,255,255,.12),
            transparent
        );
}


.ferrari-lideranca-linha span {
    position: absolute;

    left: 0;
    top: -2px;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: #dc0000;

    box-shadow:
        0 0 12px rgba(220,0,0,.8);
}


/* =========================================================
   GRID DOS LÍDERES
========================================================= */

.ferrari-lideranca-estrutura {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: calc(100% - 185px);

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        1.15fr 1.15fr .9fr .9fr;

    grid-template-rows:
        1fr 1fr;

    gap: 10px;
}


/* =========================================================
   CARD
========================================================= */

.ferrari-lideranca-card {
    position: relative;

    min-width: 0;
    min-height: 0;

    overflow: hidden;

    cursor: pointer;

    border:
        1px solid rgba(255,255,255,.12);

    background: #0b0b0b;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1),
        border-color .45s ease,
        box-shadow .45s ease;
}


/* BRILHO NO CARD */

.ferrari-lideranca-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: -120%;

    width: 70%;
    height: 100%;

    z-index: 5;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12),
            transparent
        );

    transform: skewX(-20deg);

    transition:
        left .7s ease;

    pointer-events: none;
}


/* LINHA INFERIOR */

.ferrari-lideranca-card::after {
    content: "";

    position: absolute;

    left: 0;
    bottom: 0;

    width: 0;
    height: 3px;

    z-index: 15;

    background:
        linear-gradient(
            90deg,
            #dc0000,
            #ff3030,
            transparent
        );

    transition:
        width .5s ease;
}


/* HOVER */

.ferrari-lideranca-card:hover {
    transform:
        translateY(-7px)
        scale(1.015);

    border-color:
        rgba(220,0,0,.7);

    box-shadow:
        0 20px 50px rgba(0,0,0,.65),
        0 0 35px rgba(220,0,0,.12);
}


.ferrari-lideranca-card:hover::before {
    left: 140%;
}


.ferrari-lideranca-card:hover::after {
    width: 100%;
}


/* =========================================================
   TOPO DOS CARDS
========================================================= */

.ferrari-lideranca-card-topo {
    position: absolute;

    top: 12px;
    left: 13px;
    right: 13px;

    z-index: 12;

    display: flex;

    justify-content: space-between;

    align-items: center;
}


.ferrari-lideranca-card-numero {
    font-size: 8px;

    font-weight: 900;

    letter-spacing: 2px;

    color: rgba(255,255,255,.55);
}


.ferrari-lideranca-card-cargo {
    padding: 5px 7px;

    background:
        rgba(0,0,0,.65);

    border:
        1px solid rgba(255,255,255,.14);

    backdrop-filter: blur(8px);

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 1.5px;

    color: rgba(255,255,255,.65);

    transition:
        background .4s ease,
        border-color .4s ease,
        color .4s ease;
}


.ferrari-lideranca-card:hover
.ferrari-lideranca-card-cargo {
    background:
        rgba(220,0,0,.25);

    border-color:
        rgba(220,0,0,.6);

    color: #fff;
}


/* =========================================================
   FOTO
========================================================= */

.ferrari-lideranca-foto {
    position: absolute;

    inset: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.ferrari-lideranca-foto img {
    width: 100%;
    height: 100%;

    object-fit: cover;

    display: block;

    opacity: .72;

    filter:
        grayscale(.35)
        contrast(1.12)
        brightness(.72);

    transform: scale(1.02);

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


.ferrari-lideranca-card:hover
.ferrari-lideranca-foto img {
    transform: scale(1.09);

    opacity: .9;

    filter:
        grayscale(0)
        contrast(1.08)
        brightness(.88);
}


/* =========================================================
   OVERLAY DA FOTO
========================================================= */

.ferrari-lideranca-foto-overlay {
    position: absolute;

    inset: 0;

    z-index: 2;

    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.1) 0%,
            transparent 30%,
            rgba(0,0,0,.35) 50%,
            rgba(0,0,0,.96) 100%
        );

    transition:
        background .5s ease;
}


.ferrari-lideranca-card:hover
.ferrari-lideranca-foto-overlay {
    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.05),
            rgba(220,0,0,.05) 45%,
            rgba(0,0,0,.94)
        );
}


