    #120000 40%,
    #ff1e1e 120%
  );
}

/* FUNDO */
.ferrari-sectors::before{
  content:"FERRARI";

  position:absolute;
  top:50%;
  left:50%;

  transform:translate(-50%,-50%);

  font-size:18vw;
  font-weight:900;

  color:rgba(255,255,255,.03);

  letter-spacing:15px;

  pointer-events:none;
}

/* HEADER */
.ferrari-sectors-header{
  position:relative;
  max-width:1100px;
  margin:auto;
  z-index:2;
}

.ferrari-sectors-header span{
  color:#FFD700;
  font-weight:800;
  letter-spacing:4px;
  text-transform:uppercase;
}

.ferrari-sectors-header h2{
  font-size:clamp(2.8rem,6vw,5rem);
  color:#fff;
  font-weight:900;
  margin:20px 0;
  line-height:1.1;
}

.ferrari-sectors-header p{
  color:#e0e0e0;
  font-size:1.05rem;
  line-height:2;
  max-width:900px;
}

/* GRID */
.ferrari-sectors-grid{
  display:grid;
  grid-template-columns:
  repeat(auto-fit,minmax(280px,1fr));

  gap:22px;

  margin-top:70px;

  position:relative;
  z-index:2;
}

/* CARD */
.ferrari-sector-card{
  padding:28px 24px;
  border-radius:22px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03)
  );

  border:1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(12px);

  transition:.35s;
}

/* HOVER */
.ferrari-sector-card:hover{
  transform:translateY(-10px);

  border-color:rgba(255,0,0,.5);

  box-shadow:
    0 20px 40px rgba(0,0,0,.4),
