  }

}


.ferrari-creation{
  position:relative;
  width:100%;
  padding:140px 25px;
  overflow:hidden;

  background:
  linear-gradient(
  180deg,
  #080808 0%,
  #3b0000 100%);
}

/* TEXTO FUNDO */
.ferrari-creation::before{
  content:"MARANELLO";

  position:absolute;
  top:50%;
  left:50%;

  transform:translate(-50%,-50%);

  font-size:15vw;
  font-weight:900;

  color:rgba(255,255,255,.03);

  letter-spacing:10px;

  pointer-events:none;
}

/* HEADER */
.ferrari-creation-header{
  position:relative;

  width:100%;
  max-width:1000px;

  margin:auto auto 100px;

  z-index:2;
}

.ferrari-creation-header span{
  display:inline-block;

  margin-bottom:20px;

  color:#ffcc00;

  text-transform:uppercase;

  letter-spacing:4px;

  font-size:.9rem;

  font-weight:800;
}

.ferrari-creation-header h2{
  font-size:clamp(3rem,7vw,6rem);

  line-height:1.05;

  color:#fff;

  margin-bottom:35px;

  font-weight:900;

  text-transform:uppercase;
}

.ferrari-creation-header p{
  max-width:850px;

  color:#d2d2d2;

  font-size:1.1rem;

  line-height:2;
}

/* TIMELINE */
.ferrari-creation-timeline{
  position:relative;

  max-width:1200px;

  margin:auto;

  z-index:2;
}

/* LINHA */
.ferrari-creation-timeline::before{
  content:"";

  position:absolute;

  left:32px;
  top:0;

  width:4px;
  height:100%;

  border-radius:20px;

  background:linear-gradient(
  180deg,
  #ff0000,
  rgba(255,204,0,.25));
}

/* STEP */
.ferrari-creation-step{
  position:relative;

  display:flex;

  gap:40px;

  margin-bottom:70px;
}

/* NÚMERO */
.ferrari-step-number{
  min-width:68px;
  height:68px;

  border-radius:50%;

  background:linear-gradient(
  145deg,
  #ff0000,
  #8b0000);

  display:flex;
  align-items:center;
  justify-content:center;

  color:#fff;

  font-weight:900;

  font-size:1.2rem;

  z-index:2;

  box-shadow:0 10px 25px rgba(255,0,0,.35);
}

/* CARD */
.ferrari-step-content{
  flex:1;

  padding:35px;

  border-radius:28px;

  background:linear-gradient(
  145deg,
  rgba(255,255,255,.06),
  rgba(255,255,255,.02));

  border:1px solid rgba(255,255,255,.08);

  transition:.45s;
}

/* HOVER */
.ferrari-step-content:hover{
  transform:translateY(-8px);

  border-color:rgba(255,0,0,.35);

  box-shadow:0 20px 40px rgba(0,0,0,.4);
}

/* TÍTULO */
.ferrari-step-content h3{
  position:relative;

  color:#fff;

  font-size:1.7rem;

  margin-bottom:24px;

  padding-bottom:14px;

  font-weight:800;
}

/* LINHA */
.ferrari-step-content h3::after{
  content:"";

  position:absolute;

  left:0;
  bottom:0;

  width:65px;
  height:4px;

  border-radius:20px;

  background:linear-gradient(
  90deg,
  #ff0000,
  #ffcc00);
}

/* TEXTO */
.ferrari-step-content p{
  color:#d0d0d0;

  font-size:1.05rem;

  line-height:2;
}

/* FINAL */
.ferrari-creation-ending{
  position:relative;

  margin-top:100px;

  text-align:center;

  z-index:2;
}

/* QUOTE */
.ferrari-creation-ending blockquote{
  max-width:1000px;

  margin:auto;

  color:#fff;

  font-size:clamp(1.8rem,4vw,3.2rem);

  line-height:1.5;

  font-weight:700;
}

/* RESPONSIVO */
@media(max-width:768px){

  .ferrari-creation{
    padding:100px 18px;
  }

  .ferrari-creation-header h2{
    font-size:2.7rem;
  }

  .ferrari-creation-header p{
    font-size:1rem;
  }

  .ferrari-creation-timeline::before{
    left:28px;
  }

  .ferrari-creation-step{
    gap:20px;
  }

  .ferrari-step-number{
    min-width:56px;
    height:56px;

    font-size:1rem;
  }

  .ferrari-step-content{
    padding:28px 24px;
  }

  .ferrari-step-content h3{
    font-size:1.35rem;
  }

  .ferrari-step-content p{
    font-size:.96rem;

    line-height:1.8;
  }
}


