========================================== */

.numeros-ferrari{

    position:relative;

    min-height:600px;

    padding:40px 0;

    overflow:hidden;

    background:
    linear-gradient(
        135deg,
        #eee 0%,
        #d00033 45%,
        #dc0000 120%
    );

}


/* IMAGEM DE FUNDO */

.bg-numeros-ferrari{

    position:absolute;

    inset:0;

    width:100%;
    height:100%;

    object-fit:cover;

    filter:
    brightness(.35)
    blur(4px);

    transform:scale(1.1);

    z-index:0;

}



.numeros-ferrari::before{

    content:"";

    position:absolute;

    inset:0;

    background:

    radial-gradient(
        circle at center,
        transparent 20%,
        rgba(0,0,0,.85)
    );

    z-index:1;

}



/* TITULO */

.titulo-numeros-ferrari{

    position:relative;

    z-index:2;

    text-align:center;

    color:#dc0000;

    font-size:clamp(32px,5vw,55px);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:25px;

    text-shadow:

    0 0 15px #dc0000;

}



/* GRID */

.stats-grid-ferrari{

    position:relative;

    z-index:2;


    max-width:1200px;

    margin:auto;

    padding:0 35px;


    display:grid;

    grid-template-columns:
    repeat(3,1fr);


    gap:15px;

}



/* CARDS */

.card-stat-ferrari{

    position:relative;


    background:

    linear-gradient(
        145deg,
        rgba(255,255,255,.08),
        rgba(210,0,0,.25)
    );




    border-radius:22px;


    padding:18px;


    text-align:center;


    color:white;


    border:

    1px solid
    rgba(255,255,255,.5);



    box-shadow:

    0 15px 40px
    rgba(210,0,0,.7);



    overflow:hidden;



    opacity:0;

    transform:
    translateY(50px);



    transition:.6s ease;

}



/* LINHA LARANJA */

.card-stat-ferrari::before{

    content:"";

    position:absolute;

    top:0;

    left:0;

    width:100%;

    height:4px;


    background:

    linear-gradient(
        90deg,
        transparent,
        #dc0000,
        transparent
    );

}



/* ATIVO */

.card-stat-ferrari.ativo{

    opacity:1;

    transform:
    translateY(0);


    animation:

    brilhoferrari 2.5s infinite alternate;

}



@keyframes brilhoferrari{

    from{

        box-shadow:

        0 0 15px
        rgba(255,255,255,.3);

    }


    to{

        box-shadow:

        0 0 35px
        rgba(255,255,255,.8);

    }

}



/* NUMEROS */

.card-stat-ferrari span{

    display:block;


    font-size:

    clamp(32px,4vw,55px);


    font-weight:900;


    color:#dc0000;


    text-shadow:

    0 0 15px #dc0000;

}



/* TEXTO */

.card-stat-ferrari p{

    margin-top:15px;


    font-size:

    clamp(18px,2vw,28px);


    font-weight:bold;


    color:white;

}



/* CARD GRANDE */

.grande-ferrari{

    grid-column:

    1 / -1;

}



/* BARRA */

.barra-velocidade-ferrari{


    width:0%;


    height:8px;


    margin-top:20px;


    border-radius:20px;


    background:

    linear-gradient(
        90deg,
        #dc0000,
        #db1111
    );


    box-shadow:

    0 0 15px #dc0000;


    transition:

    width .3s ease;

}



/* HOVER */

.card-stat-ferrari:hover{


    transform:

    translateY(-10px)
    scale(1.03);



    border-color:#dc0000;


}



