.card-stat-ferrari span{


    font-size:50px;

}


}




.timeline-ferrari{
  position:relative;

  padding:10px 40px;
  overflow:hidden;

  background:
    radial-gradient(
      circle at top right,
      rgba(255,215,0,.12),
      transparent 25%
    ),

    radial-gradient(
      circle at bottom left,
      rgba(255,0,0,.18),
      transparent 35%
    ),

    linear-gradient(
      135deg,
      #080808 0%,
      #120000 20%,
      #2b0000 45%,
      #450000 70%,
      #6b0000 100%
    );
}

.timeline-ferrari::before{
  content:"";

  position:absolute;
  inset:0;

  background:
    linear-gradient(
      120deg,
      transparent 0%,
      rgba(255,255,255,.03) 45%,
      transparent 100%
    );

  pointer-events:none;
}

/* TÍTULO */
.titulo-timeline-ferrari{
  text-align:center;

  color:#ff0000;

  text-shadow:
    0 0 10px #ff0000,
    0 0 20px #ff0000,
    0 0 35px rgba(255,0,0,.8);

  font-size:42px;

  margin-bottom:300px;

  box-shadow:0 15px 40px rgba(0,0,0,0.7);
}

/* LINHA */
.linha-box-ferrari{
  position:relative;

  width:100%;
  height:4px;

  margin-bottom:400px;
}

.linha-cinza-ferrari{
  position:absolute;

  width:100%;
  height:4px;

  background:#333;
}

/* PROGRESSO */
.linha-progresso-ferrari{
  position:absolute;

  width:0%;
  height:4px;

  background:linear-gradient(
    90deg,
    #ff0000,
    #ff5a5a,
    #ffd700
  );

  box-shadow:
    0 0 12px #ff0000,
    0 0 24px rgba(255,0,0,.5);

  transition:width .8s;
}

/* LUZ */
.luz-ferrari{
  position:absolute;

  width:70px;
  height:8px;

  background:linear-gradient(
    90deg,
    transparent,
    #ffffff,
    transparent
  );

  top:-2px;
  left:-60px;

  filter:blur(4px);
}

/* PONTO */
.ponto-ferrari{
  position:absolute;

  top:30%;

  transform:translate(-50%,-50%);

  text-align:center;

  transition:.3s ease;
}

.ponto-ferrari:hover{
  z-index:20;
}

/* CÍRCULO */
.ponto-ferrari::after{
  content:"";

  width:12px;
  height:12px;

  background:#666;

  display:block;

  border-radius:50%;

  margin:8px auto;

  transition:.4s;
}

.ponto-ferrari.ativo::after{
  background:#ff0000;

  box-shadow:
    0 0 12px #ff0000,
    0 0 24px rgba(255,0,0,.5);
}

/* ANO */
.ano-ferrari{
  position:absolute;

  left:50%;

  transform:translateX(-50%);

  font-size:30px;

  color:#ffb3b3;

  text-shadow:
    0 0 10px rgba(255,179,179,.5);

  opacity:0;

  font-weight:700;

  transition:.3s ease;
}

.ano-ferrari.cima{
  top:30px;
}

.ano-ferrari.baixo{
  top:-30px;
}

/* TROFÉU */
.titulo-num-ferrari{
  font-size:24px;

  padding:4px 12px;

  border-radius:20px;

  background:#0d0d0d;

  color:#fff;

  border-left:3px solid #ff0000;

  font-weight:800;

  letter-spacing:1px;

  box-shadow:0 4px 10px rgba(0,0,0,.35);

  transition:.35s ease;
}

/* HOVER TROFÉU */
.ponto-ferrari:hover .titulo-num-ferrari{
  transform:scale(1.08);

  background:#111;

  color:#ffd700;

  box-shadow:
    0 0 15px rgba(255,0,0,.35),
