.timeline-ferrari-car{
  position:relative;

  width:100%;
  height:800px;

  overflow:hidden;

  font-size:initial;

  background:
    radial-gradient(
      circle at top right,
      rgba(255,0,0,.16),
      transparent 25%
    ),

    radial-gradient(
      circle at bottom left,
      rgba(255,255,255,.08),
      transparent 35%
    ),

    linear-gradient(
      135deg,
      #090909 0%,
      #140000 20%,
      #2a0000 45%,
      #450000 70%,
      #700000 100%
    );
}

/* TÍTULO */
.titulo-timeline-car-ferrari{
  text-align:center;

  color:#ff2b2b;

  font-size:42px;

  margin-bottom:300px;

  text-shadow:
    0 0 10px rgba(255,0,0,.7),
    0 0 25px rgba(255,0,0,.35);
}

/* LINHA */
.linha-box-car-ferrari{
  position:absolute;

  top:50%;
  left:0;

  width:100%;
  height:6px;

  transform:translateY(-50%);
}

.linha-cinza-car-ferrari{
  position:absolute;

  width:100%;
  height:6px;

  background:#2a2a2a;

  border-radius:4px;
}

/* PROGRESSO */
.linha-progresso-car-ferrari{
  position:absolute;

  width:0%;
  height:6px;

  background:linear-gradient(
    90deg,
    #8b0000,
    #ff2b2b,
    #ffd6d6
  );

  border-radius:4px;

  box-shadow:
    0 0 12px rgba(255,0,0,.6),
    0 0 28px rgba(255,255,255,.15);

  transition:1.2s;
}

/* LUZ */
.luz-car-ferrari{
  position:absolute;

  top:-6px;

  width:70px;
  height:18px;

  background:
    radial-gradient(
      circle,
      #ff4d4d,
      transparent
    );

  filter:blur(6px);

  left:0;

  transition:1.2s;
}

/* PONTO */
.ponto-car-ferrari{
  position:absolute;

  top:50%;

  transform:translate(-50%,-50%);

  width:12px;
  height:12px;

  background:#ff2b2b;

  border-radius:50%;

  box-shadow:
    0 0 12px rgba(255,0,0,.7);

  z-index:3;
}

/* FOTO */
.foto-car-ferrari{
  position:absolute;

  left:50%;

  opacity:0;

  transform:
    translateX(-50%)
    translateY(40px)
    scale(.8);

  transition:
    opacity .8s ease,
    transform .8s ease;
}

.foto-car-ferrari.cima{
  bottom:120%;
}

.foto-car-ferrari.baixo{
  top:120%;
}

.foto-car-ferrari.ativo{
  opacity:1;

  transform:
    translateX(-50%)
    translateY(0)
    scale(1);
}

/* IMG */
.foto-car-ferrari img{
  max-width:100px;
  height:90px;

  object-fit:contain;

  transition:
    transform .45s ease,
    filter .45s ease;
}

/* HOVER IMG */
.foto-car-ferrari img:hover{
  transform:
    scale(1.12)
    rotate(-2deg);

  filter:
    drop-shadow(0 0 12px rgba(255,0,0,.75))
    drop-shadow(0 0 28px rgba(255,255,255,.2));
}

/* INFO */
.info-car-ferrari{
  position:absolute;

  left:50%;

  transform:
    translateX(-50%)
    translateY(20px);

  opacity:0;

  text-align:center;

  width:120px;

  transition:
    transform .3s ease,
    filter .3s ease,
    text-shadow .3s ease;
}

/* HOVER INFO */
.info-car-ferrari:hover{
  transform:
    translateX(-50%)
    translateY(-6px);

  filter:brightness(1.08);
}

.info-car-ferrari.cima{
  bottom:190%;
  color:#ff2b2b;
}

.info-car-ferrari.baixo{
  top:230%;
  color:#ff2b2b;
}

.info-car-ferrari.ativo{
  opacity:1;

  transform:
    translateX(-50%)
    translateY(0);
}

/* ANO */
.info-car-ferrari h3{
  font-size:20px;

  font-weight:800;

  letter-spacing:1px;

  color:#ffe0e0;

  text-shadow:
    0 0 10px rgba(255,0,0,.7);

  transition:.3s ease;
}

/* HOVER ANO */
.info-car-ferrari:hover h3{
  color:#ff4d4d;

  letter-spacing:2px;

  text-shadow:
    0 0 10px rgba(255,0,0,.9),
    0 0 20px rgba(255,0,0,.4);
}

/* PILOTOS */
.info-car-ferrari p{
  font-size:20px;

  color:#ffeaea;

  background:#101010;

  padding:8px 14px;

  border-radius:20px;

  border:1px solid rgba(255,0,0,.5);

  box-shadow:
    0 0 15px rgba(255,0,0,.25);

  transition:.3s ease;
}

/* HOVER PILOTOS */
.info-car-ferrari:hover p{
  transform:scale(1.05);

  color:#ff4d4d;

  text-shadow:
    0 0 6px rgba(255,255,255,.35);
}

/* ORDEM */
.info-car-ferrari.cima{
  display:flex;

  flex-direction:column-reverse;

  align-items:center;

  gap:6px;
}

/* MODELO */
.modelo-car-ferrari{
  display:inline-flex;

  align-items:center;
  justify-content:center;

  margin-top:10px;

  padding:7px 16px;

  background:#111;

  color:#ffeaea;

  font-size:15px;

  font-weight:700;

  letter-spacing:1px;

  text-transform:uppercase;

  border-left:4px solid #ff2b2b;

  border-radius:8px;

  box-shadow:
    0 4px 12px rgba(0,0,0,.35);

  transition:.25s ease;
}

/* HOVER MODELO */
.info-car-ferrari:hover .modelo-car-ferrari{
  transform:scale(1.08);

