.hall-ferrari{
padding:120px 40px;
position:relative;

background:
linear-gradient(
120deg,
#120000 35%,
#3b0000 100%
);

min-height:100vh;
overflow:hidden;
}

/* TÍTULO */
.titulo-hall-ferrari{
text-align:center;
font-size:52px;
color:#ff2b2b;
margin-bottom:80px;

text-shadow:
0 0 12px rgba(255,43,43,.7);
}

/* GRID */
.hall-grid-ferrari{
display:flex;
justify-content:center;
align-items:flex-start;
flex-wrap:wrap;

perspective:1200px;

gap:40px;

position:relative;
z-index:3;
}

/* BG */
.bg-hall-ferrari{
position:absolute;
inset:0;
z-index:0;
}

.bg-layer-ferrari{
position:absolute;
inset:0;

background-size:cover;
background-position:center;

opacity:0;

transition:opacity .8s ease;
}

.bg-layer-ferrari.active{
opacity:1;
}

.hall-grid-ferrari,
.titulo-hall-ferrari,
.hall-overlay-ferrari{
position:relative;
z-index:2;
}

/* MODO SHOWCASE */
.hall-ferrari.showcase .hall-card-ferrari{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

/* FUNDO GANHA DESTAQUE */
.hall-ferrari.showcase .bg-layer-ferrari.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.15)
saturate(1.2);

transition:1s ease;
}

/* CARD */
.hall-card-ferrari{
position:relative;

width:320px;

padding:30px;

border-radius:24px;

background:
linear-gradient(
180deg,
rgba(25,10,10,0.30),
rgba(15,0,0,0.82)
);

backdrop-filter:blur(2px);

border:1px solid rgba(255,43,43,.25);

overflow:hidden;

transition:.45s ease;

text-align:center;

transform-origin:center top;
}

/* HOVER */
.hall-card-ferrari:hover{
transform:
translateY(-14px)
scale(1.04);

background:
rgba(20,0,0,.94);

box-shadow:
0 25px 60px rgba(0,0,0,.7),
0 0 30px rgba(255,43,43,.28);

z-index:10;
}

.hall-grid-ferrari:hover .hall-card-ferrari{
opacity:.35;
transform:scale(.98);
}

.hall-card-ferrari:hover{
opacity:1 !important;

transform:
translateY(-14px)
scale(1.06);
}

/* NÚMERO */
.numero-hall-ferrari{
position:absolute;

top:15px;
right:20px;

font-size:70px;
font-weight:900;

color:
rgba(255,43,43,.08);
}

/* FOTO */
.hall-card-ferrari img{
width:170px;
height:200px;

object-fit:cover;

border-radius:50%;

border:3px solid #ff2b2b;

margin-bottom:20px;

filter:
grayscale(100%)
brightness(.9);

transition:.5s ease;
}

.hall-card-ferrari:hover img{
filter:
grayscale(0%)
brightness(1.1);

transform:scale(1.1);
}

/* ANIMAÇÃO TEXTO */
.hall-card-ferrari p,
.hall-stats-ferrari,
.frase-hall-ferrari{
opacity:0;

transform:translateY(10px);

max-height:0;

overflow:hidden;

transition:.4s ease;
}

.hall-card-ferrari:hover p,
.hall-card-ferrari:hover .hall-stats-ferrari,
.hall-card-ferrari:hover .frase-hall-ferrari{
opacity:1;

transform:translateY(0);

max-height:200px;
}

/* NOME */
.hall-card-ferrari h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}

/* PAÍS */
.pais-hall-ferrari{
display:block;

font-size:18px;

color:#ff6b6b;

margin-bottom:18px;
}

/* TEXTO */
.hall-card-ferrari p{
font-size:18px;

color:#ddd;

margin-bottom:22px;
}

/* STATS */
.hall-stats-ferrari{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#ffe0e0;
}

/* FRASE */
.frase-hall-ferrari{
font-size:14px;

font-style:italic;

color:#fff;

