  animation:rotateCircleFerrari 14s linear infinite;
}

.car-circle-ferrari::before{
  content:"";
  position:absolute;
  inset:20px;

  border-radius:50%;
  border:1px dashed rgba(255,255,255,.08);
}

/* IMAGEM */
.car-container-ferrari img{
  width:100%;
  max-width:580px;

  filter:drop-shadow(0 30px 35px rgba(0,0,0,.6));

  animation:
  floatCarFerrari 5s ease-in-out infinite,
  rotateCarFerrari 6s ease-in-out infinite;

  transition:.45s;
}

/* BOTÕES */
.controls-ferrari{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin:50px 0 90px;
}

.controls-ferrari button{
  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(145deg,#ff0000,#960000);

  color:#fff;
  font-weight:800;

  cursor:pointer;
  transition:.35s;
}

.controls-ferrari button:hover{
  transform:translateY(-6px) scale(1.05);

  box-shadow:
  0 10px 30px rgba(255,0,0,.35);
}

/* INFO */
.car-info-ferrari{
  max-width:1200px;
  margin:auto;
}

.car-info-ferrari h2{
  text-align:center;
  font-size:clamp(2rem,5vw,3.5rem);
  margin-bottom:50px;
  color:#fff;
}

/* GRID */
.info-grid-ferrari{
  display:grid;
  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));
  gap:25px;
}

/* CARD */
.info-card-ferrari{
  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
  145deg,
  rgba(255,255,255,.05),
  rgba(255,255,255,.02));

  border:1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  transition:.45s;
}

.info-card-ferrari:hover{
  transform:translateY(-12px);

  border-color:
  rgba(255,0,0,.4);

  box-shadow:
  0 15px 40px rgba(0,0,0,.45),
  0 0 25px rgba(255,0,0,.15);
}

.info-card-ferrari span{
  display:block;
  margin-bottom:14px;

  color:#ff7a7a;

  text-transform:uppercase;
  font-size:.8rem;
}

.info-card-ferrari h3{
  color:#fff;
}

/* ANIMAÇÕES */
@keyframes rotateCircleFerrari{
  from{transform:rotate(0deg);}
  to{transform:rotate(360deg);}
}

@keyframes floatCarFerrari{
  0%,100%{transform:translateY(0);}
  50%{transform:translateY(-15px);}
}

@keyframes rotateCarFerrari{
  0%,100%{rotate:y 0deg;}
  50%{rotate:y 10deg;}
}

@keyframes pulseFloorFerrari{
  0%,100%{transform:scale(.95);opacity:.5;}
  50%{transform:scale(1.05);opacity:1;}
}

@keyframes glowMoveFerrari{
  0%{transform:translate(0,0);}
  50%{transform:translate(80px,40px);}
  100%{transform:translate(0,0);}
}


.eras-ferrari{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
    radial-gradient(circle at top,
    #ff5a5a 0%,
    #c00000 35%,
    #3b0000 70%,
    #080000 100%);

    overflow:hidden;

    color:#fff1f1;
}

/* GLOW FUNDO */
.eras-ferrari::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(255,0,0,.25),
    transparent 70%);

    filter:blur(40px);

    animation:ferrariGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-ferrari::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(255,215,0,.12),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-ferrari > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-eras-ferrari{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #ff8a8a,
    #ffd700);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(255,0,0,.35);
}

/* ===== TEXTO ===== */
#textoEra-ferrari{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#fff0f0;

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-ferrari{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-ferrari button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #240000,
    #460000);

    color:#ff9b9b;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(255,120,120,.14);
}

/* brilho botão */
.botoes-eras-ferrari button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-ferrari button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-ferrari button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #ff0000,
    #b30000);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(255,0,0,.35);
}

/* BOTÃO ATIVO */
.botoes-eras-ferrari .ativo{
    background:
    linear-gradient(
    145deg,
    #ff8a8a,
    #ff0000);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(255,0,0,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#ferrari-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.ferrari-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(255,120,120,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.ferrari-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.ferrari-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.ferrari-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(255,120,120,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(255,0,0,.2);
}

/* ===== IMAGEM ===== */
.ferrari-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.ferrari-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(255,0,0,.3));
}

/* ===== ANO ===== */
.ferrari-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#ff8a8a;

    text-shadow:
    0 0 12px rgba(255,120,120,.3);
}

/* ===== TEXTO ===== */
#ferrari-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#fff1f1;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes ferrariGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-ferrari{
        padding:90px 18px;
    }

    .titulo-eras-ferrari{
        font-size:2.5rem;
    }

    #textoEra-ferrari{
        font-size:1rem;
    }

    .botoes-eras-ferrari{
        gap:10px;
    }

    .botoes-eras-ferrari button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #ferrari-timeline{
        grid-template-columns:1fr;
    }

    .ferrari-timeline-item{
        max-width:360px;
        margin:auto;
    }

}



