/* =========================================================
   PILOTOS williams
========================================================= */

.pilotos-williams {

    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 100dvh;

    overflow: hidden;

    box-sizing: border-box;

    padding: 45px 5vw;

    background:
        radial-gradient(
            circle at 50% 100%,
            rgba(0,90,255,.12),
            transparent 35%
        ),
        linear-gradient(
            120deg,
            #050505,
            #0b0b0b,
            #050505
        );

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.pilotos-titulo-williams {

    position: relative;

    z-index: 20;

    text-align: center;

    margin-bottom: 25px;
}


.pilotos-titulo-williams span {

    display: block;

    color: #005aff;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 5px;
}


.pilotos-titulo-williams h2 {

    margin: 4px 0;

    font-size: clamp(30px, 4vw, 52px);

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotos-titulo-williams p {

    margin: 0;

    color: rgba(255,255,255,.62);

    font-size: 18px;
}


/* =========================================================
   ÁREA DOS PILOTOS
========================================================= */

.dupla-pilotos-williams {

    position: relative;

    display: grid;

    grid-template-columns: 1fr 1fr;

    height: calc(100% - 125px);

    max-width: 1450px;

    margin: auto;
}


/* =========================================================
   PILOTO
========================================================= */

.piloto-williams {

    position: relative;

    display: block;

    height: 100%;

    overflow: hidden;

    text-decoration: none;

    color: white;

    transition:
        transform .5s ease;
}


/* =========================================================
   BRILHO DE FUNDO
========================================================= */

.piloto-williams::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: 15%;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0,90,255,.15),
            transparent 68%
        );

    filter: blur(30px);

    opacity: .35;

    transition:
        transform .7s ease,
        opacity .7s ease;

    pointer-events: none;
}


/* =========================================================
   BRILHO carlos
========================================================= */

.piloto-carlos-williams::before {

    left: -220px;
}


/* =========================================================
   BRILHO albon
========================================================= */

.piloto-albon-williams::before {

    right: -220px;
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.piloto-numero-bg-williams {

    position: absolute;

    z-index: 0;

    top: 5%;

    font-size: clamp(200px, 40vw, 400px);

    font-weight: 900;

    line-height: 1;

    color: transparent;

    -webkit-text-stroke:
        1px rgba(255,255,255,.08);

    opacity: .8;

    transition:
        color .7s ease,
        -webkit-text-stroke .7s ease,
        transform .7s ease,
        opacity .7s ease;
}


/* =========================================================
   NÚMERO carlos
========================================================= */

.piloto-carlos-williams
.piloto-numero-bg-williams {

    left: -3%;
	    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   NÚMERO albon
========================================================= */

.piloto-albon-williams
.piloto-numero-bg-williams {

    right: -2%;

    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   FOTO
========================================================= */

.piloto-foto-williams {

    position: absolute;

    z-index: 2;

    left: 50%;

    bottom: 0;

    width: 70%;

    height: 90%;

    transform:
        translateX(-50%);

    display: flex;

    align-items: flex-end;

    justify-content: center;

    pointer-events: none;
}


.piloto-foto-williams img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center bottom;

    filter:
        grayscale(.35)
        brightness(.65);

    opacity: .72;

    transform:
        translateY(30px)
        scale(.95);

    transition:
        transform .8s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


/* =========================================================
   POSIÇÃO DA FOTO DO albon
========================================================= */

.piloto-albon-williams
.piloto-foto-williams {

    transform:
        translateX(-60%);
}


/* =========================================================
   DADOS DO PILOTO
========================================================= */

.piloto-dados-williams {

    position: absolute;

    z-index: 30;

    left: 7%;

    bottom: 9%;

    max-width: 80%;

    transition:
        transform .6s ease;
}

/* =========================================================
   DADOS DO albon
========================================================= */

.piloto-albon-williams
.piloto-dados-williams {

    left: auto;

    right: 7%;

    text-align: right;
}


/* =========================================================
   PAÍS
========================================================= */

.piloto-pais-williams {

    display: block;

    margin-bottom: 8px;

    color: #005aff;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 4px;
}


/* =========================================================
   HAMILTON — FUNDO DO NOME MAIS TRANSPARENTE
========================================================= */

.piloto-carlos-williams
.piloto-dados-williams h3::before {

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.70) 0%,
            rgba(0,0,0,.60) 45%,
            rgba(0,0,0,.30) 75%,
            transparent 100%
        );

    opacity: .75;

    filter: blur(7px);
}

/* =========================================================
   NOME
========================================================= */

.piloto-dados-williams h3 {

    position: relative;

    display: inline-flex;

    flex-direction: column;

    align-items: flex-start;

    margin: 0;

    padding: 6px 14px 8px 0;

    z-index: 31;

    font-size: clamp(28px, 3vw, 42px);

    line-height: .9;

    font-weight: 900;

    color: #fff;

    text-shadow:
        0 3px 10px rgba(0,0,0,1),
        0 0 18px rgba(0,0,0,1);
}

/* =========================================================
   NOME albon — ALINHAMENTO
========================================================= */

.piloto-albon-williams
.piloto-dados-williams h3 {

    align-items: flex-end;

    padding-right: 0;

    padding-left: 14px;
}


/* =========================================================
   FUNDO DE PROTEÇÃO DO NOME
========================================================= */

.piloto-dados-williams h3::before {

    content: "";

    position: absolute;

    z-index: -1;

    top: -12px;
    bottom: -12px;

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.98) 0%,
            rgba(0,0,0,.92) 45%,
            rgba(0,0,0,.72) 70%,
            rgba(0,0,0,.15) 100%
        );

    filter: blur(6px);

    opacity: .95;

    pointer-events: none;

    transition:
        opacity .4s ease,
        transform .4s ease;
}


/* =========================================================
   PROTEÇÃO DO NOME — LADO DIREITO
========================================================= */

.piloto-albon-williams
.piloto-dados-williams h3::before {

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            270deg,
            rgba(0,0,0,.90) 0%,
            rgba(0,0,0,.90) 45%,
            rgba(0,0,0,.70) 70%,
            rgba(0,0,0,.10) 100%
        );
}


/* =========================================================
   PRIMEIRO NOME
========================================================= */

.piloto-dados-williams h3 {

    color: #fff;
}


/* =========================================================
   SOBRENOME
========================================================= */

.piloto-dados-williams h3 strong {

    position: relative;

    display: block;

    color: #fff;

    font-weight: 900;

    transition:
        color .35s ease,
        text-shadow .35s ease;
}


/* =========================================================
   LINHA
========================================================= */

.piloto-linha-williams {

    width: 65px;

    height: 2px;

    margin: 15px 0;

    background: #005aff;

    box-shadow:
        0 0 12px rgba(0,90,255,.7);

    transition:
        width .6s ease;
}


.piloto-albon-williams
.piloto-linha-williams {

    margin-left: auto;
}


/* =========================================================
   CATEGORIA
========================================================= */

.piloto-categoria-williams {

    color: rgba(255,255,255,.98);

    font-size: 12px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* =========================================================
   AÇÃO
========================================================= */

.piloto-acao-williams {

    position: absolute;

    z-index: 14;

    right: 7%;

    bottom: 10%;

    display: flex;

    align-items: center;

    gap: 12px;

    color: rgba(255,255,255,.4);

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    transition:
        color .4s ease,
        transform .5s ease;
}


/* =========================================================
   AÇÃO albon
========================================================= */

.piloto-albon-williams
.piloto-acao-williams {

    right: auto;

    left: 4%;
}


/* =========================================================
   ÍCONE
========================================================= */

.piloto-acao-williams strong {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 28px;

    height: 28px;

    border: 1px solid rgba(0,90,255,.3);

    color: #005aff;

    font-size: 12px;

    transition:
        background .4s ease,
        color .4s ease,
        transform .4s ease;
}



/* =========================================================
   CENTRO williams
========================================================= */

.centro-williams {

    position: absolute;

    z-index: 25;

    left: 50%;
    top: 5%;

    bottom: 5%;

    width: 90px;

    transform: translateX(-50%);

    display: flex;

    flex-direction: column;

    align-items: center;

    pointer-events: none;
}


/* =========================================================
   LOGO CENTRAL
========================================================= */

.centro-logo-williams {

    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle,
            rgba(5,5,5,.95) 45%,
            rgba(5,5,5,.75) 70%,
            transparent 100%
        );

    flex-shrink: 0;
}


.centro-logo-williams img {

    width: 55px;
    height: 55px;

    object-fit: contain;

    opacity: .75;

    filter:
        drop-shadow(
            0 0 8px rgba(0,90,255,.25)
        );

    transition:
        transform .5s ease,
        opacity .5s ease,
        filter .5s ease;
}


/* =========================================================
   LINHA VERTICAL
========================================================= */

.centro-linha-williams {

    width: 1px;

    flex: 1;

    min-height: 80px;

    background:
        linear-gradient(
            to bottom,
            rgba(0,90,255,.8),
            rgba(0,90,255,.15),
            transparent
        );

    box-shadow:
        0 0 8px rgba(0,90,255,.25);
}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.centro-nome-williams {

    writing-mode: vertical-rl;

    text-orientation: mixed;

    margin-top: 12px;

    color: rgba(255,255,255,.3);

    font-size: 20px;

    font-weight: 800;

    letter-spacing: 4px;

    text-transform: uppercase;

    white-space: nowrap;

    transition:
        color .4s ease,
        text-shadow .4s ease;
}


/* =========================================================
   HOVER NOS PILOTOS
========================================================= */

.dupla-pilotos-williams:has(
    .piloto-williams:hover
)
.centro-logo-williams img {

    opacity: 1;

    transform: scale(1.1);

    filter:
        drop-shadow(
            0 0 8px #005aff
        )
        drop-shadow(
            0 0 20px rgba(0,90,255,.55)
        );
}


.dupla-pilotos-williams:has(
    .piloto-williams:hover
)
.centro-nome-williams {

    color: #005aff;

    text-shadow:
        0 0 10px rgba(0,90,255,.6);
}


/* =========================================================
   HOVER — PILOTO
========================================================= */

.piloto-williams:hover {

    z-index: 20;
}


/* =========================================================
   HOVER — BRILHO
========================================================= */

.piloto-williams:hover::before {

    opacity: .9;

    transform: scale(1.3);
}


/* =========================================================
   HOVER — NÚMERO
========================================================= */

.piloto-williams:hover
.piloto-numero-bg-williams {

    color: rgba(0,90,255,.14);

    -webkit-text-stroke:
        1px rgba(0,90,255,.28);

    transform: scale(1.05);

    opacity: 1;
}


/* =========================================================
   HOVER — FOTO
========================================================= */

.piloto-williams:hover
.piloto-foto-williams img {

    filter:
        grayscale(0)
        brightness(1);

    opacity: 1;

    transform:
        translateY(0)
        scale(1.02);
}


/* =========================================================
   HOVER — DADOS
========================================================= */

.piloto-williams:hover
.piloto-dados-williams {

    transform:
        translateY(-8px);
}


/* =========================================================
   HOVER — NOME
========================================================= */

.piloto-williams:hover
.piloto-dados-williams h3 strong {

    color: #005aff;

    text-shadow:
        0 0 8px rgba(0,90,255,.8),
        0 0 20px rgba(0,90,255,.45),
        0 3px 10px rgba(0,0,0,.9);
}


/* =========================================================
   HOVER — FUNDO DO NOME
========================================================= */

.piloto-williams:hover
.piloto-dados-williams h3::before {

    opacity: 1;

    transform: scaleX(1.05);
}


/* =========================================================
   HOVER — LINHA
========================================================= */

.piloto-williams:hover
.piloto-linha-williams {

    width: 120px;
}


/* =========================================================
   HOVER — AÇÃO
========================================================= */

.piloto-williams:hover
.piloto-acao-williams {

    color: white;

    transform:
        translateY(-5px);
}


.piloto-williams:hover
.piloto-acao-williams strong {

    background: #005aff;

    color: #080808;

    transform:
        rotate(45deg);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 700px) {

    .pilotos-williams {

        padding:
            25px 12px;
    }


    .pilotos-titulo-williams {

        margin-bottom: 10px;
    }


    .pilotos-titulo-williams h2 {

        font-size: 30px;
    }


    .pilotos-titulo-williams p {

        font-size: 10px;
    }


    .dupla-pilotos-williams {

        height: calc(100% - 100px);

        grid-template-columns:
            1fr 1fr;
    }


    .dupla-pilotos-williams::before {

        top: 8%;

        bottom: 8%;
    }


    /* FOTO */

    .piloto-foto-williams {

        width: 110%;

        height: 72%;
    }


    /* NÚMERO */

    .piloto-numero-bg-williams {

        font-size: 150px;

        top: 15%;
    }


    .piloto-albon-williams
    .piloto-numero-bg-williams {

        font-size: 135px;

        right: -5%;
    }


    /* DADOS */

    .piloto-dados-williams {

        left: 6%;

        bottom: 13%;

        max-width: 88%;
    }


    .piloto-albon-williams
    .piloto-dados-williams {

        right: 6%;

        left: auto;
    }


    /* PAÍS */

    .piloto-pais-williams {

        font-size: 6px;

        letter-spacing: 2px;
    }


    /* NOME */

    .piloto-dados-williams h3 {

        font-size: 25px;

        line-height: .9;
    }


    /* LINHA */

    .piloto-linha-williams {

        margin-top: 9px;

        margin-bottom: 8px;

        width: 40px;
    }


    /* CATEGORIA */

    .piloto-categoria-williams {

        font-size: 5px;

        letter-spacing: 1px;
    }


    /* AÇÃO */

    .piloto-acao-williams {

        bottom: 5%;

        right: 6%;

        font-size: 6px;
    }


    .piloto-albon-williams
    .piloto-acao-williams {

        left: 6%;

        right: auto;
    }


    .piloto-acao-williams strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-williams {

        padding:
            20px 8px;
    }


    .pilotos-titulo-williams h2 {

        font-size: 25px;
    }


    .pilotos-titulo-williams p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-williams {

        font-size: 115px;
    }


    .piloto-albon-williams
    .piloto-numero-bg-williams {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-williams {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-williams {

        bottom: 12%;
    }


    .piloto-dados-williams h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-williams {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-williams span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-williams,
    .piloto-williams::before,
    .piloto-numero-bg-williams,
    .piloto-foto-williams img,
    .piloto-dados-williams,
    .piloto-dados-williams h3::before,
    .piloto-dados-williams h3 strong,
    .piloto-linha-williams,
    .piloto-acao-williams,
    .piloto-acao-williams strong {

        animation: none !important;

        transition: none !important;
    }

}



