/*=========================================================
   williams — linha-evolution
========================================================= */

.williams-linha-evolution {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 600px;

    overflow: hidden;

    box-sizing: border-box;

    padding: 38px 4vw 25px;

    background: #050708;

    color: #fff;
}


/* =========================================================
   HEADER
========================================================= */

.linha-evolution-header-williams {
    position: relative;

    z-index: 10;

    text-align: center;

    margin-bottom: 28px;
}


.linha-evolution-header-williams > span {
    font-size: 13px;

    font-weight: 800;

    letter-spacing: 4px;

    color: rgba(220,255,255,.42);
}


.linha-evolution-header-williams h2 {
    margin: 6px 0 3px;

    font-size: clamp(28px, 4vw, 48px);

    line-height: 1;

    font-weight: 300;

    letter-spacing: -2px;
}


.linha-evolution-header-williams h2 strong {
    font-weight: 900;

    color: #005AFF;

    text-shadow:
        0 0 25px rgba(190,255,255,.2);
}


.linha-evolution-header-williams p {
    margin: 0;

    font-size: 15px;

    color: rgba(255,255,255,.35);

    letter-spacing: 1px;
}


/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-williams {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: flex;
    align-items: center;
    justify-content: center;
    grid-template-columns:
        repeat(5, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}

.linha-evolution-grid-williams
.linha-evolution-team-williams {
    width: min(420px, 70vw);
    height: 100%;
    flex: 0 0 min(420px, 70vw);
}
/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-williams {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-williams:hover
.linha-evolution-team-williams {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-williams
.linha-evolution-team-williams:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-williams {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-williams:hover
.team-bg-number-williams {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-williams {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-williams::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-williams img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-williams:hover
.team-image-williams {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-williams:hover
.team-image-williams::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-williams:hover
.team-image-williams img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-williams {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-williams:hover
.team-content-williams {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-williams {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-williams h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-williams {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-williams:hover
.team-line-williams {

    width: 65px;
}


/* Função */

.team-role-williams {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-williams {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-williams:hover
.team-arrow-williams {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


/* =========================================================
   CORES DAS EQUIPES
========================================================= */





/* =========================================================
   williams ATUAL
========================================================= */

.team-williams-current {

    --team-color: #005AFF;

    --team-glow:
        rgba(0,90,255,.8);
}


.team-williams-current:hover {

    background:
        linear-gradient(
            145deg,
            #071716,
            #050708 70%
        );

    border-color:
        rgba(0,90,255,.18);
}


.team-williams-current
.team-content-williams h3 {

    color: #005AFF;
}


.team-williams-current
.team-image-williams img {

    filter:
        grayscale(0%)
        brightness(.95);

    opacity: .85;
}


/* =========================================================
   FOOTER
========================================================= */

.linha-evolution-footer-williams {

    position: absolute;

    z-index: 10;

    left: 4vw;

    right: 4vw;

    bottom: 15px;

    display: flex;

    align-items: center;

    gap: 12px;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 3px;

    color:
        rgba(0,90,255,.25);
}


.footer-line-williams {

    height: 1px;

    flex: 1;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12)
        );
}


.footer-line-williams:last-of-type {

    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.12),
            transparent
        );
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 900px) {

    .williams-linha-evolution {

        padding-left: 20px;

        padding-right: 20px;
    }


    .linha-evolution-grid-williams {

        grid-template-columns:
            repeat(
                5,
                minmax(120px, 1fr)
            );

        overflow-x: auto;

        scrollbar-width: none;
    }


    .linha-evolution-grid-williams::-webkit-scrollbar {

        display: none;
    }


    .linha-evolution-team-williams {

        min-width: 150px;
    }


    .team-content-williams {

        left: 14px;

        right: 14px;

        bottom: 18px;
    }

}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .williams-linha-evolution {

        height: auto;

        min-height: 100dvh;

        padding:
            32px 15px 55px;
    }


    .linha-evolution-header-williams {

        margin-bottom: 18px;
    }


    .linha-evolution-header-williams > span {

        font-size: 6px;

        letter-spacing: 2px;
    }


    .linha-evolution-header-williams h2 {

        font-size: 28px;
    }


    .linha-evolution-header-williams p {

        font-size: 8px;
    }


    .linha-evolution-grid-williams {

        height: 62dvh;

        grid-template-columns:
            repeat(5, 145px);

        gap: 3px;

        overflow-x: auto;

        padding-bottom: 8px;
    }


    .linha-evolution-team-williams {

        min-width: 145px;
    }


    .team-image-williams {

        width: 75%;

        height: 55%;
    }


    .team-content-williams {

        left: 12px;

        bottom: 15px;
    }


    .team-content-williams h3 {

        font-size: 19px;
    }


    .team-bg-number-williams {

        font-size: 110px;
    }


    .team-arrow-williams {

        top: 12px;

        left: 12px;

        width: 22px;

        height: 22px;
    }


    .linha-evolution-footer-williams {

        left: 15px;

        right: 15px;
    }

}


.tabela-williams{
    padding:clamp(80px, 12vw, 140px) 20px;

    background:linear-gradient(
      120deg,
      #00112b 0%,
      #003b8f 25%,
      #0055cc 55%,
      #0077ff 80%,
      #58a6ff 100%
    );

    color:#fff;
}

/* ===== TÍTULO ===== */
.titulo-tabela-williams{
    text-align:center;

    font-size:clamp(28px, 4vw, 46px);

    margin-bottom:60px;

    display:flex;
    justify-content:center;
    align-items:center;
    gap:12px;
}

/* LOGO */
.logo-titulo-wil{
    width:clamp(28px, 4vw, 46px);

    filter:drop-shadow(
      0 0 12px rgba(120,190,255,.8)
    );

    transition:.3s ease;
}

.titulo-tabela-williams:hover .logo-titulo-wil{
    transform:scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-williams{
    width:90%;
    max-width:1500px;

    margin:auto;

    background:rgba(0,0,0,0.72);

    border-radius:20px;

    backdrop-filter:blur(8px);

    box-shadow:
      0 0 40px rgba(0,90,255,0.18),
      inset 0 0 30px rgba(0,90,255,0.06);
}

/* ===== TABELA ===== */
.box-tabela-williams table{
    width:100%;

    border-collapse:collapse;

    min-width:600px;
}

/* ===== LINHAS ===== */
.box-tabela-williams tr{
    transition:.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-williams td{
    padding:clamp(18px, 2.5vw, 28px);

    font-size:clamp(15px, 2vw, 20px);

    border-bottom:
      1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-williams td:first-child{
    color:#58a6ff;

    font-weight:bold;

    width:50%;
}

/* SEGUNDA COLUNA */
.box-tabela-williams td:last-child{
    text-align:right;

    color:#e6e6e6;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-williams tr:hover{
    background:linear-gradient(
      90deg,
      rgba(0,90,255,0.16),
      rgba(88,166,255,0.10)
    );

    transform:scale(1.01);
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .box-tabela-williams{
    width:95%;
    overflow:hidden;
  }

  .box-tabela-williams table{
    width:100%;
    min-width:100%;
  }

  .box-tabela-williams td{
    padding:10px 8px;
    font-size:18px;
  }

  .box-tabela-williams td:first-child{
    width:45%;
    font-size:16px;
  }

  .box-tabela-williams td:last-child{
    width:55%;
    font-size:18px;

    text-align:right;

    word-break:break-word;
  }

  .titulo-tabela-williams{
    font-size:22px;
  }

}


/* =====================================
   TEMPORADA williams 2026
===================================== */

.temporada-williams{

    position:relative;

    overflow:hidden;

    padding:80px 20px;

    color:#fff;

    background:
    radial-gradient(
        circle at top,
        #005aff 0%,
        #120900 45%,
        #050505 100%
    );

}


/* brilho de fundo */

.temporada-williams::before{

    content:"";

    position:absolute;

    top:-200px;

    right:-200px;

    width:500px;

    height:500px;


    background:
    radial-gradient(
        circle,
        rgba(0,90,255,.18),
        transparent 70%
    );


    filter:blur(50px);

}


.temporada-williams > *{

    position:relative;

    z-index:2;

}



/* =====================================
   TÍTULO
===================================== */


.titulo-temp-williams{

    text-align:center;

    margin-bottom:50px;

    font-size:
    clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:3px;


    color:#fff;


    text-shadow:

    0 0 20px
    rgba(0,90,255,.55);

}



/* =====================================
   DASHBOARD
===================================== */


.dashboard-williams{

    max-width:1200px;

    margin:auto;

}



/* =====================================
   TOPO
===================================== */


.topo-temp-williams{

    display:grid;

    grid-template-columns:

    220px 1fr 220px;

    gap:20px;

    align-items:center;

}



/* =====================================
   CARD POSIÇÃO
===================================== */


.card-campeonato-williams,
.card-pontos-williams,
.card-grafico-williams{


    background:

    linear-gradient(
        145deg,
        #161616,
        #202020
    );


    border-radius:25px;


    border:

    1px solid
    rgba(0,90,255,.2);


    box-shadow:

    0 15px 35px
    rgba(0,0,0,.35);


}



/* posição */

.card-campeonato-williams,
.card-pontos-williams{


    padding:30px 20px;

    text-align:center;

}



.valor-posicao-williams{

    font-size:70px;

    font-weight:900;

    color:#005aff;


    text-shadow:

    0 0 20px
    rgba(0,90,255,.5);

}



.card-campeonato-williams p,
.card-pontos-williams p{


    margin:10px 0 0;


    color:#bbb;


    font-weight:700;

    text-transform:uppercase;

    font-size:14px;

}



/* =====================================
   PONTOS
===================================== */


#pontoswilliams{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-williams{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-williams svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficowilliams{


    stroke:#005aff;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(0,90,255,.8)
    );


}

/* =====================================
   DESEMPENHO williams
===================================== */

.desempenho-williams{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-williams > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(0,90,255,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-williams > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(0,90,255,.55);



    box-shadow:

    0 0 25px
    rgba(0,90,255,.25);


}



/* números */

.desempenho-williams span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#005aff;



    text-shadow:

    0 0 15px
    rgba(0,90,255,.45);


}



/* textos */

.desempenho-williams p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-williams span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(0,90,255,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(0,90,255,.75);

    }


}



/* =====================================
   DESTAQUE williams
===================================== */


.card-campeonato-williams::before,
.card-pontos-williams::before,
.card-grafico-williams::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(0,90,255,.12),
        transparent 45%
    );


    pointer-events:none;


}



/* garante posição dos cards */

.card-campeonato-williams,
.card-pontos-williams,
.card-grafico-williams{


    position:relative;


    overflow:hidden;


}

/* =====================================
   RESULTADOS williams
===================================== */

.resultados-williams{

    margin-top:45px;

    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );

    border-radius:25px;

    padding:25px;

    border:

    1px solid
    rgba(0,90,255,.18);

    box-shadow:

    0 15px 35px
    rgba(0,0,0,.4);

    overflow:hidden;

}



/* tabela */

.resultados-williams table{

    width:100%;

    border-collapse:collapse;

}



/* cabeçalho */

.resultados-williams th{


    padding:16px;


    background:

    rgba(0,90,255,.15);


    color:#005aff;


    text-transform:uppercase;


    font-size:14px;


    letter-spacing:1px;

}



/* células */

.resultados-williams td{


    padding:14px;


    text-align:center;


    color:#ddd;


    border-bottom:

    1px solid
    rgba(255,255,255,.06);


    font-weight:600;

	 font-size:25px;

}



/* hover linha */

.resultados-williams tbody tr{


    transition:.3s ease;


}



.resultados-williams tbody tr:hover{


    background:

    rgba(0,90,255,.08);


    transform:

    scale(1.01);

}



/* primeira coluna */

.resultados-williams td:first-child{


    color:#005aff;


    font-weight:900;

}



/* =====================================
   TOTAL PONTOS
===================================== */


.total-williams{


    margin-top:25px;


    padding:18px;


    border-radius:18px;


    text-align:center;


    background:

    linear-gradient(
        145deg,
        #005aff,
        #005aff
    );


    color:#fff;


    font-size:22px;


    font-weight:900;


    box-shadow:

    0 0 25px
    rgba(0,90,255,.35);

}



#totalTabelawilliams{


    font-size:32px;


    margin-left:8px;

}



/* =====================================
   RESPONSIVO TABLET
===================================== */


@media(max-width:900px){


    .topo-temp-williams{


        grid-template-columns:

        1fr;


    }


    .card-grafico-williams{


        height:260px;

    }


    .desempenho-williams{


        grid-template-columns:

