}


/*==================================================
        IMAGEM PIASTRI
==================================================*/

.williams-right-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.williams-right-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(30,65,255,.3)
    );

    transition:
    transform .4s ease;

	  transform:translateY(-70px);

}


.williams-right-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        CENTRO
==================================================*/

.williams-middle{

    width:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:center;

    position:relative;

    z-index:10;

}


/*==================================================
        VS
==================================================*/

.williams-vs{

    display:flex;

    align-items:center;

    justify-content:center;

    margin-bottom:12px;

}


.williams-vs-box{

    width:75px;

    height:75px;

    display:flex;

    align-items:center;

    justify-content:center;

    border-radius:50%;

    font-size:30px;

    font-weight:1000;

    color:#f0f0f0;

    background:#005aff;

    border:4px solid white;

    box-shadow:
    0 0 30px rgba(30,65,255,.65);

}


/*==================================================
        TEMPORADA
==================================================*/

.williams-season{

    margin-bottom:20px;

    text-align:center;

    font-size:17px;

    font-weight:800;

    letter-spacing:4px;

    color:#f0f0f0;

}


/*==================================================
        ESTATÍSTICAS
==================================================*/

.williams-stats{

    width:100%;

    display:flex;

    flex-direction:column;

    gap:13px;

}


/*==================================================
        CADA ESTATÍSTICA
==================================================*/

.williams-stat{

    width:100%;

}


/*==================================================
        VALORES

        NORRIS | LABEL | PIASTRI
==================================================*/

.williams-stat-values{

    width:100%;

    display:grid;

    grid-template-columns:
        70px
        1fr
        70px;

    align-items:center;

}


.williams-value{

    display:flex;

    align-items:center;

    justify-content:center;

    font-size:28px;

    line-height:1;

    font-weight:1000;

    color:white;

}


.williams-label{

    text-align:center;

    font-size:14px;

    font-weight:900;

    letter-spacing:2px;

    color:#005aff;

    white-space:nowrap;

}


/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.williams-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.williams-bar-left,
.williams-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.williams-bar-left{

    border-radius:999px 0 0 999px;

}


.williams-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #45c1ff,
        #005aff
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.williams-bar-right{

    border-radius:0 999px 999px 0;

}


.williams-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #005aff,
        #45c1ff
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.williams-value{

    animation:
    williamsValueShow .5s ease;

}


@keyframes williamsValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.williams-winner{

    color:#005aff !important;

    text-shadow:
    0 0 15px rgba(30,65,255,.8);

}


.williams-draw{

    color:#020202 !important;

}


/*==================================================
        TABLET
==================================================*/

@media(max-width:1100px){

    .williams-layout{

        grid-template-columns:
            minmax(0,1fr)
            minmax(360px,450px)
            minmax(0,1fr);

        gap:10px;

    }


    .williams-stat-values{

        grid-template-columns:
            55px
            1fr
            55px;

    }


    .williams-value{

        font-size:24px;

    }


    .williams-label{

        font-size:12px;

    }


    .williams-left-name h3,
