        grid-row:1;

    }


    .williams-left-image,
    .williams-right-image{

        height:220px;

        flex:none;

    }


    .williams-left-image img,
    .williams-right-image img{

        height:220px;
			 transform:translateY(-10px);

    }


    .williams-left-name h3,
    .williams-right-name h3{

        font-size:30px;

    }


    .williams-left-name span,
    .williams-right-name span{

        font-size:11px;

        letter-spacing:3px;

    }


    .williams-vs-box{

        width:55px;

        height:55px;

        font-size:23px;

    }


    .williams-season{

        font-size:13px;

        margin-bottom:10px;

    }


    .williams-stats{

        gap:8px;

    }


    .williams-stat-values{

        grid-template-columns:
            45px
            1fr
            45px;

    }


    .williams-value{

        font-size:20px;

    }


    .williams-label{

        font-size:10px;

        letter-spacing:1px;

    }


    .williams-bars{

        height:8px;

    }

}



