}



/*==================================================
        VALORES
==================================================*/

.chart-value-williams{

    fill:#eee;

    font-size:18px;

    font-weight:700;

    text-anchor:middle;

}


.chart-year-williams{

    fill:#777780;

    font-size:20px;

    text-anchor:middle;

}



/*==================================================
        SIDEBAR
==================================================*/

.evolution-sidebar-williams{

