.timeline-williams{
  position:relative;

  padding:10px 40px;
  overflow:hidden;

  background:
    radial-gradient(
      circle at top right,
      rgba(0,180,255,.12),
      transparent 25%
    ),

    radial-gradient(
      circle at bottom left,
      rgba(0,80,255,.18),
      transparent 35%
    ),

    linear-gradient(
      135deg,
      #080808 0%,
      #0a1020 20%,
      #0d1a40 45%,
      #102a66 70%,
      #1a3f99 100%
    );
}

.timeline-williams::before{
  content:"";

  position:absolute;
  inset:0;

  background:
    linear-gradient(
      120deg,
      transparent 0%,
      rgba(255,255,255,.03) 45%,
      transparent 100%
    );

  pointer-events:none;
}

/* ===== TÍTULO ===== */
.titulo-timeline-williams{
  text-align:center;

  color:#4aa3ff;

  text-shadow:
    0 0 10px #4aa3ff,
    0 0 20px #4aa3ff,
    0 0 35px rgba(74,163,255,.8);

  font-size:42px;

  margin-bottom:300px;

  box-shadow:0 15px 40px rgba(0,0,0,0.7);
}

/* ===== LINHA ===== */
.linha-box-williams{
  position:relative;

  width:100%;
  height:4px;

  margin-bottom:400px;
}

.linha-cinza-williams{
  position:absolute;

  width:100%;
  height:4px;

  background:#333;
}

.linha-progresso-williams{
  position:absolute;

  width:0%;
  height:4px;

  background:linear-gradient(
    90deg,
    #0044ff,
    #4aa3ff,
    #00d4ff
  );

  box-shadow:
    0 0 12px #4aa3ff,
    0 0 24px rgba(0,100,255,.5);

  transition:width .8s;
}

/* ===== PONTO ===== */
.ponto-williams{
  position:absolute;

  top:30%;

  transform:translate(-50%,-50%);

  text-align:center;

  transition:.3s ease;
}

.ponto-williams:hover{
  z-index:20;
}

.ponto-williams::after{
  content:"";

  width:12px;
  height:12px;

  background:#666;

  display:block;

  border-radius:50%;

  margin:8px auto;

  transition:.4s;
}

.ponto-williams.ativo::after{
  background:#4aa3ff;

  box-shadow:
    0 0 12px #4aa3ff,
    0 0 24px rgba(0,150,255,.5);
}

/* ===== ANO ===== */
.ano-williams{
  position:absolute;

  left:50%;

  transform:translateX(-50%);

  font-size:30px;

  color:#b3d9ff;

  text-shadow:0 0 10px rgba(74,163,255,.5);

  opacity:0;

  font-weight:700;

  transition:.3s ease;
}

.ano-williams.cima{
  top:30px;
}

.ano-williams.baixo{
  top:-30px;
}

/* ===== TROFÉU ===== */
.titulo-num-williams{
  font-size:25px;

  padding:5px 15px;

  border-radius:20px;

  background:#0d0d0d;

  color:#fff;

  border-left:3px solid #4aa3ff;

  font-weight:800;

  letter-spacing:1px;

  box-shadow:0 4px 10px rgba(0,0,0,.35);

  transition:.35s ease;
}

.ponto-williams:hover .titulo-num-williams{
  transform:scale(1.08);

  background:#111;

  color:#00d4ff;

  box-shadow:
    0 0 15px rgba(0,100,255,.35),
    0 0 30px rgba(74,163,255,.15);
}

/* ===== FOTO ===== */
.foto-cima-williams,
.foto-baixo-williams{
  position:absolute;

  left:50%;

  transform:translateX(-50%) scale(.6);

  opacity:0;

  transition:.6s ease;
}

.foto-cima-williams img,
.foto-baixo-williams img{
  width:120px;

  border-radius:12px;

  border:2px solid #4aa3ff;
}

.foto-cima-williams{
  bottom:70px;
}

.foto-baixo-williams{
  top:80px;
}

/* ===== INFO ===== */
.info-cima-williams,
.info-baixo-williams{
  position:absolute;

  left:50%;

  transform:translateX(-50%);

  color:#4aa3ff;

  opacity:0;

  transition:.3s ease;
}

.info-cima-williams{
  bottom:25px;
}

.info-baixo-williams{
  top:-6px;
}

/* ===== HOVER INFO ===== */
.info-cima-williams:hover,
.info-baixo-williams:hover{
  transform:
    translateX(-50%)
    translateY(-6px);

  filter:brightness(1.15);

  color:#00d4ff;

  text-shadow:
    0 0 10px rgba(74,163,255,.9),
    0 0 20px rgba(0,212,255,.45);
}

.info-cima-williams p,
.info-baixo-williams p{
  font-size:30px;

  margin-top:30px;

  color:#d6ecff;

  display:flex;
  align-items:center;
  justify-content:center;

  gap:8px;

  white-space:nowrap;
}

/* ===== ATIVO ===== */
.ponto-williams.ativo .foto-cima-williams,
.ponto-williams.ativo .foto-baixo-williams{
  opacity:1;

  transform:translateX(-50%) scale(1);
}

.ponto-williams.ativo .info-cima-williams,
.ponto-williams.ativo .info-baixo-williams{
  opacity:1;
}

/* ===== RESPONSIVO ===== */
@media (max-width:768px){

  .timeline-williams{
    padding:60px 10px;
    margin-top:100px;
  }

  .titulo-timeline-williams{
    font-size:28px;
    margin-bottom:90px;
  }

  .ponto-williams{
    transform:translate(-50%,-50%) scale(.75);
  }

  .foto-cima-williams img,
  .foto-baixo-williams img{
    width:28px;
  }

  .ano-williams{
    font-size:10px;
  }

  .titulo-num-williams{
    font-size:10px;
    padding:2px 6px;
  }

}


