.bg-hall-williams{
position:absolute;
inset:0;
z-index:0;
}

.bg-layer-williams{
position:absolute;
inset:0;

background-size:cover;
background-position:center;

opacity:0;

transition:opacity .8s ease;
}

.bg-layer-williams.active{
opacity:1;
}

.hall-grid-williams,
.titulo-hall-williams,
.hall-overlay-williams{
