  width:100%;
  padding:120px 25px;
  overflow:hidden;

  background:
  radial-gradient(circle at top,#0a1a3a 0%,#050814 60%);

  transition:background 1s ease;
}

/* ERAS */
.williams-evolution.bg-1980s{
  background:radial-gradient(circle at top,#4da3ff,#0a1a3a,#050814);
}

.williams-evolution.bg-1990s{
  background:radial-gradient(circle at top,#7fb8ff,#1a3d7a,#050814);
}

.williams-evolution.bg-2000s{
  background:radial-gradient(circle at top,#a8d0ff,#2457a8,#050814);
}

.williams-evolution.bg-2010s{
  background:radial-gradient(circle at top,#cfe6ff,#1f4c9e,#050814);
}

.williams-evolution.bg-2020s{
  background:radial-gradient(circle at top,#ffffff,#4da3ff,#050814);
}

/* BRILHO */
.williams-evolution::before{
  content:"";
  position:absolute;
  top:-200px;
  left:-200px;

  width:500px;
  height:500px;

  background:radial-gradient(circle,rgba(77,163,255,.25),transparent 70%);
  filter:blur(30px);
  animation:glowMoveWilliams 8s linear infinite;
}

.williams-evolution::after{
  content:"";
  position:absolute;
  right:-150px;
  bottom:-150px;

  width:450px;
  height:450px;

  background:radial-gradient(circle,rgba(255,255,255,.05),transparent 70%);
  filter:blur(50px);
}

/* TÍTULO */
.title-williams{
  text-align:center;
  font-size:clamp(2.5rem,6vw,5rem);
  margin-bottom:80px;

  font-weight:900;
  letter-spacing:3px;
  text-transform:uppercase;

  background:linear-gradient(90deg,#0d2b66,#4da3ff);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
}

/* CARRO */
.car-container-williams{
  position:relative;
  width:100%;
  max-width:900px;
  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;
}

.car-circle-williams{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:2px solid rgba(77,163,255,.25);

  box-shadow:
  0 0 40px rgba(77,163,255,.2),
  inset 0 0 40px rgba(77,163,255,.08);

  animation:rotateCircleWilliams 14s linear infinite;
}

/* IMG */
.car-container-williams img{
  width:100%;
  max-width:580px;

  filter:drop-shadow(0 30px 35px rgba(0,0,0,.6));

  animation:floatWilliams 5s ease-in-out infinite;

  transition:.45s;
}

/* BOTÕES */
.controls-williams{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin:50px 0 90px;
}

.controls-williams button{
  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:linear-gradient(145deg,#4da3ff,#0d2b66);

  color:#fff;
  font-weight:800;

  cursor:pointer;
  transition:.35s;
}

.controls-williams button:hover{
  transform:translateY(-6px) scale(1.05);
  box-shadow:0 10px 30px rgba(77,163,255,.35);
}

/* INFO */
.car-info-williams{
  max-width:1200px;
  margin:auto;
}

.car-info-williams h2{
  text-align:center;
  font-size:clamp(2rem,5vw,3.5rem);
  margin-bottom:50px;
  color:#fff;
}

.info-grid-williams{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
  gap:25px;
}

.info-card-williams{
  padding:35px 28px;

  border-radius:28px;

  background:linear-gradient(145deg,rgba(255,255,255,.06),rgba(255,255,255,.02));

  border:1px solid rgba(77,163,255,.15);

  backdrop-filter:blur(14px);

  transition:.45s;
}

.info-card-williams:hover{
  transform:translateY(-12px);
  border-color:rgba(77,163,255,.5);
  box-shadow:0 15px 40px rgba(0,0,0,.45);
}

.info-card-williams span{
  display:block;
  margin-bottom:14px;
  color:#7fb8ff;
  text-transform:uppercase;
  font-size:.8rem;
}

.info-card-williams h3{
  color:#fff;
}

/* ANIMAÇÕES */
@keyframes rotateCircleWilliams{
  from{transform:rotate(0deg);}
  to{transform:rotate(360deg);}
}

@keyframes floatWilliams{
  0%,100%{transform:translateY(0);}
  50%{transform:translateY(-15px);}
}

@keyframes glowMoveWilliams{
  0%{transform:translate(0,0);}
  50%{transform:translate(80px,40px);}
  100%{transform:translate(0,0);}
}


.eras-williams{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
    radial-gradient(circle at top,
    #7ec8ff 0%,
    #0057b8 35%,
    #001d4d 70%,
    #050505 100%);

    overflow:hidden;

    color:#eef6ff;
}

/* GLOW FUNDO */
.eras-williams::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(0,120,255,.24),
    transparent 70%);

    filter:blur(40px);

    animation:williamsGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-williams::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(255,255,255,.10),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-williams > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-eras-williams{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #7ec8ff,
    #d7ecff);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(0,120,255,.35);
}

/* ===== TEXTO ===== */
#textoEra-williams{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#eef6ff;

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-williams{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-williams button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #07152b,
    #0f2d57);

    color:#7ec8ff;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(126,200,255,.14);
}

/* brilho botão */
.botoes-eras-williams button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-williams button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-williams button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #0077ff,
    #0057b8);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(0,120,255,.35);
}

/* BOTÃO ATIVO */
.botoes-eras-williams .ativo{
    background:
    linear-gradient(
    145deg,
    #7ec8ff,
    #0077ff);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(0,120,255,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#williams-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.williams-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(126,200,255,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.williams-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.williams-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.williams-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(126,200,255,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(0,120,255,.2);
}

/* ===== IMAGEM ===== */
.williams-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.williams-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(0,120,255,.3));
}

/* ===== ANO ===== */
.williams-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#7ec8ff;

    text-shadow:
    0 0 12px rgba(126,200,255,.3);
}

/* ===== TEXTO ===== */
#williams-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#eef6ff;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes williamsGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-williams{
        padding:90px 18px;
    }

    .titulo-eras-williams{
        font-size:2.5rem;
    }

    #textoEra-williams{
        font-size:1rem;
    }

    .botoes-eras-williams{
        gap:10px;
    }

    .botoes-eras-williams button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #williams-timeline{
        grid-template-columns:1fr;
    }

    .williams-timeline-item{
        max-width:360px;
        margin:auto;
    }

}



