body.rb{
   background: #F8F9FA;
 }
 
 



/* ==================================================
=========================================================
   RB HERO
========================================================= */

.rb-hero {
    position: relative;
    width: 100%;
    height: 100dvh;
    min-height: 620px;
    overflow: hidden;
    background: #020713;
    color: #fff;
    isolation: isolate;
}


/* =========================================================
   CARRO — FUNDO PRINCIPAL
========================================================= */

.rb-car-bg {
    position: absolute;
    inset: -5%;
    z-index: -5;

    background-image:
        url("carros/rb26.webp");

    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;

    filter:
        brightness(.58)
        contrast(1.08)
        saturate(1.12);

    transform: scale(1.04);

    transition:
        transform 1s ease,
        filter 1s ease;
}


/* LEVE MOVIMENTO */

.rb-hero:hover .rb-car-bg {
    transform: scale(1.07);

    filter:
        brightness(.63)
        contrast(1.1)
        saturate(1.15);
}


/* =========================================================
   OVERLAY
========================================================= */

.rb-overlay {
    position: absolute;
    inset: 0;
    z-index: -4;

    background:

        /* AZUL */
        linear-gradient(
            115deg,
            rgba(0,87,184,.78),
            transparent 42%
        ),

        /* VERMELHO */
        linear-gradient(
            250deg,
            rgba(255,215,0,.32),
            transparent 42%
        ),

        /* ESCURECIMENTO */
        linear-gradient(
            to bottom,
            rgba(0,0,0,.55),
            transparent 25%,
            rgba(0,0,0,.08) 55%,
            rgba(0,0,0,.82) 100%
        );
}


/* =========================================================
   TOPO
========================================================= */

.rb-top {
    position: absolute;

    top: 25px;
    left: 4vw;
    right: 4vw;

    z-index: 30;

    display: flex;
    align-items: center;
    justify-content: space-between;
}


/* =========================================================
   HOME
========================================================= */

.rb-home {
    display: flex;
    align-items: center;

    gap: 8px;

    padding: 9px 13px;

    text-decoration: none;

    color: rgba(255,255,255,.75);

    border: 1px solid rgba(255,255,255,.2);

    background: rgba(0,0,0,.3);

    backdrop-filter: blur(10px);

    font-size: 25px;
    font-weight: 900;
    letter-spacing: 2px;

    transition: .35s ease;
}

.rb-home i {
    font-size: 20px;
}

.rb-home:hover {
    color: #057;

    background: rgba(249,249,249,.22);

    border-color: #F9F9F9;

    transform: translateY(-3px);
}


/* =========================================================
   STATUS
========================================================= */

.rb-status {
    position: absolute;

    left: 50%;

    transform: translateX(-50%);

    font-size: 15px;
    font-weight: 900;
    letter-spacing: 4px;

    color: rgba(255,255,255,.55);
}


/* =========================================================
   RB — REDES SOCIAIS INFERIORES
========================================================= */

.rb-social-top {
    position: absolute;

    z-index: 30;

    left: 50%;
    bottom:110px;

    transform: translateX(-13%);

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 7px;
}


/* =========================================================
   ÍCONES
========================================================= */

.rb-social-top a {
    width: 100px;
    height: 100px;

    display: flex;
    align-items: center;
    justify-content: center;

    text-decoration: none;

    color: rgba(255,255,255,.65);

    border: 1px solid rgba(255,255,255,.16);

    background:
        linear-gradient(
            135deg,
            rgba(10,15,30,.78),
            rgba(0,0,0,.45)
        );

    backdrop-filter: blur(8px);

    font-size: 30px;

    transition:
        transform .35s ease,
        color .35s ease,
        background .35s ease,
        border-color .35s ease,
        box-shadow .35s ease;
