/* =========================================================
   HOVER
========================================================= */

.rb-social-top a:hover {
    color: #058;

    background:#F9F9F9;

    border-color:#0057B8 ;

    transform:
        translateY(-5px)
        scale(1.08);

    box-shadow:
        0 8px 22px rgba(255,215,0,.35),
        0 0 15px rgba(255,215,0,.15);
}


/* =========================================================
   LINHA DECORATIVA
========================================================= */

.rb-social-top::before,
.rb-social-top::after {
    content: "";

    width: 55px;
    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,215,0,.7)
        );
}


.rb-social-top::after {
    background:
        linear-gradient(
            90deg,
            rgba(255,215,0,.7),
            transparent
        );
}


/* =========================================================
   LOGO RB
========================================================= */

.rb-logo {
    position: absolute;

    z-index: 8;

    right: 4vw;
    top: -50px;

    width: 300px;
    height: 300px;

    display: flex;
