    z-index: 2;

    width: 100%;
    height: 100%;

    object-fit: contain;

    display: block;

    filter: drop-shadow(0 5px 15px rgba(0,0,0,.6));
}


/* =========================================================
   ANIMAÇÃO DA LOGO
========================================================= */

@keyframes rb-logo-float {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-7px);
    }

}


/* =========================================================
   GLOW DA LOGO
========================================================= */

.rb-logo-glow {
    position: absolute;

    z-index: 1;

    width: 220px;
    height: 220px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(249,249,249,.3),
            rgba(249,249,249,.15),
