/* =========================================================
   NOME DA EQUIPE
========================================================= */

.rb-main {
    position: absolute;

    z-index: 20;

    left: 7vw;
    top: 28%;

    max-width: 520px;
}

.rb-kicker {
    font-size: 25px;
	  letter-spacing:3px;
    font-weight: 900;
    color: #FFD700;
}

.rb-main h1 {
    margin: 8px 0 4px;
    color:#F9F9F9;
	font-size:
        clamp(45px,6vw,92px);

    line-height: .82;

    font-weight: 900;

    letter-spacing: -5px;

    text-shadow:
        0 8px 30px rgba(0,0,0,.8);
}

.rb-main h1 strong {
    display: block;

    font-weight: 300;

    color: #fff;

    letter-spacing: -3px;
}

.rb-full-name {
    margin: 14px 0 0;

    font-size: 18px;

    font-weight: 900;

    letter-spacing: 4px;

    color: rgba(255,255,255,.5);
}

/* =========================================================
   RODAPÉ
========================================================= */

.rb-bottom {
    position: absolute;

    z-index: 25;

    left: 4vw;
    right: 4vw;

    bottom: 82px;

    display: flex;

    align-items: center;

    gap: 15px;

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 3px;

    color: rgba(255,255,255,.53);
}

.rb-bottom div {
