    height: 2px;

    background:
        linear-gradient(
            90deg,
            rgba(255,215,0,.8),
            rgba(249,249,249,.5)
            
        );
}


/* =========================================================
   RB — PULSOS LUMINOSOS
========================================================= */

.rb-pulsos {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 3;
    pointer-events: none;
}

/* PONTO */

.rb-pulsos span {
    position: absolute;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    opacity: 0;

    animation:
        rbPulso
        var(--tempo)
        ease-in-out
        var(--atraso)
        infinite;
}


/* =========================================================
   CORES RB
========================================================= */

.rb-pulsos span:nth-child(3n + 1) {
    background: #F9F9F9;

    box-shadow:
        0 0 5px #F9F9F9,
        0 0 12px rgba(249,249,249,.9),
        0 0 25px rgba(249,249,249,.5);
}


.rb-pulsos span:nth-child(3n + 2) {
    background: #0057B8;

    box-shadow:
        0 0 5px #0057B8,
        0 0 12px rgba(0,87,184,.9),
        0 0 25px rgba(0,87,184,.5);
}


.rb-pulsos span:nth-child(3n) {
    background: #FFD700;

    box-shadow:
        0 0 5px #FFD700,
        0 0 12px rgba(255,215,0 ,.9),
        0 0 25px rgba(255,215,0 ,.5);
}


/* =========================================================
   DISTRIBUIÇÃO
========================================================= */

.rb-pulsos span:nth-child(1)  { left:3%;  top:8%;  }
.rb-pulsos span:nth-child(2)  { left:9%;  top:22%; }
.rb-pulsos span:nth-child(3)  { left:15%; top:42%; }
.rb-pulsos span:nth-child(4)  { left:7%;  top:67%; }
.rb-pulsos span:nth-child(5)  { left:18%; top:88%; }

