/* ===========================
   TOPBAR RB
=========================== */

.topbar-RB{

width:100%;
max-width:100%;
overflow:hidden;
	
	height:70px;

    display:grid;
    grid-template-columns:60px 1fr 60px;

    align-items:center;

    background:#001b44;
    border-bottom:3px solid #ffffff;

    padding:0 10px;

    box-sizing:border-box;

    position:sticky;
    top:0;
    z-index:9998;
}
/* ===========================
MENU
=========================== */
.menu-toggle-RB{
    width:45px;
    height:45px;

    display:flex;
    align-items:center;
    justify-content:center;

    background:none;
    border:none;

    color:#ffffff;

    font-size:24px;

    cursor:pointer;

	border-radius:12px;
transition:.3s;
}

.menu-toggle-RB{
    justify-self:start;
}

.menu-toggle-RB:hover{

    transform:scale(1.15);

    color:#fff;

	background:rgba(0,27,68,.15);

}

/* ===========================
TÍTULO
=========================== */

.topbar-title-RB{

    display:flex;

    align-items:center;

    justify-content:center;

    gap:10px;

    color:#ffffff;

    font-size:22px;

    font-weight:800;

    overflow:hidden;

    white-space:nowrap;

}

.topbar-title-RB img{

    width:34px;
    height:34px;

    object-fit:contain;

    filter:
        drop-shadow(0 0 8px rgba(0,27,68,.45));

    flex-shrink:0;

}

.topbar-title-RB span{

    overflow:hidden;

    text-overflow:ellipsis;

}

/* ===========================
BOTÃO NOTÍCIAS
=========================== */

.news-toggle-RB{

    width:45px;
    height:45px;

    display:flex;
    align-items:center;
    justify-content:center;

    background:none;
    border:none;

    color:#ffffff;

    font-size:24px;

    cursor:pointer;

	border-radius:12px;
transition:.3s;
}


.news-toggle-RB{
    justify-self:end;
}
.news-toggle-RB:hover{

    transform:scale(1.15);

    color:#fff;

	background:rgba(0,27,68,.15);
}


/* ===========================
MENU LATERAL
=========================== */

.side-menu-RB{

    position:fixed;

    top:0;
    left:-300px;

    width:290px;
    height:100vh;

    background:linear-gradient(
        180deg,
        #ffffff 0%,
        #1a1207 35%,
