/* =========================================================
   rb — linha-evolution
========================================================= */

.rb-linha-evolution {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 600px;

    overflow: hidden;

    box-sizing: border-box;

    padding: 38px 4vw 25px;

    background: #050708;

    color: #fff;
}


/* =========================================================
   HEADER
========================================================= */

.linha-evolution-header-rb {
    position: relative;

    z-index: 10;

    text-align: center;

    margin-bottom: 28px;
}


.linha-evolution-header-rb > span {
    font-size: 13px;

    font-weight: 800;

    letter-spacing: 4px;

    color: rgba(220,255,255,.42);
}


.linha-evolution-header-rb h2 {
    margin: 6px 0 3px;

    font-size: clamp(28px, 4vw, 48px);

    line-height: 1;

    font-weight: 300;

    letter-spacing: -2px;
}


.linha-evolution-header-rb h2 strong {
    font-weight: 900;

    color: #F9F9F9;

    text-shadow:
        0 0 25px rgba(190,255,255,.2);
}


.linha-evolution-header-rb p {
    margin: 0;

    font-size: 15px;

    color: rgba(255,255,255,.35);

    letter-spacing: 1px;
}


/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-rb {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}


/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-rb {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-rb:hover
.linha-evolution-team-rb {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-rb
.linha-evolution-team-rb:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-rb {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-rb:hover
.team-bg-number-rb {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-rb {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-rb::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-rb img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-rb:hover
.team-image-rb {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-rb:hover
.team-image-rb::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-rb:hover
.team-image-rb img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-rb {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-rb:hover
.team-content-rb {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-rb {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-rb h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-rb {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-rb:hover
.team-line-rb {

    width: 65px;
}


/* Função */

.team-role-rb {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-rb {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-rb:hover
.team-arrow-rb {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


/* =========================================================
   CORES DAS EQUIPES
========================================================= */


/* =========================================================
   minardi
========================================================= */

.team-minardi-rb {

    --team-color: #F5C400;

    --team-glow:
	      rgba(245,196,0,.7)
}


.team-minardi-rb:hover {

    background:
        linear-gradient(
            145deg,
            #0a1726,
            #050708 70%
        );
}

/* =========================================================
   Alpha Tauri
========================================================= */

.team-alpha-rb {

    --team-color: #5C6770;

    --team-glow:
	      rgba(92,103,112,.7)
}


.team-alpha-rb:hover {

    background:
        linear-gradient(
            145deg,
            #0a1726,
            #050708 70%
        );
}


/* =========================================================
   tororosso
========================================================= */

.team-tororosso-rb {

    --team-color: #1E3A8A;

    --team-glow:
	      rgba(30,58,138,.7)
}


.team-tororosso-rb:hover {

    background:
        linear-gradient(
            145deg,
            #171819,
            #050708 70%
        );
}


/* =========================================================
   rb ATUAL
========================================================= */

.team-rb-current {

    --team-color: #F9F9F9;

    --team-glow:
        rgba(249,249,249,.8);
}


.team-rb-current:hover {

    background:
        linear-gradient(
            145deg,
            #071716,
            #050708 70%
        );

    border-color:
        rgba(249,249,249,.18);
}


.team-rb-current
.team-content-rb h3 {

    color: #F9F9F9;
}


.team-rb-current
.team-image-rb img {

    filter:
        grayscale(0%)
        brightness(.95);

    opacity: .85;
}


/* =========================================================
   FOOTER
========================================================= */

.linha-evolution-footer-rb {

    position: absolute;

    z-index: 10;

    left: 4vw;

    right: 4vw;

    bottom: 15px;

    display: flex;

    align-items: center;

    gap: 12px;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 3px;

    color:
        rgba(249,249,249,.25);
}


.footer-line-rb {

    height: 1px;

    flex: 1;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12)
        );
}


.footer-line-rb:last-of-type {

    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.12),
            transparent
        );
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 900px) {

    .rb-linha-evolution {

        padding-left: 20px;

        padding-right: 20px;
    }


    .linha-evolution-grid-rb {

        grid-template-columns:
            repeat(
                4,
                minmax(150px, 1fr)
            );

        overflow-x: auto;

        scrolltororosso-width: none;
    }


    .linha-evolution-grid-rb::-webkit-scrolltororosso {

        display: none;
    }


    .linha-evolution-team-rb {

        min-width: 150px;
    }


    .team-content-rb {

        left: 14px;

        right: 14px;

        bottom: 18px;
    }

}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .rb-linha-evolution {

        height: auto;

        min-height: 100dvh;

        padding:
            32px 15px 55px;
    }


    .linha-evolution-header-rb {

        margin-bottom: 18px;
    }


    .linha-evolution-header-rb > span {

        font-size: 6px;

        letter-spacing: 2px;
    }


    .linha-evolution-header-rb h2 {

        font-size: 28px;
    }


    .linha-evolution-header-rb p {

        font-size: 8px;
    }


    .linha-evolution-grid-rb {

        height: 62dvh;

        grid-template-columns:
            repeat(4, 145px);

        gap: 3px;

        overflow-x: auto;

        padding-bottom: 8px;
    }


    .linha-evolution-team-rb {

        min-width: 145px;
    }


    .team-image-rb {

        width: 75%;

        height: 55%;
    }


    .team-content-rb {

        left: 12px;

        bottom: 15px;
    }


    .team-content-rb h3 {

        font-size: 19px;
    }


    .team-bg-number-rb {

        font-size: 110px;
    }


    .team-arrow-rb {

        top: 12px;

        left: 12px;

        width: 22px;

        height: 22px;
    }


    .linha-evolution-footer-rb {

        left: 15px;

        right: 15px;
    }

}
   


.tabela-rb{
    padding:clamp(80px, 12vw, 140px) 20px;

    background:linear-gradient(
      120deg,
      rgba(120,120,125,1) 0%,
      rgba(70,70,75,1) 20%,
      rgba(0,70,255,1) 55%,
      rgba(0,120,255,1) 78%,
      rgba(255,0,0,0.9) 100%
    );

    color:#fff;
}

/* ===== TÍTULO ===== */
.titulo-tabela-rb{
    text-align:center;

    font-size:clamp(28px, 4vw, 46px);

    margin-bottom:60px;

    display:flex;
    justify-content:center;
    align-items:center;
    gap:12px;
}

/* LOGO */
.logo-titulo-rbs{
    width:clamp(28px, 4vw, 46px);

    filter:drop-shadow(
      0 0 12px rgba(0,120,255,.8)
    );

    transition:.3s ease;
}

.titulo-tabela-rb:hover .logo-titulo-rb{
    transform:scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-rb{
    width:90%;
    max-width:1500px;

    margin:auto;

    background:rgba(0,0,0,0.72);

    border-radius:20px;

    backdrop-filter:blur(8px);

    box-shadow:
      0 0 40px rgba(0,120,255,0.22),
      inset 0 0 30px rgba(255,0,0,0.08);
}

/* ===== TABELA ===== */
.box-tabela-rb table{
    width:100%;

    border-collapse:collapse;

    min-width:600px;
}

/* ===== LINHAS ===== */
.box-tabela-rb tr{
    transition:.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-rb td{
    padding:clamp(18px, 2.5vw, 28px);

    font-size:clamp(15px, 2vw, 20px);

    border-bottom:
      1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-rb td:first-child{
    color:#7ec8ff;

    font-weight:bold;

    width:50%;
}

/* SEGUNDA COLUNA */
.box-tabela-rb td:last-child{
    text-align:right;

    color:#f1f1f1;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-rb tr:hover{
    background:linear-gradient(
      90deg,
      rgba(0,120,255,0.18),
      rgba(255,0,0,0.10)
    );

    transform:scale(1.01);

    box-shadow:
      inset 0 0 18px rgba(0,120,255,.15);
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .box-tabela-rb{
    width:95%;
    overflow:hidden;
  }

  .box-tabela-rb table{
    width:100%;
    min-width:100%;
  }

  .box-tabela-rb td{
    padding:10px 8px;
    font-size:18px;
  }

  .box-tabela-rb td:first-child{
    width:45%;
    font-size:16px;
  }

  .box-tabela-rb td:last-child{
    width:55%;
    font-size:18px;

    text-align:right;

    word-break:break-word;
  }

  .titulo-tabela-rb{
    font-size:22px;
  }

}

/* =====================================
   TEMPORADA racingbulls 2026
===================================== */

.temporada-racingbulls{

    position:relative;

    overflow:hidden;

    padding:80px 20px;

    color:#fff;

    background:
    radial-gradient(
        circle at top,
        #6c8dff 0%,
        #120900 45%,
        #050505 100%
    );

}


/* brilho de fundo */

.temporada-racingbulls::before{

    content:"";

    position:absolute;

    top:-200px;

    right:-200px;

    width:500px;

    height:500px;


    background:
    radial-gradient(
        circle,
        rgba(108,141,255,.18),
        transparent 70%
    );


    filter:blur(50px);

}


.temporada-racingbulls > *{

    position:relative;

    z-index:2;

}



/* =====================================
   TÍTULO
===================================== */


.titulo-temp-racingbulls{

    text-align:center;

    margin-bottom:50px;

    font-size:
    clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:3px;


    color:#fff;


    text-shadow:

    0 0 20px
    rgba(108,141,255,.55);

}



/* =====================================
   DASHBOARD
===================================== */


.dashboard-racingbulls{

    max-width:1200px;

    margin:auto;

}



/* =====================================
   TOPO
===================================== */


.topo-temp-racingbulls{

    display:grid;

    grid-template-columns:

    220px 1fr 220px;

    gap:20px;

    align-items:center;

}



/* =====================================
   CARD POSIÇÃO
===================================== */


.card-campeonato-racingbulls,
.card-pontos-racingbulls,
.card-grafico-racingbulls{


    background:

    linear-gradient(
        145deg,
        #161616,
        #202020
    );


    border-radius:25px;


    border:

    1px solid
    rgba(108,141,255,.2);


    box-shadow:

    0 15px 35px
    rgba(0,0,0,.35);


}



/* posição */

.card-campeonato-racingbulls,
.card-pontos-racingbulls{


    padding:30px 20px;

    text-align:center;

}



.valor-posicao-racingbulls{

    font-size:70px;

    font-weight:900;

    color:#6c8dff;


    text-shadow:

    0 0 20px
    rgba(108,141,255,.5);

}



.card-campeonato-racingbulls p,
.card-pontos-racingbulls p{


    margin:10px 0 0;


    color:#bbb;


    font-weight:700;

    text-transform:uppercase;

    font-size:14px;

}



/* =====================================
   PONTOS
===================================== */


#pontosracingbulls{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-racingbulls{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-racingbulls svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficoracingbulls{


    stroke:#6c8dff;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(108,141,255,.8)
    );


}

/* =====================================
   DESEMPENHO racingbulls
===================================== */

.desempenho-racingbulls{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-racingbulls > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(108,141,255,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-racingbulls > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(108,141,255,.55);



    box-shadow:

    0 0 25px
    rgba(108,141,255,.25);


}



/* números */

.desempenho-racingbulls span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#6c8dff;



    text-shadow:

    0 0 15px
    rgba(108,141,255,.45);


}



/* textos */

.desempenho-racingbulls p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-racingbulls span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(108,141,255,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(108,141,255,.75);

    }


}



/* =====================================
   DESTAQUE racingbulls
===================================== */


.card-campeonato-racingbulls::before,
.card-pontos-racingbulls::before,
.card-grafico-racingbulls::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(108,141,255,.12),
        transparent 45%
    );


    pointer-events:none;


}



/* garante posição dos cards */

.card-campeonato-racingbulls,
.card-pontos-racingbulls,
.card-grafico-racingbulls{


    position:relative;


    overflow:hidden;


}

/* =====================================
   RESULTADOS racingbulls
===================================== */

.resultados-racingbulls{

    margin-top:45px;

    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );

    border-radius:25px;

    padding:25px;

    border:

    1px solid
    rgba(108,141,255,.18);

    box-shadow:

    0 15px 35px
    rgba(0,0,0,.4);

    overflow:hidden;

}



/* tabela */

.resultados-racingbulls table{

    width:100%;

    border-collapse:collapse;

}



/* cabeçalho */

.resultados-racingbulls th{


    padding:16px;


    background:

    rgba(108,141,255,.15);


    color:#6c8dff;


    text-transform:uppercase;


    font-size:14px;


    letter-spacing:1px;

}



/* células */

.resultados-racingbulls td{


    padding:14px;


    text-align:center;


    color:#ddd;


    border-bottom:

    1px solid
    rgba(255,255,255,.06);


    font-weight:600;

	 font-size:25px;

}



/* hover linha */

.resultados-racingbulls tbody tr{


    transition:.3s ease;


}



.resultados-racingbulls tbody tr:hover{


    background:

    rgba(108,141,255,.08);


    transform:

    scale(1.01);

}



/* primeira coluna */

.resultados-racingbulls td:first-child{


    color:#6c8dff;


    font-weight:900;

}



/* =====================================
   TOTAL PONTOS
===================================== */


.total-racingbulls{


    margin-top:25px;


    padding:18px;


    border-radius:18px;


    text-align:center;


    background:

    linear-gradient(
        145deg,
        #6c8dff,
        #6c8dff
    );


    color:#fff;


    font-size:22px;


    font-weight:900;


    box-shadow:

    0 0 25px
    rgba(108,141,255,.35);

}



#totalTabelaracingbulls{


    font-size:32px;


    margin-left:8px;

}



/* =====================================
   RESPONSIVO TABLET
===================================== */


@media(max-width:900px){


    .topo-temp-racingbulls{


        grid-template-columns:

        1fr;


    }


    .card-grafico-racingbulls{


        height:260px;

    }


    .desempenho-racingbulls{


        grid-template-columns:

        repeat(2,1fr);

    }


}



