    }



    .resultados-racingbulls table{


        min-width:500px;

    }



    .resultados-racingbulls th,
    .resultados-racingbulls td{


        padding:10px;


        font-size:12px;

    }



    .total-racingbulls{


        font-size:18px;

    }


    #totalTabelaracingbulls{


        font-size:25px;

    }

