/* =====================================
   CELULARES PEQUENOS
===================================== */


@media(max-width:400px){


    .desempenho-racingbulls{


        grid-template-columns:

        1fr;

    }


    .titulo-temp-racingbulls{


        font-size:1.7rem;

    }


}


/*==================================================
        rb TEAMMATE BATTLE
        CSS DEFINITIVO
==================================================*/


/*==================================================
        RESET DA SEÇÃO
==================================================*/

.rb-battle{

    width:100%;
    height:100vh;

    display:flex;
    align-items:center;
    justify-content:center;

    padding:15px;

    box-sizing:border-box;

    background:
    linear-gradient(
        180deg,
        #000000 0%,
        #1a1817 50%,
        #000000 100%
    );

    overflow:hidden;

}


/*==================================================
        CARD
==================================================*/

.rb-battle-card{

    width:100%;
    height:100%;

    max-width:2000px;

    position:relative;

    padding:20px 30px;

    box-sizing:border-box;

    border-radius:30px;

    overflow:hidden;

    background:
    linear-gradient(
        180deg,
        #191919,
        #090909
    );

    border:3px solid #F9F9F9;

    box-shadow:
    0 0 50px rgb(0,97,184);

}


/*==================================================
        HEADER
==================================================*/

.rb-header{

    width:100%;
    height:90px;

    position:relative;

    display:flex;

    align-items:center;

    justify-content:center;

}


.rb-title-wrap{

    text-align:center;

}


.rb-title-wrap h2{

    margin:0;

    font-size:clamp(30px,4vw,55px);

    line-height:1;

    font-weight:1000;

    color:white;

    text-shadow:
    0 0 25px rgba(0,97,184,.5);

}


.rb-title-wrap p{

    margin:7px 0 0;

    font-size:16px;

    font-weight:800;

    letter-spacing:6px;

    color:#f0f0f0;

}


.rb-team-logo{

    position:absolute;

    right:10px;

    top:50%;

    transform:translateY(-50%);

    height:75px;

    width:auto;

    filter:
    drop-shadow(
        0 0 20px rgba(0,97,184,.6)
    );

}


/*==================================================
        LAYOUT PRINCIPAL
==================================================*/

.rb-layout{

    width:100%;

    height:calc(100% - 90px);

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        minmax(430px,560px)
        minmax(0,1fr);

    align-items:center;

    gap:20px;

}


/*==================================================
        PILOTO ESQUERDO
==================================================*/

.rb-left{

    height:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:flex-start;

    overflow:hidden;

}


.rb-left-name{

    width:100%;

    text-align:center;

    flex-shrink:0;

    z-index:5;

}


.rb-left-name span{

    display:block;

    margin-bottom:4px;

    font-size:16px;

    font-weight:800;

    letter-spacing:5px;

    color:#ffffff;

}


.rb-left-name h3{

    margin:0;

    font-size:clamp(38px,4vw,64px);

    line-height:.85;

    font-weight:1000;

    letter-spacing:-3px;

    color:#F9F9F9;

    text-shadow:
    0 0 20px rgba(0,97,184,.4);

}


/*==================================================
        IMAGEM NORRIS
==================================================*/

.rb-left-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.rb-left-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(0,97,184,.3)
    );

    transition:
    transform .4s ease;

	 transform:translateY(-70px);

}


.rb-left-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        PILOTO DIREITO
==================================================*/

.rb-right{

    height:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:flex-start;

    overflow:hidden;

}


.rb-right-name{

    width:100%;

    text-align:center;

    flex-shrink:0;

    z-index:5;

}


.rb-right-name span{

    display:block;

    margin-bottom:4px;

    font-size:16px;

    font-weight:800;

    letter-spacing:5px;

    color:#ffffff;

}


.rb-right-name h3{

    margin:0;

    font-size:clamp(38px,4vw,64px);

    line-height:.85;

    font-weight:1000;

    letter-spacing:-3px;

    color:#F9F9F9;

    text-shadow:
    0 0 20px rgba(0,97,184,.4);

}


/*==================================================
        IMAGEM PIASTRI
==================================================*/

.rb-right-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.rb-right-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(0,97,184,.3)
    );

    transition:
    transform .4s ease;

	  transform:translateY(-70px);

}


.rb-right-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        CENTRO
==================================================*/

.rb-middle{

    width:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:center;

    position:relative;

    z-index:10;

}


/*==================================================
        VS
==================================================*/

.rb-vs{

    display:flex;

    align-items:center;

    justify-content:center;

    margin-bottom:12px;

}


.rb-vs-box{

    width:75px;

    height:75px;

    display:flex;

    align-items:center;

    justify-content:center;

    border-radius:50%;

    font-size:30px;

    font-weight:1000;

    color:#f0f0f0;

    background:#ffd700;

    border:4px solid white;

    box-shadow:
    0 0 30px rgba(0,97,184,.65);

}


/*==================================================
        TEMPORADA
==================================================*/

.rb-season{

    margin-bottom:20px;

    text-align:center;

    font-size:17px;

    font-weight:800;

    letter-spacing:4px;

    color:#f0f0f0;

}


/*==================================================
        ESTATÍSTICAS
==================================================*/

.rb-stats{

    width:100%;

    display:flex;

    flex-direction:column;

    gap:13px;

}


/*==================================================
        CADA ESTATÍSTICA
==================================================*/

.rb-stat{

    width:100%;

}


/*==================================================
        VALORES

        NORRIS | LABEL | PIASTRI
==================================================*/

.rb-stat-values{

    width:100%;

    display:grid;

    grid-template-columns:
        70px
        1fr
        70px;

    align-items:center;

}


.rb-value{

    display:flex;

    align-items:center;

    justify-content:center;

    font-size:28px;

    line-height:1;

    font-weight:1000;

    color:white;

}


.rb-label{

    text-align:center;

    font-size:14px;

    font-weight:900;

    letter-spacing:2px;

    color:#F9F9F9;

    white-space:nowrap;

}


/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.rb-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.rb-bar-left,
.rb-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.rb-bar-left{

    border-radius:999px 0 0 999px;

}


.rb-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #ffd700,
        #F9F9F9
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.rb-bar-right{

    border-radius:0 999px 999px 0;

}


.rb-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #F9F9F9,
        #ffd700
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.rb-value{

    animation:
    rbValueShow .5s ease;

}


@keyframes rbValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.rb-winner{

    color:#F9F9F9 !important;

    text-shadow:
    0 0 15px rgba(0,97,184,.8);

}


.rb-draw{

    color:#020202 !important;

}


/*==================================================
        TABLET
==================================================*/

@media(max-width:1100px){

    .rb-layout{

        grid-template-columns:
            minmax(0,1fr)
            minmax(360px,450px)
            minmax(0,1fr);

