/*==================================================
        rb DRIVER EVOLUTION
==================================================*/

.driver-evolution-rb{

    width:100%;

    min-height:100vh;

    padding:45px 0;

    box-sizing:border-box;

    background:
    linear-gradient(
        120deg,
        #f9f9f9 40%,
        #0057b8 120%
    );
	
    font-family:
    Arial,
    Helvetica,
    sans-serif;

    color:#058;

}


/*==================================================
        HEADER
==================================================*/

.evolution-header-rb{

    text-align:center;
	
    margin-bottom:28px;

}


.evolution-header-rb h2{

    margin:0;

    font-size:clamp(35px,5vw,68px);

    line-height:.95;

    font-weight:1000;

    letter-spacing:-3px;

    color:#ffd700;

}


.evolution-header-rb p{

    margin:8px 0 0;

    font-size:20px;

    font-weight:800;

    letter-spacing:3px;

    color:#0057b8;

}



/*==================================================
        CARD
==================================================*/

.evolution-card-rb{

    width:100%;

    max-width:none;

    min-height:560px;

    margin:0;

    padding:35px;

    box-sizing:border-box;

    border-radius:0;

    background:
    linear-gradient(
        120deg,
        #f9f9f9 40%,
        #0057b8 120%
    );

    box-shadow:none;

}


/*==================================================
        TOPO
==================================================*/

.evolution-card-top-rb{

    width:100%;

    display:flex;

    align-items:center;

    justify-content:space-between;

    gap:25px;

    margin-bottom:28px;

}


.evolution-intro-rb h3{

    margin:0;

    font-size:25px;

    font-weight:900;

    letter-spacing:-1px;

}


.evolution-intro-rb h3 span{

    font-weight:400;

    margin:0 5px;

}


.evolution-intro-rb p{

    margin:6px 0 0;

    color:#92929a;

    font-size:14px;

}



/*==================================================
        SELETOR
==================================================*/

.evolution-selector-rb{

    display:flex;

    align-items:center;

    padding:4px;

    border-radius:8px;

    background:#29292f;

    border:1px solid #3c3c43;

}


.evolution-mode-rb{

    border:0;

    background:transparent;

    color:#aaaab0;

    padding:11px 18px;

    border-radius:6px;

    font-size:13px;

    font-weight:800;

    cursor:pointer;

    transition:.25s ease;

}


.evolution-mode-rb:hover{

    color:white;

}


.evolution-mode-rb.active{

    background:#f0f0f0;

    color:#111;

}



/*==================================================
        CONTENT
==================================================*/

.evolution-content-rb{

    width:100%;

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        240px;

    gap:40px;

}



/*==================================================
        GRÁFICO
==================================================*/

.evolution-chart-area-rb{

    min-width:0;

    position:relative;

}


.y-axis-title-rb{

    position:absolute;

    left:-65px;

    top:50%;

    transform:
    translateY(-50%)
    rotate(-90deg);

    color:#777780;

    font-size:22px;

    letter-spacing:1px;

    font-weight:700;

}


.evolution-chart-rb{

    width:100%;

    height:400px;

    display:grid;

    grid-template-columns:45px 1fr;

}


.chart-y-labels-rb{

    height:100%;

    display:flex;

    flex-direction:column;

    justify-content:space-between;

    align-items:flex-end;

    padding:0 10px 0 0;

    box-sizing:border-box;

}


.chart-y-labels-rb span{

    color:#73737b;

    font-size:20px;

}



/*==================================================
        ÁREA DAS LINHAS
==================================================*/

.chart-main-rb{

    position:relative;

    width:100%;

    height:100%;

    border-left:1px solid #38383f;

    border-bottom:1px solid #38383f;

    background:
    repeating-linear-gradient(
        to bottom,
        transparent 0,
        transparent calc(10% - 1px),
        #292930 calc(10% - 1px),
        #292930 10%
    );

}



/*==================================================
        GRID VERTICAL
==================================================*/

.chart-grid-rb{

    position:absolute;

    inset:0;

    display:flex;

}


.chart-grid-line-rb{

    flex:1;

    border-right:1px solid rgba(255,255,255,.06);

}



/*==================================================
        SVG
==================================================*/

.evolution-svg-rb{

    position:absolute;

    inset:0;

    width:100%;

    height:100%;

    overflow:visible;

}


.lawson-path-rb{

    fill:none;

    stroke:#0057b8;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}


.lindblad-path-rb{

    fill:none;

    stroke:#ffd700;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}



/*==================================================
        ÁREA ABAIXO DA LINHA
==================================================*/

.lawson-area-rb{

    fill:url(#lawsonGradient);

    opacity:.12;

}


.lindblad-area-rb{

    fill:url(#lindbladGradient);

    opacity:.08;

}



/*==================================================
        PONTOS
==================================================*/

.chart-point-rb{

    fill:#121217;

    stroke:#0057b8;

    stroke-width:3;

}


.chart-point-rb.lindblad-rb{

    stroke:#ffd700;

}



/*==================================================
        VALORES
==================================================*/

.chart-value-rb{

    fill:#0057b8;

    font-size:18px;

    font-weight:700;

    text-anchor:middle;

}


.chart-year-rb{

    fill:#777780;

    font-size:20px;

    text-anchor:middle;

}



/*==================================================
        SIDEBAR
==================================================*/

.evolution-sidebar-rb{

    padding-top:5px;

}


.sidebar-title-rb{

    color:#85858d;

    font-size:13px;

    letter-spacing:1px;

    font-weight:700;

    margin-bottom:16px;

}



/*==================================================
        IDENTIDADE
==================================================*/

.driver-identity-rb{

	  background:#15151a;

    display:flex;

    align-items:center;

    gap:12px;

    margin-bottom:20px;

}


.identity-line-rb{

    width:42px;

    height:3px;

    position:relative;

}


.identity-line-rb span{

    position:absolute;

    width:9px;

    height:9px;

    border-radius:50%;

    top:50%;

    left:50%;

    transform:translate(-50%,-50%);

    background:#ffffff;

    border:2px solid currentColor;

}


.lawson-line-rb{

    background:#0057b8;

    color:#0057b8;

}


.lindblad-line-rb{

    background:#ffd700;

    color:#ffd700;

}


.driver-identity-rb small{

    display:block;

    color:#9999a0;

    font-size:11px;

}


.driver-identity-rb strong{

    display:block;

    color:#eee;

    font-size:14px;

}

/*==================================================
