    height:80px;

    object-fit:contain;

    object-position:center bottom;

    align-self:flex-end;

    margin-left:auto;

}

/*==================================================
        LEGEND
==================================================*/

.legend-title-rb{

    margin-top:40px;

}


.driver-legend-rb{

    height:68px;

    margin-bottom:12px;

    padding:8px 10px 8px 15px;

    box-sizing:border-box;

    display:flex;

    align-items:center;

    justify-content:space-between;

    border:1px solid #f9f9f9;

    border-radius:8px;

    background:#17171c;

