/* =========================================================
   rb — LIDERANÇA / COMMAND CENTER
========================================================= */

.rb-lideranca {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 650px;

    box-sizing: border-box;

    overflow: hidden;

    padding: 35px 5vw 25px;

    color: #fff;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(249,249,249,.16),
            transparent 30%
        ),
        radial-gradient(
            circle at 90% 80%,
            rgba(249,249,249,.10),
            transparent 30%
        ),
        #050505;

    isolation: isolate;
}


/* =========================================================
   GRID TÉCNICO DO FUNDO
========================================================= */

.rb-lideranca::before {
    content: "";

    position: absolute;

    inset: 0;

    z-index: -2;

    opacity: .35;

    background-image:
        linear-gradient(
            rgba(255,255,255,.025) 1px,
            transparent 1px
        ),
        linear-gradient(
            90deg,
            rgba(255,255,255,.025) 1px,
            transparent 1px
        );

    background-size: 55px 55px;

    pointer-events: none;
}


/* LINHA VERMELHA LATERAL */

.rb-lideranca::after {
    content: "";

    position: absolute;

    top: 0;
    right: 0;

    width: 3px;
    height: 100%;

    background:
        linear-gradient(
            to bottom,
            transparent,
            #F9F9F9 25%,
            #F9F9F9 75%,
            transparent
        );

    box-shadow:
        0 0 20px rgba(249,249,249,.35);

    pointer-events: none;
}


/* =========================================================
   HEADER
========================================================= */

.rb-lideranca-header {
    position: relative;

    width: 100%;
    max-width: 1500px;

    margin: 0 auto;
}


/* KICKER */

.rb-lideranca-kicker {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 8px;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 5px;

    color: rgba(255,255,255,.45);
}


