/* =========================================================
   LINHA DO HEADER
========================================================= */

.rb-lideranca-linha {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: 1px;

    margin:
        17px auto 15px;

    background:
        linear-gradient(
            90deg,
            #F9F9F9,
            rgba(255,255,255,.12),
            transparent
        );
}


.rb-lideranca-linha span {
    position: absolute;

    left: 0;
    top: -2px;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: #F9F9F9;

    box-shadow:
        0 0 12px rgba(249,249,249,.8);
}


/* =========================================================
   GRID DOS LÍDERES
========================================================= */

.rb-lideranca-estrutura {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: calc(100% - 185px);

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        1.15fr 1.15fr .9fr .9fr;

    grid-template-rows:
        1fr 1fr;

    gap: 10px;
}


/* =========================================================
   CARD
========================================================= */

.rb-lideranca-card {
    position: relative;

    min-width: 0;
    min-height: 0;

    overflow: hidden;

    cursor: pointer;

    border:
        1px solid rgba(255,255,255,.12);

    background: #0b0b0b;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1),
        border-color .45s ease,
        box-shadow .45s ease;
}


/* BRILHO NO CARD */

.rb-lideranca-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: -120%;

    width: 70%;
    height: 100%;

    z-index: 5;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12),
            transparent
        );

    transform: skewX(-20deg);

    transition:
        left .7s ease;

    pointer-events: none;
}


/* LINHA INFERIOR */

.rb-lideranca-card::after {
    content: "";

    position: absolute;

    left: 0;
    bottom: 0;

    width: 0;
    height: 3px;

    z-index: 15;

    background:
        linear-gradient(
            90deg,
            #F9F9F9,
            #4e68ff,
            transparent
        );

    transition:
        width .5s ease;
}


/* HOVER */

.rb-lideranca-card:hover {
    transform:
        translateY(-7px)
        scale(1.015);

    border-color:
        rgba(249,249,249,.7);

    box-shadow:
        0 20px 50px rgba(0,0,0,.65),
        0 0 35px rgba(249,249,249,.12);
}


.rb-lideranca-card:hover::before {
    left: 140%;
}


.rb-lideranca-card:hover::after {
    width: 100%;
}


/* =========================================================
   TOPO DOS CARDS
========================================================= */

.rb-lideranca-card-topo {
    position: absolute;

    top: 12px;
    left: 13px;
    right: 13px;

    z-index: 12;

    display: flex;

    justify-content: space-between;

    align-items: center;
}


.rb-lideranca-card-numero {
    font-size: 8px;

    font-weight: 900;

    letter-spacing: 2px;

    color: rgba(255,255,255,.55);
}


.rb-lideranca-card-cargo {
    padding: 5px 7px;

    background:
        rgba(0,0,0,.65);

    border:
        1px solid rgba(255,255,255,.14);

    backdrop-filter: blur(8px);

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 1.5px;

    color: rgba(255,255,255,.65);

    transition:
        background .4s ease,
        border-color .4s ease,
        color .4s ease;
}


.rb-lideranca-card:hover
.rb-lideranca-card-cargo {
    background:
        rgba(249,249,249,.25);

    border-color:
        rgba(249,249,249,.6);

    color: #fff;
}


/* =========================================================
   FOTO
========================================================= */

.rb-lideranca-foto {
    position: absolute;

    inset: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.rb-lideranca-foto img {
    width: 100%;
    height: 100%;

    object-fit: cover;

    display: block;

    opacity: .72;

    filter:
        grayscale(.35)
        contrast(1.12)
        brightness(.72);

    transform: scale(1.02);

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


.rb-lideranca-card:hover
.rb-lideranca-foto img {
    transform: scale(1.09);

    opacity: .9;

    filter:
        grayscale(0)
        contrast(1.08)
        brightness(.88);
}


/* =========================================================
   OVERLAY DA FOTO
========================================================= */

.rb-lideranca-foto-overlay {
    position: absolute;

    inset: 0;

    z-index: 2;

    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.1) 0%,
            transparent 30%,
            rgba(0,0,0,.35) 50%,
            rgba(0,0,0,.96) 100%
        );

    transition:
        background .5s ease;
}


.rb-lideranca-card:hover
.rb-lideranca-foto-overlay {
    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.05),
            rgba(249,249,249,.05) 45%,
            rgba(0,0,0,.94)
        );
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.rb-lideranca-info {
    position: absolute;

    left: 16px;
    right: 16px;
    bottom: 15px;

    z-index: 10;
}


.rb-lideranca-funcao {
    display: block;

    margin-bottom: 5px;

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 2px;

    color: #ffffff;

    transition:
        color .35s ease;
}


.rb-lideranca-card:hover
.rb-lideranca-funcao {
    color: #9fb3ff;
}


.rb-lideranca-info h3 {
    margin: 0;

    font-size:
        clamp(19px, 1.8vw, 29px);

    line-height: .9;

    font-weight: 200;

    letter-spacing: -1px;

    color: #fff;

    text-shadow:
        0 3px 15px rgba(0,0,0,.9);
}


.rb-lideranca-info h3 strong {
    font-weight: 900;
	color: #F9F9F9;
}


.rb-lideranca-info p {
    max-width: 340px;

    margin: 8px 0 0;

    font-size: 7px;

    line-height: 1.45;

    color: rgba(255,255,255,.62);

    transition:
        color .35s ease;
}


.rb-lideranca-card:hover
.rb-lideranca-info p {
    color: rgba(255,255,255,.82);
}


/* =========================================================
   CARDS PRINCIPAIS
========================================================= */

.rb-lideranca-card-destaque,
.rb-lideranca-card-principal {
    border-color:
        rgba(249,249,249,.3);
}


.rb-lideranca-card-destaque
.rb-lideranca-info h3,
.rb-lideranca-card-principal
.rb-lideranca-info h3 {
    font-size:
        clamp(23px, 2.2vw, 36px);
}


/* =========================================================
   CARD DE ENGENHARIA
========================================================= */

.rb-lideranca-foto-logo {
    background:
        radial-gradient(
            circle,
            rgba(249,249,249,.14),
            transparent 65%
        );
}


.rb-lideranca-foto-logo img {
    width: 100%;
    height: auto;

    object-fit: contain;

    opacity: .65;

    filter:
        drop-shadow(
            0 0 25px rgba(249,249,249,.4)
        );

    transition:
        transform .6s ease,
        opacity .5s ease,
        filter .5s ease;
}


.rb-lideranca-card:hover
.rb-lideranca-foto-logo img {
    transform:
        scale(1.12);

    opacity: 1;

    filter:
        drop-shadow(
            0 0 35px rgba(249,249,249,.7)
        );
}


/* =========================================================
   FOOTER
========================================================= */

.rb-lideranca-footer {
    position: absolute;

    left: 5vw;
    right: 5vw;
    bottom: 10px;

    z-index: 20;

    display: flex;

    align-items: center;

    gap: 15px;

    font-size: 5px;

    font-weight: 900;

    letter-spacing: 3px;

    color: rgba(255,255,255,.3);
}


.rb-lideranca-footer div {
    flex: 1;

    height: 1px;

    background:
        linear-gradient(
            90deg,
            rgba(249,249,249,.6),
            rgba(255,255,255,.1),
            transparent
        );
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width:900px) {

    .rb-lideranca {
        padding:
            30px 20px 20px;
    }

    .rb-lideranca-estrutura {
        grid-template-columns:
            repeat(3, 1fr);

        grid-template-rows:
            repeat(3, 1fr);

        height: calc(100% - 180px);
    }

    .rb-lideranca-info h3 {
        font-size: 18px;
    }

    .rb-lideranca-info p {
        font-size: 6px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width:700px) {

    .rb-lideranca {
        height: 100dvh;

        min-height: 650px;

        padding:
            22px 12px 12px;
    }


    /* HEADER */

    .rb-lideranca-kicker {
        font-size: 6px;

        letter-spacing: 3px;
    }

    .rb-lideranca-kicker span {
        width: 20px;
    }

    .rb-lideranca-titulo-area {
        gap: 10px;
    }

    .rb-lideranca-indice {
        width: 32px;
        height: 32px;

        font-size: 8px;
    }

    .rb-lideranca-subtitulo {
        font-size: 5px;

        letter-spacing: 2px;
    }

    .rb-lideranca-titulo {
        font-size: 27px;
    }

    .rb-lideranca-descricao {
        max-width: 300px;

        font-size: 6px;
    }


    /* LINHA */

    .rb-lideranca-linha {
        margin:
            12px auto 9px;
    }


    /* GRID */

    .rb-lideranca-estrutura {
        height: calc(100% - 145px);

        grid-template-columns:
            repeat(2, 1fr);

        grid-template-rows:
            repeat(4, 1fr);

        gap: 6px;
    }


    /* CARDS */

    .rb-lideranca-card-topo {
        top: 7px;
        left: 7px;
        right: 7px;
    }

    .rb-lideranca-card-numero {
        font-size: 5px;
    }

    .rb-lideranca-card-cargo {
        padding: 3px 4px;

        font-size: 3.5px;

        letter-spacing: .8px;
    }


    /* INFO */

    .rb-lideranca-info {
        left: 8px;
        right: 8px;
        bottom: 8px;
    }

    .rb-lideranca-funcao {
        margin-bottom: 3px;

        font-size: 4px;

        letter-spacing: 1px;
    }

    .rb-lideranca-info h3 {
        font-size: 14px;
    }

    .rb-lideranca-card-destaque
    .rb-lideranca-info h3,
    .rb-lideranca-card-principal
    .rb-lideranca-info h3 {
        font-size: 16px;
    }

    .rb-lideranca-info p {
        margin-top: 4px;

        font-size: 5px;

        line-height: 1.25;
    }


    /* FOOTER */

    .rb-lideranca-footer {
        left: 12px;
        right: 12px;

        bottom: 6px;

        gap: 8px;

        font-size: 3.5px;

        letter-spacing: 1.5px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width:400px) {

    .rb-lideranca {
        min-height: 600px;

        padding:
            18px 9px 9px;
    }

    .rb-lideranca-titulo {
        font-size: 23px;
    }

    .rb-lideranca-descricao {
        display: none;
    }

    .rb-lideranca-estrutura {
        height: calc(100% - 120px);

        gap: 5px;
    }

    .rb-lideranca-info h3 {
        font-size: 12px;
    }

    .rb-lideranca-card-destaque
    .rb-lideranca-info h3,
    .rb-lideranca-card-principal
    .rb-lideranca-info h3 {
        font-size: 13px;
    }

    .rb-lideranca-info p {
        display: none;
    }

}

