.hall-rb{
padding:120px 40px;
position:relative;
background:
linear-gradient(
120deg,
#050816 20%,
#0d1b42 55%,
#1f5eff 120%
);

min-height:auto;
height:auto;

overflow:hidden;
}

/* TÍTULO */
.titulo-hall-rb{
text-align:center;

font-size:52px;

color:#7ea6ff;

margin-bottom:80px;

text-shadow:
0 0 12px rgba(126,166,255,0.7);
}

/* GRID */
.hall-grid-rb{
display:flex;

justify-content:center;
align-items:flex-start;

flex-wrap:wrap;

perspective:1200px;

gap:40px;

position:relative;

z-index:3;
}

/* BACKGROUND */
.bg-hall-rb{
position:absolute;
inset:0;

z-index:0;
}

.bg-layer-rb{
position:absolute;
inset:0;

background-size:cover;
background-position:center center;
background-repeat:no-repeat;

transform:scale(1);

opacity:0;

transition:
opacity .8s ease,
transform 1s ease,
filter 1s ease;
}

.bg-layer-rb.active{
opacity:1;
}

/* ELEMENTOS ACIMA */
.hall-grid-rb,
.titulo-hall-rb,
.hall-overlay-rb{
position:relative;
z-index:2;
}

/* SHOWCASE */
.hall-rb.showcase .hall-card-rb{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

.hall-rb.showcase .bg-layer-rb.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.1)
saturate(1.15);
}

/* CARD */
.hall-card-rb{
position:relative;

width:320px;

padding:30px;

border-radius:24px;

background:
linear-gradient(
180deg,
rgba(10,15,35,0.35),
rgba(10,15,35,0.82)
);

border:
1px solid rgba(126,166,255,.22);

overflow:hidden;

transition:.45s ease;

box-shadow:
0 15px 35px rgba(0,0,0,.45);

text-align:center;

backdrop-filter:blur(2px);

transform-origin:center top;
}

/* HOVER */
.hall-card-rb:hover{
transform:
translateY(-14px)
scale(1.04);

background:
rgba(8,12,28,.96);

box-shadow:
0 25px 60px rgba(0,0,0,.7),
0 0 30px rgba(126,166,255,.25);

z-index:10;
}

.hall-grid-rb:hover .hall-card-rb{
opacity:.35;

transform:scale(.98);
}

.hall-card-rb:hover{
opacity:1 !important;

transform:
translateY(-14px)
scale(1.06);
}

/* NÚMERO */
.numero-hall-rb{
position:absolute;

top:15px;
right:20px;

font-size:70px;

font-weight:900;

color:rgba(126,166,255,.08);
}

/* FOTO */
.hall-card-rb img{
width:170px;
height:200px;

object-fit:cover;

border-radius:50%;

border:3px solid #7ea6ff;

margin-bottom:20px;

filter:
grayscale(100%)
brightness(.9);

transition:.5s ease;
}

.hall-card-rb:hover img{
filter:
grayscale(0%)
brightness(1.1);

transform:scale(1.1);
}

/* CONTEÚDO ESCONDIDO */
.hall-card-rb p,
.hall-stats-rb,
.frase-hall-rb{
opacity:0;

transform:translateY(10px);

max-height:0;

overflow:hidden;

transition:.4s ease;
}

.hall-card-rb:hover p,
.hall-card-rb:hover .hall-stats-rb,
.hall-card-rb:hover .frase-hall-rb{
opacity:1;

transform:translateY(0);

max-height:200px;
}

/* NOME */
.hall-card-rb h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}

/* PAÍS */
.pais-hall-rb{
display:block;

font-size:18px;

color:#7ea6ff;

margin-bottom:18px;
}

/* TEXTO */
.hall-card-rb p{
font-size:18px;

color:#ddd;

margin-bottom:22px;
}

/* STATS */
.hall-stats-rb{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#9bbcff;
}

/* FRASE */
.frase-hall-rb{
font-size:14px;

font-style:italic;

color:#fff;

line-height:1.6;
}

