.rb-evolution{
  position:relative;
  width:100%;
  padding:120px 25px;
  overflow:hidden;

  background:
  radial-gradient(circle at top,#0a122b 0%,#050814 60%);

  transition:background 1s ease;
}

/* ERAS */
.rb-evolution.bg-2000{
  background:
  radial-gradient(circle at top,
  #1b3d8f,
  #08152f,
  #050814);
}

.rb-evolution.bg-2010{
  background:
  radial-gradient(circle at top,
  #001e62,
  #111111,
  #050814);
}


.rb-evolution.bg-2020{
  background:
  radial-gradient(circle at top,
  #002fff,
  #0a122b,
  #050814);
}

/* BRILHO */
.rb-evolution::before{
  content:"";

  position:absolute;

  top:-200px;
  left:-200px;

  width:500px;
  height:500px;

  background:
  radial-gradient(
    circle,
    rgba(0,60,255,.25),
    transparent 70%
  );

  filter:blur(30px);

  animation:glowMoveRB 8s linear infinite;
}

.rb-evolution::after{
  content:"";

  position:absolute;

  right:-150px;
  bottom:-150px;

  width:450px;
  height:450px;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,.05),
    transparent 70%
  );

  filter:blur(50px);
}

/* TÍTULO */
.title-rb{
  text-align:center;

  font-size:clamp(2.5rem,6vw,5rem);

  margin-bottom:80px;

  font-weight:900;

  letter-spacing:3px;

  text-transform:uppercase;

  background:
  linear-gradient(
    90deg,
    #ffffff,
    #0044ff
  );

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
}

/* CARRO */
.car-container-rb{
  position:relative;

  width:100%;
  max-width:900px;

  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;
}

.car-circle-rb{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:2px solid rgba(0,60,255,.25);

  box-shadow:
    0 0 40px rgba(0,60,255,.2),
    inset 0 0 40px rgba(0,60,255,.08);

  animation:rotateCircleRB 14s linear infinite;
}

/* IMG */
.car-container-rb img{
  width:100%;
  max-width:580px;

  filter:
  drop-shadow(0 30px 35px rgba(0,0,0,.6));

  animation:floatRB 5s ease-in-out infinite;

  transition:.45s;
}

/* BOTÕES */
.controls-rb{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin:50px 0 90px;
}

.controls-rb button{
  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(
    145deg,
    #0044ff,
    #111111
  );

  color:#fff;

  font-weight:800;

  cursor:pointer;

  transition:.35s;
}

.controls-rb button:hover{
  transform:
  translateY(-6px)
  scale(1.05);

  box-shadow:
  0 10px 30px rgba(0,60,255,.35);
}

/* INFO */
.car-info-rb{
  max-width:1200px;
  margin:auto;
}

.car-info-rb h2{
  text-align:center;

  font-size:clamp(2rem,5vw,3.5rem);

  margin-bottom:50px;

  color:#fff;
}

.info-grid-rb{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));

  gap:25px;
}

.info-card-rb{
  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.06),
    rgba(255,255,255,.02)
  );

  border:1px solid rgba(0,60,255,.15);

  backdrop-filter:blur(14px);

  transition:.45s;
}

.info-card-rb:hover{
  transform:translateY(-12px);

  border-color:rgba(0,60,255,.5);

  box-shadow:
  0 15px 40px rgba(0,0,0,.45);
}

.info-card-rb span{
  display:block;

  margin-bottom:14px;

  color:#6d8fff;

  text-transform:uppercase;

  font-size:.8rem;
}

.info-card-rb h3{
  color:#fff;
}

/* ANIMAÇÕES */
@keyframes rotateCircleRB{

  from{
    transform:rotate(0deg);
  }

  to{
    transform:rotate(360deg);
  }

}

@keyframes floatRB{

  0%,100%{
    transform:translateY(0);
  }

  50%{
    transform:translateY(-15px);
  }

}

@keyframes glowMoveRB{

  0%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(80px,40px);
  }

  100%{
    transform:translate(0,0);
  }

}

/* RESPONSIVO */
@media(max-width:768px){

  .rb-evolution{
    padding:90px 18px;
  }

  .title-rb{
    font-size:2.4rem;
    margin-bottom:50px;
  }

  .car-container-rb{
    height:320px;
  }

  .car-circle-rb{
    width:260px;
    height:260px;
  }

  .car-container-rb img{
    max-width:320px;
  }

  .controls-rb{
    gap:10px;
    margin:40px 0 60px;
  }

  .controls-rb button{
    padding:10px 16px;
    font-size:.9rem;
  }

  .info-card-rb{
    padding:24px 20px;
  }

}


.eras-rb{
    position:relative;

    padding:90px 30px;

    text-align:center;

    overflow:hidden;

    background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #eef3ff 45%,
      #dfe8ff 100%
    );

    box-shadow:
    0 0 40px rgba(0,31,138,.18);

    color:#001f8a;

    margin-top:200px;
}

/* FUNDO DECORATIVO */
.eras-rb::before{
    content:"RB";

    position:absolute;

    top:50%;
    left:50%;

    transform:translate(-50%,-50%);

    font-size:18vw;
    font-weight:900;

    color:rgba(0,31,138,.04);

    letter-spacing:12px;

    pointer-events:none;
}

.eras-rb::after{
    content:"";

    position:absolute;

    top:-120px;
    right:-120px;

    width:320px;
    height:320px;

    border-radius:50%;

    background:
    radial-gradient(
      circle,
      rgba(0,60,255,.18),
      transparent 70%
    );

    filter:blur(20px);
}

/* ===== TÍTULO ===== */
.titulo-eras-rb{
    position:relative;
    z-index:2;

    color:#001f8a;

    font-size:clamp(2rem,5vw,4rem);

    margin-bottom:28px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    text-shadow:
    0 0 18px rgba(0,60,255,.15);
}

/* ===== TEXTO ===== */
#textoEra-rb{
    position:relative;
    z-index:2;

    color:#002a99;

    max-width:850px;

    margin:0 auto;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.35rem);

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-rb{
    position:relative;
    z-index:2;

    display:flex;
    justify-content:center;
    flex-wrap:wrap;

    gap:14px;

    margin-top:40px;
}

.botoes-eras-rb button{
    position:relative;

    overflow:hidden;

    background:
    linear-gradient(
      145deg,
      #003cff,
      #001f8a
    );

    color:#fff;

    border:none;

    padding:14px 24px;

    cursor:pointer;

    transition:.35s ease;

    border-radius:14px;

    font-weight:700;

    letter-spacing:.5px;

    box-shadow:
    0 8px 20px rgba(0,60,255,.22);
}

/* brilho */
.botoes-eras-rb button::before{
    content:"";

    position:absolute;

    top:-120%;
    left:-40%;

    width:30%;
    height:300%;

    background:
    linear-gradient(
      to right,
      transparent,
      rgba(255,255,255,.4),
      transparent
    );

    transform:rotate(25deg);

    transition:.7s ease;
}

.botoes-eras-rb button:hover::before{
    left:140%;
}

/* hover */
.botoes-eras-rb button:hover{
    transform:
    translateY(-5px)
    scale(1.05);

    background:
    linear-gradient(
      145deg,
      #0055ff,
      #0025a8
    );

    box-shadow:
    0 15px 30px rgba(0,60,255,.35);
}

/* ativo */
.botoes-eras-rb .ativo{
    background:
    linear-gradient(
      145deg,
      #001f8a,
      #000d44
    );

    box-shadow:
    0 0 25px rgba(0,60,255,.45);
}

/* ===== TIMELINE ===== */
#rb-timeline{
    position:relative;
    z-index:2;

    display:flex;
    justify-content:center;

    gap:28px;

    flex-wrap:wrap;

    margin-top:60px;
}

/* ===== CARD ===== */
.rb-timeline-item{
    position:relative;

    width:230px;

    text-align:center;

    color:#fff;

    background:
    linear-gradient(
      160deg,
      rgba(0,31,138,.96),
      rgba(0,12,60,.98)
    );

    padding:18px;

    border-radius:24px;

    overflow:hidden;

    border:1px solid rgba(0,90,255,.35);

    box-shadow:
    0 15px 35px rgba(0,0,0,.22);

    transition:
    transform .4s ease,
    box-shadow .4s ease,
    border-color .4s ease;
}

/* glow topo */
.rb-timeline-item::before{
    content:"";

    position:absolute;

    top:0;
    left:0;

    width:100%;
    height:4px;

    background:
    linear-gradient(
      90deg,
      transparent,
      #58a6ff,
      transparent
    );
}

/* reflexo */
.rb-timeline-item::after{
    content:"";

    position:absolute;

    top:0;
    left:-100%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
      120deg,
      transparent,
      rgba(255,255,255,.10),
      transparent
    );

    transition:.7s ease;
