.back-to-top-rb::before{
  content:"";

  position:absolute;

  inset:0;

  border-radius:inherit;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.22),
    transparent
  );

  opacity:0;

  transition:.35s ease;
}

.back-to-top-rb:hover::before{
  opacity:1;
}

/* hover */
.back-to-top-rb:hover{
  transform:
