}


/* =========================================================
   BRILHO DE FUNDO
========================================================= */

.piloto-aston::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: 15%;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(6,111,98,.15),
            transparent 68%
        );

    filter: blur(30px);

    opacity: .35;

    transition:
        transform .7s ease,
        opacity .7s ease;

    pointer-events: none;
}


/* =========================================================
   BRILHO fernando
========================================================= */

.piloto-fernando-aston::before {

    left: -220px;
}


/* =========================================================
   BRILHO lance
========================================================= */

.piloto-lance-aston::before {

    right: -220px;
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.piloto-numero-bg-aston {

    position: absolute;

    z-index: 0;

    top: 5%;

    font-size: clamp(200px, 40vw, 400px);

    font-weight: 900;

    line-height: 1;

    color: transparent;

    -webkit-text-stroke:
        1px rgba(255,255,255,.08);

    opacity: .8;

    transition:
        color .7s ease,
        -webkit-text-stroke .7s ease,
        transform .7s ease,
        opacity .7s ease;
}


/* =========================================================
   NÚMERO fernando
========================================================= */

.piloto-fernando-aston
.piloto-numero-bg-aston {

    left: -3%;
	    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   NÚMERO lance
========================================================= */

.piloto-lance-aston
.piloto-numero-bg-aston {

    right: -2%;

    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   FOTO
========================================================= */

.piloto-foto-aston {

    position: absolute;

    z-index: 2;

    left: 50%;

    bottom: 0;

    width: 70%;

    height: 90%;

    transform:
        translateX(-50%);

    display: flex;

    align-items: flex-end;

    justify-content: center;

    pointer-events: none;
}


.piloto-foto-aston img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center bottom;

    filter:
        grayscale(.35)
        brightness(.65);

    opacity: .72;

    transform:
        translateY(30px)
        scale(.95);

    transition:
        transform .8s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


/* =========================================================
   POSIÇÃO DA FOTO DO lance
========================================================= */

.piloto-lance-aston
.piloto-foto-aston {

    transform:
        translateX(-60%);
}


/* =========================================================
   DADOS DO PILOTO
========================================================= */

.piloto-dados-aston {

    position: absolute;

    z-index: 30;

    left: 7%;

    bottom: 9%;

    max-width: 80%;

    transition:
        transform .6s ease;
}

/* =========================================================
   DADOS DO lance
========================================================= */

.piloto-lance-aston
.piloto-dados-aston {

    left: auto;

    right: 7%;

    text-align: right;
}


/* =========================================================
   PAÍS
========================================================= */

.piloto-pais-aston {

    display: block;

    margin-bottom: 8px;

    color: #066F62;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 4px;
}


/* =========================================================
   HAMILTON — FUNDO DO NOME MAIS TRANSPARENTE
========================================================= */

.piloto-fernando-aston
.piloto-dados-aston h3::before {

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.70) 0%,
            rgba(0,0,0,.60) 45%,
            rgba(0,0,0,.30) 75%,
            transparent 100%
        );

    opacity: .75;

    filter: blur(7px);
}

/* =========================================================
   NOME
========================================================= */

.piloto-dados-aston h3 {

    position: relative;

    display: inline-flex;

    flex-direction: column;

    align-items: flex-start;

    margin: 0;

    padding: 6px 14px 8px 0;

    z-index: 31;

    font-size: clamp(28px, 3vw, 42px);

    line-height: .9;

    font-weight: 900;

    color: #fff;

    text-shadow:
        0 3px 10px rgba(0,0,0,1),
        0 0 18px rgba(0,0,0,1);
}

/* =========================================================
   NOME lance — ALINHAMENTO
========================================================= */

.piloto-lance-aston
.piloto-dados-aston h3 {

    align-items: flex-end;

    padding-right: 0;

    padding-left: 14px;
}


/* =========================================================
   FUNDO DE PROTEÇÃO DO NOME
========================================================= */

.piloto-dados-aston h3::before {

    content: "";

    position: absolute;

    z-index: -1;

    top: -12px;
    bottom: -12px;

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.98) 0%,
            rgba(0,0,0,.92) 45%,
            rgba(0,0,0,.72) 70%,
            rgba(0,0,0,.15) 100%
        );

    filter: blur(6px);

    opacity: .95;

    pointer-events: none;

    transition:
        opacity .4s ease,
        transform .4s ease;
}


/* =========================================================
   PROTEÇÃO DO NOME — LADO DIREITO
========================================================= */

.piloto-lance-aston
.piloto-dados-aston h3::before {

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            270deg,
            rgba(0,0,0,.90) 0%,
            rgba(0,0,0,.90) 45%,
            rgba(0,0,0,.70) 70%,
            rgba(0,0,0,.10) 100%
        );
}


/* =========================================================
   PRIMEIRO NOME
========================================================= */

.piloto-dados-aston h3 {

    color: #fff;
}


/* =========================================================
   SOBRENOME
========================================================= */

.piloto-dados-aston h3 strong {

    position: relative;

    display: block;

    color: #fff;

    font-weight: 900;

    transition:
        color .35s ease,
        text-shadow .35s ease;
}


/* =========================================================
   LINHA
========================================================= */

.piloto-linha-aston {

    width: 65px;

    height: 2px;

    margin: 15px 0;

    background: #066F62;

    box-shadow:
        0 0 12px rgba(6,111,98,.7);

    transition:
        width .6s ease;
}


.piloto-lance-aston
.piloto-linha-aston {

    margin-left: auto;
}


/* =========================================================
   CATEGORIA
========================================================= */

.piloto-categoria-aston {

    color: rgba(255,255,255,.98);

    font-size: 12px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* =========================================================
   AÇÃO
========================================================= */

.piloto-acao-aston {

    position: absolute;

    z-index: 14;

    right: 7%;

    bottom: 10%;

    display: flex;

    align-items: center;

    gap: 12px;

    color: rgba(255,255,255,.4);

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    transition:
        color .4s ease,
        transform .5s ease;
}


/* =========================================================
   AÇÃO lance
========================================================= */

.piloto-lance-aston
.piloto-acao-aston {

    right: auto;

    left: 4%;
}


/* =========================================================
   ÍCONE
========================================================= */

.piloto-acao-aston strong {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 28px;

    height: 28px;

    border: 1px solid rgba(6,111,98,.3);

    color: #066F62;

    font-size: 12px;

    transition:
        background .4s ease,
        color .4s ease,
        transform .4s ease;
}



/* =========================================================
   CENTRO aston
========================================================= */

.centro-aston {

    position: absolute;

    z-index: 25;

    left: 50%;
    top: 5%;

    bottom: 5%;

    width: 90px;

    transform: translateX(-50%);

    display: flex;

    flex-direction: column;

    align-items: center;

    pointer-events: none;
}


/* =========================================================
   LOGO CENTRAL
========================================================= */

.centro-logo-aston {

    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle,
            rgba(5,5,5,.95) 45%,
            rgba(5,5,5,.75) 70%,
            transparent 100%
        );

    flex-shrink: 0;
}


.centro-logo-aston img {

    width: 55px;
    height: 55px;

    object-fit: contain;

    opacity: .75;

    filter:
        drop-shadow(
            0 0 8px rgba(6,111,98,.25)
        );

    transition:
        transform .5s ease,
        opacity .5s ease,
        filter .5s ease;
}


/* =========================================================
   LINHA VERTICAL
========================================================= */

.centro-linha-aston {

    width: 1px;

    flex: 1;

    min-height: 80px;

    background:
        linear-gradient(
            to bottom,
            rgba(6,111,98,.8),
            rgba(6,111,98,.15),
            transparent
        );

    box-shadow:
        0 0 8px rgba(6,111,98,.25);
}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.centro-nome-aston {

    writing-mode: vertical-rl;

    text-orientation: mixed;

    margin-top: 12px;

    color: rgba(255,255,255,.3);

    font-size: 20px;

    font-weight: 800;

    letter-spacing: 4px;

    text-transform: uppercase;

    white-space: nowrap;

    transition:
        color .4s ease,
        text-shadow .4s ease;
}


/* =========================================================
   HOVER NOS PILOTOS
========================================================= */

.dupla-pilotos-aston:has(
    .piloto-aston:hover
)
.centro-logo-aston img {

    opacity: 1;

    transform: scale(1.1);

    filter:
        drop-shadow(
            0 0 8px #066F62
        )
        drop-shadow(
            0 0 20px rgba(6,111,98,.55)
        );
}


.dupla-pilotos-aston:has(
    .piloto-aston:hover
)
.centro-nome-aston {

    color: #066F62;

    text-shadow:
        0 0 10px rgba(6,111,98,.6);
}


/* =========================================================
   HOVER — PILOTO
========================================================= */

.piloto-aston:hover {

    z-index: 20;
}


/* =========================================================
   HOVER — BRILHO
========================================================= */

.piloto-aston:hover::before {

    opacity: .9;

    transform: scale(1.3);
}


/* =========================================================
   HOVER — NÚMERO
========================================================= */

.piloto-aston:hover
.piloto-numero-bg-aston {

    color: rgba(6,111,98,.14);

    -webkit-text-stroke:
        1px rgba(6,111,98,.28);

    transform: scale(1.05);

    opacity: 1;
}


/* =========================================================
   HOVER — FOTO
========================================================= */

.piloto-aston:hover
.piloto-foto-aston img {

    filter:
        grayscale(0)
        brightness(1);

    opacity: 1;

    transform:
        translateY(0)
        scale(1.02);
}


/* =========================================================
   HOVER — DADOS
========================================================= */

.piloto-aston:hover
.piloto-dados-aston {

    transform:
        translateY(-8px);
}


/* =========================================================
   HOVER — NOME
========================================================= */

.piloto-aston:hover
.piloto-dados-aston h3 strong {

    color: #066F62;

    text-shadow:
        0 0 8px rgba(6,111,98,.8),
        0 0 20px rgba(6,111,98,.45),
        0 3px 10px rgba(0,0,0,.9);
}


/* =========================================================
   HOVER — FUNDO DO NOME
========================================================= */

.piloto-aston:hover
.piloto-dados-aston h3::before {

    opacity: 1;

    transform: scaleX(1.05);
}


/* =========================================================
   HOVER — LINHA
========================================================= */

.piloto-aston:hover
.piloto-linha-aston {

    width: 120px;
}


/* =========================================================
   HOVER — AÇÃO
========================================================= */

.piloto-aston:hover
.piloto-acao-aston {

    color: white;

    transform:
        translateY(-5px);
}


.piloto-aston:hover
.piloto-acao-aston strong {

    background: #066F62;

    color: #080808;

    transform:
        rotate(45deg);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 700px) {

    .pilotos-aston {

        padding:
            25px 12px;
    }


    .pilotos-titulo-aston {

        margin-bottom: 10px;
    }


    .pilotos-titulo-aston h2 {

        font-size: 30px;
    }


    .pilotos-titulo-aston p {

        font-size: 10px;
    }


    .dupla-pilotos-aston {

        height: calc(100% - 100px);

        grid-template-columns:
            1fr 1fr;
    }


    .dupla-pilotos-aston::before {

        top: 8%;

        bottom: 8%;
    }


    /* FOTO */

    .piloto-foto-aston {

        width: 110%;

        height: 72%;
    }


    /* NÚMERO */

    .piloto-numero-bg-aston {

        font-size: 150px;

        top: 15%;
    }


    .piloto-lance-aston
    .piloto-numero-bg-aston {

        font-size: 135px;

        right: -5%;
    }


    /* DADOS */

    .piloto-dados-aston {

        left: 6%;

        bottom: 13%;

        max-width: 88%;
    }


    .piloto-lance-aston
    .piloto-dados-aston {

        right: 6%;

        left: auto;
    }


    /* PAÍS */

    .piloto-pais-aston {

        font-size: 6px;

        letter-spacing: 2px;
    }


    /* NOME */

    .piloto-dados-aston h3 {

        font-size: 25px;

        line-height: .9;
    }


    /* LINHA */

    .piloto-linha-aston {

        margin-top: 9px;

        margin-bottom: 8px;

        width: 40px;
    }


    /* CATEGORIA */

    .piloto-categoria-aston {

        font-size: 5px;

        letter-spacing: 1px;
    }


    /* AÇÃO */

    .piloto-acao-aston {

        bottom: 5%;

        right: 6%;

        font-size: 6px;
    }


    .piloto-lance-aston
    .piloto-acao-aston {

        left: 6%;

        right: auto;
    }


    .piloto-acao-aston strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-aston {

        padding:
            20px 8px;
    }


    .pilotos-titulo-aston h2 {

        font-size: 25px;
    }


    .pilotos-titulo-aston p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-aston {

        font-size: 115px;
    }


    .piloto-lance-aston
    .piloto-numero-bg-aston {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-aston {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-aston {

        bottom: 12%;
    }


    .piloto-dados-aston h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-aston {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-aston span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-aston,
    .piloto-aston::before,
    .piloto-numero-bg-aston,
    .piloto-foto-aston img,
    .piloto-dados-aston,
    .piloto-dados-aston h3::before,
    .piloto-dados-aston h3 strong,
    .piloto-linha-aston,
    .piloto-acao-aston,
    .piloto-acao-aston strong {

        animation: none !important;

        transition: none !important;
    }

}





.intro-aston{
  padding:80px 40px;

  background:
  linear-gradient(
    135deg,
    #02110f 0%,
    #00352f 18%,
    #006f62 42%,
    #00897b 65%,
    #00d2be 88%,
    #d7fff8 100%
  );

  position:relative;
  overflow:hidden;
}

/* brilho suave */
.intro-aston::before{
  content:"";
  position:absolute;

  top:-120px;
  left:-120px;

  width:420px;
  height:420px;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.85),
  transparent 70%);

  filter:blur(45px);
}

.intro-aston::after{
  content:"";
  position:absolute;

  right:-180px;
  bottom:-180px;

  width:500px;
  height:500px;

  background:
  radial-gradient(circle,
  rgba(0,210,190,.25),
  transparent 70%);

  filter:blur(70px);
}

.intro-container-aston{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:50px;

  max-width:1200px;
  margin:auto;

  position:relative;
  z-index:2;
}

/* TEXTO */
.intro-texto-aston{
  flex:1;
}

.intro-texto-aston h2{
  font-size:48px;

  color:#ffffff;

  margin-bottom:22px;

  text-shadow:
  0 0 18px rgba(0,210,190,.45);
}

.intro-texto-aston p{
  color:#e3fffb;

  font-size:18px;
  line-height:1.7;

  margin-bottom:18px;
}

/* DADOS */
.intro-dados-aston{
  margin-top:24px;

  display:flex;
  gap:18px;
  flex-wrap:wrap;
}

.intro-dados-aston span{
  background:
  rgba(255,255,255,.12);

  border:1px solid rgba(0,210,190,.35);

  padding:10px 16px;

  border-radius:14px;

  color:#ffffff;
  font-weight:700;

  backdrop-filter:blur(12px);

  transition:.35s ease;
}

.intro-dados-aston span:hover{
  background:rgba(255,255,255,.22);

  transform:
  translateY(-4px)
  scale(1.04);

  box-shadow:
  0 0 24px rgba(0,210,190,.45);
}

/* IMAGEM */
.intro-img-aston{
  flex:1;
  position:relative;
}

.intro-img-aston img{
  width:100%;

  border-radius:24px;

  box-shadow:
  0 0 45px rgba(0,210,190,.28);

  transition:.45s ease;
}

.intro-img-aston img:hover{
  transform:
  scale(1.03)
  rotate(-1deg);

  box-shadow:
  0 0 70px rgba(255,255,255,.5),
  0 0 40px rgba(0,210,190,.45);
