/* RESPONSIVO */
@media(max-width:768px){

  .intro-aston{
    padding:60px 20px;
  }

  .intro-container-aston{
    flex-direction:column;
    text-align:center;
  }

  .intro-texto-aston h2{
    font-size:30px;
  }

  .intro-texto-aston p{
    font-size:15px;
  }

  .intro-dados-aston{
    justify-content:center;
  }

}


