/* =========================================================
   aston — linha-evolution
========================================================= */

.aston-linha-evolution {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 600px;

    overflow: hidden;

    box-sizing: border-box;

    padding: 38px 4vw 25px;

    background: #050708;

    color: #fff;
}


/* =========================================================
   HEADER
========================================================= */

.linha-evolution-header-aston {
    position: relative;

    z-index: 10;

    text-align: center;

    margin-bottom: 28px;
}


.linha-evolution-header-aston > span {
    font-size: 13px;

    font-weight: 800;

    letter-spacing: 4px;

    color: rgba(220,255,255,.42);
}


.linha-evolution-header-aston h2 {
    margin: 6px 0 3px;

    font-size: clamp(28px, 4vw, 48px);

    line-height: 1;

    font-weight: 300;

    letter-spacing: -2px;
}


.linha-evolution-header-aston h2 strong {
    font-weight: 900;

    color: #066F62;

    text-shadow:
        0 0 25px rgba(190,255,255,.2);
}


.linha-evolution-header-aston p {
    margin: 0;

    font-size: 15px;

    color: rgba(255,255,255,.35);

    letter-spacing: 1px;
}


/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-aston {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: grid;

    grid-template-columns:
        repeat(6, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}


/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-aston {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-aston:hover
.linha-evolution-team-aston {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-aston
.linha-evolution-team-aston:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-aston {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-aston:hover
.team-bg-number-aston {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-aston {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-aston::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-aston img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-aston:hover
.team-image-aston {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-aston:hover
.team-image-aston::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-aston:hover
.team-image-aston img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-aston {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-aston:hover
.team-content-aston {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-aston {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-aston h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-aston {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-aston:hover
.team-line-aston {

    width: 65px;
}


/* Função */

.team-role-aston {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-aston {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-aston:hover
.team-arrow-aston {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


