.tabela-aston{
    padding:clamp(80px, 12vw, 140px) 20px;

    background:linear-gradient(
      120deg,
      #00352f 0%,
      #00574d 20%,
      #006f62 45%,
      #00a19b 75%,
      #b8fff5 100%
    );

    color:#fff;
}

/* ===== TÍTULO ===== */
.titulo-tabela-aston{
    text-align:center;

    font-size:clamp(28px, 4vw, 46px);

    margin-bottom:60px;

    display:flex;
    justify-content:center;
    align-items:center;
    gap:12px;
}

/* LOGO */
.logo-titulo-asston{
    width:clamp(28px, 4vw, 46px);

    filter:drop-shadow(
      0 0 12px rgba(0,210,190,.8)
    );

    transition:.3s ease;
}

.titulo-tabela-aston:hover .logo-titulo-asston{
    transform:scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-aston{
    width:90%;
    max-width:1500px;

    margin:auto;

    background:rgba(0,0,0,0.72);

    border-radius:20px;

    backdrop-filter:blur(8px);

    box-shadow:
      0 0 40px rgba(0,210,190,0.22),
      inset 0 0 30px rgba(255,255,255,0.05);
}

/* ===== TABELA ===== */
.box-tabela-aston table{
    width:100%;

    border-collapse:collapse;

    min-width:600px;
}

/* ===== LINHAS ===== */
.box-tabela-aston tr{
    transition:.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-aston td{
    padding:clamp(18px, 2.5vw, 28px);

    font-size:clamp(15px, 2vw, 20px);

    border-bottom:
      1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-aston td:first-child{
    color:#7effe8;

    font-weight:bold;

    width:50%;
}

/* SEGUNDA COLUNA */
.box-tabela-aston td:last-child{
    text-align:right;

    color:#f1f1f1;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-aston tr:hover{
    background:linear-gradient(
      90deg,
      rgba(0,210,190,0.18),
      rgba(255,255,255,0.08)
    );

    transform:scale(1.01);

    box-shadow:
      inset 0 0 18px rgba(0,210,190,.15);
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .box-tabela-aston{
    width:95%;
    overflow:hidden;
  }

  .box-tabela-aston table{
    width:100%;
    min-width:100%;
  }

  .box-tabela-aston td{
    padding:10px 8px;
    font-size:18px;
  }

  .box-tabela-aston td:first-child{
    width:45%;
    font-size:16px;
  }

  .box-tabela-aston td:last-child{
    width:55%;
    font-size:18px;

    text-align:right;

    word-break:break-word;
  }

  .titulo-tabela-aston{
    font-size:22px;
  }

}


