    font-size:70px;

    font-weight:900;

    color:#006f62;


    text-shadow:

    0 0 20px
    rgba(0,111,98,.5);

}



.card-campeonato-astonmartin p,
.card-pontos-astonmartin p{


    margin:10px 0 0;


    color:#bbb;


    font-weight:700;

    text-transform:uppercase;

