}



/* =====================================
   PONTOS
===================================== */


#pontosastonmartin{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-astonmartin{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-astonmartin svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficoastonmartin{


    stroke:#006f62;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(0,111,98,.8)
    );


}

/* =====================================
   DESEMPENHO astonmartin
===================================== */

.desempenho-astonmartin{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-astonmartin > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(0,111,98,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-astonmartin > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(0,111,98,.55);



    box-shadow:

    0 0 25px
    rgba(0,111,98,.25);


}



/* números */

.desempenho-astonmartin span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#006f62;



    text-shadow:

    0 0 15px
    rgba(0,111,98,.45);


}



/* textos */

.desempenho-astonmartin p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-astonmartin span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(0,111,98,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(0,111,98,.75);

    }


}



/* =====================================
   DESTAQUE astonmartin
===================================== */


.card-campeonato-astonmartin::before,
.card-pontos-astonmartin::before,
.card-grafico-astonmartin::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(0,111,98,.12),
        transparent 45%
    );


    pointer-events:none;


}



/* garante posição dos cards */

.card-campeonato-astonmartin,
.card-pontos-astonmartin,
.card-grafico-astonmartin{


    position:relative;


    overflow:hidden;


}

/* =====================================
   RESULTADOS astonmartin
===================================== */

.resultados-astonmartin{

    margin-top:45px;

    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );

    border-radius:25px;

    padding:25px;

    border:

    1px solid
    rgba(0,111,98,.18);

    box-shadow:

    0 15px 35px
    rgba(0,0,0,.4);

    overflow:hidden;

}



/* tabela */

.resultados-astonmartin table{

    width:100%;

    border-collapse:collapse;

}



/* cabeçalho */

.resultados-astonmartin th{


    padding:16px;


    background:

    rgba(0,111,98,.15);


    color:#006f62;


    text-transform:uppercase;


    font-size:14px;


    letter-spacing:1px;

}



/* células */

.resultados-astonmartin td{


    padding:14px;


    text-align:center;


    color:#ddd;


    border-bottom:

    1px solid
    rgba(255,255,255,.06);


    font-weight:600;

	 font-size:25px;

}



/* hover linha */

.resultados-astonmartin tbody tr{


    transition:.3s ease;


}



.resultados-astonmartin tbody tr:hover{


    background:

    rgba(0,111,98,.08);


    transform:

    scale(1.01);

}



/* primeira coluna */

.resultados-astonmartin td:first-child{


    color:#006f62;


    font-weight:900;

}



/* =====================================
   TOTAL PONTOS
===================================== */


.total-astonmartin{


    margin-top:25px;


    padding:18px;


    border-radius:18px;


    text-align:center;


    background:

    linear-gradient(
        145deg,
        #006f62,
        #006f62
    );


    color:#fff;


    font-size:22px;


    font-weight:900;


    box-shadow:

    0 0 25px
    rgba(0,111,98,.35);

}



#totalTabelaastonmartin{


    font-size:32px;


    margin-left:8px;

}



/* =====================================
   RESPONSIVO TABLET
===================================== */


@media(max-width:900px){


    .topo-temp-astonmartin{


        grid-template-columns:

        1fr;


    }


