==================================================*/


/*==================================================
        RESET DA SEÇÃO
==================================================*/

.aston-battle{

    width:100%;
    height:100vh;

    display:flex;
    align-items:center;
    justify-content:center;

    padding:15px;

    box-sizing:border-box;

    background:
    linear-gradient(
        180deg,
        #000000 0%,
        #1a1817 50%,
        #000000 100%
    );

    overflow:hidden;

}


/*==================================================
        CARD
==================================================*/

.aston-battle-card{

    width:100%;
    height:100%;

    max-width:2000px;

    position:relative;

    padding:20px 30px;

    box-sizing:border-box;

    border-radius:30px;

    overflow:hidden;

    background:
    linear-gradient(
        180deg,
        #191919,
        #090909
    );

    border:3px solid #066f62;

    box-shadow:
    0 0 50px rgb(206,220,0);

}


/*==================================================
        HEADER
==================================================*/

.aston-header{

    width:100%;
    height:90px;

    position:relative;

    display:flex;

    align-items:center;

    justify-content:center;

}


.aston-title-wrap{

    text-align:center;

}


.aston-title-wrap h2{

    margin:0;

    font-size:clamp(30px,4vw,55px);

    line-height:1;

    font-weight:1000;

    color:white;

    text-shadow:
    0 0 25px rgba(206,220,0,.5);

}


.aston-title-wrap p{

    margin:7px 0 0;

    font-size:16px;

    font-weight:800;

    letter-spacing:6px;

    color:#f0f0f0;

}


.aston-team-logo{

    position:absolute;

    right:10px;

    top:50%;

    transform:translateY(-50%);

    height:75px;

    width:auto;

    filter:
    drop-shadow(
        0 0 20px rgba(206,220,0,.6)
    );

}


/*==================================================
        LAYOUT PRINCIPAL
==================================================*/

.aston-layout{

    width:100%;

    height:calc(100% - 90px);

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        minmax(430px,560px)
        minmax(0,1fr);

    align-items:center;

    gap:20px;

}


/*==================================================
        PILOTO ESQUERDO
==================================================*/

.aston-left{

    height:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:flex-start;

    overflow:hidden;

}


.aston-left-name{

    width:100%;

    text-align:center;

    flex-shrink:0;

    z-index:5;

}


.aston-left-name span{

    display:block;

    margin-bottom:4px;

    font-size:16px;

    font-weight:800;

    letter-spacing:5px;

    color:#ffffff;

}


.aston-left-name h3{

    margin:0;

    font-size:clamp(38px,4vw,64px);

    line-height:.85;

    font-weight:1000;

    letter-spacing:-3px;

    color:#066f62;

    text-shadow:
    0 0 20px rgba(206,220,0,.4);

}


/*==================================================
        IMAGEM NORRIS
==================================================*/

.aston-left-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.aston-left-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(206,220,0,.3)
    );

    transition:
    transform .4s ease;

	 transform:translateY(-70px);

}


.aston-left-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        PILOTO DIREITO
==================================================*/

.aston-right{

    height:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:flex-start;

    overflow:hidden;

}


.aston-right-name{

    width:100%;

    text-align:center;

    flex-shrink:0;

    z-index:5;

}


.aston-right-name span{

    display:block;

    margin-bottom:4px;

    font-size:16px;

    font-weight:800;

    letter-spacing:5px;

    color:#ffffff;

}


.aston-right-name h3{

    margin:0;

    font-size:clamp(38px,4vw,64px);

    line-height:.85;

    font-weight:1000;

    letter-spacing:-3px;

    color:#066f62;

    text-shadow:
    0 0 20px rgba(206,220,0,.4);

}


/*==================================================
        IMAGEM PIASTRI
==================================================*/

.aston-right-image{

    width:100%;

    flex:1;

    min-height:0;

    display:flex;

    align-items:flex-end;

    justify-content:center;

    overflow:hidden;

}


.aston-right-image img{

    display:block;

    height:100%;

    max-height:1200px;

    max-width:100%;

    width:auto;

    object-fit:contain;

    object-position:center bottom;

    filter:
    drop-shadow(
        0 0 45px rgba(206,220,0,.3)
    );

    transition:
    transform .4s ease;

	  transform:translateY(-70px);

}


.aston-right-image img:hover{

    transform:scale(1.03);

}


/*==================================================
        CENTRO
==================================================*/

.aston-middle{

    width:100%;

    min-width:0;

    display:flex;

    flex-direction:column;

    align-items:center;

    justify-content:center;

    position:relative;

    z-index:10;

}


/*==================================================
        VS
==================================================*/

.aston-vs{

    display:flex;

    align-items:center;

    justify-content:center;

    margin-bottom:12px;

}


.aston-vs-box{

    width:75px;

    height:75px;

    display:flex;

    align-items:center;

    justify-content:center;

    border-radius:50%;

    font-size:30px;

    font-weight:1000;

    color:#f0f0f0;

    background:#066f62;

    border:4px solid white;

    box-shadow:
    0 0 30px rgba(206,220,0,.65);

}


/*==================================================
        TEMPORADA
==================================================*/

.aston-season{

    margin-bottom:20px;

    text-align:center;

    font-size:17px;

    font-weight:800;

    letter-spacing:4px;

    color:#f0f0f0;

}


/*==================================================
        ESTATÍSTICAS
==================================================*/

.aston-stats{

    width:100%;

    display:flex;

    flex-direction:column;

    gap:13px;

}


/*==================================================
        CADA ESTATÍSTICA
==================================================*/

.aston-stat{

    width:100%;

}


/*==================================================
        VALORES

        NORRIS | LABEL | PIASTRI
==================================================*/

.aston-stat-values{

    width:100%;

    display:grid;

    grid-template-columns:
        70px
        1fr
        70px;

    align-items:center;

}


.aston-value{

    display:flex;

    align-items:center;

    justify-content:center;

    font-size:28px;

    line-height:1;

    font-weight:1000;

    color:white;

}


.aston-label{

    text-align:center;

    font-size:14px;

    font-weight:900;

    letter-spacing:2px;

    color:#066f62;

    white-space:nowrap;

}


/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.aston-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.aston-bar-left,
.aston-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.aston-bar-left{

    border-radius:999px 0 0 999px;

}


.aston-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #f2e500,
        #066f62
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.aston-bar-right{

    border-radius:0 999px 999px 0;

}


.aston-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #066f62,
        #f2e500
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.aston-value{

    animation:
    astonValueShow .5s ease;

}


@keyframes astonValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.aston-winner{

    color:#066f62 !important;

    text-shadow:
    0 0 15px rgba(206,220,0,.8);

}


.aston-draw{

    color:#020202 !important;

}


