/* =========================================
   SECTORS ASTON
========================================= */
.aston-sectors{
  position:relative;

  padding:100px 20px;

  overflow:hidden;

  background:
  linear-gradient(
    135deg,
    #004d43 0%,
    #006f62 30%,
    #00a19b 70%,
    #b6fff7 100%
  );

  color:#fff;
}

/* brilho fundo */
.aston-sectors::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(
    circle at top right,
    rgba(255,255,255,.18),
    transparent 45%
  );

  pointer-events:none;
}

/* =========================================
   HEADER
========================================= */
.aston-sectors-header{
  position:relative;
  z-index:2;

  max-width:1000px;

  margin:0 auto 70px;

  text-align:center;
}

.aston-sectors-header span{
  display:inline-block;

  padding:8px 18px;

  border-radius:40px;

  background:
  rgba(255,255,255,.12);

  border:
  1px solid rgba(255,255,255,.18);

  font-size:15px;
  font-weight:700;

  letter-spacing:1px;
  text-transform:uppercase;

  margin-bottom:20px;

  backdrop-filter:blur(10px);
}

.aston-sectors-header h2{
  font-size:clamp(34px,5vw,60px);

  line-height:1.1;

  margin-bottom:25px;

  color:#ffffff;

  text-shadow:
  0 0 20px rgba(255,255,255,.18);
}

.aston-sectors-header p{
  font-size:20px;

  line-height:1.7;

  color:#eaffff;

  max-width:850px;

  margin:auto;
}

/* =========================================
   GRID
========================================= */
.aston-sectors-grid{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(260px,1fr));

  gap:25px;

  max-width:1450px;

  margin:auto;
}

/* =========================================
   CARD
========================================= */
.aston-sector-card{
  position:relative;

  overflow:hidden;

  padding:30px;

  border-radius:24px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.15),
    rgba(255,255,255,.05)
  );

  border:
  1px solid rgba(255,255,255,.18);

  backdrop-filter:blur(14px);

  transition:
  transform .4s ease,
  box-shadow .4s ease,
  border-color .4s ease;
}

/* glow */
.aston-sector-card::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(
    circle at top,
    rgba(255,255,255,.18),
    transparent 70%
  );

  opacity:0;

  transition:.4s ease;
}

/* brilho passando */
.aston-sector-card::after{
  content:"";

  position:absolute;

  top:-150%;
  left:-40%;

  width:30%;
  height:320%;

  background:
  linear-gradient(
    to right,
    transparent,
    rgba(255,255,255,.35),
    transparent
  );

  transform:rotate(25deg);

  transition:.8s ease;
}

.aston-sector-card h3{
  position:relative;
  z-index:2;

  font-size:24px;

  margin-bottom:18px;

  color:#ffffff;
}

.aston-sector-card p{
  position:relative;
  z-index:2;

  font-size:17px;

  line-height:1.7;

  color:#eaffff;
}

/* hover */
.aston-sector-card:hover{
  transform:
  translateY(-10px)
  scale(1.02);

  border-color:
  rgba(255,255,255,.4);

  box-shadow:
  0 18px 35px rgba(0,0,0,.2);
}

.aston-sector-card:hover::before{
  opacity:1;
}

.aston-sector-card:hover::after{
  left:140%;
}

/* =========================================
   RESPONSIVO
========================================= */
@media(max-width:768px){

  .aston-sectors{
    padding:70px 14px;
  }

  .aston-sectors-header{
    margin-bottom:50px;
  }

  .aston-sectors-header h2{
    font-size:30px;
  }

  .aston-sectors-header p{
    font-size:16px;
  }

  .aston-sectors-grid{
    gap:18px;
  }

  .aston-sector-card{
    padding:24px;
  }

  .aston-sector-card h3{
    font-size:20px;
  }

  .aston-sector-card p{
    font-size:15px;
  }

}


