/* ==========================================
   ESTATÍSTICAS aston
========================================== */

.numeros-aston{

    position:relative;

    min-height:600px;

    padding:40px 0;

    overflow:hidden;

    background:
    linear-gradient(
        135deg,
        #f0f0f0 0%,
        #121212 45%,
        #006f62 120%
    );

}


/* IMAGEM DE FUNDO */

.bg-numeros-aston{

    position:absolute;

    inset:0;

    width:100%;
    height:100%;

    object-fit:cover;

    filter:
    brightness(.35)
    blur(4px);

    transform:scale(1.1);

    z-index:0;

}



.numeros-aston::before{

    content:"";

    position:absolute;

    inset:0;

    background:

    radial-gradient(
        circle at center,
        transparent 20%,
        rgba(0,0,0,.85)
    );

    z-index:1;

}



/* TITULO */

.titulo-numeros-aston{

    position:relative;

    z-index:2;

    text-align:center;

    color:#006f62;

    font-size:clamp(32px,5vw,55px);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:25px;

    text-shadow:

    0 0 15px #006f62;

}



/* GRID */

.stats-grid-aston{

    position:relative;

    z-index:2;


    max-width:1200px;

    margin:auto;

    padding:0 35px;


    display:grid;

    grid-template-columns:
    repeat(3,1fr);


    gap:15px;

}



/* CARDS */

.card-stat-aston{

    position:relative;


    background:

    linear-gradient(
        145deg,
        rgba(10,10,10,.08),
        rgba(0,111,98.25)
    );




    border-radius:22px;


    padding:18px;


    text-align:center;


    color:white;


    border:

    1px solid
    rgba(10,10,10,.5);



    box-shadow:

    0 15px 40px
    rgba(0,111,98,.7);



    overflow:hidden;



    opacity:0;

    transform:
    translateY(50px);



    transition:.6s ease;

}



/* LINHA LARANJA */

.card-stat-aston::before{

    content:"";

    position:absolute;

    top:0;

    left:0;

    width:100%;

    height:4px;


    background:

    linear-gradient(
        90deg,
        transparent,
        #006f62,
        transparent
    );

}



/* ATIVO */

.card-stat-aston.ativo{

    opacity:1;

    transform:
    translateY(0);


    animation:

    brilhoaston 2.5s infinite alternate;

}



@keyframes brilhoaston{

    from{

        box-shadow:

        0 0 15px
        rgba(10,10,10,.3);

    }


    to{

        box-shadow:

        0 0 35px
        rgba(10,10,10,.8);

    }

}



/* NUMEROS */

.card-stat-aston span{

    display:block;


    font-size:

    clamp(32px,4vw,55px);


    font-weight:900;


    color:#121212;


    text-shadow:

    0 0 15px #006f62;

}



/* TEXTO */

.card-stat-aston p{

    margin-top:15px;


    font-size:

    clamp(18px,2vw,28px);


    font-weight:bold;


    color:white;

}



/* CARD GRANDE */

.grande-aston{

    grid-column:

    1 / -1;

}



/* BARRA */

.barra-velocidade-aston{


    width:0%;


    height:8px;


    margin-top:20px;


    border-radius:20px;


    background:

    linear-gradient(
        90deg,
        #121212,
        #121212
    );


    box-shadow:

    0 0 15px #006f62;


    transition:

    width .3s ease;

}



/* HOVER */

.card-stat-aston:hover{


    transform:

    translateY(-10px)
    scale(1.03);



    border-color:#006f62;


}



/* ==========================================
   MOBILE
========================================== */


@media(max-width:768px){


.stats-grid-aston{


    grid-template-columns:1fr;


    padding:0 15px;


    gap:20px;

}



.grande-aston{


    grid-column:1;

}



.card-stat-aston{


    padding:25px;

}



.card-stat-aston span{


    font-size:50px;

}


}



.hall-aston{
padding:120px 40px;
position:relative;
background:
linear-gradient(
120deg,
#06140f 35%,
#0f3d2e 70%,
#00d2be 140%
);

min-height:auto;
height:auto;

overflow:hidden;
}

/* ===== TÍTULO ===== */

.titulo-hall-aston{
text-align:center;

font-size:52px;

color:#00d2be;

margin-bottom:80px;

text-shadow:
0 0 12px rgba(0,210,190,0.7);
}

/* ===== GRID ===== */

.hall-grid-aston{
display:flex;

justify-content:center;
align-items:flex-start;

flex-wrap:wrap;

perspective:1200px;

gap:40px;

position:relative;

z-index:3;
}

/* ===== FUNDO ===== */

.bg-hall-aston{
position:absolute;
inset:0;
z-index:0;
}

.bg-layer-aston{
position:absolute;
inset:0;

background-size:cover;
background-position:center center;
background-repeat:no-repeat;

transform:scale(1);

opacity:0;

transition:opacity .8s ease;
}

.bg-layer-aston.active{
opacity:1;
}

.hall-grid-aston,
.titulo-hall-aston,
.hall-overlay-aston{
position:relative;
z-index:2;
}

/* ===== SHOWCASE ===== */

.hall-aston.showcase .hall-card-aston{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

.hall-aston.showcase .bg-layer-aston.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.15)
saturate(1.2);

transition:1s ease;
}

/* ===== CARD ===== */

.hall-card-aston{
position:relative;

width:320px;

padding:30px;

border-radius:24px;

background:
linear-gradient(
180deg,
rgba(8,20,16,0.28),
rgba(8,20,16,0.72)
);

border:
1px solid rgba(0,210,190,0.25);

overflow:hidden;

transition:.45s ease;

box-shadow:
0 15px 35px rgba(0,0,0,0.45);

text-align:center;

backdrop-filter:blur(2px);

transform-origin:center top;
}

/* ===== GLOW TOPO ===== */

.hall-card-aston::before{
content:"";

position:absolute;

top:0;
left:0;

width:100%;
height:3px;

background:
linear-gradient(
90deg,
transparent,
#00d2be,
transparent
);
}

/* ===== REFLEXO ===== */

.hall-card-aston::after{
content:"";

position:absolute;

top:0;
left:-100%;

width:100%;
height:100%;

background:
linear-gradient(
120deg,
transparent,
rgba(0,210,190,.15),
transparent
);

transition:.6s;
}

.hall-card-aston:hover::after{
left:100%;
}

/* ===== HOVER ===== */

.hall-card-aston:hover{
transform:
translateY(-14px)
scale(1.04);

background:
rgba(8,20,16,0.92);

box-shadow:
0 25px 60px rgba(0,0,0,0.7),
0 0 30px rgba(0,210,190,0.25);

z-index:10;
}

.hall-grid-aston:hover .hall-card-aston{
opacity:.35;

transform:scale(.98);
}

.hall-card-aston:hover{
opacity:1 !important;

transform:
translateY(-14px)
scale(1.06);
}

/* ===== NÚMERO ===== */

.numero-hall-aston{
position:absolute;

top:15px;
right:20px;

font-size:70px;

font-weight:900;

color:rgba(0,210,190,0.08);
}

/* ===== FOTO ===== */

.hall-card-aston img{
width:170px;
height:200px;

object-fit:cover;

border-radius:50%;

border:
3px solid #00d2be;

margin-bottom:20px;

filter:
grayscale(100%)
brightness(.9);

transition:.5s ease;
}

.hall-card-aston:hover img{
filter:
grayscale(0%)
brightness(1.1);

transform:scale(1.1);
}

/* ===== CONTEÚDO ===== */

.hall-card-aston p,
.hall-stats-aston,
.frase-hall-aston{
opacity:0;

transform:translateY(10px);

max-height:0;

overflow:hidden;

transition:.4s ease;
}

.hall-card-aston:hover p,
.hall-card-aston:hover .hall-stats-aston,
.hall-card-aston:hover .frase-hall-aston{
opacity:1;

transform:translateY(0);

max-height:200px;
}

/* ===== NOME ===== */

.hall-card-aston h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}

/* ===== PAÍS ===== */

.pais-hall-aston{
display:block;

font-size:18px;

color:#7ff5ea;

margin-bottom:18px;
}

/* ===== TEXTO ===== */

.hall-card-aston p{
font-size:18px;

color:#ddd;

margin-bottom:22px;
}

/* ===== STATS ===== */

.hall-stats-aston{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#7ff5ea;
}

/* ===== FRASE ===== */

.frase-hall-aston{
font-size:14px;

font-style:italic;

color:#fff;

line-height:1.6;
