    rgba(0,210,190,.18),
    transparent 70%
  );

  filter:blur(35px);

  animation:glowAston 8s linear infinite;
}

.aston-evolution::after{
  content:"";

  position:absolute;
  right:-180px;
  bottom:-180px;

  width:420px;
  height:420px;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,.06),
    transparent 70%
  );

  filter:blur(50px);
}

/* ===== TÍTULO ===== */

.title-aston{
  position:relative;

  font-size:clamp(2.5rem,6vw,5rem);

  text-align:center;

  margin-bottom:80px;

  font-weight:900;

  letter-spacing:3px;

  text-transform:uppercase;

  background:
  linear-gradient(
    90deg,
    #ffffff,
    #00d2be
  );

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;

  z-index:5;
}

/* ===== ÁREA CARRO ===== */

.car-container-aston{
  position:relative;

  width:100%;
  max-width:900px;
  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;

  z-index:2;
}

/* ===== BASE ===== */

.car-container-aston::before{
  content:"";

  position:absolute;
  bottom:50px;

  width:70%;
  height:40px;

  background:
  radial-gradient(
    circle,
    rgba(0,210,190,.35),
    transparent 70%
  );

  filter:blur(20px);

  border-radius:50%;

  animation:pulseFloorAston 4s ease-in-out infinite;
}

/* ===== CÍRCULO ===== */

.car-circle-aston{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:
  2px solid rgba(0,210,190,.18);

  box-shadow:
    0 0 40px rgba(0,210,190,.15),
    inset 0 0 40px rgba(0,210,190,.08);

  animation:rotateCircleAston 14s linear infinite;
}

.car-circle-aston::before{
  content:"";

  position:absolute;
  inset:20px;

  border-radius:50%;

  border:
  1px dashed rgba(255,255,255,.08);
}

/* ===== CARRO ===== */

.car-container-aston img{
  position:relative;

  width:100%;
  max-width:650px;

  object-fit:contain;

  z-index:5;

  filter:
  drop-shadow(
    0 30px 35px rgba(0,0,0,.6)
  );

  animation:
    floatCarAston 5s ease-in-out infinite,
    rotateCarAston 6s ease-in-out infinite;

  transition:
    opacity .45s ease,
    transform .45s ease;
}

/* ===== BOTÕES ===== */

.controls-aston{
  position:relative;

  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin-top:40px;
  margin-bottom:90px;

  z-index:5;
}

.controls-aston button{
  position:relative;

  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(
    145deg,
    #00d2be,
    #008f80
  );

  color:#02140f;

  font-weight:800;
  font-size:.95rem;

  letter-spacing:1px;

  cursor:pointer;

  overflow:hidden;

  transition:.35s;
}

.controls-aston button::before{
  content:"";

  position:absolute;
  top:0;
  left:-120%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.6),
    transparent
  );

  transition:.6s;
}

.controls-aston button:hover::before{
  left:120%;
}

.controls-aston button:hover{
  transform:
  translateY(-6px)
  scale(1.05);

  box-shadow:
  0 10px 30px rgba(0,210,190,.35);
}

/* ===== INFOS ===== */

.car-info-aston{
  position:relative;

  width:100%;
  max-width:1200px;

  margin:auto;

  z-index:5;
}

.car-info-aston h2{
  text-align:center;

  font-size:clamp(2rem,5vw,3.5rem);

  margin-bottom:50px;

  font-weight:900;

  color:#fff;
}

/* ===== GRID ===== */

.info-grid-aston{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));

  gap:25px;
}

/* ===== CARDS ===== */

.info-card-aston{
  position:relative;

  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.06),
    rgba(255,255,255,.02)
  );

  border:
  1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  overflow:hidden;

  transition:.45s;
}

.info-card-aston::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    140deg,
    rgba(255,255,255,.08),
    transparent 40%
  );

  opacity:0;

  transition:.4s;
}

.info-card-aston:hover::before{
  opacity:1;
}

.info-card-aston:hover{
  transform:translateY(-12px);

  border-color:
  rgba(0,210,190,.35);

  box-shadow:
    0 15px 40px rgba(0,0,0,.45),
    0 0 25px rgba(0,210,190,.12);
}

.info-card-aston span{
  display:block;

  margin-bottom:14px;

  color:#00d2be;

  text-transform:uppercase;

  letter-spacing:2px;

  font-size:.8rem;

  font-weight:700;
}

.info-card-aston h3{
  color:#fff;

  font-size:1.1rem;

  line-height:1.7;

  font-weight:600;
}

/* ===== ANIMAÇÕES ===== */

@keyframes rotateCircleAston{

  from{
    transform:rotate(0deg);
  }

  to{
    transform:rotate(360deg);
  }

}

@keyframes floatCarAston{

  0%,100%{
    transform:translateY(0px);
  }

  50%{
    transform:translateY(-15px);
  }

}

@keyframes rotateCarAston{

  0%,100%{
    rotate:y 0deg;
  }

  50%{
    rotate:y 10deg;
  }

}

@keyframes pulseFloorAston{

  0%,100%{
    transform:scale(.95);
    opacity:.5;
  }

  50%{
    transform:scale(1.05);
    opacity:1;
  }

}

@keyframes glowAston{

  0%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(80px,40px);
  }

  100%{
    transform:translate(0,0);
  }

}

/* ===== RESPONSIVO ===== */

@media(max-width:768px){

  .aston-evolution{
    padding:90px 18px;
  }

  .car-container-aston{
    height:320px;
  }

  .car-circle-aston{
    width:250px;
    height:250px;
  }

  .car-container-aston img{
    max-width:340px;
  }

  .controls-aston{
    gap:10px;
  }

  .controls-aston button{
    padding:12px 16px;
    font-size:.8rem;
  }

  .info-card-aston{
    padding:28px 22px;
  }

}


.eras-aston{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
    radial-gradient(circle at top,
    #00a08f 0%,
    #006f62 35%,
    #003d37 70%,
    #001b19 100%);

    overflow:hidden;

    color:#eafffb;
}

/* GLOW FUNDO */
.eras-aston::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(0,255,200,.18),
    transparent 70%);

    filter:blur(40px);

    animation:astonGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-aston::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(255,255,255,.08),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-aston > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-eras-aston{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #7dffe4);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(0,255,200,.25);
}

/* ===== TEXTO ===== */
#textoEra-aston{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#dffdf8;

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-aston{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-aston button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #021816,
    #032c27);

    color:#7dffe4;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(125,255,228,.12);
}

/* brilho botão */
.botoes-eras-aston button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-aston button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-aston button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #00a08f,
    #00786d);

    color:#001b19;

    box-shadow:
    0 0 30px rgba(0,255,200,.35);
}

/* BOTÃO ATIVO */
.botoes-eras-aston .ativo{
    background:
    linear-gradient(
    145deg,
    #7dffe4,
    #00c8a8);

    color:#001b19;

    box-shadow:
    0 0 30px rgba(125,255,228,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#aston-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.aston-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(125,255,228,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.aston-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.aston-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.aston-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(125,255,228,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(0,255,200,.18);
}

/* ===== IMAGEM ===== */
.aston-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.aston-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(0,255,200,.28));
}

/* ===== ANO ===== */
.aston-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#7dffe4;

    text-shadow:
    0 0 12px rgba(125,255,228,.3);
}

/* ===== TEXTO ===== */
#aston-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#eafffb;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes astonGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-aston{
        padding:90px 18px;
    }

    .titulo-eras-aston{
        font-size:2.5rem;
    }

    #textoEra-aston{
        font-size:1rem;
    }

    .botoes-eras-aston{
        gap:10px;
    }

    .botoes-eras-aston button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #aston-timeline{
        grid-template-columns:1fr;
    }

    .aston-timeline-item{
        max-width:360px;
        margin:auto;
    }

}

