/*///////////////////////////////////////////
     HAAS
///////////////////////////////////////////*/

 body.haas{
   background: #f0f0f0;
 }



/*=========================================================
   haas HERO
========================================================= */

.haas-hero {
    position: relative;
    width: 100%;
    height: 100dvh;
    min-height: 620px;
    overflow: hidden;
    background: #020713;
    color: #fff;
    isolation: isolate;
}


/* =========================================================
   CARRO — FUNDO PRINCIPAL
========================================================= */

.haas-car-bg {
    position: absolute;
    inset: -5%;
    z-index: -5;

    background-image:
        url("carros/vf26.jpg");

    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;

    filter:
        brightness(.58)
        contrast(1.08)
        saturate(1.12);

    transform: scale(1.04);

    transition:
        transform 1s ease,
        filter 1s ease;
}


/* LEVE MOVIMENTO */

.haas-hero:hover .haas-car-bg {
    transform: scale(1.07);

    filter:
        brightness(.63)
        contrast(1.1)
        saturate(1.15);
}


/* =========================================================
   OVERLAY
========================================================= */

.haas-overlay {
    position: absolute;
    inset: 0;
    z-index: -4;

    background:

        /* AZUL */
        linear-gradient(
            115deg,
            rgba(2,2,2,.78),
            transparent 42%
        ),

        /* VERMELHO */
        linear-gradient(
            250deg,
            rgba(240,240,240,.32),
            transparent 42%
        ),

        /* ESCURECIMENTO */
        linear-gradient(
            to bottom,
            rgba(0,0,0,.55),
            transparent 25%,
            rgba(0,0,0,.08) 55%,
            rgba(0,0,0,.82) 100%
        );
}


/* =========================================================
   TOPO
========================================================= */

.haas-top {
    position: absolute;

    top: 25px;
    left: 4vw;
    right: 4vw;

    z-index: 30;

    display: flex;
    align-items: center;
    justify-content: space-between;
}


/* =========================================================
   HOME
========================================================= */

.haas-home {
    display: flex;
    align-items: center;

    gap: 8px;

    padding: 9px 13px;

    text-decoration: none;

    color: rgba(255,255,255,.75);

    border: 1px solid rgba(255,255,255,.2);

    background: rgba(0,0,0,.3);

