    height: 300px;

    display: flex;
    align-items: center;
    justify-content: center;

    pointer-events: none;

    animation: haas-logo-float 4s ease-in-out infinite;
}


/* LOGO */

.haas-logo img {
    position: relative;

    z-index: 2;

    width: 100%;
    height: 100%;

    object-fit: contain;

    display: block;

    filter: drop-shadow(0 5px 15px rgba(0,0,0,.6));
}


/* =========================================================
   ANIMAÇÃO DA LOGO
========================================================= */

@keyframes haas-logo-float {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-7px);
    }

}


/* =========================================================
   GLOW DA LOGO
========================================================= */

.haas-logo-glow {
    position: absolute;

    z-index: 1;

    width: 220px;
    height: 220px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(240,240,240,.3),
            rgba(240,240,240,.15),
            transparent 70%
        );

    filter: blur(20px);

    animation: haas-logo-glow 4s ease-in-out infinite;
}


/* =========================================================
   ANIMAÇÃO DO GLOW
========================================================= */

@keyframes haas-logo-glow {

    0%,
    100% {
        transform: scale(.9);
        opacity: .55;
    }

    50% {
        transform: scale(1.15);
        opacity: 1;
    }

}

/* =========================================================
   NOME DA EQUIPE
========================================================= */

.haas-main {
    position: absolute;

    z-index: 20;

    left: 7vw;
    top: 28%;

    max-width: 520px;
}

.haas-kicker {
    font-size: 25px;
	  letter-spacing:3px;
    font-weight: 900;
    color: #E10600;
}

.haas-main h1 {
    margin: 8px 0 4px;
    color:#F0F0F0;
