    line-height: .82;

    font-weight: 900;

    letter-spacing: -5px;

    text-shadow:
        0 8px 30px rgba(0,0,0,.8);
}

.haas-main h1 strong {
    display: block;

    font-weight: 300;

    color: #fff;

    letter-spacing: -3px;
}

.haas-full-name {
