/* =========================================================
   PILOTOS haas
========================================================= */

.pilotos-haas {

    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 100dvh;

    overflow: hidden;

    box-sizing: border-box;

    padding: 45px 5vw;

    background:
        radial-gradient(
            circle at 50% 100%,
            rgba(225,6,0,.12),
            transparent 35%
        ),
        linear-gradient(
            120deg,
            #050505,
            #0b0b0b,
            #050505
        );

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.pilotos-titulo-haas {

    position: relative;

    z-index: 20;

    text-align: center;

    margin-bottom: 25px;
}


.pilotos-titulo-haas span {

    display: block;

    color: #F0F0F0;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 5px;
}


.pilotos-titulo-haas h2 {

    margin: 4px 0;

    font-size: clamp(30px, 4vw, 52px);

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotos-titulo-haas p {

    margin: 0;

    color: rgba(255,255,255,.62);

    font-size: 18px;
}


/* =========================================================
   ÁREA DOS PILOTOS
========================================================= */

.dupla-pilotos-haas {

    position: relative;

    display: grid;

    grid-template-columns: 1fr 1fr;

    height: calc(100% - 125px);

    max-width: 1450px;

    margin: auto;
}


/* =========================================================
   PILOTO
========================================================= */

.piloto-haas {

    position: relative;

    display: block;

    height: 100%;

    overflow: hidden;

    text-decoration: none;

    color: white;

    transition:
        transform .5s ease;
}


/* =========================================================
   BRILHO DE FUNDO
========================================================= */

.piloto-haas::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: 15%;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(225,6,0,.15),
            transparent 68%
        );

    filter: blur(30px);

    opacity: .35;

    transition:
        transform .7s ease,
        opacity .7s ease;

    pointer-events: none;
}


/* =========================================================
   BRILHO ocon
========================================================= */

.piloto-ocon-haas::before {

    left: -220px;
}


/* =========================================================
   BRILHO oliver
========================================================= */

.piloto-oliver-haas::before {

    right: -220px;
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.piloto-numero-bg-haas {

    position: absolute;

    z-index: 0;

    top: 5%;

    font-size: clamp(200px, 40vw, 400px);

    font-weight: 900;

    line-height: 1;

    color: transparent;

    -webkit-text-stroke:
        1px rgba(255,255,255,.08);

    opacity: .8;

    transition:
        color .7s ease,
        -webkit-text-stroke .7s ease,
        transform .7s ease,
        opacity .7s ease;
}


/* =========================================================
   NÚMERO ocon
========================================================= */

.piloto-ocon-haas
.piloto-numero-bg-haas {

    left: -3%;
	    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   NÚMERO oliver
========================================================= */

.piloto-oliver-haas
.piloto-numero-bg-haas {

    right: -2%;

    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   FOTO
========================================================= */

.piloto-foto-haas {

    position: absolute;

    z-index: 2;

    left: 50%;

    bottom: 0;

    width: 70%;

    height: 90%;

    transform:
        translateX(-50%);

    display: flex;

    align-items: flex-end;

    justify-content: center;

    pointer-events: none;
}


.piloto-foto-haas img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center bottom;

    filter:
        grayscale(.35)
        brightness(.65);

    opacity: .72;

    transform:
        translateY(30px)
        scale(.95);

    transition:
        transform .8s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


/* =========================================================
   POSIÇÃO DA FOTO DO oliver
========================================================= */

.piloto-oliver-haas
.piloto-foto-haas {

    transform:
        translateX(-60%);
}


/* =========================================================
   DADOS DO PILOTO
========================================================= */

.piloto-dados-haas {

    position: absolute;

    z-index: 30;

    left: 7%;

    bottom: 9%;

    max-width: 80%;

    transition:
        transform .6s ease;
}

/* =========================================================
   DADOS DO oliver
========================================================= */

.piloto-oliver-haas
.piloto-dados-haas {

    left: auto;

    right: 7%;

    text-align: right;
}


/* =========================================================
   PAÍS
========================================================= */

.piloto-pais-haas {

    display: block;

    margin-bottom: 8px;

    color: #F0F0F0;
	
    font-size: 15px;

    font-weight: 800;

    letter-spacing: 4px;
}


/* =========================================================
   HAMILTON — FUNDO DO NOME MAIS TRANSPARENTE
========================================================= */

.piloto-ocon-haas
.piloto-dados-haas h3::before {

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.70) 0%,
            rgba(0,0,0,.60) 45%,
            rgba(0,0,0,.30) 75%,
            transparent 100%
        );

    opacity: .75;

    filter: blur(7px);
}

/* =========================================================
   NOME
========================================================= */

.piloto-dados-haas h3 {

    position: relative;

    display: inline-flex;

    flex-direction: column;

    align-items: flex-start;

    margin: 0;

    padding: 6px 14px 8px 0;

    z-index: 31;

    font-size: clamp(28px, 3vw, 42px);

    line-height: .9;

    font-weight: 900;

    color: #fff;

    text-shadow:
        0 3px 10px rgba(0,0,0,1),
        0 0 18px rgba(0,0,0,1);
}

/* =========================================================
   NOME oliver — ALINHAMENTO
========================================================= */

.piloto-oliver-haas
.piloto-dados-haas h3 {

    align-items: flex-end;

    padding-right: 0;

    padding-left: 14px;
}


/* =========================================================
   FUNDO DE PROTEÇÃO DO NOME
========================================================= */

.piloto-dados-haas h3::before {

    content: "";

    position: absolute;

    z-index: -1;

    top: -12px;
    bottom: -12px;

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.98) 0%,
            rgba(0,0,0,.92) 45%,
            rgba(0,0,0,.72) 70%,
            rgba(0,0,0,.15) 100%
        );

    filter: blur(6px);

    opacity: .95;

    pointer-events: none;

    transition:
        opacity .4s ease,
        transform .4s ease;
}


/* =========================================================
   PROTEÇÃO DO NOME — LADO DIREITO
========================================================= */

.piloto-oliver-haas
.piloto-dados-haas h3::before {

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            270deg,
            rgba(0,0,0,.90) 0%,
            rgba(0,0,0,.90) 45%,
            rgba(0,0,0,.70) 70%,
            rgba(0,0,0,.10) 100%
        );
}


/* =========================================================
   PRIMEIRO NOME
========================================================= */

.piloto-dados-haas h3 {

    color: #fff;
}


/* =========================================================
   SOBRENOME
========================================================= */

.piloto-dados-haas h3 strong {

    position: relative;

    display: block;

    color: #fff;

    font-weight: 900;

    transition:
        color .35s ease,
        text-shadow .35s ease;
}


/* =========================================================
   LINHA
========================================================= */

.piloto-linha-haas {

    width: 65px;

    height: 2px;

    margin: 15px 0;

    background: #F0F0F0;

    box-shadow:
        0 0 12px rgba(225,6,0,.7);

    transition:
        width .6s ease;
}


.piloto-oliver-haas
.piloto-linha-haas {

    margin-left: auto;
}


/* =========================================================
   CATEGORIA
========================================================= */

.piloto-categoria-haas {

    color: rgba(255,255,255,.98);

    font-size: 12px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* =========================================================
   AÇÃO
========================================================= */

.piloto-acao-haas {

    position: absolute;

    z-index: 14;

    right: 7%;

    bottom: 10%;

    display: flex;

    align-items: center;

    gap: 12px;

    color: rgba(255,255,255,.4);

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    transition:
        color .4s ease,
        transform .5s ease;
}


/* =========================================================
   AÇÃO oliver
========================================================= */

.piloto-oliver-haas
.piloto-acao-haas {

    right: auto;

    left: 4%;
}


/* =========================================================
   ÍCONE
========================================================= */

.piloto-acao-haas strong {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 28px;

    height: 28px;

    border: 1px solid rgba(225,6,0,.3);

    color: #F0F0F0;

    font-size: 12px;

    transition:
        background .4s ease,
        color .4s ease,
        transform .4s ease;
}



/* =========================================================
   CENTRO haas
========================================================= */

.centro-haas {

    position: absolute;

    z-index: 25;

    left: 50%;
    top: 5%;

    bottom: 5%;

    width: 90px;

    transform: translateX(-50%);

    display: flex;

    flex-direction: column;

    align-items: center;

    pointer-events: none;
}


/* =========================================================
   LOGO CENTRAL
========================================================= */

.centro-logo-haas {

    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle,
            rgba(5,5,5,.95) 45%,
            rgba(5,5,5,.75) 70%,
            transparent 100%
        );

    flex-shrink: 0;
}


.centro-logo-haas img {

    width: 55px;
    height: 55px;

    object-fit: contain;

    opacity: .75;

    filter:
        drop-shadow(
            0 0 8px rgba(225,6,0,.25)
        );

    transition:
        transform .5s ease,
        opacity .5s ease,
        filter .5s ease;
}


/* =========================================================
   LINHA VERTICAL
========================================================= */

.centro-linha-haas {

    width: 1px;

    flex: 1;

    min-height: 80px;

    background:
        linear-gradient(
            to bottom,
            rgba(225,6,0,.8),
            rgba(225,6,0,.15),
            transparent
        );

    box-shadow:
        0 0 8px rgba(225,6,0,.25);
}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.centro-nome-haas {

    writing-mode: vertical-rl;

    text-orientation: mixed;

    margin-top: 12px;

    color: rgba(255,255,255,.3);

    font-size: 20px;

    font-weight: 800;

    letter-spacing: 4px;

    text-transform: uppercase;

    white-space: nowrap;

    transition:
        color .4s ease,
        text-shadow .4s ease;
}


/* =========================================================
   HOVER NOS PILOTOS
========================================================= */

.dupla-pilotos-haas:has(
    .piloto-haas:hover
)
.centro-logo-haas img {

    opacity: 1;

    transform: scale(1.1);

    filter:
        drop-shadow(
            0 0 8px #f0f0f0
        )
        drop-shadow(
            0 0 20px rgba(255,255,255,.55)
        );
}


.dupla-pilotos-haas:has(
    .piloto-haas:hover
)
.centro-nome-haas {

    color: #F0F0F0;

    text-shadow:
        0 0 15px rgba(225,6,0,.99);
}


/* =========================================================
   HOVER — PILOTO
========================================================= */

.piloto-haas:hover {

    z-index: 20;
}


/* =========================================================
   HOVER — BRILHO
========================================================= */

.piloto-haas:hover::before {

    opacity: .9;

    transform: scale(1.3);
}


/* =========================================================
   HOVER — NÚMERO
========================================================= */

.piloto-haas:hover
.piloto-numero-bg-haas {

    color: rgba(225,6,0,.14);

    -webkit-text-stroke:
        1px rgba(225,6,0,.28);

    transform: scale(1.05);

    opacity: 1;
}


/* =========================================================
   HOVER — FOTO
========================================================= */

.piloto-haas:hover
.piloto-foto-haas img {

    filter:
        grayscale(0)
        brightness(1);

    opacity: 1;

    transform:
        translateY(0)
        scale(1.02);
}


/* =========================================================
   HOVER — DADOS
========================================================= */

.piloto-haas:hover
.piloto-dados-haas {

    transform:
        translateY(-8px);
}


/* =========================================================
   HOVER — NOME
========================================================= */

.piloto-haas:hover
.piloto-dados-haas h3 strong {

    color: #F0F0F0;

    text-shadow:
        0 0 8px rgba(225,6,0,.88),
        0 0 20px rgba(225,6,0,.95),
        0 3px 10px rgba(255,6,0,.99);
}


/* =========================================================
   HOVER — FUNDO DO NOME
========================================================= */

.piloto-haas:hover
.piloto-dados-haas h3::before {

    opacity: 1;

    transform: scaleX(1.05);
}


/* =========================================================
   HOVER — LINHA
========================================================= */

.piloto-haas:hover
.piloto-linha-haas {

    width: 120px;
}


/* =========================================================
   HOVER — AÇÃO
========================================================= */

.piloto-haas:hover
.piloto-acao-haas {

    color: white;

    transform:
        translateY(-5px);
}


.piloto-haas:hover
.piloto-acao-haas strong {

    background: #F0F0F0;

    color: #dc0000;

    transform:
        rotate(45deg);
}


.piloto-haas:hover
.piloto-pais-haas {

    color: #F0f0f0;

	    text-shadow:
        0 0 8px rgba(225,6,0,.88),
        0 0 20px rgba(225,6,0,.95),
        0 3px 10px rgba(255,6,0,.99);
	
    transform:
        translateY(-5px);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 700px) {

    .pilotos-haas {

        padding:
            25px 12px;
    }


    .pilotos-titulo-haas {

        margin-bottom: 10px;
    }


    .pilotos-titulo-haas h2 {

        font-size: 30px;
    }


    .pilotos-titulo-haas p {

        font-size: 10px;
    }


    .dupla-pilotos-haas {

        height: calc(100% - 100px);

        grid-template-columns:
            1fr 1fr;
    }


    .dupla-pilotos-haas::before {

        top: 8%;

        bottom: 8%;
    }


    /* FOTO */

    .piloto-foto-haas {

        width: 110%;

        height: 72%;
    }


    /* NÚMERO */

    .piloto-numero-bg-haas {

        font-size: 150px;

        top: 15%;
    }


    .piloto-oliver-haas
    .piloto-numero-bg-haas {

        font-size: 135px;

        right: -5%;
    }


    /* DADOS */

    .piloto-dados-haas {

        left: 6%;

        bottom: 13%;

        max-width: 88%;
    }


    .piloto-oliver-haas
    .piloto-dados-haas {

        right: 6%;

        left: auto;
    }


    /* PAÍS */

    .piloto-pais-haas {

        font-size: 6px;

        letter-spacing: 2px;
    }


    /* NOME */

    .piloto-dados-haas h3 {

        font-size: 25px;

        line-height: .9;
    }


    /* LINHA */

    .piloto-linha-haas {

        margin-top: 9px;

        margin-bottom: 8px;

        width: 40px;
    }


    /* CATEGORIA */

    .piloto-categoria-haas {

        font-size: 5px;

        letter-spacing: 1px;
    }


    /* AÇÃO */

    .piloto-acao-haas {

        bottom: 5%;

        right: 6%;

        font-size: 6px;
    }


    .piloto-oliver-haas
    .piloto-acao-haas {

        left: 6%;

        right: auto;
    }


    .piloto-acao-haas strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-haas {

        padding:
            20px 8px;
    }


    .pilotos-titulo-haas h2 {

        font-size: 25px;
    }


    .pilotos-titulo-haas p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-haas {

        font-size: 115px;
    }


    .piloto-oliver-haas
    .piloto-numero-bg-haas {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-haas {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-haas {

        bottom: 12%;
    }


    .piloto-dados-haas h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-haas {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-haas span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-haas,
    .piloto-haas::before,
    .piloto-numero-bg-haas,
    .piloto-foto-haas img,
    .piloto-dados-haas,
    .piloto-dados-haas h3::before,
    .piloto-dados-haas h3 strong,
    .piloto-linha-haas,
    .piloto-acao-haas,
    .piloto-acao-haas strong {

        animation: none !important;

        transition: none !important;
    }

}




