========================================================= */

.linha-evolution-header-haas {
    position: relative;

    z-index: 10;

    text-align: center;

    margin-bottom: 28px;
}


.linha-evolution-header-haas > span {
    font-size: 13px;

    font-weight: 800;

    letter-spacing: 4px;

    color: rgba(220,255,255,.42);
}


.linha-evolution-header-haas h2 {
    margin: 6px 0 3px;

    font-size: clamp(28px, 4vw, 48px);

    line-height: 1;

    font-weight: 300;

    letter-spacing: -2px;
}


.linha-evolution-header-haas h2 strong {
    font-weight: 900;

    color: #F0F0F0;

    text-shadow:
        0 0 25px rgba(190,255,255,.2);
}


.linha-evolution-header-haas p {
    margin: 0;

    font-size: 15px;

    color: rgba(255,255,255,.35);

    letter-spacing: 1px;
}


/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-haas {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: flex;
    align-items: center;
    justify-content: center;
    grid-template-columns:
        repeat(5, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}

.linha-evolution-grid-haas
.linha-evolution-team-haas {
    width: min(420px, 70vw);
    height: 100%;
    flex: 0 0 min(420px, 70vw);
}
/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-haas {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-haas:hover
.linha-evolution-team-haas {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-haas
.linha-evolution-team-haas:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-haas {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-haas:hover
.team-bg-number-haas {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-haas {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-haas::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-haas img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-haas:hover
.team-image-haas {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-haas:hover
.team-image-haas::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-haas:hover
.team-image-haas img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-haas {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-haas:hover
.team-content-haas {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-haas {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-haas h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-haas {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-haas:hover
.team-line-haas {

    width: 65px;
}


/* Função */

.team-role-haas {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-haas {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-haas:hover
.team-arrow-haas {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


/* =========================================================
   CORES DAS EQUIPES
========================================================= */





/* =========================================================
   haas ATUAL
========================================================= */

.team-haas-current {

    --team-color: #F0F0F0;

    --team-glow:
        rgba(240,240,240,.8);
}


.team-haas-current:hover {

    background:
        linear-gradient(
            145deg,
            #071716,
            #050708 70%
        );

    border-color:
        rgba(240,240,240,.18);
}


.team-haas-current
.team-content-haas h3 {

    color: #F0F0F0;
}


.team-haas-current
.team-image-haas img {

    filter:
        grayscale(0%)
        brightness(.95);

    opacity: .85;
}


/* =========================================================
   FOOTER
========================================================= */

.linha-evolution-footer-haas {

    position: absolute;

    z-index: 10;

    left: 4vw;

    right: 4vw;

    bottom: 15px;

    display: flex;

    align-items: center;

    gap: 12px;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 3px;

    color:
        rgba(240,240,240,.25);
}


.footer-line-haas {

    height: 1px;

    flex: 1;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12)
        );
}


.footer-line-haas:last-of-type {

    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.12),
            transparent
        );
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 900px) {

    .haas-linha-evolution {

        padding-left: 20px;

        padding-right: 20px;
    }


    .linha-evolution-grid-haas {

        grid-template-columns:
            repeat(
                5,
                minmax(120px, 1fr)
            );

        overflow-x: auto;

        scrollbar-width: none;
    }


    .linha-evolution-grid-haas::-webkit-scrollbar {

        display: none;
    }


    .linha-evolution-team-haas {

        min-width: 150px;
    }


    .team-content-haas {

        left: 14px;

        right: 14px;

        bottom: 18px;
    }

}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .haas-linha-evolution {

        height: auto;

        min-height: 100dvh;

        padding:
            32px 15px 55px;
    }


    .linha-evolution-header-haas {

        margin-bottom: 18px;
    }


    .linha-evolution-header-haas > span {

        font-size: 6px;

        letter-spacing: 2px;
    }


    .linha-evolution-header-haas h2 {

        font-size: 28px;
    }


    .linha-evolution-header-haas p {

        font-size: 8px;
    }


    .linha-evolution-grid-haas {

        height: 62dvh;

        grid-template-columns:
            repeat(5, 145px);

        gap: 3px;

        overflow-x: auto;

        padding-bottom: 8px;
    }


    .linha-evolution-team-haas {

        min-width: 145px;
    }


    .team-image-haas {

        width: 75%;

        height: 55%;
    }


    .team-content-haas {

        left: 12px;

        bottom: 15px;
    }


    .team-content-haas h3 {

        font-size: 19px;
    }


    .team-bg-number-haas {

        font-size: 110px;
    }


    .team-arrow-haas {

        top: 12px;

        left: 12px;

        width: 22px;

        height: 22px;
    }


    .linha-evolution-footer-haas {

        left: 15px;

        right: 15px;
    }

}


.tabela-haas{
    position:relative;

    width:100%;

    padding:clamp(80px,12vw,140px) 20px;

    overflow:hidden;

    background:
    linear-gradient(
      120deg,
      #050505 35%,
      #8b0000 130%
    );

    color:#ff2a2a;
}

/* ===== TÍTULO ===== */
.titulo-tabela-haas{
    text-align:center;

    font-size:clamp(28px,4vw,46px);

    margin-bottom:60px;

    display:flex;
    justify-content:center;
    align-items:center;

    gap:12px;

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;
}

/* LOGO */
.logo-titulo-haass{
    width:clamp(28px,4vw,46px);

    filter:
    drop-shadow(0 0 12px rgba(255,0,0,.7));

    transition:.3s ease;
}

.titulo-tabela-haas:hover .logo-titulo-haass{
    transform:scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-haas{
    width:90%;
    max-width:1500px;

    margin:auto;

    background:
    rgba(0,0,0,.72);

    border-radius:22px;

    overflow:hidden;

    backdrop-filter:blur(10px);

    border:
    1px solid rgba(255,0,0,.15);

    box-shadow:
    0 0 40px rgba(255,0,0,.12),
    inset 0 0 30px rgba(255,0,0,.04);
}

/* ===== TABELA ===== */
.box-tabela-haas table{
    width:100%;

    border-collapse:collapse;

    min-width:600px;
}

/* ===== LINHAS ===== */
.box-tabela-haas tr{
    transition:.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-haas td{
    padding:clamp(18px,2.5vw,28px);

    font-size:clamp(15px,2vw,20px);

    border-bottom:
    1px solid rgba(255,255,255,.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-haas td:first-child{
    color:#ff2a2a;

    font-weight:800;

    width:50%;
}

/* SEGUNDA COLUNA */
.box-tabela-haas td:last-child{
    text-align:right;

    color:#e6e6e6;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-haas tr:hover{
    background:
    linear-gradient(
      90deg,
      rgba(255,0,0,.10),
      rgba(255,80,80,.08)
    );

    transform:scale(1.01);
}

/* ===== MOBILE ===== */
@media(max-width:768px){

  .box-tabela-haas{
    width:95%;
    overflow:hidden;
  }

  .box-tabela-haas table{
    width:100%;
    min-width:100%;
  }

  .box-tabela-haas td{
    padding:10px 8px;

    font-size:18px;
  }

  .box-tabela-haas td:first-child{
    width:45%;

    font-size:16px;
  }

  .box-tabela-haas td:last-child{
    width:55%;

    font-size:18px;

    text-align:right;

    word-break:break-word;
  }

  .titulo-tabela-haas{
    font-size:22px;
  }

}


/* =====================================
   TEMPORADA haas 2026
===================================== */

.temporada-haas{

    position:relative;

    overflow:hidden;

    padding:80px 20px;

    color:#fff;

    background:
    radial-gradient(
        circle at top,
        #b6babd 0%,
        #120900 45%,
        #050505 100%
    );

}


/* brilho de fundo */

.temporada-haas::before{

    content:"";

    position:absolute;

    top:-200px;

    right:-200px;

    width:500px;

    height:500px;


    background:
    radial-gradient(
        circle,
        rgba(182,186,189,.18),
        transparent 70%
    );


    filter:blur(50px);

}


.temporada-haas > *{

    position:relative;

    z-index:2;

}



/* =====================================
   TÍTULO
===================================== */


.titulo-temp-haas{

    text-align:center;

    margin-bottom:50px;

    font-size:
    clamp(2.5rem,6vw,5rem);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:3px;


    color:#fff;


    text-shadow:

    0 0 20px
    rgba(182,186,189,.55);

}



/* =====================================
   DASHBOARD
===================================== */


.dashboard-haas{

    max-width:1200px;

    margin:auto;

}



/* =====================================
   TOPO
===================================== */


.topo-temp-haas{

    display:grid;

    grid-template-columns:

    220px 1fr 220px;

    gap:20px;

    align-items:center;

}



/* =====================================
   CARD POSIÇÃO
===================================== */


.card-campeonato-haas,
.card-pontos-haas,
.card-grafico-haas{


    background:

    linear-gradient(
        145deg,
        #161616,
        #202020
    );


    border-radius:25px;


    border:

    1px solid
    rgba(182,186,189,.2);


    box-shadow:

    0 15px 35px
    rgba(0,0,0,.35);


}



/* posição */

.card-campeonato-haas,
.card-pontos-haas{


    padding:30px 20px;

    text-align:center;

}



.valor-posicao-haas{

    font-size:70px;

    font-weight:900;

    color:#b6babd;


    text-shadow:

    0 0 20px
    rgba(182,186,189,.5);

}



.card-campeonato-haas p,
.card-pontos-haas p{


    margin:10px 0 0;


    color:#bbb;


    font-weight:700;

    text-transform:uppercase;

    font-size:14px;

}



/* =====================================
   PONTOS
===================================== */


#pontoshaas{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-haas{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-haas svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficohaas{


    stroke:#b6babd;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(182,186,189,.8)
    );


}

/* =====================================
   DESEMPENHO haas
===================================== */

.desempenho-haas{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-haas > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(182,186,189,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-haas > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(182,186,189,.55);



    box-shadow:

    0 0 25px
    rgba(182,186,189,.25);


}



/* números */

.desempenho-haas span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#b6babd;



    text-shadow:

    0 0 15px
    rgba(182,186,189,.45);


}



/* textos */

.desempenho-haas p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-haas span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(182,186,189,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(182,186,189,.75);

    }


}



/* =====================================
   DESTAQUE haas
===================================== */


.card-campeonato-haas::before,
.card-pontos-haas::before,
.card-grafico-haas::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(182,186,189,.12),
        transparent 45%
    );


    pointer-events:none;


}



/* garante posição dos cards */

.card-campeonato-haas,
.card-pontos-haas,
.card-grafico-haas{


    position:relative;


    overflow:hidden;


}

/* =====================================
   RESULTADOS haas
===================================== */

.resultados-haas{

    margin-top:45px;

    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );

    border-radius:25px;

    padding:25px;

    border:

    1px solid
    rgba(182,186,189,.18);

    box-shadow:

    0 15px 35px
    rgba(0,0,0,.4);

    overflow:hidden;

}



/* tabela */

.resultados-haas table{

    width:100%;

    border-collapse:collapse;

}



/* cabeçalho */

.resultados-haas th{


    padding:16px;


    background:

    rgba(182,186,189,.15);


    color:#b6babd;


    text-transform:uppercase;


    font-size:14px;


    letter-spacing:1px;

}



/* células */

.resultados-haas td{


    padding:14px;


    text-align:center;


    color:#ddd;


    border-bottom:

    1px solid
    rgba(255,255,255,.06);


    font-weight:600;

	 font-size:25px;

}



/* hover linha */

.resultados-haas tbody tr{


    transition:.3s ease;


}



.resultados-haas tbody tr:hover{


    background:

    rgba(182,186,189,.08);


    transform:

    scale(1.01);

}



/* primeira coluna */

.resultados-haas td:first-child{


    color:#b6babd;


    font-weight:900;

}



/* =====================================
   TOTAL PONTOS
===================================== */


.total-haas{


    margin-top:25px;


    padding:18px;


    border-radius:18px;


    text-align:center;


    background:

    linear-gradient(
        145deg,
        #dc0000,
        #b6babd
    );


    color:#fff;


    font-size:22px;


    font-weight:900;


    box-shadow:

    0 0 25px
    rgba(182,186,189,.35);

}



#totalTabelahaas{


    font-size:32px;


    margin-left:8px;

}



