}


/*==================================================
        ESTATÍSTICAS
==================================================*/

.haas-stats{

    width:100%;

    display:flex;

    flex-direction:column;

    gap:13px;

}


/*==================================================
        CADA ESTATÍSTICA
==================================================*/

.haas-stat{

    width:100%;

}


/*==================================================
        VALORES

        NORRIS | LABEL | PIASTRI
==================================================*/

.haas-stat-values{

    width:100%;

    display:grid;

    grid-template-columns:
        70px
        1fr
        70px;

    align-items:center;

}


.haas-value{

    display:flex;

    align-items:center;

    justify-content:center;

    font-size:28px;

    line-height:1;

    font-weight:1000;

    color:white;

}


.haas-label{

    text-align:center;

    font-size:14px;

    font-weight:900;

    letter-spacing:2px;

    color:#F0f0f0;

    white-space:nowrap;

}


/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.haas-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.haas-bar-left,
.haas-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.haas-bar-left{

    border-radius:999px 0 0 999px;

}


.haas-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #000000,
        #F0f0f0
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.haas-bar-right{

    border-radius:0 999px 999px 0;

}


.haas-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #F0f0f0,
        #000000
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.haas-value{

    animation:
    haasValueShow .5s ease;

}


@keyframes haasValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.haas-winner{

    color:#F0f0f0 !important;

    text-shadow:
    0 0 15px rgba(255,6,0,.8);

}


.haas-draw{

    color:#020202 !important;

}


