/* =========================================================
   haas — LIDERANÇA / COMMAND CENTER
========================================================= */

.haas-lideranca {
    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 650px;

    box-sizing: border-box;

    overflow: hidden;

    padding: 35px 5vw 25px;

    color: #fff;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(240,240,240,.16),
            transparent 30%
        ),
        radial-gradient(
            circle at 90% 80%,
            rgba(240,240,240,.10),
            transparent 30%
        ),
        #050505;

    isolation: isolate;
}


/* =========================================================
   GRID TÉCNICO DO FUNDO
========================================================= */

.haas-lideranca::before {
    content: "";

    position: absolute;

    inset: 0;

    z-index: -2;

    opacity: .35;

    background-image:
        linear-gradient(
            rgba(255,255,255,.025) 1px,
            transparent 1px
        ),
        linear-gradient(
            90deg,
            rgba(255,255,255,.025) 1px,
            transparent 1px
        );

    background-size: 55px 55px;

    pointer-events: none;
}


/* LINHA VERMELHA LATERAL */

.haas-lideranca::after {
    content: "";

    position: absolute;

    top: 0;
    right: 0;

    width: 3px;
    height: 100%;

    background:
        linear-gradient(
            to bottom,
            transparent,
            #F0F0F0 25%,
            #F0F0F0 75%,
            transparent
        );

    box-shadow:
        0 0 20px rgba(240,240,240,.35);

    pointer-events: none;
}


/* =========================================================
   HEADER
========================================================= */

.haas-lideranca-header {
    position: relative;

    width: 100%;
    max-width: 1500px;

    margin: 0 auto;
}


/* KICKER */

.haas-lideranca-kicker {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 8px;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 5px;

    color: rgba(255,255,255,.45);
}


.haas-lideranca-kicker span {
    width: 35px;
    height: 2px;

    background: #F0F0F0;

    box-shadow:
        0 0 10px rgba(240,240,240,.6);
}


/* =========================================================
   TÍTULO
========================================================= */

.haas-lideranca-titulo-area {
    display: flex;

    align-items: center;

    gap: 18px;
}


.haas-lideranca-indice {
    width: 46px;
    height: 46px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border: 1px solid rgba(240,240,240,.6);

    background:
        linear-gradient(
            135deg,
            rgba(240,240,240,.18),
            rgba(240,240,240,.02)
        );

    color: #F0F0F0;

    font-size: 11px;

    font-weight: 900;

    box-shadow:
        inset 0 0 20px rgba(240,240,240,.08);
}


.haas-lideranca-subtitulo {
    display: block;

    margin-bottom: 4px;

    font-size: 7px;

    font-weight: 900;

    letter-spacing: 4px;

    color: rgba(255,255,255,.32);
}


.haas-lideranca-titulo {
    margin: 0;

    font-size:
        clamp(32px, 4vw, 58px);

    line-height: .9;

    font-weight: 200;

    letter-spacing: -2px;

    text-transform: uppercase;
}


.haas-lideranca-titulo strong {
    font-weight: 900;

    color: #F0F0F0;

    text-shadow:
        0 0 30px rgba(240,240,240,.18);
}


.haas-lideranca-descricao {
    margin: 7px 0 0;

    font-size: 9px;

    color: rgba(255,255,255,.5);

    letter-spacing: .3px;
}


/* =========================================================
   LINHA DO HEADER
========================================================= */

.haas-lideranca-linha {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: 1px;

    margin:
        17px auto 15px;

    background:
        linear-gradient(
            90deg,
            #F0F0F0,
            rgba(255,255,255,.12),
            transparent
        );
}


.haas-lideranca-linha span {
    position: absolute;

    left: 0;
    top: -2px;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: #F0F0F0;

    box-shadow:
        0 0 12px rgba(240,240,240,.8);
}


/* =========================================================
   GRID DOS LÍDERES
========================================================= */

.haas-lideranca-estrutura {
    position: relative;

    width: 100%;
    max-width: 1500px;

    height: calc(100% - 185px);

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        1.15fr 1.15fr .9fr .9fr;

    grid-template-rows:
        1fr 1fr;

    gap: 10px;
}


/* =========================================================
   CARD
========================================================= */

.haas-lideranca-card {
    position: relative;

    min-width: 0;
    min-height: 0;

    overflow: hidden;

    cursor: pointer;

    border:
        1px solid rgba(255,255,255,.12);

    background: #0b0b0b;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1),
        border-color .45s ease,
        box-shadow .45s ease;
}


/* BRILHO NO CARD */

.haas-lideranca-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: -120%;

    width: 70%;
    height: 100%;

    z-index: 5;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12),
            transparent
        );

    transform: skewX(-20deg);

    transition:
        left .7s ease;

    pointer-events: none;
}


/* LINHA INFERIOR */

.haas-lideranca-card::after {
    content: "";

    position: absolute;

    left: 0;
    bottom: 0;

    width: 0;
    height: 3px;

    z-index: 15;

    background:
        linear-gradient(
            90deg,
            #F0F0F0,
            #fa9a9a,
            transparent
        );

    transition:
        width .5s ease;
}


/* HOVER */

.haas-lideranca-card:hover {
    transform:
        translateY(-7px)
        scale(1.015);

    border-color:
        rgba(240,240,240,.7);

    box-shadow:
        0 20px 50px rgba(0,0,0,.65),
        0 0 35px rgba(240,240,240,.12);
}


.haas-lideranca-card:hover::before {
    left: 140%;
}


.haas-lideranca-card:hover::after {
    width: 100%;
}


/* =========================================================
   TOPO DOS CARDS
========================================================= */

.haas-lideranca-card-topo {
    position: absolute;

    top: 12px;
    left: 13px;
    right: 13px;

    z-index: 12;

    display: flex;

    justify-content: space-between;

    align-items: center;
}


.haas-lideranca-card-numero {
    font-size: 8px;

    font-weight: 900;

    letter-spacing: 2px;

    color: rgba(255,255,255,.55);
}


.haas-lideranca-card-cargo {
    padding: 5px 7px;

    background:
        rgba(0,0,0,.65);

    border:
        1px solid rgba(255,255,255,.14);

    backdrop-filter: blur(8px);

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 1.5px;

    color: rgba(255,255,255,.65);

    transition:
        background .4s ease,
        border-color .4s ease,
        color .4s ease;
}


.haas-lideranca-card:hover
.haas-lideranca-card-cargo {
    background:
        rgba(240,240,240,.25);

    border-color:
        rgba(240,240,240,.6);

    color: #fff;
}


/* =========================================================
   FOTO
========================================================= */

.haas-lideranca-foto {
    position: absolute;

    inset: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.haas-lideranca-foto img {
    width: 100%;
    height: 100%;

    object-fit: cover;

    display: block;

    opacity: .72;

    filter:
        grayscale(.35)
        contrast(1.12)
        brightness(.72);

    transform: scale(1.02);

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


.haas-lideranca-card:hover
.haas-lideranca-foto img {
    transform: scale(1.09);

    opacity: .9;

    filter:
        grayscale(0)
        contrast(1.08)
        brightness(.88);
}


/* =========================================================
   OVERLAY DA FOTO
========================================================= */

.haas-lideranca-foto-overlay {
    position: absolute;

    inset: 0;

    z-index: 2;

    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.1) 0%,
            transparent 30%,
            rgba(0,0,0,.35) 50%,
            rgba(0,0,0,.96) 100%
        );

    transition:
        background .5s ease;
}


.haas-lideranca-card:hover
.haas-lideranca-foto-overlay {
    background:
        linear-gradient(
            180deg,
            rgba(0,0,0,.05),
            rgba(240,240,240,.05) 45%,
            rgba(0,0,0,.94)
        );
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.haas-lideranca-info {
    position: absolute;

    left: 16px;
    right: 16px;
    bottom: 15px;

    z-index: 10;
}


.haas-lideranca-funcao {
    display: block;

    margin-bottom: 5px;

    font-size: 15px;

    font-weight: 900;

    letter-spacing: 2px;

    color: #ffffff;

    transition:
        color .35s ease;
}


.haas-lideranca-card:hover
.haas-lideranca-funcao {
    color: #ffb1b1;
}


.haas-lideranca-info h3 {
    margin: 0;

    font-size:
        clamp(19px, 1.8vw, 29px);

    line-height: .9;

    font-weight: 200;

    letter-spacing: -1px;

    color: #fff;

    text-shadow:
        0 3px 15px rgba(0,0,0,.9);
}


.haas-lideranca-info h3 strong {
    font-weight: 900;
	color: #F0F0F0;
}


.haas-lideranca-info p {
    max-width: 340px;

    margin: 8px 0 0;

    font-size: 7px;

    line-height: 1.45;

    color: rgba(255,255,255,.62);

    transition:
        color .35s ease;
}


.haas-lideranca-card:hover
.haas-lideranca-info p {
    color: rgba(255,255,255,.82);
}


/* =========================================================
   CARDS PRINCIPAIS
========================================================= */

.haas-lideranca-card-destaque,
.haas-lideranca-card-principal {
    border-color:
        rgba(240,240,240,.3);
}


.haas-lideranca-card-destaque
.haas-lideranca-info h3,
.haas-lideranca-card-principal
.haas-lideranca-info h3 {
    font-size:
        clamp(23px, 2.2vw, 36px);
}


/* =========================================================
   CARD DE ENGENHARIA
========================================================= */

.haas-lideranca-foto-logo {
    background:
        radial-gradient(
            circle,
            rgba(240,240,240,.14),
            transparent 65%
        );
}


.haas-lideranca-foto-logo img {
    width: 100%;
    height: auto;

    object-fit: contain;

    opacity: .65;

    filter:
        drop-shadow(
            0 0 25px rgba(240,240,240,.4)
        );

    transition:
        transform .6s ease,
        opacity .5s ease,
        filter .5s ease;
}


.haas-lideranca-card:hover
.haas-lideranca-foto-logo img {
    transform:
        scale(1.12);

    opacity: 1;

    filter:
        drop-shadow(
            0 0 35px rgba(240,240,240,.7)
        );
}


/* =========================================================
   FOOTER
========================================================= */

.haas-lideranca-footer {
    position: absolute;

    left: 5vw;
    right: 5vw;
    bottom: 10px;

    z-index: 20;

    display: flex;

    align-items: center;

    gap: 15px;

    font-size: 5px;

    font-weight: 900;

    letter-spacing: 3px;

    color: rgba(255,255,255,.3);
}


.haas-lideranca-footer div {
    flex: 1;

    height: 1px;

    background:
        linear-gradient(
            90deg,
            rgba(240,240,240,.6),
            rgba(255,255,255,.1),
            transparent
        );
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width:900px) {

    .haas-lideranca {
        padding:
            30px 20px 20px;
    }

    .haas-lideranca-estrutura {
        grid-template-columns:
            repeat(3, 1fr);

        grid-template-rows:
            repeat(3, 1fr);

        height: calc(100% - 180px);
    }

    .haas-lideranca-info h3 {
        font-size: 18px;
    }

    .haas-lideranca-info p {
        font-size: 6px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width:700px) {

    .haas-lideranca {
        height: 100dvh;

        min-height: 650px;

        padding:
            22px 12px 12px;
    }


    /* HEADER */

    .haas-lideranca-kicker {
        font-size: 6px;

        letter-spacing: 3px;
    }

    .haas-lideranca-kicker span {
        width: 20px;
    }

    .haas-lideranca-titulo-area {
        gap: 10px;
    }

    .haas-lideranca-indice {
        width: 32px;
        height: 32px;

        font-size: 8px;
    }

    .haas-lideranca-subtitulo {
        font-size: 5px;

        letter-spacing: 2px;
    }

    .haas-lideranca-titulo {
        font-size: 27px;
    }

    .haas-lideranca-descricao {
        max-width: 300px;

        font-size: 6px;
    }


    /* LINHA */

    .haas-lideranca-linha {
        margin:
            12px auto 9px;
    }


    /* GRID */

    .haas-lideranca-estrutura {
        height: calc(100% - 145px);

        grid-template-columns:
            repeat(2, 1fr);

        grid-template-rows:
            repeat(4, 1fr);

        gap: 6px;
    }


    /* CARDS */

    .haas-lideranca-card-topo {
        top: 7px;
        left: 7px;
        right: 7px;
    }

    .haas-lideranca-card-numero {
        font-size: 5px;
    }

    .haas-lideranca-card-cargo {
        padding: 3px 4px;

        font-size: 3.5px;

        letter-spacing: .8px;
    }


    /* INFO */

    .haas-lideranca-info {
        left: 8px;
        right: 8px;
        bottom: 8px;
    }

    .haas-lideranca-funcao {
        margin-bottom: 3px;

        font-size: 4px;

        letter-spacing: 1px;
    }

    .haas-lideranca-info h3 {
        font-size: 14px;
    }

    .haas-lideranca-card-destaque
    .haas-lideranca-info h3,
    .haas-lideranca-card-principal
    .haas-lideranca-info h3 {
        font-size: 16px;
    }

    .haas-lideranca-info p {
        margin-top: 4px;

        font-size: 5px;

        line-height: 1.25;
    }


    /* FOOTER */

    .haas-lideranca-footer {
        left: 12px;
        right: 12px;

        bottom: 6px;

        gap: 8px;

        font-size: 3.5px;

        letter-spacing: 1.5px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width:400px) {

    .haas-lideranca {
        min-height: 600px;

        padding:
            18px 9px 9px;
    }

    .haas-lideranca-titulo {
        font-size: 23px;
    }

    .haas-lideranca-descricao {
        display: none;
    }

    .haas-lideranca-estrutura {
        height: calc(100% - 120px);

        gap: 5px;
    }

    .haas-lideranca-info h3 {
        font-size: 12px;
    }

    .haas-lideranca-card-destaque
    .haas-lideranca-info h3,
    .haas-lideranca-card-principal
    .haas-lideranca-info h3 {
        font-size: 13px;
    }

    .haas-lideranca-info p {
        display: none;
    }

}


