    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:25px;

    text-shadow:

    0 0 15px #f0f0f0;

}



/* GRID */

.stats-grid-haas{

    position:relative;

    z-index:2;


    max-width:1200px;

    margin:auto;

    padding:0 35px;


    display:grid;

    grid-template-columns:
    repeat(3,1fr);


    gap:15px;

}



/* CARDS */

.card-stat-haas{

    position:relative;


    background:

    linear-gradient(
        145deg,
        rgba(10,10,10,.08),
        rgba(255,255,255,.25)
    );




    border-radius:22px;


    padding:18px;


    text-align:center;


    color:white;


    border:

    1px solid
    rgba(10,10,10,.5);



    box-shadow:

    0 15px 40px
    rgba(200,200,200,.7);



    overflow:hidden;



    opacity:0;

    transform:
    translateY(50px);



    transition:.6s ease;

}



/* LINHA LARANJA */

.card-stat-haas::before{

    content:"";

    position:absolute;

    top:0;

    left:0;

    width:100%;

    height:4px;


    background:

    linear-gradient(
        90deg,
        transparent,
        #f0f0f0,
        transparent
    );

}



/* ATIVO */

.card-stat-haas.ativo{

    opacity:1;

    transform:
    translateY(0);


    animation:

    brilhohaas 2.5s infinite alternate;

}



@keyframes brilhohaas{

    from{

        box-shadow:

        0 0 15px
