.hall-haas{
padding:120px 40px;
position:relative;
background:
linear-gradient(
120deg,
#ffffff 35%,
#000000 70%,
#dc0000 140%
);

min-height:auto;
height:auto;

overflow:hidden;
}

/* ===== TÍTULO ===== */

.titulo-hall-haas{
text-align:center;

font-size:52px;

color:#ffffff;

margin-bottom:80px;

text-shadow:
0 0 12px rgba(0,20,0,0.7);
}

/* ===== GRID ===== */

.hall-grid-haas{
display:flex;

justify-content:center;
align-items:flex-start;

flex-wrap:wrap;

perspective:1200px;

gap:40px;

position:relative;

z-index:3;
}

/* ===== FUNDO ===== */

.bg-hall-haas{
position:absolute;
inset:0;
z-index:0;
}

.bg-layer-haas{
position:absolute;
inset:0;

background-size:cover;
background-position:center center;
background-repeat:no-repeat;

transform:scale(1);

opacity:0;

transition:opacity .8s ease;
}

.bg-layer-haas.active{
opacity:1;
}

.hall-grid-haas,
.titulo-hall-haas,
.hall-overlay-haas{
position:relative;
z-index:2;
}

/* ===== SHOWCASE ===== */

.hall-haas.showcase .hall-card-haas{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

.hall-haas.showcase .bg-layer-haas.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.15)
saturate(1.2);

transition:1s ease;
}

/* ===== CARD ===== */

.hall-card-haas{
position:relative;

width:320px;

padding:30px;

border-radius:24px;

background:
linear-gradient(
180deg,
rgba(8,20,16,0.28),
rgba(8,20,16,0.72)
);

border:
1px solid rgba(0,20,0,0.25);

overflow:hidden;

transition:.45s ease;

box-shadow:
0 15px 35px rgba(0,0,0,0.45);

text-align:center;

backdrop-filter:blur(2px);

transform-origin:center top;
}

/* ===== GLOW TOPO ===== */

.hall-card-haas::before{
content:"";

position:absolute;

top:0;
left:0;

width:100%;
height:3px;

background:
linear-gradient(
90deg,
transparent,
#ffffff,
transparent
);
}

/* ===== REFLEXO ===== */

.hall-card-haas::after{
content:"";

position:absolute;

top:0;
left:-100%;

width:100%;
height:100%;

background:
linear-gradient(
120deg,
transparent,
rgba(255,250,250,.15),
transparent
);

transition:.6s;
}

.hall-card-haas:hover::after{
left:100%;
}

/* ===== HOVER ===== */

.hall-card-haas:hover{
transform:
translateY(-14px)
scale(1.04);

background:
rgba(8,20,16,0.92);

box-shadow:
0 25px 60px rgba(0,0,0,0.7),
0 0 30px rgba(0,0,1,0.25);

z-index:10;
}

.hall-grid-haas:hover .hall-card-haas{
opacity:.35;

transform:scale(.98);
}

.hall-card-haas:hover{
opacity:1 !important;

transform:
translateY(-14px)
scale(1.06);
}

/* ===== NÚMERO ===== */

.numero-hall-haas{
position:absolute;

top:15px;
right:20px;

font-size:70px;

font-weight:900;

color:rgba(0,2,1,0.08);
}

/* ===== FOTO ===== */

.hall-card-haas img{
width:170px;
height:200px;

object-fit:cover;

border-radius:50%;

border:
3px solid #ffffff;

margin-bottom:20px;

filter:
grayscale(100%)
brightness(.9);

transition:.5s ease;
}

.hall-card-haas:hover img{
filter:
grayscale(0%)
brightness(1.1);

transform:scale(1.1);
}

/* ===== CONTEÚDO ===== */

.hall-card-haas p,
.hall-stats-haas,
.frase-hall-haas{
opacity:0;

transform:translateY(10px);

max-height:0;

overflow:hidden;

transition:.4s ease;
}

.hall-card-haas:hover p,
.hall-card-haas:hover .hall-stats-haas,
.hall-card-haas:hover .frase-hall-haas{
opacity:1;

transform:translateY(0);

max-height:200px;
}

/* ===== NOME ===== */

.hall-card-haas h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}

/* ===== PAÍS ===== */

.pais-hall-haas{
display:block;

font-size:18px;

color:#dc0000;

margin-bottom:18px;
}

/* ===== TEXTO ===== */

.hall-card-haas p{
font-size:18px;

color:#ddd;

margin-bottom:22px;
}

/* ===== STATS ===== */

.hall-stats-haas{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#dc0000;
}

/* ===== FRASE ===== */

.frase-hall-haas{
font-size:14px;

font-style:italic;

color:#fff;

line-height:1.6;
}

