.haas-evolution{
  position:relative;
  width:100%;
  padding:120px 25px;
  overflow:hidden;

  background:
  radial-gradient(circle at top,#02140f 0%,#010807 60%);

  font-size:initial;

  transition:background 1s ease;
}

/* ===== FUNDOS ===== */

/* FORCE INDIA */
.haas-evolution.bg-2016{
  background:
  radial-gradient(
    circle at top,
    #000000 0%,
    #ffffff 45%,
    #dc0000 100%
  );
}

.haas-evolution.bg-2020{
  background:
  radial-gradient(
    circle at top,
    #ffffff 0%,
    #000000 45%,
    #000000 100%
  );
}

/* ===== BRILHOS ===== */

.haas-evolution::before{
  content:"";

  position:absolute;
  top:-220px;
  left:-220px;

  width:520px;
  height:520px;

  background:
  radial-gradient(
    circle,
    rgba(0,0,0,.18),
    transparent 70%
  );

  filter:blur(35px);

  animation:glowhaas 8s linear infinite;
}

.haas-evolution::after{
  content:"";

  position:absolute;
  right:-180px;
  bottom:-180px;

  width:420px;
  height:420px;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,.06),
    transparent 70%
  );

  filter:blur(50px);
}

/* ===== TÍTULO ===== */

.title-haas{
  position:relative;

  font-size:clamp(2.5rem,6vw,5rem);

  text-align:center;

  margin-bottom:80px;

  font-weight:900;

  letter-spacing:3px;

  text-transform:uppercase;

  background:
  linear-gradient(
    90deg,
    #ffffff,
    #000000
  );

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;

  z-index:5;
}

/* ===== ÁREA CARRO ===== */

.car-container-haas{
  position:relative;

  width:100%;
  max-width:900px;
  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;

  z-index:2;
}

/* ===== BASE ===== */

.car-container-haas::before{
  content:"";

  position:absolute;
  bottom:50px;

  width:70%;
  height:40px;

  background:
  radial-gradient(
    circle,
    rgba(250,250,250,.35),
    transparent 70%
  );

  filter:blur(20px);

  border-radius:50%;

  animation:pulseFloorhaas 4s ease-in-out infinite;
