  height:420px;

  border-radius:50%;

  border:
  2px solid rgba(250,250,250,.18);

  box-shadow:
    0 0 40px rgba(250,250,255,.15),
    inset 0 0 40px rgba(250,250,255,.08);

  animation:rotateCirclehaas 14s linear infinite;
}

.car-circle-haas::before{
  content:"";

  position:absolute;
  inset:20px;

  border-radius:50%;

  border:
  1px dashed rgba(255,255,255,.08);
}

/* ===== CARRO ===== */

.car-container-haas img{
  position:relative;

  width:100%;
  max-width:650px;

  object-fit:contain;

  z-index:5;

  filter:
  drop-shadow(
    0 30px 35px rgba(0,0,0,.6)
  );

  animation:
    floatCarhaas 5s ease-in-out infinite,
    rotateCarhaas 6s ease-in-out infinite;

  transition:
    opacity .45s ease,
    transform .45s ease;
}

/* ===== BOTÕES ===== */

.controls-haas{
  position:relative;

  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin-top:40px;
  margin-bottom:90px;

  z-index:5;
}

.controls-haas button{
  position:relative;

  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(
    145deg,
    #ffffff,
    #000000
  );

  color:#dc0000;

  font-weight:800;
  font-size:.95rem;

  letter-spacing:1px;

  cursor:pointer;

  overflow:hidden;

  transition:.35s;
}

.controls-haas button::before{
  content:"";

  position:absolute;
  top:0;
  left:-120%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.6),
    transparent
  );

  transition:.6s;
