.controls-haas button:hover::before{
  left:120%;
}

.controls-haas button:hover{
  transform:
  translateY(-6px)
  scale(1.05);

  box-shadow:
  0 10px 30px rgba(250,250,250,.35);
}

/* ===== INFOS ===== */

.car-info-haas{
  position:relative;

  width:100%;
  max-width:1200px;

  margin:auto;

  z-index:5;
}

.car-info-haas h2{
  text-align:center;

  font-size:clamp(2rem,5vw,3.5rem);

  margin-bottom:50px;

  font-weight:900;

  color:#fff;
}

/* ===== GRID ===== */

.info-grid-haas{
