  gap:25px;
}

/* ===== CARDS ===== */

.info-card-haas{
  position:relative;

  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.06),
    rgba(255,255,255,.02)
  );

  border:
  1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  overflow:hidden;

  transition:.45s;
}

.info-card-haas::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    140deg,
    rgba(255,255,255,.08),
    transparent 40%
  );

  opacity:0;

  transition:.4s;
}

.info-card-haas:hover::before{
  opacity:1;
}

.info-card-haas:hover{
  transform:translateY(-12px);

  border-color:
  rgba(200,10,1,.35);

  box-shadow:
    0 15px 40px rgba(0,0,0,.45),
    0 0 25px rgba(200,10,1,.12);
}

.info-card-haas span{
  display:block;

  margin-bottom:14px;

  color:#d00;

  text-transform:uppercase;

  letter-spacing:2px;

  font-size:.8rem;

  font-weight:700;
}

.info-card-haas h3{
  color:#fff;

  font-size:1.1rem;

  line-height:1.7;

  font-weight:600;
}

/* ===== ANIMAÇÕES ===== */

@keyframes rotateCirclehaas{

  from{
    transform:rotate(0deg);
  }

  to{
    transform:rotate(360deg);
  }

}

@keyframes floatCarhaas{

  0%,100%{
    transform:translateY(0px);
  }

  50%{
    transform:translateY(-15px);
  }

}

@keyframes rotateCarhaas{

  0%,100%{
    rotate:y 0deg;
  }

  50%{
    rotate:y 10deg;
  }

}

@keyframes pulseFloorhaas{

  0%,100%{
    transform:scale(.95);
    opacity:.5;
  }

  50%{
    transform:scale(1.05);
    opacity:1;
  }

}

@keyframes glowhaas{

  0%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(80px,40px);
  }

  100%{
    transform:translate(0,0);
  }

}

