    max-width:340px;
  }

  .controls-haas{
    gap:10px;
  }

  .controls-haas button{
    padding:12px 16px;
    font-size:.8rem;
  }

  .info-card-haas{
    padding:28px 22px;
  }

}


.eras-haas{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
    radial-gradient(circle at top,
    #ffffff 0%,
    #f9f9f9 35%,
    #000000 70%,
    #dc0000 100%);

    overflow:hidden;

    color:#dc0000;
}

/* GLOW FUNDO */
.eras-haas::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(250,255,255,.18),
    transparent 70%);

    filter:blur(40px);

    animation:haasGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-haas::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(255,255,255,.08),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-haas > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-eras-haas{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #000000);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(250,255,255,.25);
}

/* ===== TEXTO ===== */
#textoEra-haas{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#dc0000;

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-haas{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-haas button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #021816,
    #dc0000);

    color:#ffffff;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(225,255,228,.12);
}

/* brilho botão */
.botoes-eras-haas button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-haas button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-haas button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #000000,
    #ffffff);

    color:#d00;

    box-shadow:
    0 0 30px rgba(250,255,200,.35);
}

/* BOTÃO ATIVO */
.botoes-eras-haas .ativo{
    background:
    linear-gradient(
    145deg,
    #ffffff,
    #dc0000);

    color:#001b19;

    box-shadow:
    0 0 30px rgba(255,255,228,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#haas-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.haas-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(225,255,228,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.haas-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.haas-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.haas-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(225,255,228,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(255,255,200,.18);
}

/* ===== IMAGEM ===== */
.haas-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.haas-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(255,255,200,.28));
}

/* ===== ANO ===== */
.haas-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#d00;

    text-shadow:
    0 0 12px rgba(205,255,228,.3);
}

/* ===== TEXTO ===== */
#haas-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#eafffb;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes haasGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-haas{
        padding:90px 18px;
    }

    .titulo-eras-haas{
        font-size:2.5rem;
    }

    #textoEra-haas{
        font-size:1rem;
    }

    .botoes-eras-haas{
        gap:10px;
    }

    .botoes-eras-haas button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #haas-timeline{
        grid-template-columns:1fr;
    }

    .haas-timeline-item{
        max-width:360px;
        margin:auto;
    }

}

.footer-f1-haas{
  background:
  linear-gradient(
    135deg,
    #ffffff,
    #000000,
    #f1f1f1
  );

  color:#ffffff;

  padding:70px 25px;

  text-align:center;

  position:relative;

  overflow:hidden;
}

/* brilho fundo */
.footer-f1-haas::before{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  top:-200px;
  left:-200px;

  background:
  radial-gradient(
    circle,
    rgba(250,255,210,0.18),
    transparent 70%
  );

  filter:blur(40px);

  animation:haasFooterGlow 7s ease-in-out infinite;
}

/* brilho extra */
.footer-f1-haas::after{
  content:"";

  position:absolute;

  right:-180px;
  bottom:-180px;

  width:420px;
  height:420px;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,0.08),
    transparent 70%
  );

  filter:blur(50px);
}

/* conteúdo */
.footer-f1-haas > *{
  position:relative;
  z-index:2;
}

/* BRAND */
.footer-brand-haas p{
  font-size:34px;

  font-weight:900;

  letter-spacing:3px;

  color:#ffffff;

  margin-bottom:8px;

  text-shadow:
  0 0 15px rgba(250,255,210,.45);
}

.footer-brand-haas span{
  font-size:20px;

  color:#dc0000;

  opacity:.9;
}

/* LINKS */
.footer-links-haas,
.footer-social-haas{
  margin-top:28px;

  display:flex;

  justify-content:center;

  flex-wrap:wrap;

  gap:18px;
}

.footer-links-haas a,
.footer-social-haas a{
  position:relative;

  color:#dc0000;

  text-decoration:none;

  font-weight:700;

  font-size:16px;

  padding:10px 14px;

  border-radius:12px;

  transition:.35s ease;
}

/* underline glow */
.footer-links-haas a::after,
.footer-social-haas a::after{
  content:"";

  position:absolute;

  left:50%;
  bottom:0;

  width:0%;
  height:2px;

  background:#ffffff;

  transition:.35s ease;

  transform:translateX(-50%);
}

/* hover */
.footer-links-haas a:hover,
.footer-social-haas a:hover{
  color:#ffffff;

  background:
  rgba(255,255,255,.06);

  text-shadow:
  0 0 12px rgba(250,255,210,.4);
}

.footer-links-haas a:hover::after,
.footer-social-haas a:hover::after{
  width:80%;
}

/* COPYRIGHT */
.footer-copy-haas{
  margin-top:35px;

  font-size:14px;

  color:#ffffff;

  opacity:.8;

  letter-spacing:.5px;
}



/* animação glow */
@keyframes haasFooterGlow{

  0%,100%{
    transform:translate(0,0) scale(1);
  }

  50%{
    transform:translate(50px,30px) scale(1.1);
  }

}

/* RESPONSIVO */
@media(max-width:768px){

  .footer-f1-haas{
    padding:60px 18px;
  }

  .footer-brand-haas p{
    font-size:26px;
  }

  .footer-brand-haas span{
    font-size:16px;
  }

  .footer-links-haas,
  .footer-social-haas{
    gap:10px;
  }

  .footer-links-haas a,
  .footer-social-haas a{
    font-size:14px;
    padding:8px 10px;
  }
  }
  
  
 

