.tabela-audi{
    padding:clamp(80px, 12vw, 140px) 20px;

    background:
    linear-gradient(
      120deg,
      #111111 0%,
      #1a1a1a 20%,
      #2b2b2b 45%,
      #3a3a3a 65%,
      #5a0000 82%,
      #a30000 100%
    );

    color:#fff;

    position:relative;
    overflow:hidden;
}

/* EFEITO DE FUNDO */
.tabela-audi::before{
    content:"AUDI";

    position:absolute;
    top:50%;
    left:50%;

    transform:translate(-50%,-50%);

    font-size:14vw;
    font-weight:900;
    letter-spacing:10px;

    color:rgba(255,255,255,.03);

    pointer-events:none;
}

/* ===== TÍTULO ===== */
.titulo-tabela-audi{
    position:relative;
    z-index:2;

    text-align:center;

    font-size:clamp(28px, 4vw, 46px);

    margin-bottom:60px;

    display:flex;
    justify-content:center;
    align-items:center;
    gap:12px;

    color:#ffffff;

    text-shadow:
      0 0 18px rgba(255,0,0,.35);
}

/* LOGO */
.logo-titulo-auudi{
    width:clamp(28px, 4vw, 46px);

    filter:drop-shadow(
      0 0 12px rgba(255,0,0,.6)
    );

    transition:.3s ease;
}

.titulo-tabela-audi:hover .logo-titulo-auudi{
    transform:scale(1.15);
}

/* ===== BOX ===== */
.box-tabela-audi{
    position:relative;
    z-index:2;

    width:90%;
    max-width:1500px;

    margin:auto;

    background:rgba(0,0,0,0.72);

    border-radius:20px;

    backdrop-filter:blur(8px);

    border:1px solid rgba(255,255,255,.08);

    box-shadow:
      0 0 40px rgba(255,0,0,0.15),
      inset 0 0 30px rgba(255,255,255,0.03);
}

/* ===== TABELA ===== */
.box-tabela-audi table{
    width:100%;

    border-collapse:collapse;

    min-width:600px;
}

/* ===== LINHAS ===== */
.box-tabela-audi tr{
    transition:.3s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-audi td{
    padding:clamp(18px, 2.5vw, 28px);

    font-size:clamp(15px, 2vw, 20px);

    border-bottom:
      1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-audi td:first-child{
    color:#ff4d4d;

    font-weight:bold;

    width:50%;

    text-shadow:
      0 0 10px rgba(255,0,0,.25);
}

/* SEGUNDA COLUNA */
.box-tabela-audi td:last-child{
    text-align:right;

    color:#f1f1f1;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-audi tr:hover{
    background:
    linear-gradient(
      90deg,
      rgba(255,0,0,0.16),
      rgba(255,255,255,0.05)
    );

    transform:scale(1.01);

    box-shadow:
      inset 0 0 18px rgba(255,0,0,.12);
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .box-tabela-audi{
    width:95%;
    overflow:hidden;
  }

  .box-tabela-audi table{
    width:100%;
    min-width:100%;
  }

  .box-tabela-audi td{
    padding:10px 8px;
    font-size:18px;
  }

  .box-tabela-audi td:first-child{
    width:45%;
    font-size:16px;
  }

  .box-tabela-audi td:last-child{
    width:55%;
    font-size:18px;

    text-align:right;

    word-break:break-word;
  }

  .titulo-tabela-audi{
    font-size:22px;
  }

  .tabela-audi::before{
    font-size:22vw;
  }

}


/* =====================================
   TEMPORADA audi 2026
===================================== */

.temporada-audi{

    position:relative;

    overflow:hidden;

    padding:80px 20px;

