}



/* =====================================
   CARD POSIÇÃO
===================================== */


.card-campeonato-audi,
.card-pontos-audi,
.card-grafico-audi{


    background:

    linear-gradient(
        145deg,
        #161616,
        #202020
    );


    border-radius:25px;


    border:

    1px solid
    rgba(176,0,0,.2);


    box-shadow:

    0 15px 35px
    rgba(0,0,0,.35);


}



/* posição */

.card-campeonato-audi,
.card-pontos-audi{


    padding:30px 20px;

    text-align:center;

}



.valor-posicao-audi{

    font-size:70px;

    font-weight:900;

    color:#b00000;


    text-shadow:

    0 0 20px
