   PONTOS
===================================== */


#pontosaudi{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-audi{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-audi svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficoaudi{


    stroke:#b00000;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(176,0,0,.8)
    );


}

/* =====================================
   DESEMPENHO audi
===================================== */

.desempenho-audi{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-audi > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(176,0,0,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-audi > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(176,0,0,.55);



    box-shadow:

    0 0 25px
    rgba(176,0,0,.25);


}



/* números */

.desempenho-audi span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#b00000;



    text-shadow:

    0 0 15px
    rgba(176,0,0,.45);


}



/* textos */

.desempenho-audi p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-audi span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(176,0,0,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(176,0,0,.75);

    }


}



/* =====================================
   DESTAQUE audi
===================================== */


.card-campeonato-audi::before,
.card-pontos-audi::before,
.card-grafico-audi::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(176,0,0,.12),
