/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.audi-bar-left{

    border-radius:999px 0 0 999px;

}


.audi-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #000000,
        #808080
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.audi-bar-right{

    border-radius:0 999px 999px 0;

}


.audi-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #808080,
        #000000
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.audi-value{

    animation:
    audiValueShow .5s ease;

}


@keyframes audiValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


