.lideranca-audi{
  padding:80px 20px;

  background:
  linear-gradient(
    120deg,
    #111111 0%,
    #1a1a1a 25%,
    #2b2b2b 50%,
    #3a0000 75%,
    #8b0000 100%
  );

  text-align:center;
}

/* ===== TÍTULO ===== */
.titulo-lideranca-audi{
  font-size:38px;

  color:#f5f5f5;

  margin-bottom:60px;

  position:relative;

  letter-spacing:1px;
}

.titulo-lideranca-audi::after{
  content:"";

  width:180px;
  height:3px;

  background:
  linear-gradient(
    90deg,
    transparent,
    #ff2a2a,
    transparent
  );

  display:block;

  margin:15px auto 0;

  box-shadow:
  0 0 12px #ff2a2a;
}

/* ===== CONTAINER ===== */
.container-lideranca-audi{
  display:flex;

  justify-content:center;

  gap:30px;

  flex-wrap:wrap;
}

/* ===== CARD ===== */
.card-lider-audi{
  background:
  linear-gradient(
    145deg,
    #111111,
    #2a2a2a
  );

  width:260px;

  border-radius:20px;

  padding:24px;

  color:#fff;

  transition:.4s ease;

  border:
  3px solid rgba(255,0,0,.22);

  position:relative;

  overflow:hidden;
}

/* glow topo */
.card-lider-audi::before{
  content:"";

  position:absolute;

  top:0;
  left:0;

  width:100%;
  height:3px;

  background:
  linear-gradient(
    90deg,
    transparent,
    #ff2a2a,
    transparent
  );
}

/* reflexo */
.card-lider-audi::after{
  content:"";

  position:absolute;

  top:0;
  left:-100%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,0,0,.16),
    transparent
  );

  transition:.6s;
}

.card-lider-audi:hover::after{
  left:100%;
}

/* ===== IMAGEM ===== */
.card-lider-audi img{
  width:100%;
  height:260px;

  object-fit:cover;
  object-position:top;

  border-radius:15px;

  margin-bottom:15px;

  filter:brightness(.95);

  transition:.4s;
}

/* ===== NOME ===== */
.card-lider-audi h3{
  margin:10px 0 5px;

  font-size:20px;

  color:#ffffff;
}

/* ===== CARGO ===== */
.card-lider-audi span{
  display:block;

  color:#ff4d4d;

  font-weight:bold;

  margin-bottom:10px;

  font-size:20px;

  letter-spacing:.5px;
}

/* ===== TEXTO ===== */
.card-lider-audi p{
  color:#f1f1f1;

  line-height:1.5;

  font-size:20px;

  border-left:
  3px solid #ff2a2a;

  padding-left:10px;

  text-shadow:
  0 0 6px rgba(255,255,255,.12);

  transition:.3s;
}

.card-lider-audi:hover p{
  transform:translateY(-2px);

  color:#ffffff;
}

/* ===== HOVER ===== */
.card-lider-audi:hover{
  transform:
  translateY(-12px)
  scale(1.02);

  box-shadow:
  0 15px 40px rgba(255,0,0,.22);
}

.card-lider-audi:hover img{
  transform:scale(1.05);

  filter:brightness(1);
}

/* ===== RESPONSIVO ===== */
