/* =========================================
   NÚMEROS AUDI
========================================= */

/* ==========================================
   ESTATÍSTICAS audi
========================================== */

.numeros-audi{

    position:relative;

    min-height:600px;

    padding:40px 0;

    overflow:hidden;

    background:
    linear-gradient(
        135deg,
        #dc0000 0%,
        #121212 45%,
        #888888 120%
    );

}


/* IMAGEM DE FUNDO */

.bg-numeros-audi{

    position:absolute;

    inset:0;

    width:100%;
    height:100%;

    object-fit:cover;

    filter:
    brightness(.35)
    blur(4px);

    transform:scale(1.1);

    z-index:0;

}



.numeros-audi::before{

    content:"";

    position:absolute;

    inset:0;

    background:

    radial-gradient(
        circle at center,
        transparent 20%,
        rgba(200,200,200,.85)
    );

    z-index:1;

}



/* TITULO */

.titulo-numeros-audi{

    position:relative;

    z-index:2;

    text-align:center;

    color:#888888;

    font-size:clamp(32px,5vw,55px);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:25px;

    text-shadow:

    0 0 15px #888888;

}



/* GRID */

.stats-grid-audi{

    position:relative;

    z-index:2;


    max-width:1200px;

    margin:auto;

    padding:0 35px;


    display:grid;

    grid-template-columns:
    repeat(3,1fr);


    gap:15px;

}



/* CARDS */

.card-stat-audi{

    position:relative;


    background:

    linear-gradient(
        145deg,
        rgba(10,10,10,.08),
        rgba(255,255,255,.25)
    );




    border-radius:22px;


    padding:18px;


    text-align:center;


    color:white;


    border:

    1px solid
    rgba(10,10,10,.5);



    box-shadow:

    0 15px 40px
    rgba(200,200,200,.7);



    overflow:hidden;



    opacity:0;

    transform:
    translateY(50px);



    transition:.6s ease;

}



/* LINHA LARANJA */

.card-stat-audi::before{

    content:"";

    position:absolute;

    top:0;

    left:0;

    width:100%;

    height:4px;


    background:

    linear-gradient(
        90deg,
        transparent,
        #888888,
        transparent
    );

}



/* ATIVO */

.card-stat-audi.ativo{

    opacity:1;

    transform:
    translateY(0);


    animation:

    brilhoaudi 2.5s infinite alternate;

}



@keyframes brilhoaudi{

    from{

        box-shadow:

        0 0 15px
        rgba(10,10,10,.3);

    }


    to{

        box-shadow:

        0 0 35px
        rgba(10,10,10,.8);

    }

}



/* NUMEROS */

.card-stat-audi span{

    display:block;


    font-size:

    clamp(32px,4vw,55px);


    font-weight:900;


    color:#dc0000;


    text-shadow:

    0 0 15px #888888;

}



/* TEXTO */

.card-stat-audi p{

    margin-top:15px;


    font-size:

    clamp(18px,2vw,28px);


    font-weight:bold;


    color:white;

}



/* CARD GRANDE */

.grande-audi{

    grid-column:

    1 / -1;

}



/* BARRA */

.barra-velocidade-audi{


    width:0%;


    height:8px;


    margin-top:20px;


    border-radius:20px;


    background:

    linear-gradient(
        90deg,
        #888888,
        #121212
    );


    box-shadow:

    0 0 15px #888888;


    transition:

    width .3s ease;

}



/* HOVER */

.card-stat-audi:hover{


    transform:

    translateY(-10px)
    scale(1.03);



    border-color:#888888;


}



/* ==========================================
   MOBILE
========================================== */


@media(max-width:768px){


.stats-grid-audi{


    grid-template-columns:1fr;


    padding:0 15px;


    gap:20px;

}



.grande-audi{


    grid-column:1;

}



.card-stat-audi{


    padding:25px;

}



.card-stat-audi span{


    font-size:50px;

}


}






/* =========================================
   HALL AUDI
========================================= */

.hall-audi{
padding:120px 40px;

position:relative;

background:
linear-gradient(
120deg,
#0a0a0a 20%,
#1a1a1a 55%,
#c70000 140%
);

min-height:auto;
height:auto;

overflow:hidden;
}

/* ===== TÍTULO ===== */

.titulo-hall-audi{
text-align:center;

font-size:52px;

color:#ffffff;

margin-bottom:80px;

text-shadow:
0 0 12px rgba(199,0,0,.7);
}

/* ===== GRID ===== */

.hall-grid-audi{
display:flex;

justify-content:center;
align-items:flex-start;

flex-wrap:wrap;

perspective:1200px;

gap:40px;

position:relative;

z-index:3;
}

/* ===== FUNDO ===== */

.bg-hall-audi{
position:absolute;
inset:0;
z-index:0;
}

.bg-layer-audi{
position:absolute;
inset:0;

background-size:cover;
background-position:center center;
background-repeat:no-repeat;

transform:scale(1);

opacity:0;

transition:opacity .8s ease;
}

.bg-layer-audi.active{
opacity:1;
}

.hall-grid-audi,
.titulo-hall-audi,
.hall-overlay-audi{
position:relative;
z-index:2;
}

/* ===== SHOWCASE ===== */

.hall-audi.showcase .hall-card-audi{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

.hall-audi.showcase .bg-layer-audi.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.15)
saturate(1.2);

transition:1s ease;
}

/* ===== CARD ===== */

.hall-card-audi{
position:relative;

width:320px;

padding:30px;

border-radius:24px;

background:
linear-gradient(
180deg,
rgba(15,15,15,.35),
rgba(0,0,0,.82)
);

border:
1px solid rgba(199,0,0,.25);

overflow:hidden;

transition:.45s ease;

box-shadow:
0 15px 35px rgba(0,0,0,.45);

text-align:center;

backdrop-filter:blur(2px);

transform-origin:center top;
}

/* ===== GLOW TOPO ===== */

.hall-card-audi::before{
content:"";

position:absolute;

top:0;
left:0;

width:100%;
height:3px;

background:
linear-gradient(
90deg,
transparent,
#c70000,
transparent
);
}

/* ===== REFLEXO ===== */

.hall-card-audi::after{
content:"";

position:absolute;

top:0;
left:-100%;

width:100%;
height:100%;

background:
linear-gradient(
120deg,
transparent,
rgba(199,0,0,.18),
transparent
);

transition:.6s;
}

.hall-card-audi:hover::after{
left:100%;
}

/* ===== HOVER ===== */

.hall-card-audi:hover{
transform:
translateY(-14px)
scale(1.04);

background:
rgba(12,12,12,.96);

box-shadow:
0 25px 60px rgba(0,0,0,.7),
0 0 30px rgba(199,0,0,.25);

z-index:10;
}

.hall-grid-audi:hover .hall-card-audi{
opacity:.35;

transform:scale(.98);
}

.hall-card-audi:hover{
opacity:1 !important;

transform:
translateY(-14px)
scale(1.06);
}

/* ===== NÚMERO ===== */

.numero-hall-audi{
position:absolute;

top:15px;
right:20px;

font-size:70px;

font-weight:900;

color:rgba(199,0,0,.08);
}

/* ===== FOTO ===== */

.hall-card-audi img{
width:170px;
height:200px;

object-fit:cover;

border-radius:50%;

border:
3px solid #c70000;

margin-bottom:20px;

filter:
grayscale(100%)
brightness(.9);

transition:.5s ease;
}

.hall-card-audi:hover img{
filter:
grayscale(0%)
brightness(1.1);

transform:scale(1.1);
}

/* ===== CONTEÚDO ===== */

.hall-card-audi p,
.hall-stats-audi,
.frase-hall-audi{
opacity:0;

transform:translateY(10px);

max-height:0;

overflow:hidden;

transition:.4s ease;
}

.hall-card-audi:hover p,
.hall-card-audi:hover .hall-stats-audi,
.hall-card-audi:hover .frase-hall-audi{
opacity:1;

transform:translateY(0);

max-height:200px;
}

/* ===== NOME ===== */

.hall-card-audi h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}

/* ===== PAÍS ===== */

.pais-hall-audi{
display:block;

font-size:18px;

color:#ff8a8a;

margin-bottom:18px;
}

/* ===== TEXTO ===== */

.hall-card-audi p{
font-size:18px;

color:#ddd;

margin-bottom:22px;
}

/* ===== STATS ===== */

.hall-stats-audi{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#ff8a8a;
}

/* ===== FRASE ===== */

.frase-hall-audi{
font-size:14px;

font-style:italic;

color:#fff;

line-height:1.6;
}

/* =========================
   TABLET
========================= */

@media (max-width:1024px){

.hall-audi{
padding:100px 25px;
}

.titulo-hall-audi{
font-size:42px;
margin-bottom:60px;
}

.hall-grid-audi{
gap:30px;
}

.hall-card-audi{
width:260px;
padding:25px;
}

.hall-card-audi h3{
font-size:26px;
}

.hall-card-audi p{
font-size:15px;
}

.pais-hall-audi{
font-size:15px;
}

.hall-stats-audi{
font-size:13px;
}

.frase-hall-audi{
font-size:13px;
}

.hall-card-audi img{
width:130px;
height:130px;
}

}

/* =========================
   MOBILE
========================= */

@media (max-width:768px){

.hall-audi{
padding:80px 15px;
}

.titulo-hall-audi{
font-size:30px;
margin-bottom:40px;
}

/* GRID */

.hall-grid-audi{
