transform:none;
}

.hall-card-audi:hover{
transform:
translateY(-8px)
scale(1.02);
}

/* TEXTO */

.hall-card-audi h3{
font-size:22px;
}

.pais-hall-audi{
font-size:14px;
}

.hall-card-audi p{
font-size:14px;
}

