}

/* FUNDO */

.bg-layer-audi{
background-size:400px;

background-repeat:repeat;
}

.bg-layer-audi::after{
content:"";

position:absolute;
inset:0;

background:
rgba(0,0,0,.55);
}

/* ACTIVE */

.hall-card-audi{
