transition:.4s ease;
}

.hall-grid-audi.active .hall-card-audi{
opacity:.2;

transform:scale(.95);
}

.hall-card-audi.active{
opacity:1 !important;

transform:scale(1.05);

z-index:10;
}

}


/* =========================================
   SAUBER / ALFA ROMEO / KICK EVOLUTION
========================================= */

.audi-evolution{
  position:relative;

  width:100%;

  padding:120px 25px;

  overflow:hidden;

 background:
 linear-gradient(
  120deg,
  #111111 0%,
  #1d1d1d 25%,
  #2f2f2f 55%,
  #4a0000 82%,
  #9e0000 120%
);

  font-size:initial;

  transition:background 1s ease;
}

/* ===== FUNDOS ===== */

/* SAUBER 2000 */
.audi-evolution.bg-2000{
  background:
  radial-gradient(
    circle at top,
    #0057b8 0%,
    #002b5a 45%,
    #050505 100%
  );
}

/* ALFA ROMEO 2010 */
.audi-evolution.bg-2010{
  background:
  radial-gradient(
    circle at top,
    #a80000 0%,
    #4a0000 45%,
    #050505 100%
  );
}

/* KICK 2020 */
.audi-evolution.bg-2020{
  background:
  radial-gradient(
    circle at top,
    #39ff14 0%,
    #0d3b0d 45%,
    #050505 100%
  );
}

/* ===== BRILHOS ===== */

.audi-evolution::before{
  content:"";

  position:absolute;

  top:-220px;
  left:-220px;

  width:520px;
  height:520px;

  background:
  radial-gradient(
    circle,
    rgba(150,150,150,.18),
    transparent 70%
  );

  filter:blur(35px);

  animation:glowAudi 8s linear infinite;
}

.audi-evolution::after{
  content:"";

  position:absolute;

  right:-180px;
  bottom:-180px;

  width:420px;
  height:420px;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,.06),
    transparent 70%
  );

  filter:blur(50px);
}

/* ===== TÍTULO ===== */

.title-audi{
  position:relative;

  font-size:clamp(2.5rem,6vw,5rem);

  text-align:center;

  margin-bottom:80px;

  font-weight:900;

  letter-spacing:3px;

  text-transform:uppercase;

  background:
  linear-gradient(
    90deg,
    #333333,
    #dc0000
  );

  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;

  z-index:5;
}

/* ===== ÁREA CARRO ===== */

.car-container-audi{
  position:relative;

  width:100%;
  max-width:900px;

  height:500px;

  margin:auto;

  display:flex;
  align-items:center;
  justify-content:center;

  perspective:1800px;

  z-index:2;
}

/* ===== BASE ===== */

.car-container-audi::before{
  content:"";

  position:absolute;

  bottom:50px;

  width:70%;
  height:40px;

  background:
  radial-gradient(
    circle,
    rgba(150,155,150,.35),
    transparent 70%
  );

  filter:blur(20px);

  border-radius:50%;

  animation:pulseFloorAudi 4s ease-in-out infinite;
}

/* ===== CÍRCULO ===== */

.car-circle-audi{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:
  2px solid rgba(150,150,150,.18);

  box-shadow:
  0 0 40px rgba(150,155,150,.15),
  inset 0 0 40px rgba(150,155,150,.08);

  animation:rotateCircleAudi 14s linear infinite;
}

.car-circle-audi::before{
  content:"";

  position:absolute;

  inset:20px;

  border-radius:50%;

  border:
  1px dashed rgba(255,255,255,.08);
}

/* ===== CARRO ===== */

.car-container-audi img{
  position:relative;

  width:100%;
  max-width:650px;

  object-fit:contain;

  z-index:5;

  filter:
  drop-shadow(
    0 30px 35px rgba(0,0,0,.6)
  );

  animation:
  floatCarAudi 5s ease-in-out infinite,
  rotateCarAudi 6s ease-in-out infinite;

  transition:
  opacity .45s ease,
  transform .45s ease;
}

/* ===== BOTÕES ===== */

.controls-audi{
  position:relative;

  display:flex;

  flex-wrap:wrap;
  justify-content:center;

  gap:16px;

  margin-top:40px;
  margin-bottom:90px;

  z-index:5;
}

.controls-audi button{
  position:relative;

  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(
    145deg,
    #333333,
    #dc0000
  );

  color:#02140f;

  font-weight:800;

  font-size:.95rem;

  letter-spacing:1px;

  cursor:pointer;

  overflow:hidden;

  transition:.35s;
}

.controls-audi button::before{
  content:"";

  position:absolute;

  top:0;
  left:-120%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.6),
    transparent
  );

  transition:.6s;
}

.controls-audi button:hover::before{
  left:120%;
}

.controls-audi button:hover{
  transform:
  translateY(-6px)
  scale(1.05);

  box-shadow:
  0 10px 30px rgba(150,155,150,.35);
}

/* ===== INFOS ===== */

.car-info-audi{
  position:relative;

  width:100%;
  max-width:1200px;

  margin:auto;

  z-index:5;
}

.car-info-audi h2{
  text-align:center;

  font-size:clamp(2rem,5vw,3.5rem);

  margin-bottom:50px;

  font-weight:900;

  color:#fff;
}

/* ===== GRID ===== */

.info-grid-audi{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));

  gap:25px;
}

/* ===== CARDS ===== */

.info-card-audi{
  position:relative;

  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.06),
    rgba(255,255,255,.02)
  );

  border:
  1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  overflow:hidden;

  transition:.45s;
}

.info-card-audi::before{
  content:"";

  position:absolute;

  inset:0;

  background:
  linear-gradient(
    140deg,
    rgba(255,255,255,.08),
    transparent 40%
  );

  opacity:0;

  transition:.4s;
}

.info-card-audi:hover::before{
  opacity:1;
}

.info-card-audi:hover{
  transform:translateY(-12px);

  border-color:
  rgba(157,150,150,.35);

  box-shadow:
  0 15px 40px rgba(0,0,0,.45),
  0 0 25px rgba(150,155,150,.12);
}

.info-card-audi span{
  display:block;

  margin-bottom:14px;

  color:#dc0000;

  text-transform:uppercase;

  letter-spacing:2px;

  font-size:.8rem;

  font-weight:700;
}

.info-card-audi h3{
  color:#fff;

  font-size:1.1rem;

  line-height:1.7;

  font-weight:600;
}

/* ===== ANIMAÇÕES ===== */

@keyframes rotateCircleAudi{

  from{
    transform:rotate(0deg);
  }

  to{
    transform:rotate(360deg);
  }

}

@keyframes floatCarAudi{

  0%,100%{
    transform:translateY(0px);
  }

  50%{
    transform:translateY(-15px);
  }

}

@keyframes rotateCarAudi{

  0%,100%{
    rotate:y 0deg;
  }

  50%{
    rotate:y 10deg;
  }

}

@keyframes pulseFloorAudi{

  0%,100%{
    transform:scale(.95);
    opacity:.5;
  }

  50%{
    transform:scale(1.05);
    opacity:1;
  }

}

@keyframes glowAudi{

  0%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(80px,40px);
  }

  100%{
    transform:translate(0,0);
  }

}

/* ===== RESPONSIVO ===== */

@media(max-width:768px){

  .audi-evolution{
    padding:90px 18px;
  }

  .car-container-audi{
    height:320px;
  }

  .car-circle-audi{
    width:250px;
    height:250px;
  }

  .car-container-audi img{
    max-width:340px;
  }

  .controls-audi{
    gap:10px;
  }

  .controls-audi button{
    padding:12px 16px;

    font-size:.8rem;
  }

  .info-card-audi{
    padding:28px 22px;
  }

}


.eras-audi{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
 linear-gradient(
  120deg,
  #111111 0%,
  #1d1d1d 25%,
  #2f2f2f 55%,
  #4a0000 82%,
  #9e0000 120%
);

    overflow:hidden;

    color:#fff5f5;
}

/* GLOW FUNDO */
.eras-audi::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(255,40,40,.18),
    transparent 70%);

    filter:blur(40px);

    animation:audiGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-audi::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(255,255,255,.08),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-audi > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */

.titulo-eras-audi{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #ff9d9d);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(255,60,60,.25);
}

/* ===== TEXTO ===== */

#textoEra-audi{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#ffe6e6;

    opacity:.92;
}

/* ===== BOTÕES ===== */

.botoes-eras-audi{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-audi button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #1a0000,
    #3a0000);

    color:#ffb3b3;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(255,120,120,.12);
}

/* brilho botão */
.botoes-eras-audi button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-audi button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-audi button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #ff2e2e,
    #a80000);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(255,40,40,.35);
}

/* BOTÃO ATIVO */

.botoes-eras-audi .ativo{
    background:
    linear-gradient(
    145deg,
    #ffb3b3,
    #ff3b3b);

    color:#240000;

    box-shadow:
    0 0 30px rgba(255,120,120,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */

#audi-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */

.audi-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.08),
    rgba(255,255,255,.03));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(255,120,120,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.audi-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.12),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.audi-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */

.audi-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(255,120,120,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(255,50,50,.18);
}

/* ===== IMAGEM ===== */

.audi-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.audi-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(255,50,50,.28));
}

/* ===== ANO ===== */

.audi-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#ffb3b3;

    text-shadow:
    0 0 12px rgba(255,120,120,.3);
}

/* ===== TEXTO ===== */

#audi-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#fff0f0;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */

@keyframes audiGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}


@media(max-width:768px){

    .eras-audi{
        padding:90px 18px;
    }

    .titulo-eras-audi{
        font-size:2.5rem;
    }

    #textoEra-audi{
        font-size:1rem;
    }

    .botoes-eras-audi{
        gap:10px;
    }

    .botoes-eras-audi button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #audi-timeline{
        grid-template-columns:1fr;
    }

    .audi-timeline-item{
        max-width:360px;
        margin:auto;
    }

}


