 /*////////////////////////////////////////////
 ALPINE
 ///////////////////////////////////////////*/
 
body.alpine{
  background: #0090ff;
}

 

/*=========================================================
   alpine HERO
========================================================= */

.alpine-hero {
    position: relative;
    width: 100%;
    height: 100dvh;
    min-height: 620px;
    overflow: hidden;
    background: #020713;
    color: #fff;
    isolation: isolate;
}


/* =========================================================
   CARRO — FUNDO PRINCIPAL
========================================================= */

.alpine-car-bg {
    position: absolute;
    inset: -5%;
    z-index: -5;

    background-image:
        url("carros/a526.jpeg");

    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;

    filter:
        brightness(.58)
        contrast(1.08)
        saturate(1.12);

    transform: scale(1.04);

    transition:
        transform 1s ease,
        filter 1s ease;
}


/* LEVE MOVIMENTO */

.alpine-hero:hover .alpine-car-bg {
    transform: scale(1.07);

    filter:
        brightness(.63)
        contrast(1.1)
        saturate(1.15);
}


/* =========================================================
   OVERLAY
========================================================= */

.alpine-overlay {
    position: absolute;
    inset: 0;
    z-index: -4;

    background:

        /* AZUL */
        linear-gradient(
            115deg,
            rgba(0,144,255,.78),
            transparent 42%
        ),

        /* VERMELHO */
        linear-gradient(
            250deg,
            rgba(255,99,184,.32),
            transparent 42%
        ),

        /* ESCURECIMENTO */
        linear-gradient(
            to bottom,
            rgba(0,0,0,.55),
            transparent 25%,
            rgba(0,0,0,.08) 55%,
            rgba(0,0,0,.82) 100%
        );
}


/* =========================================================
   TOPO
========================================================= */

.alpine-top {
    position: absolute;

    top: 25px;
    left: 4vw;
    right: 4vw;

    z-index: 30;

    display: flex;
    align-items: center;
    justify-content: space-between;
}


/* =========================================================
   HOME
========================================================= */

.alpine-home {
    display: flex;
    align-items: center;

    gap: 8px;

    padding: 9px 13px;

    text-decoration: none;

    color: rgba(255,255,255,.75);

    border: 1px solid rgba(255,255,255,.2);

    background: rgba(0,0,0,.3);

    backdrop-filter: blur(10px);

    font-size: 25px;
    font-weight: 900;
    letter-spacing: 2px;

    transition: .35s ease;
}

.alpine-home i {
    font-size: 20px;
}

.alpine-home:hover {
    color: #fff;

    background: rgba(0,144,255,.22);

    border-color: #FF63B8;

    transform: translateY(-3px);
}


/* =========================================================
   STATUS
========================================================= */

.alpine-status {
    position: absolute;

    left: 50%;

    transform: translateX(-50%);

    font-size: 15px;
    font-weight: 900;
    letter-spacing: 4px;

    color: rgba(255,255,255,.55);
}


/* =========================================================
   alpine — REDES SOCIAIS INFERIORES
========================================================= */

.alpine-social-top {
    position: absolute;

    z-index: 30;

    left: 50%;
    bottom:110px;

    transform: translateX(-13%);

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 7px;
}


/* =========================================================
   ÍCONES
========================================================= */

.alpine-social-top a {
    width: 100px;
    height: 100px;

    display: flex;
    align-items: center;
    justify-content: center;

    text-decoration: none;

    color: rgba(255,255,255,.65);

    border: 1px solid rgba(255,255,255,.16);

    background:
        linear-gradient(
            135deg,
            rgba(10,15,30,.78),
            rgba(0,0,0,.45)
        );

    backdrop-filter: blur(8px);

    font-size: 30px;

    transition:
        transform .35s ease,
        color .35s ease,
        background .35s ease,
        border-color .35s ease,
        box-shadow .35s ease;
}


/* =========================================================
   HOVER
========================================================= */

.alpine-social-top a:hover {
    color: #fff;

    background:#0090FF;

    border-color:#FF63B8 ;

    transform:
        translateY(-5px)
        scale(1.08);

    box-shadow:
        0 8px 22px rgba(255,99,184,.35),
        0 0 15px rgba(255,99,184,.15);
}


/* =========================================================
   LINHA DECORATIVA
========================================================= */

.alpine-social-top::before,
.alpine-social-top::after {
    content: "";

    width: 55px;
    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,99,184,.7)
        );
}


.alpine-social-top::after {
    background:
        linear-gradient(
            90deg,
            rgba(255,99,184,.7),
            transparent
        );
}


/* =========================================================
   LOGO alpine
========================================================= */

.alpine-logo {
    position: absolute;

    z-index: 8;

    right: 4vw;
    top: -50px;

    width: 300px;
    height: 300px;

    display: flex;
    align-items: center;
    justify-content: center;

    pointer-events: none;

    animation: alpine-logo-float 4s ease-in-out infinite;
}


