/* ===========================
   TOPBAR alpine
=========================== */

.topbar-alpine{

width:100%;
max-width:100%;
overflow:hidden;
	
	height:70px;

    display:grid;
    grid-template-columns:60px 1fr 60px;

    align-items:center;

    background:#0090ff;
    border-bottom:3px solid #000;

    padding:0 10px;

    box-sizing:border-box;

    position:sticky;
    top:0;
    z-index:9998;
}
/* ===========================
MENU
=========================== */
.menu-toggle-alpine{
    width:45px;
    height:45px;

    display:flex;
    align-items:center;
    justify-content:center;

    background:none;
    border:none;

    color:#e600c4;

    font-size:24px;

    cursor:pointer;

	border-radius:12px;
transition:.3s;
}

.menu-toggle-alpine{
    justify-self:start;
}

.menu-toggle-alpine:hover{

    transform:scale(1.15);

    color:#fff;

	background:rgba(0,27,68,.15);

}

