    display:flex;

    align-items:center;

    justify-content:center;

    gap:10px;

    color:#e600c4;

    font-size:22px;

    font-weight:800;

    overflow:hidden;

    white-space:nowrap;

}

.topbar-title-alpine img{

    width:34px;
    height:34px;

    object-fit:contain;

    filter:
        drop-shadow(0 0 8px rgba(0,27,68,.45));

