/* =========================================================
   PILOTOS alpine
========================================================= */

.pilotos-alpine {

    position: relative;

    width: 100%;
    height: 100dvh;
    min-height: 100dvh;

    overflow: hidden;

    box-sizing: border-box;

    padding: 45px 5vw;

    background:
        radial-gradient(
            circle at 50% 100%,
            rgba(255,99,184,.12),
            transparent 35%
        ),
        linear-gradient(
            120deg,
            #050505,
            #0b0b0b,
            #050505
        );

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.pilotos-titulo-alpine {

    position: relative;

    z-index: 20;

    text-align: center;

    margin-bottom: 25px;
}


.pilotos-titulo-alpine span {

    display: block;

    color: #0090ff;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 5px;
}


.pilotos-titulo-alpine h2 {

    margin: 4px 0;

    font-size: clamp(30px, 4vw, 52px);

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotos-titulo-alpine p {

    margin: 0;

    color: rgba(255,255,255,.62);

    font-size: 18px;
}


/* =========================================================
   ÁREA DOS PILOTOS
========================================================= */

.dupla-pilotos-alpine {

    position: relative;

    display: grid;

    grid-template-columns: 1fr 1fr;

    height: calc(100% - 125px);

    max-width: 1450px;

    margin: auto;
}


/* =========================================================
   PILOTO
========================================================= */

.piloto-alpine {

    position: relative;

    display: block;

    height: 100%;

    overflow: hidden;

    text-decoration: none;

    color: white;

    transition:
        transform .5s ease;
}


/* =========================================================
   BRILHO DE FUNDO
========================================================= */

.piloto-alpine::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: 15%;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255,99,184,.15),
            transparent 68%
        );

    filter: blur(30px);

    opacity: .35;

    transition:
        transform .7s ease,
        opacity .7s ease;

    pointer-events: none;
}


/* =========================================================
   BRILHO gasly
========================================================= */

.piloto-gasly-alpine::before {

    left: -220px;
}


/* =========================================================
   BRILHO franco
========================================================= */

.piloto-franco-alpine::before {

    right: -220px;
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.piloto-numero-bg-alpine {

    position: absolute;

    z-index: 0;

    top: 5%;

    font-size: clamp(200px, 40vw, 400px);

    font-weight: 900;

    line-height: 1;

    color: transparent;

    -webkit-text-stroke:
        1px rgba(255,255,255,.08);

    opacity: .8;

    transition:
        color .7s ease,
        -webkit-text-stroke .7s ease,
        transform .7s ease,
        opacity .7s ease;
}


/* =========================================================
   NÚMERO gasly
========================================================= */

.piloto-gasly-alpine
.piloto-numero-bg-alpine {

    left: -3%;
	    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   NÚMERO franco
========================================================= */

.piloto-franco-alpine
.piloto-numero-bg-alpine {

    right: -2%;

    font-size: clamp(150px, 21vw, 320px);

    letter-spacing: -8px;

    z-index: 1;
}


/* =========================================================
   FOTO
========================================================= */

.piloto-foto-alpine {

    position: absolute;

    z-index: 2;

    left: 50%;

    bottom: 0;

    width: 70%;

    height: 90%;

    transform:
        translateX(-50%);

    display: flex;

    align-items: flex-end;

    justify-content: center;

    pointer-events: none;
}


.piloto-foto-alpine img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center bottom;

    filter:
        grayscale(.35)
        brightness(.65);

    opacity: .72;

    transform:
        translateY(30px)
        scale(.95);

    transition:
        transform .8s cubic-bezier(.2,.8,.2,1),
        filter .7s ease,
        opacity .7s ease;
}


/* =========================================================
   POSIÇÃO DA FOTO DO franco
========================================================= */

.piloto-franco-alpine
.piloto-foto-alpine {

    transform:
        translateX(-60%);
}


/* =========================================================
   DADOS DO PILOTO
========================================================= */

.piloto-dados-alpine {

    position: absolute;

    z-index: 30;

    left: 7%;

    bottom: 9%;

    max-width: 80%;

    transition:
        transform .6s ease;
}

/* =========================================================
   DADOS DO franco
========================================================= */

.piloto-franco-alpine
.piloto-dados-alpine {

    left: auto;

    right: 7%;

    text-align: right;
}


/* =========================================================
   PAÍS
========================================================= */

.piloto-pais-alpine {

    display: block;

    margin-bottom: 8px;

    color: #0090ff;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 4px;
}


/* =========================================================
   HAMILTON — FUNDO DO NOME MAIS TRANSPARENTE
========================================================= */

.piloto-gasly-alpine
.piloto-dados-alpine h3::before {

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.70) 0%,
            rgba(0,0,0,.60) 45%,
            rgba(0,0,0,.30) 75%,
            transparent 100%
        );

    opacity: .75;

    filter: blur(7px);
}

/* =========================================================
   NOME
========================================================= */

.piloto-dados-alpine h3 {

    position: relative;

    display: inline-flex;

    flex-direction: column;

    align-items: flex-start;

    margin: 0;

    padding: 6px 14px 8px 0;

    z-index: 31;

    font-size: clamp(28px, 3vw, 42px);

    line-height: .9;

    font-weight: 900;

    color: #fff;

    text-shadow:
        0 3px 10px rgba(0,0,0,1),
        0 0 18px rgba(0,0,0,1);
}

/* =========================================================
   NOME franco — ALINHAMENTO
========================================================= */

.piloto-franco-alpine
.piloto-dados-alpine h3 {

    align-items: flex-end;

    padding-right: 0;

    padding-left: 14px;
}


/* =========================================================
   FUNDO DE PROTEÇÃO DO NOME
========================================================= */

.piloto-dados-alpine h3::before {

    content: "";

    position: absolute;

    z-index: -1;

    top: -12px;
    bottom: -12px;

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            90deg,
            rgba(0,0,0,.98) 0%,
            rgba(0,0,0,.92) 45%,
            rgba(0,0,0,.72) 70%,
            rgba(0,0,0,.15) 100%
        );

    filter: blur(6px);

    opacity: .95;

    pointer-events: none;

    transition:
        opacity .4s ease,
        transform .4s ease;
}


/* =========================================================
   PROTEÇÃO DO NOME — LADO DIREITO
========================================================= */

.piloto-franco-alpine
.piloto-dados-alpine h3::before {

    left: -35px;
    right: -35px;

    background:
        linear-gradient(
            270deg,
            rgba(0,0,0,.90) 0%,
            rgba(0,0,0,.90) 45%,
            rgba(0,0,0,.70) 70%,
            rgba(0,0,0,.10) 100%
        );
}


/* =========================================================
   PRIMEIRO NOME
========================================================= */

.piloto-dados-alpine h3 {

    color: #fff;
}


/* =========================================================
   SOBRENOME
========================================================= */

.piloto-dados-alpine h3 strong {

    position: relative;

    display: block;

    color: #fff;

    font-weight: 900;

    transition:
        color .35s ease,
        text-shadow .35s ease;
}


/* =========================================================
   LINHA
========================================================= */

.piloto-linha-alpine {

    width: 65px;

    height: 2px;

    margin: 15px 0;

    background: #0090ff;

    box-shadow:
        0 0 12px rgba(255,99,184,.7);

    transition:
        width .6s ease;
}


.piloto-franco-alpine
.piloto-linha-alpine {

    margin-left: auto;
}


/* =========================================================
   CATEGORIA
========================================================= */

.piloto-categoria-alpine {

    color: rgba(255,255,255,.98);

    font-size: 12px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* =========================================================
   AÇÃO
========================================================= */

.piloto-acao-alpine {

    position: absolute;

    z-index: 14;

    right: 7%;

    bottom: 10%;

    display: flex;

    align-items: center;

    gap: 12px;

    color: rgba(255,255,255,.4);

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    transition:
        color .4s ease,
        transform .5s ease;
}


/* =========================================================
   AÇÃO franco
========================================================= */

.piloto-franco-alpine
.piloto-acao-alpine {

    right: auto;

    left: 4%;
}


/* =========================================================
   ÍCONE
========================================================= */

.piloto-acao-alpine strong {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 28px;

    height: 28px;

    border: 1px solid rgba(255,99,184,.3);

    color: #0090ff;

    font-size: 12px;

    transition:
        background .4s ease,
        color .4s ease,
        transform .4s ease;
}



/* =========================================================
   CENTRO alpine
========================================================= */

.centro-alpine {

    position: absolute;

    z-index: 25;

    left: 50%;
    top: 5%;

    bottom: 5%;

    width: 90px;

    transform: translateX(-50%);

    display: flex;

    flex-direction: column;

    align-items: center;

    pointer-events: none;
}


/* =========================================================
   LOGO CENTRAL
========================================================= */

.centro-logo-alpine {

    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle,
            rgba(5,5,5,.95) 45%,
            rgba(5,5,5,.75) 70%,
            transparent 100%
        );

    flex-shrink: 0;
}


.centro-logo-alpine img {

    width: 55px;
    height: 55px;

    object-fit: contain;

    opacity: .75;

    filter:
        drop-shadow(
            0 0 8px rgba(255,99,184,.25)
        );

    transition:
        transform .5s ease,
        opacity .5s ease,
        filter .5s ease;
}


/* =========================================================
   LINHA VERTICAL
========================================================= */

.centro-linha-alpine {

    width: 1px;

    flex: 1;

    min-height: 80px;

    background:
        linear-gradient(
            to bottom,
            rgba(255,99,184,.8),
            rgba(255,99,184,.15),
            transparent
        );

    box-shadow:
        0 0 8px rgba(255,99,184,.25);
}


/* =========================================================
   NOME DA EQUIPE
========================================================= */

.centro-nome-alpine {

    writing-mode: vertical-rl;

    text-orientation: mixed;

    margin-top: 12px;

    color: rgba(255,255,255,.3);

    font-size: 20px;

    font-weight: 800;

    letter-spacing: 4px;

    text-transform: uppercase;

    white-space: nowrap;

    transition:
        color .4s ease,
        text-shadow .4s ease;
}


/* =========================================================
   HOVER NOS PILOTOS
========================================================= */

.dupla-pilotos-alpine:has(
    .piloto-alpine:hover
)
.centro-logo-alpine img {

    opacity: 1;

    transform: scale(1.1);

    filter:
        drop-shadow(
            0 0 8px #0090ff
        )
        drop-shadow(
            0 0 20px rgba(255,99,184,.55)
        );
}


.dupla-pilotos-alpine:has(
    .piloto-alpine:hover
)
.centro-nome-alpine {

    color: #0090ff;

    text-shadow:
        0 0 10px rgba(255,99,184,.6);
}


/* =========================================================
   HOVER — PILOTO
========================================================= */

.piloto-alpine:hover {

    z-index: 20;
}


/* =========================================================
   HOVER — BRILHO
========================================================= */

.piloto-alpine:hover::before {

    opacity: .9;

    transform: scale(1.3);
}


/* =========================================================
   HOVER — NÚMERO
========================================================= */

.piloto-alpine:hover
.piloto-numero-bg-alpine {

    color: rgba(255,99,184,.14);

    -webkit-text-stroke:
        1px rgba(255,99,184,.28);

    transform: scale(1.05);

    opacity: 1;
}


/* =========================================================
   HOVER — FOTO
========================================================= */

.piloto-alpine:hover
.piloto-foto-alpine img {

    filter:
        grayscale(0)
        brightness(1);

    opacity: 1;

    transform:
        translateY(0)
        scale(1.02);
}


/* =========================================================
   HOVER — DADOS
========================================================= */

.piloto-alpine:hover
.piloto-dados-alpine {

    transform:
        translateY(-8px);
}


/* =========================================================
   HOVER — NOME
========================================================= */

.piloto-alpine:hover
.piloto-dados-alpine h3 strong {

    color: #0090ff;

    text-shadow:
        0 0 8px rgba(255,99,184,.8),
        0 0 20px rgba(255,99,184,.45),
        0 3px 10px rgba(0,0,0,.9);
}


/* =========================================================
   HOVER — FUNDO DO NOME
========================================================= */

.piloto-alpine:hover
.piloto-dados-alpine h3::before {

    opacity: 1;

    transform: scaleX(1.05);
}


/* =========================================================
   HOVER — LINHA
========================================================= */

.piloto-alpine:hover
.piloto-linha-alpine {

    width: 120px;
}


/* =========================================================
   HOVER — AÇÃO
========================================================= */

.piloto-alpine:hover
.piloto-acao-alpine {

    color: white;

    transform:
        translateY(-5px);
}


.piloto-alpine:hover
.piloto-acao-alpine strong {

    background: #0090ff;

    color: #080808;

    transform:
        rotate(45deg);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 700px) {

    .pilotos-alpine {

        padding:
            25px 12px;
    }


    .pilotos-titulo-alpine {

        margin-bottom: 10px;
    }


    .pilotos-titulo-alpine h2 {

        font-size: 30px;
    }


    .pilotos-titulo-alpine p {

        font-size: 10px;
    }


    .dupla-pilotos-alpine {

        height: calc(100% - 100px);

        grid-template-columns:
            1fr 1fr;
    }


    .dupla-pilotos-alpine::before {

        top: 8%;

        bottom: 8%;
    }


    /* FOTO */

    .piloto-foto-alpine {

        width: 110%;

        height: 72%;
    }


    /* NÚMERO */

    .piloto-numero-bg-alpine {

        font-size: 150px;

        top: 15%;
    }


    .piloto-franco-alpine
    .piloto-numero-bg-alpine {

        font-size: 135px;

        right: -5%;
    }


    /* DADOS */

    .piloto-dados-alpine {

        left: 6%;

        bottom: 13%;

        max-width: 88%;
    }


    .piloto-franco-alpine
    .piloto-dados-alpine {

        right: 6%;

        left: auto;
    }


    /* PAÍS */

    .piloto-pais-alpine {

        font-size: 6px;

        letter-spacing: 2px;
    }


    /* NOME */

    .piloto-dados-alpine h3 {

        font-size: 25px;

        line-height: .9;
    }


    /* LINHA */

    .piloto-linha-alpine {

        margin-top: 9px;

        margin-bottom: 8px;

        width: 40px;
    }


    /* CATEGORIA */

    .piloto-categoria-alpine {

        font-size: 5px;

        letter-spacing: 1px;
    }


    /* AÇÃO */

    .piloto-acao-alpine {

        bottom: 5%;

        right: 6%;

        font-size: 6px;
    }


    .piloto-franco-alpine
    .piloto-acao-alpine {

        left: 6%;

        right: auto;
    }


    .piloto-acao-alpine strong {

        width: 23px;

        height: 23px;

        font-size: 12px;
    }

}


/* =========================================================
   CELULARES PEQUENOS
========================================================= */

@media (max-width: 400px) {

    .pilotos-alpine {

        padding:
            20px 8px;
    }


    .pilotos-titulo-alpine h2 {

        font-size: 25px;
    }


    .pilotos-titulo-alpine p {

        display: none;
    }


    /* NÚMERO */

    .piloto-numero-bg-alpine {

        font-size: 115px;
    }


    .piloto-franco-alpine
    .piloto-numero-bg-alpine {

        font-size: 110px;

        right: -4%;
    }


    /* FOTO */

    .piloto-foto-alpine {

        width: 120%;

        height: 65%;
    }


    /* DADOS */

    .piloto-dados-alpine {

        bottom: 12%;
    }


    .piloto-dados-alpine h3 {

        font-size: 21px;
    }


    /* CATEGORIA */

    .piloto-categoria-alpine {

        display: none;
    }


    /* AÇÃO */

    .piloto-acao-alpine span {

        display: none;
    }

}


/* =========================================================
   REDUÇÃO DE MOVIMENTO
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .piloto-alpine,
    .piloto-alpine::before,
    .piloto-numero-bg-alpine,
    .piloto-foto-alpine img,
    .piloto-dados-alpine,
    .piloto-dados-alpine h3::before,
    .piloto-dados-alpine h3 strong,
