    );

}


/* brilho de fundo */

.temporada-alpine::before{

    content:"";

    position:absolute;

    top:-200px;

    right:-200px;

    width:500px;

    height:500px;


    background:
    radial-gradient(
        circle,
        rgba(255,79,168,.18),
        transparent 70%
