===================================== */


#pontosalpine{


    font-size:60px;


    font-weight:900;


    color:#fff;


}



/* =====================================
   GRÁFICO
===================================== */


.card-grafico-alpine{

    height:300px;

    padding:25px;

    display:flex;

    align-items:center;

}



.card-grafico-alpine svg{


    width:100%;

    height:100%;


    overflow:visible;


}



/* linha */

#linhaGraficoalpine{


    stroke:#0090ff;

    stroke-width:6;


    stroke-linecap:round;


    stroke-linejoin:round;


    filter:

    drop-shadow(
        0 0 8px
        rgba(255,79,168,.8)
    );


}

/* =====================================
   DESEMPENHO alpine
===================================== */

.desempenho-alpine{

    display:grid;

    grid-template-columns:
    repeat(4,1fr);

    gap:20px;

    margin-top:35px;

}



/* cards */

.desempenho-alpine > div{


    background:

    linear-gradient(
        145deg,
        #141414,
        #202020
    );


    border-radius:20px;


    padding:25px 15px;


    text-align:center;


    border:

    1px solid
    rgba(255,79,168,.18);



    box-shadow:

    0 10px 25px
    rgba(0,0,0,.35);


    transition:.35s ease;

}



/* hover */

.desempenho-alpine > div:hover{


    transform:

    translateY(-8px);


    border-color:

    rgba(255,79,168,.55);



    box-shadow:

    0 0 25px
    rgba(255,79,168,.25);


}



/* números */

.desempenho-alpine span{


    display:block;


    font-size:45px;


    font-weight:900;


    color:#0090ff;



    text-shadow:

    0 0 15px
    rgba(255,79,168,.45);


}



/* textos */

.desempenho-alpine p{


    margin:8px 0 0;


    color:#ccc;


    font-size:14px;


    font-weight:800;


    text-transform:uppercase;


    letter-spacing:1px;


}



/* =====================================
   ANIMAÇÃO DOS NÚMEROS
===================================== */


.desempenho-alpine span{


    animation:

    numeroPulse 2s infinite alternate;


}


@keyframes numeroPulse{


    from{

        text-shadow:

        0 0 10px
        rgba(255,79,168,.25);

    }


    to{

        text-shadow:

        0 0 25px
        rgba(255,79,168,.75);

    }


}



/* =====================================
   DESTAQUE alpine
===================================== */


.card-campeonato-alpine::before,
.card-pontos-alpine::before,
.card-grafico-alpine::before{


    content:"";


    position:absolute;


    inset:0;


    border-radius:25px;


    background:

    linear-gradient(
        120deg,
        rgba(255,79,168,.12),
        transparent 45%
