/* BASE */

.alpine-bar-left,
.alpine-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.alpine-bar-left{

    border-radius:999px 0 0 999px;

}


.alpine-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #FF63B8,
        #0090FF
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.alpine-bar-right{

    border-radius:0 999px 999px 0;

}


.alpine-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #0090FF,
        #FF63B8
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.alpine-value{

    animation:
    alpineValueShow .5s ease;

}


@keyframes alpineValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


/*==================================================
        VENCEDOR
==================================================*/

.alpine-winner{

    color:#0090FF !important;

    text-shadow:
    0 0 15px rgba(255,99,184,.8);

}


.alpine-draw{

    color:#020202 !important;

}


/*==================================================
        TABLET
==================================================*/

@media(max-width:1100px){

    .alpine-layout{

        grid-template-columns:
            minmax(0,1fr)
            minmax(360px,450px)
            minmax(0,1fr);

        gap:10px;

    }


    .alpine-stat-values{

        grid-template-columns:
            55px
            1fr
            55px;

    }


    .alpine-value{

        font-size:24px;

    }


    .alpine-label{

        font-size:12px;

    }


    .alpine-left-name h3,
    .alpine-right-name h3{

        font-size:48px;

    }


    .alpine-left-image img,
    .alpine-right-image img{

        max-height:420px;
			 transform:translateY(-10px);

    }

}


/*==================================================
        CELULAR / TELA ESTREITA
==================================================*/

@media(max-width:800px){

    .alpine-battle{

        height:auto;

        min-height:100vh;

        overflow:hidden;

        padding:8px;

    }


    .alpine-battle-card{

        height:auto;

        min-height:calc(100vh - 16px);

        padding:15px;

        overflow:hidden;

    }


    .alpine-header{

        height:65px;

    }


    .alpine-team-logo{

        display:none;

    }


    .alpine-title-wrap h2{

        font-size:28px;

    }


    .alpine-title-wrap p{

        font-size:11px;

        letter-spacing:3px;

    }


    .alpine-layout{

        height:auto;

        display:grid;

        grid-template-columns:
            1fr
            1fr;

        grid-template-rows:
            auto
            auto;

        gap:5px;

    }


    .alpine-middle{

        grid-column:1 / 3;

        grid-row:2;

        padding-top:10px;

    }


    .alpine-left{

        grid-column:1;

        grid-row:1;

    }


    .alpine-right{

        grid-column:2;

        grid-row:1;

    }


    .alpine-left-image,
    .alpine-right-image{

        height:220px;

        flex:none;

    }


    .alpine-left-image img,
    .alpine-right-image img{

        height:220px;
			 transform:translateY(-10px);

    }


    .alpine-left-name h3,
    .alpine-right-name h3{

        font-size:30px;

    }


    .alpine-left-name span,
    .alpine-right-name span{

        font-size:11px;

        letter-spacing:3px;

    }


    .alpine-vs-box{

        width:55px;

        height:55px;

        font-size:23px;

    }


    .alpine-season{

        font-size:13px;

        margin-bottom:10px;

    }


    .alpine-stats{

        gap:8px;

    }


    .alpine-stat-values{

        grid-template-columns:
            45px
            1fr
            45px;

    }


    .alpine-value{

        font-size:20px;

    }


    .alpine-label{

        font-size:10px;

        letter-spacing:1px;

    }


    .alpine-bars{

        height:8px;

    }

}




/*==================================================
        DRIVER EVOLUTION - alpine
==================================================*/

/*==================================================
        alpine DRIVER EVOLUTION
==================================================*/

.driver-evolution-alpine{

    width:100%;

    min-height:100vh;

    padding:45px 0;

    box-sizing:border-box;

    background:
    linear-gradient(
        120deg,
        #0090ff 40%,
        #ff63b8 120%
    );
	
    font-family:
    Arial,
    Helvetica,
    sans-serif;

    color:#fff;

}


/*==================================================
        HEADER
==================================================*/

.evolution-header-alpine{

    text-align:center;
	
    margin-bottom:28px;

}


.evolution-header-alpine h2{

    margin:0;

    font-size:clamp(35px,5vw,68px);

    line-height:.95;

    font-weight:1000;

    letter-spacing:-3px;

    color:#fff;

}


.evolution-header-alpine p{

    margin:8px 0 0;

    font-size:20px;

    font-weight:800;

    letter-spacing:3px;

    color:#ffffff;

}



/*==================================================
        CARD
==================================================*/

.evolution-card-alpine{

    width:100%;

    max-width:none;

    min-height:560px;

    margin:0;

    padding:35px;

    box-sizing:border-box;

    border-radius:0;

    background:
    linear-gradient(
        120deg,
        #0090ff 40%,
        #ff63b8 120%
    );

    box-shadow:none;

}


/*==================================================
        TOPO
==================================================*/

.evolution-card-top-alpine{

    width:100%;

    display:flex;

    align-items:center;

    justify-content:space-between;

    gap:25px;

    margin-bottom:28px;

}


.evolution-intro-alpine h3{

    margin:0;

    font-size:25px;

    font-weight:900;

    letter-spacing:-1px;

}


.evolution-intro-alpine h3 span{

    font-weight:400;

    margin:0 5px;

}


.evolution-intro-alpine p{

    margin:6px 0 0;

    color:#ffffff;

    font-size:14px;

}



/*==================================================
        SELETOR
==================================================*/

.evolution-selector-alpine{

    display:flex;

    align-items:center;

    padding:4px;

    border-radius:8px;

    background:#29292f;

    border:1px solid #3c3c43;

}


.evolution-mode-alpine{

    border:0;

    background:transparent;

    color:#aaaab0;

    padding:11px 18px;

    border-radius:6px;

    font-size:13px;

    font-weight:800;

    cursor:pointer;

    transition:.25s ease;

}


.evolution-mode-alpine:hover{

    color:white;

}


.evolution-mode-alpine.active{

    background:#0090ff;

    color:#111;

}



/*==================================================
        CONTENT
==================================================*/

.evolution-content-alpine{

    width:100%;

    display:grid;

    grid-template-columns:
        minmax(0,1fr)
        240px;

    gap:40px;

}



/*==================================================
        GRÁFICO
==================================================*/

.evolution-chart-area-alpine{

    min-width:0;

    position:relative;

}


.y-axis-title-alpine{

    position:absolute;

    left:-65px;

    top:50%;

    transform:
    translateY(-50%)
    rotate(-90deg);

    color:#777780;

    font-size:22px;

    letter-spacing:1px;

    font-weight:700;

}


.evolution-chart-alpine{

    width:100%;

    height:400px;

    display:grid;

    grid-template-columns:45px 1fr;

}


.chart-y-labels-alpine{

    height:100%;

    display:flex;

    flex-direction:column;

    justify-content:space-between;

    align-items:flex-end;

    padding:0 10px 0 0;

    box-sizing:border-box;

}


.chart-y-labels-alpine span{

    color:#ffffff;

    font-size:20px;

}



/*==================================================
        ÁREA DAS LINHAS
==================================================*/

.chart-main-alpine{

    position:relative;

    width:100%;

    height:100%;

    border-left:1px solid #38383f;

    border-bottom:1px solid #38383f;

    background:
    repeating-linear-gradient(
        to bottom,
        transparent 0,
        transparent calc(10% - 1px),
        #292930 calc(10% - 1px),
        #292930 10%
    );

}



/*==================================================
        GRID VERTICAL
==================================================*/

.chart-grid-alpine{

    position:absolute;

    inset:0;

    display:flex;

}


.chart-grid-line-alpine{

    flex:1;

    border-right:1px solid rgba(255,255,255,.36);

}



/*==================================================
        SVG
==================================================*/

.evolution-svg-alpine{

    position:absolute;

    inset:0;

    width:100%;

    height:100%;

    overflow:visible;

}


.gasly-path-alpine{

    fill:none;

    stroke:#ff63b8;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}


.colapinto-path-alpine{

    fill:none;

    stroke:#0090ff;

    stroke-width:3;

    stroke-linecap:round;

    stroke-linejoin:round;

}



/*==================================================
        ÁREA ABAIXO DA LINHA
==================================================*/

.gasly-area-alpine{

    fill:url(#gaslyGradient);

    opacity:.12;

}


.colapinto-area-alpine{

    fill:url(#colapintoGradient);

    opacity:.08;

}



/*==================================================
        PONTOS
==================================================*/

.chart-point-alpine{

    fill:#121217;

    stroke:#ff63b8;

    stroke-width:3;

}


.chart-point-alpine.colapinto-alpine{

    stroke:#0090ff;

}



/*==================================================
        VALORES
==================================================*/

.chart-value-alpine{

    fill:#000;

    font-size:18px;

    font-weight:700;

    text-anchor:middle;

}


.chart-year-alpine{

    fill:#ffffff;

    font-size:20px;

    text-anchor:middle;

}



/*==================================================
        SIDEBAR
==================================================*/

.evolution-sidebar-alpine{

    padding-top:5px;

}


.sidebar-title-alpine{

    color:#000;

    font-size:13px;

    letter-spacing:1px;

    font-weight:700;

    margin-bottom:16px;

}



/*==================================================
        IDENTIDADE
==================================================*/

.driver-identity-alpine{

	  background:#15151a;

    display:flex;

    align-items:center;

    gap:12px;

    margin-bottom:20px;

}


.identity-line-alpine{

    width:42px;

    height:3px;

    position:relative;

}


.identity-line-alpine span{

    position:absolute;

    width:9px;

    height:9px;

    border-radius:50%;

    top:50%;

    left:50%;

    transform:translate(-50%,-50%);

    background:#ffffff;

    border:2px solid currentColor;

}


.gasly-line-alpine{

    background:#ff63b8;

    color:#ff63b8;

}


.colapinto-line-alpine{

    background:#0090ff;

    color:#0090ff;

}


.driver-identity-alpine small{

    display:block;

    color:#535353;

    font-size:11px;

}


.driver-identity-alpine strong{

    display:block;

    color:#eee;

    font-size:14px;

}

/*==================================================
        IMAGENS - LINE IDENTITY
==================================================*/

.identity-driver-info-alpine{

    display:flex;

    flex-direction:column;

    justify-content:center;

}


.identity-driver-image-alpine{

    width:80px;

    height:80px;

    object-fit:contain;

    object-position:center bottom;

    align-self:flex-end;

    margin-left:auto;

}

/*==================================================
        LEGEND
==================================================*/

.legend-title-alpine{

    margin-top:40px;

}


.driver-legend-alpine{

    height:68px;

    margin-bottom:12px;

    padding:8px 10px 8px 15px;

    box-sizing:border-box;

    display:flex;

    align-items:center;

    justify-content:space-between;

    border:1px solid #ff63b8;

    border-radius:8px;

    background:#17171c;

}


.legend-info-alpine span{

    display:block;

    color:#ffffff;

    font-size:11px;

}


.legend-info-alpine strong{

    display:block;

    color:#fff;

    font-size:15px;

}


.driver-legend-alpine img{

    height:58px;

    width:auto;

    object-fit:contain;

    align-self:flex-end;

}



/*==================================================
        ANIMAÇÃO
==================================================*/

.evolution-svg-alpine path{

    stroke-dasharray:3000;

    stroke-dashoffset:3000;

    animation:
    drawEvolution 1.5s ease forwards;

}


@keyframes drawEvolution{

    to{

        stroke-dashoffset:0;

    }

}


.chart-point-alpine{

    opacity:0;

    animation:
    pointShow .3s ease forwards;

}


@keyframes pointShow{

    to{

        opacity:1;

    }

}



/*==================================================
        RESPONSIVO
==================================================*/

@media(max-width:900px){

    .evolution-card-alpine{

        padding:25px 20px;

    }


    .evolution-card-top-alpine{

        align-items:flex-start;

        flex-direction:column;

    }


    .evolution-content-alpine{

        grid-template-columns:1fr;

    }


    .evolution-sidebar-alpine{

        display:grid;

        grid-template-columns:
            1fr 1fr;

        gap:10px;

    }


    .sidebar-title-alpine{

        grid-column:1 / -1;

    }


    .legend-title-alpine{

        margin-top:15px;

    }

}


@media(max-width:600px){

    .driver-evolution-alpine{

        padding:25px 8px;

    }


    .evolution-header-alpine h2{

        font-size:32px;

        letter-spacing:-1px;

    }


    .evolution-header-alpine p{

        font-size:15px;

    }


    .evolution-card-alpine{

        padding:20px 12px;

        border-radius:10px;

    }


    .evolution-selector-alpine{

        width:100%;

    }


    .evolution-mode-alpine{

        flex:1;

        padding:10px 5px;

        font-size:11px;

    }


    .evolution-intro-alpine h3{

        font-size:18px;

    }


    .evolution-chart-alpine{

        height:300px;

        grid-template-columns:32px 1fr;

    }


    .chart-y-labels-alpine span{

        font-size:9px;

    }


    .y-axis-title-alpine{

        display:none;

    }


    .evolution-sidebar-alpine{

        grid-template-columns:1fr;

    }


    .sidebar-title-alpine{

        grid-column:auto;

    }

}



.lideranca-alpine{
  padding:80px 20px;

  background:
  linear-gradient(
    135deg,

    #ff4fa8 0%,
    #f122d4 18%,
    #0057b8 38%,
    #0094ff 52%,

    #ff4fa8 72%,
    #ff79c6 86%,

    #0068f3 100%
  );

  text-align:center;
}

/* ===== TÍTULO ===== */
.titulo-lideranca-alpine{
  font-size:38px;

  color:#f7fbff;

  margin-bottom:60px;

  position:relative;

  letter-spacing:1px;

  text-shadow:
  0 0 12px rgba(255,255,255,.18);
}

.titulo-lideranca-alpine::after{
  content:"";

  width:180px;
  height:3px;

  background:
  linear-gradient(
    90deg,
    transparent,
    #ff79c6,
    #00a2ff,
    transparent
  );

  display:block;

  margin:15px auto 0;

  box-shadow:
  0 0 14px #ff79c6,
  0 0 20px #0094ff;
}

/* ===== CONTAINER ===== */
.container-lideranca-alpine{
  display:flex;

  justify-content:center;

  gap:30px;

  flex-wrap:wrap;
}

/* ===== CARD ===== */
.card-lider-alpine{
  background:
  linear-gradient(
    145deg,
    rgba(6,18,45,.95),
    rgba(0,87,184,.92)
  );

  width:260px;

  border-radius:20px;

  padding:24px;

  color:#fff;

  transition:.4s ease;

  border:
  3px solid rgba(255,121,198,.25);

  position:relative;

  overflow:hidden;

  backdrop-filter:blur(10px);
}

/* glow topo */
.card-lider-alpine::before{
  content:"";

  position:absolute;

  top:0;
  left:0;

  width:100%;
  height:3px;

  background:
  linear-gradient(
    90deg,
    transparent,
    #ff79c6,
    #0094ff,
    transparent
  );
}

/* reflexo */
.card-lider-alpine::after{
  content:"";

  position:absolute;

  top:0;
  left:-100%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.16),
    transparent
  );

  transition:.6s;
}

.card-lider-alpine:hover::after{
  left:100%;
}

/* ===== IMAGEM ===== */
.card-lider-alpine img{
  width:100%;
  height:260px;

  object-fit:cover;
  object-position:top;

  border-radius:15px;

  margin-bottom:15px;

  filter:brightness(.96);

  transition:.4s;
}

/* ===== NOME ===== */
.card-lider-alpine h3{
  margin:10px 0 5px;

  font-size:20px;

  color:#ffffff;
}

/* ===== CARGO ===== */
.card-lider-alpine span{
  display:block;

  color:#ff9ed4;

  font-weight:bold;

  margin-bottom:10px;

  font-size:20px;

  letter-spacing:.5px;

  text-shadow:
  0 0 10px rgba(255,121,198,.25);
}

/* ===== TEXTO ===== */
.card-lider-alpine p{
  color:#eef6ff;

  line-height:1.5;

  font-size:20px;

  border-left:
  3px solid #00a2ff;

  padding-left:10px;

  text-shadow:
  0 0 6px rgba(255,255,255,.15);

  transition:.3s;
}

.card-lider-alpine:hover p{
  transform:translateY(-2px);

  color:#ffffff;
}

/* ===== HOVER ===== */
.card-lider-alpine:hover{
  transform:
  translateY(-12px)
  scale(1.02);

  box-shadow:
  0 18px 40px rgba(0,148,255,.22),
  0 0 25px rgba(255,79,168,.18);
}

.card-lider-alpine:hover img{
  transform:scale(1.05);

  filter:brightness(1);
}

/* ===== RESPONSIVO ===== */
@media(max-width:600px){

  .titulo-lideranca-alpine{
    font-size:26px;
  }

  .card-lider-alpine{
    width:100%;
    max-width:320px;
  }

  .card-lider-alpine img{
    height:220px;
  }

}


.alpine-sectors{
  position:relative;

  padding:100px 20px;

  overflow:hidden;

     background:
linear-gradient(
  135deg,

  #ff4fa8 0%,
  #f122d4 18%,
  #0057b8 38%,
  #0094ff 52%,

  #ff4fa8 72%,
  #ff79c6 86%,

  #0068f3 100%
);

  color:#fff;
}

/* brilho fundo */
.alpine-sectors::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(
    circle at top right,
    rgba(255,79,163,.22),
    transparent 40%
  ),
  radial-gradient(
    circle at bottom left,
    rgba(0,144,255,.25),
    transparent 45%
  );

  pointer-events:none;
}

/* =========================================
   HEADER
========================================= */
.alpine-sectors-header{
  position:relative;
  z-index:2;

  max-width:1000px;

  margin:0 auto 70px;

  text-align:center;
}

.alpine-sectors-header span{
  display:inline-block;

  padding:8px 18px;

  border-radius:40px;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.18);

  font-size:15px;
  font-weight:700;

  letter-spacing:1px;
  text-transform:uppercase;

  margin-bottom:20px;

  backdrop-filter:blur(10px);

  color:#ffd3e8;
}

.alpine-sectors-header h2{
  font-size:clamp(34px,5vw,60px);

  line-height:1.1;

  margin-bottom:25px;

  color:#ffffff;

  text-shadow:
  0 0 25px rgba(0,144,255,.35),
  0 0 40px rgba(255,79,163,.18);
}

.alpine-sectors-header p{
  font-size:20px;

  line-height:1.7;

  color:#eef5ff;

  max-width:850px;

  margin:auto;
}

/* =========================================
   GRID
========================================= */
.alpine-sectors-grid{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(260px,1fr));

  gap:25px;

  max-width:1450px;

  margin:auto;
}

/* =========================================
   CARD
========================================= */
.alpine-sector-card{
  position:relative;

  overflow:hidden;

  padding:30px;

  border-radius:24px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.12),
    rgba(255,255,255,.03)
  );

  border:
  1px solid rgba(255,255,255,.12);

  backdrop-filter:blur(14px);

  transition:
  transform .4s ease,
  box-shadow .4s ease,
  border-color .4s ease;
}

/* glow */
.alpine-sector-card::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(
    circle at top,
    rgba(0,144,255,.25),
    transparent 65%
  ),
  radial-gradient(
    circle at bottom,
    rgba(255,79,163,.18),
    transparent 70%
  );

  opacity:0;

  transition:.4s ease;
}

/* brilho passando */
.alpine-sector-card::after{
  content:"";

  position:absolute;

  top:-150%;
  left:-40%;

  width:30%;
  height:320%;

  background:
  linear-gradient(
    to right,
    transparent,
    rgba(255,255,255,.28),
    transparent
  );

  transform:rotate(25deg);

  transition:.8s ease;
}

.alpine-sector-card h3{
  position:relative;
  z-index:2;

  font-size:24px;

  margin-bottom:18px;

  color:#ffffff;
}

.alpine-sector-card p{
  position:relative;
  z-index:2;

  font-size:17px;

  line-height:1.7;

