.numeros-alpine{

    position:relative;

    min-height:600px;

    padding:40px 0;

    overflow:hidden;

    background:
    linear-gradient(
        135deg,
        #ff12d5 0%,
        #121212 45%,
        #0090ff 120%
    );

}


/* IMAGEM DE FUNDO */

.bg-numeros-alpine{

    position:absolute;

    inset:0;

    width:100%;
    height:100%;

    object-fit:cover;

    filter:
    brightness(.35)
    blur(4px);

    transform:scale(1.1);

    z-index:0;

}



.numeros-alpine::before{

    content:"";

    position:absolute;

    inset:0;

    background:

    radial-gradient(
        circle at center,
        transparent 20%,
        rgba(205,0,94,.85)
    );

    z-index:1;

}



/* TITULO */

.titulo-numeros-alpine{

    position:relative;

    z-index:2;

    text-align:center;

    color:#0090ff;

    font-size:clamp(32px,5vw,55px);

    font-weight:900;

    text-transform:uppercase;

    letter-spacing:2px;

    margin-bottom:25px;

    text-shadow:

    0 0 15px #0090ff;

}



/* GRID */

.stats-grid-alpine{

    position:relative;

    z-index:2;


    max-width:1200px;

    margin:auto;

    padding:0 35px;


    display:grid;

    grid-template-columns:
    repeat(3,1fr);


    gap:15px;

}



/* CARDS */

.card-stat-alpine{

    position:relative;


    background:

    linear-gradient(
        145deg,
        rgba(10,10,10,.08),
        rgba(205,0,94,.25)
    );




    border-radius:22px;


    padding:18px;


    text-align:center;


    color:white;


    border:

    1px solid
    rgba(10,10,10,.5);



    box-shadow:

    0 15px 40px
    rgba(205,0,94,.7);



    overflow:hidden;



    opacity:0;

    transform:
    translateY(50px);



    transition:.6s ease;

}



/* LINHA LARANJA */

.card-stat-alpine::before{

    content:"";

    position:absolute;

    top:0;

    left:0;

    width:100%;

    height:4px;


    background:

    linear-gradient(
        90deg,
        transparent,
        #0090ff,
        transparent
    );

}



/* ATIVO */

.card-stat-alpine.ativo{

    opacity:1;

    transform:
    translateY(0);


    animation:

    brilhoalpine 2.5s infinite alternate;

}



@keyframes brilhoalpine{

    from{

        box-shadow:

        0 0 15px
        rgba(10,10,10,.3);

    }


    to{

        box-shadow:

        0 0 35px
        rgba(10,10,10,.8);

    }

}



