    margin-top:15px;


    font-size:

    clamp(18px,2vw,28px);


    font-weight:bold;


    color:white;

}



/* CARD GRANDE */

.grande-alpine{

    grid-column:

    1 / -1;

}



/* BARRA */

.barra-velocidade-alpine{


    width:0%;


    height:8px;


    margin-top:20px;


    border-radius:20px;


    background:

    linear-gradient(
        90deg,
        #0090ff,
        #121212
    );


    box-shadow:

    0 0 15px #0090ff;


    transition:

    width .3s ease;

