.hall-alpine{
padding:120px 40px;
position:relative;

background:
linear-gradient(
135deg,

#ff4fa8 0%,
#f122d4 18%,
#0057b8 38%,
#0094ff 52%,

#ff4fa8 72%,
#ff79c6 86%,

#0068f3 100%
);

min-height:auto;
height:auto;

overflow:hidden;
}

/* ===== OVERLAY ===== */

.hall-overlay-alpine{
position:absolute;
inset:0;

background:
linear-gradient(
to bottom,
rgba(0,0,0,.25),
rgba(0,0,0,.55)
);

z-index:1;
}

/* ===== TÍTULO ===== */

.titulo-hall-alpine{
text-align:center;

font-size:52px;

color:#ffffff;

margin-bottom:80px;

text-shadow:
0 0 18px rgba(255,79,168,.8),
0 0 25px rgba(0,148,255,.6);
}

/* ===== GRID ===== */

.hall-grid-alpine{
display:flex;

justify-content:center;
align-items:flex-start;

flex-wrap:wrap;

perspective:1200px;

gap:40px;

position:relative;

z-index:3;
}

/* ===== FUNDO ===== */

.bg-hall-alpine{
position:absolute;
inset:0;
z-index:0;
}

.bg-layer-alpine{
position:absolute;
inset:0;

background-size:cover;
background-position:center center;
background-repeat:no-repeat;

transform:scale(1);

opacity:0;

transition:opacity .8s ease;
}

.bg-layer-alpine.active{
opacity:1;
}

.hall-grid-alpine,
.titulo-hall-alpine,
.hall-overlay-alpine{
position:relative;
z-index:2;
}

/* ===== SHOWCASE ===== */

.hall-alpine.showcase .hall-card-alpine{
opacity:0.08;

transform:scale(0.92);

filter:
blur(2px)
grayscale(100%);

pointer-events:none;

transition:.5s ease;
}

.hall-alpine.showcase .bg-layer-alpine.active{
opacity:1;

transform:scale(1.05);

filter:
brightness(1.15)
saturate(1.2);

transition:1s ease;
}

/* ===== CARD ===== */

.hall-card-alpine{
position:relative;

width:320px;

padding:30px;

border-radius:24px;

background:
linear-gradient(
180deg,
rgba(12,18,40,0.28),
rgba(12,18,40,0.78)
);

border:
1px solid rgba(255,79,168,.3);

overflow:hidden;

transition:.45s ease;

box-shadow:
0 15px 35px rgba(0,0,0,0.45);

text-align:center;

backdrop-filter:blur(4px);

transform-origin:center top;
}

/* ===== GLOW TOPO ===== */

.hall-card-alpine::before{
content:"";

position:absolute;

top:0;
left:0;

width:100%;
height:3px;

background:
linear-gradient(
90deg,
transparent,
#ff4fa8,
#0094ff,
transparent
);
}

/* ===== REFLEXO ===== */

.hall-card-alpine::after{
content:"";

position:absolute;

top:0;
left:-100%;

width:100%;
height:100%;

background:
linear-gradient(
120deg,
transparent,
rgba(255,255,255,.18),
transparent
);

transition:.6s;
}

.hall-card-alpine:hover::after{
left:100%;
}

/* ===== HOVER ===== */

.hall-card-alpine:hover{
transform:
translateY(-14px)
scale(1.04);

background:
rgba(15,20,45,0.92);

box-shadow:
0 25px 60px rgba(0,0,0,0.7),
0 0 30px rgba(255,79,168,.25),
0 0 30px rgba(0,148,255,.22);

z-index:10;
}

.hall-grid-alpine:hover .hall-card-alpine{
opacity:.35;

transform:scale(.98);
}

.hall-card-alpine:hover{
opacity:1 !important;

transform:
translateY(-14px)
scale(1.06);
}

/* ===== NÚMERO ===== */

.numero-hall-alpine{
position:absolute;

top:15px;
right:20px;

font-size:70px;

font-weight:900;

color:rgba(255,255,255,0.08);
}

/* ===== FOTO ===== */

.hall-card-alpine img{
width:170px;
height:200px;

object-fit:cover;

border-radius:50%;

border:
3px solid #ff4fa8;

margin-bottom:20px;

filter:
grayscale(100%)
brightness(.9);

transition:.5s ease;
}

.hall-card-alpine:hover img{
filter:
grayscale(0%)
brightness(1.1);

transform:scale(1.1);

border-color:#0094ff;
}

/* ===== CONTEÚDO ===== */

.hall-card-alpine p,
.hall-stats-alpine,
.frase-hall-alpine{
opacity:0;

transform:translateY(10px);

max-height:0;

overflow:hidden;

transition:.4s ease;
}

.hall-card-alpine:hover p,
.hall-card-alpine:hover .hall-stats-alpine,
.hall-card-alpine:hover .frase-hall-alpine{
opacity:1;

transform:translateY(0);

max-height:200px;
}

/* ===== NOME ===== */

.hall-card-alpine h3{
font-size:32px;

color:#fff;

margin-bottom:10px;
}

/* ===== PAÍS ===== */

.pais-hall-alpine{
display:block;

font-size:18px;

color:#ffd1ec;

margin-bottom:18px;
}

/* ===== TEXTO ===== */

.hall-card-alpine p{
font-size:18px;

color:#f1f5ff;

margin-bottom:22px;
}

/* ===== STATS ===== */

.hall-stats-alpine{
display:flex;

justify-content:space-between;

margin-bottom:22px;

font-size:15px;

color:#9ed8ff;
}

/* ===== FRASE ===== */

.frase-hall-alpine{
font-size:14px;

font-style:italic;

