/* ===== CÍRCULO ===== */

.car-circle-alpine{
  position:absolute;

  width:420px;
  height:420px;

  border-radius:50%;

  border:
  2px solid rgba(255,79,168,.2);

  box-shadow:
    0 0 40px rgba(255,79,168,.18),
    inset 0 0 40px rgba(0,148,255,.12);

  animation:rotateCircleAlpine 14s linear infinite;
}

.car-circle-alpine::before{
  content:"";

  position:absolute;
  inset:20px;

  border-radius:50%;

  border:
  1px dashed rgba(255,255,255,.08);
}

/* ===== CARRO ===== */

.car-container-alpine img{
  position:relative;

  width:100%;
  max-width:650px;

  object-fit:contain;

  z-index:5;

  filter:
  drop-shadow(
    0 30px 35px rgba(0,0,0,.6)
  );

  animation:
    floatCarAlpine 5s ease-in-out infinite,
    rotateCarAlpine 6s ease-in-out infinite;

  transition:
    opacity .45s ease,
    transform .45s ease;
}

/* ===== BOTÕES ===== */

.controls-alpine{
  position:relative;

  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:16px;

  margin-top:40px;
  margin-bottom:90px;

  z-index:5;
}

.controls-alpine button{
  position:relative;

  padding:14px 22px;

  border:none;
  border-radius:16px;

  background:
  linear-gradient(
    145deg,
    #ff4fa8,
    #0094ff
  );

  color:#ffffff;

  font-weight:800;
  font-size:.95rem;

  letter-spacing:1px;

  cursor:pointer;

  overflow:hidden;

  transition:.35s;
}

.controls-alpine button::before{
  content:"";

  position:absolute;
  top:0;
  left:-120%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.6),
    transparent
  );

  transition:.6s;
}

.controls-alpine button:hover::before{
  left:120%;
}

.controls-alpine button:hover{
  transform:
  translateY(-6px)
  scale(1.05);

  box-shadow:
  0 10px 30px rgba(255,79,168,.35);
}

/* ===== INFOS ===== */

.car-info-alpine{
  position:relative;

  width:100%;
  max-width:1200px;

  margin:auto;

  z-index:5;
}

.car-info-alpine h2{
  text-align:center;

  font-size:clamp(2rem,5vw,3.5rem);

  margin-bottom:50px;

  font-weight:900;

  color:#fff;
}

/* ===== GRID ===== */

.info-grid-alpine{
  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(220px,1fr));

  gap:25px;
}

/* ===== CARDS ===== */

.info-card-alpine{
  position:relative;

  padding:35px 28px;

  border-radius:28px;

  background:
  linear-gradient(
    145deg,
    rgba(255,255,255,.06),
    rgba(255,255,255,.02)
  );

  border:
  1px solid rgba(255,255,255,.08);

  backdrop-filter:blur(14px);

  overflow:hidden;

  transition:.45s;
}

.info-card-alpine::before{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    140deg,
    rgba(255,255,255,.08),
    transparent 40%
  );

  opacity:0;

  transition:.4s;
}

.info-card-alpine:hover::before{
  opacity:1;
}

.info-card-alpine:hover{
  transform:translateY(-12px);

  border-color:
  rgba(255,79,168,.35);

  box-shadow:
    0 15px 40px rgba(0,0,0,.45),
    0 0 25px rgba(0,148,255,.15);
}

.info-card-alpine span{
  display:block;

  margin-bottom:14px;

  color:#ff79c6;

  text-transform:uppercase;

  letter-spacing:2px;

  font-size:.8rem;

  font-weight:700;
}

.info-card-alpine h3{
  color:#fff;

  font-size:1.1rem;

  line-height:1.7;

  font-weight:600;
}

/* ===== ANIMAÇÕES ===== */

@keyframes rotateCircleAlpine{

  from{
    transform:rotate(0deg);
  }

  to{
    transform:rotate(360deg);
  }

}

@keyframes floatCarAlpine{

  0%,100%{
    transform:translateY(0px);
  }

  50%{
    transform:translateY(-15px);
  }

}

@keyframes rotateCarAlpine{

  0%,100%{
    rotate:y 0deg;
  }

  50%{
    rotate:y 10deg;
  }

}

@keyframes pulseFloorAlpine{

  0%,100%{
    transform:scale(.95);
    opacity:.5;
  }

  50%{
    transform:scale(1.05);
    opacity:1;
  }

}

@keyframes glowAlpine{

  0%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(80px,40px);
  }

  100%{
    transform:translate(0,0);
  }

}

/* ===== RESPONSIVO ===== */

@media(max-width:768px){

  .alpine-evolution{
    padding:90px 18px;
  }

  .car-container-alpine{
    height:320px;
  }

  .car-circle-alpine{
    width:250px;
    height:250px;
  }

  .car-container-alpine img{
    max-width:340px;
  }

  .controls-alpine{
    gap:10px;
  }

  .controls-alpine button{
    padding:12px 16px;
    font-size:.8rem;
  }

  .info-card-alpine{
    padding:28px 22px;
  }

}


.eras-alpine{
    position:relative;

    padding:120px 30px;

    text-align:center;

    background:
    radial-gradient(
    circle at top,

    #ff4fa8 0%,
    #f122d4 18%,

    #0057b8 45%,
    #0094ff 72%,

    #02142f 100%
    );

    overflow:hidden;

    color:#eef7ff;
}

/* GLOW FUNDO */
.eras-alpine::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(circle,
    rgba(255,79,168,.22),
    transparent 70%);

    filter:blur(40px);

    animation:alpineGlow 8s ease-in-out infinite;

    z-index:0;
}

.eras-alpine::after{
    content:"";

    position:absolute;

    bottom:-250px;
    right:-200px;

    width:550px;
    height:550px;

    background:
    radial-gradient(circle,
    rgba(0,148,255,.16),
    transparent 70%);

    filter:blur(50px);

    z-index:0;
}

/* CONTEÚDO */
.eras-alpine > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-eras-alpine{
    font-size:clamp(2.8rem,6vw,5rem);

    margin-bottom:25px;

    font-weight:900;

    letter-spacing:2px;

    text-transform:uppercase;

    background:
    linear-gradient(
    90deg,
    #ffffff,
    #ff79c6,
    #66c7ff);

    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;

    text-shadow:
    0 0 25px rgba(255,79,168,.25);
}

/* ===== TEXTO ===== */
#textoEra-alpine{
    max-width:950px;

    margin:0 auto 50px;

    line-height:1.8;

    font-size:clamp(1rem,2vw,1.5rem);

    color:#e6f4ff;

    opacity:.92;
}

/* ===== BOTÕES ===== */
.botoes-eras-alpine{
    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:16px;

    margin-bottom:70px;
}

.botoes-eras-alpine button{
    position:relative;

    padding:16px 26px;

    border:none;

    border-radius:18px;

    background:
    linear-gradient(
    145deg,
    #071426,
    #10294a);

    color:#ff79c6;

    font-size:1rem;

    font-weight:800;

    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(255,121,198,.18);
}

/* brilho botão */
.botoes-eras-alpine button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.4),
    transparent);

    transition:.7s;
}

.botoes-eras-alpine button:hover::before{
    left:120%;
}

/* HOVER */
.botoes-eras-alpine button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
    145deg,
    #ff4fa8,
    #0094ff);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(255,79,168,.35);
}

/* BOTÃO ATIVO */
.botoes-eras-alpine .ativo{
    background:
    linear-gradient(
    145deg,
    #ff79c6,
    #0094ff);

    color:#ffffff;

    box-shadow:
    0 0 30px rgba(255,121,198,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#alpine-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.alpine-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
    180deg,
    rgba(255,255,255,.10),
    rgba(255,255,255,.04));

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(255,121,198,.15);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.alpine-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
    140deg,
    rgba(255,255,255,.14),
    transparent 45%);

    opacity:0;

    transition:.45s;
}

.alpine-timeline-item:hover::before{
    opacity:1;
}

/* HOVER CARD */
.alpine-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(255,121,198,.45);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(255,79,168,.18);
}

/* ===== IMAGEM ===== */
.alpine-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(0 10px 20px rgba(0,0,0,.4));
}

.alpine-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(0 15px 25px rgba(255,79,168,.28));
}

/* ===== ANO ===== */
.alpine-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#ff79c6;

    text-shadow:
    0 0 12px rgba(255,121,198,.3);
}

/* ===== TEXTO ===== */
#alpine-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#eef7ff;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes alpineGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-alpine{
        padding:90px 18px;
    }

    .titulo-eras-alpine{
        font-size:2.5rem;
    }

    #textoEra-alpine{
        font-size:1rem;
    }

    .botoes-eras-alpine{
        gap:10px;
    }

    .botoes-eras-alpine button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #alpine-timeline{
        grid-template-columns:1fr;
    }

    .alpine-timeline-item{
        max-width:360px;
        margin:auto;
    }

}

.footer-f1-alpine{
  background:
  linear-gradient(
    135deg,

    #ff4fa8 0%,
    #f122d4 20%,

    #0057b8 55%,
    #02142f 100%
  );

  color:#eef7ff;

  padding:70px 25px;

  text-align:center;

  position:relative;

  overflow:hidden;
}

/* brilho fundo */
.footer-f1-alpine::before{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  top:-200px;
  left:-200px;

  background:
  radial-gradient(
    circle,
    rgba(255,79,168,.22),
    transparent 70%
  );

  filter:blur(40px);

  animation:alpineFooterGlow 7s ease-in-out infinite;
}

/* brilho extra */
.footer-f1-alpine::after{
  content:"";

  position:absolute;

  right:-180px;
  bottom:-180px;

  width:420px;
  height:420px;

  background:
  radial-gradient(
    circle,
    rgba(0,148,255,.18),
    transparent 70%
  );

  filter:blur(50px);
}

/* conteúdo */
.footer-f1-alpine > *{
  position:relative;
  z-index:2;
}

/* BRAND */
.footer-brand-alpine p{
  font-size:34px;

  font-weight:900;

  letter-spacing:3px;

  color:#ffffff;

  margin-bottom:8px;

  text-shadow:
  0 0 15px rgba(255,79,168,.45);
}

.footer-brand-alpine span{
  font-size:20px;

  color:#dbefff;

  opacity:.9;
}

/* LINKS */
.footer-links-alpine,
.footer-social-alpine{
  margin-top:28px;

  display:flex;

  justify-content:center;

  flex-wrap:wrap;

  gap:18px;
}

.footer-links-alpine a,
.footer-social-alpine a{
  position:relative;

  color:#eef7ff;

  text-decoration:none;

  font-weight:700;

  font-size:16px;

  padding:10px 14px;

  border-radius:12px;

  transition:.35s ease;
}

/* underline glow */
.footer-links-alpine a::after,
.footer-social-alpine a::after{
  content:"";

  position:absolute;

  left:50%;
  bottom:0;

  width:0%;
  height:2px;

  background:#ff79c6;

  transition:.35s ease;

  transform:translateX(-50%);
}

/* hover */
.footer-links-alpine a:hover,
.footer-social-alpine a:hover{
  color:#ff79c6;

  background:
  rgba(255,255,255,.08);

  text-shadow:
  0 0 12px rgba(255,79,168,.4);
}

.footer-links-alpine a:hover::after,
.footer-social-alpine a:hover::after{
  width:80%;
}

/* COPYRIGHT */
.footer-copy-alpine{
  margin-top:35px;

  font-size:14px;

  color:#dbefff;

  opacity:.8;

  letter-spacing:.5px;
}

/* BOTÃO TO TOP */
.back-to-top-alpine{
  position:fixed;

  right:20px;
  bottom:20px;

  background:
  linear-gradient(
    145deg,
    #ff4fa8,
    #0057b8
  );

  color:#ffffff;

  border:none;

  padding:14px 16px;

  border-radius:16px;

  cursor:pointer;

  font-weight:800;

  z-index:999;

  box-shadow:
  0 0 20px rgba(255,79,168,.28);

  transition:.35s ease;
}




.back-to-top-alpine:hover{
  transform:
  translateY(-6px)
  scale(1.08);

  box-shadow:
  0 0 35px rgba(255,79,168,.45);
}

/* animação glow */
@keyframes alpineFooterGlow{

  0%,100%{
    transform:translate(0,0) scale(1);
  }

  50%{
    transform:translate(50px,30px) scale(1.1);
  }

}

/* RESPONSIVO */
@media(max-width:768px){

  .footer-f1-alpine{
    padding:60px 18px;
  }

  .footer-brand-alpine p{
    font-size:26px;
  }

  .footer-brand-alpine span{
    font-size:16px;
  }

  .footer-links-alpine,
  .footer-social-alpine{
    gap:10px;
  }

  .footer-links-alpine a,
  .footer-social-alpine a{
    font-size:14px;
    padding:8px 10px;
  }

  .back-to-top-alpine{
    right:14px;
    bottom:14px;

    padding:12px 14px;
  }

}





/*///////////////////////////////////////////
CADILLAC
///////////////////////////////////////////*/


body.cadillac{
  background: #000000;
}




/*=========================================================
   cadillac HERO
========================================================= */

.cadillac-hero {
    position: relative;
    width: 100%;
    height: 100dvh;
    min-height: 620px;
    overflow: hidden;
    background: #020713;
    color: #fff;
    isolation: isolate;
}


/* =========================================================
   CARRO — FUNDO PRINCIPAL
========================================================= */

.cadillac-car-bg {
    position: absolute;
    inset: -5%;
    z-index: -5;

    background-image:
        url("carros/cdl.avif");

    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;

    filter:
        brightness(.58)
        contrast(1.08)
        saturate(1.12);

    transform: scale(1.04);

    transition:
        transform 1s ease,
        filter 1s ease;
}


/* LEVE MOVIMENTO */

.cadillac-hero:hover .cadillac-car-bg {
    transform: scale(1.07);

    filter:
        brightness(.63)
        contrast(1.1)
        saturate(1.15);
}


/* =========================================================
   OVERLAY
========================================================= */

.cadillac-overlay {
    position: absolute;
    inset: 0;
    z-index: -4;

    background:

        /* AZUL */
        linear-gradient(
            115deg,
            rgba(3,3,3,.78),
            transparent 42%
        ),

        /* VERMELHO */
        linear-gradient(
            250deg,
            rgba(255,255,255,.32),
            transparent 42%
        ),

        /* ESCURECIMENTO */
        linear-gradient(
            to bottom,
            rgba(0,0,0,.55),
            transparent 25%,
            rgba(0,0,0,.08) 55%,
            rgba(0,0,0,.82) 100%
        );
}


/* =========================================================
   TOPO
========================================================= */

.cadillac-top {
    position: absolute;

    top: 25px;
    left: 4vw;
    right: 4vw;

    z-index: 30;

    display: flex;
    align-items: center;
    justify-content: space-between;
}


/* =========================================================
   HOME
========================================================= */

.cadillac-home {
    display: flex;
    align-items: center;

    gap: 8px;

    padding: 9px 13px;

    text-decoration: none;

    color: rgba(255,255,255,.75);

    border: 1px solid rgba(255,255,255,.2);

    background: rgba(0,0,0,.3);

    backdrop-filter: blur(10px);

    font-size: 25px;
    font-weight: 900;
    letter-spacing: 2px;

    transition: .35s ease;
}

.cadillac-home i {
    font-size: 20px;
}

.cadillac-home:hover {
    color: #fff;

    background: rgba(3,3,3,.22);

    border-color: #FFFFFF;

    transform: translateY(-3px);
}


/* =========================================================
   STATUS
========================================================= */

.cadillac-status {
    position: absolute;

    left: 50%;

    transform: translateX(-50%);

    font-size: 15px;
    font-weight: 900;
    letter-spacing: 4px;

    color: rgba(255,255,255,.55);
}


/* =========================================================
   cadillac — REDES SOCIAIS INFERIORES
========================================================= */

.cadillac-social-top {
    position: absolute;

    z-index: 30;

    left: 50%;
    bottom:110px;

    transform: translateX(-13%);

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 7px;
}


/* =========================================================
   ÍCONES
========================================================= */

.cadillac-social-top a {
    width: 100px;
    height: 100px;

    display: flex;
    align-items: center;
    justify-content: center;

    text-decoration: none;

    color: rgba(255,255,255,.65);

    border: 1px solid rgba(255,255,255,.16);

    background:
        linear-gradient(
            135deg,
            rgba(10,15,30,.78),
            rgba(0,0,0,.45)
        );

    backdrop-filter: blur(8px);

    font-size: 30px;

    transition:
        transform .35s ease,
        color .35s ease,
        background .35s ease,
        border-color .35s ease,
        box-shadow .35s ease;
}


/* =========================================================
   HOVER
========================================================= */

.cadillac-social-top a:hover {
    color: #fff;

    background:#333333;

    border-color:#FFFFFF ;

    transform:
        translateY(-5px)
        scale(1.08);

    box-shadow:
        0 8px 22px rgba(255,255,255,.35),
        0 0 15px rgba(255,255,255,.15);
}


/* =========================================================
   LINHA DECORATIVA
========================================================= */

.cadillac-social-top::before,
.cadillac-social-top::after {
    content: "";

    width: 55px;
    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.7)
        );
}


.cadillac-social-top::after {
    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.7),
            transparent
        );
}


/* =========================================================
   LOGO cadillac
========================================================= */

.cadillac-logo {
    position: absolute;

    z-index: 8;

    right: 4vw;
    top: -50px;

    width: 300px;
    height: 300px;

    display: flex;
    align-items: center;
    justify-content: center;

    pointer-events: none;

    animation: cadillac-logo-float 4s ease-in-out infinite;
}


/* LOGO */

.cadillac-logo img {
    position: relative;

    z-index: 2;

    width: 100%;
    height: 100%;

    object-fit: contain;

    display: block;

    filter: drop-shadow(0 5px 15px rgba(0,0,0,.6));
}


/* =========================================================
   ANIMAÇÃO DA LOGO
========================================================= */

@keyframes cadillac-logo-float {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-7px);
    }

}


/* =========================================================
   GLOW DA LOGO
========================================================= */

.cadillac-logo-glow {
    position: absolute;

    z-index: 1;

    width: 220px;
    height: 220px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(3,3,3,.3),
            rgba(3,3,3,.15),
