/* =========================================================
   GRID
========================================================= */

.linha-evolution-grid-cadillac {
    position: relative;

    z-index: 2;

    width: 100%;

    height: calc(100% - 145px);

    display: flex;
    align-items: center;
    justify-content: center;
    grid-template-columns:
        repeat(5, 1fr);

    gap: 3px;

    max-width: 1500px;

    margin: auto;
}

.linha-evolution-grid-cadillac
.linha-evolution-team-cadillac {
    width: min(420px, 70vw);
    height: 100%;
    flex: 0 0 min(420px, 70vw);
}
/* =========================================================
   CARD
========================================================= */

.linha-evolution-team-cadillac {
    position: relative;

    min-width: 0;

    overflow: hidden;

    cursor: pointer;

    background: #0a0e0f;

    border-left:
        1px solid rgba(255,255,255,.05);

    transition:
        flex .6s cubic-bezier(.2,.8,.2,1),
        transform .5s ease,
        background .6s ease,
        opacity .5s ease;
}


/* Quando houver hover em alguma equipe */

.linha-evolution-grid-cadillac:hover
.linha-evolution-team-cadillac {
    opacity: .45;
}


/* Equipe em hover */

.linha-evolution-grid-cadillac
.linha-evolution-team-cadillac:hover {

    opacity: 1;

    z-index: 5;

    transform:
        translateY(-8px);
}


/* =========================================================
   NÚMERO GIGANTE
========================================================= */

.team-bg-number-cadillac {
    position: absolute;

    top: -25px;

    right: -10px;

    font-size:
        clamp(100px, 14vw, 230px);

    line-height: 1;

    font-weight: 900;

    letter-spacing: -12px;

    color:
        rgba(255,255,255,.050);

    pointer-events: none;

    transition:
        color .6s ease,
        transform .6s ease;
}


.linha-evolution-team-cadillac:hover
.team-bg-number-cadillac {

    transform:
        translateX(-15px)
        scale(1.05);

    color:
        rgba(255,255,255,.78);
}


/* =========================================================
   IMAGEM
========================================================= */

.team-image-cadillac {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 72%;

    height: 62%;

    transform:
        translate(-50%, -50%);

    display: flex;

    align-items: center;

    justify-content: center;

    z-index: 1;

    transition:
        transform .7s cubic-bezier(.2,.8,.2,1),
        width .6s ease,
        height .6s ease;
}


/* Glow atrás da imagem */

.team-image-cadillac::after {

    content: "";

    position: absolute;

    inset: -20%;

    border-radius: 50%;

    background:
        var(--team-glow);

    filter: blur(45px);

    opacity: .08;

    transition:
        opacity .5s ease,
        transform .5s ease;
}


/* Imagem */

.team-image-cadillac img {

    position: relative;

    z-index: 2;

    width: 100%;

    height: 100%;

    object-fit: contain;

    display: block;

    filter:
        grayscale(100%)
        brightness(.55);

    opacity: .55;

    transition:
        filter .7s ease,
        opacity .7s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


/* Imagem aumenta no hover */

.linha-evolution-team-cadillac:hover
.team-image-cadillac {

    width: 82%;

    height: 70%;

    transform:
        translate(-50%, -54%)
        scale(1.05);
}


/* Glow aumenta */

.linha-evolution-team-cadillac:hover
.team-image-cadillac::after {

    opacity: .4;

    transform:
        scale(1.2);
}


/* Imagem ganha cor */

.linha-evolution-team-cadillac:hover
.team-image-cadillac img {

    filter:
        grayscale(0%)
        brightness(1);

    opacity: 1;

    transform:
        scale(1.05);
}


/* =========================================================
   CONTEÚDO
========================================================= */

.team-content-cadillac {

    position: absolute;

    z-index: 5;

    left: 18px;

    right: 18px;

    bottom: 22px;

    text-align: left;

    transition:
        transform .5s ease;
}


.linha-evolution-team-cadillac:hover
.team-content-cadillac {

    transform:
        translateY(-5px);
}

/* Período */

.team-era-cadillac {

    display: block;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.45);

    margin-bottom: 4px;
}


/* Nome */

.team-content-cadillac h3 {

    margin: 0;

    padding: 0;

    font-size:
        clamp(19px, 2.2vw, 31px);

    line-height: .95;

    font-weight: 900;

    letter-spacing: 1px;

    color: #fff;

    text-shadow:
        0 3px 20px rgba(0,0,0,.9);
}


/* Linha */

.team-line-cadillac {

    width: 28px;

    height: 2px;

    margin: 7px 0 5px;

    background:
        var(--team-color);

    box-shadow:
        0 0 10px var(--team-color);

    transition:
        width .5s ease;
}


.linha-evolution-team-cadillac:hover
.team-line-cadillac {

    width: 65px;
}


/* Função */

.team-role-cadillac {

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 2px;

    color:
        rgba(255,255,255,.55);
}


/* =========================================================
   SETA
========================================================= */

.team-arrow-cadillac {

    position: absolute;

    z-index: 6;

    top: 18px;

    left: 18px;

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid rgba(255,255,255,.15);

    font-size: 12px;

    color:
        rgba(255,255,255,.4);

    opacity: .5;

    transition:
        .4s ease;
}


.linha-evolution-team-cadillac:hover
.team-arrow-cadillac {

    opacity: 1;

    color:
        var(--team-color);

    border-color:
        var(--team-color);

    transform:
        rotate(45deg);

    box-shadow:
        0 0 15px rgba(255,255,255,.08);
}


/* =========================================================
   CORES DAS EQUIPES
========================================================= */





/* =========================================================
   cadillac ATUAL
========================================================= */

.team-cadillac-current {

    --team-color: #F0F0F0;

    --team-glow:
        rgba(240,240,240,.8);
}


.team-cadillac-current:hover {

    background:
        linear-gradient(
            145deg,
            #071716,
            #050708 70%
        );

    border-color:
        rgba(240,240,240,.18);
}


.team-cadillac-current
.team-content-cadillac h3 {

    color: #F0F0F0;
}


.team-cadillac-current
.team-image-cadillac img {

    filter:
        grayscale(0%)
        brightness(.95);

    opacity: .85;
}


/* =========================================================
   FOOTER
========================================================= */

.linha-evolution-footer-cadillac {

    position: absolute;

    z-index: 10;

    left: 4vw;

    right: 4vw;

    bottom: 15px;

    display: flex;

    align-items: center;

    gap: 12px;

    font-size: 13px;

    font-weight: 800;

    letter-spacing: 3px;

    color:
        rgba(240,240,240,.25);
}


.footer-line-cadillac {

    height: 1px;

    flex: 1;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.12)
        );
}


.footer-line-cadillac:last-of-type {

    background:
        linear-gradient(
            90deg,
            rgba(255,255,255,.12),
            transparent
        );
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 900px) {

    .cadillac-linha-evolution {

        padding-left: 20px;

        padding-right: 20px;
    }


    .linha-evolution-grid-cadillac {

        grid-template-columns:
            repeat(
                5,
                minmax(120px, 1fr)
            );

        overflow-x: auto;

        scrollbar-width: none;
    }


    .linha-evolution-grid-cadillac::-webkit-scrollbar {

        display: none;
    }


    .linha-evolution-team-cadillac {

        min-width: 150px;
    }


    .team-content-cadillac {

        left: 14px;

        right: 14px;

        bottom: 18px;
    }

}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .cadillac-linha-evolution {

        height: auto;

        min-height: 100dvh;

        padding:
            32px 15px 55px;
    }


    .linha-evolution-header-cadillac {

        margin-bottom: 18px;
    }


    .linha-evolution-header-cadillac > span {

        font-size: 6px;

        letter-spacing: 2px;
    }


    .linha-evolution-header-cadillac h2 {

        font-size: 28px;
    }


    .linha-evolution-header-cadillac p {

        font-size: 8px;
    }


    .linha-evolution-grid-cadillac {

        height: 62dvh;

        grid-template-columns:
            repeat(5, 145px);

        gap: 3px;

        overflow-x: auto;

        padding-bottom: 8px;
    }


    .linha-evolution-team-cadillac {

        min-width: 145px;
    }


    .team-image-cadillac {

        width: 75%;

        height: 55%;
    }


    .team-content-cadillac {

        left: 12px;

        bottom: 15px;
    }


    .team-content-cadillac h3 {

        font-size: 19px;
    }


    .team-bg-number-cadillac {

        font-size: 110px;
    }


    .team-arrow-cadillac {

        top: 12px;

        left: 12px;

        width: 22px;

        height: 22px;
    }


    .linha-evolution-footer-cadillac {

        left: 15px;

        right: 15px;
    }

}


.tabela-cadillac{
    padding:clamp(80px, 12vw, 140px) 20px;

    background:
    linear-gradient(
      120deg,
      #050505 0%,
      #1a1a1a 20%,
      #4f3d1c 45%,
      #8c6a2d 75%,
      #d4b06a 100%
    );

    color:#fff;

    position:relative;

    overflow:hidden;
}

/* brilho fundo */
.tabela-cadillac::before{
    content:"";

    position:absolute;

    top:-200px;
    left:-200px;

    width:500px;
    height:500px;

    background:
    radial-gradient(
      circle,
      rgba(212,176,106,.18),
      transparent 70%
    );

    filter:blur(40px);

    animation:cadillacGlow 8s ease-in-out infinite;

    z-index:0;
}

.tabela-cadillac::after{
    content:"";

    position:absolute;

    right:-180px;
    bottom:-180px;

    width:420px;
    height:420px;

    background:
    radial-gradient(
      circle,
      rgba(255,255,255,.08),
      transparent 70%
    );

    filter:blur(50px);

    z-index:0;
}

/* conteúdo */
.tabela-cadillac > *{
    position:relative;
    z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-tabela-cadillac{
    text-align:center;

    font-size:clamp(28px, 4vw, 46px);

    margin-bottom:60px;

    display:flex;
    justify-content:center;
    align-items:center;
    gap:12px;

    font-weight:900;

    letter-spacing:1px;

    text-transform:uppercase;

    color:#ffffff;

    text-shadow:
      0 0 14px rgba(212,176,106,.45);
}

/* LOGO */
.logo-titulo-cad{
    width:clamp(28px, 4vw, 46px);

    filter:
    drop-shadow(
      0 0 12px rgba(212,176,106,.8)
    );

    transition:.35s ease;
}

.titulo-tabela-cadillac:hover .logo-titulo-cad{
    transform:
    scale(1.15)
    rotate(-4deg);
}

/* ===== BOX ===== */
.box-tabela-cadillac{
    width:90%;
    max-width:1500px;

    margin:auto;

    background:
    linear-gradient(
      180deg,
      rgba(0,0,0,.72),
      rgba(15,15,15,.88)
    );

    border-radius:24px;

    backdrop-filter:blur(10px);

    border:
    1px solid rgba(255,255,255,.08);

    overflow:hidden;

    box-shadow:
      0 0 40px rgba(212,176,106,.18),
      inset 0 0 30px rgba(255,255,255,.04);
}

/* ===== TABELA ===== */
.box-tabela-cadillac table{
    width:100%;

    border-collapse:collapse;

    min-width:600px;
}

/* ===== LINHAS ===== */
.box-tabela-cadillac tr{
    transition:
    .35s ease;
}

/* ===== CÉLULAS ===== */
.box-tabela-cadillac td{
    padding:clamp(18px, 2.5vw, 28px);

    font-size:clamp(15px, 2vw, 20px);

    border-bottom:
      1px solid rgba(255,255,255,0.08);
}

/* PRIMEIRA COLUNA */
.box-tabela-cadillac td:first-child{
    color:#f4d08a;

    font-weight:800;

    width:50%;

    letter-spacing:.4px;
}

/* SEGUNDA COLUNA */
.box-tabela-cadillac td:last-child{
    text-align:right;

    color:#f5f5f5;

    font-weight:500;
}

/* ===== HOVER ===== */
.box-tabela-cadillac tr:hover{
    background:
    linear-gradient(
      90deg,
      rgba(212,176,106,.18),
      rgba(255,255,255,.06)
    );

    transform:scale(1.01);

    box-shadow:
      inset 0 0 18px rgba(212,176,106,.12);
}

/* ===== ANIMAÇÃO ===== */
@keyframes cadillacGlow{

  0%,100%{
    transform:translate(0,0) scale(1);
  }

  50%{
    transform:translate(50px,30px) scale(1.08);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .tabela-cadillac{
    padding:90px 15px;
  }

  .box-tabela-cadillac{
    width:95%;

    overflow:hidden;
  }

  .box-tabela-cadillac table{
    width:100%;

    min-width:100%;
  }

  .box-tabela-cadillac td{
    padding:12px 10px;

    font-size:16px;
  }

  .box-tabela-cadillac td:first-child{
    width:45%;

    font-size:15px;
  }

  .box-tabela-cadillac td:last-child{
    width:55%;

    font-size:16px;

    text-align:right;

    word-break:break-word;
  }

  .titulo-tabela-cadillac{
    font-size:22px;

    gap:8px;
  }
}


