/*==================================================
        BARRAS

        CENTRO → ESQUERDA
        CENTRO → DIREITA
==================================================*/
/*==================================================
        BARRAS DAS ESTATÍSTICAS
==================================================*/

.cadillac-bars{

    width:100%;

    height:11px;

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:0;

    margin-top:5px;

    overflow:hidden;

}


/* BASE */

.cadillac-bar-left,
.cadillac-bar-right{

    height:100%;

    position:relative;

    background:transparent;

    overflow:hidden;

}


/*==================================================
        BARRA DO NORRIS
        COMEÇA NO CENTRO → ESQUERDA
==================================================*/

.cadillac-bar-left{

    border-radius:999px 0 0 999px;

}


.cadillac-bar-left::after{

    content:"";

    position:absolute;

    top:0;
    right:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #030303,
        #ffffff
    );

    border-radius:999px 0 0 999px;

    transition:width .8s ease;

}


/*==================================================
        BARRA DO PIASTRI
        COMEÇA NO CENTRO → DIREITA
==================================================*/

.cadillac-bar-right{

    border-radius:0 999px 999px 0;

}


.cadillac-bar-right::after{

    content:"";

    position:absolute;

    top:0;
    left:0;

    height:100%;

    width:var(--size,50%);

    background:
    linear-gradient(
        90deg,
        #ffffff,
        #030303
    );

    border-radius:0 999px 999px 0;

    transition:width .8s ease;

}







/*==================================================
        ANIMAÇÃO DOS NÚMEROS
==================================================*/

.cadillac-value{

    animation:
    cadillacValueShow .5s ease;

}


@keyframes cadillacValueShow{

    from{

        opacity:0;

        transform:translateY(8px);

    }

    to{

        opacity:1;

        transform:translateY(0);

    }

}


