.lideranca-cadillac{
  padding:90px 20px;

  background:
  linear-gradient(
    120deg,
    #050505 0%,
    #1a1a1a 25%,
    #5f4720 60%,
    #d4b06a 100%
  );

  text-align:center;

  position:relative;

  overflow:hidden;
}

/* GLOW FUNDO */
.lideranca-cadillac::before{
  content:"";

  position:absolute;

  top:-220px;
  left:-220px;

  width:450px;
  height:450px;

  background:
  radial-gradient(
    circle,
    rgba(212,176,106,.18),
    transparent 70%
  );

  filter:blur(45px);

  animation:cadillacLeaderGlow 8s ease-in-out infinite;
}

.lideranca-cadillac > *{
  position:relative;
  z-index:2;
}

/* ===== TÍTULO ===== */
.titulo-lideranca-cadillac{
  font-size:42px;

  color:#fff7e8;

  margin-bottom:65px;

  letter-spacing:1px;

  text-shadow:
  0 0 15px rgba(212,176,106,.28);
}

.titulo-lideranca-cadillac::after{
  content:"";

  width:180px;
  height:3px;

  display:block;

  margin:16px auto 0;

  background:
  linear-gradient(
    90deg,
    transparent,
    #d4b06a,
    transparent
  );

  box-shadow:
  0 0 12px rgba(212,176,106,.6);
}

/* ===== CONTAINER ===== */
.container-lideranca-cadillac{
  display:flex;

  justify-content:center;

  gap:30px;

  flex-wrap:wrap;
}

/* ===== CARD ===== */
.card-lider-cadillac{
  position:relative;

  width:280px;

  padding:24px;

  border-radius:24px;

  overflow:hidden;

  background:
  linear-gradient(
    145deg,
    rgba(20,20,20,.95),
    rgba(70,55,25,.95)
  );

  border:
  1px solid rgba(212,176,106,.22);

  color:#fff;

  transition:.45s ease;

  box-shadow:
  0 15px 35px rgba(0,0,0,.35);
}

/* LINHA TOPO */
.card-lider-cadillac::before{
  content:"";

  position:absolute;

  top:0;
  left:0;

  width:100%;
  height:3px;

  background:
  linear-gradient(
    90deg,
    transparent,
    #d4b06a,
    transparent
  );
}

/* REFLEXO */
.card-lider-cadillac::after{
  content:"";

  position:absolute;

  top:0;
  left:-100%;

  width:100%;
  height:100%;

  background:
  linear-gradient(
    120deg,
    transparent,
    rgba(255,255,255,.12),
    transparent
  );

  transition:.7s;
}

.card-lider-cadillac:hover::after{
  left:120%;
}

/* ===== IMAGEM ===== */
.card-lider-cadillac img{
  width:100%;
  height:280px;

  object-fit:cover;
  object-position:top;

  border-radius:18px;

  margin-bottom:18px;

  transition:.4s ease;

  filter:
  brightness(.96)
  drop-shadow(
    0 0 12px rgba(212,176,106,.18)
  );
}

/* ===== NOME ===== */
.card-lider-cadillac h3{
  font-size:24px;

  margin-bottom:6px;

  color:#ffffff;
}

/* ===== CARGO ===== */
.card-lider-cadillac span{
  display:block;

  margin-bottom:14px;

  color:#f0d39a;

  font-weight:800;

  font-size:15px;

  letter-spacing:1px;

  text-transform:uppercase;
}

/* ===== TEXTO ===== */
.card-lider-cadillac p{
  font-size:15px;

  line-height:1.7;

  color:#f8f1e5;

  border-left:
  3px solid #d4b06a;

  padding-left:12px;

  transition:.35s ease;
}

/* ===== HOVER ===== */
.card-lider-cadillac:hover{
  transform:
  translateY(-12px)
  scale(1.03);

  border-color:
  rgba(212,176,106,.45);

  box-shadow:
  0 20px 45px rgba(0,0,0,.45),
  0 0 30px rgba(212,176,106,.18);
}

.card-lider-cadillac:hover img{
  transform:scale(1.05);

  filter:brightness(1);
}

.card-lider-cadillac:hover p{
  transform:translateY(-2px);
}

/* ===== ANIMAÇÃO ===== */
@keyframes cadillacLeaderGlow{

  0%,100%{
    transform:translate(0,0);
  }

  50%{
    transform:translate(45px,30px);
  }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

  .lideranca-cadillac{
    padding:70px 16px;
  }

  .titulo-lideranca-cadillac{
    font-size:30px;
