    letter-spacing:1px;

    cursor:pointer;

    overflow:hidden;

    transition:.45s ease;

    box-shadow:
    0 10px 25px rgba(0,0,0,.35);

    border:
    1px solid rgba(250,250,250,.12);
}

/* brilho botão */
.botoes-eras-cadillac button::before{
    content:"";

    position:absolute;

    top:0;
    left:-120%;

    width:100%;
    height:100%;

    background:
    linear-gradient(
      120deg,
      transparent,
      rgba(255,255,255,.4),
      transparent
    );

    transition:.7s;
}

.botoes-eras-cadillac button:hover::before{
    left:120%;
}

/* ===== HOVER ===== */
.botoes-eras-cadillac button:hover{
    transform:
    translateY(-6px)
    scale(1.05);

    background:
    linear-gradient(
      145deg,
      #000,
      #fff
    );

    color:#001b19;

    box-shadow:
    0 0 30px rgba(250,255,250,.35);
}

/* ===== BOTÃO ATIVO ===== */
.botoes-eras-cadillac .ativo{
    background:
    linear-gradient(
      145deg,
      #fff,
      #000
    );

    color:#ff1;

    box-shadow:
    0 0 30px rgba(255,255,228,.45),
    0 10px 35px rgba(0,0,0,.35);

    transform:scale(1.06);
}

/* ===== TIMELINE ===== */
#cadillac-timeline{
    display:grid;

    grid-template-columns:
    repeat(auto-fit,minmax(240px,1fr));

    gap:28px;

    margin-top:30px;

    max-width:1400px;

    margin-inline:auto;
}

/* ===== CARDS ===== */
.cadillac-timeline-item{
    position:relative;

    padding:22px;

    border-radius:26px;

    overflow:hidden;

    background:
    linear-gradient(
      180deg,
      rgba(255,255,255,.08),
      rgba(255,255,255,.03)
    );

    backdrop-filter:blur(14px);

    border:
    1px solid rgba(5,5,8,.12);

    transition:.5s ease;

    box-shadow:
    0 15px 35px rgba(0,0,0,.3);
}

/* brilho */
.cadillac-timeline-item::before{
    content:"";

    position:absolute;

    inset:0;

    background:
    linear-gradient(
      140deg,
      rgba(255,255,255,.12),
      transparent 45%
    );

    opacity:0;

    transition:.45s;
}

.cadillac-timeline-item:hover::before{
    opacity:1;
}

/* ===== HOVER CARD ===== */
.cadillac-timeline-item:hover{
    transform:
    translateY(-14px)
    scale(1.03);

    border-color:
    rgba(255,255,228,.4);

    box-shadow:
    0 20px 50px rgba(0,0,0,.45),
    0 0 35px rgba(250,255,250,.18);
}

/* ===== IMAGEM ===== */
.cadillac-timeline-item img{
    width:100%;
    height:150px;

    object-fit:contain;

    border-radius:16px;

    margin-bottom:18px;

    transition:.5s ease;

    filter:
    drop-shadow(
      0 10px 20px rgba(0,0,0,.4)
    );
}

.cadillac-timeline-item:hover img{
    transform:
    scale(1.08)
    rotate(-1deg);

    filter:
    drop-shadow(
      0 15px 25px rgba(250,255,250,.28)
    );
}

/* ===== ANO ===== */
.cadillac-year{
    font-size:1.4rem;

    font-weight:900;

    margin-bottom:10px;

    color:#ffff;

    text-shadow:
    0 0 12px rgba(0,2,2,.3);
}

/* ===== TEXTO ===== */
#cadillac-timeline p{
    font-size:1rem;

    line-height:1.7;

    color:#fffffb;

    opacity:.92;
}

/* ===== ANIMAÇÃO ===== */
@keyframes cadillacGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(60px,40px) scale(1.15);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .eras-cadillac{
        padding:90px 18px;
    }

    .titulo-eras-cadillac{
        font-size:2.5rem;
    }

    #textoEra-cadillac{
        font-size:1rem;
    }

    .botoes-eras-cadillac{
        gap:10px;
    }

    .botoes-eras-cadillac button{
        padding:12px 18px;
        font-size:.85rem;
    }

    #cadillac-timeline{
        grid-template-columns:1fr;
    }

    .cadillac-timeline-item{
        max-width:360px;
        margin:auto;
    }

}

/* =========================================================
   FOOTER
========================================================= */

.footer-f1-cadillac{
  background:linear-gradient(135deg,#050505 0%,#1b1b1b 45%,#d4b06a 100%);

    color:#fffffb;

    padding:70px 25px;

    text-align:center;

    position:relative;

    overflow:hidden;
}

/* brilho fundo */
.footer-f1-cadillac::before{
    content:"";

    position:absolute;

    width:500px;
    height:500px;

    top:-200px;
    left:-200px;

    background:
    radial-gradient(
      circle,
      rgba(0,5,0,.18),
      transparent 70%
    );

    filter:blur(40px);

    animation:cadillacFooterGlow 7s ease-in-out infinite;
}

/* brilho extra */
.footer-f1-cadillac::after{
    content:"";

    position:absolute;

    right:-180px;
    bottom:-180px;

    width:420px;
    height:420px;

    background:
    radial-gradient(
      circle,
      rgba(255,255,255,.08),
      transparent 70%
    );

    filter:blur(50px);
}

/* ===== CONTEÚDO ===== */
.footer-f1-cadillac > *{
    position:relative;
    z-index:2;
}

/* ===== BRAND ===== */
.footer-brand-cadillac p{
    font-size:34px;

    font-weight:900;

    letter-spacing:3px;

    color:#ffffff;

    margin-bottom:8px;

    text-shadow:
    0 0 15px rgba(0,5,10,.45);
}

.footer-brand-cadillac span{
    font-size:20px;

    color:#fff;

    opacity:.9;
}

/* ===== LINKS ===== */
.footer-links-cadillac,
.footer-social-cadillac{
    margin-top:28px;

    display:flex;

    justify-content:center;

    flex-wrap:wrap;

    gap:18px;
}

.footer-links-cadillac a,
.footer-social-cadillac a{
    position:relative;

    color:#fffffb;

    text-decoration:none;

    font-weight:700;

    font-size:16px;

    padding:10px 14px;

    border-radius:12px;

    transition:.35s ease;
}

/* underline glow */
.footer-links-cadillac a::after,
.footer-social-cadillac a::after{
    content:"";

    position:absolute;

    left:50%;
    bottom:0;

    width:0%;
    height:2px;

    background:#000;

    transition:.35s ease;

    transform:translateX(-50%);
}

/* ===== HOVER ===== */
.footer-links-cadillac a:hover,
.footer-social-cadillac a:hover{
    color:#000000;

    background:
    rgba(255,255,255,.06);

    text-shadow:
    0 0 12px rgba(250,255,250,.4);
}

.footer-links-cadillac a:hover::after,
.footer-social-cadillac a:hover::after{
    width:80%;
