/* ===== COPYRIGHT ===== */
.footer-copy-cadillac{
    margin-top:35px;

    font-size:14px;

    color:#fffff2;

    opacity:.8;

    letter-spacing:.5px;
}

/* ===== BOTÃO TO TOP ===== */
.back-to-top-cadillac{
    position:fixed;

    right:20px;
    bottom:20px;

    background:
    linear-gradient(
      145deg,
      #000,
      #fff
    );

    color:#ffffff;

    border:none;

    padding:14px 16px;

    border-radius:16px;

    cursor:pointer;

    font-weight:800;

    z-index:999;

    box-shadow:
    0 0 20px rgba(250,255,20,.25);

    transition:.35s ease;
}

.back-to-top-cadillac:hover{
    transform:
    translateY(-6px)
    scale(1.08);

    box-shadow:
    0 0 35px rgba(250,255,20,.45);
}

/* ===== ANIMAÇÃO ===== */
@keyframes cadillacFooterGlow{

    0%,100%{
        transform:translate(0,0) scale(1);
    }

    50%{
        transform:translate(50px,30px) scale(1.1);
    }

}

/* ===== RESPONSIVO ===== */
@media(max-width:768px){

    .footer-f1-cadillac{
        padding:60px 18px;
    }

    .footer-brand-cadillac p{
        font-size:26px;
    }

