.radio-f1-lando {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* 🔴 STATUS */
.radio-status-lando {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #ff8000;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-lando::before {
  content: "●";
  margin-right: 6px;
  animation: blink 1s infinite;
}

@keyframes blink {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-lando {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: white;
}

/* CARD */
.card-lando {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-lando::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(255,128,0,0.15), transparent);
  z-index: -1;
}

.card-lando.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-lando.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-lando {
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-lando {
  font-size: 120px;
  color: #ff8000;
}

/* DIREITA */
.right-lando {
  position: absolute;
  top: 20px;
  right: 15px;
  text-align: right;
}

.right-lando h1 {
  color: #ff8000;
  margin: 0;
}

.right-lando h2 {
  color: white;
  margin: 0;
}

.logo-lando {
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-lando {
  position: absolute;
  top: 160px;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  align-items: flex-end;
}

.wave-lando span {
  flex: 1;
  margin: 0 1px;
  height: 6px;

  background: linear-gradient(to top, #ff8000, transparent);

  animation: wave infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-lando.falando .wave-lando span {
  animation-play-state: running;
}

@keyframes wave {
  0%,100% { height: 6px; opacity: 0.3 }
  50% { height: 45px; opacity: 1 }
}

/* CONTEÚDO */
.content-lando {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}

/* TEXTO ANIMADO */
.text-lando {
  padding: 10px 15px;
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.4s ease;
}

.card-lando.mostrar-texto .text-lando {
  opacity: 1;
  transform: translateY(0);
}

.eng-lando {
  color: white;
  font-size: 20px;
}

.pil-lando {
  color: #ff8000;
  text-align: right;
  font-size: 20px;
}




