}
/* RESPONSIVO */
@media(max-width: 768px){

  .slide-lando img {
    height: 300px;
  }

  .slide-lando-texto h3 {
    font-size: 20px;
  }

  .slide-lando-texto p {
    font-size: 14px;
  }
}

/* ==========================================
   ESTATÍSTICAS lando
========================================== */

.numeros-lando{
  background: linear-gradient(120deg, #000 0%, #000 55%, #ff8000 80%, #ffcc80 100%);
  position: relative;
  min-height: 650px;
  padding: 80px 0;
  overflow: hidden;
}

.numeros-lando::after{
  content:"";
  position:absolute;
  inset:0;

  background: radial-gradient(
    circle at center,
    transparent 40%,
    rgba(0,0,0,0.85) 100%
  );

  z-index:1;
}

.bg-numeros-lando{
  filter: blur(3px) brightness(0.6);
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:100%;
  object-fit:cover;
  z-index:0;
}

.overlay-numeros-lando{
  position:absolute;
  inset:0;
  z-index:1;
}

.titulo-numeros-lando{
  position:relative;
  z-index:2;
  text-align:center;
  color:#ff8000;
  font-size:44px;
  margin-bottom:40px;
}

.stats-grid-lando{
  position: relative;
  z-index: 2;

  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 25px;
  padding: 0 40px;
}

.card-stat-lando{
  background: rgba(0,0,0,0.65);
  backdrop-filter: blur(10px);
  border-radius:18px;
  padding: clamp(18px, 3vw, 30px);
  text-align:center;
  color:white;

  box-shadow:0 10px 30px rgba(0,0,0,0.6);
  border:1px solid #ff8000;

  opacity:0;
  transform:translateY(60px);
  transition:0.6s ease;
}

.card-stat-lando.ativo{
  opacity:1;
  transform:translateY(0);
  animation:glowlando 2s infinite alternate;
}

@keyframes glowlando{
  from{box-shadow:0 0 10px #ff8000;}
  to{box-shadow:0 0 30px #ff8000;}
}

.card-stat-lando span{
  font-size: clamp(32px,5vw,60px);
  font-weight:bold;
  display:block;
  color:#ff8000;
  text-shadow: 0 0 10px rgba(0,0,0,0.9);
}

.card-stat-lando p{
  margin-top:10px;
  font-size:25px;
  color:#ff8000;
}

.card-stat-lando:hover{
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 0 40px rgba(255,128,0,0.4);
}

.grande-lando{
  grid-column:span 3;
}

.barra-velocidade-lando{
  height:6px;
  background: linear-gradient(90deg, #ff8000, #ffcc80);
  box-shadow: 0 0 10px #ff8000;
  width:0%;
  margin-top:10px;
  border-radius:10px;
  transition:width 0.3s;
}

/* LUZ */
.luz-lando{
  position:absolute;
  width:600px;
  height:600px;
  background:radial-gradient(circle,#ff8000,transparent 70%);
  top:-200px;
  right:-200px;
  opacity:0.2;
  animation:pulsarlando 4s infinite alternate;
  z-index:1;
}

@keyframes pulsarlando{
  from{transform:scale(1);}
  to{transform:scale(1.3);}
}

/* MOBILE */
@media (max-width: 768px){
  .stats-grid-lando{
    grid-template-columns:1fr;
    padding:0 15px;
    gap:15px;
  }

  .grande-lando{
    grid-column:span 1;
  }
}






/* =========================================================
   lando — TIMELINE
========================================================= */

.lando-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(255,128,0,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.lando-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.lando-timeline-title{
  color:#Ff8000;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(255,128,0,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.lando-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.lando-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.lando-ano-btn:hover{
  background:rgba(255,128,0,0.15);

  color:#Ff8000;

  transform:translateY(-2px);
}


.lando-ano-btn.active{
  background:#Ff8000;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,128,0,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.lando-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.lando-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.lando-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.lando-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.lando-team-change{
  position:relative;

  border:1px solid rgba(255,128,0,.45);

  box-shadow:
    0 0 20px rgba(255,128,0,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-lando{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Ff8000,
      #6be7ff
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferlando .5s ease;
}


@keyframes transferlando{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.lando-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,128,0,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.lando-corrida-card:hover::before{
  opacity:1;
}


.lando-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,128,0,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.lando-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.lando-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.lando-vitoria .lando-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,128,0,0.25);

}


.lando-podio .lando-resultado{

  color:#ff8000;

  text-shadow:
    0 0 10px rgba(255,128,0,0.2);

}


.lando-pontos .lando-resultado{

  color:#ffffff;

}


.lando-dnf .lando-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.lando-sem-pontos .lando-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.lando-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#ff8000;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.lando-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.lando-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

  opacity:0;

  transform:translateY(15px);

  transition:.4s ease;

  box-sizing:border-box;
}


.lando-summary-card.show{

  opacity:1;

  transform:translateY(0);

}


.lando-summary-title{

  color:#Ff8000;

  font-size:18px;

  font-weight:900;

  margin-bottom:10px;

  letter-spacing:1px;

}


.lando-summary-stats{

  display:flex;

  justify-content:space-between;

  gap:10px;
}


.lando-summary-box{

  flex:1;

  padding:7px;

  border-radius:9px;

  background:
    rgba(255,255,255,0.03);

  border:
    1px solid rgba(255,255,255,0.06);
}


.lando-summary-label{

  display:block;

  font-size:11px;

  color:#aaa;

  margin-bottom:3px;

  text-transform:uppercase;

  letter-spacing:1px;
}


.lando-summary-value{

  font-size:22px;

  font-weight:900;

  color:#fff;
}


/* =========================================================
   TABLET
========================================================= */

@media(max-width:900px){

  .lando-timeline{

    padding:
      25px 15px;

  }


  .lando-top-timeline{

