/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR norris
========================================================= */

.pilotagem-norris {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(255, 128, 0, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(255, 128, 0, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-norris {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-norris {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(255, 128, 0, .10);

    border:
        1px solid
        rgba(255, 128, 0, .35);

    color: #ff8000;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-norris {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-norris span {
    color: #ff8000;
}


.pilotagem-intro-norris {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-norris {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-norris {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(255, 128, 0, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-norris::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255, 128, 0, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-norris {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-norris {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-norris:hover
.perfil-imagem-norris {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-norris::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-norris {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-norris {
    display: block;

    margin-bottom: 8px;

    color: #ff8000;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-norris {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-norris span {
    display: block;

    color: #ff8000;
}


.perfil-equipe-norris {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-norris {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-norris i {
    color: #ff8000;

    font-size: 20px;
}


.perfil-frase-norris p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-norris {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-norris {
    display: block;

    margin-bottom: 12px;

    color: #ff8000;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-norris h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-norris h3 span {
    display: block;

    color: #ff8000;
}


.pilotagem-analise-norris > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-norris {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-norris {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-norris:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(255,128,0,.5);

    background:
        rgba(255,128,0,.06);
}


.caracteristica-icone-norris {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,128,0,.10);

    color: #ff8000;
}

.caracteristica-icone-norris i{
	font-size: 40px;

	}



.caracteristica-norris h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-norris p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-norris {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-norris {
    margin-bottom: 35px;
}


.skills-header-norris > span {
    display: block;

    margin-bottom: 10px;

    color: #ff8000;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-norris h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-norris h3 span {
    color: #ff8000;
}


/* GRID */

.skills-grid-norris {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-norris {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-norris:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(255,128,0,.35);
}


.skill-topo-norris {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-norris {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-norris i {
    color: #ff8000;

    font-size: 26px;
}


.skill-numero-norris {
    color: #ff8000;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-norris::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-norris {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-norris {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #ff8000,
            #ffb14a
        );

    box-shadow:
        0 0 12px
        rgba(255,128,0,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-norris {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-norris {
    margin-bottom: 35px;
}


.grafico-header-norris > span {
    display: block;

    margin-bottom: 10px;

    color: #ff8000;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-norris h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-norris h3 span {
    color: #ff8000;
}


.grafico-layout-norris {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-norris {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-norris {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-norris {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-norris {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-norris {
    fill:
        rgba(255,128,0,.20);

    stroke: #ff8000;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,128,0,.35)
        );
}


.radar-ponto-norris {
    fill: #ff8000;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-norris {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-norris {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-norris {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-norris {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-norris {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-norris {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-norris {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-norris {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-norris {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-norris:hover {
    transform:
        translateX(6px);
}


.resumo-icone-norris {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,128,0,.10);

    color: #ff8000;

    font-size: 18px;
}


.resumo-card-norris > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-norris h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-norris p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-norris {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,128,0,.12),
            rgba(255,128,0,.02)
        );

    border:
        1px solid
        rgba(255,128,0,.25);
}


.pilotagem-conclusao-norris::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,128,0,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-norris > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-norris > span {
    display: block;

    margin-bottom: 18px;

    color: #ff8000;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-norris h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-norris strong {
    color: #ff8000;
}


.pilotagem-conclusao-norris p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-norris {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-norris.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-norris {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-norris {
        min-height: 600px;
    }


    .grafico-layout-norris {
        grid-template-columns: 1fr;

