  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.piastri-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.piastri-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.piastri-team-change{
  position:relative;

  border:1px solid rgba(255,128,0,.45);

  box-shadow:
    0 0 20px rgba(255,128,0,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-piastri{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Ff8000,
      #Ff8000
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferpiastri .5s ease;
}


@keyframes transferpiastri{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.piastri-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,128,0,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.piastri-corrida-card:hover::before{
  opacity:1;
}


.piastri-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,128,0,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.piastri-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.piastri-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.piastri-vitoria .piastri-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,128,0,0.25);

}


.piastri-podio .piastri-resultado{

  color: #ff8000 ;

  text-shadow:
    0 0 10px rgba(255,128,0,0.2);

}


.piastri-pontos .piastri-resultado{

  color:#ffffff;

}


.piastri-dnf .piastri-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.piastri-sem-pontos .piastri-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.piastri-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#ff8000;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.piastri-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.piastri-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

