    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(255, 128, 0, .10);

    border:
        1px solid
        rgba(255, 128, 0, .35);

    color: #ff8000;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-piastri {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-piastri span {
    color: #ff8000;
}


.pilotagem-intro-piastri {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-piastri {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-piastri {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(255, 128, 0, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-piastri::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255, 128, 0, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-piastri {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-piastri {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-piastri:hover
.perfil-imagem-piastri {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-piastri::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-piastri {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-piastri {
    display: block;

    margin-bottom: 8px;

    color: #ff8000;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-piastri {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-piastri span {
    display: block;

    color: #ff8000;
}


.perfil-equipe-piastri {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-piastri {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-piastri i {
    color: #ff8000;

    font-size: 20px;
}


.perfil-frase-piastri p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-piastri {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-piastri {
    display: block;

    margin-bottom: 12px;

    color: #ff8000;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-piastri h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-piastri h3 span {
    display: block;

    color: #ff8000;
}


.pilotagem-analise-piastri > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-piastri {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-piastri {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-piastri:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(255,128,0,.5);

    background:
        rgba(255,128,0,.06);
}


.caracteristica-icone-piastri {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,128,0,.10);

    color: #ff8000;
}

.caracteristica-icone-piastri i{
	font-size: 40px;

	}



.caracteristica-piastri h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-piastri p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-piastri {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-piastri {
    margin-bottom: 35px;
}


.skills-header-piastri > span {
    display: block;

    margin-bottom: 10px;

    color: #ff8000;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-piastri h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-piastri h3 span {
    color: #ff8000;
}


/* GRID */

.skills-grid-piastri {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-piastri {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-piastri:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(255,128,0,.35);
}


.skill-topo-piastri {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-piastri {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-piastri i {
    color: #ff8000;

    font-size: 26px;
}


.skill-numero-piastri {
    color: #ff8000;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-piastri::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-piastri {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-piastri {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #ff8000,
            #ffb14a
        );

    box-shadow:
        0 0 12px
        rgba(255,128,0,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-piastri {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-piastri {
    margin-bottom: 35px;
}


.grafico-header-piastri > span {
    display: block;

    margin-bottom: 10px;

    color: #ff8000;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-piastri h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-piastri h3 span {
    color: #ff8000;
}


.grafico-layout-piastri {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-piastri {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-piastri {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-piastri {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-piastri {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-piastri {
    fill:
        rgba(255,128,0,.20);

    stroke: #ff8000;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,128,0,.35)
        );
}


.radar-ponto-piastri {
    fill: #ff8000;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-piastri {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-piastri {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-piastri {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-piastri {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-piastri {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-piastri {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-piastri {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-piastri {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-piastri {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-piastri:hover {
    transform:
        translateX(6px);
}


.resumo-icone-piastri {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,128,0,.10);

    color: #ff8000;

    font-size: 18px;
}


.resumo-card-piastri > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-piastri h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-piastri p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-piastri {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,128,0,.12),
            rgba(255,128,0,.02)
        );

    border:
        1px solid
        rgba(255,128,0,.25);
}


.pilotagem-conclusao-piastri::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,128,0,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-piastri > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-piastri > span {
    display: block;

    margin-bottom: 18px;

    color: #ff8000;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-piastri h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-piastri strong {
    color: #ff8000;
}


.pilotagem-conclusao-piastri p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-piastri {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-piastri.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-piastri {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-piastri {
        min-height: 600px;
    }


    .grafico-layout-piastri {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-piastri {
        max-width: 430px;
    }


    .caracteristicas-piastri {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

    .pilotagem-piastri {
        padding:
            70px
            15px;
    }


    .pilotagem-header-piastri {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-piastri {
        font-size: 42px;

        letter-spacing: -2px;
    }


    /* PERFIL */

    .pilotagem-perfil-piastri {
        min-height: 500px;

        border-radius: 20px;
    }


    .perfil-info-piastri {
        padding:
            25px
            20px;
    }


    .perfil-nome-piastri {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-piastri {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-piastri h3 {
        font-size: 38px;
    }


    .pilotagem-analise-piastri > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-piastri {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-piastri {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-piastri {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-piastri {
        margin-top: 70px;
    }


    .skills-grid-piastri {
        grid-template-columns: 1fr;
    }


    .skill-card-piastri {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-piastri {
        margin-top: 70px;
    }


    .grafico-layout-piastri {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-piastri {
        width: 80%;
    }


    .radar-label-piastri {
        font-size: 7px;
    }


    .radar-top-right-piastri {
        right: -28px;
    }


    .radar-bottom-right-piastri {
        right: -35px;
    }


    .radar-bottom-left-piastri {
        left: -35px;
    }


    .radar-top-left-piastri {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-piastri {
        padding: 0 10px;
    }


    .resumo-card-piastri {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-piastri h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-piastri {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-piastri h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-piastri p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-piastri {
        font-size: 36px;
    }


    .pilotagem-perfil-piastri {
        min-height: 450px;
    }


    .perfil-nome-piastri {
        font-size: 38px;
    }


    .analise-topo-piastri h3 {
        font-size: 32px;
    }


    .skill-nome-piastri {
        font-size: 9px;
    }


    .radar-container-piastri {
        width: 78%;
    }


    .radar-label-piastri {
        font-size: 6px;
    }


    .resumo-card-piastri p {
        font-size: 11px;
    }

}


.galeria-piastri{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(255,128,0,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-piastri::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(255,128,0,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-piastri{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(255,128,0,.18);
}

/* GRID */
.grid-galeria-piastri{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
/* CARD */
.item-galeria-piastri{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-piastri img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-piastri:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
/* OVERLAY MODERNO */
.overlay-piastri{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-piastri:hover .overlay-piastri{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-piastri h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA DECORATIVA */
.overlay-piastri h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #ff8000,
    #ffb347
  );

  box-shadow:
  0 0 18px rgba(255,128,0,.5);
}

/* DESCRIÇÃO */
.overlay-piastri p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-piastri::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(255,128,0,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-piastri:hover::after{
  opacity:1;
}
/* LIGHTBOX */
.lightbox-piastri{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightbox .3s ease;
}

/* ANIMAÇÃO */
@keyframes fadeLightbox{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-piastri{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightbox .35s ease;
}

@keyframes zoomLightbox{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-piastri{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-piastri:hover{
  transform:rotate(90deg);

  background:
  rgba(255,128,0,.18);

  border-color:
  rgba(255,128,0,.35);

  color:#ff8000;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-piastri{
    grid-template-columns:1fr;
  }

  .overlay-piastri h3{
    font-size:20px;
  }

  .fechar-piastri{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

/* FOOTER */
.footer-f1-piastri{
  position:relative;
  overflow:hidden;

  padding:80px 25px 35px;

  background:
  radial-gradient(circle at top,
  rgba(255,128,0,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #080808 0%,
    #050505 100%
  );

  border-top:
  1px solid rgba(255,255,255,.06);

  display:flex;
  flex-direction:column;
  gap:45px;

  text-align:center;
}

/* BRILHO */
.footer-f1-piastri::before{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  top:-250px;
  left:50%;

  transform:translateX(-50%);

  background:
  radial-gradient(circle,
  rgba(255,128,0,.12),
  transparent 70%);

  filter:blur(100px);

  pointer-events:none;
}

/* CONTEÚDO */
.footer-f1-piastri > *{
  position:relative;
  z-index:2;
}

/* BRAND */
.footer-brand-piastri p{
  font-size:
  clamp(34px,5vw,58px);

  font-weight:1000;

  color:white;

  margin-bottom:10px;

  letter-spacing:-2px;

  text-transform:uppercase;

  text-shadow:
  0 0 25px rgba(255,128,0,.2);
}

.footer-brand-piastri span{
  display:block;

  color:#a5a5a5;

  font-size:15px;

  max-width:600px;

  margin:auto;

  line-height:1.6;
}

/* LINKS */
.footer-links-piastri,
.footer-social-piastri{
  display:flex;
  justify-content:center;
  flex-wrap:wrap;

  gap:16px;
}

/* BOTÕES */
.footer-links-piastri a,
.footer-social-piastri a{
  position:relative;

  padding:12px 22px;

  border-radius:999px;

  text-decoration:none;

  color:#e6e6e6;

  background:
  rgba(255,255,255,.03);

  border:
  1px solid rgba(255,255,255,.06);

  font-size:14px;
  font-weight:700;

  transition:
  transform .3s ease,
  background .3s ease,
  border-color .3s ease,
  color .3s ease;
}

/* HOVER */
.footer-links-piastri a:hover,
.footer-social-piastri a:hover{
  transform:
  translateY(-4px);

  background:
  rgba(255,128,0,.12);

  border-color:
  rgba(255,128,0,.25);

  color:#ff9f3f;

  box-shadow:
  0 10px 25px rgba(255,128,0,.12);
}

/* COPY */
.footer-copy-piastri{
  padding-top:15px;

  border-top:
  1px solid rgba(255,255,255,.05);

  color:#777;

  font-size:13px;

  letter-spacing:.5px;
}

/* MOBILE */
@media(max-width:768px){

  .footer-f1-piastri{
    gap:35px;
  }

  .footer-brand-piastri p{
    font-size:40px;
  }

  .footer-links-piastri,
  .footer-social-piastri{
    gap:12px;
  }

  .footer-links-piastri a,
  .footer-social-piastri a{
    width:100%;
    max-width:280px;
  }

}

.btn-topo-oscar{
    position:fixed;

    bottom:25px;
    right:25px;

    width:55px;
    height:55px;

    border:none;
    border-radius:50%;

    cursor:pointer;

    display:flex;
