/* =========================
   BANNER PRINCIPAL
========================= */

.russel-banner-bg{
  position: relative;

  width: 100%;
  height: 100vh;

  overflow: hidden;

  background-image: url("russell/banner.jpg");
  background-size: cover;
  background-position: center;

  display: flex;
  align-items: center;
}

.russel-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(0,210,190,0.22) 0%,
    rgba(0,210,190,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY ESCURO */
.russel-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

  background:
  linear-gradient(
    to right,
    rgba(0,0,0,0.8),
    rgba(0,0,0,0.2),
    rgba(0,0,0,0.7)
  );

  z-index: 1;
}

/* TODO CONTEÚDO ACIMA DO OVERLAY */
.russel-banner-bg > *{
  position: relative;
  z-index: 5;
}

