.slider-russell{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-russell{
  position: absolute;
  top: 0;
  left: 0;

  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER */
.bg-slider-russell::after{
  content: "";

  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO */
.slider-russell-container,
.titulo-russell-slider,
.dots-russell,
.btn-russell{
  position: relative;
  z-index: 2;
}

/* TÍTULO */
.titulo-russell-slider{
  font-size: 40px;
  color: #00d2be;

  margin-bottom: 40px;

  text-align: center;
}

/* CONTAINER */
.slider-russell-container{
  position: relative;

  max-width: 1300px;
  margin: auto;

  overflow: hidden;

  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-russell-track{
  display: flex;

  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-russell{
  min-width: 100%;

  position: relative;
}

/* IMAGEM */
.slide-russell img{
  width:100%;

  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;

  display:block;
}

/* TEXTO */
.slide-russell-texto{
  position: absolute;

  bottom: 0;
  left: 0;

  width: 100%;

  padding: 25px;

  background:
  linear-gradient(
    transparent,
    rgba(0,0,0,0.88)
  );

  text-align: left;
}

.slide-russell-texto h3{
  color: #00d2be;

  font-size: 56px;

  margin-bottom: 5px;

  text-shadow:
  0 0 12px rgba(0,210,190,0.25);
}

.slide-russell-texto p{
  color: #ddd;

  font-size: 36px;

  line-height: 1.5;
}

/* BOTÕES */
.btn-russell{
  position: absolute;

  top: 50%;

  transform: translateY(-50%);

  background: rgba(0,0,0,0.6);

  border: none;

  color: #fff;

  font-size: 30px;

  width: 45px;
  height: 45px;

  border-radius: 50%;

  cursor: pointer;

  transition: 0.3s;
}

.btn-russell.prev{
  left: 15px;
}

.btn-russell.next{
  right: 15px;
}

.btn-russell:hover{
  background: #00d2be;

  color: #000;

  box-shadow:
  0 0 20px rgba(0,210,190,0.4);
}

/* DOTS */
.dots-russell{
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}

.dot-russell{
  width: 10px;
  height: 10px;

  border-radius: 50%;

  background: rgba(255,255,255,0.3);

  cursor: pointer;

  transition: 0.3s;
}

.dot-russell:hover{
  background: #00d2be;
}

.dot-russell.active{
  background: #00d2be;

  transform: scale(1.3);

  box-shadow:
  0 0 10px rgba(0,210,190,0.6);
}

