/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR russell
========================================================= */

.pilotagem-russell {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(0,210,190, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(0,210,190, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-russell {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-russell {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(0,210,190, .10);

    border:
        1px solid
        rgba(0,210,190, .35);

    color: #00d2be;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-russell {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-russell span {
    color: #00d2be;
}


.pilotagem-intro-russell {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-russell {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-russell {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(0,210,190, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-russell::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(0,210,190, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-russell {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-russell {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-russell:hover
.perfil-imagem-russell {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-russell::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-russell {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-russell {
    display: block;

    margin-bottom: 8px;

    color: #00d2be;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-russell {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-russell span {
    display: block;

    color: #00d2be;
}


.perfil-equipe-russell {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-russell {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-russell i {
    color: #00d2be;

    font-size: 20px;
}


.perfil-frase-russell p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-russell {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-russell {
    display: block;

    margin-bottom: 12px;

    color: #00d2be;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-russell h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-russell h3 span {
    display: block;

    color: #00d2be;
}


.pilotagem-analise-russell > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-russell {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-russell {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-russell:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(0,210,190,.5);

    background:
        rgba(0,210,190,.06);
}


.caracteristica-icone-russell {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,210,190,.10);

    color: #00d2be;
}

.caracteristica-icone-russell i{
	font-size: 40px;

	}



.caracteristica-russell h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-russell p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-russell {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-russell {
    margin-bottom: 35px;
}


.skills-header-russell > span {
    display: block;

    margin-bottom: 10px;

    color: #00d2be;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-russell h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-russell h3 span {
    color: #00d2be;
}


/* GRID */

.skills-grid-russell {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-russell {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-russell:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(0,210,190,.35);
}


.skill-topo-russell {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-russell {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-russell i {
    color: #00d2be;

    font-size: 26px;
}


.skill-numero-russell {
    color: #00d2be;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-russell::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-russell {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-russell {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #00d2be,
            #C0c0c0
        );

    box-shadow:
        0 0 12px
        rgba(0,210,190,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-russell {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-russell {
    margin-bottom: 35px;
}


.grafico-header-russell > span {
    display: block;

    margin-bottom: 10px;

    color: #00d2be;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-russell h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-russell h3 span {
    color: #00d2be;
}


.grafico-layout-russell {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-russell {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-russell {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-russell {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-russell {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-russell {
    fill:
        rgba(0,210,190,.20);

    stroke: #00d2be;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(0,210,190,.35)
        );
}


.radar-ponto-russell {
    fill: #00d2be;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-russell {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-russell {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-russell {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-russell {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-russell {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-russell {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-russell {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-russell {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-russell {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-russell:hover {
    transform:
        translateX(6px);
}


.resumo-icone-russell {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,210,190,.10);

    color: #00d2be;

    font-size: 18px;
}


.resumo-card-russell > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-russell h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-russell p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-russell {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(0,210,190,.12),
            rgba(0,210,190,.02)
        );

    border:
        1px solid
        rgba(0,210,190,.25);
}


.pilotagem-conclusao-russell::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(0,210,190,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-russell > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-russell > span {
    display: block;

    margin-bottom: 18px;

    color: #00d2be;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-russell h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-russell strong {
    color: #00d2be;
}


.pilotagem-conclusao-russell p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-russell {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-russell.active {
    opacity: 1;

    transform:
        translateY(0);
}


