.radio-f1-russell{
  position:relative;

  display:flex;
  justify-content:center;
  align-items:center;

  background:black;

  padding:80px 20px;

  overflow:hidden;
}

/* 🔵 STATUS */
.radio-status-russell{
  position:absolute;

  top:15px;
  left:20px;

  color:#00d2be;

  font-size:42px;

  letter-spacing:2px;
}

.radio-status-russell::before{
  content:"●";

  margin-right:6px;

  animation:blink 1s infinite;
}

@keyframes blink{
  50%{
    opacity:0.3;
  }
}

/* 🏎️ INFO */
.race-info-russell{
  position:absolute;

  top:15px;
  right:20px;

  display:flex;
  gap:15px;

  font-size:30px;

  color:white;
}

/* CARD */
.card-russell{
  width:280px;
  height:420px;

  background:#0b0b0f;

  border-radius:12px;

  border:1px solid #222;

  position:relative;

  overflow:hidden;

  opacity:0;

  transform:translateY(20px);

  transition:0.4s ease;
}

/* ✨ GLOW */
.card-russell::before{
  content:"";

  position:absolute;
  inset:-20px;

  background:
  radial-gradient(
    circle,
    rgba(0,210,190,0.15),
    transparent
  );

  z-index:-1;
}

.card-russell.ativo{
  opacity:1;

  transform:translateY(0);
}

.card-russell.saindo{
  opacity:0;

  transform:translateY(20px);
}

/* ESQUERDA */
.left-russell{
  position:absolute;

  left:10px;
  top:60px;
}

.number-russell{
  font-size:120px;

  color:#00d2be;
}

/* DIREITA */
.right-russell{
  position:absolute;

  top:20px;
  right:15px;

  text-align:right;
}

.right-russell h1{
  color:#00d2be;

  margin:0;
}

.right-russell h2{
  color:white;

  margin:0;
}

.logo-russell{
  width:40px;

  margin-top:10px;
}

/* WAVE */
.wave-russell{
  position:absolute;

  top:160px;
  left:0;

  width:100%;
  height:50px;

  display:flex;
  align-items:flex-end;
}

.wave-russell span{
  flex:1;

  margin:0 1px;

  height:6px;

  background:
  linear-gradient(
    to top,
    #00d2be,
    transparent
  );

  animation:wave infinite ease-in-out;

  animation-play-state:paused;

  animation-duration:
  calc(0.8s + (var(--i) * 0.02s));

  animation-delay:
  calc(var(--i) * 0.05s);
}

.card-russell.falando .wave-russell span{
  animation-play-state:running;
}

@keyframes wave{

  0%,100%{
    height:6px;
    opacity:0.3;
  }

  50%{
    height:45px;
    opacity:1;
  }

}

/* CONTEÚDO */
.content-russell{
  position:absolute;

  bottom:0;

  width:100%;
  height:0;

  overflow:hidden;

  transition:height 0.4s ease;
}

/* TEXTO */
.text-russell{
  padding:10px 15px;

  opacity:0;

  transform:translateY(30px);

  transition:all 0.4s ease;
}

.card-russell.mostrar-texto .text-russell{
  opacity:1;

  transform:translateY(0);
}

.eng-russell{
  color:white;

  font-size:20px;
}

.pil-russell{
  color:#00d2be;

  text-align:right;

  font-size:20px;
}

