}

.card-stat-kimi.ativo{
  opacity:1;
  transform:translateY(0);
  animation:glowkimi 2s infinite alternate;
}

@keyframes glowkimi{
  from{box-shadow:0 0 10px #00D2BE;}
  to{box-shadow:0 0 30px #00D2BE;}
}

.card-stat-kimi span{
  font-size: clamp(32px,5vw,60px);
