  font-size:18px;
  color:#00D2BE;
  text-shadow: 0 0 6px rgba(0,0,0,0.8);
}

.card-stat-kimi:hover{
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 0 40px rgba(0,210,190,0.4);
}

.grande-kimi{
  grid-column:span 3;
}

.barra-velocidade-kimi{
  height:6px;
  background: linear-gradient(90deg, #00D2BE, #5affea);
  box-shadow: 0 0 10px #00D2BE;
  width:0%;
  margin-top:10px;
  border-radius:10px;
  transition:width 0.3s;
}

/* LUZ VERDE */
.luz-verde-kimi{
  position:absolute;
  width:600px;
  height:600px;
  background:radial-gradient(circle,#00D2BE,transparent 70%);
  top:-200px;
  right:-200px;
  opacity:0.2;
  animation:pulsarLuzkimi 4s infinite alternate;
  z-index:1;
}

@keyframes pulsarLuzkimi{
  from{ transform:scale(1);}
  to{ transform:scale(1.3);}
}

/* PARTÍCULAS */
.faiscas-kimi{
  position:absolute;
  inset:0;
  overflow:hidden;
  pointer-events:none;
  z-index:2;
}

/* partículas viram "linhas de vento" */
.spark-kimi{
  position:absolute;
  width:120px;
  height:2px;

  background: linear-gradient(
    90deg,
    transparent,
    rgba(0,210,190,0.8),
    transparent
  );

  opacity:0.6;

  animation: kimi 1.4s linear infinite;
}

/* variações pra parecer vento real */
.spark-kimi:nth-child(1){
  top:20%;
  left:-20%;
  animation-duration:1.2s;
}

.spark-kimi:nth-child(2){
  top:35%;
  left:-30%;
  animation-duration:1.6s;
  opacity:0.4;
}

.spark-kimi:nth-child(3){
  top:50%;
  left:-25%;
  animation-duration:1.3s;
}

.spark-kimi:nth-child(4){
  top:65%;
  left:-35%;
  animation-duration:1.8s;
  opacity:0.3;
}

.spark-kimi:nth-child(5){
  top:80%;
  left:-20%;
  animation-duration:1.5s;
}

@keyframes sparkkimi {
  from {
    transform: translateX(-120px);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  to {
    transform: translateX(120vw);
    opacity: 0;
  }
}

/* TÍTULO REVEAL */
.titulo-animar-kimi{
  opacity:0;
  transform:translateY(60px);
  transition:1s;
}

.titulo-animar-kimi.show{
  opacity:1;
  transform:translateY(0);
}

/* MOBILE */
@media (max-width: 768px){

  .numeros-kimi{
    height: auto;
    min-height: unset;
    padding: 40px 0 40px;
  }

  .bg-numeros-kimi{
 

    position: absolute;
    top: 0;
    left: 0;

    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;

    transform: none !important;
  }

  .overlay-numeros-kimi{
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.4);
  }

  .stats-grid-kimi{
    grid-template-columns:1fr;
    padding:0 15px;
    gap:15px;
  }

  .card-stat-kimi span{
    font-size: clamp(28px, 5vw, 60px);
  }

  .card-stat-kimi p{
    font-size: clamp(12px, 2vw, 18px);
  }

  .grande-kimi{
    grid-column:span 1;
  }

  .luz-verde-kimi{
    width:200px;
    height:200px;
    opacity:0.12;
  }

  .faiscas-kimi{
    display:none;
  }

}

