    letter-spacing: -3px;
}


.titulo-pilotagem-antonelli span {
    color: #00d2be;
}


.pilotagem-intro-antonelli {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
