/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-antonelli {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
