    background:
        rgba(0,210,190,.10);

    color: #00d2be;
}

.caracteristica-icone-antonelli i{
	font-size: 40px;

	}



.caracteristica-antonelli h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-antonelli p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-antonelli {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-antonelli {
    margin-bottom: 35px;
}


.skills-header-antonelli > span {
    display: block;

    margin-bottom: 10px;

    color: #00d2be;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-antonelli h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-antonelli h3 span {
    color: #00d2be;
}


/* GRID */

.skills-grid-antonelli {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-antonelli {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-antonelli:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(0,210,190,.35);
}


.skill-topo-antonelli {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-antonelli {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-antonelli i {
    color: #00d2be;

    font-size: 26px;
}


.skill-numero-antonelli {
    color: #00d2be;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-antonelli::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-antonelli {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-antonelli {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #00d2be,
            #C0c0c0
        );

    box-shadow:
        0 0 12px
        rgba(0,210,190,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-antonelli {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-antonelli {
    margin-bottom: 35px;
}


.grafico-header-antonelli > span {
    display: block;

    margin-bottom: 10px;

    color: #00d2be;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-antonelli h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-antonelli h3 span {
    color: #00d2be;
}


.grafico-layout-antonelli {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-antonelli {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-antonelli {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-antonelli {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-antonelli {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-antonelli {
    fill:
        rgba(0,210,190,.20);

    stroke: #00d2be;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(0,210,190,.35)
        );
}


.radar-ponto-antonelli {
    fill: #00d2be;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-antonelli {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-antonelli {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-antonelli {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-antonelli {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-antonelli {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-antonelli {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-antonelli {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-antonelli {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-antonelli {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-antonelli:hover {
    transform:
        translateX(6px);
}


.resumo-icone-antonelli {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,210,190,.10);

    color: #00d2be;

    font-size: 18px;
}


.resumo-card-antonelli > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-antonelli h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-antonelli p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-antonelli {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(0,210,190,.12),
            rgba(0,210,190,.02)
        );

    border:
        1px solid
        rgba(0,210,190,.25);
}


.pilotagem-conclusao-antonelli::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(0,210,190,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-antonelli > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-antonelli > span {
    display: block;

    margin-bottom: 18px;

    color: #00d2be;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-antonelli h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-antonelli strong {
    color: #00d2be;
}


.pilotagem-conclusao-antonelli p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-antonelli {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-antonelli.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-antonelli {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-antonelli {
        min-height: 600px;
    }


    .grafico-layout-antonelli {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-antonelli {
        max-width: 430px;
    }


    .caracteristicas-antonelli {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


