        border-radius: 20px;
    }


    .perfil-info-antonelli {
        padding:
            25px
            20px;
    }


    .perfil-nome-antonelli {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-antonelli {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-antonelli h3 {
        font-size: 38px;
    }


    .pilotagem-analise-antonelli > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-antonelli {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-antonelli {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-antonelli {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-antonelli {
        margin-top: 70px;
    }


    .skills-grid-antonelli {
        grid-template-columns: 1fr;
    }


    .skill-card-antonelli {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-antonelli {
        margin-top: 70px;
    }


    .grafico-layout-antonelli {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-antonelli {
        width: 80%;
    }


    .radar-label-antonelli {
        font-size: 7px;
    }


    .radar-top-right-antonelli {
        right: -28px;
    }


    .radar-bottom-right-antonelli {
        right: -35px;
    }


    .radar-bottom-left-antonelli {
        left: -35px;
    }


    .radar-top-left-antonelli {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-antonelli {
        padding: 0 10px;
    }


    .resumo-card-antonelli {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-antonelli h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-antonelli {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-antonelli h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-antonelli p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-antonelli {
        font-size: 36px;
    }


    .pilotagem-perfil-antonelli {
        min-height: 450px;
    }


    .perfil-nome-antonelli {
        font-size: 38px;
    }


    .analise-topo-antonelli h3 {
        font-size: 32px;
    }


    .skill-nome-antonelli {
        font-size: 9px;
    }


    .radar-container-antonelli {
        width: 78%;
    }


    .radar-label-antonelli {
        font-size: 6px;
    }


    .resumo-card-antonelli p {
        font-size: 11px;
    }

}v


