.numeros-max{
  background: linear-gradient(
    120deg,
    #000 0%,
    #0a0a0a 50%,
    #1E41FF 85%,
    #ff1e1e 120%
  );

  position: relative;
  min-height: 700px;
  padding: 80px 0;
  overflow: hidden;
}

/* FUNDO */
.bg-numeros-max{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:cover;
  filter: blur(4px) brightness(0.5);
  z-index:0;
}

/* OVERLAY */
.overlay-numeros-max{
  position:absolute;
  inset:0;
  background: radial-gradient(circle at center, transparent 40%, rgba(0,0,0,0.85) 100%);
  z-index:1;
}

/* LUZ */
.luz-azul-max{
  position:absolute;
  width:600px;
  height:600px;
  top:-200px;
  right:-200px;
  background: radial-gradient(circle, rgba(30,65,255,.6), transparent 70%);
  opacity:.25;
  filter: blur(20px);
  animation: pulsarmax 4s infinite alternate;
  z-index:1;
}

@keyframes pulsarmax{
  from{transform:scale(1);}
  to{transform:scale(1.3);}
}

/* TÍTULO */
.titulo-numeros-max{
  position:relative;
  z-index:2;
  text-align:center;
  font-size:46px;
  color:#1E41FF;
  margin-bottom:40px;
  text-shadow: 0 0 20px rgba(30,65,255,.5);
}

/* GRID */
.stats-grid-max{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns: repeat(3, 1fr);
  gap:20px;
  padding: 0 40px;
}

/* CARD BASE MELHORADO */
.card-stat-max{
  position:relative;
  background: rgba(10,10,10,0.75);
  border: 1px solid rgba(30,65,255,.35);
  border-radius:18px;
  padding: 25px;
  text-align:center;
  overflow:hidden;

  color:white;

  opacity:0;
  transform: translateY(60px);
  transition: .6s ease;

  box-shadow: 0 10px 30px rgba(0,0,0,.6);
}

/* ANIMAÇÃO ENTRADA */
.card-stat-max.ativo{
  opacity:1;
  transform: translateY(0);
}

/* 🔥 EFEITO “RPM / MOTOR LIGADO” */
.card-stat-max::before{
  content:"";
  position:absolute;
  inset:-50px;

  background: radial-gradient(circle, rgba(30,65,255,.25), transparent 60%);
  opacity:0;
  transition:.4s;
}

.card-stat-max:hover::before{
  opacity:1;
}

/* NÚMERO */
.card-stat-max span{
  font-size: clamp(34px,5vw,60px);
  font-weight:900;
  color:#1E41FF;
  text-shadow: 0 0 15px rgba(30,65,255,.6);
  display:block;
}

/* TEXTO */
.card-stat-max p{
  margin-top:10px;
  font-size:16px;
  color:#fff;
  opacity:.85;
}

/* BARRA (AGORA MAIS “ACELERAÇÃO”) */
.barra-velocidade-max{
  height:6px;
  width:0%;
  margin-top:10px;
  border-radius:20px;

  background: linear-gradient(90deg, #1E41FF, #ff1e1e);
  box-shadow: 0 0 12px rgba(30,65,255,.6);

  transition: width .2s linear;
}

/* CARD GRANDE */
.grande-max{
  grid-column: span 3;
}

/* HOVER DINÂMICO */
.card-stat-max:hover{
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 0 35px rgba(30,65,255,.25);
}

/* PARTÍCULAS (FAÍSCAS) */
.faíscas-max{
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index:2;
}

.spark-max{
  position:absolute;
  width:4px;
  height:4px;
  background:#1E41FF;
  border-radius:50%;
  animation: sparkRB 1.5s linear infinite;
}

.spark-max:nth-child(1){left:10%; animation-delay:0s;}
.spark-max:nth-child(2){left:30%; animation-delay:.3s;}
.spark-max:nth-child(3){left:50%; animation-delay:.6s;}
.spark-max:nth-child(4){left:70%; animation-delay:.9s;}
.spark-max:nth-child(5){left:85%; animation-delay:1.2s;}

@keyframes sparkmax{
  0%{transform:translateY(0); opacity:1;}
  100%{transform:translateY(-120px); opacity:0;}
}

/* MOBILE */
@media (max-width:768px){

  .stats-grid-max{
    grid-template-columns:1fr;
    padding:0 15px;
  }

