            135deg,
            rgba(255,255,255,.15),
            transparent
        );

    opacity: 0;

    transition: opacity .25s ease;
}


.max-title-btn:hover {
    transform: translateY(-2px);

    background: rgba(255,255,255,.12);

    box-shadow:
        0 8px 20px rgba(0,0,0,.35);
}


.max-title-btn:hover::before {
    opacity: 1;
}


.max-title-btn.active {
    background:
        linear-gradient(
            135deg,
            #1e41ff,
            #00023a
        );

    color: #fff;

    box-shadow:
        0 0 18px rgba(30,65,255,.4),
        0 8px 20px rgba(0,0,0,.4);

    transform: translateY(-1px);
}


.max-title-btn.active::after {
    content: "🏆";

    margin-left: 5px;

    font-size: 10px;
}


/* =========================================================
   HERO
========================================================= */

.max-hero {
    flex: 1;

    min-height: 0;

    width: 100%;

    display: grid;

    grid-template-columns: minmax(280px, .9fr) minmax(0, 1.1fr);

    gap: clamp(20px, 3vw, 50px);

    align-items: center;

    overflow: hidden;
}


/* =========================================================
   LADO DA IMAGEM
========================================================= */

.max-hero-left {
    position: relative;

    height: 100%;

    min-height: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.max-hero-art {
    width: 100%;
    height: 100%;

    max-height: 100%;
    object-fit: contain;

    object-position: center center;

    filter:
        drop-shadow(
            0 25px 35px rgba(0,0,0,.7)
        );

    transition:
        transform .5s ease,
        filter .5s ease;
}


.max-hero-left:hover .max-hero-art {
    transform: scale(1.025);

    filter:
        drop-shadow(
            0 30px 45px rgba(0,0,0,.8)
        );
}


/* =========================================================
   LADO DIREITO
========================================================= */

.max-hero-right {
    min-width: 0;
    min-height: 0;

    height: 100%;

    display: flex;

    flex-direction: column;

    justify-content: center;

    gap: clamp(8px, 1.3vh, 18px);

    overflow: hidden;
}


/* =========================================================
   ÁREA DO TÍTULO
========================================================= */

.max-title-area {
    flex-shrink: 0;
}


.max-year {
    display: block;

    margin-bottom: 6px;

    font-size: clamp(30px, 2vw, 40px);

    line-height: .9;

    font-weight: 900;

    color: #1e41ff;

    letter-spacing: -2px;
}


.max-name {
    margin: 0;

    font-size: clamp(32px, 4vw, 80px);

    line-height: .82;

    font-weight: 900;

    letter-spacing: -5px;

    text-transform: uppercase;

    color: #fff;
}


.max-name span {
    display: block;

    color: #1e41ff;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.max-subtitle {
    margin: clamp(10px, 1.5vh, 18px) 0 0;

    font-size: clamp(13px, 1.5vw, 24px);

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #ddd;
}


/* =========================================================
   DESCRIÇÃO
========================================================= */

.max-description {
    flex-shrink: 0;

    width: 100%;
    max-width: 720px;

    font-size: clamp(11px, 1.2vw, 18px);

    line-height: 1.55;

    color: #cfcfcf;

    overflow: visible;

    word-break: normal;
    overflow-wrap: break-word;
}

/* =========================================================
   ESTATÍSTICAS
========================================================= */

.max-stats {
    flex-shrink: 0;

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(5, minmax(0, 1fr));

    gap: clamp(6px, 1vw, 14px);
}


.max-stat-box {
    min-width: 0;

    padding: clamp(10px, 1.2vw, 18px);

    border-radius: 14px;

    text-align: center;

    background:
        linear-gradient(
            145deg,
            #1e41ff,
            #00023a
        );

    border: 1px solid rgba(30,65,255,.4);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.1);
}


.max-stat-box h3 {
    margin: 0 0 5px;

    font-size: clamp(20px, 2.5vw, 38px);

    line-height: 1;

    font-weight: 900;

    color: #Ffd700;
}


.max-stat-box p {
    margin: 0;

    font-size: clamp(7px, .8vw, 11px);

    line-height: 1.2;

    text-transform: uppercase;

    letter-spacing: .8px;

    color: #fff;

    font-weight: 700;
}


/* =========================================================
   QUOTE
========================================================= */

.max-quote {
    flex-shrink: 0;

    width: 100%;
    box-sizing: border-box;

    padding: clamp(12px, 1.5vw, 24px);

    border-radius: 15px;

    background:
        linear-gradient(
            135deg,
            #1e41ff,
            #00023a
        );

    border-left: 4px solid #Ffd700;

    overflow: visible;
}

.max-quote p {
    margin: 0;

    font-size: clamp(11px, 1.2vw, 17px);

    line-height: 1.5;

    color: #fff;

    white-space: normal;

    word-break: normal;

    overflow-wrap: break-word;
}

.max-quote span {
    display: block;

    margin-top: 8px;

    font-size: clamp(9px, 1vw, 13px);

    color: #Ffd700;

    font-weight: 800;
}


/* =========================================================
   TIMELINE
========================================================= */

.max-timeline-section {
    flex-shrink: 0;

    width: 100%;

    margin-top: clamp(10px, 1.5vh, 20px);

    min-height: 0;

    overflow: hidden;
}


.max-section-title {
    margin: 0 0 clamp(10px, 1.5vh, 18px);

    font-size: clamp(20px, 3vw, 42px);

    line-height: 1;

    font-weight: 900;

    text-align: center;

    text-transform: uppercase;

    color: #fff;
}


.max-timeline-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(5, minmax(0, 1fr));

    gap: clamp(8px, 1.2vw, 18px);

    min-height: 0;
}


.max-race-card {
    min-width: 0;

    min-height: clamp(130px, 20vh, 250px);

    padding: clamp(12px, 1.4vw, 22px);

    border-radius: 16px;

    background:
        linear-gradient(
            145deg,
            #0d0d0d,
            #080808
        );

    border: 1px solid #222;

    display: flex;

    flex-direction: column;

    justify-content: space-between;

    overflow: hidden;

    transition:
        transform .3s ease,
        box-shadow .3s ease;
}


.max-race-card:hover {
    transform: translateY(-5px);

    box-shadow:
        0 12px 30px rgba(0,0,0,.45);
}


.max-race-card h3 {
    margin: 0 0 8px;

    font-size: clamp(12px, 1.4vw, 21px);

    line-height: 1.1;

    font-weight: 900;

    text-transform: uppercase;
}


.max-race-card p {
    margin: 0;

    font-size: clamp(12px, 1vw, 15px);

    line-height: 1.45;

    color: #bdbdbd;

    overflow: hidden;
}


.max-race-result {
    flex-shrink: 0;

    margin-top: 10px;

    padding: 8px;

    border-radius: 9px;

    font-size: clamp(7px, .75vw, 11px);

    line-height: 1.2;

    font-weight: 800;

    text-align: center;

    text-transform: uppercase;

    background: #111;

    color: #fff;

    border: 1px solid rgba(255,255,255,.05);
}


/* =========================================================
   CORES DA TIMELINE
========================================================= */

.max-race-card.positive {
    border-color: rgba(35,255,133,.45);
}

.max-race-card.positive h3 {
    color: #23ff85;
}


.max-race-card.warning {
    border-color: rgba(255,208,0,.45);
}

.max-race-card.warning h3 {
    color: #ffd000;
}


.max-race-card.danger {
    border-color: rgba(255,61,61,.45);
}

.max-race-card.danger h3 {
    color: #ff3d3d;
}


.max-race-card.climax {
    border-color: rgba(30,65,255,.7);

    box-shadow:
        0 0 25px rgba(30,65,255,.12);
}

.max-race-card.climax h3 {
    color: #1e41ff;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1100px) {

    .max-season-card {
        padding: 18px;
    }

    .max-hero {
        grid-template-columns:
            minmax(230px, .85fr)
            minmax(0, 1.15fr);

        gap: 25px;
    }

    .max-name {
        font-size: clamp(48px, 7vw, 80px);

        letter-spacing: -3px;
    }

    .max-timeline-grid {
        gap: 8px;
    }

    .max-race-card {
        padding: 10px;
    }
}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

    #max-title-container {
        height: 100dvh;
        max-height: 100dvh;
    }


    .max-season-card {
        height: 100%;
        max-height: 100dvh;

        padding:
            12px
            10px
            10px;

        border-radius: 20px;
    }


    /* BOTÕES */

    .max-title-buttons {
        gap: 6px;

        margin-bottom: 8px;
    }


    .max-title-btn {
        min-width: 48px;

        padding: 8px 11px;

        font-size: 10px;

        border-radius: 8px;
    }


    .max-title-btn.active::after {
        display: none;
    }


    /* HERO */

    .max-hero {
        grid-template-columns:
