        gap: 10px;

        min-height: 0;

        flex: 1;
    }


    .max-hero-left {
        height: 100%;

        min-height: 0;
    }


    .max-hero-art {
        width: 100%;
        height: 100%;

        object-fit: contain;
    }


    .max-hero-right {
        gap: 7px;

        min-width: 0;

        overflow: hidden;
    }


    /* ANO */

    .max-year {
        font-size: clamp(25px, 8vw, 40px);

        margin-bottom: 4px;
    }


    /* NOME */

    .max-name {
        font-size: clamp(34px, 9vw, 60px);

        line-height: .83;

        letter-spacing: -2px;
    }


    /* SUBTÍTULO */

    .max-subtitle {
        margin-top: 8px;

        font-size: clamp(8px, 2.2vw, 12px);

        letter-spacing: .5px;
    }


    /* DESCRIÇÃO */

.max-description {
    flex-shrink: 0;

    width: 100%;

    font-size: clamp(9px, 2.2vw, 12px);

    line-height: 1.45;

    max-height: none;

    overflow: visible;

    word-break: normal;

    overflow-wrap: break-word;
}

    /* ESTATÍSTICAS */

    .max-stats {
        grid-template-columns:
            repeat(5, minmax(0, 1fr));

        gap: 4px;
    }


    .max-stat-box {
        padding: 8px 3px;

        border-radius: 8px;
    }


    .max-stat-box h3 {
        font-size: clamp(16px, 4vw, 24px);

        margin-bottom: 3px;
    }


    .max-stat-box p {
        font-size: 6px;

        letter-spacing: .2px;
    }


    /* QUOTE */

.max-quote {
    flex-shrink: 0;

    width: 100%;

    padding: 10px 12px;

    border-left-width: 3px;

    border-radius: 10px;

    overflow: visible;
}

.max-quote p {
    font-size: clamp(8px, 2vw, 11px);

    line-height: 1.45;

    white-space: normal;

    overflow: visible;
}

.max-quote span {
    margin-top: 5px;

    font-size: 8px;
}


    /* TIMELINE */

    .max-timeline-section {
        margin-top: 8px;
    }


    .max-section-title {
        margin-bottom: 7px;

        font-size: clamp(15px, 4vw, 22px);
    }


    .max-timeline-grid {
        grid-template-columns:
            repeat(5, minmax(0, 1fr));

        gap: 4px;
    }


    .max-race-card {
        min-height: 115px;

        height: 115px;

        padding: 7px;

        border-radius: 8px;
    }


    .max-race-card h3 {
        font-size: 7px;

        line-height: 1.15;

        margin-bottom: 4px;
    }


    .max-race-card p {
        font-size: 6px;

        line-height: 1.3;
    }


    .max-race-result {
        margin-top: 4px;

        padding: 4px 2px;

        border-radius: 5px;

        font-size: 5px;
    }
}


/* =========================================================
   CELULAR MUITO PEQUENO
========================================================= */

@media (max-width: 400px) {

