/* LIGHTBOX */
.lightbox-max{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightbox .3s ease;
}

/* ANIMAÇÃO */
@keyframes fadeLightbox{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-max{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightbox .35s ease;
}

@keyframes zoomLightbox{

  from{
    transform:scale(.85);
    opacity:0;
  }

