   NÚMERO GIGANTE
========================= */

.hadjar-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,255,255,0.08);

  font-family: 'Russo One', sans-serif;

  user-select: none;
  pointer-events: none;

  animation:
  hadjarGlow 4s ease-in-out infinite;
}

/* GLOW */

@keyframes hadjarGlow{

  0%{
    text-shadow:
    0 0 15px rgba(0,20,60,0.98);
  }

  50%{
    text-shadow:
    0 0 25px rgba(220,20,60,0.5),
    0 0 60px rgba(255,204,0,0.2);
  }

  100%{
    text-shadow:
    0 0 15px rgba(0,20,190,0.98);
  }

}

/* =========================
   CHUVA DIGITAL
========================= */

.hadjar-rain{
  position: absolute;
  inset: 0;

  overflow: hidden;

  z-index: 2;

  pointer-events: none;
}

.hadjar-rain span{
  position: absolute;

  width: 7px;
  height: 120px;

  background:
  linear-gradient(
    transparent,
    rgba(0,20,190,0.8),
    transparent
  );

  opacity: 0.5;

  animation:
  hadjarRain linear infinite;
}

/* POSIÇÕES */

.hadjar-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.hadjar-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.hadjar-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.hadjar-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.hadjar-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.hadjar-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.hadjar-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.hadjar-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}

/* ANIMAÇÃO */

@keyframes hadjarRain{

  0%{
    transform:
    translateY(-200px);

    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform:
    translateY(120vh);

    opacity: 0;
  }

}


/* =========================
   PARTICLES
========================= */

.hadjar-particles{
  position: absolute;
  inset: 0;

  overflow: hidden;

  z-index: 2;

  pointer-events: none;
}

/* PARTÍCULA */

.hadjar-particles span{
  position: absolute;

  display: block;

  width: 16px;
  height: 16px;

  border-radius: 50%;

  background: rgba(0,20,190,0.7);

  box-shadow:
  0 0 10px rgba(220,20,60,0.8),
  0 0 20px rgba(255,204,0,0.4);

  animation:
  hadjarFloat linear infinite;
}

/* POSIÇÕES DIFERENTES */

.hadjar-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.hadjar-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.hadjar-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.hadjar-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.hadjar-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.hadjar-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.hadjar-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.hadjar-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.hadjar-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.hadjar-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}

/* ANIMAÇÃO */

@keyframes hadjarFloat{

  0%{
    transform:
    translateY(100vh)
    scale(0.5);

    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  50%{
    opacity: 0.8;
  }

  100%{
    transform:
    translateY(-120px)
    scale(1.4);

    opacity: 0;
  }

}



/* =========================
   SOCIALS
========================= */

.hadjar-socials{
  position: absolute;

  right: 30px;
