.slider-hadjar{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-hadjar {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-hadjar::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-hadjar-container,
.titulo-hadjar-slider,
.dots-hadjar,
.btn-hadjar {
  position: relative;
  z-index: 2;
}

.titulo-hadjar-slider {
  font-size: 40px;
  color: #1E41FF;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-hadjar-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-hadjar-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-hadjar {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-hadjar img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-hadjar-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(2,0,0,0.85));
  text-align: left;
}

.slide-hadjar-texto h3 {
  color: #1E41FF;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-hadjar-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-hadjar {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(20,10,200,0.6);
  border: none;
  color: #fff;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-hadjar:hover {
  background: #ffdb09;
}

/* BOLINHAS */
.dots-hadjar {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-hadjar {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-hadjar:hover {
  background: #1E41FF;
}

.dot-hadjar.active {
  background: #1E41FF;
  transform: scale(1.3);
}
