  filter: blur(4px) brightness(0.5);
  z-index:0;
}

/* OVERLAY */
.overlay-numeros-hadjar{
  position:absolute;
  inset:0;
  background: radial-gradient(circle at center, transparent 40%, rgba(0,0,0,0.85) 100%);
  z-index:1;
}

/* LUZ */
.luz-azul-hadjar{
  position:absolute;
  width:600px;
  height:600px;
  top:-200px;
  right:-200px;
  background: radial-gradient(circle, rgba(30,65,255,.6), transparent 70%);
  opacity:.25;
  filter: blur(20px);
  animation: pulsarhadjar 4s infinite alternate;
  z-index:1;
}

@keyframes pulsarhadjar{
  from{transform:scale(1);}
  to{transform:scale(1.3);}
}

/* TÍTULO */
.titulo-numeros-hadjar{
  position:relative;
  z-index:2;
  text-align:center;
  font-size:46px;
  color:#1E41FF;
  margin-bottom:40px;
