}

/* GRID */
.stats-grid-hadjar{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns: repeat(3, 1fr);
  gap:20px;
  padding: 0 40px;
}

/* CARD BASE MELHORADO */
.card-stat-hadjar{
  position:relative;
  background: rgba(10,10,10,0.75);
  border: 1px solid rgba(30,65,255,.35);
  border-radius:18px;
  padding: 25px;
  text-align:center;
  overflow:hidden;

  color:white;

  opacity:0;
  transform: translateY(60px);
  transition: .6s ease;

  box-shadow: 0 10px 30px rgba(0,0,0,.6);
}

/* ANIMAÇÃO ENTRADA */
.card-stat-hadjar.ativo{
  opacity:1;
  transform: translateY(0);
}

/* 🔥 EFEITO “RPM / MOTOR LIGADO” */
.card-stat-hadjar::before{
  content:"";
  position:absolute;
  inset:-50px;

  background: radial-gradient(circle, rgba(30,65,255,.25), transparent 60%);
  opacity:0;
  transition:.4s;
}

.card-stat-hadjar:hover::before{
  opacity:1;
}

/* NÚMERO */
.card-stat-hadjar span{
  font-size: clamp(34px,5vw,60px);
  font-weight:900;
  color:#1E41FF;
  text-shadow: 0 0 15px rgba(30,65,255,.6);
  display:block;
}

/* TEXTO */
.card-stat-hadjar p{
  margin-top:10px;
  font-size:16px;
  color:#fff;
  opacity:.85;
}

/* BARRA (AGORA MAIS “ACELERAÇÃO”) */
.barra-velocidade-hadjar{
  height:6px;
  width:0%;
  margin-top:10px;
  border-radius:20px;

  background: linear-gradient(90deg, #1E41FF, #ff1e1e);
  box-shadow: 0 0 12px rgba(30,65,255,.6);

  transition: width .2s linear;
}

/* CARD GRANDE */
.grande-hadjar{
  grid-column: span 3;
}

/* HOVER DINÂMICO */
.card-stat-hadjar:hover{
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 0 35px rgba(30,65,255,.25);
}

/* PARTÍCULAS (FAÍSCAS) */
.faíscas-hadjar{
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index:2;
}

.spark-hadjar{
  position:absolute;
  width:4px;
  height:4px;
  background:#1E41FF;
  border-radius:50%;
  animation: sparkhadjar 1.5s linear infinite;
}

.spark-hadjar:nth-child(1){left:10%; animation-delay:0s;}
.spark-hadjar:nth-child(2){left:30%; animation-delay:.3s;}
.spark-hadjar:nth-child(3){left:50%; animation-delay:.6s;}
.spark-hadjar:nth-child(4){left:70%; animation-delay:.9s;}
.spark-hadjar:nth-child(5){left:85%; animation-delay:1.2s;}

@keyframes sparkhadjar{
  0%{transform:translateY(0); opacity:1;}
  100%{transform:translateY(-120px); opacity:0;}
}

