.hadjar-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.hadjar-ano-btn:hover{
  background:rgba(30,42,68,0.15);

  color:#1e41ff;

  transform:translateY(-2px);
}


.hadjar-ano-btn.active{
  background:#1e41ff;

  color:#000;

  box-shadow:
    0 0 18px rgba(30,42,68,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.hadjar-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.hadjar-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.hadjar-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.hadjar-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.hadjar-team-change{
  position:relative;

  border:1px solid rgba(30,42,68,.45);

  box-shadow:
    0 0 20px rgba(30,42,68,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-hadjar{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #1e41ff,
      #1e41ff
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferhadjar .5s ease;
}


@keyframes transferhadjar{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.hadjar-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(0,30,42,68.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.hadjar-corrida-card:hover::before{
  opacity:1;
}


.hadjar-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(0,30,42,68.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.hadjar-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.hadjar-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.hadjar-vitoria .hadjar-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(0,30,42,68.25);

}


.hadjar-podio .hadjar-resultado{

  color: #1e41ff ;

  text-shadow:
    0 0 10px rgba(0,30,42,68.2);

}


.hadjar-pontos .hadjar-resultado{

  color:#ffffff;

}


.hadjar-dnf .hadjar-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.hadjar-sem-pontos .hadjar-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.hadjar-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#1e41ff;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.hadjar-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.hadjar-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

  opacity:0;

  transform:translateY(15px);

  transition:.4s ease;

  box-sizing:border-box;
}


.hadjar-summary-card.show{

