    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(30,65,255, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(30,65,255, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-hadjar {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-hadjar {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(30,65,255, .10);

    border:
        1px solid
        rgba(30,65,255, .35);

    color: #1e41ff;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-hadjar {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-hadjar span {
    color: #1e41ff;
}


.pilotagem-intro-hadjar {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-hadjar {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-hadjar {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(30,65,255, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-hadjar::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(30,65,255, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-hadjar {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-hadjar {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-hadjar:hover
.perfil-imagem-hadjar {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-hadjar::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-hadjar {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-hadjar {
    display: block;

    margin-bottom: 8px;

    color: #1e41ff;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-hadjar {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-hadjar span {
    display: block;

    color: #1e41ff;
}


.perfil-equipe-hadjar {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-hadjar {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-hadjar i {
    color: #1e41ff;

    font-size: 20px;
}


.perfil-frase-hadjar p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-hadjar {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-hadjar {
    display: block;

    margin-bottom: 12px;

    color: #1e41ff;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-hadjar h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-hadjar h3 span {
    display: block;

    color: #1e41ff;
}


.pilotagem-analise-hadjar > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-hadjar {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-hadjar {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-hadjar:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(30,65,255,.5);

    background:
        rgba(30,65,255,.06);
}


.caracteristica-icone-hadjar {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(30,65,255,.10);

    color: #1e41ff;
}

.caracteristica-icone-hadjar i{
	font-size: 40px;

	}



.caracteristica-hadjar h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-hadjar p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-hadjar {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-hadjar {
    margin-bottom: 35px;
}


.skills-header-hadjar > span {
    display: block;

    margin-bottom: 10px;

    color: #1e41ff;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-hadjar h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-hadjar h3 span {
    color: #1e41ff;
}


/* GRID */

.skills-grid-hadjar {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-hadjar {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-hadjar:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(30,65,255,.35);
}


.skill-topo-hadjar {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-hadjar {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-hadjar i {
    color: #1e41ff;

    font-size: 26px;
}


.skill-numero-hadjar {
    color: #1e41ff;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-hadjar::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-hadjar {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-hadjar {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #1e41ff,
            #1e2a44
        );

    box-shadow:
        0 0 12px
        rgba(30,65,255,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-hadjar {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-hadjar {
    margin-bottom: 35px;
}


.grafico-header-hadjar > span {
    display: block;

    margin-bottom: 10px;

    color: #1e41ff;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-hadjar h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-hadjar h3 span {
    color: #1e41ff;
}


.grafico-layout-hadjar {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-hadjar {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-hadjar {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-hadjar {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-hadjar {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-hadjar {
    fill:
        rgba(30,65,255,.20);

    stroke: #1e41ff;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(30,65,255,.35)
        );
}


.radar-ponto-hadjar {
    fill: #1e41ff;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-hadjar {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-hadjar {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-hadjar {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-hadjar {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-hadjar {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-hadjar {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-hadjar {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-hadjar {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-hadjar {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-hadjar:hover {
    transform:
        translateX(6px);
}


.resumo-icone-hadjar {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(30,65,255,.10);

    color: #1e41ff;

    font-size: 18px;
}


.resumo-card-hadjar > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-hadjar h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-hadjar p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-hadjar {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(30,65,255,.12),
            rgba(30,65,255,.02)
        );

    border:
        1px solid
        rgba(30,65,255,.25);
}


.pilotagem-conclusao-hadjar::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(30,65,255,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-hadjar > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-hadjar > span {
    display: block;

    margin-bottom: 18px;

    color: #1e41ff;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-hadjar h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-hadjar strong {
    color: #1e41ff;
}


.pilotagem-conclusao-hadjar p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-hadjar {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-hadjar.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-hadjar {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-hadjar {
        min-height: 600px;
    }


    .grafico-layout-hadjar {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-hadjar {
        max-width: 430px;
    }


    .caracteristicas-hadjar {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

    .pilotagem-hadjar {
        padding:
            70px
            15px;
    }


    .pilotagem-header-hadjar {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-hadjar {
        font-size: 42px;

        letter-spacing: -2px;
    }


    /* PERFIL */

    .pilotagem-perfil-hadjar {
        min-height: 500px;

        border-radius: 20px;
    }


    .perfil-info-hadjar {
        padding:
            25px
            20px;
    }


    .perfil-nome-hadjar {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-hadjar {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-hadjar h3 {
        font-size: 38px;
    }


    .pilotagem-analise-hadjar > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-hadjar {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-hadjar {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-hadjar {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-hadjar {
        margin-top: 70px;
    }


    .skills-grid-hadjar {
        grid-template-columns: 1fr;
    }


    .skill-card-hadjar {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-hadjar {
        margin-top: 70px;
    }


    .grafico-layout-hadjar {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-hadjar {
        width: 80%;
    }


    .radar-label-hadjar {
        font-size: 7px;
    }


    .radar-top-right-hadjar {
        right: -28px;
    }


    .radar-bottom-right-hadjar {
        right: -35px;
    }


    .radar-bottom-left-hadjar {
        left: -35px;
    }


    .radar-top-left-hadjar {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-hadjar {
        padding: 0 10px;
    }


    .resumo-card-hadjar {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-hadjar h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-hadjar {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-hadjar h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-hadjar p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-hadjar {
        font-size: 36px;
    }


    .pilotagem-perfil-hadjar {
        min-height: 450px;
    }


    .perfil-nome-hadjar {
        font-size: 38px;
    }


    .analise-topo-hadjar h3 {
        font-size: 32px;
    }


    .skill-nome-hadjar {
        font-size: 9px;
    }


    .radar-container-hadjar {
        width: 78%;
    }


    .radar-label-hadjar {
        font-size: 6px;
    }


    .resumo-card-hadjar p {
        font-size: 11px;
    }

}


