.radio-f1-hadjar {
  position: relative;

  display: flex;
  justify-content: center;
  align-items: center;

  background:
  radial-gradient(
    circle at top,
    #111827 0%,
    #05070d 60%,
    #000 100%
  );

  padding: 80px 20px;
  overflow: hidden;
}

/* 🔵 STATUS */
.radio-status-hadjar {
  position: absolute;

  top: 15px;
  left: 20px;

  color: #1e5eff;

  font-size: 42px;
  font-weight: 700;

  letter-spacing: 2px;
  text-transform: uppercase;
}

.radio-status-hadjar::before {
  content: "●";

  margin-right: 6px;

  animation: blinkhadjar 1s infinite;
}

/* ✨ PISCAR */
@keyframes blinkhadjar {

  50% {
    opacity: 0.3;
  }

}

/* 🏎️ INFO */
.race-info-hadjar {
  position: absolute;

  top: 15px;
  right: 20px;

  display: flex;
  gap: 15px;

  font-size: 30px;
  font-weight: 600;

  color: white;
}

/* CARD */
.card-hadjar {
  width: 280px;
  height: 420px;

  background:
  linear-gradient(
    180deg,
    #0c1220,
    #05070d
  );

  border-radius: 18px;

  border:
  1px solid rgba(255,255,255,0.08);

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);

  transition: 0.4s ease;

  box-shadow:
  0 0 30px rgba(30,94,255,0.08);
}

/* ✨ GLOW */
.card-hadjar::before {
  content: "";

  position: absolute;
  inset: -20px;

  background:
  radial-gradient(
    circle,
    rgba(30,94,255,0.18),
    transparent
  );

  z-index: -1;
}

/* LINHA SUPERIOR */
.card-hadjar::after {
  content: "";

  position: absolute;
  top: 0;
  left: 0;

  width: 100%;
  height: 3px;

  background:
  linear-gradient(
    90deg,
    #1e5eff,
    #00a2ff
  );
}

/* ATIVO */
.card-hadjar.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-hadjar.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-hadjar {
  position: absolute;

  left: 10px;
  top: 60px;
}

.number-hadjar {
  font-size: 120px;
  font-weight: 900;

  color: #1e5eff;

  text-shadow:
  0 0 20px rgba(30,94,255,0.5);
}

/* DIREITA */
.right-hadjar {
  position: absolute;

  top: 20px;
  right: 15px;

  text-align: right;
}

.right-hadjar h1 {
  color: #1e5eff;

  margin: 0;

  font-size: 28px;
}

.right-hadjar h2 {
  color: white;

  margin: 0;

  font-size: 18px;
}

.logo-hadjar {
  width: 40px;

  margin-top: 10px;

  filter:
  drop-shadow(
    0 0 10px rgba(30,94,255,0.5)
  );
}

/* 🌊 WAVE */
.wave-hadjar {
  position: absolute;

  top: 160px;
  left: 0;

  width: 100%;
  height: 50px;

  display: flex;
  align-items: flex-end;
}

.wave-hadjar span {
  flex: 1;

  margin: 0 1px;
  height: 6px;

  border-radius: 4px;

  background:
  linear-gradient(
    to top,
    #1e5eff,
    transparent
  );

  animation: wavehadjar infinite ease-in-out;
  animation-play-state: paused;

  animation-duration:
  calc(0.8s + (var(--i) * 0.02s));

  animation-delay:
  calc(var(--i) * 0.05s);
}

.card-hadjar.falando .wave-hadjar span {
  animation-play-state: running;
}

/* 🌊 ANIMAÇÃO */
@keyframes wavehadjar {

  0%,100% {
    height: 6px;
    opacity: 0.3;
  }

  50% {
    height: 45px;
    opacity: 1;
  }

}

/* CONTEÚDO */
.content-hadjar {
  position: absolute;

  bottom: 0;
  width: 100%;
  height: 0;

  overflow: hidden;

  transition: height 0.4s ease;

  background:
  linear-gradient(
    180deg,
    transparent,
    rgba(5,7,13,0.95)
  );
}

/* TEXTO */
.text-hadjar {
  padding: 10px 15px;

  opacity: 0;
  transform: translateY(30px);

  transition: all 0.4s ease;
}

.card-hadjar.mostrar-texto .text-hadjar {
  opacity: 1;
  transform: translateY(0);
}

.eng-hadjar {
  color: white;

  font-size: 20px;
  line-height: 1.4;
}

.pil-hadjar {
  color: #1e5eff;

  text-align: right;

  font-size: 20px;
  font-weight: 700;
}

/* 📱 RESPONSIVO */
@media (max-width: 600px){

  .radio-f1-hadjar{
    padding:
    clamp(40px, 8vw, 80px)
    10px;
  }

  /* STATUS */
  .radio-status-hadjar{
    top: 10px;
    left: 10px;

    font-size:
    clamp(14px, 3vw, 42px);
  }

  /* INFO */
  .race-info-hadjar{
    top: 10px;
    right: 10px;

    gap:
    clamp(6px, 2vw, 15px);

    font-size:
    clamp(12px, 2.5vw, 30px);
  }

  /* CARD */
  .card-hadjar{
    width: min(90%, 280px);

    aspect-ratio: 2 / 3;
    height: auto;
  }

  /* NUMBER */
  .left-hadjar{
    top:
    clamp(40px, 10vw, 60px);
  }

  .number-hadjar{
    font-size:
    clamp(60px, 15vw, 120px);
  }

  /* RIGHT */
  .right-hadjar{
    top: 15px;
    right: 10px;
  }

  .right-hadjar h1{
    font-size:
    clamp(14px, 3vw, 20px);
  }

  .right-hadjar h2{
    font-size:
    clamp(12px, 2.5vw, 16px);
  }

  .logo-hadjar{
    width:
    clamp(24px, 5vw, 40px);
  }

  /* WAVE */
  .wave-hadjar{
    top:
    clamp(110px, 30vw, 160px);

    height:
    clamp(30px, 8vw, 50px);
  }

  /* TEXTO */
  .content-hadjar{
    transform: scaleY(0);

    transform-origin: bottom;

    transition: transform 0.4s ease;

    height: auto;
  }

  .card-hadjar.mostrar-texto .content-hadjar{
    transform: scaleY(1);
  }

  .text-hadjar{
    padding: 10px 15px;

    opacity: 0;
    transform: translateY(10px);

    transition: all 0.4s ease;
  }

  .card-hadjar.mostrar-texto .text-hadjar{
    opacity: 1;
    transform: translateY(0);
  }

  .eng-hadjar,
  .pil-hadjar{
    font-size:
    clamp(12px, 3vw, 20px);
  }

}

