.charles-banner-bg{
  position: relative;

  width: 100%;
  height: 100vh;

  overflow: hidden;

  background-image: url("charles/banner.avif");
  background-size: cover;
  background-position: center;

  display: flex;
  align-items: center;
}

/* LIGHT FOLLOW MOUSE */
.charles-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(220,0,0,0.25) 0%,
    rgba(255,24,24,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY */
.charles-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

  background:
  linear-gradient(
    to right,
    rgba(0,0,0,0.85),
    rgba(0,0,0,0.25),
    rgba(0,0,0,0.75)
  );

  z-index: 1;
}

/* CONTEÚDO ACIMA */
.charles-banner-bg > *{
  position: relative;
  z-index: 5;
}

/* =========================
   HOME BUTTON
========================= */

.home-btn-charles{
  position: absolute;

  top: 105px;
  left: 25px;

  display: flex;
  align-items: center;
  gap: 10px;

  padding: 10px 18px;

  border-radius: 40px;

  background: rgba(255,255,255,0.08);

  backdrop-filter: blur(10px);

  text-decoration: none;

  transition: 0.3s;
}

.home-btn-charles img{
  width: 48px;
}

.home-btn-charles span{
  color: #fff;
  font-weight: 700;
  font-size: 34px;
}

.home-btn-charles:hover{
  transform: scale(1.05);
  background: rgba(220,0,0,0.15);
}

/* =========================
   INFO
========================= */

.charles-banner-info{
  position: absolute;

  left: 70px;
  top: 50%;

  transform: translateY(-50%);

  display: flex;
  flex-direction: column;

  gap: 14px;
}

/* NOME */
.charles-nome{
  line-height: 0.9;
}

.charles-nome span{
  display: block;

  font-size: 42px;
  font-weight: 300;

  color: rgba(255,255,255,0.7);

  text-transform: uppercase;
  letter-spacing: 3px;
}

.charles-nome strong{
  display: block;

  font-size: 95px;
  font-weight: 900;

  color: #dc0000;

  text-transform: uppercase;
  letter-spacing: 4px;

  text-shadow:
  0 0 10px rgba(220,0,0,0.4),
  0 0 25px rgba(255,24,24,0.2);
}

/* PAÍS */
.charles-pais{
  font-size: 18px;
  font-weight: 600;

  color: rgba(255,255,255,0.85);

  letter-spacing: 2px;
}

/* EQUIPE */
.charles-equipe{
  width: fit-content;

  padding: 10px 18px;

  border-radius: 30px;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(255,255,255,0.1);

  backdrop-filter: blur(10px);

  color: #dc0000;

  font-size: 20px;
  font-weight: 700;

  letter-spacing: 1px;
}

/* FRASE */
.charles-frase{
  margin-top: 8px;

  padding-left: 14px;

  border-left: 3px solid #dc0000;

  color: rgba(255,255,255,0.75);

  font-size: 20px;
  font-style: italic;

  max-width: 450px;
}

/* =========================
   NÚMERO
========================= */

.charles-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,255,255,0.08);

  font-family: 'Russo One', sans-serif;

  user-select: none;
  pointer-events: none;

  animation: charlesGlow 4s ease-in-out infinite;
}

@keyframes charlesGlow{

  0%{
    text-shadow: 0 0 15px rgba(220,0,0,0.98);
  }

  50%{
    text-shadow:
    0 0 25px rgba(220,0,0,0.25),
    0 0 60px rgba(255,24,24,0.12);
  }

  100%{
    text-shadow: 0 0 15px rgba(220,0,0,0.08);
  }
}

/* =========================
   CHUVA
========================= */

.charles-rain{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.charles-rain span{
  position: absolute;
  top: -120px;
  left: calc(10% * var(--i));

  width: 7px;
  height: 120px;

  background: linear-gradient(
    transparent,
    rgba(255,255,255,0.8),
    transparent
  );

  opacity: 0.5;

  animation: charlesRain 2s linear infinite;
}

.charles-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.charles-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.charles-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.charles-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.charles-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.charles-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.charles-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.charles-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}

/* ANIMAÇÃO */

@keyframes charlesRain{

  0%{
    transform:
    translateY(-200px);

    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform:
    translateY(120vh);

    opacity: 0;
  }

}



/* =========================
   PARTICLES
========================= */

.charles-particles{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.charles-particles span{
  position: absolute;

  width: 16px;
  height: 16px;

  border-radius: 50%;

  background: rgba(255,255,255,0.7);

  box-shadow:
  0 0 10px rgba(255,255,255,0.8),
  0 0 20px rgba(220,0,0,0.4);

  animation: charlesFloat linear infinite;
}

.charles-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.charles-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.charles-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.charles-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.charles-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.charles-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.charles-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.charles-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.charles-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.charles-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}

/* ANIMAÇÃO */

@keyframes charlesFloat{

  0%{
    transform:
    translateY(100vh)
    scale(0.5);

    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  50%{
    opacity: 0.8;
  }

  100%{
    transform:
    translateY(-120px)
    scale(1.4);

    opacity: 0;
  }

}


