.slider-charles{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-charles {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-charles::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-charles-container,
.titulo-charles-slider,
.dots-charles,
.btn-charles {
  position: relative;
  z-index: 2;
}

.titulo-charles-slider {
  font-size: 40px;
  color: #dc0000;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-charles-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-charles-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-charles {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-charles img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-charles-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-charles-texto h3 {
  color: #dc0000;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-charles-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-charles {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(250,0,0,0.6);
  border: none;
  color: #fff;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-charles:hover {
  background: #ffffff;
  color:#dc0000;
}

/* BOLINHAS */
.dots-charles {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-charles {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-charles:hover {
  background: #dc0000;
}

.dot-charles.active {
  background: #ffffff;
  transform: scale(1.3);
}
.dots-charles {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-charles img {
    height: 300px;
  }

  .slide-charles-texto h3 {
    font-size: 20px;
  }

  .slide-charles-texto p {
    font-size: 14px;
  }
}

.numeros-charles{
  background: linear-gradient(
    120deg,
    #000000 0%,
    #120000 45%,
    #8b0000 75%,
    #ff1e1e 100%
  );

  position: relative;
  min-height: 650px;
  padding: 80px 0;
  overflow: hidden;
}

.numeros-charles::after{
  content:"";
  position:absolute;
  inset:0;

  background: radial-gradient(
    circle at center,
    transparent 40%,
    rgba(0,0,0,0.88) 100%
  );

  z-index:1;
}

.bg-numeros-charles{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter: blur(3px) brightness(0.55);

  z-index:0;
}

.overlay-numeros-charles{
  position:absolute;
  inset:0;
  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-charles{
  position:relative;
  z-index:2;

  text-align:center;

  color:#ff1e1e;
  font-size:44px;

  margin-bottom:40px;

  text-shadow:0 0 15px rgba(255,0,0,0.5);
}

/* ===== GRID ===== */
.stats-grid-charles{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns:repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-charles{
  background:rgba(250,250,250,0.68);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:clamp(18px,3vw,30px);

  text-align:center;
  color:red;

  border:1px solid #ff1e1e;

  box-shadow:0 10px 30px rgba(250,0,0,0.65);

  opacity:0;
  transform:translateY(60px);

  transition:0.6s ease;
}

.card-stat-charles.ativo{
  opacity:1;
  transform:translateY(0);

  animation:glowcharles 2s infinite alternate;
}

/* ===== GLOW ===== */
@keyframes glowcharles{

  from{
    box-shadow:0 0 10px #b30000;
  }

  to{
    box-shadow:0 0 30px #ff1e1e;
  }

}

/* ===== NÚMERO ===== */
.card-stat-charles span{
  display:block;

  font-size:clamp(32px,5vw,60px);
  font-weight:bold;

  color:#ff1e1e;

  text-shadow:0 0 10px rgba(0,0,0,0.9);
}

/* ===== TEXTO ===== */
.card-stat-charles p{
  margin-top:10px;

  font-size:28px;

  color:#ff4d4d;
}

/* ===== HOVER ===== */
.card-stat-charles:hover{
  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(255,0,0,0.35);
}

/* ===== CARD GRANDE ===== */
.grande-charles{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-charles{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #8b0000,
    #ff1e1e
  );

  box-shadow:0 0 10px #ff1e1e;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-charles{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #ff0000,
    transparent 70%
  );

  animation:pulsarcharles 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsarcharles{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-charles{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-charles{
    grid-column:span 1;
  }

  .titulo-numeros-charles{
    font-size:32px;
  }

}



