    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-charles h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-charles h3 span {
