}


.skill-numero-charles {
    color: #Dc0000;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-charles::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-charles {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-charles {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #Dc0000,
            #F0f0f0
        );

    box-shadow:
        0 0 12px
        rgba(255,0,0,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-charles {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-charles {
    margin-bottom: 35px;
}


.grafico-header-charles > span {
    display: block;

    margin-bottom: 10px;

    color: #Dc0000;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-charles h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-charles h3 span {
    color: #Dc0000;
}


.grafico-layout-charles {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-charles {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-charles {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-charles {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-charles {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-charles {
    fill:
        rgba(255,0,0,.20);

    stroke: #Dc0000;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,0,0,.35)
        );
}


.radar-ponto-charles {
    fill: #Dc0000;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-charles {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-charles {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-charles {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-charles {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-charles {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-charles {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-charles {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-charles {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-charles {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-charles:hover {
    transform:
        translateX(6px);
}


.resumo-icone-charles {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,0,0,.10);

    color: #Dc0000;

    font-size: 18px;
}


.resumo-card-charles > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-charles h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-charles p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-charles {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,0,0,.12),
            rgba(255,0,0,.02)
        );

    border:
        1px solid
        rgba(255,0,0,.25);
}


.pilotagem-conclusao-charles::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,0,0,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-charles > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-charles > span {
    display: block;

    margin-bottom: 18px;

    color: #Dc0000;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-charles h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-charles strong {
    color: #Dc0000;
}


.pilotagem-conclusao-charles p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-charles {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-charles.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-charles {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-charles {
        min-height: 600px;
    }


    .grafico-layout-charles {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-charles {
        max-width: 430px;
