  font-size: clamp(60px, 15vw, 120px);
  color: #dc0000;
}

/* RIGHT */
.right-charles{
  position: absolute;
  top: 15px;
  right: 10px;
  text-align: right;
}

.right-charles h1{
  color: #dc0000;
  margin: 0;
  font-size: clamp(14px, 3vw, 20px);
}

.right-charles h2{
  color: white;
  margin: 0;
  font-size: clamp(12px, 2.5vw, 16px);
}

.logo-charles{
  width: clamp(24px, 5vw, 40px);
  margin-top: 8px;
}

/* WAVE */
.wave-charles{
  position: absolute;
  top: clamp(110px, 30vw, 160px);
  left: 0;

  width: 100%;
  height: clamp(30px, 8vw, 50px);

  display: flex;
  align-items: flex-end;
}

.wave-charles span{
  flex: 1;
  margin: 0 1px;

  height: 6px;
  background: linear-gradient(to top, #dc0000, transparent);

  animation: wave-charles infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-charles.falando .wave-charles span{
  animation-play-state: running;
}

/* TEXTO */
.content-charles{
  position: absolute;
  bottom: 0;
  width: 100%;

  transform: scaleY(0);
  transform-origin: bottom;

  transition: transform 0.4s ease;
}

.card-charles.mostrar-texto .content-charles{
  transform: scaleY(1);
}

.text-charles{
  padding: 10px 15px;

  opacity: 0;
  transform: translateY(10px);

  transition: all 0.4s ease;
}

.card-charles.mostrar-texto .text-charles{
  opacity: 1;
  transform: translateY(0);
}

.eng-charles{
  color: white;
  font-size: clamp(12px, 3vw, 20px);
}

.pil-charles{
  color: #dc0000;
  text-align: right;
  font-size: clamp(12px, 3vw, 20px);
}

}

.galeria-charles{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(220,0,0,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-charles::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(220,0,0,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-charles{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(220,0,0,.18);
}

/* GRID */
.grid-galeria-charles{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-charles{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-charles img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-charles:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-charless{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-charles:hover .overlay-charless{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-charless h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA */
.overlay-charless h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #dc0000,
    #ff4d4d
  );

  box-shadow:
  0 0 18px rgba(220,0,0,.5);
}

/* DESCRIÇÃO */
.overlay-charless p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-charles::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(220,0,0,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-charles:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-charles{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightboxChar .3s ease;
}

@keyframes fadeLightboxChar{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-charles{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightboxChar .35s ease;
}

@keyframes zoomLightboxChar{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-charles{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-charles:hover{
  transform:rotate(90deg);

  background:
  rgba(220,0,0,.18);

  border-color:
  rgba(220,0,0,.35);

  color:#dc0000;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-charles{
    grid-template-columns:1fr;
  }

  .overlay-charles h3{
    font-size:20px;
  }

  .fechar-charles{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

