.slider-lewis{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-lewis {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-lewis::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-lewis-container,
.titulo-lewis-slider,
.dots-lewis,
.btn-lewis {
  position: relative;
  z-index: 2;
}

.titulo-lewis-slider {
  font-size: 40px;
  color: #dc0000;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-lewis-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-lewis-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-lewis {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-lewis img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-lewis-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-lewis-texto h3 {
  color: #dc0000;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-lewis-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-lewis {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(250,0,0,0.6);
  border: none;
  color: #fff;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-lewis:hover {
  background: #ffffff;
  color:#dc0000;
}

/* BOLINHAS */
.dots-lewis {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-lewis {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-lewis:hover {
  background: #dc0000;
}

.dot-lewis.active {
  background: #ffffff;
  transform: scale(1.3);
}
.dots-lewis {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-lewis img {
