    transparent 40%,
    rgba(0,0,0,0.88) 100%
  );

  z-index:1;
}

.bg-numeros-lewis{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter: blur(3px) brightness(0.55);

  z-index:0;
}

.overlay-numeros-lewis{
  position:absolute;
  inset:0;
  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-lewis{
  position:relative;
  z-index:2;

  text-align:center;

  color:#ff1e1e;
  font-size:44px;

  margin-bottom:40px;

  text-shadow:0 0 15px rgba(255,0,0,0.5);
}

/* ===== GRID ===== */
.stats-grid-lewis{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns:repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-lewis{
  background:rgba(250,250,250,0.68);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:clamp(18px,3vw,30px);

  text-align:center;
  color:red;

  border:1px solid #ff1e1e;

  box-shadow:0 10px 30px rgba(250,0,0,0.65);

  opacity:0;
  transform:translateY(60px);

  transition:0.6s ease;
}

.card-stat-lewis.ativo{
  opacity:1;
  transform:translateY(0);

  animation:glowlewis 2s infinite alternate;
}

/* ===== GLOW ===== */
@keyframes glowlewis{

  from{
    box-shadow:0 0 10px #b30000;
  }

  to{
    box-shadow:0 0 30px #ff1e1e;
  }

}

/* ===== NÚMERO ===== */
.card-stat-lewis span{
  display:block;

  font-size:clamp(32px,5vw,60px);
  font-weight:bold;

  color:#ff1e1e;

  text-shadow:0 0 10px rgba(0,0,0,0.9);
}

/* ===== TEXTO ===== */
.card-stat-lewis p{
  margin-top:10px;

  font-size:28px;

  color:#ff4d4d;
}

/* ===== HOVER ===== */
.card-stat-lewis:hover{
  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(255,0,0,0.35);
}

/* ===== CARD GRANDE ===== */
.grande-lewis{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-lewis{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #8b0000,
    #ff1e1e
  );

  box-shadow:0 0 10px #ff1e1e;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-lewis{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #ff0000,
    transparent 70%
  );

  animation:pulsarlewis 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsarlewis{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-lewis{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-lewis{
    grid-column:span 1;
  }

  .titulo-numeros-lewis{
    font-size:32px;
  }

}

/* =========================================================
   lewis — TIMELINE
========================================================= */

.lewis-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(255,0,0,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.lewis-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.lewis-timeline-title{
  color:#Dc0000;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(255,0,0,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.lewis-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.lewis-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.lewis-ano-btn:hover{
  background:rgba(255,0,0,0.15);

  color:#Dc0000;

  transform:translateY(-2px);
}


.lewis-ano-btn.active{
  background:#Dc0000;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,0,0,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.lewis-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.lewis-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.lewis-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.lewis-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.lewis-team-change{
  position:relative;

  border:1px solid rgba(255,0,0,.45);

  box-shadow:
    0 0 20px rgba(255,0,0,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-lewis{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Dc0000,
      #Dc0000
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferlewis .5s ease;
}


@keyframes transferlewis{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.lewis-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,0,0,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.lewis-corrida-card:hover::before{
  opacity:1;
}


.lewis-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,0,0,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.lewis-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.lewis-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.lewis-vitoria .lewis-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,0,0,0.25);

}


.lewis-podio .lewis-resultado{

  color: #Dc0000 ;

  text-shadow:
    0 0 10px rgba(255,0,0,0.2);

}


.lewis-pontos .lewis-resultado{

  color:#ffffff;

}


.lewis-dnf .lewis-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.lewis-sem-pontos .lewis-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.lewis-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#Dc0000;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.lewis-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.lewis-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

  opacity:0;

  transform:translateY(15px);

  transition:.4s ease;

  box-sizing:border-box;
}


.lewis-summary-card.show{

  opacity:1;

  transform:translateY(0);

}


.lewis-summary-title{

  color:#Dc0000;

  font-size:18px;

  font-weight:900;

  margin-bottom:10px;

  letter-spacing:1px;

}


.lewis-summary-stats{

  display:flex;

  justify-content:space-between;

  gap:10px;
}


.lewis-summary-box{

  flex:1;

  padding:7px;

  border-radius:9px;

  background:
    rgba(255,255,255,0.03);

  border:
    1px solid rgba(255,255,255,0.06);
}


.lewis-summary-label{

  display:block;

  font-size:11px;

  color:#aaa;

  margin-bottom:3px;

  text-transform:uppercase;

  letter-spacing:1px;
}


.lewis-summary-value{

  font-size:22px;

  font-weight:900;

  color:#fff;
}


/* =========================================================
   TABLET
========================================================= */

@media(max-width:900px){

  .lewis-timeline{

    padding:
      25px 15px;

  }


  .lewis-top-timeline{

    align-items:center;

    margin-bottom:15px;

  }


  .lewis-corridas-container{

    grid-template-columns:
      repeat(4,1fr);

    gap:8px;

  }


  .lewis-team-logo{

    width:42px;

    height:42px;

  }


  .lewis-corrida-card{

    padding:8px;

  }

}


