/* =========================================================
   TÍTULOS DO lewis VERSTAPPEN
   LAYOUT 100dvh
========================================================= */

#lewis-title-container {
    width: 100%;
    height: 100dvh;
    max-height: 100dvh;

    overflow: hidden;

    background: #050505;
}


/* =========================================================
   CONTAINER PRINCIPAL
========================================================= */

.lewis-title-content {
    width: 100%;
    height: 100%;
    max-height: 100%;

    overflow: hidden;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.lewis-season-card {
    position: relative;

    width: 100%;
    height: 100%;
    max-height: 100dvh;

    margin: 0 auto;

    padding: clamp(14px, 2vw, 30px);

    box-sizing: border-box;

    border-radius: 30px;

    overflow: hidden;

    background:
        radial-gradient(
            circle at 90% 5%,
            rgba(255,0,0,.13),
            transparent 30%
        ),
        radial-gradient(
            circle at 10% 90%,
            rgba(255,0,0,.06),
            transparent 30%
        ),
        #050505;

    border: 1px solid rgba(255,0,0,.25);

    color: #fff;

    font-family: 'Inter', sans-serif;

    display: flex;
    flex-direction: column;
}


/* =========================================================
   BOTÕES DOS TÍTULOS
========================================================= */

.lewis-title-buttons {
    flex-shrink: 0;

    width: 100%;

    display: flex;

    justify-content: center;
    align-items: center;

    gap: 10px;

    margin: 0 0 clamp(10px, 1.5vh, 20px);

    z-index: 10;
}


.lewis-title-btn {
    position: relative;

    padding: 10px 20px;

    min-width: 158px;

    border: none;
    outline: none;

    border-radius: 10px;

    background: rgba(255,255,255,.06);

    color: #fff;

    font-size: 18px;

    font-weight: 800;

    letter-spacing: .5px;

    cursor: pointer;

    transition:
        transform .25s ease,
        background .25s ease,
        box-shadow .25s ease;

    backdrop-filter: blur(10px);

    overflow: hidden;
}


.lewis-title-btn::before {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            135deg,
            rgba(255,255,255,.15),
            transparent
        );

    opacity: 0;

    transition: opacity .25s ease;
}


.lewis-title-btn:hover {
    transform: translateY(-2px);

    background: rgba(255,255,255,.12);

    box-shadow:
        0 8px 20px rgba(0,0,0,.35);
}


.lewis-title-btn:hover::before {
    opacity: 1;
}


.lewis-title-btn.active {
    background:
        linear-gradient(
            135deg,
            #Dc0000,
            #660000
        );

    color: #fff;

    box-shadow:
        0 0 18px rgba(255,0,0,.4),
        0 8px 20px rgba(0,0,0,.4);

    transform: translateY(-1px);
}


.lewis-title-btn.active::after {
    content: "🏆";

    margin-left: 5px;

    font-size: 10px;
}


/* =========================================================
   HERO
========================================================= */

.lewis-hero {
    flex: 1;

    min-height: 0;

    width: 100%;

    display: grid;

    grid-template-columns: minmax(280px, .9fr) minmax(0, 1.1fr);

    gap: clamp(20px, 3vw, 50px);

    align-items: center;

    overflow: hidden;
}


/* =========================================================
   LADO DA IMAGEM
========================================================= */

.lewis-hero-left {
    position: relative;

    height: 100%;

    min-height: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.lewis-hero-art {
    width: 100%;
    height: 100%;

    max-height: 100%;
    object-fit: contain;

    object-position: center center;

    filter:
        drop-shadow(
            0 25px 35px rgba(0,0,0,.7)
        );

    transition:
        transform .5s ease,
        filter .5s ease;
}


.lewis-hero-left:hover .lewis-hero-art {
    transform: scale(1.025);

    filter:
        drop-shadow(
            0 30px 45px rgba(0,0,0,.8)
        );
}


/* =========================================================
   LADO DIREITO
========================================================= */

.lewis-hero-right {
    min-width: 0;
    min-height: 0;

    height: 100%;

    display: flex;

    flex-direction: column;

    justify-content: center;

    gap: clamp(8px, 1.3vh, 18px);

    overflow: hidden;
}


/* =========================================================
   ÁREA DO TÍTULO
========================================================= */

.lewis-title-area {
    flex-shrink: 0;
}


.lewis-year {
    display: block;

    margin-bottom: 6px;

    font-size: clamp(30px, 2vw, 40px);

    line-height: .9;

    font-weight: 900;

    color: #Dc0000;

    letter-spacing: -2px;
}


.lewis-name {
    margin: 0;

    font-size: clamp(32px, 4vw, 80px);

    line-height: .82;

    font-weight: 900;

    letter-spacing: -5px;

    text-transform: uppercase;

    color: #fff;
}


.lewis-name span {
    display: block;

    color: #Dc0000;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.lewis-subtitle {
    margin: clamp(10px, 1.5vh, 18px) 0 0;

    font-size: clamp(13px, 1.5vw, 24px);

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #ddd;
}


/* =========================================================
   DESCRIÇÃO
========================================================= */

.lewis-description {
    flex-shrink: 0;

    width: 100%;
    max-width: 720px;

    font-size: clamp(11px, 1.2vw, 18px);

    line-height: 1.55;

    color: #cfcfcf;

    overflow: visible;

    word-break: normal;
    overflow-wrap: break-word;
}

/* =========================================================
   ESTATÍSTICAS
========================================================= */

.lewis-stats {
    flex-shrink: 0;

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(5, minmax(0, 1fr));

    gap: clamp(6px, 1vw, 14px);
}


.lewis-stat-box {
    min-width: 0;

    padding: clamp(10px, 1.2vw, 18px);

    border-radius: 14px;

    text-align: center;

    background:
        linear-gradient(
            145deg,
            #Dc0000,
            #660000
        );

    border: 1px solid rgba(255,0,0,.4);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.1);
}


.lewis-stat-box h3 {
    margin: 0 0 5px;

    font-size: clamp(20px, 2.5vw, 38px);

    line-height: 1;

    font-weight: 900;

    color: #F0f0f0;
}


.lewis-stat-box p {
    margin: 0;

    font-size: clamp(7px, .8vw, 11px);

    line-height: 1.2;

    text-transform: uppercase;

    letter-spacing: .8px;

    color: #fff;

    font-weight: 700;
}


/* =========================================================
   QUOTE
========================================================= */

.lewis-quote {
    flex-shrink: 0;

    width: 100%;
    box-sizing: border-box;

    padding: clamp(12px, 1.5vw, 24px);

    border-radius: 15px;

    background:
        linear-gradient(
            135deg,
            #Dc0000,
            #660000
        );

    border-left: 4px solid #F0f0f0;

    overflow: visible;
}

.lewis-quote p {
    margin: 0;

    font-size: clamp(11px, 1.2vw, 17px);

    line-height: 1.5;

    color: #fff;

    white-space: normal;

    word-break: normal;

    overflow-wrap: break-word;
}

.lewis-quote span {
    display: block;

    margin-top: 8px;

    font-size: clamp(9px, 1vw, 13px);

    color: #F0f0f0;

    font-weight: 800;
}


/* =========================================================
   TIMELINE
========================================================= */

.lewis-timeline-section {
    flex-shrink: 0;

    width: 100%;

    margin-top: clamp(10px, 1.5vh, 20px);

    min-height: 0;

    overflow: hidden;
}


.lewis-section-title {
    margin: 0 0 clamp(10px, 1.5vh, 18px);

    font-size: clamp(20px, 3vw, 42px);

    line-height: 1;

    font-weight: 900;

    text-align: center;

    text-transform: uppercase;

    color: #fff;
}


.lewis-timeline-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(5, minmax(0, 1fr));

    gap: clamp(8px, 1.2vw, 18px);

    min-height: 0;
}


.lewis-race-card {
    min-width: 0;

    min-height: clamp(130px, 20vh, 250px);

    padding: clamp(12px, 1.4vw, 22px);

    border-radius: 16px;

    background:
        linear-gradient(
            145deg,
            #0d0d0d,
            #080808
        );

    border: 1px solid #222;

    display: flex;

    flex-direction: column;

    justify-content: space-between;

    overflow: hidden;

    transition:
        transform .3s ease,
        box-shadow .3s ease;
}


.lewis-race-card:hover {
    transform: translateY(-5px);

    box-shadow:
        0 12px 30px rgba(0,0,0,.45);
}


.lewis-race-card h3 {
    margin: 0 0 8px;

    font-size: clamp(12px, 1.4vw, 21px);

    line-height: 1.1;

    font-weight: 900;

    text-transform: uppercase;
}


.lewis-race-card p {
    margin: 0;

    font-size: clamp(12px, 1vw, 15px);

    line-height: 1.45;

    color: #bdbdbd;

    overflow: hidden;
}


.lewis-race-result {
    flex-shrink: 0;

    margin-top: 10px;

    padding: 8px;

    border-radius: 9px;

    font-size: clamp(7px, .75vw, 11px);

    line-height: 1.2;

    font-weight: 800;

    text-align: center;

    text-transform: uppercase;

    background: #111;

    color: #fff;

    border: 1px solid rgba(255,255,255,.05);
}


/* =========================================================
   CORES DA TIMELINE
========================================================= */

.lewis-race-card.positive {
    border-color: rgba(35,255,133,.45);
}

.lewis-race-card.positive h3 {
    color: #23ff85;
}


.lewis-race-card.warning {
    border-color: rgba(255,208,0,.45);
}

.lewis-race-card.warning h3 {
    color: #ffd000;
}


.lewis-race-card.danger {
    border-color: rgba(255,61,61,.45);
}

.lewis-race-card.danger h3 {
    color: #ff3d3d;
}


.lewis-race-card.climax {
    border-color: rgba(255,0,0,.7);

    box-shadow:
        0 0 25px rgba(255,0,0,.12);
}

.lewis-race-card.climax h3 {
    color: #Dc0000;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1100px) {

    .lewis-season-card {
        padding: 18px;
    }

    .lewis-hero {
        grid-template-columns:
            minmax(230px, .85fr)
            minmax(0, 1.15fr);

        gap: 25px;
    }

    .lewis-name {
        font-size: clamp(48px, 7vw, 80px);

        letter-spacing: -3px;
    }

    .lewis-timeline-grid {
        gap: 8px;
    }

    .lewis-race-card {
        padding: 10px;
    }
}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

    #lewis-title-container {
        height: 100dvh;
        max-height: 100dvh;
    }


    .lewis-season-card {
        height: 100%;
        max-height: 100dvh;

        padding:
            12px
            10px
            10px;

        border-radius: 20px;
    }


    /* BOTÕES */

    .lewis-title-buttons {
        gap: 6px;

        margin-bottom: 8px;
    }


    .lewis-title-btn {
        min-width: 48px;

        padding: 8px 11px;

        font-size: 10px;

        border-radius: 8px;
    }


    .lewis-title-btn.active::after {
        display: none;
    }


    /* HERO */

    .lewis-hero {
        grid-template-columns:
            42% 58%;

        gap: 10px;

        min-height: 0;

        flex: 1;
    }


    .lewis-hero-left {
        height: 100%;

        min-height: 0;
    }


    .lewis-hero-art {
        width: 100%;
        height: 100%;

        object-fit: contain;
    }


    .lewis-hero-right {
        gap: 7px;

        min-width: 0;

        overflow: hidden;
    }


    /* ANO */

    .lewis-year {
        font-size: clamp(25px, 8vw, 40px);

        margin-bottom: 4px;
    }


    /* NOME */

    .lewis-name {
        font-size: clamp(34px, 9vw, 60px);

        line-height: .83;

        letter-spacing: -2px;
    }


    /* SUBTÍTULO */

    .lewis-subtitle {
        margin-top: 8px;

        font-size: clamp(8px, 2.2vw, 12px);

        letter-spacing: .5px;
    }


    /* DESCRIÇÃO */

.lewis-description {
    flex-shrink: 0;

    width: 100%;

    font-size: clamp(9px, 2.2vw, 12px);

    line-height: 1.45;

    max-height: none;

    overflow: visible;

    word-break: normal;

    overflow-wrap: break-word;
}

    /* ESTATÍSTICAS */

    .lewis-stats {
        grid-template-columns:
            repeat(5, minmax(0, 1fr));

        gap: 4px;
    }


    .lewis-stat-box {
        padding: 8px 3px;

        border-radius: 8px;
    }


    .lewis-stat-box h3 {
        font-size: clamp(16px, 4vw, 24px);

        margin-bottom: 3px;
    }


    .lewis-stat-box p {
        font-size: 6px;

        letter-spacing: .2px;
    }


    /* QUOTE */

.lewis-quote {
    flex-shrink: 0;

    width: 100%;

    padding: 10px 12px;

    border-left-width: 3px;

    border-radius: 10px;

    overflow: visible;
}

.lewis-quote p {
    font-size: clamp(8px, 2vw, 11px);

    line-height: 1.45;

    white-space: normal;

    overflow: visible;
}

.lewis-quote span {
    margin-top: 5px;

    font-size: 8px;
}


    /* TIMELINE */

    .lewis-timeline-section {
        margin-top: 8px;
    }


    .lewis-section-title {
        margin-bottom: 7px;

        font-size: clamp(15px, 4vw, 22px);
    }


    .lewis-timeline-grid {
        grid-template-columns:
            repeat(5, minmax(0, 1fr));

        gap: 4px;
    }


    .lewis-race-card {
        min-height: 115px;

        height: 115px;

        padding: 7px;

        border-radius: 8px;
    }


    .lewis-race-card h3 {
        font-size: 7px;

        line-height: 1.15;

        margin-bottom: 4px;
    }


    .lewis-race-card p {
        font-size: 6px;

        line-height: 1.3;
    }


    .lewis-race-result {
        margin-top: 4px;

        padding: 4px 2px;

        border-radius: 5px;

        font-size: 5px;
    }
}


/* =========================================================
   CELULAR MUITO PEQUENO
========================================================= */

@media (max-width: 400px) {

