/* =========================================================
   Maxlewis— ESTATÍSTICAS DA TEMPORADA 2026
========================================================= */

.lewis-season-2026 {
    position: relative;
    width: 100%;
	 height:100dvh;
	min-height:100dvh;
	padding: 100px 20px;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 85% 20%,
            rgba(220,0,0, 0.13),
            transparent 35%
        ),
        linear-gradient(
            135deg,
            #050505 0%,
            #0b0b0b 50%,
            #111111 100%
        );

    color: #fff;
}


/* =========================================================
   DETALHE LARANJA DE FUNDO
========================================================= */

.lewis-season-2026::before {
    content: "";
    position: absolute;

    width: 450px;
    height: 450px;

    right: -180px;
    bottom: -180px;

    border-radius: 50%;

    background: rgba(220,0,0, 0.08);

    filter: blur(100px);

    pointer-events: none;
}


/* =========================================================
   CONTAINER
========================================================= */

.lewis-season-2026-container {
    position: relative;
    z-index: 2;

    max-width: 1200px;

    margin: auto;

    display: grid;

    grid-template-columns: 350px 1fr;

    gap: 55px;

    align-items: center;
}


/* =========================================================
   IMAGEM
========================================================= */

.lewis-season-2026-image {
    position: relative;

    height: 560px;

    overflow: hidden;

    border-radius: 20px;

    background: #111;

    border: 1px solid rgba(255,255,255,0.08);

    box-shadow:
        0 25px 70px rgba(0,0,0,0.55);
}


/* IMAGEM */

.lewis-season-2026-image img {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center top;

    transition: transform 0.6s ease;
}

.lewis-season-2026-image:hover img {
    transform: scale(1.04);
}


/* =========================================================
   OVERLAY DA IMAGEM
========================================================= */

.lewis-season-2026-image-overlay {
    position: absolute;

    z-index: 2;

    inset: 0;

    background:
        linear-gradient(
            to top,
            rgba(0,0,0,0.85),
            rgba(0,0,0,0.05) 60%
        );

    pointer-events: none;
}


/* =========================================================
   NÚMERO #1
========================================================= */

.lewis-season-2026-number {
    position: absolute;

    z-index: 3;

    left: 25px;
    bottom: 20px;

    font-size: 80px;

    line-height: 1;

    font-weight: 900;

    font-style: italic;

    color: #Dc0000;

    text-shadow:
        0 5px 25px rgba(0,0,0,0.7);
}


/* =========================================================
   NOME DO PILOTO
========================================================= */

.lewis-season-2026-driver-name {
    margin: 0 0 18px;

    font-size: clamp(35px, 4vw, 65px);

    line-height: 0.85;

    font-weight: 900;

    font-style: italic;

    letter-spacing: -3px;

    text-transform: uppercase;

    color: #fff;

    text-shadow:
        0 8px 30px rgba(0,0,0,0.45);
}


/* SOBRENOME EM DESTAQUE */

.lewis-season-2026-driver-name strong {
    display: block;

    color: #Dc0000;

    font-weight: 900;
}

/* =========================================================
   CONTEÚDO
========================================================= */

.lewis-season-2026-content {
    width: 100%;
}


/* =========================================================
   TAG
========================================================= */

.lewis-season-2026-tag {
    display: inline-block;

    margin-bottom: 14px;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 3px;

    text-transform: uppercase;

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.lewis-season-2026-content h2 {
    margin: 0;

    font-size: clamp(38px, 4vw, 54px);

    line-height: 0.95;

    font-weight: 900;

    text-transform: uppercase;

    letter-spacing: -2px;
}

.lewis-season-2026-content h2 strong {
    color: #Dc0000;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.lewis-season-2026-subtitle {
    margin: 18px 0 35px;

    color: #999;

    font-size: 15px;

    line-height: 1.6;
}


/* =========================================================
   CAMPEONATO
========================================================= */

.lewis-season-2026-championship {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 28px;

    margin-bottom: 18px;

    border-radius: 16px;

    background:
        linear-gradient(
            120deg,
            rgba(220,0,0,0.13),
            rgba(255,255,255,0.035)
        );

    border: 1px solid rgba(220,0,0,0.22);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.04);
}


/* INFO CAMPEONATO */

.lewis-season-2026-championship-info {
    display: flex;

    flex-direction: column;

    gap: 8px;
}

.lewis-season-2026-championship-info span {
    font-size: 16px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}

.lewis-season-2026-championship-info strong {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   PONTOS
========================================================= */

.lewis-season-2026-points {
    display: flex;

    flex-direction: column;

    align-items: flex-end;
}

.lewis-season-2026-points span {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #Dc0000;
}

.lewis-season-2026-points small {
    margin-top: 7px;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}


/* =========================================================
   GRID
========================================================= */

.lewis-season-2026-stats {
    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 12px;
}


/* =========================================================
   CARD DE ESTATÍSTICA
========================================================= */

.lewis-season-2026-stat {
    position: relative;

    min-height: 125px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    overflow: hidden;

    border-radius: 14px;

    background:
        linear-gradient(
            145deg,
            rgba(255,255,255,0.065),
            rgba(255,255,255,0.025)
        );

    border: 1px solid rgba(255,255,255,0.07);

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        background 0.3s ease;
}

.lewis-season-2026-stat:hover {
    transform: translateY(-5px);

    border-color: rgba(220,0,0,0.4);

    background:
        linear-gradient(
            145deg,
            rgba(220,0,0,0.11),
            rgba(255,255,255,0.035)
        );
}


/* =========================================================
   BARRA LATERAL
========================================================= */

.lewis-season-2026-stat::before {
    content: "";

    position: absolute;

    left: 0;
    top: 0;

    width: 3px;
    height: 100%;

    background: #Dc0000;

    transform: scaleY(0);

    transform-origin: bottom;

    transition: transform 0.3s ease;
}

.lewis-season-2026-stat:hover::before {
    transform: scaleY(1);
}


/* =========================================================
   ÍCONE
========================================================= */

.lewis-season-2026-stat-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(220,0,0,0.1);

    font-size: 18px;
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.lewis-season-2026-stat-info {
    display: flex;

    flex-direction: column;

    min-width: 0;
}

.lewis-season-2026-stat-info span {
    font-size: 30px;

    line-height: 1;

    font-weight: 900;

    color: #fff;

    white-space: nowrap;
}

.lewis-season-2026-stat-info p {
    margin: 7px 0 0;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #999;
}


/* =========================================================
   RESUMO
========================================================= */

.lewis-season-2026-summary {
    display: grid;

    grid-template-columns: repeat(3, 1fr);

    margin-top: 14px;

    border-radius: 14px;

    overflow: hidden;

    border: 1px solid rgba(255,255,255,0.07);

    background: rgba(255,255,255,0.035);
}


/* ITEM */

.lewis-season-2026-summary-item {
    padding: 22px;

    display: flex;

    flex-direction: column;

    gap: 9px;

    border-right: 1px solid rgba(255,255,255,0.07);
}

.lewis-season-2026-summary-item:last-child {
    border-right: none;
}


/* TEXTO */

.lewis-season-2026-summary-item span {
    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1.5px;

    color: #888;
}


/* VALOR */

.lewis-season-2026-summary-item strong {
    font-size: 25px;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 1000px) {

    .lewis-season-2026-container {
        grid-template-columns: 280px 1fr;

        gap: 35px;
    }

    .lewis-season-2026-image {
        height: 500px;
    }

    .lewis-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .lewis-season-2026-stat {
        min-height: 110px;
    }
}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .lewis-season-2026 {
        padding: 70px 15px;
    }

    .lewis-season-2026-container {
        display: flex;

        flex-direction: column;

        gap: 35px;
    }

    .lewis-season-2026-image {
        width: 100%;

        height: 390px;
    }

    .lewis-season-2026-number {
        font-size: 65px;
    }

    .lewis-season-2026-content h2 {
        font-size: 42px;
    }

    .lewis-season-2026-championship {
        padding: 20px;
    }

    .lewis-season-2026-championship-info strong,
    .lewis-season-2026-points span {
        font-size: 34px;
    }

    .lewis-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .lewis-season-2026-stat {
        padding: 16px;

        min-height: 110px;
    }

    .lewis-season-2026-stat-icon {
        width: 36px;
        height: 36px;

        font-size: 15px;
    }

    .lewis-season-2026-stat-info span {
        font-size: 26px;
    }

    .lewis-season-2026-summary {
        grid-template-columns: 1fr;
    }

    .lewis-season-2026-summary-item {
        border-right: none;

        border-bottom: 1px solid rgba(255,255,255,0.07);
    }

    .lewis-season-2026-summary-item:last-child {
        border-bottom: none;
    }
}


/* =========================================================
   CELULAR PEQUENO
========================================================= */

@media (max-width: 400px) {

    .lewis-season-2026-content h2 {
        font-size: 35px;
    }

    .lewis-season-2026-stats {
        grid-template-columns: 1fr;
    }

    .lewis-season-2026-stat {
        min-height: 100px;
    }

    .lewis-season-2026-championship {
        padding: 18px;
    }

    .lewis-season-2026-championship-info strong,
    .lewis-season-2026-points span {
        font-size: 30px;
    }
}



/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR lewis
========================================================= */

.pilotagem-lewis {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(255,0,0, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(255,0,0, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-lewis {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-lewis {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(255,0,0, .10);

    border:
        1px solid
        rgba(255,0,0, .35);

    color: #Dc0000;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-lewis {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-lewis span {
    color: #Dc0000;
}


.pilotagem-intro-lewis {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-lewis {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-lewis {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(255,0,0, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-lewis::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255,0,0, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-lewis {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-lewis {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-lewis:hover
.perfil-imagem-lewis {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-lewis::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-lewis {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-lewis {
    display: block;

    margin-bottom: 8px;

    color: #Dc0000;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-lewis {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-lewis span {
    display: block;

    color: #Dc0000;
}


.perfil-equipe-lewis {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-lewis {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-lewis i {
    color: #Dc0000;

    font-size: 20px;
}


.perfil-frase-lewis p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-lewis {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-lewis {
    display: block;

    margin-bottom: 12px;

    color: #Dc0000;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-lewis h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-lewis h3 span {
    display: block;

    color: #Dc0000;
}


.pilotagem-analise-lewis > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-lewis {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-lewis {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-lewis:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(255,0,0,.5);

    background:
        rgba(255,0,0,.06);
}


.caracteristica-icone-lewis {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,0,0,.10);

    color: #Dc0000;
}

.caracteristica-icone-lewis i{
	font-size: 40px;

	}



.caracteristica-lewis h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-lewis p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-lewis {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-lewis {
    margin-bottom: 35px;
}


.skills-header-lewis > span {
    display: block;

    margin-bottom: 10px;

    color: #Dc0000;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-lewis h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-lewis h3 span {
    color: #Dc0000;
}


/* GRID */

.skills-grid-lewis {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-lewis {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-lewis:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(255,0,0,.35);
}


.skill-topo-lewis {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-lewis {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-lewis i {
    color: #Dc0000;

    font-size: 26px;
}


.skill-numero-lewis {
    color: #Dc0000;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-lewis::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-lewis {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-lewis {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #Dc0000,
            #F0f0f0
        );

    box-shadow:
        0 0 12px
        rgba(255,0,0,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-lewis {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-lewis {
    margin-bottom: 35px;
}


.grafico-header-lewis > span {
    display: block;

    margin-bottom: 10px;

    color: #Dc0000;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-lewis h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-lewis h3 span {
    color: #Dc0000;
}


.grafico-layout-lewis {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-lewis {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-lewis {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-lewis {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-lewis {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-lewis {
    fill:
        rgba(255,0,0,.20);

    stroke: #Dc0000;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,0,0,.35)
        );
}


.radar-ponto-lewis {
    fill: #Dc0000;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-lewis {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-lewis {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-lewis {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-lewis {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-lewis {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-lewis {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-lewis {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-lewis {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-lewis {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-lewis:hover {
    transform:
        translateX(6px);
}


.resumo-icone-lewis {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,0,0,.10);

    color: #Dc0000;

    font-size: 18px;
}


.resumo-card-lewis > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-lewis h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-lewis p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-lewis {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,0,0,.12),
            rgba(255,0,0,.02)
        );

    border:
        1px solid
        rgba(255,0,0,.25);
}


.pilotagem-conclusao-lewis::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,0,0,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-lewis > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-lewis > span {
    display: block;

    margin-bottom: 18px;

    color: #Dc0000;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-lewis h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-lewis strong {
    color: #Dc0000;
}


.pilotagem-conclusao-lewis p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-lewis {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-lewis.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-lewis {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-lewis {
        min-height: 600px;
    }


    .grafico-layout-lewis {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-lewis {
        max-width: 430px;
    }


    .caracteristicas-lewis {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

    .pilotagem-lewis {
        padding:
            70px
            15px;
    }


    .pilotagem-header-lewis {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-lewis {
        font-size: 42px;

        letter-spacing: -2px;
    }


    /* PERFIL */

    .pilotagem-perfil-lewis {
        min-height: 500px;

        border-radius: 20px;
    }


    .perfil-info-lewis {
        padding:
            25px
            20px;
    }


    .perfil-nome-lewis {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-lewis {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-lewis h3 {
        font-size: 38px;
    }


    .pilotagem-analise-lewis > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-lewis {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-lewis {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-lewis {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-lewis {
        margin-top: 70px;
    }


    .skills-grid-lewis {
        grid-template-columns: 1fr;
    }


    .skill-card-lewis {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-lewis {
        margin-top: 70px;
    }


    .grafico-layout-lewis {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-lewis {
        width: 80%;
    }


    .radar-label-lewis {
        font-size: 7px;
    }


    .radar-top-right-lewis {
        right: -28px;
    }


    .radar-bottom-right-lewis {
        right: -35px;
    }


    .radar-bottom-left-lewis {
        left: -35px;
    }


    .radar-top-left-lewis {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-lewis {
        padding: 0 10px;
    }


    .resumo-card-lewis {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-lewis h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-lewis {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-lewis h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-lewis p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-lewis {
        font-size: 36px;
    }


    .pilotagem-perfil-lewis {
        min-height: 450px;
    }


    .perfil-nome-lewis {
        font-size: 38px;
    }


    .analise-topo-lewis h3 {
        font-size: 32px;
    }


    .skill-nome-lewis {
        font-size: 9px;
    }


    .radar-container-lewis {
        width: 78%;
    }


    .radar-label-lewis {
        font-size: 6px;
    }


    .resumo-card-lewis p {
        font-size: 11px;
    }

}


 
