}

/* =========================
   NÚMERO
========================= */

.alex-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,255,255,0.08);

  font-family: 'Russo One', sans-serif;

  user-select: none;
  pointer-events: none;

  animation: alexGlow 4s ease-in-out infinite;
}

@keyframes alexGlow{

  0%{
    text-shadow: 0 0 15px rgba(255,255,255,0.98);
  }

  50%{
    text-shadow:
    0 0 25px rgba(255,255,255,0.25),
    0 0 60px rgba(255,255,255,0.12);
  }

  100%{
    text-shadow: 0 0 15px rgba(255,255,255,0.08);
  }
}

/* =========================
   CHUVA
========================= */

.alex-rain{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.alex-rain span{
  position: absolute;
  top: -120px;
  left: calc(10% * var(--i));

  width: 7px;
  height: 120px;

  background: linear-gradient(
    transparent,
    rgba(255,255,255,0.8),
    transparent
  );

  opacity: 0.5;

  animation: alexRain 2s linear infinite;
}

.alex-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.alex-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.alex-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.alex-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.alex-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.alex-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.alex-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.alex-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}

/* ANIMAÇÃO */

@keyframes alexRain{

  0%{
    transform:
    translateY(-200px);

    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform:
    translateY(120vh);

    opacity: 0;
  }

}



/* =========================
   PARTICLES
========================= */

.alex-particles{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.alex-particles span{
  position: absolute;

  width: 16px;
  height: 16px;

  border-radius: 50%;

  background: rgba(255,255,255,0.7);

  box-shadow:
  0 0 10px rgba(0,90,255,0.8),
  0 0 20px rgba(59,190,255,0.4);

  animation: alexFloat linear infinite;
}

.alex-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.alex-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.alex-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.alex-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.alex-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.alex-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.alex-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.alex-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.alex-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.alex-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}

/* ANIMAÇÃO */

@keyframes alexFloat{

  0%{
    transform:
    translateY(100vh)
    scale(0.5);

    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  50%{
    opacity: 0.8;
  }

  100%{
    transform:
    translateY(-120px)
    scale(1.4);

    opacity: 0;
  }

}


