.slider-alex{
  position:relative;
  overflow:hidden;
  width:100%;
  min-height:auto;
  padding-bottom:40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-alex{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  background-size:cover;
  background-position:center;

  filter:blur(40px) brightness(.4);
  transform:scale(1.2);

  transition:.8s ease;

  z-index:0;
}

/* TOM WILLIAMS */
.bg-slider-alex::after{
  content:"";
  position:absolute;
  inset:0;

  background:rgba(0,0,0,0.6);
}

/* CONTEÚDO */
.slider-alex-container,
.titulo-alex-slider,
.dots-alex,
.btn-alex{
  position:relative;
  z-index:2;
}

.titulo-alex-slider{
  font-size:40px;
  color:#005AFF;

  margin-bottom:40px;
}

/* CONTAINER */
.slider-alex-container{
  position:relative;

  max-width:1300px;
  margin:auto;

  overflow:hidden;
  border-radius:20px;

  touch-action:pan-y;
}

/* TRACK */
.slider-alex-track{
  display:flex;
  transition:transform .5s ease;
}

/* SLIDE */
.slide-alex{
  min-width:100%;
  position:relative;
}

/* IMAGEM */
.slide-alex img{
  width:100%;
  height:clamp(320px,65vw,800px);

  object-fit:cover;
  object-position:center top;

  display:block;
}

/* TEXTO */
.slide-alex-texto{
  position:absolute;

  bottom:0;
  left:0;

  width:100%;

  padding:25px;

  background:
  linear-gradient(
    transparent,
    rgba(0,0,0,.95)
  );

  text-align:left;
}

.slide-alex-texto h3{
  color:#005AFF;

  font-size:56px;
  margin-bottom:5px;
}

.slide-alex-texto p{
  color:#ddd;

  font-size:36px;
  line-height:1.5;
}

/* BOTÕES */
.btn-alex{
  position:absolute;

  top:50%;
  transform:translateY(-50%);

  background:rgba(0,90,255,.65);

  border:none;
  color:#fff;

  font-size:30px;

  width:45px;
  height:45px;

  border-radius:50%;

  cursor:pointer;

  transition:.3s;
}

.btn-alex.prev{
  left:15px;
}

.btn-alex.next{
  right:15px;
}

.btn-alex:hover{
  background:#fff;
  color:#005AFF;
}

/* BOLINHAS */
.dots-alex{
  position:absolute;

  bottom:15px;
  left:50%;

  transform:translateX(-50%);

  display:flex;
  gap:10px;

  z-index:3;
}

.dot-alex{
  width:10px;
  height:10px;

  border-radius:50%;

  background:rgba(255,255,255,.3);

  cursor:pointer;

  transition:.3s;
}

.dot-alex:hover{
  background:#005AFF;
}

.dot-alex.active{
  background:#fff;
  transform:scale(1.3);
}

/* RESPONSIVO */
@media(max-width:768px){

  .slide-alex img{
    height:300px;
  }

  .slide-alex-texto h3{
    font-size:20px;
  }

  .slide-alex-texto p{
    font-size:14px;
  }

}

.numeros-alex{
  background: linear-gradient(
    120deg,
    #000510 0%,
    #001a3d 45%,
    #0033a0 75%,
    #00a3ff 100%
  );

  position: relative;
  min-height: 650px;
  padding: 80px 0;
  overflow: hidden;
}

.numeros-alex::after{
  content:"";
  position:absolute;
  inset:0;

  background: radial-gradient(
    circle at center,
    transparent 40%,
    rgba(0,0,0,0.88) 100%
  );

  z-index:1;
}

.bg-numeros-alex{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter: blur(3px) brightness(0.55);

  z-index:0;
}

.overlay-numeros-alex{
  position:absolute;
  inset:0;
  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-alex{
  position:relative;
  z-index:2;

  text-align:center;

  color:#00a3ff;
  font-size:44px;

  margin-bottom:40px;

  text-shadow:0 0 15px rgba(0,163,255,0.5);
}

/* ===== GRID ===== */
.stats-grid-alex{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns:repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-alex{
  background:rgba(0,0,0,0.68);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:clamp(18px,3vw,30px);

  text-align:center;
  color:white;

  border:1px solid #00a3ff;

  box-shadow:0 10px 30px rgba(0,0,0,0.65);

  opacity:0;
  transform:translateY(60px);

  transition:0.6s ease;
}

.card-stat-alex.ativo{
  opacity:1;
  transform:translateY(0);

  animation:glowalex 2s infinite alternate;
}

/* ===== GLOW ===== */
@keyframes glowalex{

  from{
    box-shadow:0 0 10px #0033a0;
  }

  to{
    box-shadow:0 0 30px #00a3ff;
  }

}

/* ===== NÚMERO ===== */
.card-stat-alex span{
  display:block;

  font-size:clamp(32px,5vw,60px);
  font-weight:bold;

  color:#00a3ff;

  text-shadow:0 0 10px rgba(0,0,0,0.9);
}

/* ===== TEXTO ===== */
.card-stat-alex p{
  margin-top:10px;

  font-size:18px;

  color:#7fd3ff;
}

/* ===== HOVER ===== */
.card-stat-alex:hover{
  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(0,163,255,0.35);
}

/* ===== CARD GRANDE ===== */
.grande-alex{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-alex{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #0033a0,
    #00a3ff
  );

  box-shadow:0 0 10px #00a3ff;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-alex{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #00a3ff,
    transparent 70%
  );

  animation:pulsaralex 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsaralex{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-alex{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-alex{
    grid-column:span 1;
  }

  .titulo-numeros-alex{
    font-size:32px;
  }
}


