    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #005aff,
            #F0f0f0
        );

    box-shadow:
        0 0 12px
        rgba(0,90,255,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-albon {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-albon {
    margin-bottom: 35px;
}


.grafico-header-albon > span {
    display: block;

    margin-bottom: 10px;

    color: #005aff;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-albon h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-albon h3 span {
    color: #005aff;
}


.grafico-layout-albon {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-albon {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-albon {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-albon {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-albon {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-albon {
    fill:
        rgba(0,90,255,.20);

    stroke: #005aff;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(0,90,255,.35)
        );
}


.radar-ponto-albon {
    fill: #005aff;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-albon {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-albon {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-albon {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-albon {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-albon {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-albon {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-albon {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-albon {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-albon {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-albon:hover {
    transform:
        translateX(6px);
}


.resumo-icone-albon {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,90,255,.10);

    color: #005aff;

    font-size: 18px;
}


.resumo-card-albon > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-albon h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-albon p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-albon {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(0,90,255,.12),
            rgba(0,90,255,.02)
        );

    border:
        1px solid
        rgba(0,90,255,.25);
}


.pilotagem-conclusao-albon::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(0,90,255,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-albon > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-albon > span {
    display: block;

    margin-bottom: 18px;

    color: #005aff;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-albon h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-albon strong {
    color: #005aff;
}


.pilotagem-conclusao-albon p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-albon {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-albon.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-albon {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-albon {
        min-height: 600px;
    }


    .grafico-layout-albon {
