.wave-alex{
  position:absolute;
  top:clamp(110px,30vw,160px);
  left:0;

  width:100%;
  height:clamp(30px,8vw,50px);

  display:flex;
  align-items:flex-end;
}

.wave-alex span{
  flex:1;
  margin:0 1px;

  height:6px;

  background:
  linear-gradient(
    to top,
    #005AFF,
    transparent
  );

  animation:wave-alex infinite ease-in-out;
  animation-play-state:paused;

  animation-duration:
  calc(.8s + (var(--i) * .02s));

  animation-delay:
  calc(var(--i) * .05s);
}

.card-alex.falando .wave-alex span{
  animation-play-state:running;
}

.content-alex{
  position:absolute;
  bottom:0;
  width:100%;

  transform:scaleY(0);
  transform-origin:bottom;

  transition:transform .4s ease;
}

.card-alex.mostrar-texto .content-alex{
  transform:scaleY(1);
}

.text-alex{
  padding:10px 15px;

  opacity:0;
  transform:translateY(10px);

  transition:all .4s ease;
}

.card-alex.mostrar-texto .text-alex{
  opacity:1;
  transform:translateY(0);
}

.eng-alex{
  color:white;
  font-size:clamp(12px,3vw,20px);
}

.pil-alex{
  color:#005AFF;
  text-align:right;
  font-size:clamp(12px,3vw,20px);
}

}

.galeria-alex{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(0,90,255,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #00112b 0%,
    #002b66 100%
  );
}

/* BRILHO FUNDO */
.galeria-alex::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(0,90,255,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-alex{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(0,90,255,.18);
}

/* GRID */
.grid-galeria-alex{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-alex{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-alex img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-alex:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-alexx{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-alex:hover .overlay-alexx{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-alexx h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA */
.overlay-alexx h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #005aff,
    #dbe7ff
  );

  box-shadow:
  0 0 18px rgba(0,90,255,.5);
}

/* DESCRIÇÃO */
.overlay-alexx p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-alex::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(0,90,255,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-alex:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-alex{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightboxChar .3s ease;
}

@keyframes fadeLightboxChar{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-alex{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightboxChar .35s ease;
}

@keyframes zoomLightboxChar{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-alex{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-alex:hover{
  transform:rotate(90deg);

  background:
  rgba(0,90,250,.18);

  border-color:
  rgba(0,90,250,.35);

  color:#005aff;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-alex{
    grid-template-columns:1fr;
  }

  .overlay-alex h3{
    font-size:20px;
  }

  .fechar-alex{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

.footer-f1-alex{
  position:relative;
  overflow:hidden;

  padding:80px 25px 35px;

  background:
  radial-gradient(circle at top,
  rgba(0,90,250,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #080808 0%,
    #002b66 100%
  );

  border-top:
  1px solid rgba(255,255,255,.06);

  display:flex;
  flex-direction:column;
  gap:45px;

  text-align:center;
}

/* BRILHO */
.footer-f1-alex::before{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  top:-250px;
  left:50%;

  transform:translateX(-50%);

  background:
  radial-gradient(circle,
  rgba(0,90,255,.12),
  transparent 70%);

  filter:blur(100px);

  pointer-events:none;
}

/* CONTEÚDO */
.footer-f1-alex > *{
  position:relative;
  z-index:2;
}

/* BRAND */
.footer-brand-alex p{
  font-size:
  clamp(34px,5vw,58px);

  font-weight:1000;

  color:white;

  margin-bottom:10px;

  letter-spacing:-2px;

  text-transform:uppercase;

  text-shadow:
  0 0 25px rgba(0,90,250,.2);
}

.footer-brand-alex span{
  display:block;

  color:#a5a5a5;

  font-size:15px;

  max-width:600px;

  margin:auto;

  line-height:1.6;
}

/* LINKS */
.footer-links-alex,
.footer-social-alex{
  display:flex;
  justify-content:center;
  flex-wrap:wrap;

  gap:16px;
}

/* BOTÕES */
.footer-links-alex a,
.footer-social-alex a{
  position:relative;

  padding:12px 22px;

  border-radius:999px;

  text-decoration:none;

  color:#e6e6e6;

  background:
  rgba(255,255,255,.03);

  border:
  1px solid rgba(255,255,255,.06);

  font-size:14px;
  font-weight:700;

  transition:
  transform .3s ease,
  background .3s ease,
  border-color .3s ease,
  color .3s ease;
}

/* HOVER */
.footer-links-alex a:hover,
.footer-social-alex a:hover{
  transform:
  translateY(-4px);

  background:
  rgba(0,90,255,.12);

  border-color:
  rgba(250,250,250,.25);

  color:#005aff;

  box-shadow:
  0 10px 25px rgba(0,90,250,.12);
}

/* COPY */
.footer-copy-alex{
  padding-top:15px;

  border-top:
  1px solid rgba(255,255,255,.05);

  color:#777;

  font-size:13px;

  letter-spacing:.5px;
}

/* MOBILE */
@media(max-width:768px){

  .footer-f1-alex{
    gap:35px;
  }

  .footer-brand-alex p{
    font-size:40px;
  }

  .footer-links-alex,
  .footer-social-alex{
    gap:12px;
  }

  .footer-links-alex a,
  .footer-social-alex a{
    width:100%;
    max-width:280px;
  }

}

.back-to-top-alex{
  position:fixed;

  right:28px;
  bottom:28px;

  width:62px;
  height:62px;

  display:flex;
  align-items:center;
  justify-content:center;

  border:none;
  outline:none;

  border-radius:50%;

  cursor:pointer;

  background:
  linear-gradient(
    145deg,
    #005aff,
    #002b66
  );

  color:white;

  font-size:22px;
  font-weight:900;

  z-index:9999;

  box-shadow:
  0 10px 35px rgba(0,90,255,.35),
  0 0 25px rgba(0,90,250,.18);

  transition:
  transform .35s ease,
  box-shadow .35s ease,
  opacity .35s ease;
}

/* BRILHO */
.back-to-top-alex::before{
  content:"";

  position:absolute;
  inset:0;

  border-radius:inherit;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.35),
  transparent 65%);

  opacity:.6;

  transition:.35s ease;
}

/* HOVER */
.back-to-top-alex:hover{
  transform:
  translateY(-6px)
  scale(1.08);

  box-shadow:
  0 18px 45px rgba(0,120,240,.45),
  0 0 35px rgba(250,250,250,.28);
}

.back-to-top-alex:hover::before{
  opacity:1;
  transform:scale(1.1);
}

/* CLICK */
.back-to-top-alex:active{
  transform:scale(.96);
}

/* ÍCONE */
.back-to-top-alex i,
.back-to-top-alex span{
  position:relative;
  z-index:2;
}

/* MOBILE */
