    top:0;
    right:-430px;

    width:420px;
    max-width:100%;

    height:100vh;

    background:#eeeeee;

    border-left:4px solid #0050ff;

    z-index:10001;

    transition:.45s ease;

    overflow-y:auto;

    box-shadow:
    -15px 0 35px rgba(0,0,0,.55);

}

.painel-noticias-carlos.active{

    right:0;

}

