    font-size:24px;

    display:flex;

    align-items:center;

    gap:10px;

}

.topo-noticias-carlos button{

    width:40px;
    height:40px;

    border:none;

    background:none;

    color:#0050ff;

    font-size:25px;

    cursor:pointer;

    transition:.3s;

}

.topo-noticias-carlos button:hover{

    transform:rotate(90deg);

    color:blue;

}

