  overflow:hidden;
  width:100%;
  min-height:auto;
  padding-bottom:40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-sainz{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  background-size:cover;
  background-position:center;

  filter:blur(40px) brightness(.4);
  transform:scale(1.2);

  transition:.8s ease;

  z-index:0;
}

/* TOM WILLIAMS */
.bg-slider-sainz::after{
  content:"";
  position:absolute;
  inset:0;

  background:rgba(0,0,0,0.6);
}

/* CONTEÚDO */
