  max-width:1300px;
  margin:auto;

  overflow:hidden;
  border-radius:20px;

  touch-action:pan-y;
}

/* TRACK */
.slider-sainz-track{
  display:flex;
  transition:transform .5s ease;
}

/* SLIDE */
.slide-sainz{
  min-width:100%;
  position:relative;
}

/* IMAGEM */
