  height:100%;

  object-fit:cover;

  filter: blur(3px) brightness(0.55);

  z-index:0;
}

.overlay-numeros-carlos{
  position:absolute;
  inset:0;
  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-carlos{
  position:relative;
  z-index:2;

  text-align:center;

  color:#00a3ff;
  font-size:44px;

  margin-bottom:40px;

  text-shadow:0 0 15px rgba(0,163,255,0.5);
}

/* ===== GRID ===== */
.stats-grid-carlos{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns:repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-carlos{
  background:rgba(0,0,0,0.68);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:clamp(18px,3vw,30px);

  text-align:center;
  color:white;

  border:1px solid #00a3ff;

  box-shadow:0 10px 30px rgba(0,0,0,0.65);

  opacity:0;
  transform:translateY(60px);

  transition:0.6s ease;
}

.card-stat-carlos.ativo{
  opacity:1;
  transform:translateY(0);

  animation:glowcarlos 2s infinite alternate;
}

/* ===== GLOW ===== */
@keyframes glowcarlos{

  from{
    box-shadow:0 0 10px #0033a0;
  }

  to{
    box-shadow:0 0 30px #00a3ff;
  }

}

/* ===== NÚMERO ===== */
.card-stat-carlos span{
  display:block;

  font-size:clamp(32px,5vw,60px);
  font-weight:bold;

  color:#00a3ff;

  text-shadow:0 0 10px rgba(0,0,0,0.9);
}

/* ===== TEXTO ===== */
.card-stat-carlos p{
  margin-top:10px;

  font-size:18px;

  color:#7fd3ff;
}

/* ===== HOVER ===== */
.card-stat-carlos:hover{
  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(0,163,255,0.35);
}

/* ===== CARD GRANDE ===== */
.grande-carlos{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-carlos{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #0033a0,
    #00a3ff
  );

  box-shadow:0 0 10px #00a3ff;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-carlos{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #00a3ff,
    transparent 70%
  );

  animation:pulsarcarlos 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsarcarlos{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-carlos{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-carlos{
    grid-column:span 1;
  }

  .titulo-numeros-carlos{
    font-size:32px;
  }
}

/* =========================================================
   carlos — TIMELINE
========================================================= */

.carlos-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(0,90,255,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.carlos-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.carlos-timeline-title{
  color:#005aff;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(0,90,255,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.carlos-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.carlos-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.carlos-ano-btn:hover{
  background:rgba(0,90,255,0.15);

  color:#005aff;

  transform:translateY(-2px);
}


.carlos-ano-btn.active{
  background:#005aff;

  color:#000;

  box-shadow:
    0 0 18px rgba(0,90,255,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.carlos-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.carlos-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.carlos-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.carlos-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.carlos-team-change{
  position:relative;

  border:1px solid rgba(0,90,255,.45);

  box-shadow:
    0 0 20px rgba(0,90,255,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-carlos{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #005aff,
      #005aff
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transfercarlos .5s ease;
}


@keyframes transfercarlos{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.carlos-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(0,90,255,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.carlos-corrida-card:hover::before{
  opacity:1;
}


.carlos-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(0,90,255,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.carlos-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.carlos-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.carlos-vitoria .carlos-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(0,90,255,0.25);

}


.carlos-podio .carlos-resultado{

  color: #005aff ;

  text-shadow:
    0 0 10px rgba(0,90,255,0.2);

}


.carlos-pontos .carlos-resultado{

  color:#ffffff;

}


.carlos-dnf .carlos-resultado{

  color:#ff4d4d;

  text-shadow:
