}


.carlos-sem-pontos .carlos-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.carlos-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#005aff;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.carlos-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.carlos-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

