    letter-spacing: -2px;
}

.carlos-season-2026-content h2 strong {
    color: #005aff;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.carlos-season-2026-subtitle {
    margin: 18px 0 35px;

    color: #999;

    font-size: 15px;

    line-height: 1.6;
}


/* =========================================================
   CAMPEONATO
========================================================= */

.carlos-season-2026-championship {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 28px;

    margin-bottom: 18px;

    border-radius: 16px;

    background:
        linear-gradient(
            120deg,
            rgba(0,90,255,0.13),
            rgba(255,255,255,0.035)
        );

    border: 1px solid rgba(0,90,255,0.22);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.04);
