/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR sainz
========================================================= */

.pilotagem-sainz {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(0,90,255, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(0,90,255, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-sainz {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-sainz {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(0,90,255, .10);

    border:
        1px solid
        rgba(0,90,255, .35);

    color: #005aff;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-sainz {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-sainz span {
    color: #005aff;
}


.pilotagem-intro-sainz {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-sainz {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-sainz {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(0,90,255, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-sainz::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(0,90,255, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-sainz {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-sainz {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-sainz:hover
.perfil-imagem-sainz {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-sainz::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-sainz {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-sainz {
    display: block;

    margin-bottom: 8px;

    color: #005aff;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-sainz {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-sainz span {
    display: block;

    color: #005aff;
}


.perfil-equipe-sainz {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-sainz {
