    font-size: 20px;
}


.perfil-frase-sainz p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-sainz {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
