/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-sainz {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-sainz {
    margin-bottom: 35px;
}


.grafico-header-sainz > span {
    display: block;

    margin-bottom: 10px;

    color: #005aff;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-sainz h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-sainz h3 span {
    color: #005aff;
}


.grafico-layout-sainz {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-sainz {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-sainz {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-sainz {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-sainz {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-sainz {
    fill:
        rgba(0,90,255,.20);

    stroke: #005aff;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(0,90,255,.35)
        );
}


.radar-ponto-sainz {
    fill: #005aff;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-sainz {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-sainz {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-sainz {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-sainz {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-sainz {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-sainz {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-sainz {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-sainz {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-sainz {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-sainz:hover {
    transform:
        translateX(6px);
}


.resumo-icone-sainz {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,90,255,.10);

    color: #005aff;

    font-size: 18px;
}


.resumo-card-sainz > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-sainz h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-sainz p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-sainz {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(0,90,255,.12),
            rgba(0,90,255,.02)
        );

    border:
        1px solid
        rgba(0,90,255,.25);
}


.pilotagem-conclusao-sainz::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(0,90,255,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-sainz > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-sainz > span {
    display: block;

    margin-bottom: 18px;

    color: #005aff;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-sainz h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-sainz strong {
    color: #005aff;
}


.pilotagem-conclusao-sainz p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
