    .pilotagem-sainz {
        padding:
            70px
            15px;
    }


    .pilotagem-header-sainz {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-sainz {
        font-size: 42px;

        letter-spacing: -2px;
