.slider-lawson{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-lawson {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.35);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-lawson::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(255,255,255,0.08);
}

/* CONTEÚDO NA FRENTE */
.slider-lawson-container,
.titulo-lawson-slider,
.dots-lawson,
.btn-lawson {
  position: relative;
  z-index: 2;
}

.titulo-lawson-slider {
  font-size: 40px;
  color: #ffffff;
  margin-bottom: 40px;
  text-shadow: 0 0 15px rgba(255,255,255,0.15);
}

/* CONTAINER */
.slider-lawson-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-lawson-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-lawson {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-lawson img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-lawson-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.88));
  text-align: left;
}

.slide-lawson-texto h3 {
  color: #ffffff;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-lawson-texto p {
  color: #e6e6e6;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-lawson {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(25,0,255,0.08);
  border: 1px solid rgba(255,255,255,0.15);
  color: #fff;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-lawson:hover {
  background: #ffffff;
  color: #000;
}

/* BOLINHAS */
.dots-lawson {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-lawson {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.25);

  cursor: pointer;
  transition: 0.3s;
}

.dot-lawson:hover {
  background: #ffffff;
}

.dot-lawson.active {
  background: #ffffff;
  transform: scale(1.3);
}

/* RESPONSIVO */
@media(max-width: 768px){

  .slide-lawson img {
    height: 300px;
  }

  .slide-lawson-texto h3 {
    font-size: 20px;
  }

  .slide-lawson-texto p {
    font-size: 14px;
  }
} 

