/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-lawson {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-lawson {
    display: block;

    margin-bottom: 12px;

    color: #005dc0;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-lawson h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-lawson h3 span {
    display: block;

    color: #005dc0;
}


.pilotagem-analise-lawson > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-lawson {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-lawson {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-lawson:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(0,90,255,.5);

    background:
        rgba(0,90,255,.06);
}


.caracteristica-icone-lawson {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,90,255,.10);

    color: #005dc0;
}

.caracteristica-icone-lawson i{
	font-size: 40px;

	}



.caracteristica-lawson h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-lawson p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-lawson {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-lawson {
    margin-bottom: 35px;
}


.skills-header-lawson > span {
    display: block;

    margin-bottom: 10px;

    color: #005dc0;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-lawson h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-lawson h3 span {
    color: #005dc0;
}


/* GRID */

.skills-grid-lawson {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-lawson {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-lawson:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(0,90,255,.35);
}


.skill-topo-lawson {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-lawson {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-lawson i {
    color: #005dc0;

    font-size: 26px;
}


.skill-numero-lawson {
    color: #005dc0;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-lawson::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-lawson {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-lawson {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #005dc0,
            #Ffd700
        );

    box-shadow:
        0 0 12px
        rgba(0,90,255,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-lawson {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-lawson {
    margin-bottom: 35px;
}


.grafico-header-lawson > span {
    display: block;

    margin-bottom: 10px;

    color: #005dc0;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-lawson h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-lawson h3 span {
    color: #005dc0;
}


.grafico-layout-lawson {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-lawson {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-lawson {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-lawson {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-lawson {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-lawson {
    fill:
        rgba(0,90,255,.20);

    stroke: #005dc0;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(0,90,255,.35)
        );
}


.radar-ponto-lawson {
    fill: #005dc0;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-lawson {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-lawson {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-lawson {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-lawson {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-lawson {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-lawson {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-lawson {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-lawson {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-lawson {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-lawson:hover {
    transform:
        translateX(6px);
}


.resumo-icone-lawson {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(0,90,255,.10);

    color: #005dc0;

    font-size: 18px;
}


.resumo-card-lawson > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-lawson h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-lawson p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-lawson {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(0,90,255,.12),
            rgba(0,90,255,.02)
        );

    border:
        1px solid
        rgba(0,90,255,.25);
}


.pilotagem-conclusao-lawson::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(0,90,255,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-lawson > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-lawson > span {
    display: block;

    margin-bottom: 18px;

    color: #005dc0;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-lawson h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-lawson strong {
    color: #005dc0;
}


.pilotagem-conclusao-lawson p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-lawson {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-lawson.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-lawson {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-lawson {
        min-height: 600px;
    }


    .grafico-layout-lawson {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-lawson {
        max-width: 430px;
    }


    .caracteristicas-lawson {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

.pilotagem-lawson{
        padding:
            70px
            15px;
    }


    .pilotagem-header-lawson {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-lawson {
        font-size: 42px;

        letter-spacing: -2px;
    }


    /* PERFIL */

    .pilotagem-perfil-lawson {
        min-height: 500px;

        border-radius: 20px;
    }


    .perfil-info-lawson {
        padding:
            25px
            20px;
    }


    .perfil-nome-lawson {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-lawson {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-lawson h3 {
        font-size: 38px;
    }


    .pilotagem-analise-lawson > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-lawson {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-lawson {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-lawson {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-lawson {
        margin-top: 70px;
    }


    .skills-grid-lawson {
        grid-template-columns: 1fr;
    }


    .skill-card-lawson {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-lawson {
        margin-top: 70px;
    }


    .grafico-layout-lawson {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-lawson {
        width: 80%;
    }


    .radar-label-lawson {
        font-size: 7px;
    }


    .radar-top-right-lawson {
        right: -28px;
    }


    .radar-bottom-right-lawson {
        right: -35px;
    }


    .radar-bottom-left-lawson {
        left: -35px;
    }


    .radar-top-left-lawson {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-lawson {
        padding: 0 10px;
    }


    .resumo-card-lawson {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-lawson h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-lawson {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-lawson h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-lawson p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-lawson {
        font-size: 36px;
    }


    .pilotagem-perfil-lawson {
        min-height: 450px;
    }


    .perfil-nome-lawson {
        font-size: 38px;
    }


    .analise-topo-lawson h3 {
        font-size: 32px;
    }


    .skill-nome-lawson {
        font-size: 9px;
    }


    .radar-container-lawson {
        width: 78%;
    }


    .radar-label-lawson {
        font-size: 6px;
    }


    .resumo-card-lawson p {
        font-size: 11px;
    }

}


