.radio-f1-lawson {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* 🔵 STATUS */
.radio-status-lawson {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #1e5eff;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-lawson::before {
  content: "●";
  margin-right: 6px;
  animation: blink-lawson 1s infinite;
}

@keyframes blink-lawson {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-lawson {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: white;
}

/* CARD */
.card-lawson {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-lawson::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(30,94,255,0.15), transparent);
  z-index: -1;
}

.card-lawson.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-lawson.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-lawson {
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-lawson {
  font-size: 120px;
  color: #1e5eff;
}

/* DIREITA */
.right-lawson {
  position: absolute;
  top: 20px;
  right: 15px;
  text-align: right;
}

.right-lawson h1 {
  color: #1e5eff;
  margin: 0;
}

.right-lawson h2 {
  color: white;
  margin: 0;
}

.logo-lawson {
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-lawson {
  position: absolute;
  top: 160px;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  align-items: flex-end;
}

.wave-lawson span {
  flex: 1;
  margin: 0 1px;
  height: 6px;

  background: linear-gradient(to top, #1e5eff, transparent);

  animation: wave-lawson infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-lawson.falando .wave-lawson span {
  animation-play-state: running;
}

@keyframes wave-lawson {
  0%,100% { height: 6px; opacity: 0.3 }
  50% { height: 45px; opacity: 1 }
}

/* CONTEÚDO */
.content-lawson {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}

/* TEXTO */
.text-lawson {
  padding: 10px 15px;
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.4s ease;
}

.card-lawson.mostrar-texto .text-lawson {
  opacity: 1;
  transform: translateY(0);
}

.eng-lawson {
  color: white;
  font-size: 20px;
}

.pil-lawson {
  color: #1e5eff;
  text-align: right;
  font-size: 20px;
}

