.galeria-lawson{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(30,94,255,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-lawson::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(30,94,255,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-lawson{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(30,94,255,.18);
}

/* GRID */
.grid-galeria-lawson{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-lawson{
  position:relative;
  overflow:hidden;

  border-radius:24px;
  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-lawson img{
  position:absolute;
  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

.item-galeria-lawson:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-law{
  position:absolute;
  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:.4s ease;
}

.item-galeria-lawson:hover .overlay-law{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-law h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;
}

.overlay-law h3::after{
  content:"";
  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:linear-gradient(90deg,#1e5eff,#7aa7ff);
}

/* DESCRIÇÃO */
.overlay-law p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;
}

/* LIGHTBOX */
.lightbox-lawson{
  position:fixed;
  inset:0;

  background:rgba(0,0,0,.94);

  display:none;
  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);
}

.img-lightbox-lawson{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:0 25px 80px rgba(0,0,0,.8);
}

.fechar-lawson{
  position:absolute;
  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:rgba(255,255,255,.08);

  border:1px solid rgba(255,255,255,.12);

  color:white;
  font-size:34px;

  cursor:pointer;
  transition:.3s ease;
}

.fechar-lawson:hover{
  transform:rotate(90deg);
