.arvid-banner-bg{
  position: relative;

  width: 100%;
  height: 100vh;

  overflow: hidden;

  background-image: url("arvid/banner.jpg");
  background-size: cover;
  background-position: center;

  display: flex;
  align-items: center;
}

/* LIGHT FOLLOW MOUSE */
.arvid-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,0.25) 0%,
    rgba(255,255,255,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY */
.arvid-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

  background:
  linear-gradient(
    to right,
    rgba(0,0,0,0.85),
    rgba(0,0,0,0.25),
    rgba(0,0,0,0.75)
  );

  z-index: 1;
}

/* CONTEÚDO ACIMA */
.arvid-banner-bg > *{
  position: relative;
  z-index: 5;
}

/* =========================
   HOME BUTTON
========================= */

.home-btn-arvid{
  position: absolute;

  top: 105px;
  left: 25px;

  display: flex;
  align-items: center;
  gap: 10px;

  padding: 10px 18px;

  border-radius: 40px;

  background: rgba(255,255,255,0.08);

  backdrop-filter: blur(10px);

  text-decoration: none;

  transition: 0.3s;
}

.home-btn-arvid img{
  width: 48px;
}

.home-btn-arvid span{
  color: #fff;
  font-weight: 700;
  font-size: 34px;
}

.home-btn-arvid:hover{
  transform: scale(1.05);
  background: rgba(255,255,255,0.18);
}

/* =========================
   INFO
========================= */

.arvid-banner-info{
  position: absolute;

  left: 70px;
  top: 50%;

  transform: translateY(-50%);

  display: flex;
  flex-direction: column;

  gap: 14px;
}

.arvid-nome span{
  display: block;

