}

/* =========================
   NÚMERO
========================= */

.arvid-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,255,255,0.08);

  user-select: none;
  pointer-events: none;

  animation: arvidGlow 4s ease-in-out infinite;
}

@keyframes arvidGlow{

  0%{
    text-shadow: 0 0 15px rgba(255,255,255,0.35);
  }

  50%{
    text-shadow:
    0 0 25px rgba(255,255,255,0.15),
    0 0 60px rgba(255,255,255,0.10);
  }

  100%{
    text-shadow: 0 0 15px rgba(255,255,255,0.05);
  }
}

/* =========================
   CHUVA (WHITE STYLE)
========================= */

.arvid-rain{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.arvid-rain span{
  position: absolute;
  top: -120px;
  width: 7px;
  height: 120px;

  background: linear-gradient(
    transparent,
    rgba(255,255,255,0.9),
    transparent
  );

  opacity: 0.5;

  animation: arvidRain 2s linear infinite;
}

.arvid-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.arvid-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.arvid-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.arvid-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.arvid-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.arvid-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.arvid-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.arvid-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}


@keyframes arvidRain{

  0%{
    transform: translateY(-200px);
    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform: translateY(120vh);
    opacity: 0;
  }
}

/* =========================
   PARTICLES
========================= */

.arvid-particles{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.arvid-particles span{
  position: absolute;

  width: 14px;
  height: 14px;

  border-radius: 50%;

  background: rgba(255,255,255,0.8);

  box-shadow:
  0 0 10px rgba(255,255,255,0.8),
  0 0 20px rgba(255,255,255,0.3);

  animation: arvidFloat linear infinite;
}

.arvid-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.arvid-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.arvid-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.arvid-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.arvid-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.arvid-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.arvid-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.arvid-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.arvid-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.arvid-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}





@keyframes arvidFloat{

  0%{
    transform: translateY(100vh) scale(0.5);
    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  100%{
    transform: translateY(-120px) scale(1.4);
    opacity: 0;
  }
}

