.slider-arvid{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-arvid {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.35);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-arvid::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(255,255,255,0.08);
}

/* CONTEÚDO NA FRENTE */
.slider-arvid-container,
.titulo-arvid-slider,
.dots-arvid,
.btn-arvid {
  position: relative;
  z-index: 2;
}

.titulo-arvid-slider {
  font-size: 40px;
  color: #ffffff;
  margin-bottom: 40px;
  text-shadow: 0 0 15px rgba(255,255,255,0.15);
}

/* CONTAINER */
.slider-arvid-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-arvid-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-arvid {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-arvid img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-arvid-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.88));
  text-align: left;
}

.slide-arvid-texto h3 {
  color: #ffffff;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-arvid-texto p {
  color: #e6e6e6;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-arvid {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(25,0,255,0.08);
  border: 1px solid rgba(255,255,255,0.15);
  color: #fff;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-arvid:hover {
  background: #ffffff;
  color: #000;
}

/* BOLINHAS */
.dots-arvid {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-arvid {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.25);

  cursor: pointer;
  transition: 0.3s;
}

.dot-arvid:hover {
  background: #ffffff;
}

.dot-arvid.active {
  background: #ffffff;
  transform: scale(1.3);
}

/* RESPONSIVO */
@media(max-width: 768px){

  .slide-arvid img {
    height: 300px;
  }

  .slide-arvid-texto h3 {
    font-size: 20px;
  }

  .slide-arvid-texto p {
    font-size: 14px;
  }
} 



.numeros-arvid{
  background: linear-gradient(
    120deg,
    #ffffff 0%,
    #dbe8ff 35%,
    #4d79ff 70%,
    #001b6b 100%
  );

  position: relative;
  min-height: 650px;
  padding: 80px 0;
  overflow: hidden;
}

.numeros-arvid::after{
  content:"";
  position:absolute;
  inset:0;

  background: radial-gradient(
    circle at center,
    transparent 35%,
    rgba(0,0,40,0.45) 100%
  );

  z-index:1;
}

.bg-numeros-arvid{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter: blur(3px) brightness(0.7);

  z-index:0;
}

.overlay-numeros-arvid{
  position:absolute;
  inset:0;
  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-arvid{
  position:relative;
  z-index:2;

  text-align:center;

  color:#001b6b;
  font-size:44px;

  margin-bottom:40px;

  text-shadow:0 0 15px rgba(0,60,255,0.35);
}

/* ===== GRID ===== */
.stats-grid-arvid{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns:repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-arvid{
  background:rgba(255,255,255,0.22);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:clamp(18px,3vw,30px);

  text-align:center;
  color:white;

  border:1px solid rgba(0,60,255,.25);

  box-shadow:0 10px 30px rgba(0,0,0,0.18);

  opacity:0;
  transform:translateY(60px);

  transition:0.6s ease;
}

.card-stat-arvid.ativo{
  opacity:1;
  transform:translateY(0);

  animation:glowarvid 2s infinite alternate;
}

/* ===== GLOW ===== */
@keyframes glowarvid{

  from{
    box-shadow:0 0 10px rgba(0,60,255,.25);
  }

  to{
    box-shadow:0 0 30px rgba(77,121,255,.55);
  }

}

/* ===== NÚMERO ===== */
.card-stat-arvid span{
  display:block;

  font-size:clamp(32px,5vw,60px);
  font-weight:bold;

  color:#001b6b;

  text-shadow:0 0 10px rgba(255,255,255,0.4);
}

/* ===== TEXTO ===== */
.card-stat-arvid p{
  margin-top:10px;

  font-size:18px;

  color:#0f172a;
}

/* ===== HOVER ===== */
.card-stat-arvid:hover{
  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(0,60,255,0.22);
}

/* ===== CARD GRANDE ===== */
.grande-arvid{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-arvid{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #003cff,
    #7aa8ff
  );

  box-shadow:0 0 10px #4d79ff;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-arvid{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #4d79ff,
    transparent 70%
  );

  animation:pulsararvid 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsararvid{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-arvid{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-arvid{
    grid-column:span 1;
  }

  .titulo-numeros-arvid{
    font-size:32px;
  }

}



/* =========================================================
   lindblad — TIMELINE
========================================================= */

.lindblad-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(0,180,255,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.lindblad-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.lindblad-timeline-title{
  color:#00b8ff;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(0,184,255,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.lindblad-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.lindblad-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.lindblad-ano-btn:hover{
  background:rgba(0,184,255,0.15);

  color:#00b8ff;

  transform:translateY(-2px);
}


.lindblad-ano-btn.active{
  background:#00b8ff;

  color:#000;

  box-shadow:
    0 0 18px rgba(0,184,255,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.lindblad-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.lindblad-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.lindblad-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.lindblad-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.lindblad-team-change{
  position:relative;

  border:1px solid rgba(0,184,255,.45);

  box-shadow:
    0 0 20px rgba(0,184,255,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-lindblad{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #00b8ff,
      #6be7ff
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferlindblad .5s ease;
}


@keyframes transferlindblad{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.lindblad-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(0,184,255,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.lindblad-corrida-card:hover::before{
  opacity:1;
}


.lindblad-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(0,184,255,0.25);

