    color: #fff;

    text-shadow:
        0 8px 30px rgba(0,0,0,0.45);
}


/* SOBRENOME EM DESTAQUE */

.arvid-season-2026-driver-name strong {
    display: block;

    color: #F9f9f9;

    font-weight: 900;
}

/* =========================================================
   CONTEÚDO
========================================================= */

.arvid-season-2026-content {
    width: 100%;
}


/* =========================================================
   TAG
========================================================= */

.arvid-season-2026-tag {
    display: inline-block;

    margin-bottom: 14px;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 3px;

    text-transform: uppercase;

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.arvid-season-2026-content h2 {
    margin: 0;

    font-size: clamp(38px, 4vw, 54px);

    line-height: 0.95;

    font-weight: 900;

    text-transform: uppercase;

    letter-spacing: -2px;
}

.arvid-season-2026-content h2 strong {
    color: #F9f9f9;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.arvid-season-2026-subtitle {
    margin: 18px 0 35px;

    color: #999;

    font-size: 15px;

    line-height: 1.6;
}


/* =========================================================
   CAMPEONATO
========================================================= */

.arvid-season-2026-championship {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 28px;

    margin-bottom: 18px;

    border-radius: 16px;

    background:
        linear-gradient(
            120deg,
            rgba(249,249,249,0.13),
            rgba(255,255,255,0.035)
        );

    border: 1px solid rgba(249,249,249,0.22);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.04);
}


/* INFO CAMPEONATO */

.arvid-season-2026-championship-info {
    display: flex;

    flex-direction: column;

    gap: 8px;
}

.arvid-season-2026-championship-info span {
    font-size: 16px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}

.arvid-season-2026-championship-info strong {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   PONTOS
========================================================= */

.arvid-season-2026-points {
    display: flex;

    flex-direction: column;

    align-items: flex-end;
}

.arvid-season-2026-points span {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #F9f9f9;
}

.arvid-season-2026-points small {
    margin-top: 7px;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}


/* =========================================================
   GRID
========================================================= */

.arvid-season-2026-stats {
    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 12px;
}


/* =========================================================
   CARD DE ESTATÍSTICA
========================================================= */

.arvid-season-2026-stat {
    position: relative;

    min-height: 125px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    overflow: hidden;

    border-radius: 14px;

    background:
        linear-gradient(
            145deg,
            rgba(255,255,255,0.065),
            rgba(255,255,255,0.025)
        );

    border: 1px solid rgba(255,255,255,0.07);

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        background 0.3s ease;
}

.arvid-season-2026-stat:hover {
    transform: translateY(-5px);

    border-color: rgba(249,249,249,0.4);

    background:
        linear-gradient(
            145deg,
            rgba(249,249,249,0.11),
            rgba(255,255,255,0.035)
        );
}


/* =========================================================
   BARRA LATERAL
========================================================= */

.arvid-season-2026-stat::before {
    content: "";

    position: absolute;

    left: 0;
    top: 0;

    width: 3px;
    height: 100%;

    background: #F9f9f9;

    transform: scaleY(0);

    transform-origin: bottom;

    transition: transform 0.3s ease;
}

.arvid-season-2026-stat:hover::before {
    transform: scaleY(1);
}


/* =========================================================
   ÍCONE
========================================================= */

.arvid-season-2026-stat-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(249,249,249,0.1);

    font-size: 18px;
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.arvid-season-2026-stat-info {
    display: flex;

    flex-direction: column;

    min-width: 0;
}

.arvid-season-2026-stat-info span {
    font-size: 30px;

    line-height: 1;

    font-weight: 900;

    color: #fff;

    white-space: nowrap;
}

.arvid-season-2026-stat-info p {
    margin: 7px 0 0;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #999;
}


/* =========================================================
   RESUMO
========================================================= */

.arvid-season-2026-summary {
    display: grid;

    grid-template-columns: repeat(3, 1fr);

    margin-top: 14px;

    border-radius: 14px;

    overflow: hidden;

    border: 1px solid rgba(255,255,255,0.07);

    background: rgba(255,255,255,0.035);
}


/* ITEM */

.arvid-season-2026-summary-item {
    padding: 22px;

    display: flex;

    flex-direction: column;

    gap: 9px;

    border-right: 1px solid rgba(255,255,255,0.07);
}

.arvid-season-2026-summary-item:last-child {
    border-right: none;
}


/* TEXTO */

.arvid-season-2026-summary-item span {
    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1.5px;

    color: #888;
}


/* VALOR */

.arvid-season-2026-summary-item strong {
    font-size: 25px;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 1000px) {

    .arvid-season-2026-container {
        grid-template-columns: 280px 1fr;

        gap: 35px;
    }

    .arvid-season-2026-image {
        height: 500px;
    }

    .arvid-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .arvid-season-2026-stat {
        min-height: 110px;
    }
}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .arvid-season-2026 {
        padding: 70px 15px;
    }

    .arvid-season-2026-container {
        display: flex;

        flex-direction: column;

        gap: 35px;
    }

    .arvid-season-2026-image {
        width: 100%;

        height: 390px;
    }

    .arvid-season-2026-number {
        font-size: 65px;
    }

    .arvid-season-2026-content h2 {
        font-size: 42px;
    }

    .arvid-season-2026-championship {
        padding: 20px;
    }

    .arvid-season-2026-championship-info strong,
    .arvid-season-2026-points span {
        font-size: 34px;
    }

    .arvid-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .arvid-season-2026-stat {
        padding: 16px;

        min-height: 110px;
    }

    .arvid-season-2026-stat-icon {
        width: 36px;
        height: 36px;

        font-size: 15px;
    }

    .arvid-season-2026-stat-info span {
        font-size: 26px;
    }

    .arvid-season-2026-summary {
        grid-template-columns: 1fr;
    }

    .arvid-season-2026-summary-item {
        border-right: none;

        border-bottom: 1px solid rgba(255,255,255,0.07);
    }

    .arvid-season-2026-summary-item:last-child {
        border-bottom: none;
    }
}


/* =========================================================
   CELULAR PEQUENO
========================================================= */

@media (max-width: 400px) {

    .arvid-season-2026-content h2 {
        font-size: 35px;
    }

    .arvid-season-2026-stats {
        grid-template-columns: 1fr;
    }

    .arvid-season-2026-stat {
        min-height: 100px;
    }

    .arvid-season-2026-championship {
        padding: 18px;
    }

    .arvid-season-2026-championship-info strong,
    .arvid-season-2026-points span {
        font-size: 30px;
    }
}




/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR lindblad
========================================================= */

.pilotagem-lindblad {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(0,90,255, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(0,90,255, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-lindblad {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-lindblad {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(0,90,255, .10);

    border:
        1px solid
        rgba(0,90,255, .35);

    color: #005dc0;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-lindblad {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-lindblad span {
    color: #005dc0;
}


.pilotagem-intro-lindblad {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-lindblad {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-lindblad {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(0,90,255, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-lindblad::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(0,90,255, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-lindblad {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-lindblad {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-lindblad:hover
.perfil-imagem-lindblad {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-lindblad::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-lindblad {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-lindblad {
    display: block;

    margin-bottom: 8px;

    color: #005dc0;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-lindblad {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-lindblad span {
    display: block;

    color: #005dc0;
}


.perfil-equipe-lindblad {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-lindblad {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-lindblad i {
    color: #005dc0;

    font-size: 20px;
}


.perfil-frase-lindblad p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-lindblad {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-lindblad {
    display: block;

    margin-bottom: 12px;

    color: #005dc0;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-lindblad h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-lindblad h3 span {
    display: block;

    color: #005dc0;
}


.pilotagem-analise-lindblad > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-lindblad {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-lindblad {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-lindblad:hover {
