	}



.caracteristica-lindblad h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-lindblad p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-lindblad {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-lindblad {
    margin-bottom: 35px;
}


.skills-header-lindblad > span {
    display: block;

    margin-bottom: 10px;

    color: #005dc0;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-lindblad h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-lindblad h3 span {
    color: #005dc0;
}


/* GRID */

.skills-grid-lindblad {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-lindblad {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-lindblad:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(0,90,255,.35);
}


.skill-topo-lindblad {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-lindblad {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-lindblad i {
    color: #005dc0;

    font-size: 26px;
}


.skill-numero-lindblad {
    color: #005dc0;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-lindblad::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-lindblad {
