/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-lindblad {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-lindblad {
    margin-bottom: 35px;
}


.grafico-header-lindblad > span {
    display: block;

    margin-bottom: 10px;

    color: #005dc0;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-lindblad h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-lindblad h3 span {
    color: #005dc0;
}


.grafico-layout-lindblad {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-lindblad {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-lindblad {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-lindblad {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-lindblad {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-lindblad {
    fill:
        rgba(0,90,255,.20);

    stroke: #005dc0;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(0,90,255,.35)
        );
}


.radar-ponto-lindblad {
    fill: #005dc0;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-lindblad {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-lindblad {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-lindblad {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-lindblad {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-lindblad {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-lindblad {
    bottom: 18%;
    left: -40px;
}


