.radio-f1-arvid {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* 🔵 STATUS */
.radio-status-arvid {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #1e5eff;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-arvid::before {
  content: "●";
  margin-right: 6px;
  animation: blink-arvid 1s infinite;
}

@keyframes blink-arvid {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-arvid {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: white;
}

/* CARD */
.card-arvid {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-arvid::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(30,94,255,0.15), transparent);
  z-index: -1;
}

.card-arvid.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-arvid.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-arvid {
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-arvid {
  font-size: 120px;
  color: #1e5eff;
}

/* DIREITA */
.right-arvid {
  position: absolute;
  top: 20px;
  right: 15px;
  text-align: right;
}

.right-arvid h1 {
  color: #1e5eff;
  margin: 0;
}

.right-arvid h2 {
  color: white;
  margin: 0;
}

.logo-arvid {
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-arvid {
  position: absolute;
  top: 160px;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  align-items: flex-end;
}

.wave-arvid span {
  flex: 1;
  margin: 0 1px;
  height: 6px;

  background: linear-gradient(to top, #1e5eff, transparent);

  animation: wave-arvid infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-arvid.falando .wave-arvid span {
  animation-play-state: running;
}

@keyframes wave-arvid {
  0%,100% { height: 6px; opacity: 0.3 }
  50% { height: 45px; opacity: 1 }
}

/* CONTEÚDO */
.content-arvid {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}

/* TEXTO */
.text-arvid {
  padding: 10px 15px;
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.4s ease;
}

.card-arvid.mostrar-texto .text-arvid {
  opacity: 1;
  transform: translateY(0);
}

.eng-arvid {
  color: white;
  font-size: 20px;
}

.pil-arvid {
  color: #1e5eff;
  text-align: right;
  font-size: 20px;
}

