.galeria-arvid{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(30,94,255,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-arvid::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(30,94,255,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-arvid{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(30,94,255,.18);
}

/* GRID */
.grid-galeria-arvid{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-arvid{
  position:relative;
  overflow:hidden;

  border-radius:24px;
  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-arvid img{
  position:absolute;
  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

.item-galeria-arvid:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-arvi{
  position:absolute;
  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:.4s ease;
}

.item-galeria-arvid:hover .overlay-arvi{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-arvi h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;
}

.overlay-arvi h3::after{
  content:"";
  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:linear-gradient(90deg,#1e5eff,#7aa7ff);
}

/* DESCRIÇÃO */
.overlay-arvi p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;
}

/* LIGHTBOX */
.lightbox-arvid{
  position:fixed;
  inset:0;

  background:rgba(0,0,0,.94);

  display:none;
  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);
}

.img-lightbox-arvid{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:0 25px 80px rgba(0,0,0,.8);
}

.fechar-arvid{
  position:absolute;
  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:rgba(255,255,255,.08);

  border:1px solid rgba(255,255,255,.12);

  color:white;
  font-size:34px;

  cursor:pointer;
  transition:.3s ease;
}

.fechar-arvid:hover{
  transform:rotate(90deg);
  background:rgba(30,94,255,.18);
  color:#1e5eff;
}

/* RESPONSIVO */
@media(max-width:768px){
  .grid-galeria-arvid{
    grid-template-columns:1fr;
  }
}

.footer-f1-arvid{
  position:relative;
  overflow:hidden;

  padding:80px 25px 35px;

  background:
  radial-gradient(circle at top,
  rgba(30,94,255,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #080808 0%,
    #050505 100%
  );

  border-top:1px solid rgba(255,255,255,.06);

  display:flex;
  flex-direction:column;
  gap:45px;

  text-align:center;
}

/* BRILHO */
.footer-f1-arvid::before{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  top:-250px;
  left:50%;
  transform:translateX(-50%);

  background:
  radial-gradient(circle,
  rgba(30,94,255,.12),
  transparent 70%);

  filter:blur(100px);
}

.footer-f1-arvid > *{
  position:relative;
  z-index:2;
}

/* BRAND */
.footer-brand-arvid p{
  font-size:clamp(34px,5vw,58px);
  font-weight:1000;
  color:white;
  margin-bottom:10px;
}

.footer-brand-arvid span{
  color:#a5a5a5;
  font-size:15px;
  max-width:600px;
  margin:auto;
  line-height:1.6;
}

/* LINKS */
.footer-links-arvid,
.footer-social-arvid{
  display:flex;
  justify-content:center;
  flex-wrap:wrap;
  gap:16px;
}

.footer-links-arvid a,
.footer-social-arvid a{
  padding:12px 22px;
  border-radius:999px;

  text-decoration:none;

  color:#e6e6e6;
  background:rgba(255,255,255,.03);

  border:1px solid rgba(255,255,255,.06);

  font-size:14px;
  font-weight:700;

  transition:.3s ease;
}

.footer-links-arvid a:hover,
.footer-social-arvid a:hover{
  transform:translateY(-4px);
  background:rgba(30,94,255,.12);
  border-color:rgba(30,94,255,.25);
  color:#7aa7ff;
}

/* COPY */
.footer-copy-arvid{
  padding-top:15px;
  border-top:1px solid rgba(255,255,255,.05);
  color:#777;
  font-size:13px;
}

.back-to-top-arvid{
  position:fixed;

  right:28px;
  bottom:28px;

  width:62px;
  height:62px;

  display:flex;
  align-items:center;
  justify-content:center;

  border:none;
  border-radius:50%;

  cursor:pointer;

  background:linear-gradient(145deg,#2f6bff,#1e5eff);

  color:white;
  font-size:22px;
  font-weight:900;

  z-index:9999;

  box-shadow:
  0 10px 35px rgba(30,94,255,.35),
  0 0 25px rgba(30,94,255,.18);

  transition:.35s ease;
}

/* brilho */
.back-to-top-arvid::before{
  content:"";
  position:absolute;
  inset:0;

  border-radius:inherit;

  background:radial-gradient(circle,rgba(255,255,255,.35),transparent 65%);
  opacity:.6;
}

/* hover */
.back-to-top-arvid:hover{
  transform:translateY(-6px) scale(1.08);
  box-shadow:0 18px 45px rgba(30,94,255,.45);
}

/* active */
.back-to-top-arvid:active{
  transform:scale(.96);
}

/* mobile */
@media(max-width:768px){
  .back-to-top-arvid{
    width:56px;
    height:56px;
    right:20px;
    bottom:20px;
    font-size:20px;
  }
}



