    box-shadow:
    -15px 0 35px rgba(0,0,0,.55);

}

.painel-noticias-fernando.active{

    right:0;

}

/*======================================
        TOPO
======================================*/

.topo-noticias-fernando{

    position:sticky;

    top:0;

    display:flex;

    justify-content:space-between;

    align-items:center;

    padding:18px;

