.fernando-banner-bg{
  position: relative;

  width: 100%;
  height: 100vh;

  overflow: hidden;

  background-image: url("fernando/banner.jpeg");
  background-size: cover;
  background-position: center;

  display: flex;
  align-items: center;
}

/* LIGHT FOLLOW MOUSE */
.fernando-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(0,110,98,0.25) 0%,
    rgba(2,2,2,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY */
.fernando-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

  background:
  linear-gradient(
    to right,
    rgba(0,0,0,0.85),
    rgba(0,0,0,0.25),
    rgba(0,0,0,0.75)
  );

  z-index: 1;
}

/* CONTEÚDO ACIMA */
.fernando-banner-bg > *{
  position: relative;
  z-index: 5;
}

