  background: rgba(0,111,98,0.15);
}

/* =========================
   INFO
========================= */

.fernando-banner-info{
  position: absolute;

  left: 70px;
  top: 50%;

  transform: translateY(-50%);

  display: flex;
  flex-direction: column;

  gap: 14px;
}

/* NOME */
.fernando-nome{
  line-height: 0.9;
}

.fernando-nome span{
  display: block;

  font-size: 42px;
  font-weight: 300;

  color: rgba(255,255,255,0.7);

  text-transform: uppercase;
  letter-spacing: 3px;
}

.fernando-nome strong{
  display: block;

  font-size: 95px;
  font-weight: 900;

  color: #006f62;

  text-transform: uppercase;
  letter-spacing: 4px;

  text-shadow:
  0 0 10px rgba(0,111,96,0.4),
  0 0 25px rgba(2,4,4,0.2);
}

/* PAÍS */
.fernando-pais{
  font-size: 18px;
  font-weight: 600;

  color: rgba(255,255,255,0.85);

  letter-spacing: 2px;
}

/* EQUIPE */
.fernando-equipe{
  width: fit-content;

  padding: 10px 18px;

  border-radius: 30px;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(255,255,255,0.1);

  backdrop-filter: blur(10px);

  color: #006f62;

  font-size: 20px;
  font-weight: 700;

  letter-spacing: 1px;
}

/* FRASE */
.fernando-frase{
  margin-top: 8px;

  padding-left: 14px;

  border-left: 3px solid #006f62;

  color: rgba(255,255,255,0.75);

  font-size: 20px;
  font-style: italic;

  max-width: 450px;
}

/* =========================
   NÚMERO
========================= */

.fernando-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,255,255,0.08);

  font-family: 'Russo One', sans-serif;

  user-select: none;
  pointer-events: none;

  animation: fernandoGlow 4s ease-in-out infinite;
}

@keyframes fernandoGlow{

  0%{
    text-shadow: 0 0 15px rgba(2,111,96,0.98);
  }

  50%{
    text-shadow:
    0 0 25px rgba(2,111,96,0.25),
    0 0 60px rgba(2,2,2,0.12);
  }

  100%{
    text-shadow: 0 0 15px rgba(0,111,96,0.08);
  }
}

/* =========================
   CHUVA
========================= */

.fernando-rain{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.fernando-rain span{
  position: absolute;
  top: -120px;
  left: calc(10% * var(--i));

  width: 7px;
  height: 120px;

  background: linear-gradient(
    transparent,
    rgba(0,111,96,0.8),
    transparent
  );

  opacity: 0.5;

  animation: fernandorain 2s linear infinite;
}

.fernando-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.fernando-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.fernando-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.fernando-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.fernando-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.fernando-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.fernando-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.fernando-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}

/* ANIMAÇÃO */

@keyframes fernandorain{

  0%{
    transform:
    translateY(-200px);

    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform:
    translateY(120vh);

    opacity: 0;
  }

}



/* =========================
   PARTICLES
========================= */

.fernando-particles{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.fernando-particles span{
  position: absolute;

  width: 16px;
  height: 16px;

  border-radius: 50%;

  background: rgba(2,115,95,0.7);

  box-shadow:
  0 0 10px rgba(5,5,2,0.8),
  0 0 20px rgba(0,111,96,0.4);

  animation: fernandoFloat linear infinite;
}

.fernando-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.fernando-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.fernando-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.fernando-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.fernando-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.fernando-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.fernando-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.fernando-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.fernando-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.fernando-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}

/* ANIMAÇÃO */

@keyframes fernandoFloat{

  0%{
    transform:
    translateY(100vh)
    scale(0.5);

    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  50%{
    opacity: 0.8;
  }

  100%{
    transform:
    translateY(-120px)
    scale(1.4);

    opacity: 0;
  }

}


/* =========================
   SOCIALS
========================= */

.fernando-socials{
  position: absolute;

  right: 30px;
  bottom: 100px;

  display: flex;
  gap: 15px;
}

.social-link-fernando{
  width: 88px;
  height: 88px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(255,255,255,0.08);

  backdrop-filter: blur(10px);

  color: #fff;

  font-size: 40px;

  text-decoration: none;

  transition: 0.3s;
}

.social-link-fernando:hover{
  transform: scale(1.12);
  color: #006f62;
  box-shadow: 0 0 15px rgba(0,111,96,0.4);
}

/* =========================
   RESPONSIVO
========================= */

@media(max-width:768px){

  .fernando-banner-info{
    left: 25px;
    bottom: 100px;
    top: auto;
    transform: none;
  }

  .fernando-nome span{font-size:24px;}
  .fernando-nome strong{font-size:58px;}
  .fernando-pais{font-size:14px;}

  .fernando-equipe{
    font-size:13px;
    padding:8px 14px;
  }

  .fernando-frase{
    font-size:15px;
    max-width:260px;
  }

  .fernando-numero-bg{
    font-size:180px;
    right:10px;
    bottom:20px;
    top:auto;
    transform:none;
  }

  .fernando-socials{
    left:25px;
    right:auto;
    bottom:25px;
  }

  .social-link-fernando{
    width:48px;
    height:48px;
    font-size:16px;
  }
}

