/* =========================================================
   TÍTULOS DO fernando VERSTAPPEN
   LAYOUT 100dvh
========================================================= */

#fernando-title-container {
    width: 100%;
    height: 100dvh;
    max-height: 100dvh;

    overflow: hidden;

    background: #050505;
}


/* =========================================================
   CONTAINER PRINCIPAL
========================================================= */

.fernando-title-content {
    width: 100%;
    height: 100%;
    max-height: 100%;

    overflow: hidden;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.fernando-season-card {
    position: relative;

    width: 100%;
    height: 100%;
    max-height: 100dvh;

    margin: 0 auto;

    padding: clamp(14px, 2vw, 30px);

    box-sizing: border-box;

    border-radius: 30px;

    overflow: hidden;

    background:
        radial-gradient(
            circle at 90% 5%,
            rgba(6,111,98,.13),
            transparent 30%
        ),
        radial-gradient(
            circle at 10% 90%,
            rgba(6,111,98,.06),
            transparent 30%
        ),
        #050505;

    border: 1px solid rgba(6,111,98,.25);

    color: #fff;

    font-family: 'Inter', sans-serif;

    display: flex;
    flex-direction: column;
}


/* =========================================================
   BOTÕES DOS TÍTULOS
========================================================= */

.fernando-title-buttons {
    flex-shrink: 0;

    width: 100%;

    display: flex;

    justify-content: center;
    align-items: center;

    gap: 10px;

    margin: 0 0 clamp(10px, 1.5vh, 20px);

    z-index: 10;
}


.fernando-title-btn {
    position: relative;

    padding: 10px 20px;

    min-width: 158px;

    border: none;
    outline: none;

    border-radius: 10px;

    background: rgba(255,255,255,.06);

    color: #fff;

    font-size: 18px;

    font-weight: 800;

    letter-spacing: .5px;

    cursor: pointer;

    transition:
        transform .25s ease,
        background .25s ease,
        box-shadow .25s ease;

    backdrop-filter: blur(10px);

    overflow: hidden;
}


.fernando-title-btn::before {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            135deg,
            rgba(255,255,255,.15),
            transparent
        );

    opacity: 0;

    transition: opacity .25s ease;
}


.fernando-title-btn:hover {
    transform: translateY(-2px);

    background: rgba(255,255,255,.12);

    box-shadow:
        0 8px 20px rgba(0,0,0,.35);
}


.fernando-title-btn:hover::before {
    opacity: 1;
}


.fernando-title-btn.active {
    background:
        linear-gradient(
            135deg,
            #066f62,
            #003a33
        );

    color: #fff;

    box-shadow:
        0 0 18px rgba(6,111,98,.4),
        0 8px 20px rgba(0,0,0,.4);

    transform: translateY(-1px);
}


.fernando-title-btn.active::after {
    content: "🏆";

    margin-left: 5px;

    font-size: 10px;
}


/* =========================================================
   HERO
========================================================= */

.fernando-hero {
    flex: 1;

    min-height: 0;

    width: 100%;

    display: grid;

    grid-template-columns: minmax(280px, .9fr) minmax(0, 1.1fr);

    gap: clamp(20px, 3vw, 50px);

    align-items: center;

    overflow: hidden;
}


/* =========================================================
   LADO DA IMAGEM
========================================================= */

.fernando-hero-left {
    position: relative;

    height: 100%;

    min-height: 0;

    overflow: hidden;

    display: flex;

    align-items: center;
    justify-content: center;
}


.fernando-hero-art {
    width: 100%;
    height: 100%;

    max-height: 100%;
    object-fit: contain;

    object-position: center center;

    filter:
        drop-shadow(
            0 25px 35px rgba(0,0,0,.7)
        );

    transition:
        transform .5s ease,
        filter .5s ease;
}


.fernando-hero-left:hover .fernando-hero-art {
    transform: scale(1.025);

    filter:
        drop-shadow(
            0 30px 45px rgba(0,0,0,.8)
        );
}


/* =========================================================
   LADO DIREITO
========================================================= */

.fernando-hero-right {
    min-width: 0;
    min-height: 0;

    height: 100%;

    display: flex;

    flex-direction: column;

    justify-content: center;

    gap: clamp(8px, 1.3vh, 18px);

    overflow: hidden;
}


/* =========================================================
   ÁREA DO TÍTULO
========================================================= */

.fernando-title-area {
    flex-shrink: 0;
}


.fernando-year {
    display: block;

    margin-bottom: 6px;

    font-size: clamp(30px, 2vw, 40px);

    line-height: .9;

    font-weight: 900;

    color: #066f62;

    letter-spacing: -2px;
}


.fernando-name {
    margin: 0;

    font-size: clamp(32px, 4vw, 80px);

    line-height: .82;

    font-weight: 900;

    letter-spacing: -5px;

    text-transform: uppercase;

    color: #fff;
}


.fernando-name span {
    display: block;

    color: #066f62;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.fernando-subtitle {
    margin: clamp(10px, 1.5vh, 18px) 0 0;

    font-size: clamp(13px, 1.5vw, 24px);

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #ddd;
}


/* =========================================================
   DESCRIÇÃO
========================================================= */

.fernando-description {
    flex-shrink: 0;

    width: 100%;
    max-width: 720px;

    font-size: clamp(11px, 1.2vw, 18px);

    line-height: 1.55;

    color: #cfcfcf;

    overflow: visible;

    word-break: normal;
    overflow-wrap: break-word;
}

/* =========================================================
   ESTATÍSTICAS
========================================================= */

.fernando-stats {
    flex-shrink: 0;

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(5, minmax(0, 1fr));

    gap: clamp(6px, 1vw, 14px);
}


.fernando-stat-box {
    min-width: 0;

    padding: clamp(10px, 1.2vw, 18px);

    border-radius: 14px;

    text-align: center;

    background:
        linear-gradient(
            145deg,
            #066f62,
            #003a33
        );

    border: 1px solid rgba(6,111,98,.4);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.1);
}


.fernando-stat-box h3 {
    margin: 0 0 5px;

    font-size: clamp(20px, 2.5vw, 38px);

    line-height: 1;

    font-weight: 900;

    color: #Cedc00;
}


.fernando-stat-box p {
    margin: 0;

    font-size: clamp(7px, .8vw, 11px);

    line-height: 1.2;

    text-transform: uppercase;

    letter-spacing: .8px;

    color: #fff;

    font-weight: 700;
}


/* =========================================================
   QUOTE
========================================================= */

.fernando-quote {
    flex-shrink: 0;

    width: 100%;
    box-sizing: border-box;

    padding: clamp(12px, 1.5vw, 24px);

    border-radius: 15px;

    background:
        linear-gradient(
            135deg,
            #066f62,
            #003a33
        );

    border-left: 4px solid #Cedc00;

    overflow: visible;
}

.fernando-quote p {
    margin: 0;

    font-size: clamp(11px, 1.2vw, 17px);

    line-height: 1.5;

    color: #fff;

    white-space: normal;

    word-break: normal;

    overflow-wrap: break-word;
}

.fernando-quote span {
    display: block;

    margin-top: 8px;

    font-size: clamp(9px, 1vw, 13px);

    color: #Cedc00;

    font-weight: 800;
}


/* =========================================================
   TIMELINE
========================================================= */

.fernando-timeline-section {
    flex-shrink: 0;

    width: 100%;

    margin-top: clamp(10px, 1.5vh, 20px);

    min-height: 0;

    overflow: hidden;
}


.fernando-section-title {
    margin: 0 0 clamp(10px, 1.5vh, 18px);

    font-size: clamp(20px, 3vw, 42px);

    line-height: 1;

    font-weight: 900;

    text-align: center;

    text-transform: uppercase;

    color: #fff;
}


.fernando-timeline-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(5, minmax(0, 1fr));

    gap: clamp(8px, 1.2vw, 18px);

    min-height: 0;
}


.fernando-race-card {
    min-width: 0;

    min-height: clamp(130px, 20vh, 250px);

    padding: clamp(12px, 1.4vw, 22px);

    border-radius: 16px;

    background:
        linear-gradient(
            145deg,
            #0d0d0d,
            #080808
        );

    border: 1px solid #222;

    display: flex;

    flex-direction: column;

    justify-content: space-between;

    overflow: hidden;

    transition:
        transform .3s ease,
        box-shadow .3s ease;
}


.fernando-race-card:hover {
    transform: translateY(-5px);

    box-shadow:
        0 12px 30px rgba(0,0,0,.45);
}


.fernando-race-card h3 {
    margin: 0 0 8px;

    font-size: clamp(12px, 1.4vw, 21px);

    line-height: 1.1;

    font-weight: 900;

    text-transform: uppercase;
}


.fernando-race-card p {
    margin: 0;

    font-size: clamp(12px, 1vw, 15px);

    line-height: 1.45;

    color: #bdbdbd;

    overflow: hidden;
}


.fernando-race-result {
    flex-shrink: 0;

    margin-top: 10px;

    padding: 8px;

    border-radius: 9px;

    font-size: clamp(7px, .75vw, 11px);

    line-height: 1.2;

    font-weight: 800;

    text-align: center;

    text-transform: uppercase;

    background: #111;

    color: #fff;

    border: 1px solid rgba(255,255,255,.05);
}


/* =========================================================
   CORES DA TIMELINE
========================================================= */

.fernando-race-card.positive {
    border-color: rgba(35,255,133,.45);
}

.fernando-race-card.positive h3 {
    color: #23ff85;
}


.fernando-race-card.warning {
    border-color: rgba(255,208,0,.45);
}

.fernando-race-card.warning h3 {
    color: #ffd000;
}


.fernando-race-card.danger {
    border-color: rgba(255,61,61,.45);
}

