    margin: auto;

    aspect-ratio: 1;
}


.radar-alonso {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-alonso {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-alonso {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-alonso {
    fill:
        rgba(6,111,98,.20);

    stroke: #066f62;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(6,111,98,.35)
        );
}


.radar-ponto-alonso {
    fill: #066f62;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-alonso {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-alonso {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-alonso {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-alonso {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-alonso {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-alonso {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-alonso {
    top: 16%;
    left: -30px;
}


