.slider-stroll{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-stroll {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-stroll::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-stroll-container,
.titulo-stroll-slider,
.dots-stroll,
.btn-stroll {
  position: relative;
  z-index: 2;
}

.titulo-stroll-slider {
  font-size: 40px;
  color: #006f62;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-stroll-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-stroll-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-stroll {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-stroll img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-stroll-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-stroll-texto h3 {
  color: #006f62;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-stroll-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-stroll {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(0,111,96,0.6);
  border: none;
  color: #fff;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-stroll:hover {
  background: #000000;
  color:#006f62;
}

/* BOLINHAS */
.dots-stroll {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-stroll {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-stroll:hover {
  background: #006f62;
}

.dot-stroll.active {
  background: #ffffff;
  transform: scale(1.3);
}
.dots-stroll {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-stroll img {
    height: 300px;
  }

  .slide-stroll-texto h3 {
    font-size: 20px;
  }

  .slide-stroll-texto p {
    font-size: 14px;
  }
}

