  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-stroll::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(0,111,96,0.15), transparent);
  z-index: -1;
}

.card-stroll.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-stroll.saindo {
  opacity: 0;
