  animation-delay: calc(var(--i) * 0.05s);
}

.card-stroll.falando .wave-stroll span{
  animation-play-state: running;
}

/* TEXTO */
.content-stroll{
  position: absolute;
  bottom: 0;
  width: 100%;

  transform: scaleY(0);
  transform-origin: bottom;

  transition: transform 0.4s ease;
}

.card-stroll.mostrar-texto .content-stroll{
  transform: scaleY(1);
}

.text-stroll{
  padding: 10px 15px;

  opacity: 0;
  transform: translateY(10px);

  transition: all 0.4s ease;
}

.card-stroll.mostrar-texto .text-stroll{
  opacity: 1;
  transform: translateY(0);
}

.eng-stroll{
  color: white;
  font-size: clamp(12px, 3vw, 20px);
}

.pil-stroll{
  color: #006f62;
  text-align: right;
  font-size: clamp(12px, 3vw, 20px);
}

}

.galeria-stroll{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(0,111,96,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-stroll::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(0,111,96,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-stroll{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(0,111,96,.18);
}

/* GRID */
.grid-galeria-stroll{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-stroll{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-stroll img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-stroll:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-strol{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-stroll:hover .overlay-strol{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-strol h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA */
.overlay-strol h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #006f62,
    #000000
  );

  box-shadow:
  0 0 18px rgba(0,111,98,.5);
}

/* DESCRIÇÃO */
.overlay-strol p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-stroll::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(0,111,98,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-stroll:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-stroll{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightboxChar .3s ease;
}

@keyframes fadeLightboxChar{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-stroll{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightboxChar .35s ease;
}

@keyframes zoomLightboxChar{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-stroll{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-stroll:hover{
  transform:rotate(90deg);

  background:
  rgba(0,111,98,.18);

  border-color:
  rgba(0,111,98,.35);

  color:#006f62;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-stroll{
    grid-template-columns:1fr;
  }

  .overlay-stroll h3{
    font-size:20px;
  }

  .fechar-stroll{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

