.slider-ocon{
	position:relative;
    overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-ocon {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-ocon::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-ocon-container,
.titulo-ocon-slider,
.dots-ocon,
.btn-ocon {
  position: relative;
  z-index: 2;
}

.titulo-ocon-slider {
  font-size: 40px;
  color: #ffffff;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-ocon-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-ocon-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-ocon {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-ocon img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-ocon-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-ocon-texto h3 {
  color: #ffffff;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-ocon-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-ocon {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(255,255,255,0.6);
  border: none;
  color: #d00;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-ocon:hover {
  background: #000000;
  color:#ffffff;
}

/* BOLINHAS */
.dots-ocon {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-ocon {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-ocon:hover {
  background: #ffffff;
}

.dot-ocon.active {
  background: #ffffff;
  transform: scale(1.3);
}
.dots-ocon {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-ocon img {
    height: 300px;
  }

  .slide-ocon-texto h3 {
    font-size: 20px;
  }

  .slide-ocon-texto p {
    font-size: 14px;
  }
}

