/* =========================================================
   ocon — TIMELINE
========================================================= */

.ocon-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(255,0,0,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.ocon-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.ocon-timeline-title{
  color:#Dc0000;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(255,0,0,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.ocon-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.ocon-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.ocon-ano-btn:hover{
  background:rgba(255,0,0,0.15);

  color:#Dc0000;

  transform:translateY(-2px);
}


.ocon-ano-btn.active{
  background:#Dc0000;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,0,0,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.ocon-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.ocon-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.ocon-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.ocon-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.ocon-team-change{
  position:relative;

  border:1px solid rgba(255,0,0,.45);

  box-shadow:
    0 0 20px rgba(255,0,0,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-ocon{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Dc0000,
      #Dc0000
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferocon .5s ease;
}


@keyframes transferocon{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.ocon-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,0,0,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.ocon-corrida-card:hover::before{
  opacity:1;
}


.ocon-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,0,0,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.ocon-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.ocon-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.ocon-vitoria .ocon-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,0,0,0.25);

}


.ocon-podio .ocon-resultado{

  color: #Dc0000 ;

  text-shadow:
    0 0 10px rgba(255,0,0,0.2);

}


.ocon-pontos .ocon-resultado{

  color:#ffffff;

}


.ocon-dnf .ocon-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.ocon-sem-pontos .ocon-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.ocon-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#Dc0000;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.ocon-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.ocon-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

  opacity:0;

  transform:translateY(15px);

  transition:.4s ease;

  box-sizing:border-box;
}


.ocon-summary-card.show{

  opacity:1;

  transform:translateY(0);

}


.ocon-summary-title{

  color:#Dc0000;

  font-size:18px;

  font-weight:900;

  margin-bottom:10px;

  letter-spacing:1px;

}


.ocon-summary-stats{

  display:flex;

  justify-content:space-between;

  gap:10px;
}


.ocon-summary-box{

  flex:1;

  padding:7px;

  border-radius:9px;

  background:
    rgba(255,255,255,0.03);

  border:
    1px solid rgba(255,255,255,0.06);
}


.ocon-summary-label{

  display:block;

  font-size:11px;

  color:#aaa;

  margin-bottom:3px;

  text-transform:uppercase;

  letter-spacing:1px;
}


.ocon-summary-value{

  font-size:22px;

  font-weight:900;

  color:#fff;
}


