/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR ocon
========================================================= */

.pilotagem-ocon {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(255,6,0, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(255,6,0, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-ocon {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-ocon {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(255,6,0, .10);

    border:
        1px solid
        rgba(255,6,0, .35);

    color: #E10600;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-ocon {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-ocon span {
    color: #E10600;
}


.pilotagem-intro-ocon {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-ocon {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-ocon {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(255,6,0, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-ocon::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255,6,0, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-ocon {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-ocon {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-ocon:hover
.perfil-imagem-ocon {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-ocon::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-ocon {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-ocon {
    display: block;

    margin-bottom: 8px;

    color: #E10600;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-ocon {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-ocon span {
    display: block;

    color: #E10600;
}


.perfil-equipe-ocon {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-ocon {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-ocon i {
    color: #E10600;

    font-size: 20px;
}


.perfil-frase-ocon p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-ocon {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-ocon {
    display: block;

    margin-bottom: 12px;

    color: #E10600;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-ocon h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-ocon h3 span {
    display: block;

    color: #E10600;
}


.pilotagem-analise-ocon > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-ocon {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-ocon {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-ocon:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(255,6,0,.5);

    background:
        rgba(255,6,0,.06);
}


.caracteristica-icone-ocon {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,6,0,.10);

    color: #E10600;
}

.caracteristica-icone-ocon i{
	font-size: 40px;

	}



.caracteristica-ocon h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-ocon p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-ocon {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-ocon {
    margin-bottom: 35px;
}


.skills-header-ocon > span {
    display: block;

    margin-bottom: 10px;

    color: #E10600;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-ocon h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-ocon h3 span {
    color: #E10600;
}


/* GRID */

.skills-grid-ocon {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-ocon {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-ocon:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(255,6,0,.35);
}


.skill-topo-ocon {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-ocon {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-ocon i {
    color: #E10600;

    font-size: 26px;
}


.skill-numero-ocon {
    color: #E10600;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-ocon::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-ocon {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-ocon {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #E10600,
            #F0f0f0
        );

    box-shadow:
        0 0 12px
        rgba(255,6,0,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-ocon {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-ocon {
    margin-bottom: 35px;
}


.grafico-header-ocon > span {
    display: block;

    margin-bottom: 10px;

    color: #E10600;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-ocon h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-ocon h3 span {
    color: #E10600;
}


.grafico-layout-ocon {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-ocon {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-ocon {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-ocon {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-ocon {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-ocon {
    fill:
        rgba(255,6,0,.20);

    stroke: #E10600;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,6,0,.35)
        );
}


.radar-ponto-ocon {
    fill: #E10600;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-ocon {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-ocon {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-ocon {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-ocon {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-ocon {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-ocon {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-ocon {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-ocon {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-ocon {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-ocon:hover {
    transform:
        translateX(6px);
}


.resumo-icone-ocon {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,6,0,.10);

    color: #E10600;

    font-size: 18px;
}


.resumo-card-ocon > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-ocon h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-ocon p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-ocon {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,6,0,.12),
            rgba(255,6,0,.02)
        );

    border:
        1px solid
        rgba(255,6,0,.25);
}


.pilotagem-conclusao-ocon::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,6,0,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-ocon > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-ocon > span {
    display: block;

    margin-bottom: 18px;

    color: #E10600;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-ocon h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-ocon strong {
    color: #E10600;
}


.pilotagem-conclusao-ocon p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-ocon {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-ocon.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-ocon {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-ocon {
        min-height: 600px;
    }


    .grafico-layout-ocon {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-ocon {
        max-width: 430px;
    }


    .caracteristicas-ocon {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

.pilotagem-ocon{
        padding:
            70px
            15px;
    }


    .pilotagem-header-ocon {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-ocon {
        font-size: 42px;

        letter-spacing: -2px;
    }


    /* PERFIL */

    .pilotagem-perfil-ocon {
        min-height: 500px;

        border-radius: 20px;
    }


    .perfil-info-ocon {
        padding:
            25px
            20px;
    }


    .perfil-nome-ocon {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-ocon {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-ocon h3 {
        font-size: 38px;
    }


    .pilotagem-analise-ocon > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-ocon {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-ocon {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-ocon {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-ocon {
        margin-top: 70px;
    }


    .skills-grid-ocon {
        grid-template-columns: 1fr;
    }


    .skill-card-ocon {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-ocon {
        margin-top: 70px;
    }


    .grafico-layout-ocon {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-ocon {
        width: 80%;
    }


    .radar-label-ocon {
        font-size: 7px;
    }


    .radar-top-right-ocon {
        right: -28px;
    }


    .radar-bottom-right-ocon {
        right: -35px;
    }


    .radar-bottom-left-ocon {
        left: -35px;
    }


    .radar-top-left-ocon {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-ocon {
        padding: 0 10px;
    }


    .resumo-card-ocon {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-ocon h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-ocon {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-ocon h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-ocon p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-ocon {
        font-size: 36px;
    }


    .pilotagem-perfil-ocon {
        min-height: 450px;
    }


    .perfil-nome-ocon {
        font-size: 38px;
    }


    .analise-topo-ocon h3 {
        font-size: 32px;
    }


    .skill-nome-ocon {
        font-size: 9px;
    }


    .radar-container-ocon {
        width: 78%;
    }


    .radar-label-ocon {
        font-size: 6px;
    }


    .resumo-card-ocon p {
        font-size: 11px;
    }

}


