.radio-f1-ocon {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* 🔴 STATUS */
.radio-status-ocon {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #ffffff;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-ocon::before {
  content: "●";
  margin-right: 6px;
  animation: blink-ocon 1s infinite;
}

@keyframes blink-ocon {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-ocon {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: white;
}

/* CARD */
.card-ocon {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-ocon::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(255,255,255,0.15), transparent);
  z-index: -1;
}

.card-ocon.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-ocon.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-ocon {
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-ocon {
  font-size: 120px;
  color: #ffffff;
}

/* DIREITA */
.right-ocon {
  position: absolute;
  top: 20px;
  right: 15px;
  text-align: right;
}

.right-ocon h1 {
  color: #ffffff;
  margin: 0;
}

.right-ocon h2 {
  color: white;
  margin: 0;
}

.logo-ocon {
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-ocon {
  position: absolute;
  top: 160px;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  align-items: flex-end;
}

.wave-ocon span {
  flex: 1;
  margin: 0 1px;
  height: 6px;

  background: linear-gradient(to top, #ffffff, transparent);

  animation: wave-ocon infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-ocon.falando .wave-ocon span {
  animation-play-state: running;
}

@keyframes wave-ocon {
  0%,100% { height: 6px; opacity: 0.3 }
  50% { height: 45px; opacity: 1 }
}

/* CONTEÚDO */
.content-ocon {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}

