.oliver-banner-bg{
  position: relative;

  width: 100%;
  height: 100vh;

  overflow: hidden;

  background-image: url("oliver/banner.jpg");
  background-size: cover;
  background-position: center;

  display: flex;
  align-items: center;
}

/* LIGHT FOLLOW MOUSE */
.oliver-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(255,255,255,0.25) 0%,
    rgba(0,0,0,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY */
.oliver-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

background:
linear-gradient(
to right,
rgba(0,0,0,.90),
rgba(225,6,0,.10),
rgba(0,0,0,.85)
);

  z-index: 1;
}

/* CONTEÚDO ACIMA */
.oliver-banner-bg > *{
  position: relative;
  z-index: 5;
}

/* =========================
   HOME BUTTON
========================= */

.home-btn-oliver{
  position: absolute;

  top: 105px;
  left: 25px;

  display: flex;
  align-items: center;
  gap: 10px;

  padding: 10px 18px;

  border-radius: 40px;

  background: rgba(255,255,255,0.08);

  backdrop-filter: blur(10px);

  text-decoration: none;

  transition: 0.3s;
}

.home-btn-oliver img{
  width: 48px;
}

.home-btn-oliver span{
  color: #fff;
  font-weight: 700;
  font-size: 34px;
}

.home-btn-oliver:hover{
  transform: scale(1.05);

  background:
  rgba(225,6,0,.15);

  box-shadow:
  0 0 20px rgba(225,6,0,.25);
}

/* =========================
   INFO
========================= */

.oliver-banner-info{
  position: absolute;

  left: 70px;
  top: 50%;

  transform: translateY(-50%);

  display: flex;
  flex-direction: column;

  gap: 14px;
}

/* NOME */
.oliver-nome{
  line-height: 0.9;
}

.oliver-nome span{
  display: block;

  font-size: 42px;
  font-weight: 300;

  color: rgba(255,255,255,0.7);

  text-transform: uppercase;
