  color: rgba(255,255,255,0.85);

  letter-spacing: 2px;
}

/* EQUIPE */
.oliver-equipe{
  width: fit-content;

  padding: 10px 18px;

  border-radius: 30px;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(225,6,0,.35);

  box-shadow:
  0 0 15px rgba(225,6,0,.15);

  backdrop-filter: blur(10px);

  color: #ffffff;

  font-size: 20px;
  font-weight: 700;

  letter-spacing: 1px;
}

/* FRASE */
.oliver-frase{
  margin-top: 8px;

  padding-left: 14px;

border-left: 3px solid #e10600;

  color: rgba(255,255,255,0.75);

  font-size: 20px;
  font-style: italic;

  max-width: 450px;
}

/* =========================
   NÚMERO
========================= */

.oliver-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,255,255,0.08);

  font-family: 'Russo One', sans-serif;

  user-select: none;
  pointer-events: none;

  animation: oliverGlow 4s ease-in-out infinite;
}

/* NÚMERO */
@keyframes oliverGlow{

  0%{
    text-shadow: 0 0 15px rgba(225,6,0,0.98);
  }

  50%{
    text-shadow:
    0 0 25px rgba(225,6,0,0.35),
    0 0 60px rgba(255,255,255,0.12);
  }

  100%{
    text-shadow: 0 0 15px rgba(255,255,255,0.08);
  }
}
/* =========================
   CHUVA
========================= */

.oliver-rain{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.oliver-rain span{
  position: absolute;
  top: -120px;
  left: calc(10% * var(--i));

  width: 7px;
  height: 120px;

  background: linear-gradient(
    transparent,
    rgba(255,255,255,0.8),
    transparent
  );

  opacity: 0.5;

  animation: oliverrain 2s linear infinite;
}

.oliver-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.oliver-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.oliver-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.oliver-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.oliver-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.oliver-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.oliver-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.oliver-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}

/* ANIMAÇÃO */

@keyframes oliverrain{

  0%{
    transform:
    translateY(-200px);

    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform:
    translateY(120vh);

    opacity: 0;
  }

}



/* =========================
   PARTICLES
========================= */

.oliver-particles{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.oliver-particles span{
  position: absolute;

  width: 16px;
  height: 16px;

  border-radius: 50%;

background: rgba(225,6,0,0.7);

box-shadow:
0 0 10px rgba(225,6,0,0.8),
0 0 20px rgba(255,255,255,0.4);



  animation: oliverFloat linear infinite;
}

.oliver-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.oliver-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.oliver-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.oliver-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.oliver-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.oliver-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.oliver-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.oliver-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.oliver-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.oliver-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}

/* ANIMAÇÃO */

@keyframes oliverFloat{

  0%{
    transform:
    translateY(100vh)
    scale(0.5);

    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  50%{
    opacity: 0.8;
  }

  100%{
    transform:
    translateY(-120px)
    scale(1.4);

    opacity: 0;
  }

}


