.slider-oliver{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-oliver {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-oliver::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-oliver-container,
.titulo-oliver-slider,
.dots-oliver,
.btn-oliver {
  position: relative;
  z-index: 2;
}

.titulo-oliver-slider {
  font-size: 40px;
  color: #ffffff;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-oliver-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-oliver-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-oliver {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-oliver img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-oliver-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-oliver-texto h3 {
  color: #ffffff;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-oliver-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-oliver {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(255,255,255,0.6);
  border: none;
  color: #d00;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-oliver:hover {
  background: #000000;
  color:#ffffff;
}

/* BOLINHAS */
.dots-oliver {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-oliver {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,255,255,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-oliver:hover {
  background: #ffffff;
}

.dot-oliver.active {
  background: #ffffff;
  transform: scale(1.3);
}
.dots-oliver {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-oliver img {
    height: 300px;
  }

  .slide-oliver-texto h3 {
    font-size: 20px;
  }

  .slide-oliver-texto p {
    font-size: 14px;
  }
}

.numeros-oliver{
  background:
  linear-gradient(
    120deg,
    #ffffff 0%,
    #f0f0f0 35%,
    #000000 70%,
    #dc0000 100%
  );

  position:relative;

  min-height:650px;

  padding:80px 0;

  overflow:hidden;
}

/* OVERLAY */
.numeros-oliver::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(
    circle at center,
    transparent 35%,
    rgba(0,25,20,.45) 100%
  );

  z-index:1;
}

/* ===== BG ===== */
.bg-numeros-oliver{
  position:absolute;

  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter:
  blur(3px)
  brightness(.7);

  z-index:0;
}

/* ===== OVERLAY ===== */
.overlay-numeros-oliver{
  position:absolute;
  inset:0;

  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-oliver{
  position:relative;
  z-index:2;

  text-align:center;

  color:#ffffff;

  font-size:44px;

  margin-bottom:40px;

  text-shadow:
  0 0 15px rgba(0,0,0,.25);
}

/* ===== GRID ===== */
.stats-grid-oliver{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-oliver{
  background:
  rgba(255,255,255,.22);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:
  clamp(18px,3vw,30px);

  text-align:center;

  color:white;

  border:
  1px solid rgba(0,20,0,.25);

  box-shadow:
  0 10px 30px rgba(0,0,0,.18);

  opacity:0;

  transition:
  opacity .6s ease,
  box-shadow .3s ease,
  border-color .3s ease,
  background .3s ease;
}

/* ===== ATIVO ===== */
.card-stat-oliver.ativo{
  opacity:1;

  box-shadow:
  0 0 20px rgba(0,0,0,.18);
}

/* ===== NÚMERO ===== */
.card-stat-oliver span{
  display:block;

  font-size:
  clamp(40px,5vw,60px);

  font-weight:bold;

  color:#fff;

  text-shadow:
  0 0 10px rgba(255,255,255,.35);
}

/* ===== TEXTO ===== */
.card-stat-oliver p{
  margin-top:10px;

  font-size:30px;

  line-height:1.5;

  color:#fff;
}

/* ===== HOVER ===== */
.card-stat-oliver:hover{
  background:
  rgba(255,255,255,.28);

  border-color:
  rgba(0,0,0,.45);

  box-shadow:
  0 0 35px rgba(0,0,0,.18);
}

/* ===== CARD GRANDE ===== */
.grande-oliver{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-oliver{
  width:0%;

  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:
  linear-gradient(
    90deg,
    #000000,
    #ffffff
  );

  box-shadow:
  0 0 10px rgba(250,250,250,.35);

  transition:width .3s ease;
}

/* ===== LUZ ===== */
.luz-oliver{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:.12;

  background:
  radial-gradient(
    circle,
    #dc0000,
    transparent 70%
  );
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-oliver{
    grid-template-columns:1fr;

    padding:0 15px;

