  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(255,0,0,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.oliver-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.oliver-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.oliver-ano-btn:hover{
  background:rgba(255,0,0,0.15);

  color:#Dc0000;

  transform:translateY(-2px);
}


.oliver-ano-btn.active{
  background:#Dc0000;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,0,0,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.oliver-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.oliver-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
