/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.oliver-team-change{
  position:relative;

  border:1px solid rgba(255,0,0,.45);

  box-shadow:
    0 0 20px rgba(255,0,0,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-oliver{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Dc0000,
      #Dc0000
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferoliver .5s ease;
}


@keyframes transferoliver{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.oliver-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,0,0,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.oliver-corrida-card:hover::before{
