/* =========================================================
   Maxoliver— ESTATÍSTICAS DA TEMPORADA 2026
========================================================= */

.oliver-season-2026 {
    position: relative;
    width: 100%;
	 height:100dvh;
	min-height:100dvh;
	padding: 100px 20px;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 85% 20%,
            rgba(249,249,249, 0.13),
            transparent 35%
        ),
        linear-gradient(
            135deg,
            #050505 0%,
            #0b0b0b 50%,
            #111111 100%
        );

    color: #fff;
}


/* =========================================================
   DETALHE LARANJA DE FUNDO
========================================================= */

.oliver-season-2026::before {
    content: "";
    position: absolute;

    width: 450px;
    height: 450px;

    right: -180px;
    bottom: -180px;

    border-radius: 50%;

    background: rgba(249,249,249, 0.08);

    filter: blur(100px);

    pointer-events: none;
}


/* =========================================================
   CONTAINER
========================================================= */

.oliver-season-2026-container {
    position: relative;
    z-index: 2;

    max-width: 1200px;

    margin: auto;

    display: grid;

    grid-template-columns: 350px 1fr;

    gap: 55px;

    align-items: center;
}


/* =========================================================
   IMAGEM
========================================================= */

.oliver-season-2026-image {
    position: relative;

    height: 560px;

    overflow: hidden;

    border-radius: 20px;

    background: #111;

    border: 1px solid rgba(255,255,255,0.08);

    box-shadow:
        0 25px 70px rgba(0,0,0,0.55);
}


/* IMAGEM */

.oliver-season-2026-image img {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center top;

    transition: transform 0.6s ease;
}

.oliver-season-2026-image:hover img {
    transform: scale(1.04);
}


/* =========================================================
   OVERLAY DA IMAGEM
========================================================= */

.oliver-season-2026-image-overlay {
    position: absolute;

    z-index: 2;

    inset: 0;

    background:
        linear-gradient(
            to top,
            rgba(0,0,0,0.85),
            rgba(0,0,0,0.05) 60%
        );

    pointer-events: none;
}


/* =========================================================
   NÚMERO #1
========================================================= */

.oliver-season-2026-number {
    position: absolute;

    z-index: 3;

    left: 25px;
    bottom: 20px;

    font-size: 80px;

    line-height: 1;

    font-weight: 900;

    font-style: italic;

    color: #F9f9f9;

    text-shadow:
        0 5px 25px rgba(0,0,0,0.7);
}


/* =========================================================
   NOME DO PILOTO
========================================================= */

.oliver-season-2026-driver-name {
    margin: 0 0 18px;

    font-size: clamp(35px, 4vw, 65px);

    line-height: 0.85;

    font-weight: 900;

    font-style: italic;

    letter-spacing: -3px;

    text-transform: uppercase;

    color: #fff;

    text-shadow:
        0 8px 30px rgba(0,0,0,0.45);
}


/* SOBRENOME EM DESTAQUE */

.oliver-season-2026-driver-name strong {
    display: block;

    color: #F9f9f9;

    font-weight: 900;
}

/* =========================================================
   CONTEÚDO
========================================================= */

.oliver-season-2026-content {
    width: 100%;
}


/* =========================================================
   TAG
========================================================= */

.oliver-season-2026-tag {
    display: inline-block;

    margin-bottom: 14px;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 3px;

    text-transform: uppercase;

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.oliver-season-2026-content h2 {
    margin: 0;

    font-size: clamp(38px, 4vw, 54px);

    line-height: 0.95;

    font-weight: 900;

    text-transform: uppercase;

    letter-spacing: -2px;
}

.oliver-season-2026-content h2 strong {
    color: #F9f9f9;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.oliver-season-2026-subtitle {
    margin: 18px 0 35px;

    color: #999;

    font-size: 15px;

    line-height: 1.6;
}


/* =========================================================
   CAMPEONATO
========================================================= */

.oliver-season-2026-championship {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 28px;

    margin-bottom: 18px;

    border-radius: 16px;

    background:
        linear-gradient(
            120deg,
            rgba(249,249,249,0.13),
            rgba(255,255,255,0.035)
        );

    border: 1px solid rgba(249,249,249,0.22);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.04);
}


/* INFO CAMPEONATO */

.oliver-season-2026-championship-info {
    display: flex;

    flex-direction: column;

    gap: 8px;
}

.oliver-season-2026-championship-info span {
    font-size: 16px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}

.oliver-season-2026-championship-info strong {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   PONTOS
========================================================= */

.oliver-season-2026-points {
    display: flex;

    flex-direction: column;

    align-items: flex-end;
}

.oliver-season-2026-points span {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #F9f9f9;
}

.oliver-season-2026-points small {
    margin-top: 7px;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}


/* =========================================================
   GRID
========================================================= */

.oliver-season-2026-stats {
    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 12px;
}


/* =========================================================
   CARD DE ESTATÍSTICA
========================================================= */

.oliver-season-2026-stat {
    position: relative;

    min-height: 125px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    overflow: hidden;

    border-radius: 14px;

    background:
        linear-gradient(
            145deg,
            rgba(255,255,255,0.065),
            rgba(255,255,255,0.025)
        );

    border: 1px solid rgba(255,255,255,0.07);

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        background 0.3s ease;
}

.oliver-season-2026-stat:hover {
    transform: translateY(-5px);

    border-color: rgba(249,249,249,0.4);

    background:
        linear-gradient(
            145deg,
            rgba(249,249,249,0.11),
            rgba(255,255,255,0.035)
        );
}


/* =========================================================
   BARRA LATERAL
========================================================= */

.oliver-season-2026-stat::before {
    content: "";

    position: absolute;

    left: 0;
    top: 0;

    width: 3px;
    height: 100%;

    background: #F9f9f9;

    transform: scaleY(0);

    transform-origin: bottom;

    transition: transform 0.3s ease;
}

.oliver-season-2026-stat:hover::before {
    transform: scaleY(1);
}


/* =========================================================
   ÍCONE
========================================================= */

.oliver-season-2026-stat-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(249,249,249,0.1);

    font-size: 18px;
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.oliver-season-2026-stat-info {
    display: flex;

    flex-direction: column;

    min-width: 0;
}

.oliver-season-2026-stat-info span {
    font-size: 30px;

    line-height: 1;

    font-weight: 900;

    color: #fff;

    white-space: nowrap;
}

.oliver-season-2026-stat-info p {
    margin: 7px 0 0;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #999;
}


/* =========================================================
   RESUMO
========================================================= */

.oliver-season-2026-summary {
    display: grid;

    grid-template-columns: repeat(3, 1fr);

    margin-top: 14px;

    border-radius: 14px;

    overflow: hidden;

    border: 1px solid rgba(255,255,255,0.07);

    background: rgba(255,255,255,0.035);
}


/* ITEM */

.oliver-season-2026-summary-item {
    padding: 22px;

    display: flex;

    flex-direction: column;

    gap: 9px;

    border-right: 1px solid rgba(255,255,255,0.07);
}

.oliver-season-2026-summary-item:last-child {
    border-right: none;
}


/* TEXTO */

.oliver-season-2026-summary-item span {
    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1.5px;

    color: #888;
}


/* VALOR */

.oliver-season-2026-summary-item strong {
    font-size: 25px;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 1000px) {

    .oliver-season-2026-container {
        grid-template-columns: 280px 1fr;

        gap: 35px;
    }

    .oliver-season-2026-image {
        height: 500px;
    }

    .oliver-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .oliver-season-2026-stat {
        min-height: 110px;
    }
}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .oliver-season-2026 {
        padding: 70px 15px;
    }

    .oliver-season-2026-container {
        display: flex;

        flex-direction: column;

        gap: 35px;
    }

    .oliver-season-2026-image {
        width: 100%;

        height: 390px;
    }

    .oliver-season-2026-number {
        font-size: 65px;
    }

    .oliver-season-2026-content h2 {
        font-size: 42px;
    }

    .oliver-season-2026-championship {
        padding: 20px;
    }

    .oliver-season-2026-championship-info strong,
    .oliver-season-2026-points span {
        font-size: 34px;
    }

    .oliver-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .oliver-season-2026-stat {
        padding: 16px;

        min-height: 110px;
    }

    .oliver-season-2026-stat-icon {
        width: 36px;
        height: 36px;

        font-size: 15px;
    }

    .oliver-season-2026-stat-info span {
        font-size: 26px;
    }

    .oliver-season-2026-summary {
        grid-template-columns: 1fr;
    }

    .oliver-season-2026-summary-item {
        border-right: none;

        border-bottom: 1px solid rgba(255,255,255,0.07);
    }

    .oliver-season-2026-summary-item:last-child {
        border-bottom: none;
    }
}


/* =========================================================
   CELULAR PEQUENO
========================================================= */

@media (max-width: 400px) {

    .oliver-season-2026-content h2 {
        font-size: 35px;
    }

    .oliver-season-2026-stats {
        grid-template-columns: 1fr;
    }

    .oliver-season-2026-stat {
        min-height: 100px;
    }

    .oliver-season-2026-championship {
        padding: 18px;
    }

    .oliver-season-2026-championship-info strong,
    .oliver-season-2026-points span {
        font-size: 30px;
    }
}





