/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-bearman {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-bearman {
    margin-bottom: 35px;
}


.grafico-header-bearman > span {
    display: block;

    margin-bottom: 10px;

    color: #E10600;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-bearman h3 {
