    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-bearman h3 span {
    color: #E10600;
}


.grafico-layout-bearman {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
