/* =========================================================
   RADAR
========================================================= */

.radar-container-bearman {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-bearman {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-bearman {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-bearman {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-bearman {
    fill:
        rgba(255,6,0,.20);

    stroke: #E10600;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,6,0,.35)
        );
}


.radar-ponto-bearman {
    fill: #E10600;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-bearman {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-bearman {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-bearman {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-bearman {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-bearman {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-bearman {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-bearman {
    top: 16%;
    left: -30px;
