  transition: 0.4s ease;
}

.card-oliver.ativo{
  opacity: 1;
  transform: translateY(0);
}

/* NUMBER */
.left-oliver{
  position: absolute;
  left: 10px;
  top: clamp(40px, 10vw, 60px);
}

.number-oliver{
  font-size: clamp(60px, 15vw, 120px);
  color: #ffffff;
}

/* RIGHT */
.right-oliver{
  position: absolute;
  top: 15px;
  right: 10px;
  text-align: right;
}

.right-oliver h1{
  color: #ffffff;
  margin: 0;
  font-size: clamp(14px, 3vw, 20px);
}

.right-oliver h2{
  color: white;
  margin: 0;
  font-size: clamp(12px, 2.5vw, 16px);
}

.logo-oliver{
  width: clamp(24px, 5vw, 40px);
  margin-top: 8px;
}

/* WAVE */
.wave-oliver{
  position: absolute;
  top: clamp(110px, 30vw, 160px);
  left: 0;

  width: 100%;
  height: clamp(30px, 8vw, 50px);

  display: flex;
  align-items: flex-end;
}

.wave-oliver span{
  flex: 1;
  margin: 0 1px;

  height: 6px;
  background: linear-gradient(to top, #ffffff, transparent);

  animation: wave-oliver infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-oliver.falando .wave-oliver span{
  animation-play-state: running;
}

/* TEXTO */
.content-oliver{
  position: absolute;
  bottom: 0;
  width: 100%;

  transform: scaleY(0);
  transform-origin: bottom;

  transition: transform 0.4s ease;
}

.card-oliver.mostrar-texto .content-oliver{
  transform: scaleY(1);
}

.text-oliver{
  padding: 10px 15px;

  opacity: 0;
  transform: translateY(10px);

  transition: all 0.4s ease;
}

.card-oliver.mostrar-texto .text-oliver{
  opacity: 1;
  transform: translateY(0);
}

.eng-oliver{
  color: white;
  font-size: clamp(12px, 3vw, 20px);
}

.pil-oliver{
  color: #ffffff;
  text-align: right;
  font-size: clamp(12px, 3vw, 20px);
}

}

.galeria-oliver{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(255,255,255,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-oliver::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-oliver{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(255,255,255,.18);
}

/* GRID */
.grid-galeria-oliver{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-oliver{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-oliver img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-oliver:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-oli{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-oliver:hover .overlay-oli{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-oli h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA */
.overlay-oli h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #ffffff,
    #000000
  );

  box-shadow:
  0 0 18px rgba(255,255,255,.5);
}

/* DESCRIÇÃO */
.overlay-oli p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-oliver::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(255,255,255,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-oliver:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-oliver{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightboxChar .3s ease;
}

@keyframes fadeLightboxChar{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-oliver{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightboxChar .35s ease;
}

@keyframes zoomLightboxChar{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-oliver{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-oliver:hover{
  transform:rotate(90deg);

  background:
  rgba(255,255,255,.18);

  border-color:
  rgba(255,255,255,.35);

  color:#ffffff;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-oliver{
    grid-template-columns:1fr;
  }

  .overlay-oli h3{
    font-size:20px;
  }

  .fechar-oliver{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

