.slider-nico{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-nico {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-nico::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-nico-container,
.titulo-nico-slider,
.dots-nico,
.btn-nico {
  position: relative;
  z-index: 2;
}

.titulo-nico-slider {
  font-size: 40px;
  color: #8f8f8b;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-nico-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-nico-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-nico {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-nico img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-nico-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-nico-texto h3 {
  color: #8f8f8b;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-nico-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-nico {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(120,120,120,0.6);
  border: none;
  color: #d00;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-nico:hover {
  background: #000000;
  color:#8f8f8b;
}

/* BOLINHAS */
.dots-nico {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-nico {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(120,120,120,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-nico:hover {
  background: #8f8f8b;
}

.dot-nico.active {
  background: #8f8f8b;
  transform: scale(1.3);
}
.dots-nico {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-nico img {
    height: 300px;
  }

  .slide-nico-texto h3 {
    font-size: 20px;
  }

  .slide-nico-texto p {
    font-size: 14px;
  }
}

.numeros-nico{
 background:
 linear-gradient(
