  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* CARD */
.card-stat-nico{
  background:
  rgba(255,255,255,.22);

  backdrop-filter:blur(10px);

  border-radius:18px;

