  transition:
  opacity .6s ease,
  box-shadow .3s ease,
  border-color .3s ease,
  background .3s ease;
}

/* ATIVO */
.card-stat-nico.ativo{
  opacity:1;

  box-shadow:
  0 0 20px rgba(199,0,0,.18);
}

/* NÚMERO */
.card-stat-nico span{
  display:block;

  font-size:
  clamp(32px,5vw,60px);

  font-weight:bold;

  color:#111111;

  text-shadow:
