  border-color:
  rgba(199,0,0,.45);

  box-shadow:
  0 0 35px rgba(199,0,0,.18);
}

/* CARD GRANDE */
.grande-nico{
  grid-column:span 3;
}

/* BARRA */
.barra-velocidade-nico{
  width:0%;

  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:
  linear-gradient(
    90deg,
    #111111,
    #c70000
  );

  box-shadow:
  0 0 10px rgba(199,0,0,.35);

  transition:width .3s ease;
}

/* LUZ */
.luz-nico{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

