    font-weight: 800;

    letter-spacing: 1.5px;

    color: #888;
}


/* VALOR */

.nico-season-2026-summary-item strong {
    font-size: 25px;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 1000px) {

    .nico-season-2026-container {
        grid-template-columns: 280px 1fr;

        gap: 35px;
    }

    .nico-season-2026-image {
        height: 500px;
    }

    .nico-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

