    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-hulkenberg::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255,6,0, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-hulkenberg {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-hulkenberg {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
