    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-hulkenberg::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
