  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* 🔴 STATUS */
.radio-status-nico {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #ffffff;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-nico::before {
  content: "●";
  margin-right: 6px;
  animation: blink-nico 1s infinite;
}

@keyframes blink-nico {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-nico {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: #ffffff;
}

/* CARD */
.card-nico {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-nico::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(120,120,120,0.15), transparent);
  z-index: -1;
}

.card-nico.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-nico.saindo {
  opacity: 0;
  transform: translateY(20px);
}

