.galeria-nico{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(120,120,120,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-nico::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(120,120,120,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-nico{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:#ffffff;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(120,120,120,.18);
}

/* GRID */
.grid-galeria-nico{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-nico{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-nico img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-nico:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-hulke{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-nico:hover .overlay-hulke{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-hulke h3{
  color:#ffffff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA */
.overlay-hulke h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #8f8f8b,
    #dc0000
  );

  box-shadow:
  0 0 18px rgba(120,120,120,.5);
}

/* DESCRIÇÃO */
.overlay-hulke p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-nico::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(120,120,120,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-nico:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-nico{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightboxChar .3s ease;
}

@keyframes fadeLightboxChar{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-nico{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightboxChar .35s ease;
}

@keyframes zoomLightboxChar{

  from{
    transform:scale(.85);
