.gabi-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(120,120,140,0.25) 0%,
    rgba(255,0,0,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY */
.gabi-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

background:
linear-gradient(
to right,
rgba(120,120,120,.90),
rgba(225,6,0,.10),
rgba(0,0,0,.85)
