  transform:translateY(-2px);
}


.gabi-ano-btn.active{
  background:#Dc0000;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,0,0,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.gabi-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.gabi-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.gabi-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.gabi-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.gabi-team-change{
  position:relative;

  border:1px solid rgba(255,0,0,.45);

  box-shadow:
    0 0 20px rgba(255,0,0,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-gabi{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Dc0000,
      #Dc0000
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transfergabi .5s ease;
}


@keyframes transfergabi{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.gabi-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,0,0,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.gabi-corrida-card:hover::before{
  opacity:1;
}


.gabi-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,0,0,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.gabi-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.gabi-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.gabi-vitoria .gabi-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,0,0,0.25);

}


.gabi-podio .gabi-resultado{

  color: #Dc0000 ;

  text-shadow:
    0 0 10px rgba(255,0,0,0.2);

}


.gabi-pontos .gabi-resultado{

  color:#ffffff;

}


.gabi-dnf .gabi-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.gabi-sem-pontos .gabi-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.gabi-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#Dc0000;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.gabi-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.gabi-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

  opacity:0;

  transform:translateY(15px);

  transition:.4s ease;

  box-sizing:border-box;
}


.gabi-summary-card.show{

  opacity:1;

  transform:translateY(0);

}


.gabi-summary-title{

  color:#Dc0000;

  font-size:18px;

  font-weight:900;

  margin-bottom:10px;

  letter-spacing:1px;

}


.gabi-summary-stats{

  display:flex;

  justify-content:space-between;

  gap:10px;
}


.gabi-summary-box{

