/* 🔴 STATUS */
.radio-status-gabi {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #ffffff;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-gabi::before {
  content: "●";
  margin-right: 6px;
  animation: blink-gabi 1s infinite;
}

@keyframes blink-gabi {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-gabi {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: #ffffff;
}

/* CARD */
.card-gabi {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-gabi::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(120,120,120,0.15), transparent);
  z-index: -1;
}

.card-gabi.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-gabi.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-gabi {
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-gabi {
