.slider-gasly{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-gasly {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-gasly::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-gasly-container,
.titulo-gasly-slider,
.dots-gasly,
.btn-gasly {
  position: relative;
  z-index: 2;
}

.titulo-gasly-slider {
  font-size: 40px;
  color: #0090ff;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-gasly-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-gasly-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-gasly {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-gasly img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-gasly-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-gasly-texto h3 {
  color: #ffffff;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-gasly-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-gasly {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(255,105,180,0.6);
  border: none;
  color: #09f;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-gasly:hover {
  background: #ff4fa8;
  color:#0094ff;
}

/* BOLINHAS */
.dots-gasly {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-gasly {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,105,180,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-gasly:hover {
  background: #0094ff;
}

.dot-gasly.active {
  background: #0068f3;
  transform: scale(1.3);
}
.dots-gasly {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-gasly img {
    height: 300px;
  }

  .slide-gasly-texto h3 {
    font-size: 20px;
  }

  .slide-gasly-texto p {
    font-size: 14px;
  }
}

