    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #0090ff,
            #Ff63b8
        );

    box-shadow:
        0 0 12px
        rgba(255,99,184,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-gasly {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-gasly {
