        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-gasly h3 span {
    color: #0090ff;
}


.grafico-layout-gasly {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
