/* =========================================================
   RADAR
========================================================= */

.radar-container-gasly {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-gasly {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-gasly {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-gasly {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-gasly {
    fill:
        rgba(255,99,184,.20);

    stroke: #0090ff;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,99,184,.35)
        );
}


.radar-ponto-gasly {
    fill: #0090ff;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-gasly {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-gasly {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-gasly {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-gasly {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-gasly {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-gasly {
