.radio-f1-gasly {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* 🔴 STATUS */
.radio-status-gasly {
  position: absolute;
  top: 15px;
  left: 20px;
  color: #ff4fa8;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-gasly::before {
  content: "●";
  margin-right: 6px;
  animation: blink-gasly 1s infinite;
}

@keyframes blink-gasly {
  50% { opacity: 0.3; }
}

/* 🏎️ INFO */
.race-info-gasly {
  position: absolute;
  top: 15px;
  right: 20px;
  display: flex;
  gap: 15px;
  font-size: 30px;
  color: #ffffff;
}

/* CARD */
.card-gasly {
  width: 280px;
  height: 420px;
  background: #0b0b0f;
  border-radius: 12px;
  border: 1px solid #222;

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* ✨ GLOW */
.card-gasly::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(120,120,120,0.15), transparent);
  z-index: -1;
}

.card-gasly.ativo {
  opacity: 1;
  transform: translateY(0);
}

.card-gasly.saindo {
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-gasly {
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-gasly {
  font-size: 120px;
  color: #0094ff;
}

/* DIREITA */
.right-gasly {
  position: absolute;
  top: 20px;
  right: 15px;
  text-align: right;
}

.right-gasly h1 {
  color: #ff4fa8;
  margin: 0;
}

.right-gasly h2 {
  color: #0094ff;
  margin: 0;
}

.logo-gasly {
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-gasly {
  position: absolute;
  top: 160px;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  align-items: flex-end;
}

.wave-gasly span {
  flex: 1;
  margin: 0 1px;
  height: 6px;

  background: linear-gradient(to top, #ff4fa8, transparent);

  animation: wave-gasly infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-gasly.falando .wave-gasly span {
  animation-play-state: running;
}

@keyframes wave-gasly {
  0%,100% { height: 6px; opacity: 0.3 }
  50% { height: 45px; opacity: 1 }
}

/* CONTEÚDO */
.content-gasly {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}

/* TEXTO ANIMADO */
.text-gasly {
  padding: 10px 15px;
  opacity: 0;
  transform: translateY(30px);
