width:290px;

height:100vh;

padding:90px 20px;

background:linear-gradient(
180deg,
#0090ff 0%,
#1a1207 35%,
#0a0a0a 100%
);


overflow:hidden;

display:flex;

flex-direction:column;
	
transition:.45s cubic-bezier(.77,0,.18,1);

z-index:9999;

opacity:0;

visibility:hidden;

pointer-events:none;

}

.side-menu-franco.active{

left:0;

opacity:1;

visibility:visible;

pointer-events:all;

}


.side-menu-franco ul{
    list-style:none;
    padding:0;
    margin:0;
    position:relative;
    z-index:2;
}

.side-menu-franco li{
    margin:10px 0;
}

.side-menu-franco a{

    display:flex;
    justify-content:space-between;
    align-items:center;

    padding:12px 16px;

    color:#fff;

    text-decoration:none;

    background:rgba(252,16,252,.08);

    border:1px solid rgba(252,16,252,.12);

    border-radius:14px;

    font-size:16px;

    font-weight:800;

}


.side-menu-franco a span{

display:flex;

align-items:center;

gap:12px;

}

.side-menu-franco a i{

transition:.35s;

}

.side-menu-franco a:hover{

background:#0090ff;

color:#000;

transform:translateX(8px);

box-shadow:
0 0 20px rgba(252,16,252,.35);

}

.side-menu-franco a:hover .fa-chevron-right{

transform:translateX(8px);

}

.menu-links-franco{

    flex:1;

    overflow-y:auto;

    padding-right:8px;

}

.menu-links-franco::-webkit-scrollbar{

    width:6px;

}

.menu-links-franco::-webkit-scrollbar-thumb{

    background:#0090ff;

    border-radius:20px;

}

.menu-links-franco::-webkit-scrollbar-track{

    background:transparent;

}


/* =========================
   BOTÃO FECHAR (X)
========================= */
.close-menu-franco{
  position:absolute;
  top:20px;
  right:20px;

  font-size:26px;
  color:#000;

  cursor:pointer;

  z-index:20;
  transition:.3s;
}

.close-menu-franco:hover{
  color:#000;
  transform:rotate(90deg) scale(1.2);
}

/* =========================
   PERFIL DO MENU
========================= */

.menu-profile-franco{

    position:relative;

    z-index:2;

    display:flex;

    flex-direction:column;

    align-items:center;

    margin-bottom:35px;

}

.menu-profile-franco img{

    width:90px;

    height:90px;

    border-radius:50%;

    object-fit:cover;

    border:3px solid #0090ff;

    box-shadow:
    0 0 20px rgba(252,16,252,.45);

    margin-bottom:12px;

}

.menu-profile-franco h2{

    color:#fff;

    font-size:22px;

    font-weight:900;

    margin:0;

}

.menu-profile-franco span{

    color:#0090ff;

    font-size:20px;

    font-weight:900;

    margin-top:4px;

}

.menu-profile-franco p{

    color:#ddd;

    font-size:13px;

    margin-top:8px;

    text-align:center;

}

/* =========================
   OVERLAY
========================= */
.overlay-franco{
  position:fixed;
  inset:0;

  background: rgba(0,0,0,0.5);

  opacity:0;
  visibility:hidden;
  pointer-events:none;

  transition:.3s;

  z-index:1002;
}

.overlay-franco.active{
  opacity:1;
  visibility:visible;
  pointer-events:all;
}





@media (max-width:768px){

  .header-franco{
    padding:12px 16px;
  }

  .franco-logo img{
    width:38px;
  }

  .side-menu-franco{
    width:100%;
    height:100vh;

    top:0;
    left:-100%;

    padding:80px 18px 20px;

    overflow-y:auto;
  }

  .side-menu-franco.active{
    left:0;
  }

  .menu-profile-franco{
    margin-bottom:22px;
  }

  .menu-profile-franco img{
    width:70px;
    height:70px;
  }

  .menu-profile-franco h2{
    font-size:19px;
  }

  .menu-profile-franco span{
    font-size:16px;
  }

  .menu-profile-franco p{
    font-size:12px;
  }

  .side-menu-franco ul{
    gap:0;
  }

  .side-menu-franco li{
    margin:8px 0;
  }

  .side-menu-franco a{
    padding:11px 14px;

    font-size:14px;

    border-radius:12px;
  }

  .side-menu-franco a span{
    gap:10px;
  }

  .close-menu-franco{
    top:18px;
    right:18px;

    font-size:24px;
  }

}







.franco-banner-bg{
  position: relative;

  width: 100%;
  height: 100vh;

  overflow: hidden;

  background-image: url("franco/banner1.png");
  background-size: cover;
  background-position: center;

  display: flex;
  align-items: center;
}

/* LIGHT FOLLOW MOUSE */
.franco-banner-bg::before{
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  border-radius: 50%;

  background:
  radial-gradient(
    circle,
    rgba(0,144,255,0.85) 0%,
    rgba(255,105,180,0.10) 25%,
    transparent 70%
  );

  top: var(--mouse-y);
  left: var(--mouse-x);

  transform: translate(-50%, -50%);

  pointer-events: none;

  z-index: 2;

  transition:
  top 0.08s linear,
  left 0.08s linear;
}

/* OVERLAY */
.franco-banner-bg::after{
  content: "";

  position: absolute;
  inset: 0;

background:
linear-gradient(
to right,
rgba(0,144,255,.90),
rgba(225,105,180,.10),
rgba(0,0,0,.85)
);

  z-index: 1;
}

/* CONTEÚDO ACIMA */
.franco-banner-bg > *{
  position: relative;
  z-index: 5;
}

/* =========================
   HOME BUTTON
========================= */

.home-btn-franco{
  position: absolute;

  top: 105px;
  left: 25px;

  display: flex;
  align-items: center;
  gap: 10px;

  padding: 10px 18px;

  border-radius: 40px;

  background: rgba(125,125,155,0.98);

  backdrop-filter: blur(10px);

  text-decoration: none;

  transition: 0.3s;
}

.home-btn-franco img{
  width: 48px;
}

.home-btn-franco span{
  color: #ffffff;
  font-weight: 700;
  font-size: 34px;
}

.home-btn-franco:hover{
  transform: scale(1.05);

  background:
  rgba(225,144,180,.15);

  box-shadow:
  0 0 20px rgba(0,140,255,.25);
}

/* =========================
   INFO
========================= */

.franco-banner-info{
  position: absolute;

  left: 70px;
  top: 50%;

  transform: translateY(-50%);

  display: flex;
  flex-direction: column;

  gap: 14px;
}

/* NOME */
.franco-nome{
  line-height: 0.9;
}

.franco-nome span{
  display: block;

  font-size: 42px;
  font-weight: 300;

  color: rgba(255,255,255,0.7);

  text-transform: uppercase;
  letter-spacing: 3px;
}

.franco-nome strong{
  display: block;

  font-size: 95px;
  font-weight: 900;

  color: #ff4fa8;

  text-transform: uppercase;
  letter-spacing: 4px;

  text-shadow:
  0 0 10px rgba(0,144,255,0.4),
  0 0 25px rgba(255,160,180,0.2);
}

/* PAÍS */
.franco-pais{
  font-size: 18px;
  font-weight: 600;

  color: rgba(255,255,255,0.85);

  letter-spacing: 2px;
}

/* EQUIPE */
.franco-equipe{
  width: fit-content;

  padding: 10px 18px;

  border-radius: 30px;

  background: rgba(255,105,180,0.08);

  border: 1px solid rgba(0,155,255,.35);

  box-shadow:
  0 0 15px rgba(255,160,180,.15);

  backdrop-filter: blur(10px);

  color: #ffffff;

  font-size: 20px;
  font-weight: 700;

  letter-spacing: 1px;
}

/* FRASE */
.franco-frase{
  margin-top: 8px;

  padding-left: 14px;

border-left: 3px solid #ff4fa8;

  color: rgba(255,255,255,0.75);

  font-size: 20px;
  font-style: italic;

  max-width: 450px;
}

/* =========================
   NÚMERO
========================= */

.franco-numero-bg{
  position: absolute;

  right: 40px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 320px;
  font-weight: 900;

  color: rgba(255,144,180,0.08);

  font-family: 'Russo One', sans-serif;

  user-select: none;
  pointer-events: none;

  animation: francoGlow 4s ease-in-out infinite;
}

/* NÚMERO */
@keyframes francoGlow{

  0%{
    text-shadow: 0 0 15px rgba(0,144,255,0.98);
  }

  50%{
    text-shadow:
    0 0 25px rgba(225,105,140,0.35),
    0 0 60px rgba(0,0,0,0.12);
  }

  100%{
    text-shadow: 0 0 15px rgba(0,144,255,0.08);
  }
}
/* =========================
   CHUVA
========================= */

.franco-rain{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.franco-rain span{
  position: absolute;
  top: -120px;
  left: calc(10% * var(--i));

  width: 7px;
  height: 120px;

  background: linear-gradient(
    transparent,
    rgba(255,105,140,0.8),
    transparent
  );

  opacity: 0.5;

  animation: francorain 2s linear infinite;
}

.franco-rain span:nth-child(1){
  left: 10%;
  animation-duration: 2s;
}

.franco-rain span:nth-child(2){
  left: 25%;
  animation-duration: 1.6s;
}

.franco-rain span:nth-child(3){
  left: 40%;
  animation-duration: 2.2s;
}

.franco-rain span:nth-child(4){
  left: 55%;
  animation-duration: 1.8s;
}

.franco-rain span:nth-child(5){
  left: 70%;
  animation-duration: 2.5s;
}

.franco-rain span:nth-child(6){
  left: 82%;
  animation-duration: 1.7s;
}

.franco-rain span:nth-child(7){
  left: 92%;
  animation-duration: 2.1s;
}

.franco-rain span:nth-child(8){
  left: 48%;
  animation-duration: 1.9s;
}

/* ANIMAÇÃO */

@keyframes francorain{

  0%{
    transform:
    translateY(-200px);

    opacity: 0;
  }

  10%{
    opacity: 0.6;
  }

  100%{
    transform:
    translateY(120vh);

    opacity: 0;
  }

}



/* =========================
   PARTICLES
========================= */

.franco-particles{
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
  pointer-events: none;
}

.franco-particles span{
  position: absolute;

  width: 16px;
  height: 16px;

  border-radius: 50%;

background: rgba(0,144,255,0.7);

box-shadow:
0 0 10px rgba(255,105,140,0.8),
0 0 20px rgba(0,144,255,0.4);



  animation: francoFloat linear infinite;
}

.franco-particles span:nth-child(1){
  left: 10%;
  animation-duration: 12s;
  animation-delay: 0s;
  transform: scale(1.2);
}

.franco-particles span:nth-child(2){
  left: 20%;
  animation-duration: 18s;
  animation-delay: 2s;
}

.franco-particles span:nth-child(3){
  left: 35%;
  animation-duration: 15s;
  animation-delay: 1s;
  transform: scale(1.5);
}

.franco-particles span:nth-child(4){
  left: 50%;
  animation-duration: 20s;
  animation-delay: 4s;
}

.franco-particles span:nth-child(5){
  left: 65%;
  animation-duration: 16s;
  animation-delay: 2s;
}

.franco-particles span:nth-child(6){
  left: 75%;
  animation-duration: 22s;
  animation-delay: 5s;
  transform: scale(1.3);
}

.franco-particles span:nth-child(7){
  left: 85%;
  animation-duration: 14s;
  animation-delay: 1s;
}

.franco-particles span:nth-child(8){
  left: 92%;
  animation-duration: 19s;
  animation-delay: 3s;
}

.franco-particles span:nth-child(9){
  left: 40%;
  animation-duration: 17s;
  animation-delay: 6s;
}

.franco-particles span:nth-child(10){
  left: 58%;
  animation-duration: 13s;
  animation-delay: 2s;
}

/* ANIMAÇÃO */

@keyframes francoFloat{

  0%{
    transform:
    translateY(100vh)
    scale(0.5);

    opacity: 0;
  }

  10%{
    opacity: 1;
  }

  50%{
    opacity: 0.8;
  }

  100%{
    transform:
    translateY(-120px)
    scale(1.4);

    opacity: 0;
  }

}


/* =========================
   SOCIALS
========================= */

.franco-socials{
  position: absolute;

  right: 30px;
  bottom: 100px;

  display: flex;
  gap: 15px;
}

.social-link-franco{
  width: 88px;
  height: 88px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: rgba(120,120,120,0.08);

  border: 1px solid rgba(120,120,120,0.08);

  backdrop-filter: blur(10px);

  color: #0090ff;

  font-size: 40px;

  text-decoration: none;

  transition: 0.3s;
}

.social-link-franco:hover{
     transform: scale(1.12);

  color: #ff4da6;

  box-shadow:
  0 0 15px rgba(255,105,144,.5);

}

/* =========================
   RESPONSIVO
========================= */

@media(max-width:768px){

  .franco-banner-info{
    left: 25px;
    bottom: 100px;
    top: auto;
    transform: none;
  }

  .franco-nome span{font-size:24px;}
  .franco-nome strong{font-size:58px;}
  .franco-pais{font-size:14px;}

  .franco-equipe{
