.slider-franco{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-franco {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-franco::after {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO NA FRENTE */
.slider-franco-container,
.titulo-franco-slider,
.dots-franco,
.btn-franco {
  position: relative;
  z-index: 2;
}

.titulo-franco-slider {
  font-size: 40px;
  color: #0090ff;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-franco-container {
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-franco-track {
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-franco {
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-franco img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-franco-texto {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-franco-texto h3 {
  color: #ffffff;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-franco-texto p {
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-franco {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(255,105,180,0.6);
  border: none;
  color: #09f;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev {
  left: 15px;
}

.next {
  right: 15px;
}

.btn-franco:hover {
  background: #ff4fa8;
  color:#0094ff;
}

/* BOLINHAS */
.dots-franco {
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-franco {
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(255,105,180,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-franco:hover {
  background: #0094ff;
}

.dot-franco.active {
  background: #0068f3;
  transform: scale(1.3);
}
.dots-franco {
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}


/* RESPONSIVO */
@media(max-width: 768px){

  .slide-franco img {
    height: 300px;
  }

  .slide-franco-texto h3 {
    font-size: 20px;
  }

  .slide-franco-texto p {
    font-size: 14px;
  }
}

.numeros-franco{
  background:
  linear-gradient(
    135deg,

    #ff4fa8 0%,
    #f122d4 18%,
    #0057b8 38%,
    #0094ff 52%,

    #ff4fa8 72%,
    #ff79c6 86%,

    #0068f3 100%
  );

  position:relative;

  min-height:650px;

  padding:80px 0;

  overflow:hidden;
}

/* OVERLAY */
.numeros-franco::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  radial-gradient(
    circle at center,
    transparent 35%,
    rgba(5,10,35,.45) 100%
  );

  z-index:1;
}

/* ===== BG ===== */
.bg-numeros-franco{
  position:absolute;

  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter:
  blur(3px)
  brightness(.68);

  z-index:0;
}

/* ===== OVERLAY ===== */
.overlay-numeros-franco{
  position:absolute;
  inset:0;

  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-franco{
  position:relative;
  z-index:2;

  text-align:center;

  color:#ffffff;

  font-size:44px;

  margin-bottom:40px;

  text-shadow:
  0 0 18px rgba(255,79,168,.25),
  0 0 22px rgba(0,148,255,.2);
}

/* ===== GRID ===== */
.stats-grid-franco{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-franco{
  background:
  rgba(255,255,255,.14);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:
  clamp(18px,3vw,30px);

  text-align:center;

  color:white;

  border:
  1px solid rgba(255,255,255,.16);

  box-shadow:
  0 10px 30px rgba(0,0,0,.2);

  opacity:0;

  transition:
  opacity .6s ease,
  box-shadow .3s ease,
  border-color .3s ease,
  background .3s ease,
  transform .3s ease;
}

/* ===== ATIVO ===== */
.card-stat-franco.ativo{
  opacity:1;

  box-shadow:
  0 0 20px rgba(0,148,255,.18),
  0 0 25px rgba(255,79,168,.12);
}

/* ===== NÚMERO ===== */
.card-stat-franco span{
  display:block;

  font-size:
  clamp(32px,5vw,60px);

  font-weight:bold;

  color:#ffffff;

  text-shadow:
  0 0 12px rgba(255,255,255,.28);
}

/* ===== TEXTO ===== */
.card-stat-franco p{
  margin-top:10px;

  font-size:18px;

  line-height:1.5;

  color:#eef6ff;
}

/* ===== HOVER ===== */
.card-stat-franco:hover{
  transform:
  translateY(-6px);

  background:
  rgba(255,255,255,.18);

  border-color:
  rgba(255,255,255,.3);

  box-shadow:
  0 0 35px rgba(0,148,255,.18),
  0 0 30px rgba(255,79,168,.12);
}

/* ===== CARD GRANDE ===== */
.grande-franco{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-franco{
  width:0%;

  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:
  linear-gradient(
    90deg,
    #ff4fa8,
    #0094ff
  );

  box-shadow:
  0 0 12px rgba(255,79,168,.35),
  0 0 14px rgba(0,148,255,.25);

  transition:width .3s ease;
}

/* ===== LUZ ===== */
.luz-franco{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:.15;

  background:
  radial-gradient(
    circle,
    #ff4fa8,
    transparent 70%
  );
}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-franco{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-franco{
    grid-column:span 1;
  }

  .titulo-numeros-franco{
    font-size:32px;
  }

  .card-stat-franco p{
    font-size:16px;
  }

}



/* =========================================================
   franco — TIMELINE
========================================================= */

.franco-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(255,99,184,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.franco-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.franco-timeline-title{
  color:#Ff63b8;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(255,99,184,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.franco-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.franco-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.franco-ano-btn:hover{
  background:rgba(255,99,184,0.15);

  color:#Ff63b8;

  transform:translateY(-2px);
}


.franco-ano-btn.active{
  background:#Ff63b8;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,99,184,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.franco-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.franco-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.franco-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.franco-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.franco-team-change{
  position:relative;

  border:1px solid rgba(255,99,184,.45);

  box-shadow:
    0 0 20px rgba(255,99,184,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-franco{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Ff63b8,
      #Ff63b8
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferfranco .5s ease;
}


@keyframes transferfranco{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.franco-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,99,184,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.franco-corrida-card:hover::before{
  opacity:1;
}


.franco-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,99,184,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.franco-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.franco-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.franco-vitoria .franco-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,99,184,0.25);

}


.franco-podio .franco-resultado{

  color: #Ff63b8 ;

  text-shadow:
    0 0 10px rgba(255,99,184,0.2);

}


.franco-pontos .franco-resultado{

  color:#ffffff;

}


.franco-dnf .franco-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.franco-sem-pontos .franco-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.franco-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#Ff63b8;

  opacity:.9;

}


/* =========================================================
   SUMMARY
========================================================= */

.franco-season-summary{

  margin-top:18px;

  display:flex;

  justify-content:center;

  flex-shrink:0;
}


.franco-summary-card{

  width:100%;

  max-width:400px;

  background:
    linear-gradient(
      145deg,
      #10141a,
      #0b0e12
    );

  border:
    1px solid rgba(255,255,255,0.08);

  border-radius:14px;

  padding:12px 18px;

  text-align:center;

  box-shadow:
    0 10px 40px rgba(0,0,0,0.6);

  opacity:0;

  transform:translateY(15px);

  transition:.4s ease;

  box-sizing:border-box;
}


.franco-summary-card.show{

  opacity:1;

  transform:translateY(0);

}


.franco-summary-title{

  color:#Ff63b8;

  font-size:18px;

  font-weight:900;

  margin-bottom:10px;

  letter-spacing:1px;

}


.franco-summary-stats{

  display:flex;

  justify-content:space-between;

  gap:10px;
}


.franco-summary-box{

  flex:1;

  padding:7px;

  border-radius:9px;

  background:
    rgba(255,255,255,0.03);

  border:
    1px solid rgba(255,255,255,0.06);
}


.franco-summary-label{

  display:block;

  font-size:11px;

  color:#aaa;

  margin-bottom:3px;

  text-transform:uppercase;

  letter-spacing:1px;
}


.franco-summary-value{

  font-size:22px;

  font-weight:900;

  color:#fff;
}


