/* SOBRENOME EM DESTAQUE */

.franco-season-2026-driver-name strong {
    display: block;

    color: #Ff63b8;

    font-weight: 900;
}

/* =========================================================
   CONTEÚDO
========================================================= */

.franco-season-2026-content {
    width: 100%;
}


/* =========================================================
   TAG
========================================================= */

.franco-season-2026-tag {
    display: inline-block;

    margin-bottom: 14px;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 3px;

    text-transform: uppercase;

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.franco-season-2026-content h2 {
    margin: 0;

    font-size: clamp(38px, 4vw, 54px);

    line-height: 0.95;

    font-weight: 900;

    text-transform: uppercase;

    letter-spacing: -2px;
}

.franco-season-2026-content h2 strong {
    color: #Ff63b8;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.franco-season-2026-subtitle {
    margin: 18px 0 35px;

    color: #999;

    font-size: 15px;

    line-height: 1.6;
}


/* =========================================================
   CAMPEONATO
========================================================= */

.franco-season-2026-championship {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 28px;

    margin-bottom: 18px;

    border-radius: 16px;

    background:
        linear-gradient(
            120deg,
            rgba(0,144,255,0.13),
            rgba(255,255,255,0.035)
        );

