    letter-spacing: 2px;
}


.skills-header-colapinto h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-colapinto h3 span {
    color: #0090ff;
}


