/* =========================================================
   RADAR
========================================================= */

.radar-container-colapinto {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-colapinto {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-colapinto {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-colapinto {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-colapinto {
    fill:
        rgba(255,99,184,.20);

    stroke: #0090ff;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,99,184,.35)
        );
}


.radar-ponto-colapinto {
    fill: #0090ff;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-colapinto {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-colapinto {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-colapinto {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-colapinto {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-colapinto {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-colapinto {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-colapinto {
    top: 16%;
    left: -30px;
}


