.resumo-icone-colapinto {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,99,184,.10);

    color: #0090ff;

    font-size: 18px;
}


.resumo-card-colapinto > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-colapinto h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-colapinto p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-colapinto {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,99,184,.12),
            rgba(255,99,184,.02)
        );

    border:
        1px solid
        rgba(255,99,184,.25);
}


.pilotagem-conclusao-colapinto::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
