.logo-franco {
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-franco {
  position: absolute;
  top: 160px;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  align-items: flex-end;
}

.wave-franco span {
  flex: 1;
  margin: 0 1px;
  height: 6px;

  background: linear-gradient(to top, #ff4fa8, transparent);

  animation: wave-franco infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-franco.falando .wave-franco span {
  animation-play-state: running;
}

@keyframes wave-franco {
  0%,100% { height: 6px; opacity: 0.3 }
  50% { height: 45px; opacity: 1 }
}

/* CONTEÚDO */
.content-franco {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}

