.item-galeria-franco::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(120,120,120,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-franco:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-franco{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightboxChar .3s ease;
}

@keyframes fadeLightboxChar{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-franco{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightboxChar .35s ease;
}

@keyframes zoomLightboxChar{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-franco{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(120,120,120,.08);

  border:
  1px solid rgba(120,120,120,.12);

  color:#0094ff;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-franco:hover{
  transform:rotate(90deg);

  background:
  rgba(120,120,120,.18);

  border-color:
  rgba(120,120,120,.35);

  color:#ff4fa8;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-franco{
    grid-template-columns:1fr;
  }

  .overlay-francoo h3{
    font-size:20px;
  }

  .fechar-franco{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

