.slider-perez{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-perez{
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-perez::after{
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO */
.slider-perez-container,
.titulo-perez-slider,
.dots-perez,
.btn-perez{
  position: relative;
  z-index: 2;
}

.titulo-perez-slider{
  font-size: 40px;
  color: #C0C0C0;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-perez-container{
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-perez-track{
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-perez{
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-perez img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-perez-texto{
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-perez-texto h3{
  color: #C0C0C0;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-perez-texto p{
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-perez{
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(10,35,66,0.7);
  border: none;
  color: #FFFFFF;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev{
  left: 15px;
}

.next{
  right: 15px;
}

.btn-perez:hover{
  background: #C0C0C0;
  color:#0A2342;
}

/* BOLINHAS */
.dots-perez{
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-perez{
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(192,192,192,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-perez:hover{
  background: #C0C0C0;
}

.dot-perez.active{
  background: #C0C0C0;
  transform: scale(1.3);
}

.dots-perez{
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}

/* RESPONSIVO */
@media(max-width: 768px){

  .slide-perez img{
    height: 300px;
  }

  .slide-perez-texto h3{
    font-size: 20px;
  }

  .slide-perez-texto p{
    font-size: 14px;
  }

}

.numeros-perez{
