  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(192,192,192,0.35);
}

/* ===== CARD GRANDE ===== */
.grande-perez{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-perez{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #0a2342,
    #c0c0c0
  );

  box-shadow:0 0 10px #c0c0c0;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-perez{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #c0c0c0,
    transparent 70%
  );

  animation:pulsarperez 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsarperez{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-perez{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

