  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.perez-team-change{
  position:relative;

  border:1px solid rgba(255,255,255,.45);

  box-shadow:
    0 0 20px rgba(255,255,255,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-perez{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Ddd48c,
      #Ddd48c
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferperez .5s ease;
}


@keyframes transferperez{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.perez-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,255,255,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.perez-corrida-card:hover::before{
  opacity:1;
}


.perez-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,255,255,0.25);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.6);
}


/* =========================================================
   GP
========================================================= */

.perez-gp{
  display:block;

  color:#bdbdbd;

  font-size:14px;

  margin-bottom:5px;

  letter-spacing:.5px;
}


/* =========================================================
   RESULTADO
========================================================= */

.perez-resultado{
  font-size:clamp(25px,3vw,42px);

  font-weight:900;

  color:white;

  letter-spacing:1px;
}


/* =========================================================
   CORES
========================================================= */

.perez-vitoria .perez-resultado{

  color:#ffd54a;

  text-shadow:
    0 0 15px rgba(255,255,255,0.25);

}


.perez-podio .perez-resultado{

  color: #Ddd48c ;

  text-shadow:
    0 0 10px rgba(255,255,255,0.2);

}


.perez-pontos .perez-resultado{

  color:#ffffff;

}


.perez-dnf .perez-resultado{

  color:#ff4d4d;

  text-shadow:
    0 0 10px rgba(255,77,77,0.25);

}


.perez-sem-pontos .perez-resultado{

  color:#777;

  opacity:.7;

}


/* =========================================================
   PONTOS
========================================================= */

.perez-pontos-texto{

  display:block;

  margin-top:5px;

  font-size:13px;

  font-weight:700;

  color:#Ddd48c;

