    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-perez span {
    color: #6e6a00;
}


.pilotagem-intro-perez {
