    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-perez {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-perez {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-perez::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255,255,255, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-perez {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-perez {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-perez:hover
.perfil-imagem-perez {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-perez::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-perez {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

    margin-top: auto;

    background:
        linear-gradient(
            to top,
            #090909 55%,
            transparent
        );
}


.perfil-numero-perez {
    display: block;

    margin-bottom: 8px;

    color: #6e6a00;

    font-size: 96px;

    font-weight: 900;

    letter-spacing: 3px;
}


.perfil-nome-perez {
    margin: 0;

    font-size:
        clamp(
            40px,
            4vw,
            65px
        );

    line-height: .8;

    font-weight: 900;

    letter-spacing: -3px;
}


.perfil-nome-perez span {
    display: block;

    color: #6e6a00;
}


.perfil-equipe-perez {
    margin:
        15px 0
        20px;

    color: #aaa;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;
}


/* FRASE */

.perfil-frase-perez {
    display: flex;

    gap: 10px;

    align-items: flex-start;

    padding-top: 15px;

    border-top:
        1px solid
        rgba(255,255,255,.10);
}


.perfil-frase-perez i {
    color: #6e6a00;

    font-size: 20px;
}


.perfil-frase-perez p {
    margin: 0;

    color: #ddd;

    font-size: 18px;

    font-style: italic;

    line-height: 1.5;
}


/* =========================================================
   ANÁLISE
========================================================= */

.pilotagem-analise-perez {
    padding:
        50px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #121212,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255,.08);

    display: flex;

    flex-direction: column;

    justify-content: center;
}


.analise-label-perez {
    display: block;

    margin-bottom: 12px;

    color: #6e6a00;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;
}


.analise-topo-perez h3 {
    margin:
        0
        0
        30px;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.analise-topo-perez h3 span {
    display: block;

    color: #6e6a00;
}


.pilotagem-analise-perez > p {
    margin:
        0
        0
        18px;

    color: #b9b9b9;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   CARACTERÍSTICAS
========================================================= */

.caracteristicas-perez {
    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 15px;

    margin-top: 25px;
}


.caracteristica-perez {
    padding: 20px;

    border-radius: 15px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease,
        background .3s ease;
}


.caracteristica-perez:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(255,255,255,.5);

    background:
        rgba(255,255,255,.06);
}


.caracteristica-icone-perez {
    width: 52px;
    height: 52px;

    margin-bottom: 15px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,255,255,.10);

    color: #6e6a00;
}

.caracteristica-icone-perez i{
	font-size: 40px;

	}



.caracteristica-perez h4 {
    margin:
        0
        0
        7px;

    font-size: 15px;

    letter-spacing: 1px;
}


.caracteristica-perez p {
    margin: 0;

    color: #999;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HABILIDADES
========================================================= */

.pilotagem-skills-section-perez {
    max-width: 1300px;

    margin:
        90px auto
        0;
}


.skills-header-perez {
    margin-bottom: 35px;
}


.skills-header-perez > span {
    display: block;

    margin-bottom: 10px;

    color: #6e6a00;

    font-size: 40px;

    font-weight: 800;

    letter-spacing: 2px;
}


.skills-header-perez h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.skills-header-perez h3 span {
    color: #6e6a00;
}


/* GRID */

.skills-grid-perez {
    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 15px;
}


.skill-card-perez {
    padding: 22px;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #111,
            #0b0b0b
        );

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease,
        border-color .3s ease;
}


.skill-card-perez:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(255,255,255,.35);
}


.skill-topo-perez {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.skill-nome-perez {
    display: flex;

    align-items: center;

    gap: 10px;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;
}


.skill-nome-perez i {
    color: #6e6a00;

    font-size: 26px;
}


.skill-numero-perez {
    color: #6e6a00;

    font-size: 24px;

    font-weight: 900;
}


.skill-numero-perez::after {
    content: "%";

    margin-left: 2px;

    font-size: 22px;
}


/* BARRA */

.skill-barra-perez {
    width: 100%;
    height: 8px;

    overflow: hidden;

    border-radius: 20px;

    background:
        rgba(255,255,255,.08);
}


.skill-progresso-perez {
    width: 0;

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #6e6a00,
            #ffffff
        );

    box-shadow:
        0 0 12px
        rgba(255,255,255,.5);

    transition:
        width 1.3s
        cubic-bezier(
            .2,
            .8,
            .2,
            1
        );
}


/* =========================================================
   GRÁFICO
========================================================= */

.pilotagem-grafico-section-perez {
    max-width: 1300px;

    margin:
        100px auto
        0;
}


.grafico-header-perez {
    margin-bottom: 35px;
}


.grafico-header-perez > span {
    display: block;

    margin-bottom: 10px;

    color: #6e6a00;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-perez h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-perez h3 span {
    color: #6e6a00;
}


.grafico-layout-perez {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-perez {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-perez {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-perez {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-perez {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-perez {
    fill:
        rgba(255,255,255,.20);

    stroke: #6e6a00;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,255,255,.35)
        );
}


.radar-ponto-perez {
    fill: #6e6a00;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-perez {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-perez {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-perez {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-perez {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-perez {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-perez {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-perez {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-perez {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-perez {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-perez:hover {
    transform:
        translateX(6px);
}


.resumo-icone-perez {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,255,255,.10);

    color: #6e6a00;

    font-size: 18px;
}


.resumo-card-perez > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-perez h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-perez p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-perez {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,255,255,.12),
            rgba(255,255,255,.02)
        );

    border:
        1px solid
        rgba(255,255,255,.25);
}


.pilotagem-conclusao-perez::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,255,255,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-perez > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-perez > span {
    display: block;

    margin-bottom: 18px;

    color: #6e6a00;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-perez h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-perez strong {
    color: #6e6a00;
}


.pilotagem-conclusao-perez p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-perez {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-perez.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-perez {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-perez {
        min-height: 600px;
    }


    .grafico-layout-perez {
        grid-template-columns: 1fr;

        gap: 60px;
    }


    .radar-container-perez {
        max-width: 430px;
    }


    .caracteristicas-perez {
        grid-template-columns:
            repeat(3, 1fr);
    }

}


/* =========================================================
   CELULAR
========================================================= */

@media (max-width: 700px) {

.pilotagem-perez{
        padding:
            70px
            15px;
    }  


    .pilotagem-header-perez {
        margin-bottom: 45px;
    }


    .titulo-pilotagem-perez {
        font-size: 42px;

        letter-spacing: -2px;
    }


    /* PERFIL */

    .pilotagem-perfil-perez {
        min-height: 500px;

        border-radius: 20px;
    }


    .perfil-info-perez {
        padding:
            25px
            20px;
    }


    .perfil-nome-perez {
        font-size: 45px;
    }


    /* ANÁLISE */

    .pilotagem-analise-perez {
        padding:
            30px
            20px;

        border-radius: 20px;
    }


    .analise-topo-perez h3 {
        font-size: 38px;
    }


    .pilotagem-analise-perez > p {
        font-size: 14px;

        line-height: 1.7;
    }


    /* CARACTERÍSTICAS */

    .caracteristicas-perez {
        grid-template-columns: 1fr;

        gap: 10px;
    }


    .caracteristica-perez {
        display: flex;

        align-items: center;

        gap: 15px;

        padding: 15px;
    }


    .caracteristica-icone-perez {
        flex-shrink: 0;

        margin: 0;
    }


    /* SKILLS */

    .pilotagem-skills-section-perez {
        margin-top: 70px;
    }


    .skills-grid-perez {
        grid-template-columns: 1fr;
    }


    .skill-card-perez {
        padding: 18px;
    }


    /* GRÁFICO */

    .pilotagem-grafico-section-perez {
        margin-top: 70px;
    }


    .grafico-layout-perez {
        padding:
            45px
            10px
            30px;

        border-radius: 20px;
    }


    .radar-container-perez {
        width: 80%;
    }


    .radar-label-perez {
        font-size: 7px;
    }


    .radar-top-right-perez {
        right: -28px;
    }


    .radar-bottom-right-perez {
        right: -35px;
    }


    .radar-bottom-left-perez {
        left: -35px;
    }


    .radar-top-left-perez {
        left: -25px;
    }


    /* RESUMO */

    .grafico-resumo-perez {
        padding: 0 10px;
    }


    .resumo-card-perez {
        gap: 12px;

        padding: 18px;
    }


    .resumo-card-perez h4 {
        font-size: 15px;
    }


    /* CONCLUSÃO */

    .pilotagem-conclusao-perez {
        margin-top: 70px;

        padding:
            40px
            20px;

        border-radius: 20px;
    }


    .pilotagem-conclusao-perez h3 {
        font-size: 30px;
    }


    .pilotagem-conclusao-perez p {
        font-size: 13px;
    }

}


/* =========================================================
   TELAS MUITO PEQUENAS
========================================================= */

@media (max-width: 400px) {

    .titulo-pilotagem-perez {
        font-size: 36px;
    }


    .pilotagem-perfil-perez {
        min-height: 450px;
    }


    .perfil-nome-perez {
        font-size: 38px;
    }


    .analise-topo-perez h3 {
        font-size: 32px;
    }


    .skill-nome-perez {
        font-size: 9px;
    }


    .radar-container-perez {
        width: 78%;
    }


    .radar-label-perez {
        font-size: 6px;
    }


    .resumo-card-perez p {
        font-size: 11px;
    }

}



