.galeria-perez{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(212,176,106,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-perez::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(212,176,106,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-perez{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(212,176,106,.18);
}

/* GRID */
.grid-galeria-perez{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-perez{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-perez img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-perez:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-checo{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-perez:hover .overlay-checo{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-checo h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA DECORATIVA */
.overlay-checo h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #d4b06a,
    #f3d9a2
  );

  box-shadow:
  0 0 18px rgba(212,176,106,.5);
}

/* DESCRIÇÃO */
.overlay-checo p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-perez::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(212,176,106,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-perez:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-perez{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightbox .3s ease;
}

/* ANIMAÇÃO */
@keyframes fadeLightbox{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-perez{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightbox .35s ease;
}

@keyframes zoomLightbox{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-perez{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-perez:hover{
  transform:rotate(90deg);

  background:
  rgba(212,176,106,.18);

  border-color:
  rgba(212,176,106,.35);

  color:#d4b06a;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-perez{
    grid-template-columns:1fr;
  }

  .overlay-checo h3{
    font-size:20px;
  }

  .fechar-perez{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

