.slider-bottas{
  position: relative;
  overflow: hidden;
  width:100%;
  min-height: auto;
  padding-bottom: 40px;
}

/* BACKGROUND DINÂMICO */
.bg-slider-bottas{
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  background-size: cover;
  background-position: center;

  filter: blur(40px) brightness(0.4);
  transform: scale(1.2);

  transition: 0.8s ease;

  z-index: 0;
}

/* ESCURECER MAIS */
.bg-slider-bottas::after{
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(0,0,0,0.6);
}

/* CONTEÚDO */
.slider-bottas-container,
.titulo-bottas-slider,
.dots-bottas,
.btn-bottas{
  position: relative;
  z-index: 2;
}

.titulo-bottas-slider{
  font-size: 40px;
  color: #C0C0C0;
  margin-bottom: 40px;
}

/* CONTAINER */
.slider-bottas-container{
  position: relative;
  max-width: 1300px;
  margin: auto;
  overflow: hidden;
  border-radius: 20px;

  touch-action: pan-y;
}

/* TRACK */
.slider-bottas-track{
  display: flex;
  transition: transform 0.5s ease;
}

/* SLIDE */
.slide-bottas{
  min-width: 100%;
  position: relative;
}

/* IMAGEM */
.slide-bottas img{
  width:100%;
  height:clamp(320px, 65vw, 800px);

  object-fit:cover;
  object-position:center top;
  display:block;
}

/* TEXTO */
.slide-bottas-texto{
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;

  padding: 25px;

  background: linear-gradient(transparent, rgba(0,0,0,0.95));
  text-align: left;
}

.slide-bottas-texto h3{
  color: #C0C0C0;
  font-size: 56px;
  margin-bottom: 5px;
}

.slide-bottas-texto p{
  color: #ddd;
  font-size: 36px;
  line-height: 1.5;
}

/* BOTÕES */
.btn-bottas{
  position: absolute;
  top: 50%;
  transform: translateY(-50%);

  background: rgba(10,35,66,0.7);
  border: none;
  color: #FFFFFF;

  font-size: 30px;
  width: 45px;
  height: 45px;

  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
}

.prev{
  left: 15px;
}

.next{
  right: 15px;
}

.btn-bottas:hover{
  background: #C0C0C0;
  color:#0A2342;
}

/* BOLINHAS */
.dots-bottas{
  position: absolute;
  bottom: 15px;
  left: 50%;

  transform: translateX(-50%);

  display: flex;
  gap: 10px;

  z-index: 3;
}

.dot-bottas{
  width: 10px;
  height: 10px;

  border-radius: 50%;
  background: rgba(192,192,192,0.3);

  cursor: pointer;
  transition: 0.3s;
}

.dot-bottas:hover{
  background: #C0C0C0;
}

.dot-bottas.active{
  background: #C0C0C0;
  transform: scale(1.3);
}

.dots-bottas{
  display: flex;
  justify-content: center;
  gap: 10px;

  margin-top: 20px;
}

/* RESPONSIVO */
@media(max-width: 768px){

  .slide-bottas img{
    height: 300px;
  }

  .slide-bottas-texto h3{
    font-size: 20px;
  }

  .slide-bottas-texto p{
    font-size: 14px;
  }

}

.numeros-bottas{
  background: linear-gradient(
    120deg,
    #050505 0%,
    #0a2342 45%,
    #163b66 75%,
    #c0c0c0 100%
  );

  position: relative;
  min-height: 650px;
  padding: 80px 0;
  overflow: hidden;
}

.numeros-bottas::after{
  content:"";
  position:absolute;
  inset:0;

  background: radial-gradient(
    circle at center,
    transparent 40%,
    rgba(0,0,0,0.88) 100%
  );

  z-index:1;
}

.bg-numeros-bottas{
  position:absolute;
  top:0;
  left:0;

  width:100%;
  height:100%;

  object-fit:cover;

  filter: blur(3px) brightness(0.55);

  z-index:0;
}

.overlay-numeros-bottas{
  position:absolute;
  inset:0;
  z-index:1;
}

/* ===== TÍTULO ===== */
.titulo-numeros-bottas{
  position:relative;
  z-index:2;

  text-align:center;

  color:#c0c0c0;
  font-size:44px;

  margin-bottom:40px;

  text-shadow:0 0 15px rgba(192,192,192,0.5);
}

/* ===== GRID ===== */
.stats-grid-bottas{
  position:relative;
  z-index:2;

  display:grid;
  grid-template-columns:repeat(3,1fr);

  gap:25px;

  padding:0 40px;
}

/* ===== CARD ===== */
.card-stat-bottas{
  background:rgba(0,0,0,0.68);

  backdrop-filter:blur(10px);

  border-radius:18px;

  padding:clamp(18px,3vw,30px);

  text-align:center;
  color:white;

  border:1px solid #c0c0c0;

  box-shadow:0 10px 30px rgba(0,0,0,0.65);

  opacity:0;
  transform:translateY(60px);

  transition:0.6s ease;
}

.card-stat-bottas.ativo{
  opacity:1;
  transform:translateY(0);

  animation:glowbottas 2s infinite alternate;
}

/* ===== GLOW ===== */
@keyframes glowbottas{

  from{
    box-shadow:0 0 10px #0a2342;
  }

  to{
    box-shadow:0 0 30px #c0c0c0;
  }

}

/* ===== NÚMERO ===== */
.card-stat-bottas span{
  display:block;

  font-size:clamp(32px,5vw,60px);
  font-weight:bold;

  color:#c0c0c0;

  text-shadow:0 0 10px rgba(0,0,0,0.9);
}

/* ===== TEXTO ===== */
.card-stat-bottas p{
  margin-top:10px;

  font-size:18px;

  color:#e5e5e5;
}

/* ===== HOVER ===== */
.card-stat-bottas:hover{
  transform:translateY(-8px) scale(1.02);

  box-shadow:0 0 40px rgba(192,192,192,0.35);
}

/* ===== CARD GRANDE ===== */
.grande-bottas{
  grid-column:span 3;
}

/* ===== BARRA ===== */
.barra-velocidade-bottas{
  width:0%;
  height:6px;

  margin-top:10px;

  border-radius:10px;

  background:linear-gradient(
    90deg,
    #0a2342,
    #c0c0c0
  );

  box-shadow:0 0 10px #c0c0c0;

  transition:width 0.3s;
}

/* ===== LUZ ===== */
.luz-bottas{
  position:absolute;

  width:600px;
  height:600px;

  top:-200px;
  right:-200px;

  z-index:1;

  opacity:0.18;

  background:radial-gradient(
    circle,
    #c0c0c0,
    transparent 70%
  );

  animation:pulsarbottas 4s infinite alternate;
}

/* ===== ANIMAÇÃO ===== */
@keyframes pulsarbottas{

  from{
    transform:scale(1);
  }

  to{
    transform:scale(1.3);
  }

}

/* ===== MOBILE ===== */
@media (max-width:768px){

  .stats-grid-bottas{
    grid-template-columns:1fr;

    padding:0 15px;

    gap:15px;
  }

  .grande-bottas{
    grid-column:span 1;
  }

  .titulo-numeros-bottas{
    font-size:32px;
  }
}

/* =========================================================
   bottas — TIMELINE
========================================================= */

.bottas-timeline{
  width:100%;
  height:100dvh;
  min-height:100dvh;

  box-sizing:border-box;

  padding:35px 20px;

  display:flex;
  flex-direction:column;

  overflow:hidden;

  background:
  radial-gradient(
    circle at top,
    rgba(255,255,255,0.08),
    transparent 60%
  ),
  linear-gradient(
    180deg,
    #07090c 0%,
    #0f1116 100%
  );
}


/* =========================================================
   HEADER
========================================================= */

.bottas-top-timeline{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:25px;

  flex-shrink:0;
}


.bottas-timeline-title{
  color:#Ddd48c;

  font-size:clamp(30px,5vw,56px);

  font-weight:950;

  letter-spacing:1px;

  text-transform:uppercase;

  text-shadow:
    0 0 20px rgba(255,255,255,.15);
}


/* =========================================================
   BOTÕES
========================================================= */

.bottas-anos{
  display:flex;

  gap:10px;

  flex-wrap:wrap;

  justify-content:flex-end;
}


.bottas-ano-btn{
  padding:8px 14px;

  border:none;

  border-radius:999px;

  background:rgba(255,255,255,0.04);

  color:#ddd;

  cursor:pointer;

  font-weight:700;

  font-size:18px;

  transition:.25s ease;

  border:1px solid rgba(255,255,255,0.08);

  backdrop-filter:blur(10px);
}


.bottas-ano-btn:hover{
  background:rgba(255,255,255,0.15);

  color:#Ddd48c;

  transform:translateY(-2px);
}


.bottas-ano-btn.active{
  background:#ddd48c;

  color:#000;

  box-shadow:
    0 0 18px rgba(255,255,255,.35);
}


/* =========================================================
   GRID DAS CORRIDAS
========================================================= */

.bottas-corridas-container{
  flex:1;

  min-height:0;

  display:grid;

  grid-template-columns:
    repeat(auto-fit,minmax(150px,1fr));

  grid-auto-rows:1fr;

  gap:10px;

  width:100%;
}


/* =========================================================
   CARD
========================================================= */

.bottas-corrida-card{
  position:relative;

  display:flex;

  flex-direction:column;

  justify-content:space-between;

  min-height:0;

  padding:10px 12px;

  border-radius:10px;

  background:#0c0f14;

  overflow:hidden;

  border:1px solid rgba(255,255,255,0.05);

  transition:.35s ease;

  box-sizing:border-box;
}


/* =========================================================
   EQUIPE
========================================================= */

.bottas-team{
  display:flex;

  justify-content:flex-end;

  align-items:center;
}


.bottas-team-logo{
  width:48px;

  height:48px;

  object-fit:contain;
}


/* =========================================================
   MUDANÇA DE EQUIPE
========================================================= */

.bottas-team-change{
  position:relative;

  border:1px solid rgba(255,255,255,.45);

  box-shadow:
    0 0 20px rgba(255,255,255,.18);

  transform:scale(1.02);
}


/* =========================================================
   TAG DE TRANSFERÊNCIA
========================================================= */

.transfer-tag-bottas{
  position:absolute;

  top:6px;

  right:6px;

  padding:4px 7px;

  border-radius:6px;

  font-size:9px;

  font-weight:800;

  background:
    linear-gradient(
      90deg,
      #Ddd48c,
      #Ddd48c
    );

  color:#000;

  letter-spacing:.5px;

  animation:
    transferbottas .5s ease;
}


@keyframes transferbottas{

  0%{
    opacity:0;

    transform:translateY(-6px);
  }

  100%{
    opacity:1;

    transform:translateY(0);
  }

}


/* =========================================================
   GLOW
========================================================= */

.bottas-corrida-card::before{
  content:"";

  position:absolute;

  inset:-2px;

  background:
    radial-gradient(
      circle at top left,
      rgba(255,255,255,0.08),
      transparent 60%
    );

  opacity:0;

  transition:.3s ease;

  pointer-events:none;
}


.bottas-corrida-card:hover::before{
  opacity:1;
}


.bottas-corrida-card:hover{
  transform:translateY(-4px);

  border-color:
    rgba(255,255,255,0.25);

  box-shadow:
