            #111111 100%
        );

    color: #fff;
}


/* =========================================================
   DETALHE LARANJA DE FUNDO
========================================================= */

.valtteri-season-2026::before {
    content: "";
    position: absolute;

    width: 450px;
    height: 450px;

    right: -180px;
    bottom: -180px;

    border-radius: 50%;

    background: rgba(255,255,255, 0.08);

    filter: blur(100px);

    pointer-events: none;
}


/* =========================================================
   CONTAINER
========================================================= */

.valtteri-season-2026-container {
    position: relative;
    z-index: 2;

    max-width: 1200px;

    margin: auto;

    display: grid;

    grid-template-columns: 350px 1fr;

    gap: 55px;

    align-items: center;
}


/* =========================================================
   IMAGEM
========================================================= */

.valtteri-season-2026-image {
    position: relative;

    height: 560px;

    overflow: hidden;

    border-radius: 20px;

    background: #111;

    border: 1px solid rgba(255,255,255,0.08);

    box-shadow:
        0 25px 70px rgba(0,0,0,0.55);
}


/* IMAGEM */

.valtteri-season-2026-image img {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center top;

    transition: transform 0.6s ease;
}

.valtteri-season-2026-image:hover img {
    transform: scale(1.04);
}


/* =========================================================
   OVERLAY DA IMAGEM
========================================================= */

.valtteri-season-2026-image-overlay {
    position: absolute;

    z-index: 2;

    inset: 0;

    background:
        linear-gradient(
            to top,
            rgba(0,0,0,0.85),
            rgba(0,0,0,0.05) 60%
        );

    pointer-events: none;
}


/* =========================================================
   NÚMERO #1
========================================================= */

.valtteri-season-2026-number {
    position: absolute;

    z-index: 3;

    left: 25px;
    bottom: 20px;

    font-size: 80px;

    line-height: 1;

    font-weight: 900;

    font-style: italic;

    color: #F0f0f0;

    text-shadow:
        0 5px 25px rgba(0,0,0,0.7);
}


/* =========================================================
   NOME DO PILOTO
========================================================= */

.valtteri-season-2026-driver-name {
    margin: 0 0 18px;

    font-size: clamp(35px, 4vw, 65px);

    line-height: 0.85;

    font-weight: 900;

    font-style: italic;

    letter-spacing: -3px;

    text-transform: uppercase;

    color: #fff;

    text-shadow:
        0 8px 30px rgba(0,0,0,0.45);
}


/* SOBRENOME EM DESTAQUE */

.valtteri-season-2026-driver-name strong {
    display: block;

    color: #F0f0f0;

    font-weight: 900;
}

/* =========================================================
   CONTEÚDO
========================================================= */

.valtteri-season-2026-content {
    width: 100%;
}


/* =========================================================
   TAG
========================================================= */

.valtteri-season-2026-tag {
    display: inline-block;

    margin-bottom: 14px;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 3px;

    text-transform: uppercase;

    color: #fff;
}


/* =========================================================
   TÍTULO
========================================================= */

.valtteri-season-2026-content h2 {
    margin: 0;

    font-size: clamp(38px, 4vw, 54px);

    line-height: 0.95;

    font-weight: 900;

    text-transform: uppercase;

    letter-spacing: -2px;
}

.valtteri-season-2026-content h2 strong {
    color: #F0f0f0;
}


/* =========================================================
   SUBTÍTULO
========================================================= */

.valtteri-season-2026-subtitle {
    margin: 18px 0 35px;

    color: #999;

    font-size: 15px;

    line-height: 1.6;
}


/* =========================================================
   CAMPEONATO
========================================================= */

.valtteri-season-2026-championship {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 28px;

    margin-bottom: 18px;

    border-radius: 16px;

    background:
        linear-gradient(
            120deg,
            rgba(255,255,255,0.13),
            rgba(255,255,255,0.035)
        );

    border: 1px solid rgba(255,255,255,0.22);

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.04);
}


/* INFO CAMPEONATO */

.valtteri-season-2026-championship-info {
    display: flex;

    flex-direction: column;

    gap: 8px;
}

.valtteri-season-2026-championship-info span {
    font-size: 16px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}

.valtteri-season-2026-championship-info strong {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   PONTOS
========================================================= */

.valtteri-season-2026-points {
    display: flex;

    flex-direction: column;

    align-items: flex-end;
}

.valtteri-season-2026-points span {
    font-size: 42px;

    line-height: 1;

    font-weight: 900;

    color: #F0f0f0;
}

.valtteri-season-2026-points small {
    margin-top: 7px;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 2px;

    color: #999;
}


/* =========================================================
   GRID
========================================================= */

.valtteri-season-2026-stats {
    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 12px;
}


/* =========================================================
   CARD DE ESTATÍSTICA
========================================================= */

.valtteri-season-2026-stat {
    position: relative;

    min-height: 125px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    overflow: hidden;

    border-radius: 14px;

    background:
        linear-gradient(
            145deg,
            rgba(255,255,255,0.065),
            rgba(255,255,255,0.025)
        );

    border: 1px solid rgba(255,255,255,0.07);

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        background 0.3s ease;
}

.valtteri-season-2026-stat:hover {
    transform: translateY(-5px);

    border-color: rgba(255,255,255,0.4);

    background:
        linear-gradient(
            145deg,
            rgba(255,255,255,0.11),
            rgba(255,255,255,0.035)
        );
}


/* =========================================================
   BARRA LATERAL
========================================================= */

.valtteri-season-2026-stat::before {
    content: "";

    position: absolute;

    left: 0;
    top: 0;

    width: 3px;
    height: 100%;

    background: #F0f0f0;

    transform: scaleY(0);

    transform-origin: bottom;

    transition: transform 0.3s ease;
}

.valtteri-season-2026-stat:hover::before {
    transform: scaleY(1);
}


/* =========================================================
   ÍCONE
========================================================= */

.valtteri-season-2026-stat-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(255,255,255,0.1);

    font-size: 18px;
}


/* =========================================================
   INFORMAÇÕES
========================================================= */

.valtteri-season-2026-stat-info {
    display: flex;

    flex-direction: column;

    min-width: 0;
}

.valtteri-season-2026-stat-info span {
    font-size: 30px;

    line-height: 1;

    font-weight: 900;

    color: #fff;

    white-space: nowrap;
}

.valtteri-season-2026-stat-info p {
    margin: 7px 0 0;

    font-size: 16px;

    font-weight: 800;

    letter-spacing: 1px;

    text-transform: uppercase;

    color: #999;
}


/* =========================================================
   RESUMO
========================================================= */

.valtteri-season-2026-summary {
    display: grid;

    grid-template-columns: repeat(3, 1fr);

    margin-top: 14px;

    border-radius: 14px;

    overflow: hidden;

    border: 1px solid rgba(255,255,255,0.07);

    background: rgba(255,255,255,0.035);
}


/* ITEM */

.valtteri-season-2026-summary-item {
    padding: 22px;

    display: flex;

    flex-direction: column;

    gap: 9px;

    border-right: 1px solid rgba(255,255,255,0.07);
}

.valtteri-season-2026-summary-item:last-child {
    border-right: none;
}


/* TEXTO */

.valtteri-season-2026-summary-item span {
    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1.5px;

    color: #888;
}


/* VALOR */

.valtteri-season-2026-summary-item strong {
    font-size: 25px;

    font-weight: 900;

    color: #fff;
}


/* =========================================================
   RESPONSIVO — TABLET
========================================================= */

@media (max-width: 1000px) {

    .valtteri-season-2026-container {
        grid-template-columns: 280px 1fr;

        gap: 35px;
    }

    .valtteri-season-2026-image {
        height: 500px;
    }

    .valtteri-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .valtteri-season-2026-stat {
        min-height: 110px;
    }
}


/* =========================================================
   RESPONSIVO — CELULAR
========================================================= */

@media (max-width: 700px) {

    .valtteri-season-2026 {
        padding: 70px 15px;
    }

    .valtteri-season-2026-container {
        display: flex;

        flex-direction: column;

        gap: 35px;
    }

    .valtteri-season-2026-image {
        width: 100%;

        height: 390px;
    }

    .valtteri-season-2026-number {
        font-size: 65px;
    }

    .valtteri-season-2026-content h2 {
        font-size: 42px;
    }

    .valtteri-season-2026-championship {
        padding: 20px;
    }

    .valtteri-season-2026-championship-info strong,
    .valtteri-season-2026-points span {
        font-size: 34px;
    }

    .valtteri-season-2026-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .valtteri-season-2026-stat {
        padding: 16px;

        min-height: 110px;
    }

    .valtteri-season-2026-stat-icon {
        width: 36px;
        height: 36px;

        font-size: 15px;
    }

    .valtteri-season-2026-stat-info span {
        font-size: 26px;
    }

    .valtteri-season-2026-summary {
        grid-template-columns: 1fr;
    }

    .valtteri-season-2026-summary-item {
        border-right: none;

        border-bottom: 1px solid rgba(255,255,255,0.07);
    }

    .valtteri-season-2026-summary-item:last-child {
        border-bottom: none;
    }
}


/* =========================================================
   CELULAR PEQUENO
========================================================= */

@media (max-width: 400px) {

    .valtteri-season-2026-content h2 {
        font-size: 35px;
    }

    .valtteri-season-2026-stats {
        grid-template-columns: 1fr;
    }

    .valtteri-season-2026-stat {
        min-height: 100px;
    }

    .valtteri-season-2026-championship {
        padding: 18px;
    }

    .valtteri-season-2026-championship-info strong,
    .valtteri-season-2026-points span {
        font-size: 30px;
    }
}




/* =========================================================
   ESTILO DE PILOTAGEM — OSCAR bottas
========================================================= */

.pilotagem-bottas {
    position: relative;

    width: 100%;
    padding: 110px 5%;

    box-sizing: border-box;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 20%,
            rgba(255,255,255, .10),
            transparent 25%
        ),
        radial-gradient(
            circle at 90% 70%,
            rgba(255,255,255, .06),
            transparent 30%
        ),
        linear-gradient(
            180deg,
            #050505 0%,
            #0a0a0a 50%,
            #050505 100%
        );

    font-family: 'Inter', sans-serif;
    color: #fff;
}


/* =========================================================
   CABEÇALHO
========================================================= */

.pilotagem-header-bottas {
    position: relative;

    max-width: 900px;

    margin:
        -80px auto
        10px;

    text-align: center;

    z-index: 2;
}


.pilotagem-tag-bottas {
    display: inline-flex;

    padding:
        8px
        16px;

    margin-bottom: 18px;

    border-radius: 50px;

    background:
        rgba(255,255,255, .10);

    border:
        1px solid
        rgba(255,255,255, .35);

    color: #6e6a00;

    font-size: 25px;

    font-weight: 600;

    letter-spacing: 2px;
}


.titulo-pilotagem-bottas {
    margin: 0;

    font-size:
        clamp(
            62px,
            6vw,
            80px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -3px;
}


.titulo-pilotagem-bottas span {
    color: #6e6a00;
}


.pilotagem-intro-bottas {
    max-width: 600px;

    margin:
        25px auto 0;

    color: #a9a9a9;

    font-size:
        clamp(
            14px,
            1.3vw,
            18px
        );

    line-height: 1.7;
}


/* =========================================================
   CARD PRINCIPAL
========================================================= */

.pilotagem-card-principal-bottas {
    position: relative;

    max-width: 1300px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(320px, .8fr)
        minmax(0, 1.2fr);

    gap: 30px;
}


/* =========================================================
   PERFIL DO PILOTO
========================================================= */

.pilotagem-perfil-bottas {
    position: relative;

    min-height: 580px;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            145deg,
            #151515,
            #090909
        );

    border:
        1px solid
        rgba(255,255,255, .25);

    display: flex;

    flex-direction: column;

    justify-content: flex-end;
}


/* BRILHO */

.pilotagem-perfil-bottas::before {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    top: -120px;
    left: -120px;

    border-radius: 50%;

    background:
        rgba(255,255,255, .14);

    filter: blur(70px);

    pointer-events: none;
}


/* IMAGEM */

.perfil-imagem-container-bottas {
    position: absolute;

    inset: 0;

    z-index: 1;

    display: flex;

    align-items: flex-start;
    justify-content: center;

    overflow: hidden;
}


.perfil-imagem-bottas {
    width: 100%;
    height: 100%;

    object-fit: contain;

    object-position:
        center top;

    filter:
        drop-shadow(
            0 25px 35px
            rgba(0, 0, 0, .75)
        );

    transition:
        transform .5s ease;
}


.pilotagem-perfil-bottas:hover
.perfil-imagem-bottas {
    transform:
        scale(1.03);
}


/* GRADIENTE EM CIMA DA FOTO */

.perfil-imagem-container-bottas::after {
    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            to bottom,
            transparent 25%,
            rgba(5,5,5,.25) 55%,
            #090909 100%
        );

    pointer-events: none;
}


/* =========================================================
   INFORMAÇÕES DO PILOTO
========================================================= */

.perfil-info-bottas {
    position: relative;

    z-index: 3;

    padding:
        40px
        35px;

