    margin:
        100px auto
        0;
}


.grafico-header-bottas {
    margin-bottom: 35px;
}


.grafico-header-bottas > span {
    display: block;

    margin-bottom: 10px;

    color: #6e6a00;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;
}


.grafico-header-bottas h3 {
    margin: 0;

    font-size:
        clamp(
            30px,
            4vw,
            58px
        );

    line-height: .9;

    font-weight: 900;

    letter-spacing: -2px;
}


.grafico-header-bottas h3 span {
    color: #6e6a00;
}


.grafico-layout-bottas {
    display: grid;

    grid-template-columns:
        minmax(400px, .9fr)
        minmax(350px, 1.1fr);

    gap: 50px;

    align-items: center;

    padding: 45px;

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            #111,
            #080808
        );

    border:
        1px solid
        rgba(255,255,255,.08);
}


/* =========================================================
   RADAR
========================================================= */

.radar-container-bottas {
    position: relative;

    width: 100%;
    max-width: 500px;

    margin: auto;

    aspect-ratio: 1;
}


.radar-bottas {
    width: 100%;
    height: 100%;

    overflow: visible;
}


.radar-linha-bottas {
    fill: none;

    stroke:
        rgba(255,255,255,.10);

    stroke-width: 1;
}


.radar-eixo-bottas {
    stroke:
        rgba(255,255,255,.12);

    stroke-width: 1;
}


.radar-area-bottas {
    fill:
        rgba(255,255,255,.20);

    stroke: #6e6a00;

    stroke-width: 3;

    stroke-linejoin: round;

    filter:
        drop-shadow(
            0 0 10px
            rgba(255,255,255,.35)
        );
}


.radar-ponto-bottas {
    fill: #6e6a00;

    stroke: #111;

    stroke-width: 3;
}


/* LABELS */

.radar-label-bottas {
    position: absolute;

    color: #ddd;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1px;

    pointer-events: none;
}


.radar-top-bottas {
    top: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-top-right-bottas {
    top: 16%;
    right: -30px;
}


.radar-bottom-right-bottas {
    bottom: 18%;
    right: -45px;
}


.radar-bottom-bottas {
    bottom: -20px;
    left: 50%;

    transform:
        translateX(-50%);
}


.radar-bottom-left-bottas {
    bottom: 18%;
    left: -40px;
}


.radar-top-left-bottas {
    top: 16%;
    left: -30px;
}


/* =========================================================
   RESUMO
========================================================= */

.grafico-resumo-bottas {
    display: flex;

    flex-direction: column;

    gap: 15px;
}


.resumo-card-bottas {
    display: flex;

    gap: 20px;

    padding: 25px;

    border-radius: 18px;

    background:
        rgba(255,255,255,.035);

    border:
        1px solid
        rgba(255,255,255,.07);

    transition:
        transform .3s ease;
}


.resumo-card-bottas:hover {
    transform:
        translateX(6px);
}


.resumo-icone-bottas {
    flex-shrink: 0;

    width: 46px;
    height: 46px;

    border-radius: 12px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(255,255,255,.10);

    color: #6e6a00;

    font-size: 18px;
}


.resumo-card-bottas > div:last-child > span {
    display: block;

    margin-bottom: 6px;

    color: #888;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.resumo-card-bottas h4 {
    margin:
        0
        0
        8px;

    color: #fff;

    font-size: 18px;
}


.resumo-card-bottas p {
    margin: 0;

    color: #aaa;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   CONCLUSÃO
========================================================= */

.pilotagem-conclusao-bottas {
    position: relative;

    max-width: 1000px;

    margin:
        100px auto
        0;

    padding:
        60px
        50px;

    text-align: center;

    border-radius: 25px;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            rgba(255,255,255,.12),
            rgba(255,255,255,.02)
        );

    border:
        1px solid
        rgba(255,255,255,.25);
}


.pilotagem-conclusao-bottas::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -150px;
    left: -150px;

    border-radius: 50%;

    background:
        rgba(255,255,255,.10);

    filter: blur(60px);
}


.pilotagem-conclusao-bottas > * {
    position: relative;

    z-index: 1;
}


.pilotagem-conclusao-bottas > span {
    display: block;

    margin-bottom: 18px;

    color: #6e6a00;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 2px;
}


.pilotagem-conclusao-bottas h3 {
    max-width: 800px;

    margin:
        0 auto
        25px;

    font-size:
        clamp(
            28px,
            4vw,
            55px
        );

    line-height: 1;

    font-weight: 900;

    letter-spacing: -2px;
}


.pilotagem-conclusao-bottas strong {
    color: #6e6a00;
}


.pilotagem-conclusao-bottas p {
    max-width: 700px;

    margin: auto;

    color: #bbb;

    font-size: 15px;

    line-height: 1.8;
}


/* =========================================================
   REVEAL
========================================================= */

.reveal-bottas {
    opacity: 0;

    transform:
        translateY(35px);

    transition:
        opacity .8s ease,
        transform .8s ease;
}


.reveal-bottas.active {
    opacity: 1;

    transform:
        translateY(0);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

    .pilotagem-card-principal-bottas {
        grid-template-columns: 1fr;
    }


    .pilotagem-perfil-bottas {
        min-height: 600px;
    }


    .grafico-layout-bottas {
