.radio-f1-bottas{
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background: black;
  padding: 80px 20px;
  overflow: hidden;
}

/* STATUS */
.radio-status-bottas{
  position: absolute;
  top: 15px;
  left: 20px;

  color: #d4b06a;
  font-size: 42px;
  letter-spacing: 2px;
}

.radio-status-bottas::before{
  content: "●";
  margin-right: 6px;
  animation: blink 1s infinite;
}

@keyframes blink{
  50%{opacity:0.3;}
}

/* INFO */
.race-info-bottas{
  position: absolute;
  top: 15px;
  right: 20px;

  display: flex;
  gap: 15px;

  font-size: 30px;
  color: white;
}

/* CARD */
.card-bottas{
  width: 280px;
  height: 420px;

  background: #0b0b0f;

  border-radius: 12px;
  border: 1px solid rgba(212,176,106,.3);

  position: relative;
  overflow: hidden;

  opacity: 0;
  transform: translateY(20px);
  transition: 0.4s ease;
}

/* GLOW */
.card-bottas::before{
  content: "";

  position: absolute;
  inset: -20px;

  background:
  radial-gradient(
    circle,
    rgba(212,176,106,.15),
    transparent
  );

  z-index: -1;
}

.card-bottas.ativo{
  opacity: 1;
  transform: translateY(0);
}

.card-bottas.saindo{
  opacity: 0;
  transform: translateY(20px);
}

/* ESQUERDA */
.left-bottas{
  position: absolute;
  left: 10px;
  top: 60px;
}

.number-bottas{
  font-size: 120px;
  color: #d4b06a;
}

/* DIREITA */
.right-bottas{
  position: absolute;
  top: 20px;
  right: 15px;
  text-align: right;
}

.right-bottas h1{
  color: #d4b06a;
  margin: 0;
}

.right-bottas h2{
  color: white;
  margin: 0;
}

.logo-bottas{
  width: 40px;
  margin-top: 10px;
}

/* WAVE */
.wave-bottas{
  position: absolute;
  top: 160px;
  left: 0;

  width: 100%;
  height: 50px;

  display: flex;
  align-items: flex-end;
}

.wave-bottas span{
  flex: 1;
  margin: 0 1px;

  height: 6px;

  background:
  linear-gradient(
    to top,
    #d4b06a,
    transparent
  );

  animation: wave infinite ease-in-out;
  animation-play-state: paused;

  animation-duration: calc(0.8s + (var(--i) * 0.02s));
  animation-delay: calc(var(--i) * 0.05s);
}

.card-bottas.falando .wave-bottas span{
  animation-play-state: running;
}

@keyframes wave{
  0%,100%{
    height: 6px;
    opacity: 0.3;
  }

  50%{
    height: 45px;
    opacity: 1;
  }
}

/* CONTEÚDO */
.content-bottas{
  position: absolute;
  bottom: 0;
  width: 100%;

  height: 0;
  overflow: hidden;

  transition: height 0.4s ease;
}

/* TEXTO */
.text-bottas{
  padding: 10px 15px;

  opacity: 0;
