    width: clamp(24px, 5vw, 40px);
    margin-top: 8px;
  }

  .wave-bottas{
    position: absolute;
    top: clamp(110px, 30vw, 160px);
    left: 0;

    width: 100%;
    height: clamp(30px, 8vw, 50px);

    display: flex;
    align-items: flex-end;
  }

  .wave-bottas span{
    flex: 1;
    margin: 0 1px;

    height: 6px;

    background:
    linear-gradient(
      to top,
      #d4b06a,
      transparent
    );

    animation: wave infinite ease-in-out;
    animation-play-state: paused;

    animation-duration: calc(0.8s + (var(--i) * 0.02s));
    animation-delay: calc(var(--i) * 0.05s);
  }

  .card-bottas.falando .wave-bottas span{
    animation-play-state: running;
  }

  .content-bottas{
    position: absolute;
    bottom: 0;
    width: 100%;

    transform: scaleY(0);
    transform-origin: bottom;

    transition: transform 0.4s ease;
  }

  .card-bottas.mostrar-texto .content-bottas{
    transform: scaleY(1);
  }

  .text-bottas{
    padding: 10px 15px;

    opacity: 0;
    transform: translateY(10px);

    transition: all 0.4s ease;
  }

  .card-bottas.mostrar-texto .text-bottas{
    opacity: 1;
    transform: translateY(0);
  }

  .eng-bottas{
    color: white;
    font-size: clamp(12px, 3vw, 20px);
  }

  .pil-bottas{
    color: #d4b06a;
    text-align: right;
    font-size: clamp(12px, 3vw, 20px);
  }
}

.galeria-bottas{
  position:relative;
  overflow:hidden;

  padding:120px 25px;

  background:
  radial-gradient(circle at top,
  rgba(212,176,106,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #050505 0%,
    #0b0b0b 100%
  );
}

/* BRILHO FUNDO */
.galeria-bottas::before{
  content:"";

  position:absolute;

  width:700px;
  height:700px;

  top:-250px;
  right:-200px;

  background:
  radial-gradient(circle,
  rgba(212,176,106,.10),
  transparent 70%);

  filter:blur(120px);

  pointer-events:none;
}

/* TITULO */
.titulo-galeria-bottas{
  position:relative;
  z-index:2;

  text-align:center;

  font-size:
  clamp(42px,6vw,78px);

  font-weight:1000;

  color:white;

  margin-bottom:70px;

  text-transform:uppercase;

  letter-spacing:-2px;

  text-shadow:
  0 0 25px rgba(212,176,106,.18);
}

/* GRID */
.grid-galeria-bottas{
  position:relative;
  z-index:2;

  display:grid;

  grid-template-columns:
  repeat(auto-fit,minmax(320px,1fr));

  gap:28px;
}

/* ITEM */
.item-galeria-bottas{
  position:relative;

  overflow:hidden;

  border-radius:24px;

  cursor:pointer;

  aspect-ratio:1/1;

  display:flex;
  align-items:flex-end;

  background:#111;

  transition:.4s ease;
}

/* IMG */
.item-galeria-bottas img{
  position:absolute;

  inset:0;

  width:100%;
  height:100%;

  object-fit:cover;

  transition:.6s ease;
}

/* HOVER */
.item-galeria-bottas:hover img{
  transform:scale(1.1);
  filter:brightness(.55);
}

/* OVERLAY */
.overlay-bot{
  position:absolute;

  left:0;
  bottom:0;
  width:100%;

  padding:28px 24px;

  background:
  linear-gradient(
    to top,
    rgba(0,0,0,.96) 0%,
    rgba(0,0,0,.72) 45%,
    rgba(0,0,0,.18) 75%,
    transparent 100%
  );

  backdrop-filter:blur(4px);

  z-index:5;

  transition:
  transform .4s ease,
  opacity .4s ease;
}

/* ANIMAÇÃO */
.item-galeria-bottas:hover .overlay-bot{
  transform:translateY(-4px);
}

/* TITULO */
.overlay-bot h3{
  color:#fff;

  font-size:28px;
  font-weight:900;

  margin-bottom:8px;

  letter-spacing:-1px;

  text-shadow:
  0 4px 20px rgba(0,0,0,.5);
}

/* LINHA DECORATIVA */
.overlay-bot h3::after{
  content:"";

  display:block;

  width:55px;
  height:4px;

  margin-top:10px;

  border-radius:999px;

  background:
  linear-gradient(
    90deg,
    #d4b06a,
    #f3d9a2
  );

  box-shadow:
  0 0 18px rgba(212,176,106,.5);
}

/* DESCRIÇÃO */
.overlay-bot p{
  margin-top:14px;

  color:#d8d8d8;

  font-size:15px;
  line-height:1.5;

  max-width:90%;

  text-shadow:
  0 2px 10px rgba(0,0,0,.4);
}

/* EFEITO EXTRA */
.item-galeria-bottas::after{
  content:"";

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    135deg,
    rgba(212,176,106,.10),
    transparent 45%
  );

  opacity:0;

  transition:.45s ease;

  z-index:1;
}

.item-galeria-bottas:hover::after{
  opacity:1;
}

/* LIGHTBOX */
.lightbox-bottas{
  position:fixed;
  inset:0;

  background:
  rgba(0,0,0,.94);

  display:none;

  justify-content:center;
  align-items:center;

  z-index:9999;

  backdrop-filter:blur(12px);

  animation:
  fadeLightbox .3s ease;
}

/* ANIMAÇÃO */
@keyframes fadeLightbox{

  from{
    opacity:0;
  }

  to{
    opacity:1;
  }

}

/* IMG LIGHTBOX */
.img-lightbox-bottas{
  max-width:88%;
  max-height:88%;

  object-fit:contain;

  border-radius:22px;

  box-shadow:
  0 25px 80px rgba(0,0,0,.8);

  animation:
  zoomLightbox .35s ease;
}

@keyframes zoomLightbox{

  from{
    transform:scale(.85);
    opacity:0;
  }

  to{
    transform:scale(1);
    opacity:1;
  }

}

/* FECHAR */
.fechar-bottas{
  position:absolute;

  top:28px;
  right:38px;

  width:60px;
  height:60px;

  display:flex;
  align-items:center;
  justify-content:center;

  border-radius:50%;

  background:
  rgba(255,255,255,.08);

  border:
  1px solid rgba(255,255,255,.12);

  color:white;

  font-size:34px;
  font-weight:300;

  cursor:pointer;

  z-index:10000;

  transition:.3s ease;
}

.fechar-bottas:hover{
  transform:rotate(90deg);

  background:
  rgba(212,176,106,.18);

  border-color:
  rgba(212,176,106,.35);

  color:#d4b06a;
}

/* RESPONSIVO */
@media(max-width:768px){

  .grid-galeria-bottas{
    grid-template-columns:1fr;
  }

  .overlay-bot h3{
    font-size:20px;
  }

  .fechar-bottas{
    top:20px;
    right:20px;

    width:52px;
    height:52px;

    font-size:28px;
  }

}

.footer-f1-bottas{
  position:relative;
  overflow:hidden;

  padding:80px 25px 35px;

  background:
  radial-gradient(circle at top,
  rgba(180,140,80,.08),
  transparent 35%),

  linear-gradient(
    180deg,
    #080808 0%,
    #050505 100%
  );

  border-top:
  1px solid rgba(255,255,255,.06);

  display:flex;
  flex-direction:column;
  gap:45px;

  text-align:center;
}

/* BRILHO */
.footer-f1-bottas::before{
  content:"";

  position:absolute;

  width:500px;
  height:500px;

  top:-250px;
  left:50%;

  transform:translateX(-50%);

  background:
  radial-gradient(circle,
  rgba(180,140,80,.12),
  transparent 70%);

  filter:blur(100px);

  pointer-events:none;
}

/* CONTEÚDO */
.footer-f1-bottas > *{
  position:relative;
  z-index:2;
}

/* BRAND */
.footer-brand-bottas p{
  font-size:
  clamp(34px,5vw,58px);

  font-weight:1000;

  color:white;

  margin-bottom:10px;

  letter-spacing:-2px;

  text-transform:uppercase;

  text-shadow:
  0 0 25px rgba(180,140,80,.2);
}

.footer-brand-bottas span{
  display:block;

  color:#a5a5a5;

  font-size:15px;

  max-width:600px;

  margin:auto;

  line-height:1.6;
}

/* LINKS */
.footer-links-bottas,
.footer-social-bottas{
  display:flex;
  justify-content:center;
  flex-wrap:wrap;

  gap:16px;
}

/* BOTÕES */
.footer-links-bottas a,
.footer-social-bottas a{
  position:relative;

  padding:12px 22px;

  border-radius:999px;

  text-decoration:none;

  color:#e6e6e6;

  background:
  rgba(255,255,255,.03);

  border:
  1px solid rgba(255,255,255,.06);

  font-size:14px;
  font-weight:700;

  transition:
  transform .3s ease,
  background .3s ease,
  border-color .3s ease,
  color .3s ease;
}

/* HOVER */
.footer-links-bottas a:hover,
.footer-social-bottas a:hover{
  transform:
  translateY(-4px);

  background:
  rgba(180,140,80,.12);

  border-color:
  rgba(180,140,80,.25);

  color:#d4b06a;

  box-shadow:
  0 10px 25px rgba(180,140,80,.12);
}

/* COPY */
.footer-copy-bottas{
  padding-top:15px;

  border-top:
  1px solid rgba(255,255,255,.05);

  color:#777;

  font-size:13px;

  letter-spacing:.5px;
}

/* MOBILE */
@media(max-width:768px){

  .footer-f1-bottas{
    gap:35px;
  }

  .footer-brand-bottas p{
    font-size:40px;
  }

  .footer-links-bottas,
  .footer-social-bottas{
    gap:12px;
  }

  .footer-links-bottas a,
  .footer-social-bottas a{
    width:100%;
    max-width:280px;
  }

}

/* BOTÃO TOPO */
.back-to-top-bottas{
  position:fixed;

  right:28px;
  bottom:28px;

  width:62px;
  height:62px;

  display:flex;
  align-items:center;
  justify-content:center;

  border:none;
  outline:none;

  border-radius:50%;

  cursor:pointer;

  background:
  linear-gradient(
    145deg,
    #d4b06a,
    #8f6a2f
  );

  color:white;

  font-size:22px;
  font-weight:900;

  z-index:9999;

  box-shadow:
  0 10px 35px rgba(180,140,80,.35),
  0 0 25px rgba(180,140,80,.18);

  transition:
  transform .35s ease,
  box-shadow .35s ease,
  opacity .35s ease;
}

/* BRILHO */
.back-to-top-bottas::before{
  content:"";

  position:absolute;
  inset:0;

  border-radius:inherit;

  background:
  radial-gradient(circle,
  rgba(255,255,255,.35),
  transparent 65%);

  opacity:.6;

  transition:.35s ease;
}

/* HOVER */
.back-to-top-bottas:hover{
  transform:
  translateY(-6px)
  scale(1.08);

  box-shadow:
  0 18px 45px rgba(180,140,80,.45),
  0 0 35px rgba(180,140,80,.28);
}

.back-to-top-bottas:hover::before{
  opacity:1;
  transform:scale(1.1);
}

/* CLICK */
.back-to-top-bottas:active{
  transform:scale(.96);
}

/* ÍCONE */
.back-to-top-bottas i,
.back-to-top-bottas span{
  position:relative;
  z-index:2;
}

/* MOBILE */
@media(max-width:768px){

  .back-to-top-bottas{
    width:56px;
    height:56px;

    right:20px;
    bottom:20px;

    font-size:20px;
  }

}







